System.register(["./clfC02-legacy-w7y4qGi7.js"],function(e,a){"use strict";var o;return{setters:[e=>{o=e.t}],execute:function(){e({e:function(e){const a=new Set(e);return u.filter(e=>e.objetivos.some(e=>a.has(e)))},f:function(e){const a=new Set(e);return l.filter(e=>e.objetivos.some(e=>a.has(e)))},g:function(e){return s[e]??[]},h:function(e){const a=new Set(e);return d.filter(e=>e.objetivos.some(e=>a.has(e)))},p:function(e){return i[e]??[]},r:function(e){return m[e]??{grupos:[],preguntas:[],tarjetas:[],pares:[]}},t:function(e){return r[e]??[]}});const a=[{id:"1.1-m1",taskId:"1.1",objetivos:["1.1#2"],tipo:"casoDeUso",formato:"multiple",question:"Una empresa quiere servir a clientes de tres continentes con baja latencia y tolerancia a la caída de una zona. ¿Qué dos características del alcance global de la nube lo permiten? (Elige DOS)",options:["Desplegar la aplicación en varias Regiones y usar servicios de borde cercanos al usuario.","Comprar servidores físicos en cada país y administrarlos desde una sola oficina central.","Reducir el número de zonas de disponibilidad para concentrar el tráfico en un único punto.","Distribuir los recursos en varias zonas de disponibilidad de la Región para tolerar la caída de una de ellas.","Trasladar todos los datos a una ubicación física temporal mientras se decide la arquitectura definitiva del proyecto internacional."],correctAnswer:0,correctAnswers:[0,3],explanation:"El alcance global combina Regiones para resiliencia y ubicaciones de borde para latencia. Si cambia el requisito a soberanía de datos, la elección de Región pasa a depender de cumplimiento.",porQueOpcion:["Correcta: varias Regiones más servicios de borde son el patrón del alcance global.","Incorrecta: adquirir y administrar hardware propio elimina la elasticidad de la nube.","Incorrecta: reducir zonas de disponibilidad aumenta el riesgo de caída, no la tolerancia.","Correcta: distribuir en varias zonas de disponibilidad tolera la caída de una de ellas.","Incorrecta: trasladar datos temporalmente no aporta baja latencia ni resiliencia."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.4-m1",taskId:"1.4",objetivos:["1.4#2"],tipo:"conocimiento",formato:"multiple",question:"¿Qué dos cambios en el modelo de gasto explican el ahorro económico al migrar a la nube? (Elige DOS)",options:["Se sustituye una gran inversión inicial por un pago por uso.","Se paga siempre la misma capacidad aunque no se utilice.","Se trasladan los costes fijos a costes variables y se evita sobredimensionar.","Se elimina la necesidad de medir y optimizar el consumo porque el precio ya es fijo.","Se duplica la capacidad reservada para anticipar el crecimiento de los próximos años."],correctAnswer:0,correctAnswers:[0,2],explanation:"El ahorro viene de convertir gasto de capital en gasto operativo y de ajustar la capacidad a la demanda. Si cambia el requisito a previsibilidad, entran los descuentos por compromiso.",porQueOpcion:["Correcta: pasar de inversión inicial a pago por uso es el núcleo de la economía de la nube.","Incorrecta: pagar por capacidad no utilizada es el modelo tradicional, no el ahorro de la nube.","Correcta: convertir costes fijos en variables y evitar sobredimensionar reduce el gasto.","Incorrecta: medir y optimizar sigue siendo necesario para controlar el gasto.","Incorrecta: duplicar capacidad reservada aumenta el coste, no lo reduce."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"2.1-m1",taskId:"2.1",objetivos:["2.1#1"],tipo:"conocimiento",formato:"multiple",question:"Bajo el modelo de responsabilidad compartida, ¿qué dos elementos son responsabilidad del cliente? (Elige DOS)",options:["La clasificación de los datos y la gestión de las identidades y los permisos.","La seguridad física de los centros de datos y de la infraestructura subyacente.","La aplicación de parches al sistema operativo invitado de sus instancias.","El mantenimiento del hipervisor y de la red troncal que conecta las zonas de disponibilidad.","La sustitución del hardware averiado en las instalaciones donde se aloja el servicio."],correctAnswer:0,correctAnswers:[0,2],explanation:"AWS protege la infraestructura física; el cliente protege datos, accesos y el sistema invitado. Si cambia el servicio a uno totalmente gestionado, la frontera se desplaza hacia AWS.",porQueOpcion:["Correcta: datos, identidades y permisos siempre corresponden al cliente.","Incorrecta: la seguridad física de las instalaciones es responsabilidad de AWS.","Correcta: el sistema operativo invitado y sus parches son del cliente.","Incorrecta: el hipervisor y la red troncal los administra AWS.","Incorrecta: el hardware lo mantiene AWS, no el cliente."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.2-m1",taskId:"2.2",objetivos:["2.2#1"],tipo:"seguridad",formato:"multiple",question:"¿Qué dos medidas refuerzan de forma directa el control de acceso a una cuenta? (Elige DOS)",options:["Exigir un segundo factor además de la contraseña para iniciar sesión.","Conceder permisos de administrador a todas las identidades para evitar bloqueos.","Aplicar el principio de menor privilegio con políticas específicas por función.","Compartir una única credencial entre el equipo para simplificar la administración.","Desactivar el registro de auditoría para reducir el ruido de eventos."],correctAnswer:0,correctAnswers:[0,2],explanation:"La autenticación multifactor y el menor privilegio controlan quién entra y qué puede hacer. Si cambia el contexto a clientes finales de una app, entra la federación de identidades.",porQueOpcion:["Correcta: el segundo factor protege el inicio de sesión aunque se filtre la contraseña.","Incorrecta: el permiso de administrador generalizado aumenta el riesgo.","Correcta: el menor privilegio limita el alcance de cada identidad.","Incorrecta: compartir credenciales elimina la trazabilidad individual.","Incorrecta: desactivar la auditoría oculta actividad y dificulta la investigación."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"3.1-m1",taskId:"3.1",objetivos:["3.1#2"],tipo:"conocimiento",formato:"multiple",question:"¿Qué dos formas de aprovisionar recursos son repetibles y se pueden versionar? (Elige DOS)",options:["Definir la infraestructura como código en plantillas revisables.","Crear cada recurso a mano desde la consola siguiendo una lista en papel.","Automatizar la creación mediante la interfaz de programación o la línea de comandos.","Pedir los recursos por correo al equipo de operaciones para que los cree cuando pueda.","Reutilizar una instantánea de una cuenta ajena sin registrar los pasos realizados."],correctAnswer:0,correctAnswers:[0,2],explanation:"La infraestructura como código y la automatización por API o CLI son repetibles y auditables. Si cambia el requisito a una prueba puntual, la consola puede ser aceptable.",porQueOpcion:["Correcta: las plantillas versionadas permiten repetir el despliegue.","Incorrecta: crear a mano desde la consola no es repetible ni versionable.","Correcta: la API o la CLI automatizan y registran la creación de recursos.","Incorrecta: el correo manual no es reproducible ni auditable.","Incorrecta: reutilizar recursos ajenos sin registro no es una práctica repetible."],fuentes:["https://docs.aws.amazon.com/AWSCloudFormation/latest/UserGuide/Welcome.html","https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.3-m1",taskId:"3.3",objetivos:["3.3#5"],tipo:"escenario",formato:"multiple",question:"Una tienda en línea recibe picos de tráfico por campañas y quiere ajustar la capacidad sola. ¿Qué dos beneficios aporta el escalado automático? (Elige DOS)",options:["Ajusta el número de recursos a la demanda real de cada momento.","Mantiene siempre el máximo de capacidad para que nunca falte, durante todo el año y sin límite.","Reduce el coste en los periodos de baja actividad al retirar recursos sobrantes.","Elimina la necesidad de supervisar el rendimiento porque la capacidad ya es automática.","Garantiza que la aplicación nunca tenga errores de código bajo carga elevada."],correctAnswer:0,correctAnswers:[0,2],explanation:"El escalado sigue la demanda y retira capacidad cuando no hace falta, mejorando coste y elasticidad. Si cambia el requisito a cargas impredecibles, el escalado reactivo encaja mejor.",porQueOpcion:["Correcta: ajusta la capacidad a la demanda observada.","Incorrecta: sobredimensionar de forma permanente desaprovecha recursos y encarece.","Correcta: retirar recursos sobrantes reduce el coste en valles de actividad.","Incorrecta: sigue siendo necesario supervisar el rendimiento y los umbrales.","Incorrecta: el escalado no corrige errores del código de la aplicación."],fuentes:["https://docs.aws.amazon.com/autoscaling/ec2/userguide/what-is-amazon-ec2-auto-scaling.html","https://docs.aws.amazon.com/ec2/"]},{id:"3.5-m1",taskId:"3.5",objetivos:["3.5#3"],tipo:"conocimiento",formato:"multiple",question:"¿Qué dos controles permiten aislar y filtrar el tráfico dentro de una red virtual? (Elige DOS)",options:["Grupos de seguridad que actúan como cortafuegos a nivel de recurso.","Listas de control de acceso de red que filtran por subred.","Un servicio de correo empresarial para notificar incidencias de red.","Un panel de facturación que muestra el coste del tráfico por servicio.","Un certificado de cifrado que sustituye a las reglas de red."],correctAnswer:0,correctAnswers:[0,2],explanation:"Los grupos de seguridad filtran por recurso y las listas de control por subred, y son complementarios. Si cambia el requisito a inspección centralizada, entra un cortafuegos gestionado.",porQueOpcion:["Correcta: los grupos de seguridad filtran el tráfico permitido por recurso.","Incorrecta: el correo no interviene en el filtrado de tráfico.","Correcta: las listas de control filtran a nivel de subred, sin estado.","Incorrecta: el panel de costes informa, no filtra tráfico.","Incorrecta: el cifrado protege datos; no reemplaza las reglas de red."],fuentes:["https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html"]},{id:"3.6-m1",taskId:"3.6",objetivos:["3.6#1"],tipo:"conocimiento",formato:"multiple",question:"¿Qué dos afirmaciones describen correctamente el almacenamiento de objetos? (Elige DOS)",options:["Se accede a los datos como objetos completos mediante una interfaz de servicio.","Se monta como un disco de bloques adjunto a una sola instancia.","Es adecuado para contenido estático y datos que se comparten por internet.","Requiere formatear el volumen con un sistema de archivos antes de usarlo.","Solo puede usarse desde dentro de una única zona de disponibilidad."],correctAnswer:0,correctAnswers:[0,2],explanation:"El almacenamiento de objetos se accede por API y sirve contenido compartido. Si cambia el requisito a un disco de arranque, la respuesta pasa al almacenamiento de bloques.",porQueOpcion:["Correcta: los objetos se leen y escriben completos mediante API o HTTP.","Incorrecta: montar un disco de bloques corresponde a otro modelo de almacenamiento.","Correcta: es el modelo habitual para contenido estático y distribución web.","Incorrecta: formatear volúmenes es propio del almacenamiento de bloques.","Incorrecta: el almacenamiento de objetos se replica y es accesible más allá de una zona."],fuentes:["https://docs.aws.amazon.com/AmazonS3/latest/userguide/Welcome.html","https://docs.aws.amazon.com/s3/"]},{id:"4.1-m1",taskId:"4.1",objetivos:["4.1#1"],tipo:"tradeoff",formato:"multiple",question:"¿Qué dos opciones reducen el coste de cómputo a cambio de un compromiso de uso? (Elige DOS)",options:["Reservar capacidad por un periodo a cambio de un descuento.","Pagar la tarifa por demanda sin ningún compromiso de tiempo.","Adoptar un plan de ahorro con un compromiso de gasto por hora.","Elegir la instancia más grande disponible para aprovechar su precio unitario.","Aumentar el tráfico saliente para repartir mejor el coste fijo."],correctAnswer:0,correctAnswers:[0,2],explanation:"La reserva y los planes de ahorro cambian compromiso por descuento. Si cambia el requisito a flexibilidad total, el pago por demanda vuelve a ser la opción.",porQueOpcion:["Correcta: reservar capacidad a plazo aplica descuento sobre el precio por demanda.","Incorrecta: el pago por demanda no exige compromiso y por eso no descuenta.","Correcta: los planes de ahorro comprometen gasto por hora y reducen el precio.","Incorrecta: una instancia mayor no implica descuento por compromiso.","Incorrecta: generar más tráfico saliente aumenta el coste, no lo reduce."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.2-m1",taskId:"4.2",objetivos:["4.2#5"],tipo:"metrica",formato:"multiple",question:"¿Qué dos herramientas permiten revisar el gasto histórico y avisar antes de superar un umbral? (Elige DOS)",options:["Un panel que visualiza el coste por servicio y periodo.","Un sistema de gestión de identidades que concede permisos a los usuarios.","Una alerta configurable que avisa al acercarse a un límite de gasto.","Un registro de auditoría que detalla quién modificó una política.","Un servicio de nombres de dominio para publicar la web de la empresa."],correctAnswer:0,correctAnswers:[0,2],explanation:"La exploración de costes analiza el gasto y las alertas presupuestarias avisan de umbrales. Si cambia el requisito a estimar antes de desplegar, entra una calculadora de precios.",porQueOpcion:["Correcta: el explorador de costes permite ver y desglosar el gasto.","Incorrecta: la gestión de identidades no analiza ni avisa del gasto.","Correcta: los presupuestos con alertas avisan al acercarse a un umbral.","Incorrecta: el registro de auditoría traza cambios, no costes.","Incorrecta: el servicio de nombres no tiene relación con el gasto."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]}],n=[{id:"g2-1",taskId:"4.2",objetivos:["4.2#8"],tipo:"metrica",question:"Un área de finanzas necesita un informe detallado y desglosado del uso y los costos por recurso y por etiqueta, que pueda exportarse para analizarlo con herramientas propias de inteligencia de negocio. ¿Qué recurso cubre ese requisito?",options:["AWS Cost and Usage Reports, que publica informes detallados del uso y los costos por recurso y etiqueta exportables a herramientas propias.","AWS Cost Explorer, que muestra tendencias y patrones de gasto mediante gráficos y filtros dentro de su propia interfaz interactiva y no entrega el archivo desglosado por recurso.","AWS Budgets, que define presupuestos y envía alertas cuando el gasto real o previsto supera un umbral configurado por el equipo.","AWS Pricing Calculator, que estima el costo mensual de una arquitectura propuesta antes de crearla, sin medir el uso real ya consumido."],correctAnswer:0,explanation:"AWS Cost and Usage Reports entrega el detalle por recurso y etiqueta que finanzas necesita para conciliar y analizar con sus propias herramientas, mientras que las alternativas se orientan a visualizar tendencias, vigilar umbrales o estimar costos futuros. Si cambia el requisito a una estimación previa al despliegue, la opción adecuada sería AWS Pricing Calculator.",porQueOpcion:["Correcta: entrega el informe detallado por recurso y etiqueta que se puede exportar para analizarlo con herramientas propias.","Incorrecta: muestra tendencias de gasto en su propia interfaz, pero no genera el archivo desglosado por recurso que pide finanzas.","Incorrecta: define presupuestos y alertas de umbral, no un informe exportable de uso y costos detallado.","Incorrecta: estima costos futuros antes de desplegar, sin medir ni detallar el uso real consumido."],fuentes:["https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/ce-what-is.html","https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/budgets-managing-costs.html","https://docs.aws.amazon.com/cur/latest/userguide/what-is-cur.html"]},{id:"g2-2",taskId:"3.3",objetivos:["3.3#4"],tipo:"casoDeUso",question:"Un equipo necesita ejecutar contenedores a demanda sin aprovisionar ni administrar instancias ni clústeres de servidores, pagando solo por los recursos que cada tarea consume mientras se ejecuta. ¿Qué servicio encaja mejor?",options:["AWS Fargate, que ejecuta contenedores sin que el equipo administre las instancias ni el clúster subyacente.","AWS Batch, que planifica y programa trabajos de cómputo por lotes en colas según la capacidad disponible.","Amazon EC2, que ofrece instancias virtuales que el equipo debe aprovisionar, parchear y escalar por su cuenta.","Amazon Lightsail, que entrega instancias y bloques de almacenamiento con una configuración simplificada y precio mensual fijo."],correctAnswer:0,explanation:"El requisito es ejecutar contenedores sin administrar la capa de servidores, y la opción que lo resuelve directamente es AWS Fargate; las demás exigen aprovisionar instancias o gestionar trabajos por lotes. Si cambia el requisito a trabajos por lotes programados que deban encolarse y reintentarse, la opción sería AWS Batch.",porQueOpcion:["Correcta: ejecuta contenedores sin que el equipo administre las instancias ni el clúster subyacente, con pago por uso.","Incorrecta: planifica trabajos por lotes en colas, pero no cubre la ejecución de contenedores a demanda sin administrar infraestructura.","Incorrecta: entrega instancias virtuales que el equipo debe aprovisionar, parchear y escalar, justo lo que se quiere evitar.","Incorrecta: ofrece instancias con configuración simplificada y precio fijo, no contenedores sin servidores gestionados."],fuentes:["https://docs.aws.amazon.com/AmazonECS/latest/developerguide/AWS_Fargate.html","https://docs.aws.amazon.com/batch/","https://docs.aws.amazon.com/ec2/","https://docs.aws.amazon.com/lightsail/"]},{id:"g2-3",taskId:"3.1",objetivos:["3.1#6"],tipo:"escenario",question:"Una empresa debe ejecutar algunas cargas con latencia ultrabaja y residencia de datos dentro de sus propias instalaciones, pero quiere usar las mismas interfaces, herramientas y servicios de nube que ya conoce para operarlas. ¿Qué opción permite ese modelo híbrido?",options:["AWS Outposts, que extiende la infraestructura y los servicios de nube a las instalaciones del cliente para ejecutar cargas con baja latencia y residencia local.","AWS Storage Gateway, que integra el almacenamiento local con la nube mediante caché y copias de seguridad, pero no ejecuta cómputo dentro de las instalaciones del cliente.","AWS Direct Connect, que establece una conexión de red dedicada entre las instalaciones y la nube, sin alojar cómputo local.","AWS Site-to-Site VPN, que cifra el tráfico entre la red local y la nube, pero no ejecuta servicios en el edificio."],correctAnswer:0,explanation:"AWS Outposts lleva la infraestructura y los servicios de nube al edificio del cliente, que es lo que permite cargas locales con las mismas interfaces y herramientas. Las demás opciones solo conectan o integran almacenamiento y red, sin ejecutar cómputo en las instalaciones. Si cambia el requisito a trasladar toda la carga a la nube, la extensión local dejaría de ser necesaria.",porQueOpcion:["Correcta: extiende la infraestructura y los servicios de nube a las instalaciones del cliente para cargas con residencia y baja latencia locales.","Incorrecta: integra almacenamiento local con la nube, pero no ejecuta cómputo dentro de las instalaciones.","Incorrecta: ofrece una conexión de red dedicada entre las instalaciones y la nube, sin alojar cómputo local.","Incorrecta: cifra el tráfico entre la red local y la nube, pero no ejecuta servicios en el edificio."],fuentes:["https://docs.aws.amazon.com/outposts/","https://docs.aws.amazon.com/storagegateway/","https://docs.aws.amazon.com/directconnect/latest/UserGuide/Welcome.html","https://docs.aws.amazon.com/vpn/latest/s2svpn/VPC_VPN.html"]},{id:"g2-4",taskId:"3.3",objetivos:["3.3#3"],tipo:"servicio",question:"Un equipo construye imágenes de contenedor y necesita almacenarlas de forma privada, versionarlas y que sus clústeres de contenedores las descarguen de manera segura e integrada. ¿Qué servicio cubre ese requisito?",options:["Amazon Elastic Container Registry (Amazon ECR), que almacena y versiona imágenes de contenedor de forma privada e integrada con los servicios de contenedores.","Amazon Elastic Container Service (Amazon ECS), que orquesta la ejecución de los contenedores y programa las tareas, pero no es un repositorio donde almacenar y versionar las imágenes.","Amazon Elastic Kubernetes Service (Amazon EKS), que administra clústeres de Kubernetes, pero no actúa como registro de imágenes.","AWS CodeBuild, que compila y prueba el código, pero no funciona como registro privado de imágenes de contenedor."],correctAnswer:0,explanation:"Amazon Elastic Container Registry (Amazon ECR) es el repositorio gestionado donde se almacenan y versionan las imágenes de contenedor y desde el que los servicios de contenedores las descargan. Los orquestadores ejecutan contenedores y el servicio de compilación construye el código, pero ninguno actúa como registro de imágenes. Si cambia el requisito a compartir el registro entre varias cuentas con control de acceso, habría que evaluar otro repositorio.",porQueOpcion:["Correcta: almacena y versiona imágenes de contenedor de forma privada e integrada con los servicios de contenedores.","Incorrecta: orquesta y programa la ejecución de contenedores, pero no es un repositorio donde almacenar y versionar imágenes.","Incorrecta: administra clústeres de Kubernetes, pero no funciona como registro de imágenes de contenedor.","Incorrecta: compila y prueba el código, pero no actúa como registro privado de imágenes de contenedor."],fuentes:["https://docs.aws.amazon.com/ecr/","https://docs.aws.amazon.com/ecs/","https://docs.aws.amazon.com/eks/","https://docs.aws.amazon.com/codebuild/"]},{id:"g2-5",taskId:"4.1",objetivos:["4.1#1"],tipo:"metrica",question:"Un equipo quiere recomendaciones basadas en el uso histórico para elegir el tamaño y el tipo de sus recursos de cómputo y evitar pagar por capacidad sobredimensionada. ¿Qué servicio ofrece ese análisis?",options:["AWS Compute Optimizer, que analiza la utilización histórica y recomienda el tamaño y el tipo adecuados de los recursos de cómputo.","AWS Trusted Advisor, que revisa buenas prácticas de seguridad, costos y tolerancia a fallos, pero no calcula el tamaño óptimo a partir del uso histórico.","AWS Cost Explorer, que visualiza y analiza el gasto, pero no recomienda el tamaño de cada recurso de cómputo.","AWS Budgets, que vigila el gasto frente a un umbral, pero no analiza la utilización para redimensionar recursos."],correctAnswer:0,explanation:"AWS Compute Optimizer se basa en métricas de utilización histórica para recomendar el dimensionamiento y el tipo de los recursos de cómputo, que es justo el requisito de reducir el sobredimensionamiento. Las demás herramientas revisan prácticas, visualizan gasto o vigilan umbrales, sin calcular el tamaño óptimo. Si cambia el requisito a reservar capacidad por adelantado en lugar de redimensionarla, la decisión pasaría a los planes de compra.",porQueOpcion:["Correcta: analiza la utilización histórica y recomienda el tamaño y el tipo adecuados de los recursos de cómputo.","Incorrecta: revisa buenas prácticas, pero no calcula el tamaño óptimo a partir del uso histórico.","Incorrecta: visualiza y analiza el gasto, pero no recomienda el tamaño de cada recurso de cómputo.","Incorrecta: vigila el gasto frente a un umbral, pero no analiza la utilización para redimensionar recursos."],fuentes:["https://docs.aws.amazon.com/compute-optimizer/","https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/ce-what-is.html","https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/budgets-managing-costs.html"]},{id:"g2-6",taskId:"2.4",objetivos:["2.4#1"],tipo:"servicio",question:"Una organización quiere crear y gobernar un entorno de varias cuentas con reglas de seguridad y configuraciones de referencia aplicadas de forma centralizada desde el primer momento. ¿Qué servicio facilita esa gobernanza?",options:["AWS Control Tower, que configura y gobierna un entorno de varias cuentas con reglas y controles de referencia.","AWS Organizations, que agrupa y administra cuentas y su facturación consolidada, pero no despliega por sí solo un entorno con controles de referencia.","AWS Service Catalog, que ofrece catálogos de productos aprobados a los usuarios, pero no crea ni gobierna la estructura de cuentas.","AWS Config, que evalúa la conformidad de los recursos, pero no aprovisiona una estructura multi-cuenta con controles."],correctAnswer:0,explanation:"AWS Control Tower configura el entorno multi-cuenta y aplica controles de referencia centralizados, que es el requisito completo. Las demás agrupan cuentas, publican productos o evalúan conformidad, pero no despliegan por sí solas ese entorno gobernado. Si cambia el requisito a evaluar solo el cumplimiento de recursos ya existentes, bastaría con un servicio de evaluación de configuración.",porQueOpcion:["Correcta: configura y gobierna un entorno de varias cuentas con reglas y controles de referencia de forma centralizada.","Incorrecta: agrupa y administra cuentas y facturación, pero no despliega por sí solo un entorno con controles de referencia.","Incorrecta: ofrece catálogos de productos aprobados, pero no crea ni gobierna la estructura de cuentas.","Incorrecta: evalúa la conformidad de los recursos, pero no aprovisiona una estructura multi-cuenta con controles."],fuentes:["https://docs.aws.amazon.com/controltower/","https://docs.aws.amazon.com/organizations/","https://docs.aws.amazon.com/servicecatalog/","https://docs.aws.amazon.com/config/"]},{id:"g2-7",taskId:"3.1",objetivos:["3.1#4"],tipo:"casoDeUso",question:"Un equipo necesita definir sus recursos una sola vez y volver a desplegarlos de forma idéntica en cada entorno, con la definición guardada y revisable. ¿Qué forma de trabajo encaja mejor?",options:["La infraestructura como código, porque define los recursos en archivos versionados y los reproduce de forma consistente.","AWS Management Console, porque con sus asistentes visuales se repite el mismo resultado sin dejar una definición versionada.","AWS CLI, porque los comandos escritos una vez en la terminal bastan para reproducir el entorno sin guardar nada.","AWS SDK, porque una llamada puntual desde una aplicación recrea el entorno sin necesidad de versionar la definición."],correctAnswer:0,explanation:"La infraestructura como código es la única opción que deja una definición versionada y revisable capaz de reproducir el entorno de forma consistente. La consola, los comandos sueltos de terminal y las llamadas puntuales no conservan esa definición. Si cambia el requisito a una tarea puntual y exploratoria, la consola pasaría a ser la opción adecuada.",porQueOpcion:["Correcta: define los recursos en archivos versionados y los reproduce de forma consistente en cada entorno.","Incorrecta: sus asistentes visuales no dejan una definición versionada y revisable del entorno.","Incorrecta: los comandos sueltos de terminal sin guardar no reproducen el entorno de forma consistente.","Incorrecta: una llamada puntual desde una aplicación no versiona la definición ni garantiza el mismo resultado."],fuentes:["https://docs.aws.amazon.com/awsconsolehelpdocs/latest/gsg/what-is.html","https://docs.aws.amazon.com/cli/"]},{id:"g2-8",taskId:"3.1",objetivos:["3.1#1"],tipo:"servicio",question:"Un equipo de plataforma quiere publicar un catálogo de productos ya aprobados y preconfigurados para que otras áreas los desplieguen por sí mismas sin salirse de las reglas de la organización. ¿Qué servicio cubre ese requisito?",options:["AWS Service Catalog, que permite publicar y gobernar un catálogo de productos aprobados que las áreas pueden desplegar.","AWS Control Tower, que gobierna la estructura de cuentas y sus controles, pero no publica un catálogo de productos desplegables.","AWS Marketplace, que ofrece software de terceros listo para comprar y suscribir, pero no un catálogo interno de productos aprobados.","AWS Config, que registra y evalúa la conformidad de los recursos, pero no ofrece un catálogo de despliegue por autoservicio."],correctAnswer:0,explanation:"AWS Service Catalog publica un catálogo curado de productos aprobados para que las áreas los desplieguen dentro de las reglas definidas. Las demás gobiernan cuentas, ofrecen software de terceros o evalúan conformidad, sin entregar ese catálogo de autoservicio. Si cambia el requisito a compartir un recurso ya existente entre cuentas, la respuesta sería otro servicio.",porQueOpcion:["Correcta: publica y gobierna un catálogo de productos aprobados que las áreas despliegan por sí mismas.","Incorrecta: gobierna la estructura de cuentas y sus controles, pero no publica un catálogo de productos desplegables.","Incorrecta: ofrece software de terceros para comprar y suscribir, no un catálogo interno de productos aprobados.","Incorrecta: registra y evalúa la conformidad de los recursos, pero no ofrece un catálogo de despliegue por autoservicio."],fuentes:["https://docs.aws.amazon.com/servicecatalog/","https://docs.aws.amazon.com/controltower/","https://docs.aws.amazon.com/marketplace/","https://docs.aws.amazon.com/config/"]},{id:"g2-9",taskId:"3.1",objetivos:["3.1#1"],tipo:"servicio",question:"Un equipo necesita consultar los límites máximos de un servicio en su cuenta y solicitar un aumento cuando la demanda lo exige, todo desde un único lugar por región. ¿Qué herramienta cubre ese requisito?",options:["Service Quotas, que muestra los límites aplicables por cuenta y región y permite solicitar aumentos desde un único lugar.","AWS Trusted Advisor, que revisa buenas prácticas de seguridad, costos y tolerancia a fallos, pero no concentra los límites ni tramita sus aumentos.","AWS Config, que evalúa la conformidad de la configuración, pero no administra los límites de la cuenta.","AWS Health Dashboard, que informa sobre eventos y mantenimientos, pero no gestiona los límites de servicio."],correctAnswer:0,explanation:"Service Quotas centraliza los límites aplicables por cuenta y región y permite solicitar aumentos en el mismo lugar. Las demás herramientas revisan prácticas, evalúan conformidad o informan eventos, sin administrar los límites. Si cambia el requisito a controlar el gasto frente a un umbral, la respuesta sería un servicio de presupuestos.",porQueOpcion:["Correcta: muestra los límites por cuenta y región y permite solicitar aumentos desde un único lugar.","Incorrecta: revisa buenas prácticas, pero no concentra los límites ni tramita sus aumentos.","Incorrecta: evalúa la conformidad de la configuración, pero no administra los límites de la cuenta.","Incorrecta: informa sobre eventos y mantenimientos, pero no gestiona los límites de servicio."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/config/","https://docs.aws.amazon.com/health/","https://docs.aws.amazon.com/servicequotas/"]},{id:"g2-10",taskId:"3.5",objetivos:["3.5#5"],tipo:"servicio",question:"Una empresa quiere conectar de forma cifrada su red local con su red virtual en la nube a través de internet, con una configuración rápida y sin contratar un enlace dedicado. ¿Qué opción encaja mejor?",options:["AWS Site-to-Site VPN, que crea túneles cifrados entre la red local y la red virtual a través de internet.","AWS Direct Connect, que establece una conexión dedicada y privada entre las instalaciones y la nube, sin depender de internet.","AWS Transit Gateway, que centraliza la conectividad entre redes, pero no sustituye al túnel cifrado por internet.","AWS Client VPN, que conecta a usuarios individuales con la red, pero no enlaza de forma permanente la red local completa."],correctAnswer:0,explanation:"AWS Site-to-Site VPN levanta túneles cifrados sobre internet entre la red local y la red virtual, que es lo que pide el escenario con configuración rápida y sin enlace dedicado. Las demás opciones ofrecen conexión dedicada, centralizan redes o conectan usuarios sueltos. Si cambia el requisito a un enlace privado y dedicado sin depender de internet, la respuesta sería AWS Direct Connect.",porQueOpcion:["Correcta: crea túneles cifrados entre la red local y la red virtual a través de internet.","Incorrecta: ofrece una conexión dedicada y privada, que es justo el enlace que el escenario quiere evitar.","Incorrecta: centraliza la conectividad entre redes, pero no es el túnel cifrado por internet que se pide.","Incorrecta: conecta usuarios individuales, pero no enlaza de forma permanente la red local completa."],fuentes:["https://docs.aws.amazon.com/directconnect/latest/UserGuide/Welcome.html","https://docs.aws.amazon.com/vpc/latest/tgw/what-is-transit-gateway.html","https://docs.aws.amazon.com/vpn/latest/clientvpn-admin/what-is.html","https://docs.aws.amazon.com/vpn/latest/s2svpn/VPC_VPN.html"]},{id:"g2-11",taskId:"2.2",objetivos:["2.2#7"],tipo:"seguridad",question:"Un equipo necesita obtener, renovar y desplegar certificados de servidor para cifrar las comunicaciones de sus aplicaciones web sin gestionar el ciclo de vida a mano. ¿Qué servicio cubre ese requisito?",options:["AWS Certificate Manager (ACM), que aprovisiona, renueva y despliega certificados para cifrar el tráfico en tránsito.","AWS CloudHSM, que protege claves en un módulo de hardware dedicado, pero no emite ni renueva certificados públicos para aplicaciones web.","AWS Key Management Service (AWS KMS), que administra claves de cifrado para los datos, pero no emite certificados de servidor.","AWS Secrets Manager, que guarda y rota secretos de acceso, pero no emite ni renueva certificados de servidor."],correctAnswer:0,explanation:"AWS Certificate Manager (ACM) aprovisiona, renueva y despliega certificados de servidor para cifrar las comunicaciones, que es el requisito completo. Los servicios de claves y secretos protegen material criptográfico, pero no emiten certificados de servidor. Si cambia el requisito a proteger claves en hardware dedicado con control total del dispositivo, la respuesta sería AWS CloudHSM.",porQueOpcion:["Correcta: aprovisiona, renueva y despliega certificados para cifrar el tráfico en tránsito.","Incorrecta: protege claves en hardware dedicado, pero no emite ni renueva certificados públicos para aplicaciones web.","Incorrecta: administra claves de cifrado de datos, pero no emite certificados de servidor.","Incorrecta: guarda y rota secretos de acceso, pero no emite ni renueva certificados de servidor."],fuentes:["https://docs.aws.amazon.com/acm/","https://docs.aws.amazon.com/cloudhsm/","https://docs.aws.amazon.com/kms/","https://docs.aws.amazon.com/secretsmanager/"]},{id:"g2-12",taskId:"2.2",objetivos:["2.2#2"],tipo:"seguridad",question:"Un equipo necesita crear y controlar claves de cifrado que usan sus servicios, con rotación y registro de auditoría, sin adquirir ni administrar hardware dedicado. ¿Qué servicio encaja mejor?",options:["AWS Key Management Service (AWS KMS), que administra claves de cifrado integradas con los servicios y no requiere operar hardware dedicado.","AWS CloudHSM, que ofrece módulos de hardware dedicados para proteger claves, pero obliga a administrar el dispositivo, su alta disponibilidad y sus usuarios.","AWS Certificate Manager (ACM), que emite y renueva certificados de servidor, pero no administra claves de cifrado de datos.","AWS Secrets Manager, que almacena y rota secretos de aplicaciones, pero no es el servicio de claves de cifrado de los datos."],correctAnswer:0,explanation:"AWS Key Management Service (AWS KMS) crea y controla claves de cifrado integradas con los servicios, con rotación y auditoría, y sin operar hardware dedicado. Las demás opciones no administran las claves de cifrado de los datos o exigen gestionar el dispositivo. Si cambia el requisito a controlar claves en hardware dedicado y aislado, la respuesta sería AWS CloudHSM.",porQueOpcion:["Correcta: administra claves de cifrado integradas con los servicios y no requiere operar hardware dedicado.","Incorrecta: protege claves en hardware dedicado, pero obliga a administrar el dispositivo y sus usuarios.","Incorrecta: emite y renueva certificados de servidor, pero no administra claves de cifrado de datos.","Incorrecta: almacena y rota secretos de aplicaciones, pero no es el servicio de claves de cifrado de los datos."],fuentes:["https://docs.aws.amazon.com/kms/","https://docs.aws.amazon.com/cloudhsm/","https://docs.aws.amazon.com/acm/","https://docs.aws.amazon.com/secretsmanager/"]},{id:"g2-13",taskId:"2.3",objetivos:["2.3#10"],tipo:"servicio",question:"Una empresa quiere que sus empleados inicien sesión una sola vez con sus credenciales corporativas y accedan a varias cuentas y aplicaciones con permisos definidos por rol. ¿Qué servicio cubre mejor ese requisito?",options:["AWS IAM Identity Center, que ofrece acceso único con identidades corporativas y permisos por rol sobre varias cuentas y aplicaciones.","AWS Directory Service, que aloja un directorio administrado en la nube, pero no concede por sí solo el acceso único a varias cuentas.","AWS Identity and Access Management (IAM), que administra usuarios y permisos dentro de una cuenta, pero no el acceso único federado a muchas cuentas.","Amazon Cognito, que autentica usuarios de aplicaciones propias, pero no gobierna el acceso de la plantilla a las cuentas de la organización."],correctAnswer:0,explanation:"AWS IAM Identity Center combina las identidades corporativas con permisos por rol y acceso único a varias cuentas y aplicaciones. El directorio administrado, la gestión de identidades de una sola cuenta y la autenticación de aplicaciones propias no cubren ese acceso único federado. Si cambia el requisito a administrar un directorio propio en la nube, la respuesta sería AWS Directory Service.",porQueOpcion:["Correcta: ofrece acceso único con identidades corporativas y permisos por rol sobre varias cuentas y aplicaciones.","Incorrecta: aloja un directorio administrado, pero no concede por sí solo el acceso único a varias cuentas.","Incorrecta: administra usuarios y permisos de una cuenta, pero no el acceso único federado a muchas cuentas.","Incorrecta: autentica usuarios de aplicaciones propias, pero no gobierna el acceso de la plantilla a las cuentas."],fuentes:["https://docs.aws.amazon.com/singlesignon/","https://docs.aws.amazon.com/directoryservice/latest/admin-guide/what_is.html","https://docs.aws.amazon.com/cognito/","https://docs.aws.amazon.com/iam/"]},{id:"g2-14",taskId:"2.3",objetivos:["2.3#1"],tipo:"servicio",question:"Una organización quiere compartir un recurso concreto entre varias cuentas de su organización sin crear copias ni configurar permisos uno a uno. ¿Qué servicio está pensado para ese intercambio?",options:["AWS Resource Access Manager (AWS RAM), que permite compartir recursos entre cuentas de la organización sin duplicarlos.","AWS IAM Identity Center, que gestiona el acceso único de personas, pero no comparte recursos entre cuentas.","AWS Organizations, que agrupa cuentas y consolida la facturación, pero no es el mecanismo para compartir un recurso concreto.","AWS Service Catalog, que publica productos aprobados para desplegarlos, pero no comparte un recurso ya existente entre cuentas."],correctAnswer:0,explanation:"AWS Resource Access Manager (AWS RAM) comparte recursos entre cuentas de la organización sin duplicarlos, que es el requisito exacto. Las demás gestionan el acceso de personas, agrupan cuentas o publican productos, sin compartir un recurso ya existente. Si cambia el requisito a publicar productos aprobados para su despliegue, la respuesta sería AWS Service Catalog.",porQueOpcion:["Correcta: comparte recursos entre cuentas de la organización sin duplicarlos ni configurar permisos uno a uno.","Incorrecta: gestiona el acceso único de personas, pero no comparte recursos entre cuentas.","Incorrecta: agrupa cuentas y consolida la facturación, pero no comparte un recurso concreto entre ellas.","Incorrecta: publica productos aprobados para desplegarlos, pero no comparte un recurso ya existente entre cuentas."],fuentes:["https://docs.aws.amazon.com/ram/latest/userguide/what-is.html","https://docs.aws.amazon.com/singlesignon/","https://docs.aws.amazon.com/organizations/","https://docs.aws.amazon.com/servicecatalog/"]},{id:"g2-15",taskId:"3.6",objetivos:["3.6#2"],tipo:"casoDeUso",question:"Un equipo necesita almacenar y servir archivos estáticos de un sitio web que se acceden por HTTP, con durabilidad y sin administrar ningún sistema de archivos. ¿Qué servicio encaja mejor?",options:["Amazon S3, que almacena objetos y los sirve por HTTP con alta durabilidad, sin administrar sistemas de archivos.","Amazon Elastic File System (Amazon EFS), que ofrece un sistema de archivos compartido que se monta en instancias, no un almacén de objetos por HTTP.","Amazon Elastic Block Store (Amazon EBS), que ofrece volúmenes de bloque para una instancia, no almacenamiento de objetos por HTTP.","AWS Storage Gateway, que conecta el almacenamiento local con la nube, pero no sirve objetos estáticos por HTTP."],correctAnswer:0,explanation:"El almacenamiento de objetos por HTTP sin administrar sistemas de archivos corresponde a Amazon S3. El sistema de archivos compartido, los volúmenes de bloque y la pasarela de almacenamiento no sirven objetos estáticos por HTTP ni evitan administrar un sistema de archivos. Si cambia el requisito a un sistema de archivos compartido montable en varias instancias, la respuesta sería Amazon Elastic File System (Amazon EFS).",porQueOpcion:["Correcta: almacena objetos y los sirve por HTTP con alta durabilidad, sin administrar sistemas de archivos.","Incorrecta: ofrece un sistema de archivos que se monta en instancias, no un almacén de objetos servido por HTTP.","Incorrecta: ofrece volúmenes de bloque para una instancia, no almacenamiento de objetos por HTTP.","Incorrecta: conecta el almacenamiento local con la nube, pero no sirve objetos estáticos por HTTP."],fuentes:["https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/efs/","https://docs.aws.amazon.com/ebs/","https://docs.aws.amazon.com/storagegateway/"]},{id:"g2-16",taskId:"3.2",objetivos:["3.2#8"],tipo:"escenario",question:"Una empresa necesita recuperar sus servidores en otra región con un objetivo de tiempo de recuperación bajo tras una caída, replicando de forma continua sin mantener en marcha la misma capacidad. ¿Qué servicio cubre ese requisito?",options:["AWS Elastic Disaster Recovery, que replica de forma continua los servidores y permite recuperarlos en otra región con poco tiempo de inactividad.","AWS Backup, que centraliza y automatiza copias de seguridad programadas de varios recursos, pero no ofrece replicación continua ni una recuperación con bajo tiempo de inactividad.","AWS Storage Gateway, que integra almacenamiento local con la nube, pero no replica servidores para recuperarlos en otra región.","Amazon Elastic File System (Amazon EFS), que ofrece un sistema de archivos compartido y elástico, pero no recupera servidores ante un desastre."],correctAnswer:0,explanation:"AWS Elastic Disaster Recovery replica de forma continua los servidores y permite recuperarlos en otra región con poco tiempo de inactividad, tal como exige el escenario. Las copias programadas, la integración de almacenamiento y el sistema de archivos compartido no replican servidores para un desastre regional. Si cambia el requisito a copias de seguridad programadas sin recuperación casi inmediata, bastaría con AWS Backup.",porQueOpcion:["Correcta: replica de forma continua los servidores y permite recuperarlos en otra región con poco tiempo de inactividad.","Incorrecta: automatiza copias programadas, pero no ofrece replicación continua ni recuperación con bajo tiempo de inactividad.","Incorrecta: integra almacenamiento local con la nube, pero no replica servidores para recuperarlos en otra región.","Incorrecta: ofrece un sistema de archivos compartido y elástico, pero no recupera servidores ante un desastre."],fuentes:["https://docs.aws.amazon.com/drs/","https://docs.aws.amazon.com/aws-backup/","https://docs.aws.amazon.com/storagegateway/","https://docs.aws.amazon.com/efs/"]}],s={1.1:[{id:"1.1-g1",titulo:"Propuesta de valor de la nube de AWS",objetivos:["1.1#1"],bloques:[{tipo:"concepto",md:"La **propuesta de valor** de la nube de AWS consiste en cambiar la forma de adquirir y operar la tecnología:\n\n- **Pago por uso**: se paga solo por lo que se consume, sin comprar hardware por adelantado.\n- **Eliminación de capacidad ociosa**: la capacidad se ajusta a la demanda en lugar de dimensionarse para el pico.\n- **Economías de escala**: al agregar el consumo de millones de clientes, AWS puede ofrecer precios más bajos.\n- **Velocidad y agilidad**: los recursos se aprovisionan en minutos y se experimenta sin grandes inversiones.\n- **Alcance global**: se despliega en regiones de todo el mundo sin construir centros de datos propios.\n- **Seguridad y fiabilidad**: infraestructura y servicios gestionados que asumen parte de la carga operativa.\n\nEn conjunto, la propuesta de valor es **convertir el gasto fijo en gasto variable** y ganar velocidad: se pasa de comprar y mantener servidores a consumir servicios cuando se necesitan."},{tipo:"ejemplo",md:"```text\nModelo tradicional:\n  comprar servidores para el pico -> capacidad ociosa el resto del año\n\nModelo AWS Cloud:\n  aprovisionar lo necesario -> crecer y decrecer según la demanda\n  pagar por uso -> el coste sigue al consumo real\n```"},{tipo:"cuandoUsar",usar:["Usa la nube de AWS cuando necesites convertir inversión fija en coste variable y escalar sin comprar hardware.","Apóyate en servicios gestionados cuando quieras reducir la carga operativa y centrarte en el producto."],noUsar:["No justifiques la nube solo por precio: la propuesta de valor también incluye velocidad, alcance global y elasticidad.","No asumas que toda carga de trabajo encaja igual: cada una necesita evaluar su modelo de coste y de operación."]},{tipo:"errorComun",error:"Creer que la propuesta de valor de la nube es únicamente ahorrar dinero en la factura.",correccion:"El ahorro es un efecto del pago por uso y de las economías de escala, pero la propuesta de valor incluye también agilidad, alcance global y capacidad de innovar más rápido. La nube cambia el modelo de coste y de operación, no solo el precio."}],preguntasGuia:["¿Qué significa convertir gasto fijo en gasto variable?","¿Por qué el pago por uso y las economías de escala reducen el coste?","¿Qué beneficios además del precio forman parte de la propuesta de valor?"]},{id:"1.1-g2",titulo:"Infraestructura global: velocidad de despliegue y alcance global",objetivos:["1.1#2"],bloques:[{tipo:"concepto",md:"La **infraestructura global** de AWS está formada por regiones, Availability Zones y edge locations repartidas por el mundo. De ella salen dos beneficios centrales:\n\n- **Velocidad de despliegue**: en minutos se crean recursos en cualquier región, sin esperar a comprar y montar centros de datos. Eso acorta el tiempo entre la idea y la producción.\n- **Alcance global**: el mismo servicio está disponible en muchas zonas geográficas, de modo que una aplicación puede servir a usuarios de otros continentes sin abrir infraestructura propia.\n\nLa infraestructura global actúa como plataforma común: se elige la región cercana a los usuarios para reducir la latencia y se distribuye el contenido con las edge locations para acercar la entrega. Todo ello sin gestionar el cableado ni los edificios."},{tipo:"comparacion",parId:"velocidad-despliegue-vs-alcance-global"},{tipo:"escenario",situacion:"Una startup debe publicar su aplicación en un plazo de dos semanas para clientes de varios países. No tiene presupuesto para montar infraestructura fuera de su país y necesita que las descargas sean rápidas desde cualquier continente.",analisis:"La infraestructura global permite desplegar en minutos en la región adecuada y distribuir el contenido estático con **edge locations**, de modo que la entrega se acerca al usuario sin abrir centros de datos propios. La velocidad de despliegue atiende el plazo y el alcance global atiende a la audiencia internacional.",servicio:"Amazon CloudFront"},{tipo:"cuandoUsar",usar:["Usa la infraestructura global cuando el plazo de puesta en producción sea corto: los recursos están disponibles en minutos.","Apóyate en las ubicaciones de borde cuando el contenido deba entregarse con baja latencia a usuarios de varios continentes."],noUsar:["No confundas el alcance global con replicar todos los datos en cada región: la residencia y la replicación son decisiones de diseño aparte.","No esperes que la infraestructura global garantice por sí sola la continuidad: para tolerar fallos hay que diseñar la redundancia."]},{tipo:"clave",items:["Velocidad de despliegue: recursos disponibles en minutos, en cualquier región, sin comprar hardware.","Alcance global: la misma plataforma sirve a usuarios de todo el mundo.","La infraestructura global reduce la distancia entre la aplicación y el usuario.","No hace falta construir ni mantener centros de datos propios para operar a escala mundial."]}],preguntasGuia:["¿Qué ventaja aporta desplegar en minutos en lugar de comprar hardware?","¿Cómo ayuda la infraestructura global a llegar a usuarios de otros continentes?","¿Por qué el alcance global es un beneficio y no solo una cuestión de tamaño?"]},{id:"1.1-g3",titulo:"Alta disponibilidad, elasticidad y agilidad",objetivos:["1.1#3"],bloques:[{tipo:"concepto",md:"Tres ventajas se confunden con facilidad y conviene separarlas:\n\n- **Alta disponibilidad**: seguir atendiendo el servicio aunque falle un componente, repartiendo la carga entre varios recursos (por ejemplo, varias Availability Zones).\n- **Elasticidad**: ajustar la capacidad de forma automática a la demanda; se crece cuando hace falta y se reduce cuando baja, sin intervención manual.\n- **Agilidad**: capacidad de crear, cambiar y experimentar rápido. Al no depender de compras de hardware, un equipo puede probar una idea y descartarla en poco tiempo.\n\nLas tres son ventajas distintas: la alta disponibilidad protege frente a fallos, la elasticidad adapta la capacidad al uso y la agilidad acelera el ritmo de innovación. En la práctica se refuerzan entre sí."},{tipo:"comparacion",parId:"alta-disponibilidad-vs-elasticidad-vs-agilidad"},{tipo:"ejemplo",md:"```text\nAlta disponibilidad: cae una zona -> el servicio sigue respondiendo\nElasticidad: sube la demanda -> se añaden recursos; baja -> se retiran\nAgilidad: nueva idea -> se prueba en días, sin comprar servidores\n```"},{tipo:"errorComun",error:"Usar elasticidad y alta disponibilidad como sinónimos.",correccion:"La elasticidad ajusta la capacidad al volumen de trabajo; la alta disponibilidad mantiene el servicio operativo ante fallos. Un sistema puede escalar bien y aun así caerse cuando falla una zona si no tiene redundancia."},{tipo:"cuandoUsar",usar:["Usa redundancia en varias zonas cuando el servicio no puede interrumpirse: eso es alta disponibilidad.","Deja que la capacidad siga la demanda con ajuste automático cuando el tráfico es variable: eso es elasticidad.","Reserva entornos de prueba de bajo coste para probar rápido: eso es agilidad."],noUsar:["No confíes solo en la elasticidad para cubrir fallos: escalar no sustituye a la redundancia.","No dimensiones para el pico permanente si la demanda es estacional: es más caro que ajustar la capacidad."]}],preguntasGuia:["¿Qué diferencia hay entre alta disponibilidad y elasticidad?","¿Cómo se relaciona la agilidad con la velocidad de experimentación?","¿Puede un sistema ser elástico y no tener alta disponibilidad?"]}],1.2:[{id:"1.2-g1",titulo:"El Well-Architected Framework como guía de diseño",objetivos:["1.2#1"],bloques:[{tipo:"concepto",md:"El **Well-Architected Framework** es una guía de diseño que reúne buenas prácticas, principios y preguntas para evaluar y mejorar la arquitectura de una carga de trabajo en la nube. No crea ni gestiona recursos: ordena las decisiones de diseño para que la carga sea segura, fiable, eficiente y sostenible. Su unidad de análisis es la **carga de trabajo (workload)**, no la cuenta ni la organización.\n\nLa revisión se apoya en la **Well-Architected Tool**, que conduce un cuestionario pilar a pilar, recoge las respuestas y genera un plan de mejora con los riesgos identificados. El resultado es un informe de riesgos altos y medios que el equipo prioriza; no es una certificación ni una auditoría automática."},{tipo:"ejemplo",md:"```text\nRevisión de una aplicación web:\n1. Describir la carga: usuarios, datos y dependencias.\n2. Responder las preguntas de cada pilar.\n3. Marcar los riesgos altos y medios.\n4. Acordar un plan de mejora con responsables.\n\nEntrada -> preguntas de diseño\nSalida  -> lista priorizada de mejoras, nunca recursos creados\n```"},{tipo:"cuandoUsar",usar:["Antes de poner una carga en producción, para detectar riesgos de diseño a tiempo.","Tras un incidente o un cambio grande, para comprobar si el diseño sigue siendo el adecuado.","Como marco común entre equipos para hablar de fiabilidad, coste y seguridad con el mismo vocabulario."],noUsar:["No lo uses como sustituto de las pruebas de carga ni de los planes de continuidad: orienta el diseño, no ejecuta la validación.","No esperes que cree la infraestructura ni que corrija los hallazgos por sí solo; el plan de mejora lo ejecuta el equipo."]},{tipo:"clave",items:["El Well-Architected Framework es una guía de diseño, no un servicio que despliegue infraestructura.","Se aplica a una carga de trabajo y la revisa pilar a pilar.","La Well-Architected Tool conduce la revisión y produce un plan de mejora con riesgos priorizados.","El resultado es una lista de mejoras acordadas, no una certificación."]}],preguntasGuia:["¿Qué es el Well-Architected Framework y qué no es?","¿Sobre qué se aplica la revisión: la cuenta o una carga de trabajo?","¿Qué aporta la Well-Architected Tool al proceso de revisión?"]},{id:"1.2-g2",titulo:"Los seis pilares y el equilibrio entre ellos",objetivos:["1.2#2"],bloques:[{tipo:"concepto",md:"El Well-Architected Framework se organiza en **seis pilares**, y cada uno responde a una pregunta distinta de diseño:\n\n- **Operational excellence**: ¿cómo operamos la carga y la mejoramos de forma continua? Cubre despliegues, observabilidad, runbooks y aprendizaje tras los incidentes.\n- **Security**: ¿cómo protegemos la información y el acceso? Cubre identidades, permisos, cifrado, detección y respuesta.\n- **Reliability**: ¿cómo sigue funcionando la carga cuando algo falla? Cubre redundancia, recuperación y tolerancia a fallos.\n- **Performance efficiency**: ¿cómo usamos los recursos de forma adecuada y escalamos con la demanda? Cubre selección de recursos y elasticidad.\n- **Cost optimization**: ¿cómo pagamos solo por lo que aporta valor? Cubre dimensionado, compromiso de uso y control del gasto.\n- **Sustainability**: ¿cómo reducimos el consumo y el impacto ambiental de la carga? Cubre eficiencia energética y ciclo de vida de los recursos.\n\nLos pilares no compiten entre sí: se equilibran. Un diseño excelente en fiabilidad pero insostenible en coste no es un buen diseño; la revisión hace explícitos los compromisos."},{tipo:"comparacion",parId:"well-architected-pillars"},{tipo:"escenario",situacion:"Un equipo revisa su plataforma y encuentra tres problemas a la vez: la base de datos se cae con frecuencia, no existen procedimientos de operación ni despliegues automatizados, y la factura creció por instancias sobredimensionadas. Necesita clasificar cada hallazgo en el pilar que le corresponde.",analisis:"El fallo recurrente de la base de datos apunta a **Reliability**; la ausencia de runbooks y automatización, a **Operational excellence**; y el sobredimensionamiento, a **Cost optimization**. Asignar cada hallazgo a un pilar concreto permite priorizar acciones en lugar de tratar la revisión como un único aprobado o suspenso.",servicio:"AWS Well-Architected Tool"},{tipo:"errorComun",error:"Elegir un pilar favorito, normalmente seguridad o coste, y evaluar la carga solo contra él.",correccion:"La revisión recorre los seis pilares. Un buen diseño equilibra fiabilidad, coste, rendimiento y sostenibilidad a la vez; dejar un pilar sin evaluar mantiene sus riesgos fuera del informe."},{tipo:"clave",items:["Seis pilares: operational excellence, security, reliability, performance efficiency, cost optimization y sustainability.","Cada pilar responde a una pregunta de diseño distinta.","La revisión busca equilibrio entre pilares, no un pilar ganador.","Cada hallazgo se asigna al pilar que le corresponde para poder priorizarlo."]}],preguntasGuia:["¿Qué pregunta de diseño responde cada uno de los seis pilares?","¿Por qué la revisión no elige un pilar prioritario sobre los demás?","¿A qué pilar asignarías un fallo de disponibilidad o un sobredimensionamiento?"]},{id:"1.2-g3",titulo:"Diferencias entre pilares: asignar bien cada decisión",objetivos:["1.2#3"],bloques:[{tipo:"concepto",md:"Cada pilar mira la carga desde un ángulo distinto, y por eso una misma decisión técnica puede mejorar uno y empeorar otro.\n\n- **Reliability** pregunta si el sistema sigue funcionando pese a los fallos; **performance efficiency** pregunta si usa los recursos adecuados y escala con la demanda.\n- **Cost optimization** pregunta si se paga solo por lo que aporta valor; **sustainability** pregunta si se reduce el consumo y el impacto ambiental.\n- **Security** pregunta si se protegen la información y el acceso; **operational excellence** pregunta si se opera y se mejora con procesos y automatización.\n\nDistinguir el pilar correcto evita confundir causas: una latencia alta es un asunto de rendimiento, no de fiabilidad; una factura inflada es un asunto de coste, no de seguridad."},{tipo:"comparacion",parId:"well-architected-pillars"},{tipo:"ejemplo",md:"```text\nSíntoma -> pilar al que apunta\n- Se pierde una ubicación y hay corte       -> Reliability\n- La aplicación responde lenta con carga    -> Performance efficiency\n- Instancias sobredimensionadas             -> Cost optimization\n- Datos sin cifrar ni control de acceso     -> Security\n- Sin runbooks ni automatización            -> Operational excellence\n- Recursos ociosos y desperdicio energético -> Sustainability\n```"},{tipo:"errorComun",error:"Atribuir todo problema de lentitud a la fiabilidad o todo sobrecoste a la seguridad, mezclando el pilar que corresponde.",correccion:"Cada pilar responde a una pregunta distinta y la solución cambia con él: la fiabilidad se resuelve con redundancia y recuperación, el rendimiento con dimensionado y escalado, y el coste con compromiso de uso y control del gasto."}],preguntasGuia:["¿En qué se diferencia reliability de performance efficiency?","¿Qué separa cost optimization de sustainability?","¿Cómo se asigna un síntoma concreto al pilar correcto?"]}],1.3:[{id:"1.3-g1",titulo:"Estrategias de adopción de la nube y beneficios de migrar",objetivos:["1.3#1"],bloques:[{tipo:"concepto",md:"Las **estrategias de adopción** describen cómo y en qué orden una organización lleva sus cargas a AWS. Antes de mover nada conviene responder al **por qué**: los beneficios que se buscan al migrar son reducir costes de infraestructura, ganar **agilidad** para desplegar más rápido, obtener **elasticidad** para escalar según la demanda, mejorar la **resiliencia** y ampliar el **alcance global** sin abrir centros de datos propios.\n\nLa adopción no es solo un traslado técnico: es un cambio organizativo. Las estrategias habituales combinan varios ingredientes:\n\n- **Adopción escalonada por olas**: agrupar aplicaciones por dependencias y migrarlas en tandas, empezando por las más sencillas.\n- **Enfoque cloud-first**: toda carga nueva se plantea primero en la nube y solo se excluye con una justificación clara.\n- **Centro de excelencia**: equipo que define estándares, guardarraíles y buenas prácticas para el resto de la organización.\n- **Motivaciones alineadas con el negocio**: cada migración se justifica por un resultado (coste, velocidad, cumplimiento, experiencia del cliente) y no por la tecnología en sí."},{tipo:"cuandoUsar",usar:["Usa adopción por olas cuando tengas muchas aplicaciones y dependencias: reduce el riesgo al migrar por grupos manejables.","Impulsa cloud-first para que los equipos no repliquen por inercia el modelo anterior.","Crea un centro de excelencia cuando varias áreas deban compartir estándares, seguridad y control de costes.","Alinea cada ola con un resultado de negocio medible antes de empezar."],noUsar:["No migres todo a la vez buscando rapidez: multiplica el riesgo y dificulta revertir.","No plantees la adopción solo como un proyecto de infraestructura: sin cambio en procesos y personas, los beneficios no llegan."]},{tipo:"errorComun",error:"Creer que migrar se reduce a copiar servidores a AWS y que, por tanto, los beneficios aparecen solos.",correccion:"La migración es un proceso de adopción: exige priorizar cargas, rediseñar procesos y preparar a las personas. Sin ese cambio organizativo, mover servidores no produce agilidad ni ahorro sostenido."},{tipo:"clave",items:["La adopción empieza por el por qué de negocio, no por el servicio técnico.","Los beneficios típicos son coste, agilidad, elasticidad, resiliencia y alcance global.","La adopción por olas y el enfoque cloud-first reducen el riesgo de un cambio completo de golpe.","Un centro de excelencia difunde estándares y buenas prácticas en toda la organización."]}],preguntasGuia:["¿Qué beneficios de negocio justifican migrar a la nube?","¿Por qué la adopción por olas reduce el riesgo frente a una migración completa de golpe?","¿Qué papel tiene un centro de excelencia en la estrategia de adopción?"]},{id:"1.3-g2",titulo:"Recursos del viaje de migración y estrategias de migración",objetivos:["1.3#2","1.3#4"],bloques:[{tipo:"concepto",md:"Migrar una cartera de aplicaciones es un **viaje** por fases: evaluar, planificar, mover y optimizar. AWS ofrece recursos para cada fase:\n\n- **Migration Evaluator**: construye el caso de negocio y estima el ahorro frente al entorno actual.\n- **AWS Application Discovery Service**: descubre servidores, dependencias y uso real de la infraestructura on-premises.\n- **AWS Migration Hub**: punto único para seguir el progreso de las migraciones entre herramientas y regiones.\n- **AWS Application Migration Service**: replica servidores completos (rehost) con la mínima interrupción.\n- **AWS Database Migration Service (AWS DMS)**: migra bases de datos, incluidas las replicaciones continuas.\n- **AWS Schema Conversion Tool (AWS SCT)**: convierte esquemas y código de bases de datos entre motores distintos.\n- **AWS Prescriptive Guidance**: guías y patrones probados para planificar y ejecutar la migración.\n\nSobre esas herramientas se elige la **estrategia de migración** aplicación a aplicación, conocida como las «7 R»:\n\n- **Retire**: apagar lo que ya no aporta.\n- **Retain**: dejar temporalmente lo que aún no conviene mover.\n- **Rehost** (*lift and shift*): mover tal cual.\n- **Relocate**: trasladar plataformas completas sin cambios.\n- **Replatform** (*lift, tuck and reshape*): migrar con ajustes para usar servicios gestionados.\n- **Repurchase** (*drop and shop*): sustituir por una solución SaaS.\n- **Refactor / re-architect**: rediseñar aprovechando la nube.\n\nLa **replicación de bases de datos** es un ejemplo concreto: se copia el dato de forma continua desde el origen hasta AWS y se corta el tráfico en una ventana breve."},{tipo:"comparacion",parId:"rehost-vs-replataforma"},{tipo:"cuandoUsar",usar:["Usa rehost para cumplir plazos y salir rápido del centro de datos cuando la aplicación no se va a tocar.","Usa replatform cuando quieras aprovechar servicios gestionados con un cambio acotado y riesgo controlado.","Usa replicación de bases de datos cuando no puedas permitirte una parada larga durante el corte."],noUsar:["No rehostees una aplicación que piensas apagar en pocos meses: solo trasladas deuda técnica.","No reserves el refactor completo para toda la cartera: el rediseño profundo se justifica donde aporta ventaja competitiva."]},{tipo:"errorComun",error:"Elegir una sola estrategia de migración para toda la cartera de aplicaciones.",correccion:"La estrategia se decide aplicación a aplicación: unas se retiran, otras se rehospedan y solo unas pocas se rediseñan. Forzar una sola «R» a todo el inventario encarece o retrasa el viaje."},{tipo:"clave",items:["Evalúa con Migration Evaluator y AWS Application Discovery Service; planifica con AWS Prescriptive Guidance.","Sigue el progreso con AWS Migration Hub; ejecuta con AWS Application Migration Service y AWS Database Migration Service (AWS DMS).","Elige la estrategia por aplicación: rehost, replatform, refactor, repurchase, relocate, retain o retire.","La replicación continua de bases de datos reduce la ventana de corte."]}],preguntasGuia:["¿Qué recurso del viaje de migración sirve para evaluar, cuál para planificar y cuál para seguir el progreso?","¿Qué diferencia hay entre rehost, replatform y refactor?","¿Cómo ayuda la replicación de bases de datos a reducir la parada durante una migración?"]},{id:"1.3-g3",titulo:"Componentes del AWS Cloud Adoption Framework (AWS CAF)",objetivos:["1.3#3"],bloques:[{tipo:"concepto",md:"El **AWS Cloud Adoption Framework (AWS CAF)** es el marco de AWS para ordenar la adopción de la nube en toda la organización. No diseña la arquitectura técnica de una aplicación: organiza el cambio en **perspectivas** y **capacidades** para que negocio y tecnología avancen juntos.\n\nEl AWS CAF agrupa sus componentes en seis perspectivas, tres de negocio y tres técnicas:\n\n- **Business**: asegura que la nube genera valor de negocio.\n- **People**: prepara a las personas y los procesos de cambio (cultura, formación, organización).\n- **Governance**: alinea la inversión con la estrategia y gestiona riesgos y cumplimiento.\n- **Platform**: construye la plataforma y la arquitectura de la solución.\n- **Security**: protege datos, sistemas y activos.\n- **Operations**: opera y monitoriza los servicios en la nube.\n\nLos **beneficios** que persigue el AWS CAF son de negocio: reducir el riesgo empresarial, mejorar el desempeño ambiental, social y de gobernanza (ESG), aumentar los ingresos y mejorar la eficiencia operativa. Por eso se mide en resultados de negocio, no solo en artefactos técnicos."},{tipo:"comparacion",parId:"caf-vs-well-architected"},{tipo:"escenario",situacion:"Una empresa quiere migrar a AWS, pero cada área va por su cuenta: finanzas no ve el retorno, recursos humanos no está preparado para el cambio y el equipo de plataforma improvisa la arquitectura. El comité pide un plan que ordene la adopción y demuestre valor de negocio.",analisis:"El **AWS Cloud Adoption Framework (AWS CAF)** encaja porque cubre las seis perspectivas: Business y Governance para justificar la inversión y gestionar el riesgo, People para el cambio cultural y la formación, y Platform, Security y Operations para la parte técnica. El AWS CAF aporta el mapa organizativo; el diseño técnico detallado de cada carga llega después con el AWS Well-Architected Framework."},{tipo:"cuandoUsar",usar:["Usa el AWS CAF cuando el requisito sea ordenar la adopción en toda la organización y alinear negocio, personas y tecnología.","Usa el AWS Well-Architected Framework cuando el requisito sea evaluar el diseño técnico de una carga de trabajo concreta.","Usa AWS Prescriptive Guidance cuando el requisito sea una guía práctica de implementación para un escenario concreto."],noUsar:["No uses el AWS CAF para elegir un tipo de instancia, una clase de almacenamiento o un motor de base de datos: eso es diseño técnico.","No uses el AWS CAF como sustituto de un plan de proyecto: aporta el marco de perspectivas y capacidades, no las tareas del plan.","No confundas «mejorar el desempeño ESG» con un pilar del Well-Architected: es un beneficio de negocio del AWS CAF."]},{tipo:"errorComun",error:"Confundir el AWS CAF con un marco de diseño técnico y usarlo para decidir tipos de instancias o clases de almacenamiento.",correccion:"El AWS CAF guía el cambio organizativo y de negocio: personas, gobernanza, plataforma, seguridad y operaciones. El diseño técnico de las cargas corresponde al AWS Well-Architected Framework."},{tipo:"clave",items:["El AWS CAF ordena la adopción con seis perspectivas: Business, People, Governance, Platform, Security y Operations.","Business, People y Governance miran al negocio; Platform, Security y Operations, a lo técnico.","Los beneficios se miden en resultados: menos riesgo, mejor desempeño ESG, más ingresos y más eficiencia operativa.","El AWS CAF no es el AWS Well-Architected Framework: adopción organizativa frente a diseño técnico de las cargas."]}],preguntasGuia:["¿En qué perspectivas organiza el AWS CAF sus componentes?","¿Qué beneficios de negocio persigue el AWS CAF?","¿En qué se diferencia el AWS CAF del AWS Well-Architected Framework?"]}],1.4:[{id:"1.4-g1",titulo:"Coste fijo frente a coste variable y costes del entorno on-premises",objetivos:["1.4#1","1.4#3","1.4#4"],bloques:[{tipo:"concepto",md:"La **economía de la nube** describe cómo cambia la estructura de costes al pasar de un centro de datos propio a la nube. El eje de esa estructura es la distinción entre **coste fijo** y **coste variable**.\n\n- **Coste fijo (capex)**: inversión que se paga por adelantado y no depende del uso — servidores comprados, almacenamiento, licencias perpetuas, obra y equipamiento de la sala. Existe aunque no haya ni un solo cliente.\n- **Coste variable (opex)**: se factura según el consumo real — horas de cómputo, GB almacenados, transferencia de datos. Si el recurso no se usa, no se paga.\n\nEn **on-premises** dominan los costes fijos y los costes indirectos: hardware, energía, refrigeración, espacio físico, personal de mantenimiento, seguridad física y el **coste de la capacidad ociosa**, es decir, comprar para el pico de tráfico y desperdiciar esa capacidad el resto del tiempo. En la nube buena parte de ese gasto se convierte en variable y se alinea con la demanda, lo que reduce el riesgo financiero de acertar con la previsión."},{tipo:"comparacion",parId:"costes-fijos-vs-variables"},{tipo:"escenario",situacion:"Un equipo quiere dimensionar su infraestructura para el pico de Black Friday comprando servidores de más, de forma que el resto del año quede capacidad sin usar.",analisis:"Comprar para el pico convierte el sobredimensionamiento en un **coste fijo hundido**: se paga también los meses de baja demanda. En la nube el gasto se alinea con el consumo real y el aprovisionamiento se ajusta con elasticidad, de modo que el pico no obliga a mantener recursos ociosos el resto del año. Cuando la carga es estable sí conviene un compromiso (Reserved Instances o Savings Plans) para bajar la tarifa, pero el dimensionado sigue basándose en la necesidad real y no en comprar capacidad física para el peor día.",servicio:"AWS Auto Scaling"},{tipo:"errorComun",error:"Creer que pasar a la nube siempre sale más barato por sí solo, sin comparar el coste total de cada opción.",correccion:"La nube no garantiza ahorro automático: hay que comparar el coste total, eliminar la capacidad ociosa, apagar lo que no se usa y elegir el modelo de precio adecuado. El ahorro nace de la elasticidad y del pago por uso, no del proveedor por sí mismo."},{tipo:"clave",items:["Coste fijo = capex: se paga por adelantado y no depende del uso (hardware, licencias perpetuas, obra).","Coste variable = opex: se factura según el consumo real (cómputo, almacenamiento, transferencia).","On-premises concentra costes fijos e indirectos: energía, refrigeración, espacio, personal y capacidad ociosa.","La nube convierte buena parte del coste fijo en variable y reduce el riesgo de sobredimensionar."]}],preguntasGuia:["¿Qué diferencia hay entre un coste fijo y un coste variable en un centro de datos propio?","¿Por qué el sobredimensionamiento on-premises se paga aunque no se use?","¿De qué depende que migrar a la nube suponga un ahorro real?"]},{id:"1.4-g2",titulo:"Ahorro al migrar a la nube y economías de escala",objetivos:["1.4#2","1.4#8"],bloques:[{tipo:"concepto",md:"**Migrar a la nube** reduce costes por varias vías a la vez:\n\n- Se deja de invertir en **capex** y se pasa a **opex** ligado al consumo.\n- Se **elimina la capacidad ociosa**: no hay que comprar para el pico anual.\n- Se dejan de pagar los costes indirectos del centro de datos (energía, refrigeración, espacio, mantenimiento).\n- Se reduce el trabajo de operar y actualizar hardware, que pasa a ser responsabilidad del proveedor.\n\nLas **economías de escala** son el motor de fondo: un proveedor de nube compra y opera a un volumen enorme y reparte ese coste entre millones de clientes. El **precio por unidad baja** a medida que crece la escala, y esa tarifa reducida se traslada al cliente sin que este tenga que alcanzar ese volumen por su cuenta. El ahorro no es solo «pagar por uso»: es pagar una **tarifa más baja** de la que lograría un centro de datos pequeño."},{tipo:"ejemplo",md:"```text\nEstructura de coste al migrar\n\nOn-premises              Nube\ncapex alto               opex por consumo\ncapacidad para el pico   capacidad elastica\ncoste fijo alto          coste variable\n+ energia y espacio      tarifa de escala\n+ personal de sala       sin sala que mantener\n```"},{tipo:"errorComun",error:"Creer que migrar a la nube abarata la factura de forma automática por el simple hecho de usar AWS.",correccion:"El ahorro depende de ajustar el tamaño de los recursos, apagar lo que no se usa, aprovechar las economías de escala del proveedor y elegir el modelo de precio adecuado. Sin ese trabajo, la factura puede parecerse a la del centro de datos anterior."},{tipo:"clave",items:["Ahorro al migrar: menos capex, sin capacidad ociosa, menos costes indirectos y menos operación.","Economías de escala: el proveedor compra y opera a gran volumen y traslada un precio unitario menor.","El ahorro no es automático: depende de apagar recursos, ajustar tamaños y elegir el modelo de precio.","A mayor volumen agregado del proveedor, menor coste por unidad para cada cliente."]}],preguntasGuia:["¿Por qué migrar a la nube puede reducir el coste total frente a un centro de datos propio?","¿Qué significa que existan economías de escala en la nube?","¿El ahorro al migrar es automático?"]},{id:"1.4-g3",titulo:"Rightsizing, beneficios de la automatización y estrategias de licencias",objetivos:["1.4#5","1.4#6","1.4#7"],bloques:[{tipo:"concepto",md:"**Rightsizing** es ajustar el tamaño de los recursos a la carga real. Un recurso sobredimensionado se paga entero aunque se aproveche una fracción; uno infradimensionado degrada el servicio. El right-sizing se apoya en métricas de uso para subir o bajar capacidad de forma continua.\n\nLa **automatización** reduce coste de dos maneras: quita trabajo manual repetitivo y evita que la infraestructura se quede encendida por olvido. Apagar entornos fuera de horario, escalar según la demanda y aplicar cambios de forma reproducible son ejemplos típicos.\n\nLas **estrategias de licencias** afectan directamente a la factura:\n\n- **BYOL (Bring Your Own License)**: la empresa reutiliza licencias que ya posee y paga solo la infraestructura. Aprovecha la inversión previa, pero exige gestionar el cumplimiento y los términos de cada licencia.\n- **Licencias incluidas**: el coste de la licencia va dentro del precio del servicio, sin aportar nada. Simplifica la gestión, pero puede salir más caro si ya se tenían licencias propias."},{tipo:"servicio",nombre:"AWS License Manager"},{tipo:"cuandoUsar",usar:["Aplica right-sizing cuando las métricas muestran recursos muy por debajo o por encima de su capacidad.","Automatiza el apagado y el escalado para que la capacidad siga a la demanda sin intervención manual.","Elige BYOL si ya tienes licencias en propiedad y puedes cumplir sus condiciones; elige licencias incluidas si prefieres simplicidad."],noUsar:["No dejes servidores encendidos «por si acaso»: el coste de lo infrautilizado se acumula igual.","No apliques BYOL sin revisar la compatibilidad y los términos de la licencia, ni asumas que siempre es más barato."]},{tipo:"ejemplo",md:"```text\nSituacion                 Decision\n- Uso de CPU al 8%         reducir tamano (right-sizing)\n- Entornos de prueba       apagado automatico fuera de horario\n- Ya tengo licencias       evaluar BYOL\n- No quiero gestionar      licencias incluidas\n```"},{tipo:"errorComun",error:"Creer que right-sizing es reducir tamaño una sola vez, o que BYOL siempre ahorra.",correccion:"Rightsizing es un ajuste continuo guiado por métricas, no una acción puntual. Y BYOL solo ahorra si las licencias propias son válidas en el entorno elegido y su gestión no cuesta más que la licencia incluida."}],preguntasGuia:["¿Qué es rightsizing y qué señales indican que hace falta?","¿Cómo reduce costes la automatización?","¿Cuándo conviene BYOL y cuándo una licencia incluida?"]}],2.1:[{id:"2.1-g1",titulo:"El AWS shared responsibility model y sus dos caras",objetivos:["2.1#1","2.1#2","2.1#3","2.1#4"],bloques:[{tipo:"concepto",md:"El **AWS shared responsibility model** reparte la seguridad entre dos actores: AWS y el cliente. No se trata de quién hace «más», sino de **quién controla qué**.\n\n- **AWS: seguridad de la nube**. Protege la infraestructura que sostiene todos los servicios: instalaciones físicas, hardware, red y la capa de virtualización. Es seguridad física y de plataforma, controlada por AWS y no delegable al cliente.\n- **Cliente: seguridad en la nube**. Protege lo que pone dentro: los datos, las identidades y los accesos, las aplicaciones y la configuración de los recursos que contrata.\n\nEl límite no es fijo: depende del servicio. Cuanto más gestionado es el servicio, más arriba queda la línea y más responsabilidad operativa asume AWS. Por eso se habla de una **responsabilidad compartida** y no de una división rígida."},{tipo:"comparacion",parId:"responsabilidad-compartida-cliente-vs-aws"},{tipo:"escenario",situacion:"Una empresa ejecuta sus servidores en instancias de Amazon EC2 y descubre que hay actualizaciones de seguridad pendientes del sistema operativo invitado. El equipo pregunta quién debe aplicarlas.",analisis:"AWS asegura la infraestructura que aloja la instancia —centro de datos, hosts, red y capa de virtualización—, pero el sistema operativo invitado, las aplicaciones y la configuración de la instancia corresponden al cliente. Aplicar esos parches es responsabilidad del cliente.",servicio:"Amazon EC2"},{tipo:"errorComun",error:"Creer que, al contratar un servicio de AWS, AWS se encarga de absolutamente todo, incluida la seguridad de los datos y la configuración de los recursos.",correccion:"AWS responde de la infraestructura subyacente; el cliente responde de lo que configura en la nube: datos, identidades, aplicaciones y ajustes del servicio. La seguridad es una responsabilidad compartida y ninguna de las dos partes cubre la mitad de la otra."},{tipo:"clave",items:["AWS = seguridad de la nube: instalaciones, hardware, red y virtualización.","Cliente = seguridad en la nube: datos, identidades, aplicaciones y configuración.","El modelo reparte responsabilidades, no las elimina: ambas partes actúan a la vez.","El reparto cambia según el servicio contratado y su nivel de gestión."]}],preguntasGuia:["¿Qué dos grandes mitades reparte el AWS shared responsibility model?","¿De qué responde AWS y de qué responde el cliente?","¿Por qué se dice que la responsabilidad es compartida y no dividida?"]},{id:"2.1-g2",titulo:"Seguridad de la nube y seguridad en la nube",objetivos:["2.1#5","2.1#6"],bloques:[{tipo:"concepto",md:"«Seguridad **de** la nube» y «seguridad **en** la nube» son las dos mitades del modelo:\n\n- **Seguridad de la nube**: la asume AWS. Cubre la protección de la infraestructura que ejecuta los servicios: instalaciones, cómputo, almacenamiento, red y el software que lo gestiona.\n- **Seguridad en la nube**: la asume el cliente y depende de lo que configura. Incluye los datos, las identidades y permisos, las aplicaciones y los ajustes de red y cifrado del servicio.\n\nExisten además **responsabilidades compartidas**, que ambos atienden desde su lado: por ejemplo, la gestión de parches, la gestión de la configuración y la concienciación y formación. AWS parchea su infraestructura y el cliente parchea lo suyo; sin las dos partes, el resultado no es seguro."},{tipo:"comparacion",parId:"seguridad-de-la-nube-vs-seguridad-en-la-nube"},{tipo:"escenario",situacion:"Una empresa aloja su base de datos en Amazon RDS y cree que, por ser un servicio gestionado, ya no tiene ninguna responsabilidad de seguridad.",analisis:"AWS gestiona el motor de base de datos, sus parches y las copias de seguridad de la plataforma, pero el cliente sigue siendo responsable de los datos que guarda, de quién puede acceder a ellos y de cómo configura el servicio. La responsabilidad se desplaza, no desaparece.",servicio:"Amazon RDS"},{tipo:"errorComun",error:"Pensar que la seguridad en la nube es responsabilidad exclusiva de AWS porque los servicios son gestionados.",correccion:"El cliente responde de la seguridad de lo que controla dentro de la nube: datos, identidades, permisos y configuración. Un servicio gestionado mueve la frontera, pero el cliente conserva su parte."}],preguntasGuia:["¿Qué diferencia hay entre seguridad de la nube y seguridad en la nube?","¿Qué responsabilidades comparten AWS y el cliente?","¿Qué parte sigue siendo del cliente en un servicio gestionado?"]},{id:"2.1-g3",titulo:"Cómo se desplaza la responsabilidad según el servicio",objetivos:["2.1#6"],bloques:[{tipo:"concepto",md:"La frontera entre ambas responsabilidades **se desplaza según el servicio**. Tres casos ilustran el examen:\n\n- **Infraestructura como servicio**, por ejemplo Amazon EC2: AWS gestiona la infraestructura; el cliente gestiona el sistema operativo, los parches y todo lo que instala.\n- **Plataforma gestionada**, por ejemplo Amazon RDS: AWS gestiona además el motor de base de datos, sus parches y las copias de seguridad de la plataforma; el cliente cuida los datos y los accesos.\n- **Serverless**, por ejemplo AWS Lambda: AWS gestiona el entorno de ejecución y el escalado; el cliente aporta el código, sus permisos y sus datos.\n\nCuanto más gestionado es el servicio, más responsabilidad operativa asume AWS y menos el cliente, pero el cliente **nunca** deja de ser responsable de sus datos, de sus identidades y de su configuración."},{tipo:"comparacion",parId:"seguridad-de-la-nube-vs-seguridad-en-la-nube"},{tipo:"escenario",situacion:"Un equipo pasa una función de cómputo a AWS Lambda y pregunta si sigue teniendo que aplicar parches al sistema operativo que ejecuta su código.",analisis:"No: en AWS Lambda AWS gestiona el sistema operativo y el entorno de ejecución. El cliente mantiene la responsabilidad sobre el código de la función, los permisos que concede y los datos a los que accede.",servicio:"AWS Lambda"},{tipo:"cuandoUsar",usar:["Usa un servicio más gestionado cuando quieras que AWS asuma más capas de operación, como parches o escalado.","Usa un servicio menos gestionado cuando necesites controlar el sistema operativo o el entorno de ejecución.","Comprueba en cada servicio dónde queda la frontera antes de decidir, porque el reparto no es el mismo para todos."],noUsar:["No asumas que elegir un servicio gestionado te libera de proteger datos, accesos y configuración.","No trates la responsabilidad como una decisión de todo o nada: se desplaza capa a capa según el servicio."]},{tipo:"errorComun",error:"Suponer que la responsabilidad del cliente desaparece por completo al usar un servicio totalmente gestionado.",correccion:"El reparto se desplaza, no se elimina: en un servicio gestionado AWS asume más capas de operación, pero el cliente sigue respondiendo de sus datos, del acceso a esos datos y de la configuración del servicio."}],preguntasGuia:["¿Cómo cambia la responsabilidad entre Amazon EC2, Amazon RDS y AWS Lambda?","¿Qué asume AWS en un servicio serverless y qué conserva el cliente?","¿Por qué el cliente nunca deja de responder de sus datos?"]}],2.2:[{id:"2.2-g1",titulo:"Seguridad en la nube, cifrado y protección de datos",objetivos:["2.2#1","2.2#2","2.2#7"],bloques:[{tipo:"concepto",md:"La **seguridad en la nube** abarca mucho más que evitar intrusiones: incluye **cifrado**, **control de acceso**, **visibilidad** y **cumplimiento**. Bajo el modelo de responsabilidad compartida, AWS protege la infraestructura y el cliente protege sus datos, sus identidades y la configuración de sus recursos.\n\nConviene separar dos conceptos que suelen confundirse:\n\n- **Compliance (cumplimiento)**: cumplir las normas, leyes y estándares que aplican a la organización, por ejemplo la protección de datos personales o la normativa de un sector concreto.\n- **Governance (gobernanza)**: las reglas, controles y procesos internos con los que la organización demuestra y sostiene ese cumplimiento en el tiempo.\n\nEl **cifrado** es el beneficio de seguridad más citado porque reduce el impacto de una exposición: aunque un dato se copie o se filtre, sin la clave no es legible. Se aplica en dos momentos que hay que distinguir: **en tránsito** (mientras viaja por la red) y **en reposo** (cuando está almacenado). Ninguno sustituye al control de acceso ni a las copias de seguridad: se complementan."},{tipo:"comparacion",parId:"cifrado-en-transito-vs-en-reposo"},{tipo:"ejemplo",md:"```text\nCifrado en reposo:\n  el dato guardado no es legible sin la clave\n  se gestiona con claves, por ejemplo con AWS KMS\n\nCifrado en tránsito:\n  el dato viaja protegido entre el cliente y el servicio\n  se apoya en TLS/HTTPS en los endpoints\n\nAmbos se complementan:\n  no basta con cifrar solo uno de los dos momentos\n```"},{tipo:"errorComun",error:"Creer que basta con cifrar los datos en reposo porque el tráfico interno «ya está dentro» de la infraestructura.",correccion:"El cifrado en reposo y el cifrado en tránsito cubren riesgos distintos y no se sustituyen. Los datos también viajan entre servicios, entre cuentas y hacia el usuario; ese recorrido necesita cifrado en tránsito además del cifrado en reposo."},{tipo:"clave",items:["Compliance = cumplir normas y leyes aplicables; governance = reglas y controles internos que lo sostienen.","El cifrado reduce el impacto de una exposición: sin la clave, el dato es ilegible.","Cifrado en tránsito protege el dato mientras viaja; cifrado en reposo lo protege mientras está almacenado.","El cifrado es un beneficio de la nube, pero no reemplaza al control de acceso ni a las copias de seguridad."]}],preguntasGuia:["¿En qué se diferencian compliance y governance?","¿Por qué el cifrado se considera un beneficio de seguridad clave?","¿Qué protege el cifrado en tránsito y qué protege el cifrado en reposo?"]},{id:"2.2-g2",titulo:"Monitoreo, auditoría y cumplimiento de configuración",objetivos:["2.2#3","2.2#8"],bloques:[{tipo:"concepto",md:"La gobernanza en la nube responde a tres preguntas distintas, y cada una tiene su herramienta:\n\n- **¿Cómo está funcionando el entorno?** → **monitoreo**. **Amazon CloudWatch** recoge métricas, logs y eventos, y permite crear alarmas cuando se cruza un umbral.\n- **¿Quién hizo qué y cuándo?** → **auditoría**. **AWS CloudTrail** registra las llamadas a la API realizadas en la cuenta: la identidad, el origen y el momento de cada acción.\n- **¿En qué estado está la configuración y cumple las reglas?** → **cumplimiento de configuración**. **AWS Config** guarda el historial de configuración de los recursos y evalúa si cumplen las reglas definidas.\n\nLos **logs de seguridad** se capturan y localizan en varios sitios: los logs operativos van a **CloudWatch Logs**, la actividad de la API queda en **AWS CloudTrail** (cuyos eventos se pueden entregar a un bucket de **Amazon S3**) y los cambios de configuración en **AWS Config**. Conocer dónde vive cada registro es imprescindible para investigar un incidente o preparar una auditoría."},{tipo:"comparacion",parId:"cloudwatch-vs-cloudtrail-vs-config"},{tipo:"escenario",situacion:"Un auditor pregunta qué identidad eliminó un recurso, cuándo ocurrió y si la configuración del recurso se había desviado antes de lo permitido.",analisis:"**AWS CloudTrail** aporta el historial de llamadas a la API con la identidad y la marca temporal; **AWS Config** aporta el historial de configuración del recurso y el resultado de las reglas; **Amazon CloudWatch** suma métricas y logs de operación para ver qué estaba pasando en ese momento. Los tres registros se consultan juntos en una investigación.",servicio:"AWS CloudTrail"},{tipo:"ejemplo",md:"```text\nNecesidad -> servicio\n- ¿Quién cambió este recurso?       -> AWS CloudTrail\n- ¿Está configurado como exige la norma? -> AWS Config\n- ¿Cómo responde el sistema y cuándo alerta? -> Amazon CloudWatch\n\nLos registros se centralizan para retención y consulta:\n  eventos de AWS CloudTrail y logs en Amazon S3 o CloudWatch Logs\n```"},{tipo:"errorComun",error:"Usar Amazon CloudWatch como si fuera un registro de auditoría y creer que sus métricas demuestran quién hizo un cambio.",correccion:"CloudWatch describe el funcionamiento del sistema; la autoría de las acciones la registra AWS CloudTrail y el estado de la configuración lo registra AWS Config. Para una auditoría se necesitan los registros de actividad y de configuración, no solo las métricas."},{tipo:"clave",items:["Amazon CloudWatch = monitoreo con métricas, logs y alarmas del funcionamiento.","AWS CloudTrail = auditoría; registra las llamadas a la API y responde quién hizo qué y cuándo.","AWS Config = historial de configuración de los recursos y evaluación frente a reglas.","Los logs de seguridad se buscan en CloudWatch Logs, en el historial de AWS CloudTrail y en AWS Config, según el tipo de registro."]}],preguntasGuia:["¿Qué pregunta responde cada uno: CloudWatch, CloudTrail y Config?","¿Dónde se capturan y localizan los logs asociados a la seguridad?","¿Por qué las métricas de monitoreo no sustituyen a un registro de auditoría?"]},{id:"2.2-g3",titulo:"Información de cumplimiento y variación por geografía e industria",objetivos:["2.2#4","2.2#5"],bloques:[{tipo:"concepto",md:"La información de cumplimiento de AWS se consulta sin abrir incidencias de soporte: **AWS Artifact** es un centro de autoservicio donde el cliente descarga los informes de auditoría y certificaciones de AWS (por ejemplo, informes SOC e ISO) y los acuerdos y condiciones aplicables.\n\nEl cumplimiento **no es el mismo para todos**: depende de dos ejes.\n\n- **Geografía**: las leyes de cada país o región imponen obligaciones distintas, como la residencia de los datos personales.\n- **Industria**: sectores como salud, finanzas o comercio electrónico tienen normas propias (por ejemplo, normativa sanitaria o estándares de pago).\n\nCuando cambia el requisito, cambia la configuración: hay que elegir la región adecuada, los servicios y controles que lo soportan y los informes que lo evidencian. La responsabilidad de cumplir con la normativa propia del cliente es del cliente; AWS facilita la evidencia y la seguridad de la infraestructura."},{tipo:"cuandoUsar",usar:["Usa AWS Artifact cuando un auditor o un área legal pida informes de cumplimiento, certificaciones o acuerdos de AWS.","Revisa los requisitos de la geografía y de la industria antes de elegir la región y los servicios de un sistema.","Conserva la evidencia de cumplimiento junto con la configuración aplicada para poder demostrarla en auditorías."],noUsar:["No asumas que un informe de AWS cubre los controles del cliente: la evidencia de AWS no demuestra la configuración de tu cuenta.","No apliques la misma configuración en todas las geografías sin revisar las obligaciones locales y sectoriales."]},{tipo:"errorComun",error:"Pensar que los requisitos de cumplimiento son iguales en todos los países y sectores, o que AWS es responsable de cumplirlos por el cliente.",correccion:"Cada geografía y cada industria imponen obligaciones distintas, y el cliente conserva la responsabilidad de su propio cumplimiento. AWS proporciona la evidencia y la seguridad de la infraestructura mediante recursos como AWS Artifact."},{tipo:"clave",items:["AWS Artifact = centro de recursos para descargar informes de cumplimiento y acuerdos de AWS.","Los requisitos de cumplimiento varían por geografía (leyes locales) y por industria (normas del sector).","El cliente cumple su propia normativa; AWS aporta evidencia e infraestructura.","Antes de diseñar, revisa qué región, servicios y controles exige el requisito aplicable."]}],preguntasGuia:["¿Dónde se encuentra la información de cumplimiento de AWS y qué se puede descargar?","¿Qué dos ejes hacen variar los requisitos de cumplimiento?","¿Quién es responsable de cumplir la normativa propia del cliente?"]},{id:"2.2-g4",titulo:"Servicios de detección y protección gestionada",objetivos:["2.2#6","2.2#9"],bloques:[{tipo:"concepto",md:"Un cliente asegura sus recursos combinando servicios gestionados de detección y protección, cada uno con un foco distinto:\n\n- **Amazon Inspector**: detecta vulnerabilidades y exposición en las cargas de trabajo.\n- **Amazon GuardDuty**: detecta actividad maliciosa y comportamiento anómalo a partir de registros y señales de la cuenta.\n- **AWS Security Hub**: centraliza y normaliza los hallazgos de seguridad para verlos en un solo lugar.\n- **AWS Shield**: protege frente a ataques de denegación de servicio distribuido (DDoS).\n- **AWS WAF**: filtra el tráfico web malintencionado que llega a una aplicación.\n- **Amazon Macie**: descubre y clasifica datos sensibles almacenados.\n- **Amazon Detective**: ayuda a investigar la causa de un hallazgo.\n- **AWS Firewall Manager**: aplica políticas de protección de forma centralizada.\n\nLos **requisitos de cumplimiento varían según el servicio**: cada servicio tiene su propio alcance dentro del modelo de responsabilidad compartida, sus controles disponibles y sus informes. Un requisito de cifrado, por ejemplo, se cumple de forma distinta según cómo cada servicio gestione las claves y qué delegue en el cliente."},{tipo:"cuandoUsar",usar:["Usa Amazon GuardDuty para detectar amenazas y AWS Shield para mitigar ataques de denegación de servicio distribuido (DDoS).","Usa Amazon Inspector para vulnerabilidades, AWS Security Hub para centralizar hallazgos y Amazon Macie para datos sensibles.","Comprueba, servicio a servicio, cómo se implementa el control exigido y qué parte queda del lado del cliente."],noUsar:["No esperes que un solo servicio de seguridad cubra detección, mitigación, inventario y cumplimiento a la vez: se complementan.","No asumas que un requisito se cumple igual en todos los servicios: revisa el alcance y los controles de cada uno."]},{tipo:"escenario",situacion:"Una empresa recibe un pico de tráfico que intenta dejar su web fuera de servicio y, a la vez, quiere detectar de forma automática comportamiento sospechoso en su cuenta.",analisis:"**AWS Shield** mitiga el ataque de denegación de servicio distribuido (DDoS) sobre la aplicación, y **Amazon GuardDuty** analiza señales y registros para detectar actividad maliciosa. Son focos distintos y complementarios dentro del mismo modelo de responsabilidad compartida.",servicio:"Amazon GuardDuty"},{tipo:"errorComun",error:"Suponer que un servicio de seguridad de AWS cubre todas las capas y que su activación exime al cliente de configurar sus propios controles.",correccion:"Cada servicio cubre un foco concreto (vulnerabilidades, amenazas, DDoS, tráfico web) y su cobertura depende de que el cliente lo configure y lo aplique a sus recursos. La seguridad del cliente sigue siendo responsabilidad del cliente."},{tipo:"clave",items:["Amazon Inspector = vulnerabilidades; Amazon GuardDuty = actividad maliciosa; AWS Security Hub = hallazgos centralizados; AWS Shield = ataques de denegación de servicio distribuido (DDoS).","AWS WAF filtra tráfico web, Amazon Macie descubre datos sensibles y Amazon Detective investiga hallazgos.","Los requisitos de cumplimiento cambian según el servicio: distinto alcance, distintos controles y distintos informes.","Los servicios de seguridad se complementan; ninguno cubre todo el modelo de responsabilidad compartida por sí solo."]}],preguntasGuia:["¿Qué protege cada uno: Amazon Inspector, Amazon GuardDuty, AWS Security Hub y AWS Shield?","¿Por qué los requisitos de cumplimiento varían entre servicios de AWS?","¿Qué parte del modelo de responsabilidad compartida sigue cubriendo el cliente?"]}],2.3:[{id:"2.3-g1",titulo:"IAM: identidades, políticas y acceso programático",objetivos:["2.3#1","2.3#7"],bloques:[{tipo:"concepto",md:"**AWS Identity and Access Management (IAM)** es el servicio que controla **quién** puede hacer **qué** dentro de una cuenta de AWS. Se organiza en dos piezas complementarias:\n\n- **Identidades**: el **usuario** (persona o aplicación con credenciales propias), el **grupo** (conjunto de usuarios que comparten los mismos permisos) y el **rol** (identidad que se asume temporalmente y que no tiene credenciales permanentes).\n- **Políticas**: documentos que conceden o deniegan acciones sobre recursos. Las **managed policies** las administra AWS o las crea el cliente para reutilizarlas en varias identidades; las **custom policies** las escribe el cliente a medida; las **inline policies** quedan pegadas a una única identidad y no se reutilizan.\n\nLa **autenticación** comprueba quién es la identidad y la **autorización** decide qué puede hacer. El diseño recomendado agrupa identidades por función, adjunta al grupo una política con el permiso mínimo y recurre a roles con credenciales temporales cuando el acceso lo asume una aplicación o un servicio."},{tipo:"comparacion",parId:"iam-user-vs-iam-role"},{tipo:"comparacion",parId:"managed-policy-vs-inline-policy"},{tipo:"escenario",situacion:"Una empresa incorpora a veinte personas al equipo de soporte durante un proyecto de tres meses. Necesitan consultar paneles y reiniciar instancias, pero el equipo de seguridad no quiere repartir credenciales permanentes ni conceder permisos de administrador.",analisis:"El patrón correcto es crear un **grupo** con una política de permisos mínimos (consultar paneles y reiniciar, nada más) y añadir temporalmente a quienes lo necesiten. Para accesos desde aplicaciones o entre cuentas se usa un **rol**, que entrega credenciales temporales. Así se aplica el **principio de menor privilegio** sin credenciales de larga duración que haya que revocar después.",servicio:"AWS Identity and Access Management (IAM)"},{tipo:"errorComun",error:"Crear un usuario de IAM para cada integración y adjuntarle la política de administrador «para que funcione a la primera».",correccion:"Las integraciones deben usar roles con permisos mínimos y credenciales temporales, no usuarios con permisos amplios y claves de acceso permanentes. El permiso de administrador solo se concede si es estrictamente imprescindible y de forma temporal."},{tipo:"clave",items:["IAM autentica identidades y autoriza acciones mediante políticas.","Usuario = credenciales propias; grupo = permisos compartidos; rol = credenciales temporales sin secretos permanentes.","Managed policies se reutilizan; custom policies se escriben a medida; inline policies viven en una sola identidad.","Agrupar identidades y adjuntar el permiso mínimo evita repetir permisos y reduce el riesgo."]}],preguntasGuia:["¿Qué diferencia hay entre un usuario, un grupo y un rol de IAM?","¿Cuándo conviene una managed policy y cuándo una custom policy?","¿Cómo se aplica el principio de menor privilegio al crear identidades?"]},{id:"2.3-g2",titulo:"Protección del root user y principio de menor privilegio",objetivos:["2.3#2","2.3#3","2.3#8","2.3#9"],bloques:[{tipo:"concepto",md:"La cuenta de AWS nace con una identidad especial, el **root user**, creada con el correo y la contraseña de la cuenta. Ese usuario tiene **acceso completo** a todos los recursos y servicios y sus permisos no se pueden limitar con políticas de IAM (solo las políticas de control de servicios de AWS Organizations pueden restringir sus acciones), de modo que comprometerlo compromete la cuenta entera. Por eso se protege con MFA, no se le crean claves de acceso y no se usa para el trabajo diario.\n\nEl **principio de menor privilegio** consiste en conceder a cada identidad solo los permisos que necesita, sobre los recursos que necesita y durante el tiempo necesario. Se aplica con políticas específicas, grupos con permisos mínimos, roles con credenciales temporales y una revisión periódica que retira los permisos sobrantes. Un permiso de administrador permanente «por comodidad» es la negación del principio."},{tipo:"comparacion",parId:"root-user-vs-identidad-administrativa-iam"},{tipo:"escenario",situacion:"Una auditoría detecta que el equipo usa el root user para crear recursos todos los días y que tiene una clave de acceso guardada en un archivo compartido. El equipo de seguridad debe corregir la situación sin bloquear la operación.",analisis:"Primero se activa **MFA** en el root user y se eliminan sus claves de acceso; después se crea una identidad administrativa de IAM (o se usa **AWS IAM Identity Center**) para el trabajo diario, con permisos mínimos y MFA. El root user queda reservado para las tareas que solo él puede realizar y su actividad se vigila con el registro de auditoría.",servicio:"AWS Identity and Access Management (IAM)"},{tipo:"errorComun",error:"Usar el root user para las tareas diarias o crearle claves de acceso para automatizaciones, porque «es más rápido».",correccion:"El root user no se usa en el día a día: se protege con MFA, se le retiran las claves de acceso y las tareas cotidianas se hacen con una identidad administrativa de IAM o con IAM Identity Center. Debe quedar reservado para lo que solo él puede hacer."},{tipo:"clave",items:["El root user tiene acceso total y no se le pueden denegar permisos con políticas de IAM (solo las SCP de AWS Organizations pueden restringirlo).","Protección del root user: MFA activado, sin claves de acceso y sin uso diario.","Solo el root user puede, por ejemplo, cambiar el plan de soporte o cerrar la cuenta.","Menor privilegio = permisos mínimos, sobre recursos concretos y durante el tiempo necesario."]}],preguntasGuia:["¿Por qué el root user no se puede limitar con políticas de IAM?","¿Qué tareas quedan reservadas al root user?","¿Qué medidas concretas protegen la cuenta raíz?","¿Cómo se aplica el principio de menor privilegio en la práctica?"]},{id:"2.3-g3",titulo:"Claves de acceso, contraseñas y almacenamiento de credenciales",objetivos:["2.3#5","2.3#6"],bloques:[{tipo:"concepto",md:"Las **claves de acceso** (access keys) son credenciales de larga duración para llamadas programáticas: un **access key ID** y un **secret access key**. No sirven para iniciar sesión en la consola y, si se filtran, cualquiera puede actuar con los permisos de su propietario; por eso no se escriben en el código ni en archivos de texto, se rotan y se guardan en un almacén gestionado como **AWS Secrets Manager** o el **Parameter Store de AWS Systems Manager**.\n\nLas **password policies** definen los requisitos de las contraseñas de las personas (longitud mínima, mayúsculas, números, símbolos, caducidad y reutilización). El **MFA** añade un factor adicional al inicio de sesión y protege aunque la contraseña se filtre. La clave de acceso y el MFA no compiten: uno autentica programas, el otro refuerza el acceso humano."},{tipo:"comparacion",parId:"claves-de-acceso-vs-mfa"},{tipo:"cuandoUsar",usar:["Usa un almacén de secretos gestionado para las claves y contraseñas de las aplicaciones, en lugar de dejarlas en el código o en archivos de configuración.","Exige una password policy estricta y MFA a las personas, sobre todo a las identidades administrativas y al root user.","Rota las claves de acceso periódicamente y retíralas cuando ya no sean necesarias."],noUsar:["No incrustes claves de acceso en repositorios, imágenes o el user data de una instancia.","No repartas una misma credencial entre varias personas ni sustituyas el MFA por una contraseña más larga."]},{tipo:"errorComun",error:"Guardar la clave de acceso en el código fuente o en un archivo dentro del repositorio y considerarlo aceptable porque el repositorio es privado.",correccion:"Los secretos no viven en el código. Se guardan en AWS Secrets Manager o en el Parameter Store de AWS Systems Manager, se accede a ellos mediante permisos mínimos y se rotan; el código solo contiene una referencia al secreto, nunca el valor."}],preguntasGuia:["¿En qué se diferencia una clave de acceso de un factor MFA?","¿Dónde deben guardarse los secretos de una aplicación?","¿Qué controla una password policy?"]},{id:"2.3-g4",titulo:"IAM Identity Center y gestión de identidades federadas",objetivos:["2.3#4","2.3#10"],bloques:[{tipo:"concepto",md:"**AWS IAM Identity Center** centraliza el acceso de la plantilla a varias cuentas de AWS. Conecta el directorio corporativo o un proveedor de identidad externo, aplica **inicio de sesión único** y asigna **permission sets** a grupos de personas por cada cuenta, en lugar de crear un usuario de IAM por persona y por cuenta.\n\nLa **identidad federada** delega la autenticación en un proveedor de identidad externo: la persona se valida en su directorio corporativo y recibe **credenciales temporales** para la cuenta que le corresponde. Es la forma habitual de gestionar el personal y se apoya en estándares como SAML 2.0 u OIDC. Para las aplicaciones dirigidas a clientes existe **Amazon Cognito**, que gestiona el registro, el inicio de sesión y la federación con identidades sociales."},{tipo:"cuandoUsar",usar:["Usa IAM Identity Center cuando muchas personas necesiten acceder a varias cuentas de AWS con su identidad corporativa y permisos por función.","Elige la identidad federada cuando ya exista un directorio o proveedor de identidad que deba seguir siendo la fuente autorizada.","Emplea Amazon Cognito cuando la autenticación corresponda a los clientes finales de una aplicación."],noUsar:["No crees un usuario de IAM por persona y por cuenta cuando existe un directorio corporativo que puede federarse.","No uses identidades federadas para dar permisos permanentes: la federación entrega credenciales temporales ligadas a la sesión."]},{tipo:"ejemplo",md:"```text\nEscenario                            -> mecanismo\n- Plantilla con directorio corporativo -> identidad federada + IAM Identity Center\n- Muchas cuentas, permisos por rol     -> permission sets asignados a grupos\n- Aplicación que consume AWS           -> rol de IAM con credenciales temporales\n- Clientes finales de una app           -> Amazon Cognito\n```"},{tipo:"escenario",situacion:"Una empresa tiene a sus empleados en un proveedor de identidad corporativo y quiere que accedan a varias cuentas de AWS sin crear un usuario de IAM por persona y por cuenta, además de retirar el acceso de inmediato cuando alguien deja la compañía.",analisis:"Con **AWS IAM Identity Center** se conecta el directorio una sola vez, se agrupan las personas y se asignan **permission sets** por cuenta. La autenticación es **federada**: el usuario se valida en el proveedor de identidad y recibe credenciales temporales para las cuentas que le corresponden. Al desactivar la cuenta en el directorio, el acceso desaparece sin borrar usuarios uno a uno.",servicio:"AWS IAM Identity Center"}],preguntasGuia:["¿Qué resuelve AWS IAM Identity Center frente a crear usuarios de IAM?","¿Qué significa que la identidad sea federada?","¿Cuándo se usa Amazon Cognito en lugar de IAM Identity Center?"]}],2.4:[{id:"2.4-g1",titulo:"Capacidades de seguridad que ofrece AWS",objetivos:["2.4#1"],bloques:[{tipo:"concepto",md:"AWS no entrega una sola herramienta de seguridad, sino un conjunto de **capacidades** repartidas por dominios, apoyadas en el **modelo de responsabilidad compartida**: AWS protege la infraestructura que sostiene los servicios y el cliente protege lo que configura encima.\n\n- **Identidad y acceso**: controlan quién puede hacer qué (por ejemplo, AWS Identity and Access Management (IAM) y AWS IAM Identity Center).\n- **Protección de la red y de las aplicaciones**: filtran tráfico y detienen ataques (por ejemplo, AWS WAF, AWS Shield y AWS Firewall Manager).\n- **Detección**: vigilan la actividad y buscan amenazas o vulnerabilidades (por ejemplo, Amazon GuardDuty, Amazon Inspector y AWS Security Hub).\n- **Protección de datos**: cifrado y gestión de secretos (por ejemplo, AWS Key Management Service (AWS KMS) y AWS Secrets Manager).\n- **Visibilidad y auditoría**: registran y consultan la actividad (por ejemplo, AWS CloudTrail, Amazon CloudWatch y AWS Config).\n- **Cumplimiento**: evidencias y documentación regulatoria (por ejemplo, AWS Artifact).\n\nLa idea de examen es que estas capacidades son **complementarias**: ninguna cubre todo, y se combinan según lo que se quiera proteger o detectar."},{tipo:"ejemplo",md:"```text\nNecesidad                           -> capacidad de AWS\nQuién entra y qué puede hacer        -> identidad y acceso\nFiltrar peticiones web maliciosas    -> protección de aplicaciones\nDetectar comportamiento sospechoso   -> detección\nCifrar datos y guardar secretos       -> protección de datos\nSaber quién hizo qué y cuándo         -> visibilidad y auditoría\nDemostrar cumplimiento normativo      -> cumplimiento\n```"},{tipo:"clave",items:["Las capacidades de seguridad de AWS se agrupan en identidad y acceso, protección, detección, protección de datos, visibilidad y cumplimiento.","Ninguna capacidad cubre todo por sí sola: se combinan según el riesgo que se quiera reducir.","AWS protege la infraestructura; el cliente configura y usa estas capacidades sobre su parte del modelo de responsabilidad compartida."]},{tipo:"errorComun",error:"Creer que AWS ofrece un único servicio de seguridad que cubre a la vez identidad, red, datos y cumplimiento, y que basta con activarlo.",correccion:"Las capacidades de seguridad de AWS son complementarias y se reparten por dominios: identidad y acceso, protección, detección, protección de datos, visibilidad y cumplimiento. Ninguna cubre todo por sí sola y el cliente las habilita y configura según el riesgo que quiera reducir."}],preguntasGuia:["¿En qué dominios se agrupan las capacidades de seguridad de AWS?","¿Qué capacidad usarías para saber quién accedió a un recurso y cuándo?","¿Por qué ninguna capacidad de seguridad cubre por sí sola todas las necesidades?"]},{id:"2.4-g2",titulo:"Servicios de seguridad: WAF, Shield, Firewall Manager, GuardDuty, Inspector y Security Hub",objetivos:["2.4#3"],bloques:[{tipo:"concepto",md:"AWS ofrece varios servicios de seguridad que se confunden con facilidad porque sus nombres se parecen, aunque cada uno mira algo distinto:\n\n- **AWS WAF**: firewall de aplicaciones web. Inspecciona las peticiones HTTP(S) y bloquea patrones maliciosos con reglas, por ejemplo inyección SQL o cross-site scripting.\n- **AWS Shield**: protección gestionada frente a ataques de denegación de servicio distribuido (DDoS), que buscan tumbar el servicio por volumen de tráfico.\n- **AWS Firewall Manager**: administración central de reglas y políticas de protección en varias cuentas de una organización.\n- **Amazon GuardDuty**: detección de amenazas. Analiza señales del entorno (flujos de red, DNS y eventos de auditoría) y avisa de actividad sospechosa.\n- **Amazon Inspector**: evaluación de vulnerabilidades y exposición de las cargas de trabajo; busca fallos conocidos y configuraciones inseguras.\n- **AWS Security Hub**: agrega y prioriza los hallazgos de otros servicios de seguridad en una vista única.\n- **Amazon Macie**: descubre y clasifica datos sensibles, por ejemplo en Amazon S3.\n- **Amazon Detective**: investiga la causa de un hallazgo analizando relaciones entre recursos y actividad.\n\nLa forma de no confundirlos es preguntar **qué protege cada uno**: WAF protege aplicaciones web, Shield absorbe ataques de volumen, Firewall Manager centraliza reglas, GuardDuty detecta amenazas, Inspector encuentra vulnerabilidades y Security Hub reúne los hallazgos."},{tipo:"comparacion",parId:"waf-vs-shield"},{tipo:"comparacion",parId:"guardduty-vs-inspector-vs-security-hub"},{tipo:"escenario",situacion:"Una empresa publica un portal web con formularios y observa intentos de inyección de código en las peticiones, además de un pico de tráfico anómalo destinado a saturar el sitio. El equipo quiere filtrar el contenido malicioso de cada petición sin reescribir la aplicación.",analisis:"El filtrado de peticiones HTTP(S) maliciosas corresponde a **AWS WAF**, que se asocia a la distribución o al balanceador y bloquea las peticiones que coinciden con reglas. La absorción del tráfico de saturación corresponde a **AWS Shield**. Son capas distintas: WAF inspecciona el contenido de la petición; Shield protege frente al volumen del ataque.",servicio:"AWS WAF"},{tipo:"cuandoUsar",usar:["Usa AWS WAF cuando el requisito sea inspeccionar y bloquear el contenido de peticiones HTTP(S), no el volumen de tráfico.","Usa AWS Shield cuando el requisito sea mitigar un ataque de denegación de servicio distribuido que busca saturar el servicio.","Usa Amazon Inspector cuando el requisito sea conocer vulnerabilidades y exposición de las cargas de trabajo.","Usa Amazon GuardDuty cuando el requisito sea detectar actividad maliciosa o sospechosa en la cuenta.","Usa AWS Security Hub cuando el requisito sea reunir y priorizar hallazgos de varias fuentes en un solo lugar.","Usa Amazon Macie para descubrir datos sensibles y Amazon Detective para investigar la causa de un hallazgo."],noUsar:["No elijas Amazon GuardDuty para saber si una instancia tiene software desactualizado: eso es Inspector.","No elijas Amazon Inspector ni AWS Security Hub para absorber un ataque de volumen: eso es Shield.","No elijas AWS WAF para bloquear tráfico de red no HTTP (por ejemplo otro puerto): WAF trabaja sobre peticiones web.","No elijas AWS Firewall Manager como protección por sí sola: centraliza políticas, no sustituye al servicio que las aplica.","No elijas Amazon Macie para detectar amenazas activas ni Amazon Detective para configurar reglas: cada uno responde a una pregunta distinta."]},{tipo:"errorComun",error:"Creer que Amazon GuardDuty, Amazon Inspector y AWS Security Hub son la misma clase de herramienta y que cualquiera de ellos basta para cubrir todas las necesidades de seguridad.",correccion:"Cubren etapas distintas: GuardDuty detecta amenazas sobre la actividad, Inspector evalúa vulnerabilidades y exposición, y Security Hub agrega y prioriza hallazgos. Se usan juntos, no como sustitutos."},{tipo:"clave",items:["AWS WAF filtra peticiones HTTP(S) por su contenido; AWS Shield mitiga ataques DDoS por su volumen.","AWS Firewall Manager administra reglas y políticas de protección en varias cuentas de una organización.","Amazon GuardDuty detecta amenazas; Amazon Inspector evalúa vulnerabilidades; AWS Security Hub agrega y prioriza hallazgos.","Amazon Macie clasifica datos sensibles y Amazon Detective investiga la causa de un hallazgo."]}],preguntasGuia:["¿Qué protege cada uno de los servicios de seguridad WAF, Shield, Firewall Manager, GuardDuty, Inspector y Security Hub?","¿Qué diferencia hay entre detener un ataque de volumen y filtrar el contenido de una petición?","¿En qué se parecen GuardDuty, Inspector y Security Hub y en qué se diferencian?"]},{id:"2.4-g3",titulo:"Documentación y recursos de seguridad de AWS",objetivos:["2.4#2","2.4#5"],bloques:[{tipo:"concepto",md:"Cuando se necesita información oficial de seguridad, AWS publica varios recursos con propósitos distintos:\n\n- **AWS Security Center**: punto de entrada que reúne información de seguridad, cumplimiento y protección de AWS.\n- **AWS Security Blog**: artículos y anuncios sobre prácticas, servicios y novedades de seguridad.\n- **AWS Knowledge Center**: respuestas breves y prácticas a preguntas frecuentes y problemas concretos.\n- **AWS Artifact**: portal de auto-servicio donde se descargan informes de cumplimiento y acuerdos de AWS.\n- **Documentación técnica**: referencia de cada servicio y guías de prácticas recomendadas.\n- **Comunidad**: foros oficiales donde otros clientes y especialistas responden dudas.\n\nLa elección depende de la pregunta: para una duda puntual de configuración, respuestas y foros; para entender una novedad, el blog; para evidencia de cumplimiento, los informes; para el detalle formal de una API, la documentación del servicio."},{tipo:"escenario",situacion:"Un auditor externo pide a una empresa las certificaciones y los informes de cumplimiento vigentes de AWS para su revisión anual, y por separado un ingeniero necesita entender por qué una comprobación de seguridad de la consola no aplica a su caso.",analisis:"La evidencia formal de cumplimiento se descarga desde **AWS Artifact**, el portal de auto-servicio de informes y acuerdos. La duda puntual de configuración se resuelve con respuestas breves y comunidad, típicamente en **AWS Knowledge Center** y en los foros; para entender una novedad o el criterio general se consulta **AWS Security Blog** y **AWS Security Center**."},{tipo:"errorComun",error:"Buscar información de seguridad en blogs y foros de terceros antes que en los recursos oficiales, o confundir el material de respuestas puntuales de AWS Knowledge Center con los informes de cumplimiento de AWS Artifact.",correccion:"Empieza por los recursos oficiales: AWS Security Center y la documentación del servicio para información general, AWS Knowledge Center para dudas puntuales, AWS Security Blog para novedades y AWS Artifact para informes de cumplimiento."},{tipo:"clave",items:["AWS Security Center reúne la información de seguridad y cumplimiento de AWS.","AWS Security Blog publica artículos y novedades; AWS Knowledge Center responde dudas puntuales.","AWS Artifact entrega informes de cumplimiento y acuerdos, que son la evidencia documental."]}],preguntasGuia:["¿Qué recurso de AWS usarías para descargar un informe de cumplimiento?","¿En qué se diferencian AWS Security Blog, AWS Knowledge Center y AWS Artifact?","¿Por qué conviene consultar primero los recursos oficiales de seguridad?"]},{id:"2.4-g4",titulo:"Detección de problemas y productos de seguridad de terceros",objetivos:["2.4#4","2.4#6"],bloques:[{tipo:"concepto",md:"Existen dos vías complementarias para mejorar la postura de seguridad sin construir todo desde cero:\n\n- **AWS Trusted Advisor**: revisa el entorno y entrega comprobaciones y recomendaciones en categorías como seguridad, rendimiento, tolerancia a fallos, optimización de costes y cuotas de servicio. Sus comprobaciones de seguridad señalan configuraciones de riesgo, por ejemplo accesos demasiado abiertos.\n- **AWS Marketplace**: catálogo donde proveedores independientes publican productos y servicios, incluidos **productos de seguridad de terceros**. Permite suscribirse a software de firewall, antivirus, gestión de vulnerabilidades o SIEM sin desarrollarlo a medida.\n\nLa diferencia práctica: Trusted Advisor mira la configuración de tu propia cuenta y recomienda mejoras; AWS Marketplace amplía tus opciones con software de otros fabricantes que se integra con AWS."},{tipo:"cuandoUsar",usar:["Usa AWS Trusted Advisor para una revisión automatizada del entorno y para localizar configuraciones de seguridad de riesgo antes de una auditoría.","Usa AWS Marketplace cuando necesites una capacidad de seguridad muy concreta que prefieras adquirir a un proveedor independiente en lugar de construirla.","Ten en cuenta el nivel de AWS Support contratado: algunas comprobaciones y funcionalidades se comportan distinto según el plan."],noUsar:["No esperes que AWS Trusted Advisor corrija los hallazgos por ti: señala y recomienda, la corrección la aplica el cliente.","No asumas que todo producto de AWS Marketplace lo opera AWS: son productos de terceros con su propio proveedor."]},{tipo:"errorComun",error:"Pensar que AWS Marketplace es una tienda gestionada por AWS donde todo producto lo soporta AWS, o que AWS Trusted Advisor ejecuta las correcciones por el cliente.",correccion:"AWS Marketplace es un catálogo de productos de terceros (proveedores independientes) que el cliente suscribe y opera; AWS Trusted Advisor solo entrega comprobaciones y recomendaciones, y la corrección corre por cuenta del cliente."},{tipo:"clave",items:["AWS Trusted Advisor entrega comprobaciones y recomendaciones, no correcciones automáticas.","Las comprobaciones de Trusted Advisor cubren seguridad, rendimiento, tolerancia a fallos, optimización de costes y cuotas de servicio.","AWS Marketplace ofrece productos de seguridad de terceros que se adquieren como suscripciones."]}],preguntasGuia:["¿Qué tipo de comprobaciones ofrece AWS Trusted Advisor y quién aplica la corrección?","¿Dónde se adquieren productos de seguridad de terceros y quién los soporta?","¿Qué diferencia hay entre revisar tu propia configuración y ampliar tus opciones con software de terceros?"]}],3.1:[{id:"3.1-g1",titulo:"Aprovisionar y operar: operaciones puntuales frente a procesos repetibles",objetivos:["3.1#1","3.1#5"],bloques:[{tipo:"concepto",md:"Aprovisionar es crear y configurar recursos; operar es mantenerlos, ajustarlos y responder a los cambios. En la nube de AWS ambas cosas admiten varios niveles de automatización:\n\n- **Acceso manual**: una persona crea los recursos desde la consola de administración, uno a uno, guiada por formularios. Es cómodo para explorar y para tareas puntuales, pero no deja un rastro reproducible.\n- **Acceso programático**: la interfaz de línea de comandos (CLI), los SDK y las API permiten ejecutar las mismas acciones desde scripts y herramientas, lo que habilita la automatización.\n- **Infraestructura como código (IaC)**: la infraestructura se describe en archivos versionados que se despliegan de forma repetible. La definición pasa a ser la fuente de verdad del entorno.\n- **Servicios gestionados de plataforma**: AWS Elastic Beanstalk aprovisiona y opera la infraestructura por el usuario a partir del código de la aplicación.\n\nEl segundo eje de decisión es temporal: una **operación puntual** resuelve una necesidad concreta y no se vuelve a ejecutar; un **proceso repetible** se define una vez y se replica cuantas veces haga falta. Cuanto más frecuente sea la tarea, más entornos implique y más personas dependan de ella, más conviene automatizarla."},{tipo:"comparacion",parId:"una-vez-vs-repetible"},{tipo:"cuandoUsar",usar:["Usa operaciones puntuales para explorar un servicio, validar una idea o resolver una necesidad irrepetible.","Usa procesos repetibles cuando el mismo despliegue deba reproducirse en varios entornos o con frecuencia (por ejemplo, desarrollo, pruebas y producción).","Automatiza con IaC en cuanto el entorno tenga que ser auditable y reconstruible."],noUsar:["No documentes un despliegue recurrente solo con pasos manuales: se vuelve lento y propenso a errores.","No automatices un cambio de una sola vez si el coste de definir el proceso supera el beneficio esperado."]},{tipo:"ejemplo",md:"```text\nNecesidad                              -> Enfoque\n- Probar un servicio por primera vez   -> Operación puntual en la consola\n- Repetir el mismo entorno cada semana -> Proceso repetible con IaC\n- Consultar recursos desde el terminal -> Comando puntual de la CLI\n- Reconstruir producción tras un fallo -> Proceso repetible versionado\n```"},{tipo:"errorComun",error:"Creer que automatizar es siempre la respuesta y que hacer una operación puntual a mano es «hacerlo mal».",correccion:"La elección depende de la frecuencia y de la necesidad de reproducibilidad. Una exploración o un ajuste único puede hacerse a mano; lo que no debe hacerse a mano es un despliegue que se repite, porque acumula errores y no deja rastro."},{tipo:"clave",items:["Aprovisionar crea recursos; operar los mantiene y los ajusta.","Las vías de trabajo son la consola, la CLI, los SDK, las API y la infraestructura como código.","Operación puntual = una vez; proceso repetible = definido una vez y reejecutable.","La frecuencia, el número de entornos y la necesidad de auditoría deciden entre manual y automatizado."]}],preguntasGuia:["¿Qué diferencia hay entre aprovisionar y operar?","¿Cuándo basta una operación puntual y cuándo conviene un proceso repetible?","¿Qué gana un equipo al describir su infraestructura como código?"]},{id:"3.1-g2",titulo:"Formas de acceder a los servicios de AWS",objetivos:["3.1#2","3.1#4"],bloques:[{tipo:"concepto",md:"Existen varias formas de acceder a los servicios de AWS y cada una encaja en un momento distinto:\n\n- **Consola de administración**: interfaz web gráfica, ideal para explorar, aprender y hacer tareas puntuales. No está pensada para repetir cientos de operaciones ni para dejar una definición versionada.\n- **Interfaz de línea de comandos (CLI)**: ejecuta acciones desde la terminal y permite encadenarlas en scripts. Es programática y adecuada para tareas repetitivas sencillas y para administración desde el equipo local.\n- **SDK**: bibliotecas que integran las llamadas a la API en el lenguaje de la aplicación, de modo que el propio programa cree y gestione recursos.\n- **API**: la interfaz base sobre la que se apoyan la consola, la CLI y los SDK; permite integraciones a medida.\n- **Infraestructura como código (IaC)**: describe el estado deseado de la infraestructura en archivos versionados (por ejemplo, con AWS CloudFormation) y lo despliega de forma repetible.\n\nNo son excluyentes: la consola sirve para entender, la CLI y los SDK para automatizar desde el código y la IaC para que el entorno sea reproducible y auditable."},{tipo:"comparacion",parId:"iac-vs-consola-vs-cli"},{tipo:"ejemplo",md:"```text\nSituación                                -> Acceso recomendado\n- Aprender cómo funciona un servicio      -> Consola de administración\n- Tarea repetitiva desde la terminal      -> CLI con un script\n- La aplicación crea recursos al arrancar -> SDK\n- Reproducir un entorno entero igual      -> Infraestructura como código\n- Integración a medida entre sistemas     -> API\n```"},{tipo:"errorComun",error:"Pensar que la consola es la única forma de trabajar con AWS o que la CLI y la infraestructura como código son lo mismo.",correccion:"La consola es solo una de las vías. La CLI ejecuta comandos, pero quien los escribe sigue siendo la persona; la infraestructura como código describe el estado deseado en archivos versionados. La CLI puede lanzar un despliegue, pero la IaC es la que define y reproduce el entorno."},{tipo:"clave",items:["Formas de acceso: consola, CLI, SDK, API e infraestructura como código.","La consola es visual y puntual; la CLI y los SDK son programáticos.","La IaC describe el estado deseado en archivos versionados y es reproducible.","La elección depende de quién ejecuta la tarea, de si se repite y de si debe quedar auditada."]}],preguntasGuia:["¿Qué diferencias hay entre la consola, la CLI, los SDK y la IaC?","¿Cuándo conviene usar la consola y cuándo la infraestructura como código?","¿Qué aporta versionar la definición de la infraestructura?"]},{id:"3.1-g3",titulo:"Modelos de despliegue: nube, híbrido y on-premises",objetivos:["3.1#3","3.1#6"],bloques:[{tipo:"concepto",md:"El modelo de despliegue describe dónde se ejecuta la carga de trabajo y de quién es la infraestructura:\n\n- **Cloud (nube)**: los recursos se ejecutan en la nube de AWS, que aporta elasticidad, alcance global y pago por uso. El cliente no compra servidores.\n- **On-premises**: todo se ejecuta en instalaciones propias. Da control total sobre el hardware y los datos, pero exige comprar capacidad por adelantado y mantenerla.\n- **Híbrido**: combina ambos mundos. Parte del entorno permanece en las instalaciones por normativa, latencia o inversión ya realizada, y otra parte usa la nube de AWS.\n\nEl modelo no es solo una decisión técnica: suele venir impuesto por requisitos de cumplimiento, por la inversión existente o por la necesidad de escalar sin comprar hardware."},{tipo:"escenario",situacion:"Una empresa mantiene un sistema antiguo que debe seguir ejecutándose en su centro de datos por requisitos normativos, pero quiere llevar el análisis de datos y las aplicaciones nuevas a la nube de AWS.",analisis:"Es un caso claro de modelo híbrido: lo que no puede salir se queda en las instalaciones y lo nuevo se despliega en la nube. La conectividad entre ambos mundos se resuelve con un enlace dedicado que evita depender de internet público (por ejemplo, AWS Direct Connect).",servicio:"AWS Direct Connect"},{tipo:"cuandoUsar",usar:["Elige cloud cuando no tengas ataduras de hardware y quieras elasticidad, alcance global y pago por uso.","Elige híbrido cuando parte del entorno deba permanecer en las instalaciones por normativa, latencia o inversión existente.","Elige on-premises cuando el control físico, el cumplimiento o una inversión ya amortizada lo exijan."],noUsar:["No elijas híbrido por inercia: añade complejidad de red, identidad y operación entre dos entornos.","No asumas que la nube elimina toda responsabilidad: el cliente sigue siendo responsable de la seguridad de lo que despliega."]},{tipo:"errorComun",error:"Confundir «híbrido» con «multinube» y creer que un modelo híbrido significa usar varios proveedores de nube a la vez.",correccion:"Híbrido combina instalaciones propias con la nube. Usar varios proveedores de nube es otra cosa (multinube) y no es lo mismo que el modelo híbrido de despliegue."},{tipo:"clave",items:["Cloud: todo se ejecuta en la nube de AWS.","On-premises: todo se ejecuta en instalaciones propias.","Híbrido: parte en instalaciones propias y parte en la nube de AWS.","El modelo lo determinan el cumplimiento, la inversión existente y los requisitos de latencia o escala."]}],preguntasGuia:["¿Qué tres modelos de despliegue existen y en qué se diferencian?","¿Qué situaciones empujan a un modelo híbrido?","¿Qué implicaciones de coste y de control tiene quedarse on-premises?"]}],3.2:[{id:"3.2-g1",titulo:"Regiones, Availability Zones y edge locations",objetivos:["3.2#1","3.2#5"],bloques:[{tipo:"concepto",md:"La infraestructura global de AWS se organiza en capas anidadas:\n\n- **Región**: área geográfica independiente (por ejemplo, `eu-west-1`). Cada región es un despliegue separado con sus propios servicios y su propio aislamiento frente al resto.\n- **Availability Zone (AZ)**: uno o varios centros de datos aislados dentro de una región, conectados entre sí por red de baja latencia. Una región tiene al menos tres AZ en la mayoría de los casos.\n- **Edge location**: punto de presencia cercano al usuario final que usan servicios de entrega de contenido y DNS para acercar la respuesta.\n\nLa relación es de continente a edificio a punto de proximidad: la **región** agrupa AZ, y las **edge locations** están fuera de ese eje, repartidas por muchas ciudades para reducir la distancia hasta el usuario. Un recurso se despliega en una región concreta; las AZ de esa región dan tolerancia a fallos; las edge locations aceleran la entrega global."},{tipo:"comparacion",parId:"regiones-vs-az-vs-edge"},{tipo:"escenario",situacion:"Una empresa europea sirve una aplicación web a clientes de Europa, América y Asia. Necesita baja latencia de descarga, pero también cumplir que los datos personales de sus clientes europeos permanezcan almacenados en Europa.",analisis:"Los **datos** se alojan en una región europea para respetar la residencia de datos; las **edge locations** distribuyen el contenido estático cerca de cada usuario sin mover los datos de origen. Es el patrón habitual: región para el dato y el cómputo, edge para la entrega.",servicio:"Amazon CloudFront"},{tipo:"errorComun",error:"Pensar que una edge location es una región más pequeña o que se puede crear una instancia de cómputo general en ella.",correccion:"Las edge locations no alojan los servicios generales: son puntos de presencia para entrega de contenido y resolución DNS. Para cómputo y datos se despliega en una región, repartiendo entre sus AZ."},{tipo:"clave",items:["Región = área geográfica con varios centros de datos aislados (AZ).","AZ = centro de datos aislado dentro de la región, con red de baja latencia entre AZ.","Edge location = punto de presencia cercano al usuario para entrega de contenido y DNS.","La relación geográfica es: región ⊃ Availability Zones; edge locations, fuera de ese eje."]}],preguntasGuia:["¿Cuál es la relación entre una región y sus Availability Zones?","¿Para qué sirve una edge location y en qué se diferencia de una AZ?","¿Qué se despliega en una región y qué se sirve desde el edge?"]},{id:"3.2-g2",titulo:"Alta disponibilidad con varias Availability Zones",objetivos:["3.2#2","3.2#6","3.2#7"],bloques:[{tipo:"concepto",md:"La **alta disponibilidad** es la capacidad de seguir atendiendo el servicio aunque falle un componente. AWS la consigue repartiendo la carga entre **varias Availability Zones** de una misma región: si una AZ se cae, las otras siguen respondiendo.\n\nLa clave está en el aislamiento: cada AZ tiene su propia alimentación, refrigeración y red, y **no comparten un punto único de fallo**. Un error de configuración o un fallo físico en una AZ no se propaga automáticamente a la otra. Para aprovecharlo hay que **desplegar réplicas** en más de una AZ y distribuir el tráfico entre ellas; tener todo en una sola AZ no aporta ninguna tolerancia."},{tipo:"ejemplo",md:"```text\nBase de datos en una sola AZ:\n  falla la AZ -> la base de datos no está disponible\n\nBase de datos con instancia en espera en otra AZ:\n  falla la AZ -> conmutación (failover) a la instancia en espera; sigue el servicio\n\nBalanceador de carga delante:\n  reparte el tráfico entre instancias de varias AZ\n```"},{tipo:"errorComun",error:"Confundir alta disponibilidad con copia de seguridad y creer que tener un snapshot basta para seguir operando si se cae una AZ.",correccion:"La alta disponibilidad se logra con redundancia activa en varias AZ, no con copias de seguridad. El snapshot sirve para recuperar datos tras una pérdida, no para mantener el servicio en marcha durante un fallo de zona."}],preguntasGuia:["¿Cómo consigue AWS que una AZ no sea punto único de fallo?","¿Basta con desplegar en una AZ para tener alta disponibilidad?","¿Qué diferencia hay entre alta disponibilidad y copia de seguridad?"]},{id:"3.2-g3",titulo:"Cuándo usar varias regiones y para qué sirve el edge",objetivos:["3.2#3","3.2#4","3.2#8"],bloques:[{tipo:"concepto",md:"Usar **varias regiones** va más allá de la alta disponibilidad: añade distancia geográfica. Los motivos oficiales para hacerlo son:\n\n- **Disaster recovery (DR)**: mantener una copia o una capacidad de recuperación en otra región para el caso extremo de pérdida total de una región.\n- **Continuidad de negocio**: seguir operando aunque una región completa quede indisponible durante más tiempo.\n- **Baja latencia para el usuario final**: servir desde la región más cercana a cada audiencia.\n- **Soberanía de los datos**: mantener los datos de un país o zona dentro de sus fronteras.\n\nLas **edge locations** atacan el mismo problema de latencia desde otro ángulo: no replican la aplicación, sino que acercan la entrega de contenido y la resolución DNS. Son complementarias a la elección de región: el dato vive en una región y el edge lo distribuye."},{tipo:"cuandoUsar",usar:["Usa varias regiones cuando necesites DR con independencia geográfica, continuidad de negocio o residencia de datos por país.","Elige la región más cercana a los usuarios para reducir latencia, y apóyate en el edge para la entrega de contenido.","Documenta la estrategia de recuperación: región principal, región de respaldo y qué datos se replican."],noUsar:["No replices en varias regiones «por si acaso»: multiplica coste, complejidad operativa y consistencia de datos.","No esperes que el edge sustituya a una región de DR: el edge no reemplaza el dato ni la lógica de negocio."]},{tipo:"ejemplo",md:"```text\nMotivo -> decisión de diseño\n- Cumplir residencia de datos      -> fijar región por país\n- Sobrevivir a la caída de región  -> réplica en otra región (DR)\n- Descargas rápidas en 3 continentes -> edge locations (entrega)\n- Usuarios solo en un país         -> una región con varias AZ\n```"}],preguntasGuia:["¿Qué cuatros motivos justifican usar varias regiones?","¿En qué se diferencian las edge locations de una región de respaldo?","¿Cuándo basta con una sola región y varias AZ?"]}],3.3:[{id:"3.3-g1",titulo:"Panorama de los servicios de cómputo",objetivos:["3.3#1"],bloques:[{tipo:"concepto",md:"El **cómputo** en AWS es un espectro según cuánto controlas y cuánto gestionas tú:\n\n- **Máquinas virtuales**: servidores completos que aprovisionas y administras, con el máximo control sobre el sistema operativo y el software. El servicio de referencia es Amazon EC2.\n- **Contenedores**: empaquetan la aplicación con sus dependencias para ejecutarse de forma portable; el clúster que los organiza lo aporta Amazon Elastic Container Service (Amazon ECS) o Amazon Elastic Kubernetes Service (Amazon EKS).\n- **Serverless**: no gestionas servidores ni capacidad; AWS Lambda ejecuta funciones por evento y AWS Fargate ejecuta contenedores sin que administres la infraestructura.\n- **Plataformas gestionadas**: AWS Elastic Beanstalk y Amazon Lightsail reducen la operación en escenarios sencillos.\n\nHacia un extremo del espectro hay más control y más responsabilidad operativa; hacia el otro, más gestión por parte de AWS y menos control. Elegir el servicio correcto es ajustar ese equilibrio al requisito del negocio."},{tipo:"servicio",nombre:"Amazon EC2"},{tipo:"servicio",nombre:"AWS Lambda"},{tipo:"servicio",nombre:"AWS Elastic Beanstalk"},{tipo:"cuandoUsar",usar:["Usa máquinas virtuales cuando necesites control del sistema operativo, instalar software específico o procesos de larga duración.","Usa contenedores cuando quieras empaquetar la aplicación con sus dependencias y ejecutarla de forma portable.","Usa cómputo serverless cuando la carga llegue por eventos, sea corta y no necesite conservar estado."],noUsar:["No uses cómputo serverless para procesos continuos, de larga duración o que necesiten conservar estado entre invocaciones.","No elijas máquinas virtuales solo por costumbre si la carga es corta y esporádica: mantener capacidad encendida desperdicia dinero.","No elijas un modelo por su tamaño o novedad: primero identifica el recurso limitante y el patrón de uso."]},{tipo:"errorComun",error:"Elegir el cómputo más potente o más nuevo en lugar de ajustar el modelo al requisito de control y al patrón de uso.",correccion:"El modelo se elige por cuánto control necesitas y cómo llega la carga: máquina virtual para control del sistema operativo y procesos largos, contenedores para empaquetado portable y serverless para eventos cortos y sin estado. Sobredimensionar o forzar serverless en cargas con estado no arregla el problema."},{tipo:"clave",items:["El cómputo en AWS va del control total de la máquina virtual al cómputo serverless sin servidores.","Amazon EC2 entrega instancias; los contenedores se orquestan con Amazon ECS o Amazon EKS; AWS Lambda ejecuta funciones por evento.","AWS Elastic Beanstalk y Amazon Lightsail reducen la administración en escenarios sencillos.","A más control, más responsabilidad operativa; a más gestión de AWS, menos control."]}],preguntasGuia:["¿Qué opciones de cómputo ofrece AWS y en qué se diferencian por nivel de control?","¿Cuándo conviene una máquina virtual y cuándo una función serverless?","¿Qué papel cumplen los contenedores dentro del panorama de cómputo?"]},{id:"3.3-g2",titulo:"Contenedores gestionados: Amazon ECS, Amazon EKS y AWS Fargate",objetivos:["3.3#3"],bloques:[{tipo:"concepto",md:"Los **contenedores** empaquetan la aplicación con sus dependencias y se ejecutan de forma aislada y portable. Para coordinar muchos contenedores hace falta un **orquestador**, y AWS ofrece dos:\n\n- **Amazon ECS**: orquestador propio de AWS, sencillo y muy integrado con el resto del ecosistema. La definición de tareas y servicios es directa.\n- **Amazon EKS**: Kubernetes gestionado. Útil si ya usas Kubernetes en otro sitio o necesitas su portabilidad y su ecosistema.\n\nEl **motor de cómputo** es distinto del orquestador. **AWS Fargate** es un motor serverless: ejecuta los contenedores sin que aprovisiones ni administres instancias, y puede usarse con ECS o con EKS. La alternativa es ejecutar los contenedores en instancias de Amazon EC2 que tú gestionas, con más control pero también más trabajo operativo.\n\nEn resumen: ECS o EKS deciden **dónde y cómo se orquesta**; Fargate decide **en qué se ejecuta**, sin servidores."},{tipo:"comparacion",parId:"ecs-vs-eks-vs-fargate"},{tipo:"escenario",situacion:"Un equipo con perfil de desarrollo migra una API en contenedores. No tiene personal dedicado a administrar sistemas operativos ni a aplicar parches, pero sí conoce Kubernetes y quiere evitar quedar atado a una herramienta propietaria.",analisis:"El equipo necesita un orquestador y, a la vez, no quiere gestionar servidores. Kubernetes gestionado apunta a Amazon Elastic Kubernetes Service (Amazon EKS), y la ejecución sin administrar máquinas encaja con AWS Fargate como motor de cómputo. Si no necesitara Kubernetes, Amazon ECS sería la opción más simple.",servicio:"AWS Fargate"},{tipo:"errorComun",error:"Creer que Amazon ECS y AWS Fargate son alternativas una de la otra.",correccion:"Amazon ECS es el orquestador y AWS Fargate es un motor de cómputo: no compiten, se combinan. Puedes ejecutar tareas de ECS sobre Fargate, o sobre instancias de Amazon EC2 que tú administras."},{tipo:"clave",items:["Amazon ECS es el orquestador propio de AWS; Amazon EKS es Kubernetes gestionado.","AWS Fargate es un motor de cómputo serverless, no un orquestador.","Fargate se combina con ECS o con EKS para ejecutar contenedores sin administrar servidores.","Si ya usas Kubernetes y buscas portabilidad, EKS; si buscas simplicidad en AWS, ECS."]}],preguntasGuia:["¿Qué diferencia hay entre un orquestador de contenedores y un motor de cómputo?","¿Cuándo elegir Amazon ECS y cuándo Amazon EKS?","¿Qué aporta AWS Fargate frente a ejecutar contenedores en instancias que administras?"]},{id:"3.3-g3",titulo:"Cómputo serverless: AWS Lambda y AWS Fargate",objetivos:["3.3#4"],bloques:[{tipo:"concepto",md:"El **cómputo serverless** elimina la administración de servidores: no aprovisionas ni mantienes instancias y pagas por el uso. En el alcance del examen aparecen dos opciones que conviene no confundir:\n\n- **AWS Lambda**: ejecuta **funciones** disparadas por eventos, como una petición HTTP, un objeto nuevo o un mensaje. No hay servidor que gestionar y el servicio escala de forma automática. Está pensado para ejecuciones cortas y sin estado.\n- **AWS Fargate**: ejecuta **contenedores** sin que administres la infraestructura subyacente. Es el motor serverless para cargas que ya están empaquetadas como contenedor.\n\nLa diferencia práctica: Lambda es para código y eventos; Fargate es para contenedores. Ambos comparten la promesa de no ocuparte de servidores, pero no el mismo modelo de empaquetado ni de ejecución."},{tipo:"comparacion",parId:"ec2-vs-lambda"},{tipo:"escenario",situacion:"Una empresa debe procesar imágenes cada vez que se sube un archivo a un almacenamiento de objetos. El tráfico es irregular: hay horas sin subidas y picos de miles de archivos.",analisis:"El patrón es orientado a eventos y de duración corta por archivo. AWS Lambda se activa con cada subida, escala solo cuando hay eventos y no cuesta nada cuando no los hay; administrar servidores para ese tráfico irregular sería caro e innecesario.",servicio:"AWS Lambda"},{tipo:"errorComun",error:"Pensar que AWS Lambda sirve para cualquier carga, incluidas las de ejecución larga o las que necesitan estado en memoria entre invocaciones.",correccion:"Lambda está diseñado para ejecuciones cortas y sin estado. Para procesos largos, con estado o con contenedores ya construidos encajan mejor AWS Fargate o instancias de Amazon EC2."},{tipo:"ejemplo",md:"```text\nDisparador -> opción serverless típica\n- Petición HTTP o evento nuevo -> AWS Lambda (función)\n- Contenedor ya empaquetado    -> AWS Fargate (tarea)\n```"}],preguntasGuia:["¿Qué caracteriza al cómputo serverless?","¿En qué se diferencian AWS Lambda y AWS Fargate?","¿Qué tipo de cargas encajan mejor en cada opción serverless?"]},{id:"3.3-g4",titulo:"Tipos de instancia de Amazon EC2",objetivos:["3.3#2"],bloques:[{tipo:"concepto",md:"No todas las cargas necesitan el mismo tipo de instancia. Amazon EC2 ofrece **familias de instancias** optimizadas para distintos cuellos de botella:\n\n- **General purpose**: equilibrio entre cómputo, memoria y red; punto de partida habitual.\n- **Compute optimized**: prioriza la CPU; procesamiento intensivo, servidores web muy exigentes o procesamiento por lotes.\n- **Memory optimized**: prioriza la memoria RAM; bases de datos en memoria, cachés y análisis en tiempo real.\n- **Storage optimized**: prioriza la entrada/salida de disco y el almacenamiento local; bases de datos con muchas lecturas y escrituras y sistemas de archivos de alto rendimiento.\n- **Accelerated computing**: incorpora aceleradores; entrenamiento e inferencia de aprendizaje automático y procesamiento gráfico.\n\nElegir bien la familia evita pagar recursos que la carga no aprovecha: es la base del *rightsizing*."},{tipo:"cuandoUsar",usar:["Usa compute optimized cuando el cuello de botella es la CPU: procesamiento por lotes, codificación o servidores con mucha carga de cálculo.","Usa storage optimized cuando el cuello de botella es la entrada/salida de disco o necesitas almacenamiento local de alto rendimiento.","Usa memory optimized cuando el conjunto de datos activo vive en memoria, como en cachés o bases de datos en memoria."],noUsar:["No elijas una familia solo por su tamaño: la familia responde al perfil de la carga y el tamaño, al volumen.","No uses accelerated computing si la carga no aprovecha el acelerador: pagarías por capacidad sin uso."]},{tipo:"ejemplo",md:"```text\nCuello de botella -> familia\n- CPU intensiva       -> compute optimized\n- I/O de disco alto   -> storage optimized\n- Datos en memoria    -> memory optimized\n- Carga equilibrada   -> general purpose\n- IA o gráficos       -> accelerated computing\n```"},{tipo:"errorComun",error:"Elegir la instancia más grande o más potente en lugar de la familia adecuada al perfil de la carga.",correccion:"Primero se identifica el recurso limitante (CPU, memoria, disco, red o acelerador) y se elige la familia; después se dimensiona el tamaño. Sobredimensionar no arregla un cuello de botella mal identificado."}],preguntasGuia:["¿Qué familias de instancias ofrece Amazon EC2 y para qué sirve cada una?","¿Cómo se elige la familia de instancia adecuada a una carga?","¿Qué diferencia hay entre familia y tamaño de instancia?"]},{id:"3.3-g5",titulo:"Elasticidad con auto scaling y balanceadores de carga",objetivos:["3.3#5","3.3#6"],bloques:[{tipo:"concepto",md:"La **elasticidad** es la capacidad de ajustar automáticamente los recursos a la demanda. AWS Auto Scaling la implementa observando una métrica y ajustando el número de recursos: cuando la demanda sube añade capacidad, y cuando baja la retira. Así el sistema soporta los picos sin quedar infrautilizado el resto del tiempo, y se paga por lo que se usa.\n\nUn **balanceador de carga** reparte el tráfico entrante entre varios destinos y comprueba su estado. Aporta tres cosas: distribuye la carga, evita depender de un único servidor y retira de la rotación los destinos que no responden. Auto scaling y balanceador se complementan: el balanceador reparte entre los destinos activos y auto scaling decide cuántos hay."},{tipo:"ejemplo",md:"```text\nPico de tráfico   -> auto scaling añade recursos\nValle de tráfico  -> auto scaling retira recursos\nBalanceador       -> reparte el tráfico entre los destinos activos\nDestino que falla -> el balanceador deja de enviarle tráfico\n```"},{tipo:"errorComun",error:"Confundir elasticidad con tener capacidad fija de sobra para el peor caso.",correccion:"La elasticidad ajusta la capacidad a la demanda; la capacidad fija sobredimensionada desperdicia dinero la mayor parte del tiempo. AWS Auto Scaling es el mecanismo que aporta esa elasticidad."},{tipo:"clave",items:["AWS Auto Scaling ajusta el número de recursos según una métrica: añade capacidad en los picos y la retira en los valles.","Elasticidad significa pagar por lo que se usa, no mantener capacidad para el peor caso.","Un balanceador de carga reparte el tráfico entre varios destinos y comprueba su estado.","Balanceador y auto scaling se complementan: uno reparte y el otro decide cuántos destinos existen."]}],preguntasGuia:["¿Qué significa que un sistema sea elástico?","¿Cómo aporta AWS Auto Scaling elasticidad a una aplicación?","¿Qué aporta un balanceador de carga además de repartir el tráfico?"]}],3.4:[{id:"3.4-g1",titulo:"Panorama de los servicios de base de datos de AWS",objetivos:["3.4#1","3.4#3"],bloques:[{tipo:"concepto",md:"Las bases de datos en AWS se eligen por **cómo modelan el dato** y por **quién las administra**:\n\n- **Relacionales**: organizan los datos en tablas con esquema fijo y se consultan con SQL. Aquí están las gestionadas `Amazon RDS` (MySQL, PostgreSQL, MariaDB, Oracle, SQL Server) y `Amazon Aurora`, compatible con MySQL y PostgreSQL y pensada para alto rendimiento.\n- **NoSQL**: no exigen esquema relacional y escalan horizontalmente. `Amazon DynamoDB` es clave-valor y documento; `Amazon DocumentDB` es documental; `Amazon Neptune` es de grafos.\n- **En memoria**: mantienen los datos en RAM para dar latencias muy bajas. `Amazon ElastiCache` es la opción típica como caché delante de otra base.\n- **Analíticas**: `Amazon Redshift` es un almacén de datos columnar orientado a consultas analíticas sobre grandes volúmenes.\n\nEl segundo eje es **quién administra**: una base gestionada deja en manos de AWS parches, copias de seguridad, alta disponibilidad y escalado; una base **alojada en `Amazon EC2`** corre en una instancia que el equipo debe mantener. AWS no obliga a elegir un único motor: lo normal es combinar una base transaccional con una caché en memoria."},{tipo:"comparacion",parId:"base-gestionada-vs-base-en-ec2"},{tipo:"cuandoUsar",usar:["Usa una base gestionada de AWS cuando quieras delegar parches, copias de seguridad, alta disponibilidad y escalado, y centrar el equipo en la aplicación.","Usa una base alojada en `Amazon EC2` cuando necesites un motor o una versión no soportada por el servicio gestionado, control del sistema operativo o requisitos muy concretos de configuración.","Combina una base transaccional con una caché en memoria cuando las lecturas repetidas dominen la latencia."],noUsar:["No elijas `Amazon EC2` solo porque «parece más barato»: sumas el coste de administrar parches, copias de seguridad y alta disponibilidad por tu cuenta.","No uses una base gestionada si tu requisito principal es controlar el sistema operativo y el motor hasta el último detalle.","No uses una caché en memoria como base principal de datos persistentes."]},{tipo:"ejemplo",md:"```text\nNecesidad -> categoría\n- Transacciones con SQL y relaciones      -> relacional (Amazon RDS, Amazon Aurora)\n- Clave-valor con escala masiva            -> NoSQL (Amazon DynamoDB)\n- Lecturas repetidas que deben ir en RAM   -> en memoria (Amazon ElastiCache)\n- Análisis de grandes volúmenes            -> almacén columnar (Amazon Redshift)\n- Motor o versión que AWS no gestiona      -> base en Amazon EC2\n```"},{tipo:"errorComun",error:"Creer que «gestionado» significa que AWS también administra los datos y las consultas, o que una base en `Amazon EC2` es siempre la opción más barata.",correccion:"El servicio gestionado administra la **infraestructura** de la base (parches, copias, alta disponibilidad, escalado), no el modelo de datos ni las consultas, que siguen siendo responsabilidad del cliente. Y una base en `Amazon EC2` traslada al equipo toda la operación, lo que suele encarecerla en tiempo y en riesgo, no solo en factura."}],preguntasGuia:["¿Qué categorías de base de datos ofrece AWS y qué ejemplo hay de cada una?","¿Qué administra AWS en una base gestionada y qué queda en manos del cliente?","¿Cuándo tiene sentido alojar la base en Amazon EC2 en lugar de usar un servicio gestionado?"]},{id:"3.4-g2",titulo:"Bases de datos relacionales: Amazon RDS y Amazon Aurora",objetivos:["3.4#3","3.4#4"],bloques:[{tipo:"concepto",md:"El modelo **relacional** guarda los datos en tablas con filas y columnas, con un esquema definido y consultas SQL. Las dos opciones gestionadas del alcance son:\n\n- **`Amazon RDS`**: servicio gestionado que ejecuta motores conocidos (MySQL, PostgreSQL, MariaDB, Oracle y SQL Server) sin que el equipo administre el sistema operativo. Cubre copias de seguridad automáticas, parches y réplicas de lectura.\n- **`Amazon Aurora`**: motor relacional gestionado por AWS, compatible con MySQL y PostgreSQL, con almacenamiento distribuido y replicación integrada. Está pensado para cargas exigentes que necesitan más rendimiento y disponibilidad que una instancia estándar, y sigue siendo relacional: se consulta con SQL.\n\nElegir relacional no es solo una cuestión de motor: si los datos tienen relaciones claras (pedidos y clientes, cuentas y movimientos) y las consultas son transaccionales, el modelo relacional encaja. La alternativa gestionada frente a una base en `Amazon EC2` es la misma decisión del grupo anterior: AWS administra la infraestructura y el equipo se queda con el esquema, los índices y las consultas."},{tipo:"comparacion",parId:"rds-vs-aurora-vs-dynamodb"},{tipo:"escenario",situacion:"Una plataforma de ventas necesita un motor relacional compatible con PostgreSQL, con lecturas intensivas y alta disponibilidad entre varias Availability Zones, y el equipo quiere administrar lo mínimo posible.",analisis:"`Amazon Aurora` aporta el modelo relacional con compatibilidad PostgreSQL, almacenamiento replicado y réplicas de lectura, sin que el equipo gestione el sistema operativo ni la conmutación. Si el requisito fuera un motor concreto no soportado por Aurora, la alternativa sería `Amazon RDS`.",servicio:"Amazon Aurora"},{tipo:"errorComun",error:"Confundir `Amazon Aurora` con una base NoSQL por su escalado, o suponer que `Amazon RDS` obliga a administrar el sistema operativo.",correccion:"`Amazon Aurora` es **relacional** y se consulta con SQL; su escalado no la convierte en NoSQL. Y `Amazon RDS` es gestionado: AWS se encarga del sistema operativo y de las tareas de mantenimiento del motor."},{tipo:"cuandoUsar",usar:["Usa `Amazon RDS` cuando necesites un motor relacional conocido y no quieras administrar la instancia.","Usa `Amazon Aurora` cuando el rendimiento, la disponibilidad y las réplicas de lectura sean exigentes y el motor compatible (MySQL o PostgreSQL) sea suficiente."],noUsar:["No uses una base relacional si el dato es clave-valor con acceso por clave y escala impredecible: ahí encaja mejor una base NoSQL.","No elijas `Amazon Aurora` solo por marketing: si un motor concreto no compatible es un requisito, `Amazon RDS` es la vía."]}],preguntasGuia:["¿Qué diferencia hay entre Amazon RDS y Amazon Aurora dentro del modelo relacional?","¿Qué tareas de administración asume AWS en una base relacional gestionada?","¿Cuándo conviene una base relacional y cuándo no?"]},{id:"3.4-g3",titulo:"Bases de datos NoSQL y en memoria: Amazon DynamoDB y Amazon ElastiCache",objetivos:["3.4#5","3.4#6"],bloques:[{tipo:"concepto",md:"**`Amazon DynamoDB`** es la base **NoSQL** gestionada de referencia: almacena elementos identificados por una clave, admite un modelo clave-valor y documento, y escala de forma horizontal con latencia de milisegundos sin que el equipo administre servidores. No se consulta con SQL tradicional y no exige un esquema fijo.\n\n**`Amazon ElastiCache`** es un almacén **en memoria**: mantiene los datos en RAM para responder en microsegundos y se usa sobre todo como **caché** delante de una base relacional o NoSQL, descargando lecturas repetidas. No es una base persistente de propósito general: si la caché se apaga, los datos volátiles se pierden.\n\nLa diferencia se ve en el rol: DynamoDB es la **fuente de verdad** para datos NoSQL, mientras que ElastiCache **acelera** el acceso a datos que viven en otra base. También hay bases NoSQL especializadas en el alcance: `Amazon DocumentDB` para documentos compatibles con MongoDB y `Amazon Neptune` para grafos."},{tipo:"comparacion",parId:"relacional-vs-nosql-vs-memoria"},{tipo:"escenario",situacion:"Una aplicación móvil con millones de usuarios guarda sesiones y perfiles por clave, con tráfico muy variable, y no puede dedicar un equipo a administrar servidores de base de datos.",analisis:"`Amazon DynamoDB` ofrece el modelo clave-valor con escalado gestionado y latencia de milisegundos, justo lo que pide el patrón de acceso por clave. Una base relacional añadiría administración de esquema e instancias que aquí no aportan valor.",servicio:"Amazon DynamoDB"},{tipo:"errorComun",error:"Usar `Amazon ElastiCache` como base de datos principal persistente, o creer que `Amazon DynamoDB` es una base relacional porque acepta tablas.",correccion:"`Amazon ElastiCache` es una capa en memoria pensada para caché; los datos críticos deben persistir en una base como `Amazon RDS`, `Amazon Aurora` o `Amazon DynamoDB`. Y `Amazon DynamoDB` es NoSQL: su unidad es el elemento con clave, no la fila de una tabla relacional con esquema fijo."},{tipo:"clave",items:["DynamoDB = NoSQL clave-valor y documento, gestionado, escala horizontal.","ElastiCache = en memoria, se usa como caché delante de otra base.","DocumentDB = documental (MongoDB); Neptune = grafos.","La caché acelera; no sustituye al almacenamiento persistente."]}],preguntasGuia:["¿Qué tipo de base de datos es Amazon DynamoDB y cómo se consulta?","¿Para qué sirve Amazon ElastiCache y por qué no es una base persistente?","¿Cuándo conviene una base NoSQL frente a una relacional?"]},{id:"3.4-g4",titulo:"Migración de bases de datos: AWS DMS y AWS SCT",objetivos:["3.4#2","3.4#7"],bloques:[{tipo:"concepto",md:"Migrar una base de datos a AWS puede ser **homogénea** (mismo motor, por ejemplo de MySQL local a MySQL gestionado) o **heterogénea** (motor distinto, por ejemplo de Oracle a PostgreSQL). Para cubrirlo, AWS ofrece dos herramientas complementarias:\n\n- **`AWS Database Migration Service (AWS DMS)`**: mueve y **replica los datos** entre un origen y un destino, incluso con motores distintos, y permite **replicación continua** para reducir el tiempo de inactividad durante el corte.\n- **`AWS Schema Conversion Tool (AWS SCT)`**: convierte el **esquema y el código** (procedimientos, vistas) de un motor a otro, paso imprescindible en las migraciones heterogéneas.\n\nEl patrón habitual combina ambos: primero se convierte el esquema con `AWS SCT` y después se replican los datos con `AWS DMS`. `AWS Migration Hub` sirve para seguir el progreso de la migración desde un único lugar, y `AWS Application Migration Service` cubre la migración de servidores completos, no solo de la base de datos."},{tipo:"comparacion",parId:"dms-vs-sct"},{tipo:"escenario",situacion:"Una empresa quiere mover su base de datos Oracle local a `Amazon Aurora` PostgreSQL con el mínimo tiempo de inactividad y sin reescribir el esquema a mano.",analisis:"Es una migración heterogénea: `AWS Schema Conversion Tool (AWS SCT)` convierte el esquema y el código incompatible, y `AWS Database Migration Service (AWS DMS)` replica los datos de forma continua hasta que se hace el corte final. Así la aplicación sigue operando contra el origen mientras se sincroniza el destino.",servicio:"AWS Database Migration Service (AWS DMS)"},{tipo:"errorComun",error:"Pensar que `AWS DMS` convierte el esquema por sí solo, o que `AWS SCT` mueve los datos.",correccion:"Son herramientas complementarias: `AWS DMS` mueve y replica datos; `AWS SCT` convierte el esquema y el código entre motores. En una migración heterogénea se usan las dos, primero la conversión y después la réplica."},{tipo:"ejemplo",md:"```text\nMigración homogénea (MySQL -> MySQL gestionado):\n  AWS DMS mueve los datos, el esquema encaja sin cambios\n\nMigración heterogénea (Oracle -> PostgreSQL en Amazon Aurora):\n  AWS SCT convierte esquema y código\n  AWS DMS replica los datos hasta el corte\n```"}],preguntasGuia:["¿En qué se diferencian una migración homogénea y una heterogénea?","¿Qué hace AWS DMS y qué hace AWS SCT?","¿Cómo se reduce el tiempo de inactividad al migrar una base de datos?"]}],3.5:[{id:"3.5-g1",titulo:"Servicios de red y componentes de una VPC",objetivos:["3.5#1","3.5#2"],bloques:[{tipo:"concepto",md:"La categoría de **redes y entrega de contenido** agrupa los servicios que conectan, aíslan y publican recursos: **Amazon VPC** para la red virtual privada, **Amazon Route 53** para DNS, **Amazon CloudFront** para entrega de contenido, **AWS Direct Connect** y **AWS VPN** para enlazar instalaciones propias, **AWS Transit Gateway** y **AWS PrivateLink** para interconectar redes y servicios, y **AWS Global Accelerator** para dirigir el tráfico de red por la infraestructura global de AWS.\n\n**Amazon VPC** es una red virtual aislada dentro de una región, con el rango de direcciones IP que tú defines. Sus componentes principales son:\n\n- **Subnet**: división del rango de la VPC confinada a una sola Availability Zone; puede ser pública o privada.\n- **Route table**: reglas que deciden por dónde sale cada paquete.\n- **Internet gateway**: puerta de entrada y salida hacia internet para las subredes públicas.\n- **NAT gateway**: salida a internet para subredes privadas, sin exponerlas a conexiones entrantes.\n- **VPC endpoint**: acceso privado a servicios de AWS sin salir a internet."},{tipo:"ejemplo",md:"```text\nDiseño habitual de una VPC:\n- Subred pública:  internet gateway + route table 0.0.0.0/0 hacia el gateway\n- Subred privada:  NAT gateway para la salida, sin entrada desde internet\n- Un par de subredes por Availability Zone para tolerar el fallo de una\n```"},{tipo:"cuandoUsar",usar:["Usa Amazon CloudFront cuando el requisito sea cachear y entregar contenido cerca del usuario.","Usa Amazon Route 53 cuando el requisito sea resolver nombres de dominio y enrutar por políticas.","Usa AWS Global Accelerator cuando el requisito sea mejorar la latencia de tráfico dinámico aprovechando la red global.","Usa AWS Transit Gateway o AWS PrivateLink cuando el requisito sea conectar redes o exponer servicios de forma privada."],noUsar:["No uses Route 53 para cachear ni servir contenido: solo resuelve nombres.","No uses CloudFront para conectar redes o para dirigir tráfico dinámico no cacheable.","No uses AWS Global Accelerator para interconectar VPC ni como CDN: dirige rutas de tráfico, no almacena contenido ni une redes.","No uses AWS PrivateLink para llegar a internet: expone servicios de forma privada entre redes."]},{tipo:"errorComun",error:"Creer que cualquier subred puede salir a internet por el simple hecho de estar dentro de una VPC.",correccion:"Para que una subred sea pública necesita un internet gateway asociado a la VPC y una route table que envíe el tráfico a ese gateway. Sin esa ruta, la subred queda privada aunque el rango de direcciones sea válido."}],preguntasGuia:["¿Qué servicios de AWS pertenecen a la categoría de red y para qué sirve cada uno?","¿Qué componentes forman una VPC y qué papel cumple cada uno?","¿Qué diferencia hay entre una subred pública y una privada?"]},{id:"3.5-g2",titulo:"Seguridad dentro de una VPC",objetivos:["3.5#3"],bloques:[{tipo:"concepto",md:"La seguridad de una VPC se aplica en capas que conviene no mezclar.\n\n- **Security group**: cortafuegos **con estado** (stateful) asociado a recursos como instancias. Solo admite reglas de permiso (allow); la respuesta de una conexión permitida vuelve sola, sin regla inversa. Actúa a nivel de instancia o recurso.\n- **Network ACL**: cortafuegos **sin estado** (stateless) asociado a una subred. Admite reglas de permiso y de denegación, se evalúa por orden de número de regla y obliga a definir explícitamente el tráfico de respuesta. Actúa a nivel de subred.\n\nAdemás, **Amazon Inspector** evalúa de forma continua las instancias para detectar vulnerabilidades conocidas y exposiciones de red no deseadas, mientras que **AWS Shield** mitiga ataques de denegación de servicio distribuido (DDoS) de red y volumen, y **AWS WAF** filtra peticiones HTTP(S) en la capa de aplicación."},{tipo:"comparacion",parId:"security-group-vs-nacls"},{tipo:"escenario",situacion:"Un equipo revisa por qué una instancia con un security group restrictivo sigue recibiendo tráfico inesperado. Quiere saber qué herramienta detecta configuraciones de red peligrosas y vulnerabilidades en sus servidores.",analisis:"El **security group** controla el tráfico permitido a la instancia y el **network ACL** filtra a nivel de subred; son controles preventivos. Para el análisis continuo de vulnerabilidades y exposiciones se usa **Amazon Inspector**, que evalúa las instancias y reporta hallazgos en lugar de bloquear el tráfico.",servicio:"Amazon Inspector"},{tipo:"errorComun",error:"Creer que los network ACLs y los security groups son lo mismo y que basta con configurar uno de los dos.",correccion:"Son capas complementarias: el network ACL filtra en la subred y el security group en el recurso. El tráfico debe superar ambos controles, así que conviene revisar las dos capas y no asumir que una sustituye a la otra."}],preguntasGuia:["¿Qué diferencia hay entre un security group y un network ACL?","¿Para qué sirve Amazon Inspector dentro de la seguridad de la VPC?","¿Por qué se aplican controles a nivel de subred y a nivel de recurso?"]},{id:"3.5-g3",titulo:"Propósito de Amazon Route 53",objetivos:["3.5#4"],bloques:[{tipo:"concepto",md:"**Amazon Route 53** es el servicio de DNS administrado de AWS. Traduce nombres de dominio legibles (por ejemplo, `app.ejemplo.com`) a direcciones IP o a destinos de AWS, de modo que los usuarios no tengan que conocer la dirección del servidor.\n\nSus usos principales son:\n\n- **Registro de dominios**: registrar y administrar el nombre de dominio público.\n- **Resolución DNS**: responder consultas mediante registros como A, AAAA o CNAME.\n- **Enrutamiento**: políticas por latencia, geolocalización, ponderación o failover.\n- **Comprobaciones de estado**: retirar un destino no saludable y desviar el tráfico al que sigue disponible.\n\nRoute 53 no reemplaza al alojamiento web ni a la entrega de contenido: resuelve nombres y dirige el tráfico hacia el destino correcto."},{tipo:"cuandoUsar",usar:["Usa Amazon Route 53 cuando necesites publicar un dominio público y resolver nombres hacia tus recursos en AWS.","Configura comprobaciones de estado y failover cuando quieras desviar el tráfico automáticamente si un destino deja de responder.","Elige políticas de enrutamiento por latencia o geolocalización cuando los usuarios estén repartidos por varias ubicaciones."],noUsar:["No esperes que Route 53 almacene o sirva el contenido: para eso se usan el alojamiento y la entrega de contenido.","No confundas Route 53 con un balanceador de carga: el DNS dirige la resolución de nombres, no reparte conexiones dentro de una red."]},{tipo:"errorComun",error:"Pensar que Amazon Route 53 solo registra dominios y no interviene en la disponibilidad del servicio.",correccion:"Además del registro, Route 53 resuelve consultas y aplica políticas de enrutamiento y comprobaciones de estado. Con failover puede retirar un destino no saludable y enviar a los usuarios a otro destino disponible."}],preguntasGuia:["¿Cuál es el propósito principal de Amazon Route 53?","¿Qué aportan las comprobaciones de estado y las políticas de enrutamiento?","¿En qué se diferencia Route 53 de un balanceador de carga?"]},{id:"3.5-g4",titulo:"Opciones de conectividad de red hacia AWS",objetivos:["3.5#5"],bloques:[{tipo:"concepto",md:"Conectar una red propia con AWS se apoya en dos piezas distintas: la **VPN** y la **conexión dedicada**.\n\n- **AWS VPN**: levanta un túnel cifrado sobre internet entre la red local y la VPC. Se despliega rápido y sirve como enlace de respaldo o para necesidades puntuales. Incluye variantes de sitio a sitio y de cliente remoto, como **AWS Client VPN**.\n- **AWS Direct Connect**: enlace dedicado y privado que no atraviesa internet, con ancho de banda y latencia más estables y predecibles. Exige contratar la conexión con un proveedor y tarda en aprovisionarse.\n\nA partir de ahí, **AWS Transit Gateway** conecta muchas VPC y redes locales desde un único punto, y **AWS PrivateLink** da acceso privado a servicios sin exponerlos a internet. La decisión habitual es Direct Connect para tráfico estable y crítico, y VPN para rapidez de despliegue, bajo volumen o respaldo."},{tipo:"comparacion",parId:"vpn-vs-direct-connect"},{tipo:"escenario",situacion:"Una empresa necesita transferir cada noche grandes volúmenes de datos entre su centro de datos y AWS con un ancho de banda estable y una latencia predecible. Además quiere un enlace de respaldo por si el principal falla.",analisis:"El requisito de ancho de banda estable y latencia predecible encaja con **AWS Direct Connect**, que no depende de las variaciones de internet. Como respaldo y para tráfico puntual se añade **AWS VPN**, que se despliega rápido sobre internet y puede asumir la conexión si el enlace dedicado se interrumpe.",servicio:"AWS Direct Connect"},{tipo:"errorComun",error:"Elegir AWS VPN o AWS Direct Connect solo por el precio, sin mirar la latencia, el ancho de banda ni la privacidad del tráfico.",correccion:"AWS VPN es más rápida de desplegar y más económica, pero el tráfico viaja cifrado por internet y su rendimiento puede variar. AWS Direct Connect ofrece un enlace dedicado y privado con mayor estabilidad a cambio de contratación y tiempo de aprovisionamiento. La elección depende del requisito de red."},{tipo:"clave",items:["AWS VPN = túnel cifrado sobre internet; rápida de desplegar, apta para respaldo y bajo volumen.","AWS Direct Connect = enlace dedicado y privado; ancho de banda y latencia estables, sin atravesar internet.","AWS Transit Gateway = concentrador para conectar muchas VPC y redes locales.","AWS PrivateLink = acceso privado a servicios sin exponerlos a internet."]}],preguntasGuia:["¿Qué diferencia hay entre AWS VPN y AWS Direct Connect?","¿Cuándo conviene un enlace dedicado y cuándo basta con una VPN?","¿Qué servicios ayudan a interconectar varias VPC y a exponer servicios de forma privada?"]}],3.6:[{id:"3.6-g1",titulo:"Almacenamiento de objetos y clases de Amazon S3",objetivos:["3.6#1","3.6#2","3.6#3"],bloques:[{tipo:"concepto",md:"El almacenamiento en AWS se reparte en tres modelos según cómo se accede al dato:\n\n- **Almacenamiento de objetos**: los datos se guardan como objetos con metadatos y una clave, dentro de un contenedor plano sin jerarquía real. Se accede por API HTTP y escala prácticamente sin límite. El servicio de referencia es **Amazon S3**.\n- **Almacenamiento en bloque**: volúmenes que se comportan como un disco, con sistema de archivos que gestiona el sistema operativo. Lo usan las instancias; ejemplos **Amazon EBS** e instance store.\n- **Almacenamiento de archivos**: sistemas de archivos compartidos por red, con rutas y permisos POSIX. Ejemplos **Amazon EFS** y **Amazon FSx**.\n\nEl objeto es la unidad completa: se lee y se escribe entero, no por bloques, y por eso resulta inmutable. Esa inmutabilidad habilita el versionado, las clases de almacenamiento y las políticas de ciclo de vida. El uso típico del almacenamiento de objetos es contenido estático, copias de seguridad, data lakes y cualquier dato que se consulte como un todo."},{tipo:"comparacion",parId:"s3-storage-classes"},{tipo:"escenario",situacion:"Una plataforma guarda fotos y vídeos que los usuarios consultan durante los primeros días y, después de un año, casi nadie vuelve a abrir. El equipo quiere reducir el coste sin perder los archivos.",analisis:"El patrón encaja con almacenamiento de objetos: se guardan los archivos como objetos y se aplica una política de ciclo de vida que mueve los objetos fríos a clases más baratas y los archiva después. No hay que reescribir la aplicación: solo cambia la clase del objeto.",servicio:"Amazon S3"},{tipo:"errorComun",error:"Creer que el almacenamiento de objetos sirve para montar el disco de una instancia o que se puede modificar un byte de un objeto sin reemplazarlo.",correccion:"Los objetos se leen y escriben completos, no por bloques. Para un disco de instancia o un sistema de archivos compartido se usan servicios de bloque o de archivos; el almacenamiento de objetos está pensado para datos completos sujetos a API y ciclo de vida."},{tipo:"clave",items:["Objetos: datos completos con metadatos, acceso por API y escala prácticamente ilimitada.","Bloque: volúmenes tipo disco para una instancia (Amazon EBS, instance store).","Archivos: sistema de archivos compartido por red (Amazon EFS, Amazon FSx).","Las clases de Amazon S3 intercambian coste por latencia y disponibilidad de acceso."]}],preguntasGuia:["¿Qué modelo de almacenamiento usarías para contenido estático servido por API?","¿En qué se diferencian las clases de almacenamiento de Amazon S3 entre sí?","¿Por qué un objeto no se puede editar parcialmente?"]},{id:"3.6-g2",titulo:"Almacenamiento en bloque: Amazon EBS e instance store",objetivos:["3.6#4"],bloques:[{tipo:"concepto",md:"El almacenamiento en bloque ofrece volúmenes que el sistema operativo ve como un disco. En **Amazon EC2** conviven dos opciones:\n\n- **Amazon EBS**: volúmenes de red asociados a una instancia. Son persistentes, admiten snapshots, cifrado y cambios de tamaño o de tipo sin recrear la instancia. La vida del volumen es independiente de la instancia.\n- **instance store**: almacenamiento físico local del host donde corre la instancia. Aporta la latencia más baja y el mayor rendimiento, pero es efímero: si la instancia se detiene, se reinicia en otro host o se termina, los datos se pierden.\n\nLa decisión habitual: los datos que deben sobrevivir a la instancia van a **Amazon EBS**; las cachés temporales, los archivos de intercambio o los datos replicados que se pueden reconstruir aprovechan instance store. Un volumen de bloque, además, no se comparte entre muchas instancias a la vez como un sistema de archivos."},{tipo:"comparacion",parId:"s3-vs-ebs-vs-efs"},{tipo:"escenario",situacion:"Una base de datos que corre en una instancia necesita que su volumen de datos sobreviva a un reinicio, se pueda ampliar más adelante y admita snapshots para restaurar.",analisis:"Es un caso claro de almacenamiento en bloque persistente: se asocia un volumen de **Amazon EBS** a la instancia, se cifra y se programan snapshots. El instance store no serviría porque sus datos se pierden al detener la instancia y no admite snapshots.",servicio:"Amazon Elastic Block Store (Amazon EBS)"},{tipo:"errorComun",error:"Elegir instance store para datos permanentes por su mayor rendimiento y descubrir que se pierden al detener o mover la instancia.",correccion:"El instance store es efímero y no se puede desasociar ni trasladar. Para datos que deben persistir se usa **Amazon EBS**; el instance store se reserva para datos temporales que se pueden reconstruir."},{tipo:"clave",items:["Amazon EBS: bloque persistente de red, con snapshots y cifrado.","instance store: bloque local efímero, atado al host de la instancia.","El instance store es más rápido pero se pierde al detener la instancia.","Para persistencia y copias recuperables, la respuesta es Amazon EBS."]}],preguntasGuia:["¿Qué diferencia hay entre Amazon EBS y el instance store?","¿Cuándo conviene un volumen efímero aunque se pierda el dato?","¿Por qué Amazon EBS sobrevive al ciclo de vida de la instancia?"]},{id:"3.6-g3",titulo:"Servicios de archivos y sistemas de archivos en caché",objetivos:["3.6#5","3.6#6"],bloques:[{tipo:"concepto",md:"Los servicios de archivos ofrecen un sistema de archivos compartido al que varias instancias acceden a la vez mediante NFS o SMB:\n\n- **Amazon EFS**: sistema de archivos elástico, gestionado y compartido para Linux. Crece y se encoge automáticamente, atiende a muchas instancias concurrentes y admite clases de almacenamiento para abaratar los archivos fríos.\n- **Amazon FSx**: familia de sistemas de archivos gestionados para cargas que necesitan motores concretos, como Windows File Server u otros motores específicos.\n\nEl almacenamiento en caché aparece cuando parte del dato sigue en las instalaciones. **AWS Storage Gateway** expone una puerta de enlace híbrida que da acceso local con caché a datos que realmente viven en AWS: los archivos de acceso reciente se quedan en la caché local y el resto se sirve bajo demanda desde el almacenamiento en la nube. No es un sistema de archivos compartido en AWS, sino un puente con caché entre el entorno local y la nube; según el caso ofrece modos de archivos, de volúmenes y de cintas."},{tipo:"comparacion",parId:"efs-vs-fsx-vs-storage-gateway"},{tipo:"cuandoUsar",usar:["Usa Amazon EFS cuando varias instancias Linux necesiten compartir archivos con crecimiento automático.","Usa Amazon FSx cuando la carga exija un motor concreto, como Windows File Server o Lustre.","Usa AWS Storage Gateway cuando las aplicaciones locales deban seguir leyendo archivos con baja latencia mientras el dato se guarda en AWS."],noUsar:["No uses un sistema de archivos compartido como sustituto de un volumen de bloque para el disco de arranque de una instancia.","No montes el mismo sistema de archivos en hosts que necesitan semánticas incompatibles, como Linux y Windows sobre Amazon EFS."]},{tipo:"ejemplo",md:"```text\nNecesidad -> servicio\n- Archivos compartidos entre muchas instancias Linux -> Amazon EFS\n- Sistema de archivos gestionado para Windows           -> Amazon FSx\n- Archivos locales con el dato en AWS (caché)          -> AWS Storage Gateway\n- Disco persistente de una sola instancia              -> Amazon EBS\n```"}],preguntasGuia:["¿Cuándo elegirías Amazon EFS frente a Amazon FSx?","¿Para qué sirve AWS Storage Gateway y qué papel juega la caché local?","¿Por qué un sistema de archivos compartido no sustituye a un volumen de bloque?"]},{id:"3.6-g4",titulo:"Ciclo de vida del dato y AWS Backup",objetivos:["3.6#7","3.6#8"],bloques:[{tipo:"concepto",md:"Dos capacidades gestionan el ciclo de vida del dato almacenado:\n\n- **Políticas de ciclo de vida**: reglas que mueven o eliminan objetos automáticamente según su antigüedad. En **Amazon S3** permiten transicionar objetos entre clases de almacenamiento y expirarlos cuando ya no se necesitan, sin intervención manual.\n- **AWS Backup**: servicio centralizado que define, programa y supervisa copias de seguridad de varios servicios, como volúmenes de **Amazon EBS** o sistemas de archivos **Amazon EFS** y **Amazon FSx**, con políticas, retención y almacén de respaldo.\n\nLa diferencia conceptual es clara: la política de ciclo de vida optimiza el coste del dato activo moviéndolo entre clases o borrándolo cuando deja de aportar; **AWS Backup** protege contra pérdida o corrupción creando copias recuperables con una retención definida. Una no sustituye a la otra."},{tipo:"cuandoUsar",usar:["Usa lifecycle policies cuando el patrón de acceso de los objetos cambie con el tiempo y quieras abaratar el almacenamiento de forma automática.","Usa AWS Backup cuando necesites copias recuperables con retención y cumplimiento sobre varios servicios a la vez.","Combínalas: la política de ciclo de vida abarata el dato frío y AWS Backup asegura que exista una copia restaurable."],noUsar:["No confundas una transición de clase con una copia de seguridad: el objeto sigue siendo el mismo, solo cambia de clase.","No uses solo políticas de ciclo de vida para cumplir una retención de copias de seguridad."]},{tipo:"errorComun",error:"Pensar que mover objetos a una clase de archivado con una política de ciclo de vida equivale a tener una copia de seguridad.",correccion:"La transición de clase no crea una copia independiente: es el mismo objeto en otra clase. Para recuperarte de un borrado accidental o de una corrupción necesitas **AWS Backup** u otra copia con retención."},{tipo:"ejemplo",md:"```text\nObjetivo -> herramienta\n- Abaratar objetos que envejecen       -> política de ciclo de vida (Amazon S3)\n- Conservar el dato pero más barato     -> transición de clase\n- Recuperar datos tras un borrado       -> AWS Backup\n- Retención y cumplimiento multi-servicio -> AWS Backup\n```"}],preguntasGuia:["¿Qué problema resuelve una política de ciclo de vida y qué no resuelve?","¿En qué se diferencia el ciclo de vida de AWS Backup?","¿Por qué una transición de clase no equivale a una copia de seguridad?"]}],3.7:[{id:"3.7-g1",titulo:"Servicios de IA/ML y la tarea que resuelve cada uno",objetivos:["3.7#1","3.7#3"],bloques:[{tipo:"concepto",md:"Los servicios de **IA/ML gestionados** de AWS se dividen en dos familias según lo que esperas de ellos:\n\n- **Servicios de IA ya entrenados**: exponen una tarea concreta como API. No entrenas nada; envías datos y recibes el resultado. Por ejemplo, análisis de imágenes y vídeo con **Amazon Rekognition**, análisis de lenguaje natural con **Amazon Comprehend**, extracción de texto de documentos con **Amazon Textract**, voz a texto con **Amazon Transcribe**, texto a voz con **Amazon Polly**, traducción con **Amazon Translate** y asistentes conversacionales con **Amazon Lex**.\n- **Plataforma para construir**: **Amazon SageMaker AI** permite preparar datos, entrenar, ajustar y desplegar modelos propios.\n\nLa pregunta clave no es «qué servicio es más potente», sino **qué tarea resuelve**: si existe un servicio ya entrenado para tu caso, suele ser la vía más rápida; si necesitas un modelo propio, la plataforma de aprendizaje automático.\n\nLa analítica responde a otra pregunta distinta: no interpreta lenguaje ni imágenes, sino que **mueve, transforma y consulta datos** para obtener información de negocio."},{tipo:"comparacion",parId:"transcribe-vs-polly"},{tipo:"comparacion",parId:"comprehend-vs-textract"},{tipo:"escenario",situacion:"Un banco quiere un asistente virtual que entienda preguntas escritas en lenguaje natural y responda conversando con el cliente dentro de su aplicación.",analisis:"La tarea es comprender el lenguaje del usuario y mantener un diálogo con intención definida. Eso es exactamente lo que resuelve **Amazon Lex**, un servicio de IA ya entrenado para asistentes conversacionales; no requiere entrenar un modelo propio.",servicio:"Amazon Lex"},{tipo:"errorComun",error:"Confundir la dirección de los servicios de voz y texto, o creer que **Amazon SageMaker AI** es un servicio ya entrenado que responde a una tarea concreta.",correccion:"Cada servicio ya entrenado resuelve una tarea concreta: **Amazon Transcribe** convierte voz en texto y **Amazon Polly** texto en voz; **Amazon Comprehend** interpreta texto y **Amazon Textract** lo extrae de documentos. **Amazon SageMaker AI** es la plataforma para construir modelos propios, no una tarea resuelta."},{tipo:"clave",items:["Servicios ya entrenados: tarea resuelta por API, sin entrenar (imágenes, texto, voz, traducción, conversación).","Plataforma para construir: **Amazon SageMaker AI** cubre preparar datos, entrenar, ajustar y desplegar.","**Amazon Transcribe** = voz a texto; **Amazon Polly** = texto a voz; son direcciones opuestas.","**Amazon Comprehend** analiza texto existente; **Amazon Textract** extrae texto de documentos escaneados.","La elección se hace por tarea, no por popularidad del servicio."]}],preguntasGuia:["¿Qué dos familias de servicios de IA/ML ofrece AWS y en qué se diferencian?","¿Qué servicio de IA ya entrenado usarías para analizar imágenes, para analizar texto y para convertir voz en texto?","¿Cómo decides entre un servicio de IA ya entrenado y Amazon SageMaker AI?"]},{id:"3.7-g2",titulo:"Amazon SageMaker AI frente a los servicios de IA ya entrenados",objetivos:["3.7#3","3.7#1"],bloques:[{tipo:"concepto",md:"**Amazon SageMaker AI** es la plataforma gestionada para el ciclo de vida del aprendizaje automático: preparar y etiquetar datos, elegir algoritmos, entrenar, ajustar hiperparámetros, evaluar y desplegar el modelo para inferencia. Tú aportas los datos y el problema; AWS gestiona la infraestructura de cómputo y el entorno.\n\nLos **servicios de IA ya entrenados**, en cambio, ya vienen resueltos para una tarea concreta. Si tu necesidad es transcribir audio, analizar sentimiento o detectar objetos en una imagen, no tiene sentido entrenar un modelo desde cero: se usa la API del servicio correspondiente.\n\nLa decisión práctica es: **tarea estándar y sin datos propios → servicio ya entrenado; modelo propio, datos propios y control del entrenamiento → Amazon SageMaker AI**."},{tipo:"comparacion",parId:"sagemaker-vs-servicios-ia"},{tipo:"escenario",situacion:"Un equipo de datos quiere predecir la rotación de clientes con un modelo entrenado a partir de los datos históricos de la empresa, que son confidenciales y muy específicos del negocio.",analisis:"No existe un servicio ya entrenado que resuelva esa predicción concreta con esos datos: hace falta construir, entrenar y desplegar un modelo propio. Ese ciclo completo es lo que cubre **Amazon SageMaker AI**.",servicio:"Amazon SageMaker AI"},{tipo:"errorComun",error:"Creer que **Amazon SageMaker AI** es un servicio de IA ya entrenado que responde a una tarea concreta, o pensar que hay que entrenar un modelo propio aunque exista un servicio ya entrenado para esa tarea.",correccion:"**Amazon SageMaker AI** es la plataforma para construir y desplegar modelos propios. Si la tarea es estándar (imágenes, voz, texto, traducción), el servicio de IA ya entrenado es la opción directa y de menor esfuerzo."},{tipo:"cuandoUsar",usar:["Usa un servicio de IA ya entrenado cuando la tarea sea estándar y no quieras gestionar entrenamiento ni datos de entrenamiento.","Usa **Amazon SageMaker AI** cuando necesites un modelo propio, con tus datos, tu algoritmo y control del entrenamiento y del despliegue."],noUsar:["No entrenes un modelo propio para una tarea que ya resuelve un servicio gestionado: añade coste, tiempo y mantenimiento.","No uses **Amazon SageMaker AI** como sustituto de la analítica: para consultar y transformar datos están los servicios de analítica."]}],preguntasGuia:["¿Qué cubre Amazon SageMaker AI dentro del ciclo de vida del aprendizaje automático?","¿Cuándo un servicio de IA ya entrenado es mejor opción que entrenar un modelo propio?","¿Qué coste y esfuerzo añades si entrenas un modelo para una tarea que ya tiene servicio gestionado?"]},{id:"3.7-g3",titulo:"Analítica de datos: ingerir, preparar y consultar",objetivos:["3.7#2","3.7#4"],bloques:[{tipo:"concepto",md:"La analítica de datos en AWS cubre tres momentos distintos, y confundirlos es el error más habitual:\n\n- **Ingesta de flujos**: **Amazon Kinesis** recibe y procesa datos que llegan de forma continua (eventos, telemetría, clics).\n- **Preparación y catálogo**: **AWS Glue** descubre y cataloga los datos y ejecuta trabajos de extracción, transformación y carga (ETL).\n- **Consulta y visualización**: **Amazon Athena** consulta con SQL datos que ya están en **Amazon S3**, sin aprovisionar servidores, y **Amazon Quick Sight** construye paneles y visualizaciones.\n\nUn servicio no sustituye al otro: **Amazon Kinesis** mueve el dato en movimiento, **AWS Glue** lo prepara y organiza, **Amazon Athena** lo consulta y **Amazon Quick Sight** lo presenta. Para volúmenes analíticos grandes y consultas repetidas también existen **Amazon Redshift**, **Amazon EMR** y **Amazon OpenSearch Service**, cada uno con su nicho."},{tipo:"comparacion",parId:"athena-vs-glue-vs-kinesis"},{tipo:"escenario",situacion:"Una empresa guarda año tras año archivos de registro y de ventas en **Amazon S3**. Quiere hacer preguntas puntuales con SQL sobre ese histórico sin montar ni administrar ningún servidor de base de datos.",analisis:"**Amazon Athena** consulta directamente los datos que ya están en **Amazon S3** con SQL y sin infraestructura que administrar, por lo que encaja con consultas exploratorias sobre el histórico almacenado.",servicio:"Amazon Athena"},{tipo:"errorComun",error:"Pensar que **Amazon Kinesis** consulta el histórico almacenado o que **AWS Glue** es un motor de consultas SQL, y usar el servicio equivocado para el momento del dato.",correccion:"Ordena por momento del dato: **Amazon Kinesis** para el dato en movimiento, **AWS Glue** para preparar y catalogar y **Amazon Athena** para consultar con SQL lo que ya está almacenado. Cada uno resuelve una fase distinta."},{tipo:"clave",items:["**Amazon Kinesis** = dato en streaming, en tiempo real.","**AWS Glue** = catálogo y trabajos ETL para dejar los datos listos.","**Amazon Athena** = consultas SQL sobre datos ya almacenados, sin servidores.","**Amazon Quick Sight** = visualización y paneles de negocio.","Pregúntate siempre en qué momento está el dato antes de elegir el servicio."]}],preguntasGuia:["¿Qué servicio de analítica usarías para un flujo continuo de eventos y cuál para consultar un histórico con SQL?","¿Qué papel cumple AWS Glue entre el dato almacenado y el análisis?","¿Por qué Amazon Athena no necesita que administres servidores?"]},{id:"3.7-g4",titulo:"Almacén, buscador y visualización en analítica",objetivos:["3.7#2"],bloques:[{tipo:"concepto",md:"Cuando los datos ya están preparados, AWS ofrece servicios de analítica especializados según el tipo de pregunta:\n\n- **Amazon Redshift**: almacén de datos (data warehouse) para consultas analíticas complejas y agregadas sobre grandes volúmenes.\n- **Amazon OpenSearch Service**: motor de búsqueda y análisis de registros y texto, útil para explorar y encontrar patrones en logs.\n- **Amazon EMR**: procesamiento de grandes volúmenes de datos con frameworks distribuidos para transformaciones pesadas.\n- **Amazon Quick Sight**: servicio de inteligencia de negocio para crear paneles y visualizaciones a partir de datos ya preparados, sin programar.\n\nTodos parten de datos que ya existen; la diferencia está en si necesitas un almacén para consultas analíticas, un buscador sobre registros, capacidad de procesamiento masivo o una capa de visualización para el negocio."},{tipo:"cuandoUsar",usar:["Usa **Amazon Redshift** para un almacén analítico con consultas complejas y repetidas sobre datos estructurados.","Usa **Amazon OpenSearch Service** para buscar y explorar registros y texto, y **Amazon Quick Sight** para paneles de negocio.","Usa **Amazon EMR** cuando necesites procesar grandes volúmenes con cómputo distribuido."],noUsar:["No uses un almacén analítico para ingerir un flujo en tiempo real: para eso está el procesamiento de streaming.","No uses una capa de visualización como sustituto del almacenamiento o la preparación de datos."]},{tipo:"ejemplo",md:"```text\nPregunta de negocio -> servicio de analítica\n- Consultas analíticas complejas y repetidas -> Amazon Redshift\n- Buscar patrones en registros y logs     -> Amazon OpenSearch Service\n- Procesamiento masivo distribuido        -> Amazon EMR\n- Panel con gráficos para el negocio      -> Amazon Quick Sight\n```"}],preguntasGuia:["¿Qué diferencia hay entre un almacén analítico y una capa de visualización?","¿Para qué tipo de datos conviene Amazon OpenSearch Service?","¿Cuándo tiene sentido Amazon EMR?"]}],3.8:[{id:"3.8-g1",titulo:"Integración de aplicaciones: eventos, notificaciones y colas",objetivos:["3.8#1","3.8#8"],bloques:[{tipo:"concepto",md:"La **integración de aplicaciones** conecta componentes sin acoplarlos entre sí. En el alcance del examen hay tres servicios que resuelven la entrega de información:\n\n- **Amazon Simple Queue Service (Amazon SQS)**: cola de mensajes. Un productor deposita el mensaje y un consumidor lo recoge para procesarlo; desacopla ambos lados y permite acumular trabajo y reintentar sin perder nada.\n- **Amazon Simple Notification Service (Amazon SNS)**: publicación/suscripción (pub/sub). Un mismo mensaje se difunde a muchos suscriptores a la vez (correo, SMS, endpoints HTTP); es la vía natural para alertas y notificaciones.\n- **Amazon EventBridge**: bus de eventos que reacciona a eventos del sistema o de las aplicaciones y los enruta a destinos según reglas, sin que el emisor conozca al receptor.\n\nA estos se suma **AWS Step Functions**, que orquesta varios pasos como una máquina de estados cuando el flujo tiene lógica y secuencia propia."},{tipo:"comparacion",parId:"sns-vs-sqs-vs-eventbridge"},{tipo:"escenario",situacion:"Una tienda en línea debe avisar de inmediato a cada cliente por correo y por SMS cuando su pedido cambia de estado, y a la vez entregar cada cambio a un sistema de análisis que lo procesa a su propio ritmo.",analisis:"Las **alertas** al cliente exigen un patrón de publicación/suscripción: el mismo evento debe llegar a varios suscriptores al instante, y eso lo resuelve un topic de **Amazon SNS**. El sistema de análisis, en cambio, no debe bloquear el flujo de la tienda, así que el trabajo se deposita en una cola de **Amazon SQS** que el analizador consume cuando puede. Un topic puede publicar en una cola, de modo que ambas piezas encajan sin acoplar la tienda con sus consumidores.",servicio:"Amazon Simple Notification Service (Amazon SNS)"},{tipo:"errorComun",error:"Usar Amazon Simple Queue Service (Amazon SQS) para lanzar una alerta inmediata a muchos destinatarios o emplear Amazon Simple Notification Service (Amazon SNS) para retener trabajo pendiente que otro sistema procesará después.",correccion:"Las alertas y notificaciones inmediatas a varios suscriptores son pub/sub y las cubre Amazon SNS; el trabajo que debe esperar y procesarse una sola vez es una cola y lo cubre Amazon SQS. Cuando la decisión depende de reaccionar a eventos y enrutarlos según reglas, el servicio es Amazon EventBridge."},{tipo:"clave",items:["Amazon SQS = cola: desacopla productor y consumidor, acumula trabajo y permite reintentar.","Amazon SNS = publicación/suscripción: difunde alertas y notificaciones a muchos suscriptores.","Amazon EventBridge = bus de eventos: reacciona y enruta eventos a destinos según reglas.","AWS Step Functions = orquestación de pasos cuando el flujo tiene lógica y secuencia."]}],preguntasGuia:["¿Cuándo conviene una cola y cuándo un modelo de publicación/suscripción?","¿Qué diferencia hay entre enrutar eventos y difundir un mensaje?","¿Qué servicio orquesta varios pasos de un flujo de trabajo?"]},{id:"3.8-g2",titulo:"Aplicaciones de negocio: centro de contacto y correo electrónico",objetivos:["3.8#2","3.8#9"],bloques:[{tipo:"concepto",md:"Las **aplicaciones de negocio** cubren funciones de negocio listas para usar, sin construir la infraestructura por tu cuenta:\n\n- **Amazon Connect**: centro de contacto omnicanal en la nube. Enruta llamadas, chat y tareas a los agentes, incorpora IVR, grabación y analíticas, y se paga por uso sin mantener centralitas propias.\n- **Amazon Simple Email Service (Amazon SES)**: servicio de envío y recepción de correo electrónico a escala. Está pensado para correo transaccional y de marketing con alta entregabilidad, sin administrar servidores de correo.\n\nLa clave para elegir es el canal: **voz y chat** apuntan a Amazon Connect; **correo electrónico**, a Amazon SES."},{tipo:"cuandoUsar",usar:["Usa **Amazon Connect** cuando necesites atención al cliente con enrutamiento de llamadas, IVR y agentes que trabajan desde cualquier lugar.","Usa **Amazon Simple Email Service (Amazon SES)** cuando una aplicación deba enviar correos transaccionales o de marketing de forma masiva y fiable.","Combina ambos canales si la atención al cliente requiere voz, chat y correo en una misma experiencia."],noUsar:["No uses Amazon SES para gestionar llamadas telefónicas ni Amazon Connect para enviar correo masivo.","No montes servidores de correo propios para envíos transaccionales: Amazon SES ya gestiona entregabilidad y reputación."]},{tipo:"escenario",situacion:"Una empresa quiere atender a sus clientes por teléfono y chat desde varios países, con enrutamiento inteligente a los agentes, sin comprar ni mantener infraestructura telefónica.",analisis:"La necesidad es un centro de contacto omnicanal gestionado: enrutamiento de voz y chat, IVR y agentes distribuidos. Eso es exactamente **Amazon Connect**, que se aprovisiona en minutos y escala según la demanda. El correo no entra en este escenario; si además se quisieran enviar notificaciones por email, correspondería a Amazon SES.",servicio:"Amazon Connect"},{tipo:"errorComun",error:"Creer que Amazon Simple Email Service (Amazon SES) gestiona llamadas telefónicas o que Amazon Connect sirve para enviar correo transaccional masivo.",correccion:"Cada servicio cubre un canal distinto: Amazon Connect es el centro de contacto para voz y chat, y Amazon Simple Email Service (Amazon SES) es el servicio de correo electrónico a escala. Elegir por el canal esperado evita confusiones."}],preguntasGuia:["¿Qué servicio atiende llamadas y chat, y cuál envía correo a escala?","¿Cómo se elige entre Amazon Connect y Amazon Simple Email Service (Amazon SES)?","¿Qué canal cubre cada aplicación de negocio del alcance?"]},{id:"3.8-g3",titulo:"Habilitación del cliente: planes de AWS Support",objetivos:["3.8#3","3.8#10"],bloques:[{tipo:"concepto",md:"La **habilitación del cliente** agrupa los recursos de asistencia que AWS ofrece al cliente. **AWS Support** se contrata en varios planes con distinto nivel de respuesta:\n\n- **Basic**: incluido en toda cuenta; acceso a documentación, AWS re:Post y AWS Health Dashboard, pero sin soporte técnico de producción.\n- **AWS Developer Support**: soporte técnico por correo en horario laboral, orientado a desarrollo y pruebas.\n- **AWS Business Support**: soporte 24/7, AWS Trusted Advisor completo y tiempos de respuesta rápidos para producción.\n- **AWS Enterprise On-Ramp Support** y **AWS Enterprise Support**: niveles para cargas críticas. Enterprise On-Ramp da acceso a un grupo de Technical Account Managers (TAM) y guía proactiva para cargas moderadas; Enterprise añade un TAM designado, revisión proactiva de la arquitectura y el menor tiempo de respuesta para sistemas críticos.\n\nEl **AWS Support Center** concentra la gestión de casos y **AWS Trusted Advisor** revisa buenas prácticas del entorno."},{tipo:"escenario",situacion:"Una empresa ejecuta una plataforma de ventas con tráfico continuo y necesita soporte 24/7, tiempos de respuesta rápidos y un interlocutor técnico dedicado que conozca su arquitectura.",analisis:"El soporte básico no cubre producción y el plan de desarrollo no ofrece cobertura 24/7. Lo que se pide —cobertura continua, respuesta rápida y un Technical Account Manager (TAM)— corresponde a **AWS Enterprise Support**, el nivel más alto de asistencia. Elegir un plan inferior dejaría sin cubrir la criticidad de la carga.",servicio:"AWS Support"},{tipo:"errorComun",error:"Suponer que el plan Basic incluye soporte técnico de producción o contratar AWS Enterprise Support para un prototipo sin cargas críticas.",correccion:"El plan Basic no incluye soporte técnico de producción. El nivel se elige según la criticidad: AWS Developer Support para desarrollo y pruebas, AWS Business Support para producción con cobertura 24/7 y AWS Enterprise Support para cargas críticas que exigen el menor tiempo de respuesta y un Technical Account Manager (TAM)."},{tipo:"clave",items:["Basic = incluido, sin soporte técnico de producción.","AWS Developer Support = correo en horario laboral, para desarrollo y pruebas.","AWS Business Support = 24/7 y AWS Trusted Advisor completo para producción.","AWS Enterprise Support = cargas críticas, menor tiempo de respuesta y Technical Account Manager (TAM).","AWS Trusted Advisor y AWS Health Dashboard complementan la asistencia sin sustituir al plan."]}],preguntasGuia:["¿Qué incluye el plan Basic y qué añade un plan de pago?","¿Qué plan elegir para una carga crítica con cobertura 24/7?","¿Qué papel cumplen AWS Trusted Advisor y AWS Support Center?"]},{id:"3.8-g4",titulo:"Herramientas de desarrollo: compilar, desplegar y depurar",objetivos:["3.8#4","3.8#11"],bloques:[{tipo:"concepto",md:"Las **herramientas de desarrollo** cubren el ciclo de vida de una aplicación:\n\n- **AWS CodeBuild**: compila el código, ejecuta pruebas y genera el artefacto, sin administrar servidores de compilación.\n- **AWS CodePipeline**: modela y coordina la canalización de extremo a extremo; encadena origen, compilación, pruebas y despliegue según las etapas definidas.\n- **AWS X-Ray**: rastrea las solicitudes a través de los componentes de la aplicación para localizar errores y cuellos de botella.\n- **AWS CLI**: permite operar los servicios de forma programática desde la línea de comandos.\n\nRegla práctica: **AWS CodeBuild** hace el trabajo de construir, **AWS CodePipeline** dirige el flujo y **AWS X-Ray** ayuda a **depurar** cuando algo falla en ejecución."},{tipo:"comparacion",parId:"codebuild-vs-codepipeline"},{tipo:"escenario",situacion:"Un equipo quiere que cada cambio en el repositorio compile, pase pruebas y llegue a producción sin pasos manuales, y poder ver en qué etapa falla la entrega.",analisis:"La coordinación de todas las etapas de principio a fin corresponde a **AWS CodePipeline**, que encadena origen, compilación, pruebas y despliegue. Dentro de esa canalización, la etapa de compilar y probar la ejecuta AWS CodeBuild. Para diagnosticar el comportamiento en ejecución de la aplicación desplegada se usa AWS X-Ray.",servicio:"AWS CodePipeline"},{tipo:"errorComun",error:"Pedirle a AWS CodeBuild que coordine todas las etapas de despliegue o esperar que AWS CodePipeline compile el código por sí mismo.",correccion:"AWS CodeBuild construye y prueba; AWS CodePipeline orquesta las etapas y decide el orden del flujo. Son piezas complementarias de la misma canalización, no sustitutos entre sí."},{tipo:"clave",items:["AWS CodeBuild = compila, ejecuta pruebas y produce el artefacto.","AWS CodePipeline = coordina las etapas de la canalización de principio a fin.","AWS X-Ray = traza solicitudes para depurar errores y latencia.","AWS CLI = acceso programático desde la línea de comandos."]}],preguntasGuia:["¿Qué servicio compila y cuál coordina la canalización?","¿Con qué herramienta se depuran errores en ejecución?","¿Qué piezas forman un flujo de integración y entrega continua?"]},{id:"3.8-g5",titulo:"Computación de usuario final: aplicaciones y escritorios en la nube",objetivos:["3.8#5","3.8#12"],bloques:[{tipo:"concepto",md:"La **computación de usuario final** entrega puestos de trabajo desde la nube, de modo que la carga se ejecuta en AWS y el usuario solo recibe la salida en su dispositivo:\n\n- **Amazon AppStream 2.0**: entrega **aplicaciones** concretas por streaming. La aplicación corre en AWS y el usuario la ve y la usa en su navegador o cliente, sin instalarla.\n- **Amazon WorkSpaces**: entrega un **escritorio virtual completo y persistente** por usuario, con su sistema operativo y sus aplicaciones, accesible desde distintos dispositivos.\n- **Amazon WorkSpaces Secure Browser**: ofrece un **navegador aislado** para acceder de forma segura a sitios internos sin exponer la red del usuario.\n\nLa distinción habitual es aplicación suelta frente a escritorio completo: AppStream 2.0 publica una aplicación, WorkSpaces publica el escritorio entero."},{tipo:"comparacion",parId:"appstream-vs-workspaces"},{tipo:"escenario",situacion:"Una empresa quiere dar acceso a un programa de diseño pesado a contratistas que usan equipos modestos, sin instalarlo en esos equipos ni enviarles licencias locales.",analisis:"Lo que se necesita es publicar **una sola aplicación** por streaming: el programa se ejecuta en AWS y el contratista solo recibe su salida en el dispositivo. El servicio indicado es **Amazon AppStream 2.0**. Si además cada persona necesitara un escritorio corporativo completo, la opción sería Amazon WorkSpaces.",servicio:"Amazon AppStream 2.0"},{tipo:"errorComun",error:"Confundir Amazon AppStream 2.0 con Amazon WorkSpaces y creer que Amazon WorkSpaces Secure Browser entrega un escritorio completo con sistema operativo.",correccion:"Amazon AppStream 2.0 publica aplicaciones individuales por streaming; Amazon WorkSpaces entrega un escritorio virtual completo y persistente por usuario; Amazon WorkSpaces Secure Browser solo proporciona un navegador aislado. Se elige según lo que haya que presentar en el equipo del usuario final."},{tipo:"clave",items:["Amazon AppStream 2.0 = aplicaciones por streaming, sin instalación local.","Amazon WorkSpaces = escritorio virtual completo y persistente por usuario.","Amazon WorkSpaces Secure Browser = navegador aislado para acceso web seguro.","El cómputo se ejecuta en AWS y el usuario final solo recibe la salida."]}],preguntasGuia:["¿Qué servicio publica una aplicación y cuál publica un escritorio completo?","¿Para qué sirve Amazon WorkSpaces Secure Browser?","¿Dónde se ejecuta el cómputo en la computación de usuario final?"]},{id:"3.8-g6",titulo:"Frontend web y móvil con AWS Amplify",objetivos:["3.8#6","3.8#13"],bloques:[{tipo:"concepto",md:"**AWS Amplify** agrupa el frontend web y móvil en un mismo flujo: proporciona herramientas y bibliotecas para crear la interfaz, añadir capacidades como autenticación o APIs y publicar la aplicación con hosting y entrega continua.\n\nSu valor es reducir el trabajo de integrar el frontend con el backend: en lugar de montar y cablear cada servicio por separado, Amplify ofrece una experiencia guiada para construir, conectar y desplegar aplicaciones web y móviles, apoyándose por debajo en servicios como Amazon Cognito (autenticación), Amazon API Gateway (APIs), Amazon S3 (contenido estático) y Amazon CloudFront (entrega)."},{tipo:"escenario",situacion:"Una startup quiere lanzar una aplicación móvil con registro de usuarios y una web de marketing, y desplegar ambas desde el repositorio sin configurar manualmente autenticación, hosting y entrega.",analisis:"El objetivo es **crear y desplegar frontend web y móvil** con las capacidades habituales ya integradas. **AWS Amplify** cubre ese ciclo: conecta la autenticación, expone la API y publica el frontend con hosting y entrega continua, apoyándose por debajo en Amazon Cognito, Amazon API Gateway, Amazon S3 y Amazon CloudFront. No es una herramienta de compilación de propósito general ni un centro de contacto.",servicio:"AWS Amplify"},{tipo:"errorComun",error:"Encargar a AWS Amplify la depuración de microservicios o creer que sustituye a AWS CodePipeline como orquestador genérico de cualquier aplicación.",correccion:"AWS Amplify está orientado al frontend web y móvil: crear la interfaz, integrar capacidades y desplegarla. La depuración de solicitudes distribuidas es AWS X-Ray y la orquestación genérica de canalizaciones, AWS CodePipeline."},{tipo:"clave",items:["AWS Amplify = creación y despliegue de frontend web y móvil.","Integra autenticación, APIs y hosting en un flujo guiado.","Se apoya en Amazon Cognito, Amazon API Gateway, Amazon S3 y Amazon CloudFront.","No es una herramienta de compilación genérica ni un servicio de integración de aplicaciones."]}],preguntasGuia:["¿Qué problema resuelve AWS Amplify en el frontend?","¿Qué servicios usa por debajo para autenticación y entrega?","¿En qué se diferencia de una canalización genérica de despliegue?"]},{id:"3.8-g7",titulo:"IoT gestionado con AWS IoT Core",objetivos:["3.8#7","3.8#14"],bloques:[{tipo:"concepto",md:"**AWS IoT Core** es el servicio gestionado que conecta dispositivos IoT con la nube. Registra los dispositivos, autentica su conexión y recibe los mensajes que publican mediante protocolos ligeros como MQTT.\n\nCon las reglas de AWS IoT Core los mensajes de los dispositivos se enrutan hacia otros servicios, por ejemplo AWS Lambda para procesarlos o Amazon S3 para almacenarlos. Así, la flota de dispositivos queda administrada de forma centralizada —identidad, comunicación segura y enrutado— sin operar un bróker propio."},{tipo:"escenario",situacion:"Una fábrica despliega miles de sensores que deben registrarse de forma individual, comunicarse de forma segura con la nube y publicar sus lecturas para que un proceso automático las analice.",analisis:"El reto es **gestionar dispositivos IoT**: identidad por dispositivo, conexión segura y recepción de lecturas. **AWS IoT Core** registra y autentica cada sensor, recibe sus mensajes y, mediante reglas, los enruta a AWS Lambda o Amazon S3 según el caso. No es un servicio de colas para trabajo de aplicaciones ni un centro de contacto.",servicio:"AWS IoT Core"},{tipo:"errorComun",error:"Elegir Amazon Simple Queue Service (Amazon SQS) o Amazon Connect para conectar y administrar dispositivos IoT, o intentar operar un bróker MQTT propio en su lugar.",correccion:"La conexión, autenticación y administración de dispositivos IoT las cubre AWS IoT Core. Amazon SQS desacopla aplicaciones con colas y Amazon Connect atiende llamadas y chat; ninguno gestiona una flota de dispositivos."},{tipo:"clave",items:["AWS IoT Core = conexión y administración de dispositivos IoT.","Registra la identidad de cada dispositivo y autentica su conexión.","Recibe mensajes por protocolos ligeros, como MQTT.","Enruta los mensajes a otros servicios con reglas, por ejemplo a AWS Lambda o Amazon S3."]}],preguntasGuia:["¿Qué servicio conecta y administra dispositivos IoT en AWS?","¿Cómo llegan las lecturas de los dispositivos al resto de la arquitectura?","¿Por qué no basta con una cola para gestionar dispositivos?"]}],4.1:[{id:"4.1-g1",titulo:"Opciones de compra de cómputo y cuándo usarlas",objetivos:["4.1#1","4.1#3"],bloques:[{tipo:"concepto",md:"Comprar capacidad de cómputo en la nube no es una sola decisión: es elegir el modelo de pago que encaje con la previsibilidad y la criticidad de la carga. Las opciones principales son:\n\n- **On-Demand Instances**: se paga por el tiempo de uso, sin compromiso ni pago por adelantado. Máxima flexibilidad y precio de lista.\n- **Reserved Instances (RI)**: compromiso de 1 o 3 años sobre atributos de instancia y una región o Availability Zone; a cambio, un descuento de hasta aproximadamente el 72 %. Las **Standard** dan el descuento máximo y no admiten cambios; las **Convertible** permiten intercambiar atributos con un descuento algo menor.\n- **Spot Instances**: capacidad sobrante ofrecida con descuentos de hasta el 90 %, pero interrumpible con dos minutos de aviso. Para cargas tolerantes a fallos.\n- **AWS Savings Plans**: compromiso de un gasto por hora durante 1 o 3 años. Los **Compute Savings Plans** cubren Amazon EC2, AWS Fargate y AWS Lambda en cualquier familia, sistema operativo y región; los **EC2 Instance Savings Plans** se limitan a una familia en una región y dan más descuento.\n- **Dedicated Hosts**: un servidor físico completo reservado para la cuenta, con visibilidad y control de sockets y núcleos, útil para licencias propias (BYOL).\n- **Dedicated Instances**: instancias que corren en hardware dedicado a un único cliente, sin control sobre la ubicación física del host ni facturación por host.\n- **Capacity Reservations**: reservan capacidad en una Availability Zone concreta sin compromiso de plazo; se paga la tarifa On-Demand por la capacidad reservada, se use o no.\n\nLa idea de fondo es intercambiar flexibilidad por descuento: cuanto más te comprometes o más aceptas interrupciones, menos pagas."},{tipo:"comparacion",parId:"savings-plans-vs-ri-vs-spot"},{tipo:"comparacion",parId:"on-demand-vs-dedicated-vs-capacity"},{tipo:"cuandoUsar",usar:["Usa On-Demand Instances para cargas nuevas, imprevisibles, de corta duración o en desarrollo y pruebas.","Usa Reserved Instances o Savings Plans para cargas estables que correrán de forma continua durante uno o más años.","Usa Spot Instances para procesamiento por lotes, renderizado o tareas stateless que toleran una interrupción con aviso.","Usa Dedicated Hosts cuando necesites control del host físico o traer tus propias licencias, y Capacity Reservations cuando debas garantizar capacidad en una Availability Zone concreta."],noUsar:["No compres compromisos de 1 o 3 años para cargas que puedes apagar o que aún no conoces: acabarías pagando por capacidad que no usas.","No ejecutes bases de datos transaccionales críticas en Spot Instances: la interrupción con dos minutos de aviso puede cortar el servicio."]},{tipo:"escenario",situacion:"Una empresa tiene dos cargas: un servicio web con tráfico estable que corre 24/7 desde hace dos años, y un proceso nocturno de conversión de vídeo que puede reintentarse sin problema si se interrumpe. Quiere reducir la factura sin cambiar la arquitectura.",analisis:"Para el servicio estable, un compromiso de 1 o 3 años (Reserved Instances o Savings Plans) recorta el precio de forma significativa porque el uso es predecible. Para el proceso nocturno, las Spot Instances aprovechan capacidad sobrante con el mayor descuento y su tolerancia a interrupciones encaja con el reintento.",servicio:"Amazon EC2"},{tipo:"errorComun",error:"Creer que el compromiso es siempre la opción más barata y contratar Reserved Instances o Savings Plans para cargas esporádicas o que se van a apagar.",correccion:"El compromiso solo ahorra si el uso se mantiene. En cargas intermitentes o desconocidas, las On-Demand Instances se ajustan mejor al consumo real y evitan pagar por capacidad comprometida sin usar."},{tipo:"clave",items:["On-Demand = pago por uso, sin compromiso; es el precio de referencia.","Reserved Instances y Savings Plans = compromiso de 1 o 3 años a cambio de descuento.","Spot = mayor descuento, pero la instancia puede interrumpirse.","Dedicated Hosts, Dedicated Instances y Capacity Reservations resuelven aislamiento físico o garantía de capacidad."]}],preguntasGuia:["¿Qué diferencia hay entre reservar descuento y reservar capacidad?","¿Cuándo conviene un compromiso de 1 o 3 años y cuándo no?","¿Qué cargas toleran Spot Instances y cuáles no?"]},{id:"4.1-g2",titulo:"Flexibilidad de las Reserved Instances y su comportamiento en AWS Organizations",objetivos:["4.1#4","4.1#5"],bloques:[{tipo:"concepto",md:"Una Reserved Instance (RI) no es rígida: su flexibilidad depende del tipo y del alcance.\n\n- **Alcance regional**: una RI regional aplica el descuento a cualquier Availability Zone de la región y no reserva capacidad física.\n- **Alcance zonal**: una RI zonal reserva capacidad en una Availability Zone concreta y su descuento solo aplica allí.\n- **Flexibilidad de tamaño**: dentro de la misma familia, región y sistema operativo Linux/Unix con tenancy compartida, una RI se normaliza y se reparte entre tamaños. Una RI de `m5.large` puede cubrir parte del uso de dos `m5.large` o de un `m5.xlarge`, según el factor de normalización.\n- **Standard frente a Convertible**: las Standard no se modifican ni se intercambian, pero dan el descuento máximo; las Convertible permiten cambiar familia, sistema operativo, tenancy o modalidad de pago por otra Convertible de valor igual o mayor, con un descuento algo menor.\n\nEn **AWS Organizations** el comportamiento es colectivo. La facturación consolidada agrupa a todas las cuentas y, por defecto, las RI y los Savings Plans comprados en cualquier cuenta se **comparten** con las demás: primero cubren el uso de la cuenta que los compró y el descuento sobrante se aplica al resto. La cuenta de administración puede desactivar esa compartición, cuenta por cuenta, en las preferencias de facturación."},{tipo:"cuandoUsar",usar:["Elige RI regionales cuando quieras que el descuento siga a las instancias, sea cual sea la Availability Zone donde se lancen.","Elige RI Convertible si prevés cambiar de familia, sistema operativo o tenancy dentro del plazo del compromiso.","Deja activada la compartición de RI y Savings Plans en AWS Organizations para que el descuento no usado en una cuenta reduzca la factura de las demás."],noUsar:["No esperes que una RI Standard cambie de familia ni de sistema operativo: para eso están las Convertible.","No cuentes con la flexibilidad de tamaño en sistemas operativos distintos de Linux/Unix ni con tenancy dedicada."]},{tipo:"ejemplo",md:"```text\nRI regional de m5.large (Linux/Unix, tenancy compartida)\n  -> cubre m5.large en cualquier Availability Zone de la región\n  -> su tamaño normalizado se reparte: una m5.large cubre la mitad (0,5)\n     de un m5.xlarge, por lo que harían falta dos para cubrirlo entero\n  -> una RI zonal solo cubre la AZ donde se compró\n\nOrganizations con uso compartido\n  cuenta A compra RI -> cubre primero su uso\n  sobra descuento     -> se aplica al uso de la cuenta B\n```"},{tipo:"errorComun",error:"Comprar RI Standard esperando poder cambiar de familia o de sistema operativo, o asumir que el descuento queda encerrado en la cuenta que lo compró.",correccion:"Las Standard no se modifican: si necesitas cambiar atributos, la opción es Convertible. Y en AWS Organizations el beneficio se comparte por defecto entre las cuentas, salvo que se desactive esa preferencia."}],preguntasGuia:["¿Qué puede cambiar una RI Convertible que una Standard no permite?","¿Cómo se reparte el descuento de una RI entre las cuentas de una organización?","¿En qué se diferencian una RI regional y una zonal?"]},{id:"4.1-g3",titulo:"Almacenamiento, niveles y costes de transferencia de datos",objetivos:["4.1#2","4.1#6","4.1#7"],bloques:[{tipo:"concepto",md:"Elegir almacenamiento es elegir el nivel de acceso y su coste. En **Amazon S3** las clases ordenan el precio según la frecuencia de acceso y la velocidad de recuperación:\n\n- **S3 Standard**: acceso frecuente, latencia de milisegundos, almacenamiento más caro.\n- **S3 Intelligent-Tiering**: mueve automáticamente los objetos entre niveles según su patrón de acceso.\n- **S3 Standard-IA** y **S3 One Zone-IA**: acceso poco frecuente con almacenamiento más barato, pero con cargo por recuperación; One Zone-IA guarda en una sola Availability Zone.\n- **Amazon S3 Glacier Instant Retrieval**, **Glacier Flexible Retrieval** y **Glacier Deep Archive**: archivo a largo plazo con almacenamiento muy barato y recuperación desde milisegundos hasta horas.\n\nEn **Amazon EBS** se paga por la capacidad aprovisionada mientras el volumen existe, aunque no esté conectado; en **Amazon EFS** se paga por datos almacenados. Las políticas de ciclo de vida mueven objetos entre clases para no pagar precio de acceso frecuente por datos que casi no se leen."},{tipo:"concepto",md:"Los costes de transferencia de datos siguen una regla general: entrar es barato, salir cuesta y cruzar fronteras también.\n\n- **Transferencia entrante (incoming)**: mover datos desde internet hacia AWS suele ser gratuita.\n- **Transferencia saliente (outgoing)**: sacar datos hacia internet se factura por GB, con tramos decrecientes.\n- **Entre Availability Zones de la misma región**: el tráfico que cruza de una AZ a otra se cobra por GB en los dos extremos.\n- **Entre regiones**: mover datos de una región a otra también se factura por GB.\n- **Dentro de la misma AZ**: el tráfico entre recursos de la misma AZ con direcciones privadas no genera ese cargo de cruce.\n\nPor eso el diseño importa: colocar en la misma AZ los componentes que más se comunican, o usar un endpoint privado, reduce la factura de red."},{tipo:"cuandoUsar",usar:["Usa S3 Standard para datos de acceso frecuente y S3 Intelligent-Tiering cuando el patrón de acceso es desconocido o cambiante.","Usa las clases de archivo para datos que deben conservarse mucho tiempo y casi nunca se leen.","Configura políticas de ciclo de vida para que los objetos bajen de nivel de forma automática.","Diseña para que el tráfico entre componentes cercanos no cruce Availability Zones ni regiones si no aporta valor."],noUsar:["No dejes en Standard datos que no se leen desde hace meses: pagarías de más por almacenamiento.","No asumas que todo el tráfico de red es gratis: la salida a internet y el cruce de AZ o de región se facturan."]},{tipo:"escenario",situacion:"Una empresa conserva registros de auditoría que debe mantener siete años, se consultan solo ante una inspección y hoy están en S3 Standard. Además, dos instancias de la misma aplicación en Availability Zones distintas se envían grandes volúmenes de datos cada noche.",analisis:"Los registros a largo plazo encajan en una clase de archivo como S3 Glacier Deep Archive, alcanzada con una política de ciclo de vida desde Standard. El tráfico nocturno entre AZ se reduce colocando en la misma Availability Zone los componentes que más colaboran o usando un endpoint, porque el cruce de AZ se cobra por GB en ambos sentidos.",servicio:"Amazon S3"},{tipo:"errorComun",error:"Pensar que toda la transferencia de datos saliente es gratuita o que los datos guardados en S3 dejan de costar cuando nadie los lee.",correccion:"La transferencia entrante a AWS suele ser gratuita, pero la saliente a internet y los cruces entre AZ o entre regiones se facturan por GB. Y en S3 se paga por GB almacenado al mes mientras el objeto exista, se lea o no."}],preguntasGuia:["¿Cómo se ordena el precio entre las clases de almacenamiento de objetos?","¿Qué transferencias de datos se facturan y cuáles no?","¿Cómo ayuda una política de ciclo de vida a reducir la factura?"]}],4.2:[{id:"4.2-g1",titulo:"Información de facturación y precios de los servicios de AWS",objetivos:["4.2#1","4.2#2"],bloques:[{tipo:"concepto",md:"La facturación en AWS se apoya en una consola de facturación y gestión de costos donde se consultan las facturas, el uso por servicio y los informes de costos. Desde esa consola se accede a la información de facturación y a las herramientas de análisis, y las dudas sobre cargos se resuelven con el soporte de AWS, que ofrece ayuda específica de facturación.\n\nPara el **soporte de facturación** existen varias vías:\n\n- **Consola de facturación y gestión de costos**: facturas, historial de pagos y desglose de uso por cuenta.\n- **AWS Support**: canal para abrir casos de facturación y revisar explicaciones de cargos.\n- **AWS Knowledge Center** y **AWS Support Center**: artículos y casos donde consultar dudas de facturación.\n\nLa **información de precios** es pública y se publica servicio a servicio: cada página de precios detalla las dimensiones que se cobran (cómputo por hora, almacenamiento por GB, transferencia de datos) y los modelos de compra disponibles. Para estimar el costo antes de crear recursos se usa **AWS Pricing Calculator**, que permite modelar una arquitectura, ajustar cantidades y obtener una estimación sin desplegar nada."},{tipo:"cuandoUsar",usar:["Consulta la consola de facturación cuando necesites entender de dónde viene un cargo o revisar facturas y pagos.","Usa AWS Pricing Calculator antes de desplegar para estimar el costo mensual de una arquitectura propuesta.","Revisa la página de precios del servicio concreto para entender qué dimensiones generan el cobro."],noUsar:["No uses una estimación como si fuera la factura final: los precios pueden cambiar y el uso real manda.","No abras un caso de soporte por cada duda de precios: la información pública de precios resuelve la mayoría de consultas."]},{tipo:"ejemplo",md:"```text\nPregunta -> recurso\n- ¿Por qué subió la factura este mes?      -> Consola de facturación y gestión de costos\n- ¿Cuánto costará la arquitectura nueva?    -> AWS Pricing Calculator\n- ¿Cómo se cobra este servicio?             -> Página de precios del servicio\n- ¿Duda sobre un cargo concreto?            -> AWS Support\n```"},{tipo:"errorComun",error:"Creer que el precio de un servicio es único y fijo, o que estimar con AWS Pricing Calculator equivale a la factura real.",correccion:"El precio depende de la región, de las dimensiones consumidas y del modelo de compra. AWS Pricing Calculator produce una estimación orientativa; la factura refleja el uso real y puede variar por descuentos o por cambios de precio."},{tipo:"clave",items:["La consola de facturación y gestión de costos reúne facturas, pagos, uso y análisis.","El soporte de facturación se atiende por AWS Support.","La información de precios es pública y se detalla por servicio.","AWS Pricing Calculator estima el costo antes de crear recursos."]}],preguntasGuia:["¿Dónde se consultan las facturas y el historial de pagos?","¿Qué recurso se usa para estimar el costo antes de desplegar?","¿Qué diferencia hay entre una estimación de precios y la factura real?"]},{id:"4.2-g2",titulo:"AWS Organizations, facturación consolidada y reparto de costos",objetivos:["4.2#3","4.2#7"],bloques:[{tipo:"concepto",md:"AWS Organizations permite administrar de forma centralizada varias cuentas de AWS como una sola unidad de gobierno. La cuenta de gestión crea la organización e incorpora a las demás cuentas como miembros; a partir de ahí se aplican políticas, se comparten recursos y se factura de forma conjunta.\n\nLa **facturación consolidada** reúne el uso de todas las cuentas miembro en una única factura pagada por la cuenta de gestión. Consolidar no es solo comodidad administrativa: el uso agregado puede alcanzar antes los descuentos por volumen y una sola factura simplifica el seguimiento.\n\nEl **reparto de costos** es el problema complementario: cuando las cuentas pertenecen a equipos, proyectos o entornos distintos, hay que atribuir cada cargo a su responsable. La organización aporta la estructura de cuentas como primer nivel de separación, y las etiquetas de asignación de costos completan la atribución dentro de cada cuenta."},{tipo:"escenario",situacion:"Una empresa tiene ocho equipos, cada uno con su propia cuenta de AWS, y quiere una sola factura, control centralizado y capacidad de saber cuánto gasta cada equipo.",analisis:"La organización resuelve la administración y la facturación: la cuenta de gestión recibe la factura consolidada y aplica gobierno sobre las cuentas miembro. La atribución por equipo se logra etiquetando los recursos y analizando los informes, no solo por tener cuentas separadas.",servicio:"AWS Organizations"},{tipo:"errorComun",error:"Pensar que la facturación consolidada reparte automáticamente el costo entre los equipos o que mezcla los recursos de todas las cuentas.",correccion:"Consolidar agrupa el uso y los cargos en una factura, pero no atribuye el gasto por sí sola ni fusiona los recursos: cada cuenta conserva los suyos y sus propios límites. El reparto requiere etiquetas de asignación de costos e informes."},{tipo:"cuandoUsar",usar:["Usa AWS Organizations cuando necesites administrar muchas cuentas como una unidad de gobierno y una sola factura consolidada.","Usa la facturación consolidada para alcanzar antes los descuentos por volumen con el uso agregado de todas las cuentas.","Combina Organizations con etiquetas de asignación de costos para atribuir el gasto a cada equipo."],noUsar:["No esperes que la facturación consolidada reparta el gasto por equipo ni fusione los recursos: cada cuenta conserva los suyos y sus límites.","No creas que consolidar exime del pago: agrupa la factura, no perdona el consumo de ninguna cuenta.","No uses Organizations como sustituto del control de acceso por persona: eso corresponde a IAM o IAM Identity Center."]},{tipo:"clave",items:["AWS Organizations administra varias cuentas como una unidad.","La facturación consolidada produce una sola factura para todas las cuentas miembro.","Consolidar puede mejorar los descuentos por volumen, pero no asigna el gasto automáticamente.","La atribución por equipo o proyecto requiere etiquetas de asignación de costos."]}],preguntasGuia:["¿Qué permite hacer AWS Organizations con varias cuentas?","¿Qué es la facturación consolidada y qué no hace?","¿Cómo se atribuye el gasto a cada equipo dentro de una organización?"]},{id:"4.2-g3",titulo:"Etiquetas de asignación de costos e informes de facturación",objetivos:["4.2#4","4.2#8"],bloques:[{tipo:"concepto",md:"Las **etiquetas de asignación de costos** son pares clave-valor que se aplican a los recursos y que permiten desglosar la factura por criterios de negocio: centro de costo, equipo, proyecto, entorno o aplicación. Sin etiquetas, el análisis de costos queda limitado a la cuenta y al servicio.\n\nHay dos tipos según su origen:\n\n- **Etiquetas generadas automáticamente**: las crea la plataforma para cada recurso, por ejemplo un identificador de recurso o el servicio que lo creó.\n- **Etiquetas definidas por el usuario**: las crean y asignan las personas, con las claves y los valores que el negocio necesite.\n\nEl **informe de costos y uso** (AWS Cost and Usage Report) es el informe más detallado de facturación: incluye cada línea de uso con sus etiquetas activadas, de modo que se puede cruzar el gasto con los criterios de negocio. La relación es directa: las etiquetas aportan el criterio y el informe aporta el detalle. Para que una etiqueta aparezca en el informe hay que **activarla** como etiqueta de asignación de costos."},{tipo:"ejemplo",md:"```text\nSin etiquetas:\n  factura -> por cuenta y por servicio\n\nCon etiquetas de asignación de costos activadas:\n  factura -> por equipo, proyecto y entorno\n\nEn el informe de costos y uso:\n  cada línea de uso -> incluye los valores de las etiquetas activadas\n```"},{tipo:"errorComun",error:"Creer que basta con etiquetar los recursos: si la etiqueta no se activa como etiqueta de asignación de costos, no aparece en los informes de facturación.",correccion:"Primero se aplican las etiquetas a los recursos y después se activan como etiquetas de asignación de costos. Solo entonces se pueden usar para filtrar y agrupar en los informes; las etiquetas no activadas no se propagan a los datos de facturación."},{tipo:"cuandoUsar",usar:["Usa etiquetas de asignación de costos cuando necesites desglosar la factura por equipo, proyecto, entorno o centro de costo.","Activa la etiqueta como etiqueta de asignación de costos para que aparezca en los informes de facturación.","Usa el informe de costos y uso cuando necesites el detalle línea a línea con las etiquetas activadas."],noUsar:["No esperes que activar una etiqueta cambie cargos ya facturados: la asignación no es retroactiva.","No uses etiquetas como control de seguridad: son metadatos de gestión, no permisos de acceso.","No trates el informe de costos y uso como un panel en tiempo real: es un informe detallado, con su propia latencia de entrega."]},{tipo:"clave",items:["Etiquetas de asignación de costos = pares clave-valor para desglosar el gasto por criterio de negocio.","Tipos según su origen: generadas automáticamente y definidas por el usuario.","Hay que activarlas como etiquetas de asignación de costos para que aparezcan en la facturación.","El informe de costos y uso es el detalle que incluye cada línea de uso con sus etiquetas."]}],preguntasGuia:["¿Qué son las etiquetas de asignación de costos?","¿Qué tipos de etiquetas existen según su origen?","¿Cómo llegan las etiquetas al informe de costos y uso?"]},{id:"4.2-g4",titulo:"AWS Budgets, AWS Cost Explorer y AWS Pricing Calculator",objetivos:["4.2#5","4.2#6"],bloques:[{tipo:"concepto",md:"AWS ofrece herramientas distintas para momentos distintos del ciclo de costos:\n\n- **AWS Pricing Calculator**: estima antes de desplegar. Modela una arquitectura, se ajustan cantidades y se obtiene una estimación del costo mensual sin crear recursos. Responde a «¿cuánto costará?».\n- **AWS Cost Explorer**: analiza el gasto ya realizado. Muestra el costo y el uso históricos, permite agrupar y filtrar por servicio, cuenta o etiqueta y explorar tendencias. Responde a «¿en qué se está gastando?».\n- **AWS Budgets**: vigila contra un umbral. Se define un presupuesto y se configuran alertas cuando el gasto real o previsto se acerca o supera el límite. Responde a «¿me estoy pasando?».\n\nLos tres no compiten: se complementan. Se estima con AWS Pricing Calculator, se analiza lo gastado con AWS Cost Explorer y se vigila el límite con AWS Budgets. Confundirlos lleva a usar una estimación como si fuera un análisis histórico o a esperar que una alerta de presupuesto explique el detalle del gasto."},{tipo:"comparacion",parId:"budgets-vs-cost-explorer-vs-pricing-calculator"},{tipo:"escenario",situacion:"Una empresa fijó un límite mensual de gasto para su entorno de pruebas. El equipo quiere recibir un aviso antes de superarlo y, cuando ocurra, entender qué servicio lo provocó.",analisis:"La vigilancia del umbral corresponde a AWS Budgets: se define el presupuesto y una alerta que se dispara al acercarse o superar el límite. El análisis posterior del gasto por servicio corresponde a AWS Cost Explorer, que desglosa el uso ya realizado.",servicio:"AWS Budgets"},{tipo:"errorComun",error:"Usar AWS Cost Explorer como si fuera una calculadora de precios para estimar una arquitectura que todavía no existe.",correccion:"AWS Cost Explorer analiza el costo y el uso ya registrados; no proyecta arquitecturas futuras. Para estimar antes de desplegar se usa AWS Pricing Calculator. La estimación previa y el análisis histórico son funciones distintas."},{tipo:"cuandoUsar",usar:["Usa AWS Pricing Calculator para estimar el costo de una arquitectura que todavía no existe.","Usa AWS Cost Explorer para analizar el gasto ya realizado y ver tendencias por servicio, cuenta o etiqueta.","Usa AWS Budgets para vigilar un umbral y recibir alertas cuando el gasto real o previsto se acerque al límite."],noUsar:["No esperes que AWS Budgets detenga el gasto por sí solo: alerta cuando se cruza el umbral, pero no bloquea recursos.","No uses AWS Cost Explorer para estimar una arquitectura futura: solo analiza lo ya registrado.","No uses AWS Pricing Calculator para auditar la factura real: es una estimación previa, no un historial.","No confundas la previsión de Cost Explorer con una garantía de la factura final."]},{tipo:"clave",items:["AWS Pricing Calculator estima el costo futuro; AWS Cost Explorer analiza el gasto pasado.","AWS Budgets define un límite y dispara alertas cuando el gasto se acerca o supera el umbral.","Los tres se complementan: estimar, analizar y vigilar.","Ninguna alerta de presupuesto sustituye al análisis detallado del gasto."]}],preguntasGuia:["¿Qué herramienta se usa antes de desplegar y cuál después?","¿En qué se diferencian AWS Budgets y AWS Cost Explorer?","¿Qué papel cumple AWS Pricing Calculator en una propuesta de arquitectura?"]}],4.3:[{id:"4.3-g1",titulo:"Recursos y documentación en los sitios oficiales de AWS",objetivos:["4.3#1","4.3#5","4.3#6"],bloques:[{tipo:"concepto",md:"Los **sitios oficiales de AWS** son la fuente autoritativa para aprender y verificar información técnica. Cada recurso cubre una necesidad distinta:\n\n- **Documentación de AWS**: referencia de cada servicio con su API, sus límites y sus permisos; es el punto de consulta para confirmar el comportamiento exacto.\n- **Whitepapers**: documentos de arquitectura, seguridad y economía que explican el «por qué» de un diseño y recogen buenas prácticas.\n- **Blogs de AWS**: anuncios, novedades y casos prácticos publicados por los equipos de AWS.\n- **AWS Knowledge Center**: respuestas breves a preguntas frecuentes y pasos de solución de problemas.\n- **AWS Prescriptive Guidance**: estrategias, patrones y guías de implementación para migrar, modernizar y operar.\n- **AWS re:Post**: comunidad de preguntas y respuestas donde participan expertos de AWS y otros clientes.\n\nLa regla práctica es elegir el recurso según la pregunta: comportamiento exacto → documentación; decisión de arquitectura → whitepaper o AWS Prescriptive Guidance; problema concreto → AWS Knowledge Center o AWS re:Post."},{tipo:"cuandoUsar",usar:["Usa la documentación del servicio cuando necesites confirmar límites, parámetros o permisos exactos antes de implementar.","Usa un whitepaper o AWS Prescriptive Guidance cuando tengas que decidir una arquitectura, una estrategia de migración o un patrón de operación.","Usa AWS Knowledge Center o AWS re:Post cuando tengas un problema concreto y busques pasos de solución o experiencias de otros usuarios."],noUsar:["No bases una decisión técnica en fuentes no oficiales sin contrastarla con documentación vigente del servicio.","No uses AWS re:Post como sustituto de un caso de soporte cuando necesitas que AWS actúe sobre tu cuenta."]},{tipo:"comparacion",parId:"documentacion-oficial-vs-comunidad-y-guias"},{tipo:"errorComun",error:"Confundir AWS re:Post, que es una comunidad de preguntas y respuestas, con el AWS Support Center, que es el canal formal para abrir y gestionar casos de soporte.",correccion:"AWS re:Post sirve para consultar y compartir conocimiento con la comunidad; el AWS Support Center se usa cuando se necesita asistencia de AWS sobre la cuenta, con seguimiento y tiempos de respuesta comprometidos según el plan de soporte."},{tipo:"ejemplo",md:"```text\nPregunta -> recurso oficial recomendado\nComportamiento exacto de una API        -> documentación de AWS\nDecisión de arquitectura o migración    -> whitepaper / AWS Prescriptive Guidance\nDuda frecuente con pasos de solución    -> AWS Knowledge Center\nExperiencia de otros clientes           -> AWS re:Post\nIncidente sobre mi cuenta               -> AWS Support Center (caso de soporte)\n```"}],preguntasGuia:["¿Qué recurso oficial conviene para verificar el comportamiento exacto de un servicio?","¿En qué se diferencian un whitepaper y la documentación de referencia?","¿Cuándo conviene usar AWS re:Post y cuándo abrir un caso en el AWS Support Center?"]},{id:"4.3-g2",titulo:"Planes de soporte de AWS y opciones para clientes",objetivos:["4.3#2","4.3#7"],bloques:[{tipo:"concepto",md:"**AWS Support** ofrece varios planes que se escalonan según la asistencia que necesita el cliente:\n\n- **Basic Support**: incluido sin coste en toda cuenta. Da acceso a documentación, whitepapers, AWS re:Post, el AWS Health Dashboard y las comprobaciones básicas de AWS Trusted Advisor. No incluye casos técnicos: solo permite consultas de facturación y cuenta.\n- **AWS Developer Support**: asistencia técnica por correo en horario laboral, con un contacto designado y tiempos de respuesta de negocio; pensado para desarrollo y pruebas.\n- **AWS Business Support**: asistencia 24/7 por teléfono, chat y correo, todas las comprobaciones de AWS Trusted Advisor y tiempos de respuesta más cortos; adecuado para producción.\n- **AWS Enterprise On-Ramp Support**: para cargas moderadas que necesitan guía proactiva, con acceso a un grupo de Technical Account Managers (TAM).\n- **AWS Enterprise Support**: el nivel más completo, con TAM designado, revisión proactiva de la arquitectura y el menor tiempo de respuesta para sistemas críticos.\n\nMás allá de los planes, el cliente dispone de asistencia técnica con **AWS Professional Services** y los **AWS solutions architects** para proyectos de diseño e implementación.\n\nAWS reorganiza periódicamente la familia de planes: renombra niveles y añade capacidades al nivel superior. Por eso lo evaluable no es memorizar la lista, sino la relación entre el nivel de soporte y estas dimensiones: canal y horario de atención, tiempo de respuesta por severidad, Technical Account Manager designado o compartido, revisión proactiva de la arquitectura y alcance de las comprobaciones de AWS Trusted Advisor. El exam guide vigente nombra AWS Developer Support, AWS Business Support, AWS Enterprise On-Ramp Support y AWS Enterprise Support; si al consultar la página actual ves otros nombres, la lógica de escalado es la misma."},{tipo:"comparacion",parId:"planes-de-soporte-aws"},{tipo:"escenario",situacion:"Una empresa ejecuta una plataforma de ventas que debe estar disponible 24/7. Necesita abrir casos por teléfono a cualquier hora, una respuesta en menos de una hora ante una caída de producción y revisar su arquitectura para optimizar costos.",analisis:"La carga es de producción y exige canales 24/7, tiempos de respuesta cortos y comprobaciones completas de AWS Trusted Advisor: encaja con **AWS Business Support**. AWS Developer Support se limita al horario laboral y a un contacto, y AWS Enterprise Support está pensado para organizaciones que además requieren un TAM designado y compromisos más estrictos.",servicio:"AWS Support"},{tipo:"errorComun",error:"Creer que Basic Support incluye casos técnicos o que AWS Developer Support ofrece atención telefónica 24/7.",correccion:"Basic Support solo cubre facturación y cuenta, sin casos técnicos. La atención 24/7 por teléfono empieza en AWS Business Support; AWS Developer Support se apoya en correo y horario laboral."},{tipo:"clave",items:["Basic Support: incluido, sin casos técnicos; cubre facturación, cuenta y comunidad.","AWS Developer Support: correo en horario laboral, pensado para desarrollo y pruebas.","AWS Business Support: 24/7 por teléfono, chat y correo, con todas las comprobaciones de AWS Trusted Advisor.","AWS Enterprise On-Ramp Support: guía proactiva y acceso a un grupo de TAM para cargas moderadas.","AWS Enterprise Support: TAM designado y los tiempos de respuesta más cortos."]}],preguntasGuia:["¿Qué incluye Basic Support y qué no incluye?","¿Qué diferencia hay entre AWS Business Support y AWS Enterprise Support?","¿Cuándo es suficiente AWS Developer Support?"]},{id:"4.3-g3",titulo:"El AWS Support Center y la asistencia técnica",objetivos:["4.3#4","4.3#13"],bloques:[{tipo:"concepto",md:"El **AWS Support Center** es el panel donde se crean, se consultan y se gestionan los casos de soporte de la cuenta. Desde él se elige la severidad del caso, se sigue su estado y se ve el historial; también sirve como punto de entrada a AWS Trusted Advisor y al AWS Health Dashboard.\n\nLa asistencia técnica de AWS va más allá de los casos:\n\n- **AWS Support plans**: definen canales, tiempos de respuesta y alcance del soporte continuo.\n- **AWS Professional Services**: equipo de consultoría que acompaña proyectos concretos, como migraciones o modernizaciones.\n- **AWS solutions architects**: especialistas que ayudan a diseñar arquitecturas bien construidas y a elegir servicios.\n- **AWS Knowledge Center** y **AWS re:Post**: recursos de autoservicio para resolver dudas sin abrir un caso."},{tipo:"cuandoUsar",usar:["Abre un caso en el AWS Support Center cuando necesites que AWS investigue o actúe sobre un recurso de tu cuenta.","Acude a AWS Professional Services o a los AWS solutions architects cuando el reto sea un proyecto de diseño, migración o modernización, no un incidente puntual.","Resuelve dudas generales con el AWS Knowledge Center o AWS re:Post antes de abrir un caso."],noUsar:["No uses el AWS Support Center para pedir consultoría estratégica: para eso están AWS Professional Services y los AWS solutions architects.","No esperes que AWS Professional Services sustituya al soporte continuo de un plan de soporte."]},{tipo:"errorComun",error:"Intentar resolver un incidente que requiere intervención de AWS solo con publicaciones en AWS re:Post, sin abrir un caso en el AWS Support Center.",correccion:"AWS re:Post es autoservicio comunitario y no garantiza seguimiento ni tiempos de respuesta. Cuando el problema afecta a la cuenta o a un recurso en producción, hay que abrir un caso en el AWS Support Center conforme al plan contratado."},{tipo:"ejemplo",md:"```text\nNecesidad -> punto de entrada\nGestionar un incidente de mi cuenta   -> AWS Support Center\nConsulta rápida de autoservicio      -> AWS Knowledge Center / AWS re:Post\nProyecto de migración con AWS        -> AWS Professional Services\nDiseñar una arquitectura nueva       -> AWS solutions architects\n```"}],preguntasGuia:["¿Para qué sirve el AWS Support Center y qué se gestiona desde él?","¿Cuándo conviene recurrir a AWS Professional Services en lugar de abrir un caso?","¿Qué aportan los AWS solutions architects a un cliente?"]},{id:"4.3-g4",titulo:"Trusted Advisor, AWS Health Dashboard y AWS Health API",objetivos:["4.3#8"],bloques:[{tipo:"concepto",md:"**AWS Trusted Advisor** es una herramienta que inspecciona el entorno y compara la configuración con las buenas prácticas de AWS. Emite recomendaciones en cinco categorías: **optimización de costos**, seguridad, tolerancia a fallos, rendimiento y cuotas de servicio. Es la referencia para detectar recursos infrautilizados o gastos innecesarios.\n\nEl **AWS Health Dashboard** ofrece una vista personalizada del estado de los servicios de AWS y de los eventos que afectan a los recursos concretos de la cuenta, no solo el estado global.\n\nLa **AWS Health API** permite acceder por programación a esa información de salud para automatizar alertas y flujos de trabajo.\n\nLos tres recursos comparten el mismo objetivo: dar visibilidad para operar y optimizar entornos. Las comprobaciones básicas de AWS Trusted Advisor están en todos los planes; las completas requieren un plan de soporte de negocio o superior, y la AWS Health API también exige ese nivel."},{tipo:"escenario",situacion:"Un equipo de finanzas observa que la factura mensual creció sin un aumento claro de tráfico. El equipo técnico revisa la cuenta y busca recomendaciones concretas para reducir el gasto sin rehacer la arquitectura.",analisis:"AWS Trusted Advisor es el recurso adecuado: entre sus comprobaciones de optimización de costos señala instancias infrautilizadas, recursos sin usar y direcciones IP elásticas ociosas. La AWS Health API complementa la operación al permitir automatizar el seguimiento de eventos, pero no genera recomendaciones de ahorro.",servicio:"AWS Trusted Advisor"},{tipo:"errorComun",error:"Esperar que AWS Trusted Advisor aplique cambios automáticamente o que el AWS Health Dashboard sustituya a la monitorización de los recursos.",correccion:"AWS Trusted Advisor solo recomienda; los cambios los decide y los ejecuta el cliente. El AWS Health Dashboard informa de eventos de los servicios de AWS que afectan a la cuenta, mientras que las métricas y alarmas de los recursos se gestionan con las herramientas de monitorización correspondientes."},{tipo:"comparacion",parId:"trusted-advisor-vs-health-dashboard-y-api"},{tipo:"cuandoUsar",usar:["Usa AWS Trusted Advisor para obtener recomendaciones de configuración y ahorro por categorías.","Usa el AWS Health Dashboard para ver el estado de los servicios de AWS y los eventos que afectan a tus recursos.","Usa la AWS Health API cuando necesites consumir esa información de salud de forma programática y automatizar alertas."],noUsar:["No uses AWS Trusted Advisor para vigilar métricas o alarmas en tiempo real: eso es Amazon CloudWatch.","No uses el AWS Health Dashboard como sistema de monitorización de tus propios recursos: informa de eventos de AWS, no de tus métricas.","No esperes que la AWS Health API aplique cambios por sí sola: expone la información para que tú automatices la reacción.","No cuentes con las comprobaciones completas de Trusted Advisor ni con la API de salud si el plan de soporte no las incluye."]},{tipo:"clave",items:["AWS Trusted Advisor recomienda en cinco categorías, incluida la optimización de costos.","Las comprobaciones completas de AWS Trusted Advisor dependen del plan de soporte.","El AWS Health Dashboard muestra los eventos de AWS que afectan a tus recursos.","La AWS Health API expone esa información de salud para automatizarla."]}],preguntasGuia:["¿En qué categorías emite recomendaciones AWS Trusted Advisor?","¿Qué diferencia hay entre el estado global de AWS y el AWS Health Dashboard?","¿Para qué sirve la AWS Health API?"]},{id:"4.3-g5",titulo:"Partners de AWS, AWS Marketplace y AWS Trust and Safety",objetivos:["4.3#3","4.3#9","4.3#10","4.3#11","4.3#12"],bloques:[{tipo:"concepto",md:"El **AWS Partner Network (APN)** agrupa a las organizaciones que ayudan a los clientes a adoptar AWS:\n\n- **Consulting partners** o **system integrators**: consultoras e integradores que diseñan, migran y operan soluciones para los clientes.\n- **Technology partners** o **independent software vendors (ISV)**: empresas que construyen productos de software y los ofrecen a través de AWS.\n\nSer partner aporta beneficios como formación y certificación de partners, acceso a eventos de partners y descuentos por volumen en los programas que los ofrecen.\n\n**AWS Marketplace** es el catálogo digital donde los clientes descubren, compran y despliegan software, datos y servicios de terceros. Sus servicios clave incluyen la **gestión de costos**, con facturación consolidada en la factura de AWS, y la **gobernanza y los derechos de uso**, que controlan qué soluciones se adquieren y quién puede desplegarlas.\n\nPor último, el equipo de **AWS Trust and Safety** es el canal para denunciar el uso abusivo de recursos de AWS, por ejemplo spam, phishing o contenido ilícito."},{tipo:"cuandoUsar",usar:["Acude a un consulting partner o system integrator cuando necesites experiencia externa para migrar u operar una carga en AWS.","Busca un independent software vendor o su producto en AWS Marketplace cuando quieras adquirir software de terceros con facturación consolidada.","Consulta el AWS Partner Network cuando quieras conocer programas, formación y descuentos para partners."],noUsar:["No uses el AWS Partner Network para comprar software: el catálogo de compra es AWS Marketplace.","No uses el equipo de AWS Trust and Safety para incidencias técnicas de tus recursos; ese canal es para denunciar abuso."]},{tipo:"escenario",situacion:"Una empresa quiere migrar un sistema heredado y no tiene personal con experiencia en AWS. Además, prefiere comprar el software de seguridad de un proveedor externo y unificar el pago en la factura de AWS.",analisis:"El proyecto de migración encaja con un consulting partner o system integrator del AWS Partner Network, que aporta experiencia y metodología. El software de seguridad se adquiere a un independent software vendor a través de AWS Marketplace, donde la facturación se consolida y se aplican controles de gobernanza y derechos de uso.",servicio:"AWS Marketplace"},{tipo:"errorComun",error:"Confundir el AWS Partner Network con AWS Marketplace y creer que AWS Trust and Safety ofrece soporte técnico.",correccion:"El AWS Partner Network es el programa de partners, con consultoras e ISV; AWS Marketplace es el catálogo digital donde se compran sus soluciones. AWS Trust and Safety gestiona denuncias de abuso de recursos de AWS, no incidencias técnicas de la cuenta."},{tipo:"comparacion",parId:"partners-y-marketplace-vs-canales-de-soporte"},{tipo:"clave",items:["AWS Partner Network: consulting partners (system integrators) y technology partners (ISV).","Beneficios de ser partner: formación y certificación, eventos y descuentos por volumen.","AWS Marketplace clave: gestión de costos y gobernanza con derechos de uso.","AWS Trust and Safety: denunciar el abuso de recursos de AWS."]}],preguntasGuia:["¿Qué tipos de partner participan en el AWS Partner Network?","¿Qué diferencia hay entre un system integrator y un independent software vendor?","¿Qué servicios clave ofrece AWS Marketplace?"]}]},i={1.1:[{id:"1.1-q1",taskId:"1.1",objetivos:["1.1#1"],tipo:"conocimiento",question:"¿Qué significa que la nube de AWS convierta gasto fijo en gasto variable?",options:["Que la empresa compra la capacidad por adelantado y la amortiza durante varios años.","Que la capacidad se dimensiona una vez para el pico y se mantiene después.","Que el gasto sigue al consumo real y no exige inversión inicial en infraestructura.","Que el precio unitario de cada servicio permanece constante aunque cambie el uso."],correctAnswer:2,explanation:"El gasto variable sigue al consumo: si el recurso no se usa, no se paga, y no hay inversión inicial en servidores. Las otras opciones describen justo el modelo contrario (capex), una capacidad fija dimensionada para el pico o un precio que no depende del uso. Si el requisito exigiera capacidad reservada y pagada por adelantado, el gasto volvería a comportarse en parte como fijo (Reserved Instances o Savings Plans).",porQueOpcion:["Incorrecta: comprar capacidad por adelantado y amortizarla es el modelo de gasto fijo (capex) que la nube sustituye.","Incorrecta: dimensionar una sola vez para el pico deja capacidad ociosa y mantiene el gasto acoplado a la inversión, no al consumo.","Correcta: el gasto variable sigue al consumo real y evita la inversión inicial en infraestructura.","Incorrecta: que el precio unitario sea constante no convierte el gasto en variable, que depende del uso y no de la tarifa."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.1-q2",taskId:"1.1",objetivos:["1.1#1"],tipo:"escenario",question:"Una empresa, aunque su presupuesto sea limitado, compra servidores cada tres años para cubrir su pico de tráfico y el resto del tiempo los mantiene infrautilizados. ¿Qué beneficio de la nube de AWS responde directamente a ese problema?",options:["La posibilidad de fijar de antemano el precio de los servicios y evitar cualquier sorpresa en la factura mensual.","El pago por uso con capacidad ajustada a la demanda, que evita la capacidad ociosa.","La obligación de mantener el mismo número de servidores siempre encendidos.","El traslado de todo el gasto a una única factura mensual consolidada."],correctAnswer:1,explanation:"La capacidad ociosa desaparece cuando se paga solo por lo consumido y la capacidad sigue a la demanda. Ese es el beneficio central de la propuesta de valor frente al modelo de compra para el pico. Si el requisito fuera solo fijar los precios de antemano, no se resolvería el problema de la capacidad infrautilizada que describe el escenario.",porQueOpcion:["Incorrecta: fijar precios de antemano no elimina la capacidad ociosa, que es el problema del escenario.","Correcta: el pago por uso ajusta la capacidad a la demanda y evita la capacidad ociosa del pico.","Incorrecta: mantener siempre el mismo número de servidores encendidos reproduce el sobredimensionamiento que se quiere evitar.","Incorrecta: consolidar la factura es una ventaja de gestión de costes, no una solución a la infrautilización."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.1-q3",taskId:"1.1",objetivos:["1.1#2"],tipo:"conocimiento",question:"¿Qué beneficios aporta la infraestructura global de AWS a la hora de lanzar una aplicación?",options:["Que permite desplegar en minutos en la región adecuada y servir a usuarios de varios continentes.","Que garantiza que la aplicación no sufre ninguna interrupción, en ninguna región, durante todo el año.","Que distribuye automáticamente los datos entre todos los países donde hay usuarios registrados.","Que abarata el coste porque los recursos se compran a escala mundial."],correctAnswer:0,explanation:"La infraestructura global aporta velocidad de despliegue (recursos en minutos) y alcance global (cobertura geográfica amplia). «No sufrir interrupciones» es alta disponibilidad, «distribuir datos por países» es una decisión de residencia y replicación que el cliente toma, y el descuento por escala es economía de la nube, no infraestructura global. Si el requisito fuera residencia de datos, la respuesta correcta pasaría a ser elegir y fijar la Región.",porQueOpcion:["Correcta: la infraestructura global permite desplegar en minutos en la región adecuada y atender usuarios de varios continentes.","Incorrecta: la ausencia total de interrupciones es alta disponibilidad, no un beneficio garantizado de la infraestructura global.","Incorrecta: la distribución de datos entre países es una decisión de residencia y replicación del cliente, no algo automático.","Incorrecta: el menor coste por escala es una economía de la nube, no un beneficio geográfico de la infraestructura global."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.1-q4",taskId:"1.1",objetivos:["1.1#2"],tipo:"servicio",question:"Un equipo quiere acercar las descargas de contenido a usuarios repartidos por el mundo. ¿Qué componente de la infraestructura global aprovecha?",options:["Una Availability Zone aislada dentro de la Región donde corre la aplicación.","Un volumen de almacenamiento replicado de forma automática entre varias Regiones cercanas.","Un plan de compra con descuento por compromiso de uso.","Una ubicación de borde (edge location) que entrega el contenido cerca del usuario."],correctAnswer:3,explanation:"Las ubicaciones de borde acercan la entrega de contenido al usuario y reducen la latencia. Una Availability Zone aísla fallos dentro de una Región, la replicación entre Regiones protege el dato y busca continuidad, y el descuento por compromiso afecta al precio, no a la cercanía. Si el requisito fuera aislar la carga frente al fallo de una zona, la respuesta sería desplegar en varias Availability Zones.",porQueOpcion:["Incorrecta: una Availability Zone aísla fallos dentro de una Región, pero no acerca el contenido a usuarios repartidos por el mundo.","Incorrecta: replicar un volumen entre Regiones protege el dato y busca continuidad, no la entrega cercana al usuario.","Incorrecta: el descuento por compromiso de uso afecta al precio, no a la latencia de entrega.","Correcta: la ubicación de borde entrega el contenido cerca del usuario y reduce la latencia."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.1-q5",taskId:"1.1",objetivos:["1.1#3"],tipo:"conocimiento",question:"¿Qué describe mejor la elasticidad en la nube de AWS?",options:["Mantener el servicio operativo y sin interrupciones cuando falla por completo una zona.","Ajustar la capacidad de forma automática a la demanda, creciendo y decreciendo.","Crear recursos en varios continentes a la vez.","Reducir la factura mediante descuentos por volumen contratado."],correctAnswer:1,explanation:"La elasticidad ajusta la capacidad al volumen de trabajo: se añaden recursos cuando sube la demanda y se retiran cuando baja. Mantener el servicio ante fallos es alta disponibilidad, no elasticidad. Si el requisito fuera resistir el fallo de una zona, la respuesta correcta sería la alta disponibilidad.",porQueOpcion:["Incorrecta: seguir operando ante el fallo de una zona es alta disponibilidad, no elasticidad.","Correcta: la elasticidad ajusta automáticamente la capacidad a la demanda, creciendo y decreciendo.","Incorrecta: crear recursos en varios continentes es alcance global, no elasticidad.","Incorrecta: los descuentos por volumen son coste y precio, no ajuste automático de capacidad."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.1-q6",taskId:"1.1",objetivos:["1.1#3"],tipo:"comparacion",question:"Un equipo debate tres ventajas de la nube. ¿Qué afirmación distingue correctamente alta disponibilidad, elasticidad y agilidad?",options:["Las tres significan lo mismo: crecer en capacidad cuando hay más usuarios.","La alta disponibilidad evita interrupciones ante fallos, la elasticidad ajusta la capacidad a la demanda y la agilidad acelera la creación y el cambio.","La agilidad mide el tiempo de actividad y de funcionamiento; la elasticidad, el número de regiones desplegadas; y la alta disponibilidad, el precio por hora de los recursos.","La elasticidad garantiza la continuidad; la alta disponibilidad reduce el tiempo de innovación."],correctAnswer:1,explanation:"Cada ventaja responde a un problema distinto: alta disponibilidad = seguir operando pese a fallos; elasticidad = capacidad según la demanda; agilidad = velocidad para crear, probar y cambiar. Si el escenario pidiera las tres por separado, igual que aquí, conviene definirlas sin mezclarlas.",porQueOpcion:["Incorrecta: las tres ventajas responden a problemas distintos, no son sinónimos de crecer en capacidad.","Correcta: distingue bien alta disponibilidad ante fallos, elasticidad según demanda y agilidad para crear y cambiar.","Incorrecta: invierte las definiciones y atribuye a la elasticidad el número de regiones y a la alta disponibilidad el precio.","Incorrecta: intercambia los papeles: la continuidad es alta disponibilidad y la velocidad de innovación es agilidad."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.1-q7",taskId:"1.1",objetivos:["1.1#3"],tipo:"escenario",question:"Una tienda en línea recibe un pico de tráfico durante una campaña y luego vuelve al nivel habitual, sin embargo la latencia se mantiene estable todo el año. ¿Qué ventaja de la nube responde mejor a esa situación?",options:["La agilidad, porque permite rediseñar la aplicación durante la campaña y publicar mejoras en plena promoción.","La elasticidad, porque la capacidad crece con la demanda y se reduce al bajar el tráfico.","La alta disponibilidad, porque garantiza que la campaña no se interrumpa.","Las economías de escala, porque reparten el coste entre todos los clientes."],correctAnswer:1,explanation:"Un pico temporal seguido de un valle es el caso típico de elasticidad: ajustar la capacidad al uso. La alta disponibilidad se ocupa de los fallos y la agilidad, de la velocidad de cambio. Si el requisito fuera evitar cortes durante la campaña, la respuesta sería la alta disponibilidad.",porQueOpcion:["Incorrecta: la agilidad permite rediseñar y publicar cambios, no absorber por sí sola un pico temporal de tráfico.","Correcta: la elasticidad crece con la demanda y se reduce al bajar el tráfico, encajando con el pico de la campaña.","Incorrecta: la alta disponibilidad protege frente a fallos, no dimensiona la capacidad para un pico de demanda.","Incorrecta: las economías de escala reducen el precio unitario, no ajustan la capacidad al pico temporal."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.1-q8",taskId:"1.1",objetivos:["1.1#1"],tipo:"casoDeUso",question:"¿Cuál de los siguientes escenarios ilustra mejor la propuesta de valor de la nube de AWS frente a un centro de datos propio?",options:["Provisionar recursos en minutos, pagar por uso y ajustar la capacidad a la demanda.","Comprar capacidad para el pico y mantenerla contratada aunque el proyecto se cancele.","Construir un centro de datos en cada país donde haya clientes.","Trasladar todo el gasto a una única factura mensual consolidada."],correctAnswer:0,explanation:"La propuesta de valor combina velocidad de aprovisionamiento, pago por uso y ajuste a la demanda. Comprar capacidad para el pico o construir centros de datos reproduce el modelo que la nube evita, y consolidar la factura es una ventaja de gestión de costes, no la propuesta de valor. Si el escenario pidiera demostrar solo la reducción de esfuerzo operativo, la respuesta seguiría siendo la nube, pero el foco sería la operación delegada y no la elasticidad.",porQueOpcion:["Correcta: combina velocidad de aprovisionamiento, pago por uso y ajuste a la demanda, el núcleo de la propuesta de valor.","Incorrecta: comprar capacidad para el pico y mantenerla reproduce el modelo on-premises que la nube evita.","Incorrecta: construir centros de datos en cada país es justo la infraestructura propia que se quiere eliminar.","Incorrecta: consolidar la factura es una ventaja de gestión de costes, no la propuesta de valor de la nube."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.1-q9",taskId:"1.1",objetivos:["1.1#2"],tipo:"escenario",question:"Un equipo necesita lanzar su producto en varios países en semanas, sin abrir infraestructura en cada uno. ¿Qué característica de la infraestructura global de AWS lo hace posible?",options:["Que cada país exige un centro de datos propio.","Que las regiones repartidas por el mundo permiten desplegar rápido y atender a usuarios lejanos.","Que los datos solo pueden residir en un único país.","Que la entrega de contenido depende sobre todo de la ubicación geográfica del equipo de desarrollo."],correctAnswer:1,explanation:"La cobertura de regiones en todo el mundo permite desplegar en poco tiempo y servir a usuarios de otros países sin construir infraestructura propia. Eso resume velocidad de despliegue y alcance global. Si el requisito fuera que los datos residan en un país concreto, la decisión se centraría en elegir la región adecuada para cumplir esa normativa.",porQueOpcion:["Incorrecta: la nube evita precisamente tener que abrir un centro de datos propio en cada país.","Correcta: las Regiones repartidas por el mundo permiten desplegar rápido y servir a usuarios lejanos sin infraestructura propia.","Incorrecta: los datos pueden residir en la región que elija el cliente; no hay una restricción a un único país.","Incorrecta: la ubicación del equipo de desarrollo no determina la entrega del contenido, que usan las ubicaciones de borde."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"1.1-q10",taskId:"1.1",objetivos:["1.1#2"],tipo:"comparacion",question:"Un equipo debe justificar dos beneficios distintos de la infraestructura global de AWS: uno relacionado con el tiempo de puesta en producción y otro con la cobertura geográfica. ¿Qué afirmación los distingue correctamente?",options:["La velocidad de despliegue acorta el tiempo para poner recursos en producción y el alcance global permite servir a usuarios de varias geografías.","La velocidad de despliegue mide cuántos países cubre la plataforma y el alcance global mide lo rápido que se aprovisiona cada recurso en la región elegida.","Ambos describen la misma ventaja: repartir el tráfico entre varias Availability Zones para no depender de una sola zona.","La velocidad de despliegue depende del modelo de pago por uso y el alcance global depende del cifrado de los datos en reposo."],correctAnswer:0,explanation:"La velocidad de despliegue y el alcance global son beneficios distintos de la misma infraestructura: el primero mide el tiempo de puesta en marcha y el segundo, la cobertura geográfica. Invertir las definiciones, reducir ambos a la redundancia entre zonas o atribuirlos al pago por uso y al cifrado son confusiones frecuentes. Si el requisito fuera únicamente cubrir varios continentes, la respuesta se centraría en el alcance global y no en la velocidad de aprovisionamiento.",porQueOpcion:["Correcta: distingue la velocidad de puesta en producción del alcance geográfico, que son los dos beneficios pedidos.","Incorrecta: invierte ambas definiciones: la velocidad no mide países ni el alcance global mide rapidez de aprovisionamiento.","Incorrecta: repartir tráfico entre zonas es alta disponibilidad, no la suma de velocidad de despliegue y alcance global.","Incorrecta: el pago por uso y el cifrado en reposo no definen ni la velocidad de despliegue ni la cobertura geográfica."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]}],1.2:[{id:"1.2-q1",taskId:"1.2",objetivos:["1.2#1"],tipo:"conocimiento",question:"¿Qué es el AWS Well-Architected Framework?",options:["Un servicio gestionado que despliega de forma automática una arquitectura de referencia y la mantiene actualizada.","Un conjunto de buenas prácticas, principios y preguntas para evaluar y mejorar el diseño de una carga de trabajo.","Una certificación obligatoria para publicar aplicaciones en la nube.","El AWS Well-Architected Tool, que reúne las buenas prácticas y principios de diseño del marco."],correctAnswer:1,explanation:"El AWS Well-Architected Framework es una guía de diseño: reúne buenas prácticas y preguntas para revisar una carga de trabajo. No despliega recursos, no certifica y no es el AWS Well-Architected Tool, que es el servicio que aplica ese contenido al revisar una carga. Si el objetivo fuera estimar el coste de una configuración, la herramienta adecuada sería otra y no este marco de diseño.",porQueOpcion:["Incorrecta: el Framework no despliega recursos; es una guía de diseño y no un servicio gestionado.","Correcta: reúne buenas prácticas, principios y preguntas para evaluar y mejorar el diseño de una carga de trabajo.","Incorrecta: no es una certificación obligatoria para publicar aplicaciones en la nube.","Incorrecta: el AWS Well-Architected Tool es el servicio que guía la revisión, no el marco que reúne las buenas prácticas y principios."],fuentes:["https://docs.aws.amazon.com/wellarchitected/"]},{id:"1.2-q2",taskId:"1.2",objetivos:["1.2#1"],tipo:"servicio",question:"Un equipo quiere dejar constancia de la revisión de su arquitectura, marcar los riesgos y priorizar las mejoras. ¿Qué recurso encaja mejor?",options:["El AWS Well-Architected Tool, que guía el cuestionario por pilar y genera un plan de mejora.","Un grupo de AWS Auto Scaling que mida la disponibilidad y genere el informe de riesgos de la carga.","Un bucket de Amazon S3 para almacenar los diagramas de la arquitectura.","El panel de facturación, porque resume el gasto por servicio."],correctAnswer:0,explanation:"El AWS Well-Architected Tool conduce la revisión pilar a pilar y produce un informe de riesgos con un plan de mejora. No es un servicio de cómputo ni de almacenamiento: apoya la revisión del diseño. Si el requisito fuera solo almacenar los diagramas de la arquitectura, bastaría con un servicio de almacenamiento de objetos.",porQueOpcion:["Correcta: la AWS Well-Architected Tool guía la revisión por pilar y genera un plan de mejora con los riesgos priorizados.","Incorrecta: Auto Scaling ajusta capacidad de cómputo; no realiza revisiones de arquitectura ni informes de riesgos.","Incorrecta: un bucket de S3 solo almacena objetos y no evalúa el diseño de la carga.","Incorrecta: el panel de facturación resume gasto, no documenta riesgos ni prioriza mejoras de arquitectura."],fuentes:["https://docs.aws.amazon.com/autoscaling/","https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/wellarchitected/"]},{id:"1.2-q3",taskId:"1.2",objetivos:["1.2#2"],tipo:"comparacion",question:"¿Cuál de estos conjuntos enumera correctamente los pilares del AWS Well-Architected Framework?",options:["Operational excellence, security, reliability, performance efficiency, cost optimization y sustainability.","Compute, storage, database, networking, security y cost management como categorías de servicios de la carga.","Business, people, governance, platform, security y operations.","Rehost, replatform, repurchase, refactor, retire y retain."],correctAnswer:0,explanation:"Los seis pilares son operational excellence, security, reliability, performance efficiency, cost optimization y sustainability. La opción con business, people y governance corresponde al AWS Cloud Adoption Framework; compute, storage y database son categorías de servicios; y rehost, replatform y refactor son estrategias de migración. Si el escenario pidiera ordenar la adopción organizativa, la respuesta correcta sería la lista del AWS CAF.",porQueOpcion:["Correcta: enumera los seis pilares oficiales del AWS Well-Architected Framework.","Incorrecta: compute, storage y database son categorías de servicios, no pilares del Framework.","Incorrecta: business, people y governance son perspectivas del AWS Cloud Adoption Framework, no pilares.","Incorrecta: rehost, replatform y refactor son estrategias de migración (las «7 R»), no pilares."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.2-q4",taskId:"1.2",objetivos:["1.2#2"],tipo:"escenario",question:"Una empresa con un presupuesto mensual acotado quiere que su aplicación siga atendiendo peticiones aunque falle un componente y, a la vez, que ante un pico de tráfico crezca de forma automática. ¿Qué pilares abordan estos dos requisitos?",options:["Reliability y performance efficiency.","Security y cost optimization.","Sustainability y operational excellence.","Operational excellence y security."],correctAnswer:0,explanation:"Seguir operando pese a un fallo es Reliability, que cubre redundancia y tolerancia a fallos; adaptarse a la demanda con eficiencia es Performance efficiency, que cubre la selección de recursos y la elasticidad. Si el escenario pidiera solo uno de los dos requisitos, la respuesta se reduciría a Reliability o a Performance efficiency según el caso.",porQueOpcion:["Correcta: Reliability cubre seguir operando ante fallos y Performance efficiency, adaptarse a la demanda con eficiencia.","Incorrecta: Security protege datos y accesos y Cost optimization reduce gasto; ninguno aborda tolerancia a fallos ni elasticidad.","Incorrecta: Sustainability reduce impacto ambiental y Operational excellence mejora procesos; no cubren esos dos requisitos.","Incorrecta: Operational excellence automatiza operaciones y Security gestiona identidades, no tolerancia a fallos ni escalado."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.2-q5",taskId:"1.2",objetivos:["1.2#2"],tipo:"escenario",question:"Durante una revisión se detecta que no hay procedimientos documentados de operación ni automatización de despliegues. ¿A qué pilar corresponde el hallazgo?",options:["Cost optimization.","Operational excellence.","Sustainability.","Performance efficiency."],correctAnswer:1,explanation:"Los runbooks, la automatización de despliegues y la mejora continua pertenecen a Operational excellence. No es un problema de coste, de rendimiento ni de sostenibilidad. Si el escenario fuera un corte del servicio, el hallazgo apuntaría a Reliability y no a Operational excellence.",porQueOpcion:["Incorrecta: la falta de runbooks no es un problema de gasto, sino de operación.","Correcta: procedimientos documentados y automatización de despliegues pertenecen a Operational excellence.","Incorrecta: Sustainability mide consumo e impacto ambiental, no la documentación de operaciones.","Incorrecta: Performance efficiency elige recursos y escala; no trata la falta de procedimientos operativos."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.2-q6",taskId:"1.2",objetivos:["1.2#3"],tipo:"comparacion",question:"Un mismo cambio puede mejorar un pilar y empeorar otro. ¿Qué afirmación distingue correctamente reliability de performance efficiency?",options:["Reliability se ocupa de sobrevivir a los fallos; performance efficiency, de usar los recursos adecuados y escalar con eficiencia.","Reliability mide la factura mensual; performance efficiency, la seguridad de los datos.","Reliability y performance efficiency son el mismo pilar con distinto nombre.","Reliability diseña la automatización de las operaciones; performance efficiency, la gobernanza de las identidades y de los accesos de la organización."],correctAnswer:0,explanation:"Reliability responde a si el sistema sigue funcionando ante fallos; performance efficiency, a si la carga usa los recursos adecuados y escala. La automatización operativa es Operational excellence y la gestión de identidades es Security. Si el escenario pidiera reducir el gasto, la respuesta sería Cost optimization y no Performance efficiency.",porQueOpcion:["Correcta: distingue sobrevivir a fallos (Reliability) de usar los recursos adecuados y escalar (Performance efficiency).","Incorrecta: la factura es Cost optimization y la seguridad de datos es Security; no definen estos dos pilares.","Incorrecta: son pilares distintos con propósitos diferentes, no el mismo con otro nombre.","Incorrecta: la automatización operativa es Operational excellence y la gestión de identidades es Security."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.2-q7",taskId:"1.2",objetivos:["1.2#3"],tipo:"conocimiento",question:"¿Qué diferencia fundamental separa cost optimization de sustainability?",options:["Cost optimization busca aumentar el gasto de forma sostenida y deliberada, y sustainability busca reducirlo cada año en la nube.","Cost optimization reduce el coste que no aporta valor; sustainability reduce el consumo de recursos y el impacto ambiental.","Cost optimization es un pilar y sustainability es una perspectiva del AWS Cloud Adoption Framework.","Ambos son sinónimos: los dos miden la factura por servicio."],correctAnswer:1,explanation:"Cost optimization se centra en pagar solo por lo que aporta valor y evitar el gasto innecesario; sustainability, en reducir el consumo y la huella ambiental de la carga. Son pilares distintos, aunque medidas como el right-sizing o apagar lo ocioso mejoran ambos. Si el requisito fuera solo reducir la factura, la respuesta sería Cost optimization; el matiz ambiental corresponde a Sustainability.",porQueOpcion:["Incorrecta: Cost optimization busca evitar el gasto innecesario, no aumentar el gasto de forma deliberada.","Correcta: separa el coste que no aporta valor (Cost optimization) del consumo y la huella ambiental (Sustainability).","Incorrecta: Sustainability es un pilar del Well-Architected Framework, no una perspectiva del AWS CAF.","Incorrecta: no son sinónimos: persiguen objetivos distintos aunque medidas concretas mejoren ambos."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.2-q8",taskId:"1.2",objetivos:["1.2#3"],tipo:"escenario",question:"Una aplicación con recursos bien dimensionados responde con latencia alta bajo carga y el informe de revisión lo etiqueta como «problema de fiabilidad». ¿Qué corrección es más precisa?",options:["Es un problema de operational excellence, porque faltan automatización y runbooks en el despliegue de los cambios.","Es un problema de security, porque la latencia expone los datos.","Es un problema de performance efficiency: los recursos no se eligen ni se escalan de forma adecuada para la carga.","Es un problema de cost optimization, porque la latencia indica gasto excesivo."],correctAnswer:2,explanation:"La latencia mide rendimiento y corresponde a Performance efficiency. Reliability trataría la tolerancia a fallos, no la velocidad; ni Security ni Cost optimization describen este síntoma. Si el escenario fuera un corte por el fallo de una zona, entonces sí sería un problema de Reliability.",porQueOpcion:["Incorrecta: no faltan runbooks ni automatización; el síntoma es latencia bajo carga, propio del rendimiento.","Incorrecta: la latencia es un problema de rendimiento y no expone los datos, que sería Security.","Correcta: la latencia alta indica que los recursos no se eligen ni escalan de forma adecuada para la carga.","Incorrecta: la latencia no demuestra gasto excesivo; el síntoma corresponde a Performance efficiency."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.2-q9",taskId:"1.2",objetivos:["1.2#2"],tipo:"tradeoff",question:"Un equipo debe decidir entre replicar en dos ubicaciones para tolerar fallos o consolidar en una sola para reducir coste. ¿Cómo aborda el AWS Well-Architected Framework esta decisión?",options:["Elige siempre la opción más barata, porque cost optimization es el pilar que siempre debe priorizarse por encima de los demás.","Equilibra los pilares: documenta el compromiso entre reliability y cost optimization según el impacto de negocio.","Ignora el coste, porque la fiabilidad siempre va primero.","Traslada la decisión a sustainability, que cubre ambos pilares."],correctAnswer:1,explanation:"La revisión no corona un pilar: hace explícito el compromiso. La redundancia mejora Reliability a cambio de asumir más coste; el equipo decide el equilibrio según la criticidad y el presupuesto, y documenta la decisión. Si el requisito fuera minimizar el gasto a cualquier precio, no sería un buen equilibrio y el Framework seguiría pidiendo documentar el compromiso.",porQueOpcion:["Incorrecta: el Framework no corona un pilar ni prioriza siempre el menor coste; hace explícito el compromiso.","Correcta: equilibra los pilares documentando el trade-off entre Reliability y Cost optimization según el impacto de negocio.","Incorrecta: ignorar el coste tampoco es correcto: el compromiso debe considerar el impacto de negocio.","Incorrecta: Sustainability trata el consumo ambiental y no cubre la decisión entre fiabilidad y coste."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.2-q10",taskId:"1.2",objetivos:["1.2#1"],tipo:"escenario",question:"Un equipo va a poner en producción una aplicación nueva y quiere detectar riesgos de diseño antes del lanzamiento, dejando constancia de las mejoras acordadas. ¿Qué recurso encaja mejor?",options:["Revisar la carga de trabajo con la AWS Well-Architected Tool, que guía el cuestionario por pilar y produce un plan de mejora.","Contratar AWS Enterprise Support, porque su equipo rediseña por completo la arquitectura de la aplicación durante el proyecto de migración.","Abrir un caso en el AWS Support Center para que AWS valide la arquitectura antes de permitir el despliegue.","Habilitar AWS Trusted Advisor, porque aplica automáticamente las recomendaciones de diseño al entorno."],correctAnswer:0,explanation:"La AWS Well-Architected Tool conduce la revisión pilar a pilar de una carga de trabajo y genera un plan de mejora con los riesgos priorizados, que es justo lo que el equipo busca antes de lanzar. El soporte no certifica ni reescribe la arquitectura, y AWS Trusted Advisor aporta recomendaciones pero no aplica los cambios por sí solo. Si el requisito fuera validar técnicamente el diseño de una sola carga, la herramienta de revisión seguiría siendo la respuesta; el soporte encajaría si lo que se pidiera fuera asistencia técnica de cuenta.",porQueOpcion:["Correcta: la Well-Architected Tool guía la revisión por pilar y produce un plan de mejora con riesgos priorizados.","Incorrecta: el soporte no rediseña la arquitectura ni sustituye la revisión de la carga.","Incorrecta: el AWS Support Center no valida ni certifica arquitecturas como requisito de despliegue.","Incorrecta: Trusted Advisor aporta recomendaciones, pero no aplica los cambios de diseño por sí solo."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/wellarchitected/","https://docs.aws.amazon.com/awssupport/latest/user/getting-started.html"]}],1.3:[{id:"1.3-q1",taskId:"1.3",objetivos:["1.3#1"],tipo:"conocimiento",question:"¿Qué describe mejor una estrategia de adopción de la nube?",options:["Contratar el mayor número posible de servicios de AWS en el menor tiempo, buscando la modernización total de la organización.","Decidir cómo y en qué orden la organización lleva sus cargas a la nube, alineando el cambio con objetivos de negocio.","Copiar los servidores actuales a AWS sin modificar procesos ni formación.","Sustituir todo el personal de operaciones por servicios gestionados."],correctAnswer:1,explanation:"Una estrategia de adopción define el cómo y el orden (por ejemplo, por olas o con enfoque cloud-first) y conecta la migración con resultados de negocio. No consiste en contratar servicios ni en un simple traslado técnico. Si el requisito fuera solo mover servidores sin cambiar procesos, no habría estrategia de adopción sino un traslado técnico.",porQueOpcion:["Incorrecta: contratar servicios sin plan no es una estrategia; la adopción exige orden y objetivos.","Correcta: define cómo y en qué orden se llevan las cargas a la nube y alinea el cambio con objetivos de negocio.","Incorrecta: copiar servidores sin cambiar procesos ni formación es un traslado técnico, no una estrategia de adopción.","Incorrecta: sustituir personal por servicios gestionados no es el propósito de una estrategia de adopción."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.3-q2",taskId:"1.3",objetivos:["1.3#1"],tipo:"escenario",question:"Pese a que la dirección fija un plazo urgente, una compañía tiene 200 aplicaciones con dependencias complejas y quiere migrar sin asumir un riesgo inasumible. ¿Qué estrategia de adopción es más adecuada?",options:["Migrar las 200 aplicaciones en un solo fin de semana para acortar el proyecto.","Agrupar las aplicaciones en olas según sus dependencias y migrarlas por fases.","Empezar por la aplicación más crítica y compleja, sin inventario previo.","Posponer la migración hasta que exista un único servicio que lo haga todo."],correctAnswer:1,explanation:"La adopción por olas reduce el riesgo: se agrupa por dependencias y se migra por tandas, aprendiendo en cada fase. Un corte único o empezar sin inventario aumentan el riesgo en lugar de controlarlo. Si el requisito fuera mínima interrupción con migración masiva, habría que combinar la adopción por olas con replicación continua.",porQueOpcion:["Incorrecta: un corte único de 200 aplicaciones concentra el riesgo en lugar de controlarlo.","Correcta: agrupar por dependencias y migrar por olas reduce el riesgo y permite aprender en cada fase.","Incorrecta: empezar sin inventario por la aplicación más compleja añade riesgo en vez de mitigarlo.","Incorrecta: posponer la migración indefinidamente no es una estrategia y ningún servicio único hace todo."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.3-q3",taskId:"1.3",objetivos:["1.3#2"],tipo:"servicio",question:"Antes de migrar, un equipo necesita descubrir qué servidores tiene, qué dependencias existen y cómo se usan. ¿Qué recurso del viaje de migración cubre esa fase?",options:["Migration Evaluator, porque estima el ahorro del caso de negocio.","AWS Application Discovery Service, porque inventaría servidores, dependencias y uso.","AWS Schema Conversion Tool (AWS SCT), porque convierte esquemas de bases de datos entre motores distintos.","AWS Database Migration Service (AWS DMS), porque replica bases de datos."],correctAnswer:1,explanation:"La fase de evaluación necesita inventario y dependencias, que aporta AWS Application Discovery Service. Migration Evaluator estima el caso de negocio, mientras que AWS SCT y AWS DMS actúan más tarde sobre bases de datos. Si el requisito fuera estimar el ahorro del caso de negocio, la herramienta sería Migration Evaluator.",porQueOpcion:["Incorrecta: Migration Evaluator estima el ahorro del caso de negocio, no descubre servidores ni dependencias.","Correcta: AWS Application Discovery Service inventaría servidores, dependencias y patrones de uso en la fase de evaluación.","Incorrecta: AWS SCT convierte esquemas entre motores, una tarea posterior sobre bases de datos.","Incorrecta: AWS DMS replica bases de datos en la fase de ejecución, no descubre el entorno."],fuentes:["https://docs.aws.amazon.com/application-discovery/","https://docs.aws.amazon.com/SchemaConversionTool/","https://docs.aws.amazon.com/dms/","https://aws.amazon.com/migration-evaluator/"]},{id:"1.3-q4",taskId:"1.3",objetivos:["1.3#2"],tipo:"conocimiento",question:"¿Qué función cumple AWS Migration Hub dentro del viaje de migración?",options:["Convertir automáticamente el esquema de una base de datos de un motor a otro distinto.","Seguir el progreso de las migraciones en un solo lugar, entre herramientas y regiones.","Sustituir la necesidad de evaluar el entorno on-premises.","Ejecutar la aplicación en el edge para reducir la latencia."],correctAnswer:1,explanation:"AWS Migration Hub centraliza el seguimiento del estado de las migraciones. No convierte esquemas (eso corresponde a AWS SCT) ni sustituye la evaluación previa del entorno. Si el requisito fuera convertir el esquema entre motores, la herramienta sería AWS SCT.",porQueOpcion:["Incorrecta: convertir esquemas es función de AWS Schema Conversion Tool (AWS SCT), no de Migration Hub.","Correcta: AWS Migration Hub centraliza el seguimiento del estado de las migraciones entre herramientas y regiones.","Incorrecta: Migration Hub no sustituye la evaluación previa del entorno on-premises.","Incorrecta: ejecutar en el edge para reducir latencia es entrega de contenido, no seguimiento de migraciones."],fuentes:["https://docs.aws.amazon.com/migrationhub/","https://docs.aws.amazon.com/SchemaConversionTool/"]},{id:"1.3-q5",taskId:"1.3",objetivos:["1.3#3"],tipo:"comparacion",question:"Un comité quiere distinguir el AWS Cloud Adoption Framework (AWS CAF) del AWS Well-Architected Framework. ¿Qué afirmación es correcta?",options:["El AWS CAF diseña la arquitectura técnica de cada carga y el AWS Well-Architected Framework organiza el cambio de las personas y de los procesos.","El AWS CAF guía la adopción y el cambio organizativo; el AWS Well-Architected Framework guía el diseño técnico de las cargas de trabajo.","Ambos son lo mismo y solo cambian de nombre según el público al que se dirigen.","El AWS CAF se usa solo después de migrar y el AWS Well-Architected Framework solo antes de migrar."],correctAnswer:1,explanation:"El AWS CAF ordena la adopción con seis perspectivas (Business, People, Governance, Platform, Security y Operations). El AWS Well-Architected Framework evalúa y mejora el diseño técnico de las cargas mediante sus pilares. Si el requisito fuera revisar la arquitectura de una carga concreta, el marco sería el Well-Architected Framework.",porQueOpcion:["Incorrecta: invierte los papeles: el CAF no diseña la arquitectura técnica de cada carga.","Correcta: el AWS CAF guía la adopción y el cambio organizativo y el Well-Architected Framework el diseño técnico.","Incorrecta: son marcos distintos con propósitos diferentes, no dos nombres para lo mismo.","Incorrecta: ninguno se limita a antes o después de migrar; ambos acompañan distintas fases."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.3-q6",taskId:"1.3",objetivos:["1.3#3"],tipo:"escenario",question:"Una empresa migra a AWS y su dirección pregunta qué beneficios de negocio debe esperar del AWS Cloud Adoption Framework (AWS CAF). ¿Qué respuesta es correcta?",options:["Únicamente reducir el coste de la factura mensual de cómputo y de almacenamiento de la organización que migra a AWS.","Elegir el tipo de instancia óptimo para cada aplicación.","Reducir el riesgo empresarial, mejorar el desempeño ESG, aumentar los ingresos y mejorar la eficiencia operativa.","Sustituir la necesidad de un plan de seguridad y cumplimiento."],correctAnswer:2,explanation:"Los beneficios que persigue el AWS CAF son de negocio: menor riesgo, mejor desempeño ambiental, social y de gobernanza (ESG), más ingresos y más eficiencia operativa. Elegir instancias o solo bajar la factura es una lectura técnica y parcial. Si el requisito fuera elegir el tipo de instancia, sería una decisión de diseño técnico y no un beneficio del AWS CAF.",porQueOpcion:["Incorrecta: reducir la factura es un resultado parcial y técnico, no el conjunto de beneficios del AWS CAF.","Incorrecta: elegir el tipo de instancia es una decisión de diseño técnico, no un beneficio de negocio del CAF.","Correcta: el AWS CAF persigue menor riesgo empresarial, mejor desempeño ESG, más ingresos y eficiencia operativa.","Incorrecta: el CAF no sustituye el plan de seguridad ni las obligaciones de cumplimiento."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.3-q7",taskId:"1.3",objetivos:["1.3#3"],tipo:"conocimiento",question:"¿Cómo agrupa el AWS CAF sus componentes?",options:["En regiones y zonas de disponibilidad.","En seis perspectivas: Business, People, Governance, Platform, Security y Operations.","En los seis pilares del AWS Well-Architected Framework, que guían el diseño técnico de la carga.","En las «7 R» de migración."],correctAnswer:1,explanation:"El AWS CAF organiza sus componentes en seis perspectivas: tres de negocio (Business, People y Governance) y tres técnicas (Platform, Security y Operations). Los pilares pertenecen al AWS Well-Architected Framework y las «7 R» son estrategias de migración. Si el escenario pidiera clasificar hallazgos de diseño técnico, se usarían los pilares y no las perspectivas del CAF.",porQueOpcion:["Incorrecta: regiones y zonas de disponibilidad son componentes de infraestructura, no la agrupación del CAF.","Correcta: el AWS CAF organiza sus componentes en seis perspectivas de negocio y técnicas.","Incorrecta: los seis pilares pertenecen al AWS Well-Architected Framework, no al CAF.","Incorrecta: las «7 R» son estrategias de migración, no la agrupación de componentes del CAF."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.3-q8",taskId:"1.3",objetivos:["1.3#4"],tipo:"comparacion",question:"Un equipo compara dos estrategias de migración para la misma aplicación. ¿Qué diferencia a rehost de replatform?",options:["Rehost rediseña por completo la aplicación durante la migración y replatform la mueve sin ningún cambio en su arquitectura.","Rehost mueve la aplicación tal cual a AWS y replatform la migra con ajustes para aprovechar servicios gestionados.","Rehost solo aplica a bases de datos y replatform solo a servidores web.","Rehost y replatform son sinónimos y solo cambia el proveedor de nube."],correctAnswer:1,explanation:"Rehost (*lift and shift*) traslada la aplicación sin cambios; replatform (*lift, tuck and reshape*) migra con modificaciones acotadas para usar servicios gestionados. El rediseño profundo corresponde a refactor. Si el requisito fuera rediseñar la aplicación por completo, la estrategia sería refactor.",porQueOpcion:["Incorrecta: invierte los conceptos: el rediseño profundo corresponde a refactor, no a rehost.","Correcta: rehost traslada la aplicación sin cambios y replatform la migra con ajustes para usar servicios gestionados.","Incorrecta: ninguna de las dos se limita a bases de datos o a servidores web.","Incorrecta: no son sinónimos: difieren en si se modifica o no la aplicación al migrar."],fuentes:["https://docs.aws.amazon.com/wellarchitected/latest/framework/welcome.html"]},{id:"1.3-q9",taskId:"1.3",objetivos:["1.3#4"],tipo:"escenario",question:"Una empresa debe migrar una base de datos de gran tamaño con apenas unos minutos de parada permitidos. ¿Qué recurso y enfoque son más adecuados?",options:["Exportar un volcado completo y cargarlo el día del corte, asumiendo varias horas de indisponibilidad para los usuarios.","Usar AWS Database Migration Service (AWS DMS) con replicación continua y hacer el corte en una ventana breve.","Usar AWS Application Migration Service para rehospedar la base de datos.","Usar Migration Evaluator para replicar los datos en tiempo real."],correctAnswer:1,explanation:"La replicación continua con AWS DMS mantiene el destino sincronizado y permite un corte corto. Migration Evaluator estima el caso de negocio y AWS Application Migration Service rehospeda servidores, no replica bases de datos. Si el requisito permitiera una parada larga, bastaría con un volcado y una carga, sin replicación continua.",porQueOpcion:["Incorrecta: un volcado y una carga completa asumen horas de parada, incompatibles con unos minutos permitidos.","Correcta: AWS DMS con replicación continua mantiene el destino al día y permite un corte breve.","Incorrecta: AWS Application Migration Service rehospeda servidores, no replica bases de datos con corte mínimo.","Incorrecta: Migration Evaluator estima el caso de negocio y no replica datos en tiempo real."],fuentes:["https://docs.aws.amazon.com/dms/","https://docs.aws.amazon.com/mgn/","https://aws.amazon.com/migration-evaluator/"]},{id:"1.3-q10",taskId:"1.3",objetivos:["1.3#4"],tipo:"conocimiento",question:"Una base de datos va a cambiar de motor al migrar a AWS y su esquema no es compatible. ¿Qué recurso aborda ese problema?",options:["AWS Schema Conversion Tool (AWS SCT).","AWS Application Discovery Service para inventariar el entorno local.","AWS Migration Hub.","Migration Evaluator."],correctAnswer:0,explanation:"AWS SCT convierte esquemas y código de bases de datos entre motores distintos. El descubrimiento, el seguimiento del progreso y la estimación del caso de negocio corresponden a otras herramientas. Si el requisito fuera replicar los datos y no convertir el esquema, la herramienta sería AWS DMS.",porQueOpcion:["Correcta: AWS Schema Conversion Tool convierte esquemas y código entre motores distintos cuando no son compatibles.","Incorrecta: Application Discovery Service inventaría el entorno local, pero no convierte esquemas.","Incorrecta: Migration Hub solo hace seguimiento del progreso de las migraciones.","Incorrecta: Migration Evaluator estima el caso de negocio y no convierte esquemas."],fuentes:["https://docs.aws.amazon.com/SchemaConversionTool/","https://docs.aws.amazon.com/application-discovery/","https://docs.aws.amazon.com/migrationhub/","https://docs.aws.amazon.com/dms/","https://aws.amazon.com/migration-evaluator/"]},{id:"1.3-q11",taskId:"1.3",objetivos:["1.3#2"],tipo:"escenario",question:"Una empresa quiere construir el caso de negocio de su migración y, a la vez, inventariar los servidores locales y sus dependencias antes de planificar. ¿Qué dos recursos del viaje de migración cubren esas necesidades?",options:["Migration Evaluator para el caso de negocio y AWS Application Discovery Service para el inventario y las dependencias.","AWS Migration Hub para el caso de negocio y AWS Application Migration Service para el inventario y las dependencias.","AWS Database Migration Service (AWS DMS) para el caso de negocio y Migration Evaluator para el inventario y las dependencias.","AWS Schema Conversion Tool (AWS SCT) para el caso de negocio y AWS Migration Hub para el inventario y las dependencias."],correctAnswer:0,explanation:"Migration Evaluator estima el ahorro y construye el caso de negocio, mientras que AWS Application Discovery Service recopila el inventario de servidores, aplicaciones y dependencias. Migration Hub hace seguimiento del progreso, y AWS DMS, AWS SCT y AWS Application Migration Service actúan en fases de ejecución, no en la estimación ni el descubrimiento. Si el requisito fuera seguir el avance de varias migraciones a la vez, la respuesta sería AWS Migration Hub.",porQueOpcion:["Correcta: Migration Evaluator construye el caso de negocio y Application Discovery Service recopila inventario y dependencias.","Incorrecta: Migration Hub hace seguimiento y Application Migration Service rehospeda servidores; no cubren esas fases.","Incorrecta: AWS DMS replica datos y Migration Evaluator estima el negocio, no inventaría dependencias.","Incorrecta: AWS SCT convierte esquemas y Migration Hub sigue el progreso, no estima ni inventaría."],fuentes:["https://docs.aws.amazon.com/application-discovery/","https://docs.aws.amazon.com/migrationhub/","https://docs.aws.amazon.com/mgn/","https://docs.aws.amazon.com/dms/","https://docs.aws.amazon.com/SchemaConversionTool/","https://aws.amazon.com/migration-evaluator/"]}],1.4:[{id:"1.4-q1",taskId:"1.4",objetivos:["1.4#1"],tipo:"conocimiento",question:"¿Qué abarca la economía de la nube como concepto?",options:["Únicamente el precio por hora de las instancias de cómputo y el precio por GB almacenado y descargado en la nube.","El cambio en la estructura de costes al pasar de inversión fija on-premises a gasto variable ligado al consumo.","La cantidad de servicios que ofrece un proveedor de nube.","El número de regiones disponibles para desplegar una aplicación."],correctAnswer:1,explanation:"La economía de la nube estudia cómo cambia la estructura de costes: se sustituye buena parte del capex por opex ligado al uso, se elimina la capacidad ociosa y se aprovechan las economías de escala del proveedor. Si el requisito fuera solo conocer una tarifa, sería un análisis de precios y no de economía de la nube.",porQueOpcion:["Incorrecta: una tarifa concreta es un análisis de precios, no la economía de la nube como concepto.","Correcta: describe el paso de inversión fija on-premises a gasto variable ligado al consumo, núcleo de la economía de la nube.","Incorrecta: la cantidad de servicios ofrecidos no define cómo cambia la estructura de costes.","Incorrecta: el número de regiones es alcance geográfico, no economía de la nube."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q2",taskId:"1.4",objetivos:["1.4#3"],tipo:"comparacion",question:"En términos de economía de la nube, ¿qué distingue un coste fijo de un coste variable?",options:["El fijo depende del consumo real de cada recurso y el variable se paga una sola vez por adelantado al proveedor.","El fijo se paga por adelantado y no cambia con el uso; el variable se factura según el consumo real.","El fijo solo existe en la nube y el variable solo on-premises.","Ambos se pagan por hora y solo cambian de nombre según el proveedor."],correctAnswer:1,explanation:"El coste fijo (capex) se decide antes de conocer la demanda y se paga aunque el recurso no se use; el variable (opex) sigue al consumo. On-premises concentra costes fijos e indirectos, mientras la nube convierte buena parte de ese gasto en variable. Si el escenario pidiera distinguir los costes indirectos del centro de datos, seguiría siendo una comparación entre fijo y variable.",porQueOpcion:["Incorrecta: invierte los conceptos: el fijo no depende del consumo ni el variable se paga por adelantado.","Correcta: el coste fijo se paga por adelantado y no varía con el uso; el variable se factura según el consumo real.","Incorrecta: el coste fijo domina on-premises y el variable es característico de la nube, no al contrario.","Incorrecta: no son el mismo coste con distinto nombre: difieren en si dependen o no del consumo."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q3",taskId:"1.4",objetivos:["1.4#4"],tipo:"escenario",question:"Una empresa compara su centro de datos propio con mover la carga a la nube. ¿Qué costes debe incluir al calcular el coste del entorno on-premises?",options:["Solo el precio de compra de los servidores.","El hardware, la energía, la refrigeración, el espacio, el personal de mantenimiento y la capacidad ociosa.","Únicamente las licencias de software y la conexión de red, porque el resto de costes son propios de la nube.","Solo la conexión a internet, ya que el resto lo cubre el proveedor."],correctAnswer:1,explanation:"El coste on-premises es mayor que el precio del hardware: suma energía, refrigeración, espacio físico, personal, seguridad y la capacidad comprada para el pico que queda sin usar. Ignorar esos costes indirectos lleva a conclusiones erróneas sobre el ahorro de migrar. Si el requisito fuera comparar solo el precio del hardware, se infravaloraría el coste total del entorno propio.",porQueOpcion:["Incorrecta: quedarse en el precio de compra omite energía, refrigeración, personal y capacidad ociosa.","Correcta: el coste on-premises incluye hardware, energía, refrigeración, espacio, personal y la capacidad ociosa del pico.","Incorrecta: licencias y red son solo parte del gasto; el centro de datos asume muchos más costes.","Incorrecta: la conexión a internet es una partida mínima y el proveedor no cubre los costes del entorno propio."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q4",taskId:"1.4",objetivos:["1.4#2"],tipo:"conocimiento",question:"¿Cuál es una razón por la que migrar a la nube puede reducir el coste total frente a operar un centro de datos propio?",options:["Porque en la nube desaparecen por completo todos los costes variables de la infraestructura y del personal interno.","Porque se evita comprar capacidad para el pico y se dejan de asumir costes indirectos de la sala y el hardware.","Porque las licencias de software dejan de ser necesarias.","Porque la nube garantiza el precio más bajo para cualquier carga sin analizar el uso."],correctAnswer:1,explanation:"La migración reduce capex, elimina la capacidad ociosa y descarga costes indirectos como energía, refrigeración, espacio y mantenimiento. No elimina los costes variables ni las licencias, y el ahorro depende de ajustar el consumo. Si el requisito fuera no pagar nunca por capacidad ociosa, la clave seguiría siendo el ajuste de capacidad y el pago por uso.",porQueOpcion:["Incorrecta: la nube introduce costes variables de consumo; no los elimina ni suprime todo el personal interno.","Correcta: evitar capacidad para el pico y los costes indirectos de sala y hardware reduce el coste total.","Incorrecta: las licencias de software siguen siendo necesarias y su coste no desaparece solo por migrar.","Incorrecta: el ahorro depende de ajustar el uso; la nube no garantiza el precio más bajo sin analizarlo."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q5",taskId:"1.4",objetivos:["1.4#8"],tipo:"conocimiento",question:"¿Qué significa que la nube se beneficie de economías de escala?",options:["Que cada cliente debe comprar por su cuenta el mismo volumen de hardware que los demás clientes para poder obtener descuentos por volumen.","Que el proveedor opera a gran volumen y reparte ese coste de compra y operación entre muchos clientes, logrando un precio unitario menor.","Que el precio de los servicios sube a medida que crece el uso.","Que solo las empresas grandes, con mucho volumen propio, pueden acceder a los servicios de nube."],correctAnswer:1,explanation:"Las economías de escala surgen porque el proveedor compra y opera a un volumen muy superior al de cualquier cliente y reparte ese coste agregado. El resultado es una tarifa por unidad más baja que la que alcanzaría un centro de datos pequeño. Si el requisito fuera entender por qué el precio unitario baja, la clave son las economías de escala del proveedor.",porQueOpcion:["Incorrecta: el cliente no compra hardware ni lo hace por su cuenta; esa es la premisa del modelo que la nube evita.","Correcta: el proveedor compra y opera a gran volumen y reparte ese coste entre muchos clientes, bajando el precio unitario.","Incorrecta: las economías de escala tienden a reducir el coste unitario, no a subirlo con el uso.","Incorrecta: las economías de escala del proveedor benefician también a clientes pequeños."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q6",taskId:"1.4",objetivos:["1.4#6"],tipo:"escenario",question:"Un equipo observa que sus servidores usan menos del 10 % de CPU durante casi todo el mes, aunque la factura mensual sigue siendo la misma. ¿Qué medida de rightsizing es adecuada?",options:["Aumentar el tamaño de las instancias para mejorar el rendimiento aunque el uso siga siendo bajo.","Reducir el tamaño de los recursos para ajustarlos a la carga real y seguir midiendo el uso.","Comprar más servidores para repartir la carga.","Ignorar la métrica, porque el uso bajo no tiene impacto en el coste."],correctAnswer:1,explanation:"El uso muy por debajo de la capacidad indica recursos sobredimensionados: el right-sizing consiste en reducirlos a un tamaño acorde con la carga real y revisar periódicamente las métricas. Un recurso infrautilizado se paga completo aunque se aproveche una fracción. Si el escenario fuera un uso alto y sostenido, reducir el tamaño sería contraproducente.",porQueOpcion:["Incorrecta: aumentar el tamaño de recursos ya infrautilizados agrava el sobredimensionamiento.","Correcta: con uso muy por debajo de la capacidad, el right-sizing reduce el tamaño a la carga real y sigue midiendo.","Incorrecta: añadir más servidores multiplica la capacidad ociosa en lugar de ajustarla.","Incorrecta: el uso bajo tiene impacto directo en el coste, porque un recurso infrautilizado se paga completo."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q7",taskId:"1.4",objetivos:["1.4#7"],tipo:"conocimiento",question:"¿Cómo contribuye la automatización a reducir costes en la nube?",options:["Elimina por completo la necesidad de medir el consumo y el gasto de todos los recursos desplegados en la cuenta.","Reduce trabajo manual repetitivo y evita que recursos como los entornos de prueba queden encendidos por olvido.","Sustituye las licencias de software por licencias incluidas.","Garantiza que la factura no cambie de un mes a otro."],correctAnswer:1,explanation:"Automatizar el encendido y apagado, el escalado y los cambios reproducibles quita trabajo manual y evita pagar recursos ociosos que nadie apagó. La automatización no sustituye la medición del consumo ni fija la factura. Si el requisito fuera evitar olvidos de apagado, la automatización es la medida directa.",porQueOpcion:["Incorrecta: la automatización no elimina la necesidad de medir el consumo; apoya su control.","Correcta: reduce trabajo manual repetitivo y evita que recursos como los entornos de prueba queden encendidos por olvido.","Incorrecta: la automatización no sustituye licencias ni convierte las propias en incluidas.","Incorrecta: la factura sigue dependiendo del consumo; la automatización no la fija."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q8",taskId:"1.4",objetivos:["1.4#5"],tipo:"tradeoff",question:"Una empresa ya posee licencias de software y evalúa cómo usarlas en la nube. ¿Qué compara correctamente BYOL con las licencias incluidas?",options:["BYOL obliga a pagar de nuevo la licencia al proveedor, mientras que la licencia incluida reutiliza la que la empresa ya tenía comprada y amortizada antes de migrar.","BYOL reutiliza las licencias propias y se paga solo la infraestructura; la licencia incluida lleva su coste dentro del precio del servicio y simplifica la gestión.","Las dos opciones son idénticas en coste total y en esfuerzo de gestión para la organización.","Las licencias incluidas siempre salen más baratas que BYOL."],correctAnswer:1,explanation:"BYOL (Bring Your Own License) aprovecha licencias ya adquiridas y factura solo la infraestructura, a cambio de gestionar el cumplimiento y los términos. La licencia incluida evita esa gestión porque su coste va dentro del servicio, lo que puede ser más caro si ya se tenían licencias propias. Ninguna es siempre más barata. Si el requisito fuera simplificar la gestión sin licencias propias, encajarían las licencias incluidas.",porQueOpcion:["Incorrecta: invierte los modelos: BYOL reutiliza las licencias propias y la incluida las aporta el proveedor.","Correcta: BYOL aprovecha licencias ya adquiridas pagando solo la infraestructura, e incluida integra el coste en el servicio.","Incorrecta: no son idénticas: difieren en coste total y en el esfuerzo de gestión del cumplimiento.","Incorrecta: ninguna es siempre más barata; si ya se tienen licencias propias, BYOL puede salir mejor."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q9",taskId:"1.4",objetivos:["1.4#2"],tipo:"escenario",question:"Una empresa decide migrar a la nube y espera un ahorro automático. Tras el primer mes la factura es similar a la anterior. ¿Qué explica mejor la situación?",options:["La nube nunca reduce los costes frente a un centro de datos propio, ni siquiera ajustando bien el dimensionado de los recursos.","El ahorro no es automático: hace falta ajustar tamaños, apagar lo que no se usa y elegir modelos de precio acordes al consumo.","El proveedor aplica un recargo fijo durante el primer año.","El coste variable siempre supera al coste fijo."],correctAnswer:1,explanation:"Migrar traslada la estructura de costes, pero el ahorro depende de prácticas como right-sizing, apagado de recursos ociosos, automatización y elección del modelo de precio. Sin ese trabajo, la factura puede parecerse a la del centro de datos anterior. Si el escenario fuera un uso estable y predecible, un compromiso de reserva ayudaría, pero no sustituye el ajuste del consumo.",porQueOpcion:["Incorrecta: la nube sí puede reducir costes cuando se ajusta el dimensionado y el consumo.","Correcta: el ahorro exige right-sizing, apagar recursos ociosos y elegir modelos de precio acordes al consumo.","Incorrecta: no existe un recargo fijo de primer año; la factura similar se debe a la falta de optimización.","Incorrecta: no hay una regla de que el variable supere siempre al fijo; depende del uso y del dimensionado."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q10",taskId:"1.4",objetivos:["1.4#1"],tipo:"escenario",question:"Una dirección pide comparar el modelo económico de su centro de datos con el de AWS antes de decidir. ¿Qué análisis responde mejor a esa petición?",options:["Comparar el modelo de gasto (fijo frente a variable), el coste total de propiedad y otros factores relevantes.","Comparar solo la tarifa por hora de cómputo y el precio por GB de almacenamiento que cada proveedor publica en su lista de precios.","Comparar el número de servidores disponibles en cada entorno y su antigüedad media.","Comparar la factura del último mes de AWS con el presupuesto anual aprobado."],correctAnswer:0,explanation:"La economía de la nube analiza la estructura de costes completa: qué parte del gasto es fija, qué parte variable y cómo cambia el coste total de propiedad, además de factores cualitativos como la operación o la agilidad. Quedarse en la tarifa unitaria, en el inventario de servidores o en una factura aislada omite partidas y conduce a decisiones sesgadas. Si el requisito fuera solo estimar el precio mensual de una configuración concreta, la herramienta sería una calculadora de precios.",porQueOpcion:["Correcta: analiza el modelo de gasto fijo frente a variable, el coste total de propiedad y factores cualitativos.","Incorrecta: comparar solo tarifas unitarias omite el TCO y las partidas indirectas de cada modelo.","Incorrecta: el inventario de servidores no refleja la estructura de costes ni el coste total de propiedad.","Incorrecta: una factura aislada no representa el modelo económico completo de cada entorno."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q11",taskId:"1.4",objetivos:["1.4#3"],tipo:"escenario",question:"Una empresa calcula cuánto le cuesta cada hora de cómputo en su centro de datos y descubre que su proveedor de nube se la cobra solo cuando la usa. ¿Qué diferencia del modelo de costes ilustra la situación?",options:["Que en la nube el gasto se vuelve variable y sigue al consumo, mientras que en on-premises domina el coste fijo.","Que en la nube todos los costes son fijos porque los recursos se contratan por adelantado mediante compromisos anuales.","Que en on-premises el coste es variable porque depende del número de empleados.","Que ambos modelos facturan igual y solo cambia la moneda de pago."],correctAnswer:0,explanation:"El pago por horas consumidas convierte el gasto en variable: si no se usa el recurso, no se factura. En un centro de datos propio, en cambio, el hardware y las instalaciones se pagan con independencia del uso, por lo que dominan los costes fijos. Decir que todo es fijo o que ambos modelos facturan igual invierte la distinción. Si el requisito fuera pagar menos por un uso estable y predecible, seguiría siendo válido un compromiso de reserva, pero el modelo base continúa siendo variable.",porQueOpcion:["Correcta: el pago por uso convierte el gasto en variable, mientras que on-premises dominan los costes fijos.","Incorrecta: los compromisos de reserva son opcionales y no convierten en fijos todos los costes de la nube.","Incorrecta: el coste on-premises no es variable por el número de empleados; dominan los costes fijos.","Incorrecta: los modelos no facturan igual: uno sigue el consumo y el otro se paga con independencia del uso."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q12",taskId:"1.4",objetivos:["1.4#4"],tipo:"conocimiento",question:"¿Qué caracteriza a los costes de un entorno on-premises frente a la nube?",options:["Concentran inversión fija e indirectos como energía, refrigeración, espacio y personal, que se pagan aunque la capacidad quede ociosa.","Dependen del consumo horario de cada máquina y desaparecen por completo cuando no hay usuarios conectados a la aplicación ni tráfico en la red.","Se limitan al precio de compra del hardware y no incluyen instalaciones ni mantenimiento.","Se facturan por GB transferido y por número de peticiones atendidas."],correctAnswer:0,explanation:"El entorno propio acumula costes fijos e indirectos —hardware, energía, refrigeración, espacio y personal— que existen aunque no haya carga, además de la capacidad comprada para el pico. La facturación por consumo horario o por peticiones es propia de la nube, y reducir el coste al precio del hardware ignora la mayor parte del gasto. Si el escenario pidiera estimar el coste total de propiedad, habría que sumar también el mantenimiento y la renovación periódica.",porQueOpcion:["Correcta: el entorno propio acumula inversión fija e indirectos que se pagan aunque la capacidad quede ociosa.","Incorrecta: la facturación por consumo horario es propia de la nube, no de un centro de datos propio.","Incorrecta: reducir el coste al precio del hardware ignora instalaciones, energía y mantenimiento.","Incorrecta: facturar por GB o por peticiones describe modelos de nube, no los costes on-premises."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q13",taskId:"1.4",objetivos:["1.4#7"],tipo:"escenario",question:"Un equipo apaga a mano los entornos de desarrollo cada noche, pero a veces olvida hacerlo el fin de semana y esos recursos siguen facturando. ¿Qué medida aprovecha mejor los beneficios de la automatización?",options:["Programar el apagado y encendido automático de esos entornos según un horario, sin depender de que alguien lo recuerde.","Contratar más personal de guardia para revisar cada noche que todos los entornos de desarrollo quedan apagados y liberados.","Migrar los entornos a un tipo de instancia más pequeño y mantenerlos encendidos todo el tiempo.","Reservar capacidad por un año para bajar la tarifa de esos entornos de desarrollo."],correctAnswer:0,explanation:"La automatización aplica la misma acción de forma repetible y elimina el error humano: programar el apagado evita que los recursos queden encendidos por olvido, que es la causa del gasto. Añadir personal o reservar capacidad no ataca el problema y pueden consolidar el gasto. Si el requisito fuera reducir el tamaño de los recursos porque están sobredimensionados, la medida sería el right-sizing y no la programación horaria.",porQueOpcion:["Correcta: programar el apagado y encendido elimina el error humano y evita que los entornos sigan facturando por olvido.","Incorrecta: añadir personal de guardia mantiene el trabajo manual y el riesgo de olvido que causa el gasto.","Incorrecta: reducir el tamaño y dejarlos encendidos no evita el gasto de las horas en que no se usan.","Incorrecta: reservar capacidad abarata la tarifa, pero consolida el gasto en lugar de eliminarlo."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q14",taskId:"1.4",objetivos:["1.4#8"],tipo:"escenario",question:"Una empresa pequeña no alcanza el volumen necesario para negociar precios bajos de hardware y aun así accede a tarifas por unidad mejores que las que lograría por su cuenta. ¿Qué explica esa situación?",options:["Las economías de escala: el proveedor compra y opera a gran volumen y traslada parte de ese menor coste unitario al cliente.","Un descuento personal que AWS concede a cada cliente nuevo durante el primer año de uso.","Que la empresa compra su propio hardware y lo amortiza en la nube sin coste añadido.","Que los precios de AWS suben con el volumen de uso para financiar así su infraestructura global repartida por todo el mundo."],correctAnswer:0,explanation:"Las economías de escala existen porque el proveedor agrega la demanda de millones de clientes y reduce su coste unitario; parte de ese ahorro se refleja en el precio que paga cada cliente, incluso uno pequeño. No hay un descuento personal por ser nuevo ni la empresa compra hardware propio, y los precios por unidad no suben con el volumen. Si el requisito fuera comparar el gasto propio con el del proveedor, habría que añadir los costes indirectos del centro de datos.",porQueOpcion:["Correcta: el proveedor agrega la demanda de millones de clientes, reduce su coste unitario y traslada parte del ahorro.","Incorrecta: no existe un descuento personal de bienvenida; el menor precio viene de la escala del proveedor.","Incorrecta: la empresa no compra ni amortiza hardware propio: eso anularía la ventaja de escala.","Incorrecta: los precios por unidad no suben con el volumen; el modelo reparte el menor coste agregado."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q15",taskId:"1.4",objetivos:["1.4#5"],tipo:"comparacion",question:"En la estrategia de licencias, ¿qué distingue el modelo BYOL de las licencias incluidas?",options:["Con BYOL la organización reutiliza las licencias que ya posee y paga aparte la infraestructura; con las incluidas, el coste de la licencia va dentro del precio del servicio.","Con BYOL la licencia la aporta el proveedor y con las incluidas la aporta el cliente desde su inventario.","Ambos modelos exigen comprar una licencia nueva por cada instancia que se levante.","Las licencias incluidas permiten usar el software propio de la organización en la nube sin pagar nada adicional por la licencia ni por el servicio contratado de forma mensual."],correctAnswer:0,explanation:"BYOL (Bring Your Own License) aprovecha licencias ya adquiridas y factura solo la infraestructura, a cambio de gestionar su cumplimiento y sus términos; en las licencias incluidas el software viene con el servicio y su coste está dentro del precio. Invertir quién aporta la licencia o afirmar que siempre hay que comprar una nueva describe mal ambos modelos. Si el requisito fuera evitar toda gestión de licencias, encajarían las incluidas aunque salgan más caras para quien ya tenía licencias propias.",porQueOpcion:["Correcta: BYOL reutiliza las licencias propias pagando aparte la infraestructura y las incluidas llevan su coste dentro del servicio.","Incorrecta: invierte quién aporta la licencia: en BYOL la aporta el cliente y en las incluidas el proveedor.","Incorrecta: ninguno obliga a comprar una licencia nueva por instancia; eso describe mal ambos modelos.","Incorrecta: las incluidas no permiten usar software propio gratis; su coste está dentro del precio del servicio."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q16",taskId:"1.4",objetivos:["1.4#6"],tipo:"comparacion",question:"Un equipo compara dos formas de encarar el tamaño de sus recursos. ¿Qué distingue el right-sizing de mantener una capacidad fija?",options:["El right-sizing ajusta de forma continua el tamaño a la carga real medida; la capacidad fija se dimensiona de antemano y se paga aunque quede ociosa.","El right-sizing compra la capacidad máxima para el pico y la capacidad fija la reduce cuando baja el uso.","El right-sizing solo reduce el número de instancias y la capacidad fija solo cambia el tipo de instancia.","Ambos buscan exactamente lo mismo: contratar toda la capacidad por adelantado para fijar así el coste mensual de la infraestructura contratada durante todo el año."],correctAnswer:0,explanation:"El right-sizing usa métricas de uso para subir o bajar el tamaño de los recursos de forma continua y pagar solo por lo necesario; la capacidad fija se decide antes de conocer la demanda y se paga incluso infrautilizada. Invertir los papeles o reducir el right-sizing a un único ajuste de número de instancias lo simplifica en exceso. Si el requisito fuera responder a picos temporales sin sobredimensionar, la combinación adecuada sería right-sizing con elasticidad.",porQueOpcion:["Correcta: el right-sizing ajusta el tamaño a la carga medida de forma continua y la capacidad fija se decide antes y se paga ociosa.","Incorrecta: invierte los papeles: comprar la capacidad máxima es el enfoque de capacidad fija, no del right-sizing.","Incorrecta: el right-sizing no se limita al número de instancias ni la capacidad fija solo al tipo.","Incorrecta: el right-sizing busca pagar solo por lo necesario, no contratar toda la capacidad por adelantado."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"1.4-q17",taskId:"1.4",objetivos:["1.4#7"],tipo:"comparacion",question:"¿Qué distingue gestionar los recursos con automatización frente a hacerlo de forma manual?",options:["La automatización aplica acciones repetibles sin intervención y sin olvidos; la gestión manual depende de que alguien ejecute cada tarea a tiempo.","La automatización elimina por completo el coste de los recursos que gestiona, mientras que la manual lo mantiene.","La gestión manual es más barata porque evita el coste de las herramientas de automatización.","Ambas opciones son equivalentes en coste total y solo cambia quién las ejecuta dentro del equipo de operaciones de la plataforma y de sus servicios asociados."],correctAnswer:0,explanation:"La automatización reduce trabajo manual y errores, y garantiza que acciones como apagar recursos fuera de horario se cumplan de forma consistente; la gestión manual queda a merced de que alguien recuerde cada tarea. La automatización no elimina el coste de los recursos ni es más caro gestionarlos a mano de forma sistemática. Si el requisito fuera corregir recursos sobredimensionados, la automatización ayudaría, pero la medida principal sería el right-sizing.",porQueOpcion:["Correcta: la automatización aplica acciones repetibles sin intervención ni olvidos, mientras la gestión manual depende de que alguien ejecute a tiempo.","Incorrecta: la automatización no elimina el coste de los recursos que gestiona; solo asegura que se apliquen las acciones.","Incorrecta: la gestión manual no es más barata: sumada al error humano y al trabajo repetitivo suele costar más.","Incorrecta: no son equivalentes; la automatización aporta consistencia y reduce errores frente a la ejecución manual."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]}],2.1:[{id:"2.1-q1",taskId:"2.1",objetivos:["2.1#1"],tipo:"conocimiento",question:"¿Qué describe el AWS shared responsibility model?",options:["Que AWS se encarga de absolutamente toda la seguridad de la cuenta y el cliente solo se limita a usar los servicios que contrata, sin responsabilidad alguna sobre sus datos.","Que la seguridad se reparte entre AWS, responsable de la seguridad de la nube, y el cliente, responsable de la seguridad en la nube.","Que el cliente hereda la seguridad física de los centros de datos y de la red troncal al contratar cualquier servicio de AWS.","Que la seguridad se delega por completo a productos de terceros que se adquieren en AWS Marketplace para cada servicio."],correctAnswer:1,explanation:"El modelo reparte la seguridad entre AWS y el cliente. AWS protege la infraestructura que sostiene los servicios (seguridad de la nube) y el cliente protege lo que configura dentro de ella (seguridad en la nube). No se delega por completo a ninguna de las dos partes. Si el requisito pidiera distinguir qué protege cada parte, la respuesta separaría la infraestructura de AWS de los datos y la configuración del cliente.",porQueOpcion:["Incorrecta: el cliente sí conserva responsabilidad sobre sus datos, identidades y configuración.","Correcta: el modelo reparte la seguridad de la nube, de AWS, y la seguridad en la nube, del cliente.","Incorrecta: la seguridad física y la red troncal son de AWS y no se heredan en todos los servicios.","Incorrecta: el modelo no delega la seguridad en productos de terceros del Marketplace."],fuentes:["https://docs.aws.amazon.com/marketplace/"]},{id:"2.1-q2",taskId:"2.1",objetivos:["2.1#2","2.1#3"],tipo:"comparacion",question:"En el AWS shared responsibility model, ¿quién es responsable de qué?",options:["AWS responde de los datos y las identidades del cliente, y el cliente responde del hardware, la red y los centros de datos.","AWS responde de la infraestructura física y la virtualización, y el cliente responde de los datos, las identidades, las aplicaciones y la configuración.","Ambos responden exactamente de lo mismo en todos los servicios, sin que la frontera se desplace al cambiar de servicio ni al elegir uno más o menos gestionado.","El cliente responde de la infraestructura global de AWS y AWS responde de las aplicaciones y los datos que el cliente despliega."],correctAnswer:1,explanation:"AWS es responsable de la seguridad de la nube: instalaciones, hardware, red y virtualización. El cliente es responsable de la seguridad en la nube: datos, identidades y accesos, aplicaciones y configuración de los recursos. El reparto cambia según el servicio, pero no son responsables de lo mismo. Si el escenario pidiera saber de qué responde AWS, la respuesta se centraría en la infraestructura y la virtualización.",porQueOpcion:["Incorrecta: invierte los papeles, pues los datos e identidades son del cliente y el hardware de AWS.","Correcta: AWS cubre la infraestructura física y la virtualización, y el cliente los datos, identidades, aplicaciones y configuración.","Incorrecta: la frontera sí se desplaza según el servicio y no responden de lo mismo.","Incorrecta: invierte los papeles, porque la infraestructura global es de AWS y las aplicaciones y datos del cliente."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.1-q3",taskId:"2.1",objetivos:["2.1#3"],tipo:"escenario",question:"Aunque el coste mensual de la migración preocupa a la dirección, un equipo migra una aplicación de servidores propios a instancias de Amazon EC2. ¿Qué parte de la seguridad queda del lado del cliente en este modelo?",options:["La seguridad física de los centros de datos, el hardware y la red troncal que sostiene el servicio.","El sistema operativo invitado, sus parches, los datos y la configuración de las instancias.","La capa de virtualización que separa unas instancias de otras dentro del mismo servidor físico.","La refrigeración, la alimentación eléctrica y la vigilancia de los edificios donde se alojan los servidores."],correctAnswer:1,explanation:"AWS protege la infraestructura (centros de datos, hardware, red y virtualización). En Amazon EC2 el cliente responde del sistema operativo invitado, de sus parches, de las aplicaciones, de los datos y de la configuración de la instancia. Si el requisito cambiara a un servicio totalmente gestionado, esa misma capa de parcheo pasaría a AWS.",porQueOpcion:["Incorrecta: la seguridad física, el hardware y la red troncal son responsabilidad de AWS.","Correcta: en Amazon EC2 el cliente responde del sistema operativo invitado, sus parches, los datos y la configuración.","Incorrecta: la capa de virtualización que separa las instancias la gestiona AWS.","Incorrecta: la refrigeración, la alimentación y la vigilancia de los edificios corresponden a AWS."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"2.1-q4",taskId:"2.1",objetivos:["2.1#4"],tipo:"conocimiento",question:"¿Cuál de estas es una responsabilidad que corresponde a AWS?",options:["Cifrar los datos del cliente con las claves que este crea y administra dentro de sus propios servicios.","Definir qué usuarios y aplicaciones pueden acceder a cada recurso y con qué nivel de permisos.","Proteger las instalaciones, el hardware, la red y la capa de virtualización que ejecutan los servicios.","Elegir la configuración de red, las subredes y las reglas de acceso de la nube virtual privada del cliente."],correctAnswer:2,explanation:"AWS responde de la seguridad de la infraestructura: instalaciones físicas, hardware, red y software de virtualización. Las claves, los permisos de acceso y la configuración del servicio son responsabilidad del cliente. Si el objetivo pidiera enumerar responsabilidades del cliente, aparecerían los datos, las identidades y la configuración.",porQueOpcion:["Incorrecta: cifrar los datos con claves propias es una decisión del cliente.","Incorrecta: definir qué usuarios acceden a cada recurso corresponde al cliente.","Correcta: AWS protege las instalaciones, el hardware, la red y la capa de virtualización.","Incorrecta: elegir la configuración de red, las subredes y las reglas de acceso es del cliente."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.1-q5",taskId:"2.1",objetivos:["2.1#5","2.1#6"],tipo:"comparacion",question:"¿Qué distingue la seguridad de la nube de la seguridad en la nube?",options:["La seguridad de la nube la asume AWS sobre su infraestructura; la seguridad en la nube la asume el cliente sobre lo que configura.","La seguridad de la nube la asume el cliente sobre sus datos y la seguridad en la nube la asume AWS sobre su infraestructura.","Ambas las asume AWS y el cliente solo elige el servicio que contrata y paga la factura mensual, sin responsabilidad alguna sobre su configuración.","Ambas las asume el cliente porque los datos son suyos en cualquier caso, con independencia del servicio que use."],correctAnswer:0,explanation:"La seguridad de la nube es la que AWS aplica a la infraestructura que sostiene los servicios. La seguridad en la nube es la que el cliente aplica a sus datos, identidades, aplicaciones y configuración. Además hay responsabilidades compartidas, como la gestión de parches y de la configuración. Si el escenario pidiera un control compartido, la respuesta apuntaría a la gestión de parches y de la configuración.",porQueOpcion:["Correcta: la seguridad de la nube la asume AWS sobre su infraestructura y la seguridad en la nube el cliente.","Incorrecta: invierte los términos, porque la seguridad de la nube es de AWS y la seguridad en la nube del cliente.","Incorrecta: el cliente no queda exento, pues conserva la seguridad en la nube sobre lo que configura.","Incorrecta: los datos son del cliente, pero la seguridad de la nube la aplica AWS sobre su infraestructura."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.1-q6",taskId:"2.1",objetivos:["2.1#6"],tipo:"escenario",question:"Una empresa compara ejecutar su base de datos por su cuenta en servidores autogestionados o usar un servicio de base de datos gestionado. ¿Cómo cambia la responsabilidad al elegir el servicio gestionado?",options:["El cliente deja de ser responsable de sus datos y de decidir quién puede acceder a la base de datos.","AWS asume el motor de base de datos, sus parches y las copias de la plataforma; el cliente conserva los datos y los accesos.","La responsabilidad no cambia: en los dos casos el proveedor gestiona el sistema operativo sobre el que corre la base de datos y sus parches.","AWS pasa a responder también de la configuración de la aplicación que consulta la base de datos y de sus credenciales de acceso."],correctAnswer:1,explanation:"Al pasar a un servicio de base de datos gestionado, AWS asume más capas: el motor, sus parches y las copias de seguridad de la plataforma. El cliente conserva la responsabilidad sobre los datos, las identidades, los accesos y la configuración del servicio. Si cambia el tipo de servicio a uno sin servidor, AWS absorbe todavía más operación, pero el cliente nunca pierde sus datos.",porQueOpcion:["Incorrecta: el cliente nunca pierde la responsabilidad sobre sus datos ni sobre quién accede a ellos.","Correcta: AWS asume el motor, sus parches y las copias, y el cliente conserva los datos y los accesos.","Incorrecta: la responsabilidad sí cambia, porque en el servicio gestionado AWS absorbe más capas.","Incorrecta: la configuración de la aplicación y sus credenciales siguen siendo del cliente."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.1-q7",taskId:"2.1",objetivos:["2.1#6"],tipo:"tradeoff",question:"Al elegir entre un servicio más gestionado y uno menos gestionado, ¿qué trade-off describe mejor el modelo de responsabilidad compartida?",options:["Cuanto menos gestionado es el servicio, más control tiene el cliente y más responsabilidad de operación asume.","Cuanto más gestionado es el servicio, más responsabilidad operativa recae sobre el cliente.","El nivel de gestión no influye: la responsabilidad del cliente es siempre idéntica en cualquier servicio y en cualquier región.","Elegir un servicio gestionado transfiere al cliente la seguridad física de la infraestructura."],correctAnswer:0,explanation:"El control y la responsabilidad van juntos: en un servicio menos gestionado el cliente controla más capas y, por tanto, opera más. En un servicio más gestionado AWS asume más operación, pero el cliente nunca pierde la responsabilidad sobre sus datos, identidades y configuración. Si el requisito priorizara reducir la carga operativa, encajaría un servicio más gestionado.",porQueOpcion:["Correcta: a menor gestión, más control y más responsabilidad operativa del cliente.","Incorrecta: es al contrario, un servicio más gestionado traslada menos operación al cliente.","Incorrecta: el nivel de gestión sí desplaza la frontera de responsabilidad.","Incorrecta: la seguridad física siempre es de AWS y no se transfiere al cliente."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.1-q8",taskId:"2.1",objetivos:["2.1#5"],tipo:"conocimiento",question:"¿Cuál de las siguientes es una responsabilidad compartida entre AWS y el cliente?",options:["La seguridad física de los centros de datos.","La gestión de parches y la gestión de la configuración.","La decisión de qué usuarios pueden acceder a los datos.","La construcción y el mantenimiento de la red troncal."],correctAnswer:1,explanation:"La gestión de parches y la gestión de la configuración son responsabilidades compartidas: AWS las aplica sobre su infraestructura y el cliente sobre sus recursos. La seguridad física y la red troncal son de AWS; la decisión de quién accede a los datos es del cliente. Si el escenario preguntara por una responsabilidad exclusiva de AWS, la respuesta sería la seguridad física o la red troncal.",porQueOpcion:["Incorrecta: la seguridad física de los centros de datos es exclusiva de AWS.","Correcta: la gestión de parches y de la configuración se reparte, cada parte sobre su ámbito.","Incorrecta: decidir qué usuarios acceden a los datos es responsabilidad del cliente.","Incorrecta: la construcción y el mantenimiento de la red troncal son de AWS."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.1-q9",taskId:"2.1",objetivos:["2.1#1"],tipo:"escenario",question:"Un equipo directivo compara abrir un centro de datos propio con usar la nube. ¿Qué argumento de la propuesta de valor de AWS explica mejor el ahorro de tiempo y la capacidad de crecer sin inversión inicial?",options:["Que AWS transfiere al cliente la propiedad del hardware que usa, de modo que deja de pagar por él a partir del segundo año y sin pagar por la capacidad ociosa.","Que el cliente cambia gasto fijo en infraestructura por pago por uso y accede a capacidad elástica en minutos, sin aprovisionar de antemano.","Que el cliente mantiene la misma inversión inicial, pero reparte los costes entre más servicios y más regiones de AWS.","Que el hardware se contrata a plazos fijos de varios años, lo que reduce el precio unitario frente a la compra directa."],correctAnswer:1,explanation:"La propuesta de valor de la nube sustituye la inversión inicial en infraestructura por un pago variable según el uso y permite disponer de capacidad en minutos. Ninguna otra opción elimina el gasto fijo: transferir la propiedad, repartir costes o contratar a plazos siguen generando compromisos. Si el escenario pidiera alta disponibilidad, el argumento se centraría en desplegar en varias zonas y no en el modelo de pago.",porQueOpcion:["Incorrecta: AWS no transfiere la propiedad del hardware ni elimina el gasto fijo.","Correcta: la nube sustituye el gasto fijo por pago por uso y ofrece capacidad elástica en minutos.","Incorrecta: mantener la inversión inicial y repartir costes no elimina el gasto fijo.","Incorrecta: contratar hardware a plazos fijos sigue generando un compromiso de capital."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.1-q10",taskId:"2.1",objetivos:["2.1#2"],tipo:"escenario",question:"Un equipo nuevo en AWS pregunta qué dos grandes componentes conviene tener presentes al repartir la seguridad. ¿Qué respuesta describe mejor esos dos componentes?",options:["El plano de control y el plano de datos, que AWS gestiona siempre de la misma forma en todos los servicios.","La seguridad de la nube, que asume AWS sobre su infraestructura, y la seguridad en la nube, que asume el cliente sobre lo que configura.","La seguridad física y la seguridad lógica, que son responsabilidad exclusiva de AWS en cualquier servicio que se contrate, sin que eso dependa del servicio elegido.","El cifrado en tránsito y el cifrado en reposo, que el cliente aplica de forma idéntica en todos los servicios."],correctAnswer:1,explanation:"Los dos componentes del modelo son la seguridad de la nube, responsabilidad de AWS, y la seguridad en la nube, responsabilidad del cliente. Los planos, las capas físicas y lógicas o los tipos de cifrado son conceptos técnicos que se reparten dentro de esos dos componentes, no los componentes en sí. Si el objetivo pidiera enumerar lo que aporta AWS, entrarían la infraestructura y los servicios gestionados.",porQueOpcion:["Incorrecta: los planos de control y datos no son los dos componentes del modelo de seguridad.","Correcta: los dos componentes son la seguridad de la nube, de AWS, y la seguridad en la nube, del cliente.","Incorrecta: la seguridad física y lógica no son esos componentes y no todas son exclusivas de AWS.","Incorrecta: el cifrado es un control concreto, no un componente del modelo de responsabilidad."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.1-q11",taskId:"2.1",objetivos:["2.1#4"],tipo:"escenario",question:"Durante una revisión, el equipo debe enumerar qué protege AWS y qué no. ¿Cuál de estas afirmaciones describe correctamente una responsabilidad de AWS?",options:["Cifrar los datos del cliente con las claves que este crea, administra y rota dentro de sus propios servicios y de sus recursos.","Definir qué usuarios de la organización pueden acceder a cada recurso y con qué nivel de permisos.","Mantener la seguridad física de los centros de datos, el hardware, la red troncal y la capa de virtualización.","Configurar los grupos de seguridad, las subredes y las tablas de rutas de la red virtual del cliente."],correctAnswer:2,explanation:"La seguridad de la nube, que asume AWS, cubre instalaciones físicas, hardware, red y capa de virtualización. El cifrado con claves propias, la definición de permisos y la configuración de red son decisiones del cliente. Si el requisito pidiera una responsabilidad del cliente, la respuesta señalaría los datos, las identidades o la configuración.",porQueOpcion:["Incorrecta: crear y rotar las claves de cifrado es responsabilidad del cliente.","Incorrecta: definir qué usuarios acceden a cada recurso corresponde al cliente.","Correcta: mantener la seguridad física, el hardware, la red troncal y la virtualización es de AWS.","Incorrecta: configurar grupos de seguridad, subredes y rutas es responsabilidad del cliente."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.1-q12",taskId:"2.1",objetivos:["2.1#5"],tipo:"escenario",question:"En una auditoría, el equipo debe identificar un control que ambas partes atienden desde su lado. ¿Cuál de los siguientes es un ejemplo de responsabilidad compartida?",options:["La seguridad física de los centros de datos, que AWS y el cliente protegen de forma conjunta en cada servicio contratado.","La gestión de parches y de la configuración: cada parte cubre su mitad, AWS la infraestructura y el cliente sus recursos.","La construcción y el mantenimiento de la red troncal que interconecta las regiones de AWS y sus centros de datos.","La decisión de qué usuarios pueden acceder a los datos y con qué nivel de permisos en cada cuenta de la organización."],correctAnswer:1,explanation:"Los controles compartidos implican que cada parte aplica su mitad: AWS parchea y configura su infraestructura y el cliente sus recursos. La seguridad física y la red troncal son exclusivas de AWS, y la decisión de quién accede a los datos es del cliente. Si el escenario se centrara en la seguridad física, dejaría de ser compartida y pasaría a ser responsabilidad de AWS.",porQueOpcion:["Incorrecta: la seguridad física de los centros de datos no es compartida, es de AWS.","Correcta: la gestión de parches y de la configuración es un control compartido entre AWS y el cliente.","Incorrecta: la red troncal es infraestructura exclusiva de AWS.","Incorrecta: decidir quién accede a los datos es responsabilidad exclusiva del cliente."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]}],2.2:[{id:"2.2-q1",taskId:"2.2",objetivos:["2.2#1"],tipo:"conocimiento",question:"¿Qué describen los conceptos de compliance y governance en AWS?",options:["Compliance es cumplir las normas y leyes aplicables; governance son las reglas y controles internos que sostienen ese cumplimiento.","Compliance es el cifrado de los datos en reposo; governance es el modelo de responsabilidad compartida entre AWS y el cliente en todas las cuentas.","Compliance es la región donde se alojan los datos; governance es la Availability Zone que se elige para cada recurso.","Ambos conceptos son sinónimos de la facturación mensual y del reparto de costes entre las cuentas de la organización."],correctAnswer:0,explanation:"Compliance es cumplir las normas, leyes y estándares aplicables; governance es el conjunto de reglas, controles y procesos internos con los que la organización demuestra y mantiene ese cumplimiento a lo largo del tiempo. El cifrado es un control concreto, no el concepto global. Si el escenario pidiera el marco interno, la respuesta sería governance.",porQueOpcion:["Correcta: compliance es cumplir las normas y governance son las reglas y controles internos que lo sostienen.","Incorrecta: el cifrado es un control concreto y el modelo de responsabilidad no define governance.","Incorrecta: la región y la zona de disponibilidad son ubicaciones, no estos conceptos.","Incorrecta: la facturación y el reparto de costes no tienen relación con compliance y governance."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q2",taskId:"2.2",objetivos:["2.2#1"],tipo:"conocimiento",question:"Una empresa debe demostrar ante un auditor que sus controles de seguridad se aplican de forma constante. ¿Qué concepto describe ese conjunto de reglas y controles internos?",options:["El cifrado en tránsito de los datos.","La gobernanza (governance).","El escalado automático de la capacidad.","La latencia de red entre regiones."],correctAnswer:1,explanation:"La gobernanza agrupa las reglas, controles y procesos internos que la organización aplica de manera constante para demostrar cumplimiento. El cifrado, el escalado y la latencia son capacidades o métricas concretas, no el marco de control. Si el requisito aludiera a una obligación externa y no al marco interno, la respuesta sería compliance.",porQueOpcion:["Incorrecta: el cifrado en tránsito es un control técnico concreto, no el marco de reglas internas.","Correcta: la gobernanza es el conjunto de reglas y controles internos que se aplican de forma constante.","Incorrecta: el escalado automático es una capacidad de capacidad, no un marco de control.","Incorrecta: la latencia entre regiones es una métrica de red, no gobernanza."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q3",taskId:"2.2",objetivos:["2.2#2"],tipo:"conocimiento",question:"¿Cuál es el principal beneficio de seguridad del cifrado de datos?",options:["Aumenta la capacidad de cómputo disponible y el rendimiento de los servicios que tratan los datos en la cuenta.","Reduce la latencia de acceso a los datos almacenados y al tráfico en tránsito entre regiones.","Hace que los datos sean ilegibles sin la clave, aunque un atacante consiga copiarlos.","Elimina la necesidad de copias de seguridad y de control de acceso."],correctAnswer:2,explanation:"El cifrado protege la confidencialidad: sin la clave, el dato no es legible aunque se copie o se filtre. No aumenta el cómputo, no reduce latencia y no reemplaza al control de acceso ni a las copias de seguridad. Si cambia el objetivo a la disponibilidad de los datos, la respuesta se centraría en copias y redundancia.",porQueOpcion:["Incorrecta: el cifrado no aumenta la capacidad de cómputo ni el rendimiento.","Incorrecta: el cifrado no reduce la latencia de acceso ni del tráfico.","Correcta: el cifrado protege la confidencialidad y hace el dato ilegible sin la clave.","Incorrecta: el cifrado complementa, pero no sustituye las copias de seguridad ni el control de acceso."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q4",taskId:"2.2",objetivos:["2.2#3"],tipo:"escenario",question:"Un equipo reducido necesita averiguar qué identidad eliminó un recurso y cuándo ocurrió. Aunque todavía no cuenta con un proceso de auditoría formal, debe localizar esa actividad. ¿Dónde está registrada y cómo debe buscarla?",options:["En las métricas de rendimiento y las alarmas del servicio de monitoreo, que identifican al autor de cada cambio realizado y el momento exacto en que se realizó cada cambio.","En el historial de llamadas a la API registrado por AWS CloudTrail, entregable a un bucket de Amazon S3 y consultable por identidad y fecha.","En las reglas de configuración de los recursos cifrados, que guardan la identidad de quien eliminó cada recurso.","En los informes de cumplimiento publicados y en los acuerdos disponibles para descargar desde el portal de auditoría."],correctAnswer:1,explanation:"AWS CloudTrail registra las llamadas a la API con la identidad, el origen y la marca temporal de cada acción; sus eventos se pueden entregar a Amazon S3 y consultar por identidad y fecha. Las métricas no identifican autores y los informes de cumplimiento no registran actividad. Si el requisito pidiera el estado de la configuración, la respuesta sería AWS Config.",porQueOpcion:["Incorrecta: las métricas y alarmas muestran rendimiento, no la identidad que hizo cada cambio.","Correcta: CloudTrail registra las llamadas a la API y permite consultarlas por identidad y fecha.","Incorrecta: las reglas de configuración no guardan la identidad que eliminó un recurso.","Incorrecta: los informes de cumplimiento no registran la actividad de la cuenta."],fuentes:["https://docs.aws.amazon.com/cloudtrail/","https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/config/"]},{id:"2.2-q5",taskId:"2.2",objetivos:["2.2#3"],tipo:"conocimiento",question:"¿Dónde se capturan y localizan habitualmente los logs asociados a la seguridad?",options:["Únicamente en la factura mensual de la cuenta, que detalla el consumo de cada servicio y su coste por región, sin incluir registros de actividad.","En los paneles de precios, en el catálogo de servicios y en las hojas de cálculo de estimación de costes, que no contienen registros.","En CloudWatch Logs para los logs operativos, en el historial de actividad de AWS CloudTrail para las llamadas a la API y en AWS Config para los cambios de configuración.","Únicamente en los informes de cumplimiento emitidos por auditores externos y publicados en el portal de cumplimiento, que no recogen la actividad técnica ni los cambios de configuración."],correctAnswer:2,explanation:"Los logs se reparten según su origen: logs operativos en CloudWatch Logs, actividad de la API en AWS CloudTrail y cambios de configuración en AWS Config. Centralizarlos en Amazon S3 facilita la retención y las consultas. Si cambia el tipo de registro a la actividad de la API, la respuesta apuntaría al historial de AWS CloudTrail.",porQueOpcion:["Incorrecta: la factura detalla consumo y coste, no registros de actividad.","Incorrecta: los paneles de precios y el catálogo no contienen logs.","Correcta: los logs se reparten entre CloudWatch Logs, CloudTrail y AWS Config según su origen.","Incorrecta: los informes de auditores externos no recogen la actividad técnica ni los cambios."],fuentes:["https://docs.aws.amazon.com/cloudtrail/","https://docs.aws.amazon.com/config/","https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/cloudwatch/"]},{id:"2.2-q6",taskId:"2.2",objetivos:["2.2#4"],tipo:"conocimiento",question:"Un cliente necesita las certificaciones y los informes de cumplimiento de AWS para una auditoría. ¿Qué servicio de AWS los ofrece en autoservicio?",options:["Un centro de autoservicio con informes de cumplimiento de AWS y acuerdos aplicables.","Un servicio que cifra en reposo los volúmenes y las bases de datos con claves propias del cliente.","Una consola que reúne métricas, logs y alarmas del rendimiento de los recursos de la cuenta.","Una herramienta que estima el coste mensual de una arquitectura antes de desplegarla."],correctAnswer:0,explanation:"AWS Artifact es el punto de autoservicio para obtener informes de auditoría, certificaciones de AWS y los acuerdos aplicables a cada sector. No cifra datos, no reúne métricas y no estima costes. Si el requisito fuera demostrar el estado de configuración de los propios recursos, la respuesta sería AWS Config.",porQueOpcion:["Correcta: AWS Artifact es el centro de autoservicio de informes de cumplimiento y acuerdos.","Incorrecta: el servicio que cifra volúmenes y bases de datos no entrega certificaciones.","Incorrecta: la consola de métricas, logs y alarmas es monitoreo, no informes de cumplimiento.","Incorrecta: la herramienta de estimación de costes no ofrece informes de auditoría."],fuentes:["https://docs.aws.amazon.com/artifact/","https://docs.aws.amazon.com/config/"]},{id:"2.2-q7",taskId:"2.2",objetivos:["2.2#4"],tipo:"servicio",question:"Un cliente debe entregar a su auditor los informes SOC e ISO de AWS y firmar un acuerdo comercial aplicable. ¿Qué servicio le permite obtenerlos sin abrir una incidencia de soporte?",options:["AWS Artifact.","AWS CloudTrail.","Amazon GuardDuty.","AWS Config."],correctAnswer:0,explanation:"AWS Artifact es el centro de autoservicio de informes de cumplimiento y acuerdos de AWS. CloudTrail audita la actividad, GuardDuty detecta amenazas y Config registra la configuración; ninguno publica los informes de cumplimiento. Si el requisito fuera demostrar el estado de configuración de los propios recursos, la respuesta sería AWS Config.",porQueOpcion:["Correcta: AWS Artifact entrega los informes SOC e ISO y los acuerdos sin abrir incidencia.","Incorrecta: CloudTrail registra la actividad de la API, no publica informes de cumplimiento.","Incorrecta: GuardDuty detecta amenazas, no entrega informes de auditoría.","Incorrecta: AWS Config evalúa la configuración, no publica certificaciones ni acuerdos."],fuentes:["https://docs.aws.amazon.com/artifact/","https://docs.aws.amazon.com/cloudtrail/","https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/config/"]},{id:"2.2-q8",taskId:"2.2",objetivos:["2.2#5"],tipo:"escenario",question:"Una empresa de salud quiere operar en varios países y debe cumplir con normativas sanitarias locales y con requisitos de residencia de datos. ¿Qué afirmación es correcta?",options:["Los requisitos de cumplimiento son idénticos en todas las geografías e industrias, por lo que basta una única configuración global sin revisar las leyes locales ni las normas de cada sector.","El cumplimiento depende de la geografía y del sector: hay que revisar los informes y las condiciones aplicables antes de elegir región y servicios.","El cumplimiento solo depende del cifrado en reposo y no de la ubicación geográfica donde se almacenan los datos personales.","La responsabilidad del cumplimiento recae únicamente sobre AWS y el cliente no debe revisar normativa sectorial alguna."],correctAnswer:1,explanation:"Las leyes de cada país o región y las normas de cada industria imponen obligaciones distintas, incluida la residencia de datos. El cliente debe revisar la documentación aplicable y diseñar en consecuencia. Si cambia la industria del caso, los requisitos aplicables también cambiarían aunque la región fuera la misma.",porQueOpcion:["Incorrecta: los requisitos varían por país e industria y exigen revisar la normativa aplicable.","Correcta: el cumplimiento depende de la geografía y del sector, por lo que hay que revisar región y servicios.","Incorrecta: la residencia y las leyes locales importan, no solo el cifrado en reposo.","Incorrecta: el cumplimiento es compartido y el cliente debe revisar la normativa sectorial."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q9",taskId:"2.2",objetivos:["2.2#5"],tipo:"conocimiento",question:"¿Por qué los requisitos de cumplimiento varían entre organizaciones?",options:["Porque dependen de las leyes de cada país o región y de las normas de cada industria, además de los servicios y configuraciones que se utilicen.","Porque AWS cambia las leyes de cada país y publica la normativa aplicable a cada industria en su catálogo de servicios y en los informes de cumplimiento.","Porque el cifrado solo existe en algunas industrias y en algunos servicios, según la región en la que se contratan.","Porque solo las grandes empresas tienen obligaciones legales, mientras que las pequeñas quedan exentas de cumplirlas."],correctAnswer:0,explanation:"Las obligaciones nacen de la legislación de cada geografía y de la normativa de cada sector, y se concretan según los servicios y la configuración usados. Organizaciones de distintos países o industrias, por tanto, afrontan requisitos distintos. Si se pidiera el lugar donde consultar esa información, la respuesta sería el recurso de autoservicio de informes de AWS.",porQueOpcion:["Correcta: las obligaciones nacen de la legislación de cada geografía y de la normativa de cada sector.","Incorrecta: AWS no cambia las leyes; cada país y sector fijan sus requisitos.","Incorrecta: el cifrado está disponible en todas las industrias y no determina por sí solo el cumplimiento.","Incorrecta: las obligaciones legales alcanzan a empresas de cualquier tamaño."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q10",taskId:"2.2",objetivos:["2.2#6"],tipo:"conocimiento",question:"Relaciona cada servicio de seguridad con su función principal. ¿Cuál asociación es correcta?",options:["Amazon Inspector evalúa vulnerabilidades; Amazon GuardDuty detecta actividad maliciosa; AWS Security Hub centraliza hallazgos; AWS Shield protege frente a ataques de denegación de servicio distribuido (DDoS).","Amazon Inspector protege frente a ataques de denegación de servicio distribuido y AWS Shield evalúa las vulnerabilidades de las cargas de trabajo, mientras que Security Hub y GuardDuty gestionan las claves de cifrado.","Amazon GuardDuty cifra los datos en reposo, AWS Security Hub gestiona las claves de cifrado, Inspector centraliza los hallazgos y Shield evalúa la configuración de la red.","AWS Shield centraliza los hallazgos de seguridad, Amazon Inspector detecta las amenazas de la red y Amazon GuardDuty evalúa las vulnerabilidades de las instancias."],correctAnswer:0,explanation:"Inspector busca vulnerabilidades en las cargas de trabajo, GuardDuty detecta actividad maliciosa, Security Hub centraliza y normaliza hallazgos y Shield mitiga ataques de denegación de servicio distribuido (DDoS). Las demás opciones intercambian las funciones. Si el requisito fuera descubrir datos sensibles, la respuesta sería Amazon Macie.",porQueOpcion:["Correcta: Inspector evalúa vulnerabilidades, GuardDuty detecta amenazas, Security Hub centraliza hallazgos y Shield mitiga DDoS.","Incorrecta: intercambia las funciones de Inspector y Shield y atribuye la gestión de claves a servicios que no la hacen.","Incorrecta: ningún servicio de esa asociación cifra datos ni gestiona claves de esa forma.","Incorrecta: cruza por completo las funciones de Shield, Inspector y GuardDuty."],fuentes:["https://docs.aws.amazon.com/inspector/","https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/securityhub/","https://docs.aws.amazon.com/shield/","https://docs.aws.amazon.com/macie/"]},{id:"2.2-q11",taskId:"2.2",objetivos:["2.2#6"],tipo:"escenario",question:"Una aplicación recibe un volumen anómalo de tráfico que intenta dejarla fuera de servicio y, además, el equipo quiere detectar comportamiento sospechoso en la cuenta. ¿Qué combinación encaja mejor?",options:["AWS Shield para mitigar el ataque de denegación de servicio distribuido (DDoS) y Amazon GuardDuty para detectar actividad maliciosa.","AWS Config para mitigar el ataque de denegación de servicio y AWS CloudTrail para detectar el tráfico anómalo que llega a la cuenta.","Amazon CloudWatch para cifrar los datos en tránsito y AWS Artifact para mitigar el ataque de volumen sobre la aplicación web.","AWS KMS para bloquear el tráfico malicioso y Amazon S3 para detectar la amenaza y almacenar los registros de la investigación."],correctAnswer:0,explanation:"AWS Shield está diseñado para mitigar ataques de denegación de servicio distribuido (DDoS) y Amazon GuardDuty para detectar actividad maliciosa. Config y CloudTrail registran, CloudWatch monitorea y AWS KMS gestiona claves; ninguno mitiga tráfico malicioso. Si el requisito fuera evaluar vulnerabilidades, la respuesta sería Amazon Inspector.",porQueOpcion:["Correcta: Shield mitiga el ataque DDoS y GuardDuty detecta la actividad maliciosa.","Incorrecta: Config y CloudTrail registran, pero no mitigan tráfico ni detectan anomalías de volumen.","Incorrecta: CloudWatch no cifra datos y AWS Artifact no mitiga ataques.","Incorrecta: KMS gestiona claves y Amazon S3 almacena, no bloquea ni detecta amenazas."],fuentes:["https://docs.aws.amazon.com/shield/","https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/config/","https://docs.aws.amazon.com/cloudtrail/","https://docs.aws.amazon.com/cloudwatch/","https://docs.aws.amazon.com/artifact/","https://docs.aws.amazon.com/kms/","https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/inspector/"]},{id:"2.2-q12",taskId:"2.2",objetivos:["2.2#7"],tipo:"comparacion",question:"Un equipo debe explicar la diferencia entre cifrado en tránsito y cifrado en reposo. ¿Cuál afirmación es correcta?",options:["El cifrado en tránsito protege los datos mientras se almacenan en un volumen y el cifrado en reposo los protege mientras viajan por la red entre servicios o entre distintos componentes de la arquitectura.","El cifrado en tránsito protege los datos mientras viajan por la red; el cifrado en reposo protege los datos almacenados, por ejemplo en un volumen o en un bucket.","Ambos protegen exactamente el mismo momento del ciclo de vida del dato, por lo que solo hace falta aplicar uno de los dos en cada servicio.","El cifrado en reposo se aplica únicamente al tráfico que viaja entre regiones y el cifrado en tránsito a los datos guardados en un bucket."],correctAnswer:1,explanation:"El cifrado en tránsito protege el dato durante el recorrido por la red; el cifrado en reposo lo protege cuando está almacenado. Cubren momentos distintos y se complementan. Si cambia el momento del dato a cuando está guardado, la respuesta se referiría al cifrado en reposo.",porQueOpcion:["Incorrecta: invierte los conceptos, pues el cifrado en tránsito protege el dato en la red.","Correcta: el cifrado en tránsito protege los datos mientras viajan y el en reposo los datos almacenados.","Incorrecta: cubren momentos distintos del ciclo de vida y se complementan.","Incorrecta: confunde ambos conceptos al asociar el reposo al tráfico entre regiones."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q13",taskId:"2.2",objetivos:["2.2#8"],tipo:"comparacion",question:"Un equipo confunde monitoreo y auditoría. ¿Qué afirmación distingue correctamente el monitoreo del funcionamiento de la auditoría de la actividad?",options:["El servicio de monitoreo registra las llamadas a la API y el de auditoría recoge métricas de rendimiento, alarmas y logs operativos de todos los recursos de la cuenta.","El monitoreo recoge métricas, logs y alarmas sobre el funcionamiento del entorno; la auditoría registra las llamadas a la API para saber quién hizo qué y cuándo.","Ambos servicios solo sirven para calcular el coste mensual de la cuenta y repartir los gastos entre los equipos de la organización.","El servicio de auditoría sustituye al de monitoreo y hace innecesario observar el rendimiento y las alarmas de los recursos, además de revisar su configuración."],correctAnswer:1,explanation:"El monitoreo aporta la visión operativa (métricas, logs y alarmas); la auditoría aporta la actividad de la API con autor y momento. Son funciones complementarias, no sustitutas. Si el requisito pidiera evaluar el estado de la configuración, la respuesta sería un tercer servicio, no el de monitoreo.",porQueOpcion:["Incorrecta: invierte las funciones, porque el monitoreo aporta métricas y alarmas, no el registro de la API.","Correcta: el monitoreo observa el funcionamiento y la auditoría registra quién hizo qué y cuándo.","Incorrecta: ninguno de los dos se dedica a calcular o repartir costes.","Incorrecta: las funciones son complementarias y la auditoría no sustituye al monitoreo."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q14",taskId:"2.2",objetivos:["2.2#8"],tipo:"comparacion",question:"¿Qué diferencia hay entre el servicio que audita la actividad y el que vigila el estado de la configuración para la gobernanza?",options:["El servicio de auditoría guarda el historial de configuración de los recursos y el de configuración registra las llamadas a la API realizadas en la cuenta y el momento exacto de cada operación.","El servicio de auditoría registra la actividad de la API (quién hizo qué); el de configuración guarda el historial de los recursos y evalúa si cumplen las reglas.","Los dos servicios son exactamente lo mismo y solo cambian de nombre según la consola o la región desde la que se consulten.","Ninguno de los dos guarda registros de actividad ni de configuración; solo generan alarmas cuando se supera un umbral definido."],correctAnswer:1,explanation:"El servicio de auditoría responde a «quién hizo qué y cuándo» con el registro de llamadas a la API; el de configuración responde a «en qué estado está la configuración y cumple las reglas» con su historial y evaluación. Ambos complementan la gobernanza. Si cambia la pregunta a «cómo está funcionando el sistema», la respuesta sería el servicio de monitoreo.",porQueOpcion:["Incorrecta: invierte los roles, ya que el historial de configuración pertenece al servicio de configuración.","Correcta: la auditoría registra la actividad de la API y la configuración guarda el historial y evalúa reglas.","Incorrecta: son servicios distintos con propósitos distintos, no un simple cambio de nombre.","Incorrecta: ambos guardan registros; no se limitan a generar alarmas por umbral."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q15",taskId:"2.2",objetivos:["2.2#8"],tipo:"tradeoff",question:"La organización necesita monitoreo operativo, auditoría de seguridad y evaluación de cumplimiento de configuración, pero no puede abordar las tres cosas a la vez. ¿Qué razonamiento es correcto?",options:["Basta con activar el monitoreo de rendimiento: si las métricas y las alarmas son correctas, la auditoría de actividad y el cumplimiento de configuración quedan cubiertos automáticamente, sin necesidad de otros registros.","Son tres necesidades distintas y complementarias: monitoreo con Amazon CloudWatch, auditoría con AWS CloudTrail y evaluación de configuración con AWS Config. Se pueden priorizar, pero una no cubre a las otras.","La auditoría de seguridad se puede sustituir por el monitoreo operativo porque ambos generan registros, métricas y alarmas sobre el comportamiento de los recursos de la cuenta, sin necesidad de un historial aparte.","El cumplimiento de configuración se demuestra solo con el cifrado en reposo de los datos y no requiere revisar el estado ni las reglas de configuración de los recursos de la cuenta."],correctAnswer:1,explanation:"Las tres necesidades son distintas: el monitoreo observa el funcionamiento, la auditoría registra la actividad y la evaluación de configuración comprueba el estado frente a reglas. Priorizar su implantación es válido, pero ninguna cubre el propósito de las otras. Si cambia la prioridad a la autoría de los cambios, la auditoría pasa a ser la primera necesidad.",porQueOpcion:["Incorrecta: el monitoreo no cubre la auditoría de actividad ni la evaluación de configuración.","Correcta: son tres necesidades complementarias que se atienden con CloudWatch, CloudTrail y AWS Config.","Incorrecta: la auditoría responde a quién hizo qué, algo que el monitoreo no registra.","Incorrecta: el cifrado en reposo no demuestra por sí solo el cumplimiento de configuración."],fuentes:["https://docs.aws.amazon.com/cloudwatch/","https://docs.aws.amazon.com/cloudtrail/","https://docs.aws.amazon.com/config/"]},{id:"2.2-q16",taskId:"2.2",objetivos:["2.2#9"],tipo:"conocimiento",question:"¿Por qué los requisitos de cumplimiento varían entre los distintos servicios de AWS?",options:["Porque cada servicio tiene su propio alcance en el modelo de responsabilidad compartida, con controles e informes distintos.","Porque solo algunos servicios están sujetos a leyes y normas, mientras que la mayoría queda exenta de cualquier requisito de cumplimiento en todas las regiones.","Porque el cifrado solo está disponible en un servicio concreto y los demás no permiten proteger los datos en reposo ni en tránsito.","Porque los informes de cumplimiento cambian según la hora del día y la carga de trabajo que soporta cada servicio en cada región."],correctAnswer:0,explanation:"Cada servicio define qué gestiona AWS y qué le corresponde al cliente, y ofrece distintos controles e informes. Por eso un mismo requisito se implementa o se evidencia de manera diferente según el servicio. Si cambia el servicio elegido, la forma de cumplir el requisito también cambia.",porQueOpcion:["Correcta: cada servicio reparte el modelo de responsabilidad de forma distinta y ofrece controles e informes propios.","Incorrecta: todos los servicios están sujetos a las leyes y normas aplicables a la organización.","Incorrecta: el cifrado está disponible en muchos servicios, no en uno solo.","Incorrecta: los informes de cumplimiento no cambian con la hora ni con la carga de trabajo."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q17",taskId:"2.2",objetivos:["2.2#9"],tipo:"escenario",question:"Una empresa debe cumplir un requisito de cifrado en reposo para sus datos. ¿Qué debe tener en cuenta al elegir entre varios servicios de AWS?",options:["Que todos los servicios ofrecen exactamente las mismas opciones de cifrado, los mismos controles y los mismos informes de cumplimiento.","Que las opciones de cifrado y las responsabilidades del cliente varían según el servicio, así que hay que revisar cómo lo implementa cada uno.","Que el cifrado en reposo solo depende de la región elegida y no de la configuración ni de las opciones que ofrece cada servicio contratado ni de los controles que delega en el cliente.","Que el cumplimiento se garantiza activando el monitoreo de rendimiento y las alarmas de la cuenta, sin revisar el cifrado de cada servicio."],correctAnswer:1,explanation:"Cada servicio implementa el cifrado con sus propias opciones y reparte las responsabilidades de forma distinta. Antes de dar por cumplido el requisito hay que revisar la configuración concreta del servicio y qué parte gestiona el cliente. Si el requisito añadiera auditoría de esa configuración, entraría un servicio de evaluación de configuración.",porQueOpcion:["Incorrecta: los servicios no ofrecen las mismas opciones de cifrado ni los mismos informes.","Correcta: las opciones de cifrado y las responsabilidades del cliente varían según el servicio.","Incorrecta: el cifrado en reposo depende de la configuración del servicio, no solo de la región.","Incorrecta: el monitoreo y las alarmas no garantizan el cumplimiento del cifrado."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q18",taskId:"2.2",objetivos:["2.2#1"],tipo:"escenario",question:"Una empresa debe demostrar ante un auditor que aplica controles de seguridad de forma constante y sostenida en el tiempo. ¿Qué enfoque describe mejor la gobernanza en este contexto?",options:["Definir y aplicar un conjunto de reglas, controles y procesos internos, y revisar su cumplimiento de forma periódica.","Contratar un nivel de soporte superior para que AWS asuma la responsabilidad de los controles del cliente.","Cifrar todos los datos en reposo y considerar que el cifrado demuestra por sí solo el cumplimiento exigido.","Trasladar el cumplimiento al proveedor de la nube, que queda obligado a responder por la normativa del cliente sin que el cliente revise nada."],correctAnswer:0,explanation:"La gobernanza es el marco interno de reglas, controles y revisiones con el que la organización sostiene el cumplimiento en el tiempo. Ni el soporte, ni el cifrado, ni el proveedor sustituyen ese marco propio. Si cambia el foco a una obligación externa, el concepto sería compliance.",porQueOpcion:["Correcta: la gobernanza es el marco interno de reglas, controles y revisión periódica.","Incorrecta: el nivel de soporte no transfiere a AWS la responsabilidad de los controles del cliente.","Incorrecta: el cifrado es un control, pero no demuestra por sí solo el cumplimiento sostenido.","Incorrecta: el proveedor no responde por la normativa del cliente ni exime de revisar los controles."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q19",taskId:"2.2",objetivos:["2.2#2"],tipo:"escenario",question:"Un equipo quiere reducir el impacto de una posible fuga de datos de un bucket y pregunta qué aporta el cifrado frente a otros controles. ¿Qué razonamiento es correcto?",options:["El cifrado mantiene los datos ilegibles sin la clave, pero no sustituye al control de acceso ni a las copias de seguridad.","El cifrado impide que un actor no autorizado enumere los objetos del bucket y sustituye a las políticas de acceso y garantiza por sí solo el cumplimiento normativo.","El cifrado evita que los datos salgan de la región elegida y garantiza por sí solo el cumplimiento normativo.","El cifrado elimina la necesidad de clasificar los datos y de revisar los permisos concedidos a cada identidad."],correctAnswer:0,explanation:"El cifrado protege la confidencialidad, de modo que una copia filtrada no expone la información, pero complementa y no reemplaza a los permisos ni a las copias. No controla el listado de objetos ni la residencia de los datos. Si cambiara el riesgo a la disponibilidad, la respuesta se centraría en copias y redundancia.",porQueOpcion:["Correcta: el cifrado protege la confidencialidad, pero no reemplaza los permisos ni las copias de seguridad.","Incorrecta: el cifrado no impide enumerar objetos ni sustituye las políticas de acceso.","Incorrecta: el cifrado no controla la residencia de los datos ni garantiza el cumplimiento por sí solo.","Incorrecta: clasificar los datos y revisar permisos sigue siendo necesario."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q20",taskId:"2.2",objetivos:["2.2#4"],tipo:"escenario",question:"Antes de una auditoría, un área legal pide certificaciones e informes de cumplimiento de AWS, y un ingeniero necesita comprobar el estado de configuración de sus propios recursos. ¿Qué recurso corresponde a cada necesidad?",options:["Los informes de cumplimiento se descargan del centro de autoservicio de AWS y el estado de configuración se evalúa con AWS Config.","Ambas necesidades se cubren con el centro de autoservicio de informes, que también evalúa la configuración de la cuenta y descarga las certificaciones aplicables al sector.","Ambas necesidades se cubren con AWS Config, que publica las certificaciones de AWS y los acuerdos aplicables al sector.","Los informes se obtienen abriendo una incidencia de soporte y la configuración se revisa en los informes de auditoría."],correctAnswer:0,explanation:"Las certificaciones e informes de AWS se descargan del centro de autoservicio (AWS Artifact), mientras que el estado de configuración de los recursos se evalúa con AWS Config. No son intercambiables: uno publica documentación de AWS y el otro audita la configuración del cliente. Si cambia la necesidad a la autoría de un cambio, la respuesta sería el historial de actividad de la API.",porQueOpcion:["Correcta: los informes se descargan del centro de autoservicio de AWS y la configuración se evalúa con AWS Config.","Incorrecta: el centro de informes no evalúa la configuración de los recursos del cliente.","Incorrecta: AWS Config no publica certificaciones ni los acuerdos de sector.","Incorrecta: los informes se obtienen en autoservicio y la configuración no se revisa en informes de auditoría."],fuentes:["https://docs.aws.amazon.com/config/","https://docs.aws.amazon.com/artifact/"]},{id:"2.2-q21",taskId:"2.2",objetivos:["2.2#7"],tipo:"escenario",question:"Una aplicación debe proteger los datos cuando se guardan y cuando viajan entre servicios. ¿Qué combinación de cifrado responde a ese requisito?",options:["Cifrado en reposo para los datos almacenados y cifrado en tránsito para los datos en movimiento; se complementan.","Cifrado en tránsito únicamente, porque el tráfico interno dentro de la infraestructura de AWS ya viaja protegido.","Cifrado en reposo únicamente, porque el cifrado del almacenamiento protege también el recorrido por la red.","Un solo tipo de cifrado basta si se aplica a todos los servicios, con independencia de dónde estén los datos."],correctAnswer:0,explanation:"Cubrir ambos momentos exige aplicar cifrado en reposo al dato almacenado y cifrado en tránsito cuando viaja por la red. Ninguno de los dos sustituye al otro. Si cambia el escenario a datos que solo se guardan, bastaría con el cifrado en reposo.",porQueOpcion:["Correcta: se necesita cifrado en reposo para lo almacenado y en tránsito para lo que viaja por la red.","Incorrecta: solo el cifrado en tránsito no protege los datos almacenados.","Incorrecta: el cifrado en reposo no protege el recorrido de los datos por la red.","Incorrecta: un solo tipo no cubre ambos momentos del ciclo de vida del dato."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.2-q22",taskId:"2.2",objetivos:["2.2#4"],tipo:"comparacion",question:"¿Qué distingue al servicio que entrega los informes de cumplimiento de AWS del que evalúa la configuración de tus propios recursos?",options:["El primero publica informes y acuerdos de AWS; el segundo guarda el historial de configuración y evalúa reglas sobre tus recursos.","El primero evalúa la configuración de la cuenta y el estado de los recursos; el segundo descarga informes de auditoría, certificaciones y acuerdos de AWS.","Ambos entregan informes de cumplimiento de AWS y solo se diferencian por la región desde la que se consultan y por el idioma disponible.","Ambos evalúan la configuración de los recursos y publican los acuerdos aplicables a cada cuenta del cliente en autoservicio."],correctAnswer:0,explanation:"El servicio de informes (AWS Artifact) entrega la documentación de AWS, mientras que el de configuración evalúa los recursos del cliente frente a reglas. Uno aporta evidencia del proveedor y el otro evidencia del estado propio. Si cambia la necesidad a la autoría de los cambios, entraría el historial de actividad de la API.",porQueOpcion:["Correcta: Artifact publica los informes de AWS y el servicio de configuración evalúa los recursos del cliente.","Incorrecta: invierte las funciones, pues el historial y la evaluación de reglas son de AWS Config.","Incorrecta: solo uno entrega informes de AWS; el otro evalúa la configuración del cliente.","Incorrecta: no ambos evalúan la configuración ni publican los acuerdos."],fuentes:["https://docs.aws.amazon.com/config/","https://docs.aws.amazon.com/artifact/"]},{id:"2.2-q23",taskId:"2.2",objetivos:["2.2#6"],tipo:"comparacion",question:"Un equipo debe elegir el servicio adecuado para detectar actividad maliciosa, evaluar vulnerabilidades y mitigar un ataque de volumen. ¿Qué asociación es correcta?",options:["Amazon GuardDuty para actividad maliciosa, Amazon Inspector para vulnerabilidades y AWS Shield para ataques de denegación de servicio distribuido.","Amazon Inspector para actividad maliciosa, AWS Shield para vulnerabilidades y Amazon GuardDuty para ataques de denegación de servicio distribuido.","AWS Shield para vulnerabilidades, Amazon GuardDuty para ataques de denegación de servicio distribuido y Amazon Inspector para amenazas.","Los tres servicios cubren las mismas funciones y son intercambiables según la región o el plan de soporte contratado."],correctAnswer:0,explanation:"Cada servicio tiene un foco: GuardDuty detecta amenazas sobre la actividad, Inspector evalúa vulnerabilidades y Shield mitiga ataques de volumen. No son intercambiables entre sí. Si el requisito pidiera una vista agregada de hallazgos, entraría AWS Security Hub.",porQueOpcion:["Correcta: GuardDuty detecta actividad maliciosa, Inspector vulnerabilidades y Shield ataques de volumen.","Incorrecta: intercambia las funciones de los tres servicios.","Incorrecta: vuelve a cruzar los focos de cada servicio.","Incorrecta: cada servicio tiene un foco distinto y no son intercambiables."],fuentes:["https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/inspector/","https://docs.aws.amazon.com/shield/","https://docs.aws.amazon.com/securityhub/"]},{id:"2.2-q24",taskId:"2.2",objetivos:["2.2#9"],tipo:"comparacion",question:"Al cumplir un requisito de cifrado en reposo, ¿por qué hay que revisar cada servicio por separado?",options:["Porque el alcance del cifrado y quién gestiona las claves varían: en algunos servicios AWS lo aplica por defecto y en otros el cliente debe configurarlo.","Porque todos los servicios cifran siempre con las mismas claves administradas por AWS y el cliente no puede elegir ni configurar ninguna opción de cifrado.","Porque el cifrado en reposo solo depende de la región elegida y no del servicio contratado ni de la parte que administra las claves utilizadas.","Porque el cifrado en reposo se activa únicamente al contratar un plan de soporte empresarial y no está disponible en los planes básicos."],correctAnswer:0,explanation:"El alcance del control y la gestión de claves cambian de un servicio a otro dentro del modelo de responsabilidad compartida, por lo que un mismo requisito se cumple de forma distinta. Asumir que todos los servicios cifran igual lleva a dar por cumplido un requisito que no lo está. Si cambia el servicio, la forma de evidenciar el cifrado también cambia.",porQueOpcion:["Correcta: el alcance del cifrado y quién gestiona las claves varían de un servicio a otro.","Incorrecta: no todos los servicios cifran igual ni con claves administradas por AWS.","Incorrecta: el cifrado depende del servicio y de quién administra las claves, no solo de la región.","Incorrecta: el cifrado en reposo no se limita a los planes de soporte empresarial."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]}],2.3:[{id:"2.3-q1",taskId:"2.3",objetivos:["2.3#1"],tipo:"conocimiento",question:"¿Qué controla el servicio de gestión de identidades y accesos dentro de una cuenta?",options:["El cifrado en reposo de los datos que guardan los servicios y los volúmenes de almacenamiento de la cuenta.","Quién puede hacer qué en una cuenta, mediante identidades y políticas de permisos.","El reparto del tráfico entre varias Regiones de AWS.","El reparto de costes entre las cuentas de una organización."],correctAnswer:1,explanation:"El servicio de identidades y accesos gobierna la autenticación y la autorización dentro de una cuenta: define identidades (usuarios, grupos, roles) y políticas que indican qué acciones se permiten o deniegan sobre qué recursos. El cifrado corresponde a otro servicio, el reparto de tráfico a la capa de red y el reparto de costes a la facturación consolidada. Si cambia el escenario a empleados con directorio corporativo, entraría un centro de identidad centralizado.",porQueOpcion:["Incorrecta: el cifrado en reposo corresponde a los servicios de cifrado, no a la gestión de identidades.","Correcta: el servicio de identidades y accesos define identidades y políticas sobre quién puede hacer qué.","Incorrecta: el reparto de tráfico entre regiones pertenece a la capa de red.","Incorrecta: el reparto de costes entre cuentas corresponde a la facturación consolidada."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q2",taskId:"2.3",objetivos:["2.3#1"],tipo:"comparacion",question:"Un equipo necesita que una aplicación que corre en AWS acceda a un bucket sin guardar credenciales permanentes. ¿Qué diferencia entre usuario de IAM y rol de IAM justifica la elección?",options:["El usuario de IAM nunca tiene credenciales propias ni contraseña; el rol de IAM siempre tiene una clave de acceso permanente para las llamadas programáticas a la API y para todos los servicios de la cuenta.","El rol de IAM no tiene credenciales permanentes: se asume y entrega credenciales temporales, mientras que el usuario de IAM puede tener claves de acceso de larga duración.","Ambos son idénticos y solo cambian de nombre según la consola que se use para crearlos y administrarlos, o la región donde se despliegan.","El usuario de IAM solo sirve para acceder a la consola y el rol de IAM solo para consultar la facturación consolidada."],correctAnswer:1,explanation:"Un rol se asume y proporciona credenciales temporales, por lo que no requiere almacenar claves de larga duración; es la opción adecuada para aplicaciones y accesos entre cuentas. Un usuario de IAM puede tener claves de acceso permanentes y solo se justifica cuando no hay alternativa. Si cambia el escenario a una persona sin directorio federado, un usuario con MFA y permisos mínimos sería aceptable.",porQueOpcion:["Incorrecta: el usuario de IAM sí puede tener credenciales y el rol no usa claves permanentes.","Correcta: el rol entrega credenciales temporales al asumirse y el usuario puede tener claves de larga duración.","Incorrecta: no son idénticos; el rol evita credenciales permanentes.","Incorrecta: el rol sirve para aplicaciones y accesos, no solo para consultar facturación."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q3",taskId:"2.3",objetivos:["2.3#1","2.3#7"],tipo:"escenario",question:"Una empresa contrata a diez analistas para un proyecto de tres meses y el presupuesto no admite licencias adicionales de administración. No importa el proveedor de identidad que usen: deben consultar paneles y leer datos, sin capacidad de modificar recursos. ¿Qué enfoque respeta mejor el principio de menor privilegio?",options:["Adjuntar la política de administrador a cada analista para evitar bloqueos durante el proyecto de tres meses.","Crear un grupo con una política que permita solo leer paneles y datos, y añadir al grupo a los analistas durante el proyecto.","Compartir la contraseña del root user entre los diez analistas para que puedan consultar los paneles y los datos.","Crear una clave de acceso por analista con permisos de administrador y rotarla cada seis meses durante el proyecto y sin límite temporal dentro de la organización."],correctAnswer:1,explanation:"Agrupar identidades y adjuntar al grupo una política con el permiso mínimo evita repetir permisos y reduce el riesgo. La política de administrador y el uso de credenciales del root user contradicen el principio de menor privilegio. Si cambia el requisito a permitir un reinicio puntual, se añadiría esa acción concreta y se retiraría al terminar.",porQueOpcion:["Incorrecta: la política de administrador concede permisos muy superiores a los necesarios.","Correcta: agrupar identidades con una política de solo lectura aplica el menor privilegio y simplifica la administración.","Incorrecta: compartir credenciales del root user elimina la trazabilidad y contradice el menor privilegio.","Incorrecta: los permisos de administrador y las claves de larga duración exceden la necesidad."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q4",taskId:"2.3",objetivos:["2.3#7"],tipo:"conocimiento",question:"¿Qué son las managed policies en AWS Identity and Access Management (IAM)?",options:["Políticas que solo puede usar el root user de la cuenta y que no se pueden adjuntar a ningún otro tipo de identidad.","Políticas administradas por AWS o creadas por el cliente para reutilizarlas y adjuntarlas a varias identidades.","Políticas que se guardan dentro de una única identidad y no se pueden reutilizar en otras identidades de la cuenta.","Reglas de red que filtran el tráfico de entrada y de salida hacia las instancias y los servicios de la cuenta."],correctAnswer:1,explanation:"Las managed policies son documentos de permisos reutilizables que AWS administra o que crea el cliente, y pueden adjuntarse a varias identidades. Las políticas que viven dentro de una sola identidad son inline policies; las reglas de red pertenecen a la capa de red, no a IAM. Si cambia el requisito a una política exclusiva de una identidad, la respuesta sería una política inline.",porQueOpcion:["Incorrecta: las managed policies no son exclusivas del root user ni se limitan a una identidad.","Correcta: son políticas reutilizables administradas por AWS o por el cliente que se adjuntan a varias identidades.","Incorrecta: las políticas que viven dentro de una identidad son inline policies.","Incorrecta: las reglas de red no son managed policies."],fuentes:["https://docs.aws.amazon.com/iam/"]},{id:"2.3-q5",taskId:"2.3",objetivos:["2.3#3"],tipo:"escenario",question:"Un desarrollador necesita reiniciar instancias solo durante los despliegues, pero su política actual le permite borrar cualquier recurso de la cuenta. ¿Qué cambio aplica el principio de menor privilegio?",options:["Mantener el permiso amplio porque acelera los despliegues y evita solicitar aprobaciones en cada release del proyecto.","Sustituir el permiso amplio por uno que solo permita reiniciar y consultar las instancias del proyecto, y retirarlo al terminar.","Añadir MFA al desarrollador y conservar todos los permisos actuales, porque el segundo factor compensa el exceso de permisos aunque no reduzca ninguna acción concreta.","Convertir al desarrollador en root user para que todas sus acciones queden auditadas y se reduzca el riesgo de la cuenta."],correctAnswer:1,explanation:"El principio de menor privilegio concede únicamente las acciones necesarias, sobre los recursos necesarios y durante el tiempo necesario. Añadir MFA mejora la autenticación, pero no reduce los permisos; usar el root user los amplía al máximo. Si cambia el requisito a un permiso permanente de solo lectura, seguiría siendo excesivo frente a la necesidad temporal.",porQueOpcion:["Incorrecta: conservar el permiso amplio excede la necesidad y rompe el menor privilegio.","Correcta: limitar el permiso a las acciones necesarias, sobre los recursos del proyecto y durante el tiempo necesario.","Incorrecta: el MFA mejora la autenticación, pero no reduce los permisos excesivos.","Incorrecta: el root user amplía los permisos al máximo y agrava el riesgo."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q6",taskId:"2.3",objetivos:["2.3#3"],tipo:"tradeoff",question:"El equipo de operaciones pide permisos de administrador «para no perder tiempo pidiendo aprobaciones». ¿Cómo se equilibra la agilidad con el principio de menor privilegio?",options:["Conceder administrador permanente a todo el equipo para maximizar la velocidad y evitar cuellos de botella en las aprobaciones.","Conceder acceso elevado temporal, ligado a una tarea y con aprobación y registro, en lugar de permisos permanentes.","Eliminar todos los permisos del equipo y pedir al root user que ejecute personalmente cada tarea de operación.","Repartir la contraseña del root user entre los operadores para que ninguno dependa de solicitar permisos."],correctAnswer:1,explanation:"El acceso elevado temporal y justificado mantiene la agilidad sin dejar permisos permanentes de administrador. El registro y la aprobación conservan la trazabilidad; repartir credenciales del root user elimina cualquier control. Si el requisito pidiera revisión periódica, se auditarían los permisos concedidos y se retirarían los sobrantes.",porQueOpcion:["Incorrecta: el administrador permanente anula el principio de menor privilegio.","Correcta: el acceso elevado temporal, aprobado y registrado equilibra agilidad y control.","Incorrecta: eliminar todos los permisos y depender del root user hace inviable la operación.","Incorrecta: repartir las credenciales del root user elimina cualquier control y trazabilidad."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q7",taskId:"2.3",objetivos:["2.3#2"],tipo:"conocimiento",question:"¿Por qué es importante proteger la cuenta raíz (root user) de una cuenta de AWS?",options:["Porque es la única identidad que puede crear y administrar las políticas de IAM y adjuntarlas a usuarios, grupos y roles de la cuenta.","Porque tiene acceso completo a todos los recursos y servicios de la cuenta y no se le pueden denegar permisos con políticas de IAM.","Porque es la única identidad que puede iniciar sesión en la consola de AWS y usar los servicios de la cuenta.","Porque solo ella puede crear usuarios de IAM, grupos y roles, además de adjuntar políticas a esas identidades."],correctAnswer:1,explanation:"El root user tiene acceso total y sus permisos no se pueden restringir con políticas de IAM, por lo que comprometerlo compromete la cuenta entera. Los usuarios administradores de IAM también pueden gestionar políticas y usuarios, así que la singularidad del root user es su acceso irrestricto. Si cambia el escenario a una tarea concreta, la respuesta sería una tarea reservada al root user.",porQueOpcion:["Incorrecta: los usuarios administradores de IAM también pueden gestionar políticas.","Correcta: el root user tiene acceso completo y no admite restricciones con políticas de IAM.","Incorrecta: cualquier identidad con permiso puede iniciar sesión en la consola.","Incorrecta: crear usuarios, grupos y roles es delegable a administradores de IAM."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q8",taskId:"2.3",objetivos:["2.3#8"],tipo:"conocimiento",question:"¿Qué tarea solo puede realizar el root user de la cuenta?",options:["Crear un usuario de IAM con permisos de administrador para el equipo de la cuenta.","Cambiar el plan de soporte de la cuenta y cerrar la cuenta de AWS.","Iniciar una instancia de cómputo en una región concreta.","Adjuntar una política administrada a un rol de IAM."],correctAnswer:1,explanation:"Tareas como cambiar el plan de soporte, cerrar la cuenta, cambiar el correo o el nombre de la cuenta o restaurar los permisos de un administrador de IAM quedan reservadas al root user. Crear usuarios, adjuntar políticas e iniciar instancias son tareas delegables. Si cambia la tarea a restaurar los permisos de un administrador de IAM, también quedaría reservada al root user.",porQueOpcion:["Incorrecta: crear usuarios de IAM es una tarea delegable.","Correcta: cambiar el plan de soporte y cerrar la cuenta están reservados al root user.","Incorrecta: iniciar una instancia de cómputo es delegable con los permisos adecuados.","Incorrecta: adjuntar una política administrada es una tarea delegable."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q9",taskId:"2.3",objetivos:["2.3#9"],tipo:"seguridad",question:"¿Qué conjunto de medidas protege mejor la cuenta raíz (root user)?",options:["Crear claves de acceso para el root user y usarlas en los scripts de automatización de la cuenta.","Activar MFA en el root user, no crear claves de acceso para él y usar una identidad administrativa distinta para el trabajo diario.","Compartir la contraseña del root user con todo el equipo de operaciones para repartir la carga de administración y evitar bloqueos.","Desactivar el registro de actividad para que no se filtren datos del root user ni de las operaciones de la cuenta."],correctAnswer:1,explanation:"Proteger el root user combina activar MFA, evitar claves de acceso de larga duración y reservarlo para las tareas que solo él puede hacer; el trabajo diario se realiza con una identidad administrativa. Compartir credenciales o desactivar el registro aumenta el riesgo. Si se necesitara administrar la cuenta sin usar el root user, se crearía esa identidad administrativa con permisos mínimos.",porQueOpcion:["Incorrecta: crear claves de acceso para el root user amplía el riesgo en lugar de protegerlo.","Correcta: activar MFA, evitar claves de acceso y usar una identidad administrativa aparte protege el root user.","Incorrecta: compartir la contraseña del root user elimina la trazabilidad y multiplica el riesgo.","Incorrecta: desactivar el registro oculta la actividad y dificulta la investigación."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q10",taskId:"2.3",objetivos:["2.3#5","2.3#6"],tipo:"comparacion",question:"Un equipo confunde una clave de acceso con un segundo factor de autenticación. ¿Qué distingue correctamente a cada uno?",options:["La clave de acceso es un segundo factor que se pide al iniciar sesión y el MFA es una credencial de larga duración para las llamadas a la API.","La clave de acceso es una credencial programática de larga duración; el MFA es un factor adicional que se exige durante el inicio de sesión.","Ambos son sinónimos y solo cambian de nombre según el servicio de AWS que los use para autenticar a las identidades.","El MFA sustituye a la contraseña de la persona y la clave de acceso sustituye al rol que asume una aplicación."],correctAnswer:1,explanation:"La clave de acceso es un par de credenciales permanente para llamadas programáticas; el MFA añade un factor extra en la autenticación y no sustituye a la contraseña ni a las políticas. Son mecanismos distintos: uno autentica programas y el otro refuerza el inicio de sesión. Si cambia el escenario a una aplicación que llama a la API, la respuesta sería la clave de acceso o un rol.",porQueOpcion:["Incorrecta: invierte los conceptos, pues el MFA es el segundo factor y la clave una credencial programática.","Correcta: la clave de acceso es una credencial de larga duración para la API y el MFA un factor extra de inicio de sesión.","Incorrecta: son mecanismos distintos, no sinónimos.","Incorrecta: el MFA no sustituye a la contraseña ni la clave de acceso a un rol."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q11",taskId:"2.3",objetivos:["2.3#5"],tipo:"conocimiento",question:"¿Dónde conviene almacenar los secretos de una aplicación en lugar de dejarlos en el código o en archivos de configuración?",options:["En una política de IAM con permisos de administrador y con una condición que restrinja el acceso al recurso.","En un almacén de secretos gestionado, como AWS Secrets Manager o AWS Systems Manager.","En el user data de una instancia tal como está, para que la aplicación lo lea al arrancar sin configuración adicional.","En el nombre del recurso, para que sea fácil de leer y de localizar por cualquier identidad de la cuenta."],correctAnswer:1,explanation:"Los secretos deben vivir en un almacén gestionado que permita cifrado, control de acceso y rotación, como AWS Secrets Manager o AWS Systems Manager. Dejarlos en el código, en archivos o en texto plano los expone a cualquiera que lea el repositorio o el recurso. Si cambia el requisito a rotación automática, el almacén gestionado sigue siendo la respuesta.",porQueOpcion:["Incorrecta: una política de IAM no es un almacén de secretos.","Correcta: un almacén gestionado permite cifrado, control de acceso y rotación de los secretos.","Incorrecta: el user data queda visible y no es un almacén seguro de secretos.","Incorrecta: el nombre del recurso es legible y no protege el secreto."],fuentes:["https://docs.aws.amazon.com/secretsmanager/","https://docs.aws.amazon.com/systems-manager/"]},{id:"2.3-q12",taskId:"2.3",objetivos:["2.3#6"],tipo:"escenario",question:"Una empresa quiere que su personal acceda desde el móvil con un segundo factor y que los servicios entre cuentas se llamen sin claves permanentes. ¿Qué combinación de métodos de autenticación cumple ambos objetivos?",options:["Contraseñas únicas por persona sin segundo factor y claves de acceso compartidas entre las cuentas de la organización.","MFA para las personas e IAM Identity Center o roles entre cuentas que entregan credenciales temporales para los servicios.","Solo el root user para todas las operaciones, con MFA activado y sus claves de acceso guardadas en un almacén de secretos.","Un usuario de IAM con clave de acceso de larga duración por cada cuenta y servicio, repartido entre las aplicaciones."],correctAnswer:1,explanation:"MFA refuerza el inicio de sesión de las personas y los roles entre cuentas o IAM Identity Center entregan credenciales temporales a los servicios, sin claves permanentes. Concentrar todo en el root user o repartir claves de acceso de larga duración contradice el principio de menor privilegio. Si cambia el requisito a autenticación de clientes finales, la respuesta sería Amazon Cognito.",porQueOpcion:["Incorrecta: las claves compartidas y la falta de segundo factor no cumplen los objetivos.","Correcta: el MFA refuerza el acceso humano y la federación o los roles entregan credenciales temporales a los servicios.","Incorrecta: concentrar todo en el root user no es seguro ni sostenible.","Incorrecta: repartir claves de larga duración contradice el menor privilegio."],fuentes:["https://docs.aws.amazon.com/cognito/","https://docs.aws.amazon.com/singlesignon/"]},{id:"2.3-q13",taskId:"2.3",objetivos:["2.3#4"],tipo:"conocimiento",question:"¿Qué aporta el servicio de acceso federado centralizado de AWS frente a crear un usuario de IAM por persona y por cuenta?",options:["Sustituye por completo a las políticas de IAM, de modo que ya no hace falta definir permisos por recurso en la cuenta.","Centraliza el acceso de la plantilla con inicio de sesión único y permission sets asignados por grupo y por cuenta.","Solo sirve para gestionar la facturación de varias cuentas y consolidar los costes de la organización en una única factura.","Elimina la necesidad de usar MFA en las cuentas y sustituye a los roles de IAM que asumen las aplicaciones."],correctAnswer:1,explanation:"IAM Identity Center centraliza la autenticación de la plantilla, se integra con el directorio o proveedor de identidad corporativo y asigna permission sets por cuenta, evitando crear un usuario por persona y por cuenta. No sustituye a las políticas ni exime de usar MFA. Si cambia el escenario a clientes finales de una aplicación, la respuesta sería Amazon Cognito.",porQueOpcion:["Incorrecta: el acceso federado no sustituye la definición de permisos por recurso.","Correcta: IAM Identity Center centraliza el acceso con inicio de sesión único y permission sets por grupo y cuenta.","Incorrecta: la facturación consolidada corresponde a AWS Organizations, no al acceso federado.","Incorrecta: no elimina el MFA ni sustituye a los roles que asumen las aplicaciones."],fuentes:["https://docs.aws.amazon.com/organizations/","https://docs.aws.amazon.com/cognito/","https://docs.aws.amazon.com/singlesignon/"]},{id:"2.3-q14",taskId:"2.3",objetivos:["2.3#10"],tipo:"escenario",question:"Una compañía quiere que sus empleados inicien sesión en AWS con las credenciales de su proveedor de identidad corporativo, sin contraseñas propias de IAM. ¿Qué tipo de gestión de identidades describe esta situación?",options:["Autenticación local con un usuario de IAM por empleado, con contraseña propia, MFA obligatorio y claves de acceso de larga duración.","Identidad federada: la autenticación se delega en un proveedor de identidad externo y se reciben credenciales temporales.","Autenticación con la contraseña del root user compartida entre los empleados que necesitan administrar la cuenta.","Cifrado en reposo de los datos de los empleados, que sustituye a la autenticación y protege sus credenciales."],correctAnswer:1,explanation:"La identidad federada confía en un proveedor de identidad externo para autenticar a las personas y emite credenciales temporales para el acceso, de modo que no se crean contraseñas de IAM por empleado. Compartir el root user o crear un usuario local por persona son alternativas peores en seguridad y administración. Si cambia el escenario a autenticación de clientes finales, la respuesta sería un servicio de identidades para aplicaciones.",porQueOpcion:["Incorrecta: crear un usuario de IAM por empleado no es federación y mantiene contraseñas locales.","Correcta: la identidad federada delega la autenticación en el proveedor corporativo y entrega credenciales temporales.","Incorrecta: compartir el root user no es federación y agrava el riesgo.","Incorrecta: el cifrado protege datos, pero no autentica identidades."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q15",taskId:"2.3",objetivos:["2.3#4","2.3#10"],tipo:"servicio",question:"¿Qué servicio se usa para conectar el directorio corporativo y asignar permisos por cuenta a los empleados con autenticación federada?",options:["AWS Identity and Access Management (IAM) sin integración externa.","AWS IAM Identity Center.","AWS Secrets Manager.","AWS Resource Access Manager (AWS RAM)."],correctAnswer:1,explanation:"AWS IAM Identity Center conecta el directorio o proveedor de identidad corporativo, aplica inicio de sesión único y asigna permission sets por cuenta a grupos de personas. Secrets Manager almacena secretos y AWS RAM comparte recursos entre cuentas; ninguno gestiona la federación de la plantilla. Si cambia el requisito a almacenar secretos de aplicación, la respuesta sería AWS Secrets Manager.",porQueOpcion:["Incorrecta: IAM sin integración no conecta el directorio corporativo.","Correcta: IAM Identity Center conecta el directorio y asigna permission sets por cuenta a los empleados.","Incorrecta: Secrets Manager almacena secretos, no gestiona federación.","Incorrecta: AWS RAM comparte recursos entre cuentas, pero no conecta directorios ni gestiona identidades."],fuentes:["https://docs.aws.amazon.com/singlesignon/","https://docs.aws.amazon.com/secretsmanager/","https://docs.aws.amazon.com/ram/latest/userguide/what-is.html","https://docs.aws.amazon.com/iam/"]},{id:"2.3-q16",taskId:"2.3",objetivos:["2.3#2"],tipo:"escenario",question:"Una auditoría exige que el root user de la cuenta deje de usarse en el día a día. ¿Qué explicación justifica mejor esta medida?",options:["Porque el root user tiene acceso total y no admite restricciones por políticas, así que comprometerlo compromete toda la cuenta.","Porque el root user no puede activar MFA ni modificar el plan de soporte contratado para la cuenta.","Porque las acciones del root user no quedan registradas en el historial de actividad de la cuenta.","Porque el root user solo puede iniciar sesión con claves de acceso y nunca con la contraseña de la cuenta ni con un segundo factor de autenticación."],correctAnswer:0,explanation:"El root user conserva acceso completo y no admite restricciones mediante políticas de IAM, por lo que usarlo a diario amplía la superficie de riesgo. Sí puede activar MFA, cambiar el plan de soporte y sus acciones quedan registradas. Si cambia el escenario a las tareas permitidas, seguiría reservado para cambiar el plan de soporte o cerrar la cuenta.",porQueOpcion:["Correcta: el root user tiene acceso total sin restricciones por políticas, por lo que usarlo a diario amplía el riesgo.","Incorrecta: el root user sí puede activar MFA y cambiar el plan de soporte.","Incorrecta: las acciones del root user sí quedan registradas en el historial.","Incorrecta: el root user puede iniciar sesión con contraseña y MFA, no solo con claves."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q17",taskId:"2.3",objetivos:["2.3#4"],tipo:"escenario",question:"Una empresa con muchas cuentas quiere que su plantilla acceda con un único inicio de sesión corporativo y permisos por grupo. ¿Qué enfoque responde mejor a esa necesidad?",options:["Crear un usuario de IAM por persona y por cuenta, y adjuntar las mismas políticas a cada uno manualmente en todas las cuentas y con las mismas credenciales duraderas.","Conectar el directorio corporativo a un servicio de acceso centralizado que asigna permission sets por cuenta y por grupo.","Compartir una única clave de acceso entre los empleados y rotarla cada vez que alguien deja la compañía.","Usar el root user de cada cuenta para dar de alta a los empleados y retirarles el acceso al terminar."],correctAnswer:1,explanation:"Un servicio de acceso centralizado se integra con el directorio corporativo, aplica inicio de sesión único y asigna permission sets por cuenta y grupo, evitando usuarios de IAM por persona y por cuenta. Repartir claves o usar el root user multiplica el riesgo. Si cambia el requisito a autenticar clientes finales, la respuesta sería un servicio de identidades para aplicaciones.",porQueOpcion:["Incorrecta: crear usuarios de IAM por persona y por cuenta multiplica la administración y el riesgo.","Correcta: un acceso centralizado conectado al directorio asigna permission sets por cuenta y grupo.","Incorrecta: compartir una clave impide la trazabilidad individual.","Incorrecta: usar el root user de cada cuenta no es un enfoque seguro ni delegable."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q18",taskId:"2.3",objetivos:["2.3#5"],tipo:"escenario",question:"Una aplicación necesita una contraseña de base de datos y no debe contenerla en el código ni en archivos de configuración. ¿Dónde debe guardarla y por qué?",options:["En un almacén de secretos gestionado que permite cifrado, control de acceso y rotación de la credencial.","En una política de IAM con permisos de administrador, porque así solo la lee quien administra la cuenta.","En el user data de la instancia, porque se ejecuta al arrancar y la aplicación siempre la encuentra.","En una etiqueta del recurso, porque es un metadato legible por cualquiera que consulte la consola."],correctAnswer:0,explanation:"Los secretos se guardan en un almacén gestionado con cifrado, permisos mínimos y rotación; el código solo referencia el secreto. Las políticas de IAM, el user data y las etiquetas no son almacenes seguros de credenciales. Si cambia el requisito a reforzar el acceso humano, la respuesta sería una contraseña robusta más MFA.",porQueOpcion:["Correcta: el secreto debe guardarse en un almacén gestionado que cifre, controle el acceso y permita rotarlo.","Incorrecta: una política de IAM define permisos, no almacena credenciales.","Incorrecta: el user data es legible y no protege la contraseña.","Incorrecta: una etiqueta es metadato visible, no un almacén de secretos."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q19",taskId:"2.3",objetivos:["2.3#8"],tipo:"escenario",question:"Una empresa descubre que necesita modificar el correo de contacto de su cuenta y que su equipo de IAM no puede hacerlo. ¿Qué implica esta situación?",options:["Que esa tarea queda reservada al root user, igual que cambiar el plan de soporte o cerrar la cuenta.","Que la cuenta está bloqueada y debe crearse una nueva con un correo de contacto distinto.","Que cualquier usuario con la política de administrador de IAM puede hacerlo sin restricción siempre que tenga esa política adjunta.","Que la tarea requiere abrir una incidencia de soporte y esperar la intervención de AWS."],correctAnswer:0,explanation:"Cambiar el correo o el nombre de la cuenta, cambiar el plan de soporte y cerrar la cuenta son tareas reservadas al root user, que no se delegan con políticas de IAM. No implican crear otra cuenta ni dependen de un administrador de IAM. Si cambia la tarea a restaurar los permisos de un administrador, seguiría siendo del root user.",porQueOpcion:["Correcta: cambiar el correo de contacto es una tarea reservada al root user.","Incorrecta: la cuenta no está bloqueada; la tarea simplemente no es delegable.","Incorrecta: un administrador de IAM no puede realizar las tareas reservadas al root user.","Incorrecta: la tarea se hace desde el root user sin necesidad de una incidencia."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q20",taskId:"2.3",objetivos:["2.3#9"],tipo:"escenario",question:"Un equipo quiere administrar la cuenta sin usar el root user y pide un conjunto de medidas concretas. ¿Cuál es la recomendación correcta?",options:["Activar MFA en el root user, no crearle claves de acceso y usar una identidad administrativa aparte para el trabajo diario.","Crear claves de acceso para el root user y guardarlas en un almacén de secretos para automatizar las tareas y usarlas en los scripts de automatización de la organización.","Compartir la contraseña del root user entre los administradores y exigir MFA en cada inicio de sesión.","Convertir a un usuario de IAM en copia del root user y usar sus credenciales con permisos completos."],correctAnswer:0,explanation:"La protección del root user combina MFA, ausencia de claves de acceso y una identidad administrativa separada para el día a día. Compartir su contraseña o crearle claves amplía el riesgo, y ningún usuario de IAM replica su acceso irrestricto. Si cambia el requisito a reducir el número de identidades, se agruparían por función con permisos mínimos.",porQueOpcion:["Correcta: proteger el root user combina MFA, ausencia de claves de acceso y una identidad administrativa separada.","Incorrecta: crear claves para el root user amplía el riesgo.","Incorrecta: compartir la contraseña del root user elimina el control individual.","Incorrecta: ningún usuario de IAM replica el acceso irrestricto del root user."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q21",taskId:"2.3",objetivos:["2.3#4","2.3#10"],tipo:"comparacion",question:"¿Qué distingue el acceso federado con un centro de identidad centralizado de crear usuarios de IAM por persona y por cuenta?",options:["El acceso centralizado valida en un proveedor de identidad externo y entrega credenciales temporales; los usuarios locales tienen credenciales duraderas.","El acceso centralizado crea un usuario permanente en cada cuenta de la organización; los usuarios locales se validan contra un directorio externo sin necesidad de asignar permisos por cuenta.","Ambos enfoques son idénticos en administración y seguridad, y solo cambian por el número de cuentas de la organización.","El acceso centralizado elimina la necesidad de permisos, porque la autenticación ya la resuelve el proveedor externo."],correctAnswer:0,explanation:"La federación delega la autenticación en un proveedor de identidad externo y emite credenciales temporales para cada cuenta, mientras que los usuarios locales guardan credenciales duraderas que hay que administrar. La federación no elimina la necesidad de definir permisos. Si cambia el escenario a autenticación de clientes finales, la respuesta sería un servicio de identidades para aplicaciones.",porQueOpcion:["Correcta: la federación valida en un proveedor externo y entrega credenciales temporales, frente a las duraderas de los usuarios locales.","Incorrecta: invierte los enfoques, pues el centralizado no crea usuarios permanentes por cuenta.","Incorrecta: ambos enfoques difieren en administración y seguridad, no solo en el número de cuentas.","Incorrecta: la federación no elimina la necesidad de definir permisos."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q22",taskId:"2.3",objetivos:["2.3#2","2.3#3","2.3#8","2.3#9"],tipo:"comparacion",question:"Una empresa quiere hacer el trabajo diario de administración con una identidad de IAM y dejar la cuenta raíz solo para lo imprescindible. ¿Qué diferencia entre ambas identidades sostiene esa decisión?",options:["La cuenta raíz conserva un acceso completo que no se limita con políticas, mientras que la identidad administrativa aplica el menor privilegio y solo asume tareas delegables.","La cuenta raíz puede restringirse con políticas como cualquier identidad, mientras que la identidad administrativa nunca puede delegar sus permisos ni asumir tareas cotidianas dentro de la organización.","La única diferencia es el formato de las credenciales: la cuenta raíz usa contraseña y la identidad administrativa usa siempre claves de acceso de larga duración.","La identidad administrativa hereda el acceso total de la cuenta raíz y por eso conviene usarla en el día a día sin MFA ni permisos concretos."],correctAnswer:0,explanation:"La cuenta raíz tiene acceso total que no se puede denegar con políticas de IAM y queda reservada a tareas que solo ella puede realizar, como cambiar el plan de soporte o cerrar la cuenta; por eso se protege con MFA, sin claves de acceso y sin uso diario. La identidad administrativa de IAM se rige por el principio de menor privilegio y ejecuta el trabajo cotidiano con permisos acotados. Si cambia el escenario a una tarea reservada a la cuenta raíz, la identidad administrativa no podría asumirla aunque tuviera la política de administrador.",porQueOpcion:["Correcta: el root user no se limita con políticas y la identidad administrativa aplica el menor privilegio.","Incorrecta: el root user no puede restringirse con políticas y la identidad administrativa sí asume tareas cotidianas.","Incorrecta: la diferencia no es el formato de credenciales, sino el alcance de los permisos.","Incorrecta: la identidad administrativa no hereda el acceso total y debe usar MFA y permisos acotados."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]},{id:"2.3-q23",taskId:"2.3",objetivos:["2.3#7"],tipo:"comparacion",question:"Un equipo quiere reutilizar el mismo conjunto de permisos en varios grupos y usuarios y actualizarlo una sola vez. ¿Qué diferencia entre una managed policy y una política inline sostiene esa decisión?",options:["Una managed policy es reutilizable y se adjunta a varias identidades, mientras que una política inline queda ligada a una sola identidad y no se comparte.","Una política inline se administra de forma central y se adjunta a muchas identidades, mientras que una managed policy solo existe dentro de la identidad que la crea y no se puede reutilizar.","Solo se diferencian por quién las redacta: las managed policies siempre las escribe el cliente y las políticas inline siempre las administra AWS.","La managed policy concede permisos permanentes de administrador y la política inline solo puede denegar acciones sobre un recurso concreto."],correctAnswer:0,explanation:"Las managed policies son documentos de permisos reutilizables, administrados por AWS o creados por el cliente, que se adjuntan a varias identidades y se actualizan en un solo lugar. Las políticas inline viven dentro de una única identidad, no se reutilizan y quedan para permisos muy concretos de esa identidad. Si cambia el requisito a un permiso exclusivo que no deba compartirse, encajaría una política inline.",porQueOpcion:["Correcta: la managed policy es reutilizable y la inline queda ligada a una sola identidad.","Incorrecta: invierte la definición, porque la inline es la que no se reutiliza.","Incorrecta: no se diferencian solo por quién las redacta; AWS y el cliente pueden crear managed policies.","Incorrecta: ninguna de las dos se define por conceder administrador o solo denegar."],fuentes:["https://docs.aws.amazon.com/IAM/latest/UserGuide/introduction.html"]}],2.4:[{id:"2.4-q1",taskId:"2.4",objetivos:["2.4#1"],tipo:"conocimiento",question:"¿Qué describe mejor las capacidades de seguridad que AWS ofrece a sus clientes?",options:["Un único producto de seguridad que cubre a la vez la identidad, la red, los datos y el cumplimiento en todas las cuentas de la organización.","Un conjunto de capacidades complementarias repartidas en dominios como identidad y acceso, detección, protección de datos y cumplimiento.","Un servicio que solo cifra los datos en reposo y delega al cliente el resto de las capacidades, como la detección de amenazas.","Un requisito contractual que obliga al cliente a usar hardware propio y a operarlo en sus propias instalaciones fuera de la nube."],correctAnswer:1,explanation:"AWS ofrece capacidades complementarias (identidad y acceso, protección, detección, protección de datos, visibilidad y cumplimiento). Ninguna cubre todo por sí sola: el cliente las combina dentro del modelo de responsabilidad compartida. Si el requisito pidiera un dominio concreto, la respuesta señalaría la capacidad asociada a ese riesgo.",porQueOpcion:["Incorrecta: ninguna capacidad única cubre identidad, red, datos y cumplimiento a la vez.","Correcta: AWS ofrece capacidades complementarias repartidas en dominios según el riesgo.","Incorrecta: AWS no se limita al cifrado ni delega por completo la detección al cliente.","Incorrecta: la nube no exige hardware propio ni operar fuera de AWS."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.4-q2",taskId:"2.4",objetivos:["2.4#2"],tipo:"conocimiento",question:"Un equipo necesita las certificaciones y los informes de cumplimiento vigentes que AWS emite para sus servicios. ¿Dónde los obtiene?",options:["En el portal de auto-servicio de informes de cumplimiento y acuerdos de AWS.","En el servicio de comprobaciones y recomendaciones de mejores prácticas de la cuenta.","En el servicio que agrega y prioriza los hallazgos de seguridad de la organización.","En el servicio que detecta de forma continua actividad maliciosa en la cuenta."],correctAnswer:0,explanation:"Los informes de cumplimiento y acuerdos de AWS se descargan del portal de auto-servicio de AWS (AWS Artifact). Los servicios de recomendaciones, de hallazgos agregados y de detección informan sobre el estado del entorno, pero no son la evidencia documental de cumplimiento. Si cambia la necesidad a documentación de seguridad puntual, la respuesta sería el centro de conocimiento de AWS.",porQueOpcion:["Correcta: los informes y acuerdos se obtienen del portal de auto-servicio de AWS (AWS Artifact).","Incorrecta: el servicio de comprobaciones y recomendaciones no emite la evidencia documental de cumplimiento.","Incorrecta: la agregación de hallazgos informa del estado del entorno, no de las certificaciones.","Incorrecta: el servicio de detección de amenazas no publica informes de cumplimiento."],fuentes:["https://docs.aws.amazon.com/artifact/"]},{id:"2.4-q3",taskId:"2.4",objetivos:["2.4#3"],tipo:"comparacion",question:"Un sitio web recibe dos ataques al mismo tiempo: peticiones con carga maliciosa dirigidas a los formularios y un volumen masivo de tráfico que intenta saturar el servicio. ¿Qué servicio mitiga cada ataque?",options:["Amazon GuardDuty detiene la carga maliciosa de los formularios y AWS WAF absorbe el volumen del ataque de saturación de la aplicación.","AWS WAF inspecciona y bloquea las peticiones maliciosas, y AWS Shield protege frente al ataque de denegación de servicio distribuido.","AWS Shield inspecciona el contenido de cada petición y AWS Firewall Manager absorbe el volumen del ataque de saturación sobre el sitio web.","AWS Security Hub bloquea ambos ataques a la vez y Amazon Inspector informa de las vulnerabilidades detectadas en los formularios."],correctAnswer:1,explanation:"AWS WAF filtra el contenido de las peticiones HTTP(S) y bloquea patrones maliciosos; AWS Shield protege frente a ataques DDoS que buscan agotar el servicio por volumen. Son capas distintas que se combinan. Si cambia el ataque a una inyección de código, la respuesta seguiría siendo AWS WAF.",porQueOpcion:["Incorrecta: GuardDuty detecta amenazas y no filtra el contenido de las peticiones.","Correcta: AWS WAF filtra las peticiones maliciosas y AWS Shield mitiga el ataque de volumen.","Incorrecta: Shield mitiga DDoS, pero no inspecciona el contenido de cada petición.","Incorrecta: Security Hub agrega hallazgos e Inspector evalúa vulnerabilidades; ninguno bloquea los ataques."],fuentes:["https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/waf/","https://docs.aws.amazon.com/shield/","https://docs.aws.amazon.com/firewall-manager/","https://docs.aws.amazon.com/securityhub/","https://docs.aws.amazon.com/inspector/"]},{id:"2.4-q4",taskId:"2.4",objetivos:["2.4#3"],tipo:"comparacion",question:"Un equipo quiere saber si hay comportamiento sospechoso, si sus instancias tienen vulnerabilidades conocidas y qué hallazgos de seguridad existen en la cuenta. ¿Qué servicio corresponde a cada necesidad?",options:["Amazon Inspector detecta amenazas, Amazon GuardDuty evalúa vulnerabilidades y AWS Security Hub agrega los hallazgos de toda la organización.","Amazon GuardDuty detecta amenazas, Amazon Inspector evalúa vulnerabilidades y AWS Security Hub agrega y prioriza los hallazgos.","AWS Security Hub detecta amenazas, Amazon GuardDuty evalúa vulnerabilidades y Amazon Inspector agrega los hallazgos.","Los tres servicios son intercambiables: cualquiera de ellos hace las tres funciones."],correctAnswer:1,explanation:"Amazon GuardDuty detecta actividad sospechosa a partir de señales del entorno; Amazon Inspector evalúa vulnerabilidades y exposición de las cargas de trabajo; AWS Security Hub agrega y prioriza los hallazgos de seguridad en una vista única. Si cambia la necesidad a la mitigación de un ataque de volumen, la respuesta sería AWS Shield.",porQueOpcion:["Incorrecta: intercambia los roles de Inspector y GuardDuty.","Correcta: GuardDuty detecta amenazas, Inspector evalúa vulnerabilidades y Security Hub agrega y prioriza los hallazgos.","Incorrecta: cruza por completo las funciones de los tres servicios.","Incorrecta: los tres servicios tienen funciones distintas y no son intercambiables."],fuentes:["https://docs.aws.amazon.com/inspector/","https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/securityhub/","https://docs.aws.amazon.com/shield/"]},{id:"2.4-q5",taskId:"2.4",objetivos:["2.4#3"],tipo:"escenario",question:"Una empresa ejecuta cargas de trabajo en varias cuentas y quiere aplicar las mismas reglas de protección de aplicaciones web de forma centralizada, sin configurar cada cuenta por separado. ¿Qué servicio responde mejor a esa necesidad?",options:["AWS WAF, porque crea y distribuye las reglas de forma automática en cada cuenta de la organización sin configuración central.","AWS Shield, porque distribuye y aplica la política de reglas de protección entre todas las cuentas de la organización.","AWS Firewall Manager, porque administra centralmente las políticas de protección en varias cuentas de una organización.","Amazon GuardDuty, porque aplica las reglas del firewall web a todas las cuentas de la organización."],correctAnswer:2,explanation:"AWS Firewall Manager centraliza la administración de políticas y reglas de protección (por ejemplo, de AWS WAF y AWS Shield) en varias cuentas de una organización. WAF define reglas en una cuenta; GuardDuty detecta amenazas, no administra reglas. Si cambia el requisito a filtrar el contenido de las peticiones, la respuesta sería AWS WAF.",porQueOpcion:["Incorrecta: AWS WAF define reglas en una cuenta y no las distribuye solo entre varias.","Incorrecta: AWS Shield mitiga DDoS, pero no distribuye políticas de reglas entre cuentas.","Correcta: AWS Firewall Manager administra centralmente las políticas de protección en varias cuentas.","Incorrecta: GuardDuty detecta amenazas y no aplica reglas de firewall web."],fuentes:["https://docs.aws.amazon.com/waf/","https://docs.aws.amazon.com/shield/","https://docs.aws.amazon.com/firewall-manager/","https://docs.aws.amazon.com/guardduty/"]},{id:"2.4-q6",taskId:"2.4",objetivos:["2.4#3"],tipo:"servicio",question:"Una empresa requiere evaluar de forma continua si sus instancias y contenedores tienen vulnerabilidades conocidas o configuraciones que los exponen. ¿Qué servicio de AWS está diseñado para ello?",options:["AWS Shield","Amazon Inspector","AWS Trusted Advisor","AWS Firewall Manager"],correctAnswer:1,explanation:"Amazon Inspector evalúa vulnerabilidades y exposición de cargas de trabajo; Shield mitiga ataques DDoS, Firewall Manager centraliza políticas y Trusted Advisor entrega comprobaciones y recomendaciones generales. Si cambia el requisito a detectar actividad maliciosa en la cuenta, la respuesta sería Amazon GuardDuty.",porQueOpcion:["Incorrecta: AWS Shield mitiga ataques DDoS, no evalúa vulnerabilidades.","Correcta: Amazon Inspector evalúa vulnerabilidades y exposición de instancias y contenedores.","Incorrecta: Trusted Advisor entrega recomendaciones generales, no un análisis de vulnerabilidades.","Incorrecta: Firewall Manager centraliza políticas de protección, no evalúa vulnerabilidades."],fuentes:["https://docs.aws.amazon.com/shield/","https://docs.aws.amazon.com/inspector/","https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/firewall-manager/"]},{id:"2.4-q7",taskId:"2.4",objetivos:["2.4#4"],tipo:"conocimiento",question:"Una empresa necesita una herramienta de seguridad muy específica que no quiere desarrollar y prefiere adquirirla ya integrada con AWS. ¿Qué recurso de AWS le permite encontrarla?",options:["AWS Marketplace, que ofrece productos de terceros, incluidos productos de seguridad.","AWS Artifact, que publica informes de cumplimiento.","AWS Trusted Advisor, que vende licencias de software.","AWS Security Center, que es un catálogo de productos de terceros publicados por proveedores independientes."],correctAnswer:0,explanation:"AWS Marketplace es el catálogo donde proveedores independientes publican productos y servicios, incluidos productos de seguridad de terceros. AWS Artifact publica informes de cumplimiento y Trusted Advisor entrega recomendaciones; ninguno es un catálogo de software de terceros. Si cambia el requisito a descargar informes de cumplimiento, la respuesta sería AWS Artifact.",porQueOpcion:["Correcta: AWS Marketplace ofrece productos de terceros, incluidos los de seguridad.","Incorrecta: AWS Artifact publica informes de cumplimiento, no es un catálogo de software.","Incorrecta: Trusted Advisor entrega recomendaciones y no vende licencias.","Incorrecta: AWS Security Center es un recurso informativo, no un catálogo de terceros."],fuentes:["https://docs.aws.amazon.com/marketplace/","https://docs.aws.amazon.com/artifact/","https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html"]},{id:"2.4-q8",taskId:"2.4",objetivos:["2.4#4"],tipo:"escenario",question:"Una startup quiere cumplir un requisito de seguridad sectorial y decide comprar un producto especializado de un fabricante que ya ofrece su solución en AWS, en lugar de construirlo internamente. ¿Qué afirmación describe mejor esta decisión?",options:["Es inválida: en AWS solo se puede usar software desarrollado y soportado directamente por AWS en todos los servicios.","Es posible: AWS Marketplace ofrece productos de seguridad de terceros que se adquieren como suscripciones.","Solo es posible con el plan AWS Enterprise Support contratado y con la aprobación del equipo de cuentas de AWS.","Requiere migrar primero todas las cuentas a una sola región y unificar la facturación con AWS Organizations."],correctAnswer:1,explanation:"AWS Marketplace permite adquirir y desplegar productos de terceros, incluidos productos de seguridad, sin desarrollarlos internamente. No exige un plan de soporte concreto ni limita el uso al software de AWS. Si cambia el objetivo a revisar la propia configuración, la respuesta sería un servicio de recomendaciones de la cuenta.",porQueOpcion:["Incorrecta: en AWS sí se puede usar software de terceros, no solo el de AWS.","Correcta: AWS Marketplace permite adquirir productos de seguridad de terceros como suscripciones.","Incorrecta: no se exige un plan de soporte concreto ni una aprobación especial.","Incorrecta: comprar en el Marketplace no obliga a migrar de región ni a unificar la facturación."],fuentes:["https://docs.aws.amazon.com/marketplace/","https://docs.aws.amazon.com/organizations/"]},{id:"2.4-q9",taskId:"2.4",objetivos:["2.4#5"],tipo:"conocimiento",question:"Un arquitecto necesita información oficial y actualizada sobre prácticas y novedades de seguridad de AWS. ¿Cuál es un recurso adecuado?",options:["AWS Security Blog y AWS Security Center.","AWS Shield y AWS WAF.","Amazon GuardDuty y Amazon Inspector.","AWS Firewall Manager y AWS Trusted Advisor."],correctAnswer:0,explanation:"AWS Security Blog publica artículos y novedades de seguridad, y AWS Security Center reúne la información de seguridad de AWS. Las demás opciones son servicios de protección, detección o recomendaciones, no fuentes de documentación. Si cambia la necesidad a resolver una duda puntual, la respuesta sería el centro de conocimiento de AWS.",porQueOpcion:["Correcta: el blog de seguridad publica novedades y el Security Center reúne información oficial de seguridad.","Incorrecta: Shield y WAF son servicios de protección, no fuentes de información.","Incorrecta: GuardDuty e Inspector son servicios de detección y evaluación, no documentación.","Incorrecta: Firewall Manager y Trusted Advisor son servicios operativos, no fuentes de consulta."],fuentes:["https://docs.aws.amazon.com/shield/","https://docs.aws.amazon.com/waf/","https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/inspector/","https://docs.aws.amazon.com/firewall-manager/","https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html"]},{id:"2.4-q10",taskId:"2.4",objetivos:["2.4#5"],tipo:"escenario",question:"Tras activar una opción en la consola, un ingeniero no entiende por qué una recomendación concreta no aplica a su caso y busca una explicación breve y práctica. ¿Qué recurso encaja mejor?",options:["AWS Knowledge Center, que reúne respuestas breves a dudas frecuentes y de solución de problemas.","AWS Artifact, que contiene informes de auditoría del entorno del cliente y explicaciones detalladas de cada configuración de la consola.","Amazon GuardDuty, que explica cada configuración de la consola.","AWS Shield, que documenta las opciones de la cuenta."],correctAnswer:0,explanation:"AWS Knowledge Center ofrece respuestas breves y prácticas a preguntas frecuentes. AWS Artifact entrega informes de cumplimiento; GuardDuty y Shield son servicios operativos, no fuentes de ayuda puntual. Si cambia la necesidad a entender una novedad, la respuesta sería el blog de seguridad de AWS.",porQueOpcion:["Correcta: AWS Knowledge Center reúne respuestas breves y prácticas a dudas frecuentes.","Incorrecta: AWS Artifact contiene informes de cumplimiento, no explicaciones de configuración.","Incorrecta: GuardDuty es un servicio de detección, no una fuente de ayuda.","Incorrecta: Shield es un servicio de protección y no documenta las opciones de la cuenta."],fuentes:["https://docs.aws.amazon.com/artifact/","https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/shield/"]},{id:"2.4-q11",taskId:"2.4",objetivos:["2.4#6"],tipo:"conocimiento",question:"¿Qué hace por un cliente el servicio de revisión proactiva que señala mejores prácticas?",options:["Corrige automáticamente las configuraciones inseguras de la cuenta y aplica por sí mismo las mejores prácticas que detecta en el entorno.","Revisa el entorno y entrega comprobaciones y recomendaciones en categorías como seguridad, rendimiento y optimización de costes.","Emite los informes de cumplimiento que exige un auditor y los acuerdos aplicables a la organización.","Sustituye al firewall de aplicaciones web en la protección de las aplicaciones y del tráfico entrante."],correctAnswer:1,explanation:"AWS Trusted Advisor inspecciona el entorno y entrega comprobaciones y recomendaciones. No aplica cambios por el cliente, no emite informes de cumplimiento y no sustituye a los servicios de protección. Si cambia el requisito a mostrar una vista única de hallazgos, la respuesta sería un servicio de agregación de hallazgos.",porQueOpcion:["Incorrecta: Trusted Advisor no aplica cambios por el cliente, solo recomienda.","Correcta: Trusted Advisor revisa el entorno y entrega comprobaciones en categorías como seguridad, rendimiento y coste.","Incorrecta: los informes de cumplimiento los publica AWS Artifact, no Trusted Advisor.","Incorrecta: Trusted Advisor no sustituye a AWS WAF ni protege el tráfico."],fuentes:["https://docs.aws.amazon.com/artifact/","https://docs.aws.amazon.com/waf/","https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html"]},{id:"2.4-q12",taskId:"2.4",objetivos:["2.4#3"],tipo:"tradeoff",question:"Un equipo debe elegir cómo cubrir la detección de amenazas frente a la evaluación de vulnerabilidades. Sin embargo, aunque ambos problemas son relevantes, solo hay presupuesto para contratar un servicio este trimestre. ¿Qué criterio de decisión es correcto?",options:["Elegir Amazon GuardDuty si la prioridad es detectar comportamiento sospechoso; elegir Amazon Inspector si la prioridad es encontrar vulnerabilidades.","Elegir Amazon GuardDuty si la prioridad es encontrar vulnerabilidades; elegir Amazon Inspector si la prioridad es detectar amenazas sobre la actividad.","Elegir AWS Security Hub si la prioridad es proteger frente a ataques de volumen; elegir AWS Shield si la prioridad es agregar los hallazgos de seguridad.","Los tres servicios son equivalentes y la elección no cambia el resultado, porque todos detectan amenazas y evalúan vulnerabilidades."],correctAnswer:0,explanation:"Amazon GuardDuty se orienta a la detección de amenazas sobre la actividad del entorno; Amazon Inspector, a la evaluación de vulnerabilidades y exposición de las cargas. Son necesidades distintas, por eso el criterio depende de la prioridad. Si cambia la prioridad a mitigar un ataque de volumen, la respuesta sería AWS Shield.",porQueOpcion:["Correcta: GuardDuty se orienta a detectar amenazas y Inspector a evaluar vulnerabilidades.","Incorrecta: invierte la prioridad, porque GuardDuty no busca vulnerabilidades.","Incorrecta: Security Hub agrega hallazgos y Shield mitiga ataques de volumen, no al contrario.","Incorrecta: los servicios no son equivalentes y la elección cambia el resultado."],fuentes:["https://docs.aws.amazon.com/guardduty/","https://docs.aws.amazon.com/inspector/","https://docs.aws.amazon.com/securityhub/","https://docs.aws.amazon.com/shield/"]},{id:"2.4-q13",taskId:"2.4",objetivos:["2.4#1"],tipo:"escenario",question:"Una empresa pregunta qué capacidades de seguridad necesita cubrir además del cifrado. ¿Qué respuesta describe mejor el enfoque de AWS?",options:["Combinar capacidades complementarias de identidad, protección, detección, visibilidad y cumplimiento según el riesgo a reducir.","Contratar un único servicio de seguridad que cubra a la vez todos los dominios y no requiera configuración adicional en la cuenta.","Delegar todas las capacidades en AWS, que las habilita por defecto en cada cuenta y las opera en nombre del cliente.","Limitarse al cifrado en reposo y en tránsito, porque el resto de capacidades las aporta la infraestructura de AWS."],correctAnswer:0,explanation:"Las capacidades de seguridad de AWS se reparten en dominios complementarios y se eligen según el riesgo que se quiera reducir. Ningún servicio único cubre todos los dominios ni AWS opera la configuración del cliente. Si el requisito priorizara la identidad, la respuesta sería la capacidad de identidad y acceso.",porQueOpcion:["Correcta: las capacidades se reparten en dominios complementarios y se eligen según el riesgo.","Incorrecta: ningún servicio único cubre todos los dominios de seguridad.","Incorrecta: AWS no habilita todas las capacidades ni opera la configuración del cliente.","Incorrecta: limitarse al cifrado deja sin cubrir identidad, detección y cumplimiento."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.4-q14",taskId:"2.4",objetivos:["2.4#2"],tipo:"escenario",question:"Un equipo necesita localizar información oficial de seguridad para resolver una incidencia concreta y, por separado, entender una novedad de seguridad publicada por AWS. ¿Qué recursos encajan?",options:["Las respuestas breves del centro de conocimiento para la incidencia y el blog de seguridad para la novedad.","Los informes de cumplimiento para ambos casos, porque recogen toda la información de seguridad de AWS.","El panel de revisión de mejores prácticas para la incidencia y los foros de terceros para la novedad.","La consola del servicio de detección de amenazas para la incidencia y sus propios boletines para la novedad."],correctAnswer:0,explanation:"El centro de conocimiento de AWS resuelve dudas puntuales y el blog de seguridad publica artículos y novedades. Los informes de cumplimiento no explican incidencias concretas y los foros de terceros no son la fuente oficial. Si cambia la necesidad a evidencia de cumplimiento, la respuesta sería el portal de informes de AWS.",porQueOpcion:["Correcta: el centro de conocimiento resuelve la incidencia y el blog de seguridad explica la novedad.","Incorrecta: los informes de cumplimiento no explican incidencias ni novedades técnicas.","Incorrecta: los foros de terceros no son la fuente oficial y el panel no resuelve la incidencia.","Incorrecta: la consola de detección y sus boletines no son el recurso de consulta adecuado."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-risk-and-compliance/shared-responsibility-model.html"]},{id:"2.4-q15",taskId:"2.4",objetivos:["2.4#6"],tipo:"escenario",question:"Un ingeniero no entiende por qué una comprobación de seguridad de la consola no aplica a su caso y quiere entender el criterio de la recomendación. ¿Qué debería hacer?",options:["Consultar la explicación de la comprobación en el servicio de revisión proactiva, que señala el motivo y la mejor práctica.","Desactivar la comprobación para que no vuelva a aparecer en el informe de recomendaciones de la cuenta.","Abrir el servicio de detección de amenazas y esperar a que genere un hallazgo sobre la configuración revisada en el panel de la cuenta.","Descargar los informes de cumplimiento y buscar la comprobación entre sus acuerdos aplicables al sector."],correctAnswer:0,explanation:"AWS Trusted Advisor explica cada comprobación y la mejor práctica asociada, además de por qué puede no aplicar a un caso concreto. Desactivarla oculta el aviso; los servicios de detección y los informes de cumplimiento no explican esa recomendación. Si cambia la necesidad a centralizar hallazgos, la respuesta sería un servicio de agregación.",porQueOpcion:["Correcta: Trusted Advisor explica la comprobación, el motivo y la mejor práctica aplicable.","Incorrecta: desactivar la comprobación oculta el aviso en lugar de explicarlo.","Incorrecta: el servicio de detección no explica el criterio de una recomendación.","Incorrecta: los informes de cumplimiento no contienen la explicación de esa comprobación."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html"]},{id:"2.4-q16",taskId:"2.4",objetivos:["2.4#6"],tipo:"comparacion",question:"¿Qué distingue la revisión proactiva de la cuenta de la centralización de hallazgos de seguridad?",options:["La revisión proactiva analiza la configuración propia y recomienda mejoras; la centralización reúne y prioriza hallazgos de varios servicios y cuentas.","La revisión proactiva reúne los hallazgos de otros servicios de seguridad; la centralización analiza la configuración y recomienda mejoras en la cuenta.","Ambos servicios son equivalentes y solo cambian de nombre según el plan de soporte que tenga contratado el cliente.","Ambos servicios corrigen de forma automática los problemas que detectan y no requieren intervención del cliente."],correctAnswer:0,explanation:"La revisión proactiva (AWS Trusted Advisor) analiza la configuración de la cuenta y propone mejoras, mientras que la centralización (AWS Security Hub) agrega y prioriza hallazgos de varios servicios. Son funciones distintas y complementarias. Si cambia el requisito a evaluar vulnerabilidades, la respuesta sería Amazon Inspector.",porQueOpcion:["Correcta: la revisión proactiva analiza la configuración y la centralización agrupa hallazgos.","Incorrecta: invierte las funciones, pues la revisión proactiva no reúne hallazgos de otros servicios.","Incorrecta: son servicios distintos y no dependen solo del plan de soporte.","Incorrecta: ninguno corrige los problemas de forma automática."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/securityhub/","https://docs.aws.amazon.com/inspector/"]},{id:"2.4-q17",taskId:"2.4",objetivos:["2.4#4"],tipo:"comparacion",question:"Una empresa necesita una herramienta de seguridad especializada para cumplir un requisito sectorial y duda entre adquirir un producto de un proveedor externo ofrecido en el catálogo de AWS o cubrir la necesidad con un servicio de seguridad nativo de AWS. ¿Qué caracteriza a cada opción?",options:["El catálogo de terceros solo publica productos gratuitos y sin soporte, mientras que el servicio nativo obliga a la empresa a desarrollar, operar y mantener la herramienta con su propio equipo en todas las regiones.","El catálogo ofrece productos de proveedores externos como suscripciones integradas; el servicio nativo lo opera y soporta AWS dentro de su alcance.","Ambas opciones son equivalentes: cualquier producto externo del catálogo pasa a convertirse en un servicio nativo operado directamente por AWS en la cuenta del cliente.","El servicio nativo solo está disponible si se contrata el plan de soporte empresarial, y el catálogo de terceros exige migrar todas las cuentas a una sola región antes de comprar."],correctAnswer:1,explanation:"En el catálogo de terceros el cliente adquiere la solución de un proveedor externo por suscripción y la integra en su entorno, y ese proveedor responde de su producto; en el servicio nativo es AWS quien opera y soporta la capacidad dentro de su alcance. El primer distractor falla porque el catálogo no se limita a productos gratuitos ni obliga a desarrollar la herramienta. El tercero falla porque un producto de terceros no se convierte en un servicio de AWS. El cuarto falla porque el servicio nativo no depende del plan de soporte empresarial ni el catálogo obliga a migrar de región. Si cambia el requisito a descargar informes de cumplimiento, la respuesta sería AWS Artifact.",porQueOpcion:["Incorrecta: el catálogo no se limita a productos gratuitos ni el servicio nativo obliga a desarrollar la herramienta.","Correcta: el catálogo integra productos de terceros por suscripción y el servicio nativo lo opera y soporta AWS.","Incorrecta: un producto de terceros no se convierte en un servicio nativo de AWS.","Incorrecta: el servicio nativo no depende del plan de soporte ni el catálogo obliga a migrar de región."],fuentes:["https://docs.aws.amazon.com/artifact/"]}],3.1:[{id:"3.1-q1",taskId:"3.1",objetivos:["3.1#1"],tipo:"conocimiento",question:"¿Cuál de las siguientes opciones describe formas válidas de aprovisionar y operar recursos en la nube de AWS?",options:["Únicamente mediante llamadas a la API desde el navegador, porque AWS no ofrece ninguna otra vía para crear y operar recursos.","Mediante consola, CLI, SDK, infraestructura como código y servicios gestionados de plataforma.","Solo con procesos manuales asistidos por el soporte de AWS, porque la plataforma no admite automatización de ningún tipo.","Únicamente a través de un proveedor externo que gestione la cuenta y cree los recursos en nombre del cliente."],correctAnswer:1,explanation:"El aprovisionamiento y la operación admiten varios niveles: acceso manual por consola, acceso programático por CLI, SDK y API, infraestructura como código para procesos reproducibles y servicios gestionados que aprovisionan por el usuario. Las opciones que reducen todo a la API, a procesos manuales o a un proveedor externo niegan vías que existen de verdad, y AWS sí admite automatización. Si el requisito fuera reproducir entornos idénticos de forma auditable, la vía principal sería la infraestructura como código; si cambiara a una exploración puntual, bastaría la consola.",porQueOpcion:["Incorrecta: reducir el aprovisionamiento a la API desde el navegador niega la consola, la CLI, los SDK y la infraestructura como código.","Correcta: consola, CLI, SDK, infraestructura como código y servicios gestionados son las vías válidas para aprovisionar y operar recursos.","Incorrecta: AWS sí admite automatización, por lo que no depende solo de procesos manuales asistidos por soporte.","Incorrecta: el cliente puede operar sus propios recursos, así que no necesita delegar toda la cuenta en un proveedor externo."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q2",taskId:"3.1",objetivos:["3.1#2"],tipo:"conocimiento",question:"Un equipo necesita elegir cómo interactuará con los servicios de AWS. ¿Qué conjunto reúne formas de acceso válidas?",options:["La consola de administración, la interfaz de línea de comandos, los SDK y la API.","Solo la consola de administración, porque es la única vía oficial y el resto de interfaces no existen para el cliente.","Únicamente el correo electrónico y el teléfono al soporte técnico, además del acceso físico a los centros de datos.","Las herramientas de terceros y el correo electrónico son las únicas formas admitidas de interactuar con la plataforma."],correctAnswer:0,explanation:"Las formas de acceso son la consola de administración, la interfaz de línea de comandos, los SDK y la API, y sobre ellas se construye la infraestructura como código. La consola no es la única vía, y no se accede a los servicios por correo, teléfono ni acceso físico a los centros de datos. Si el requisito cambiara a dejar una definición versionada y repetible del entorno, la respuesta apuntaría a la infraestructura como código.",porQueOpcion:["Correcta: consola de administración, CLI, SDK y API son las formas de acceso válidas a los servicios de AWS.","Incorrecta: la consola no es la única vía oficial, ya que la CLI, los SDK y la API también existen para el cliente.","Incorrecta: no se accede a los servicios por correo, teléfono ni físicamente a los centros de datos.","Incorrecta: las herramientas de terceros y el correo electrónico no son formas admitidas de interactuar con la plataforma."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q3",taskId:"3.1",objetivos:["3.1#4"],tipo:"comparacion",question:"Un equipo debe decidir cómo crear cientos de recursos idénticos que deben reproducirse igual en varios entornos. ¿Qué opción encaja mejor y por qué?",options:["La consola de administración, porque es la forma más rápida de repetir cientos de recursos idénticos y deja una plantilla versionada reutilizable.","La infraestructura como código, porque describe los recursos en archivos versionados y los reproduce de forma consistente.","La interfaz de línea de comandos escrita a mano una vez, sin guardar los comandos, porque repetir los pasos a mano garantiza el mismo resultado.","El soporte técnico de AWS, que crea los recursos por el cliente y mantiene una definición del entorno lista para auditorías."],correctAnswer:1,explanation:"La infraestructura como código es la opción para reproducir el mismo entorno de forma consistente y auditable: el estado deseado queda en archivos versionados. La consola es visual y puntual, y no deja plantilla; unos comandos sueltos de CLI sin guardar no son una definición reutilizable; y el soporte no crea el entorno por el cliente. Si cambiara el requisito a un ajuste puntual sin reproducibilidad, la consola o la CLI serían suficientes.",porQueOpcion:["Incorrecta: la consola es visual y puntual y no deja una plantilla versionada reutilizable.","Correcta: la infraestructura como código describe los recursos en archivos versionados y los reproduce de forma consistente.","Incorrecta: unos comandos de CLI sin guardar no son una definición reutilizable ni garantizan el mismo resultado.","Incorrecta: el soporte técnico no crea el entorno por el cliente ni mantiene una definición lista para auditorías."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q4",taskId:"3.1",objetivos:["3.1#4"],tipo:"escenario",question:"Una persona nueva en el equipo necesita explorar visualmente los servicios y crear un recurso puntual con rapidez, sin automatizar y con un plazo muy ajustado. Aunque la organización planea automatizar entornos más adelante, esta tarea es única. ¿Qué método de acceso es el más adecuado?",options:["La consola de administración, por su enfoque visual y guiado.","La infraestructura como código, porque es obligatoria para cualquier recurso.","La API directamente, escribiendo las peticiones firmadas a mano.","Un script de CLI sin documentación."],correctAnswer:0,explanation:"La consola de administración es la vía visual y guiada, ideal para explorar y para tareas puntuales. La infraestructura como código no es obligatoria para cada recurso y no es el medio natural para explorar; escribir peticiones firmadas a mano a la API añade complejidad innecesaria, y un script sin documentación no deja una definición reutilizable. Si el escenario cambiara a reproducir el mismo entorno cada semana, la respuesta sería la infraestructura como código.",porQueOpcion:["Correcta: la consola de administración es visual y guiada, ideal para explorar y para tareas puntuales.","Incorrecta: la infraestructura como código no es obligatoria para cada recurso y no es el medio natural para explorar.","Incorrecta: escribir peticiones firmadas a mano a la API añade complejidad innecesaria para una tarea puntual.","Incorrecta: un script sin documentación no deja una definición reutilizable ni es adecuado para explorar."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q5",taskId:"3.1",objetivos:["3.1#3"],tipo:"conocimiento",question:"¿Cuáles son los tipos de modelos de despliegue en la nube?",options:["Nube, híbrido y on-premises.","Público, privado y gratuito.","Regional, zonal y local.","Manual, automático y semiautomático."],correctAnswer:0,explanation:"Los modelos de despliegue son cloud (todo en la nube), on-premises (todo en instalaciones propias) e híbrido (combinación de ambos). Público y privado describen el tipo de nube, no el modelo de despliegue; regional y zonal describen alcance de infraestructura; y manual o automático describen el grado de automatización. Si el requisito fuera combinar instalaciones propias con la nube, la respuesta sería el modelo híbrido.",porQueOpcion:["Correcta: nube, híbrido y on-premises son los modelos de despliegue en la nube.","Incorrecta: público y privado describen el tipo de nube, no el modelo de despliegue.","Incorrecta: regional y zonal describen el alcance de la infraestructura, no el modelo de despliegue.","Incorrecta: manual y automático describen el grado de automatización, no el modelo de despliegue."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q6",taskId:"3.1",objetivos:["3.1#6"],tipo:"conocimiento",question:"Una organización quiere identificar qué modelo de despliegue describe cada situación. ¿Qué afirmación es correcta?",options:["Cloud: todo el entorno se ejecuta en la nube; on-premises: todo se ejecuta en instalaciones propias; híbrido: combina ambos.","Híbrido significa usar a la vez dos proveedores de nube distintos y repartir entre ellos la misma carga, sin conexión con instalaciones propias.","On-premises significa alojar los datos en la nube pública y mantener solo el acceso desde el edificio de la empresa.","Cloud significa tener los servidores en el edificio de la empresa y contratar la refrigeración como servicio externo."],correctAnswer:0,explanation:"Cloud ejecuta todo en la nube, on-premises todo en instalaciones propias e híbrido combina las dos anteriores. Usar varios proveedores de nube es multinube, no híbrido, y cloud no implica tener servidores propios. Si el requisito fuera mantener datos en las instalaciones y usar la nube para el análisis, la opción sería híbrido.",porQueOpcion:["Correcta: cloud ejecuta todo en la nube, on-premises todo en instalaciones propias e híbrido combina ambos.","Incorrecta: usar dos proveedores de nube es multinube, no híbrido, y no describe la combinación con instalaciones propias.","Incorrecta: on-premises ejecuta en instalaciones propias, no aloja los datos en la nube pública.","Incorrecta: cloud ejecuta en la nube, no en el edificio de la empresa con refrigeración externa."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q7",taskId:"3.1",objetivos:["3.1#6"],tipo:"escenario",question:"Una empresa del sector sanitario debe mantener ciertos datos en sus instalaciones por normativa, pero quiere usar servicios de nube para el análisis y el escalado. ¿Qué modelo de despliegue encaja?",options:["On-premises puro, manteniendo todo en el centro de datos propio y renunciando a la nube para el análisis y el escalado.","Híbrido, que combina las instalaciones propias con la nube de AWS.","Solo nube pública, trasladando también los datos que la normativa obliga a retener en las instalaciones.","Solo ubicaciones de borde, sin usar ninguna región, para acercar el contenido al usuario."],correctAnswer:1,explanation:"Cuando una parte del entorno debe permanecer en las instalaciones y otra puede aprovechar la nube, el modelo es híbrido. On-premises puro renuncia al análisis y al escalado, mover todos los datos incumpliría la normativa y las ubicaciones de borde no sustituyen a la región. Si el requisito fuera cumplir la normativa sin usar la nube en absoluto, el modelo sería on-premises.",porQueOpcion:["Incorrecta: on-premises puro renuncia a la nube para el análisis y el escalado que la empresa necesita.","Correcta: el modelo híbrido combina las instalaciones propias que exige la normativa con la nube de AWS.","Incorrecta: mover a la nube pública los datos que la normativa obliga a retener en las instalaciones la incumpliría.","Incorrecta: las ubicaciones de borde no sustituyen a la región ni resuelven la retención normativa de los datos."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q8",taskId:"3.1",objetivos:["3.1#5"],tipo:"comparacion",question:"Un equipo debe decidir entre una operación puntual y un proceso repetible. ¿Qué criterio los distingue?",options:["La operación puntual se ejecuta una sola vez; el proceso repetible se define una vez y se vuelve a ejecutar de forma consistente.","La operación puntual es siempre más segura y auditable que el proceso repetible, porque una persona revisa cada paso de la ejecución.","El proceso repetible solo sirve para eliminar recursos ociosos, mientras que la operación puntual es la única vía para crear entornos nuevos.","Ambos enfoques son iguales y solo cambia el nombre según quién los ejecute, sin que la frecuencia de uso altere la decisión."],correctAnswer:0,explanation:"La operación puntual cubre una necesidad que no se repite; el proceso repetible se diseña para reejecutarse con el mismo resultado. La operación puntual no es más segura por sí sola, el proceso repetible no se limita a eliminar recursos y ambos no son equivalentes. Si cambiara el requisito a una tarea que se repite cada semana en varios entornos, la respuesta sería el proceso repetible.",porQueOpcion:["Correcta: la operación puntual se ejecuta una sola vez y el proceso repetible se define para reejecutarse de forma consistente.","Incorrecta: la operación puntual no es más segura ni auditable por el simple hecho de revisarla una persona.","Incorrecta: el proceso repetible sirve para crear entornos, no solo para eliminar recursos ociosos.","Incorrecta: ambos enfoques no son equivalentes, ya que difieren en frecuencia y reproducibilidad."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q9",taskId:"3.1",objetivos:["3.1#5"],tipo:"escenario",question:"Un equipo crea cada semana un entorno de pruebas idéntico al de producción. ¿Qué enfoque reduce el trabajo manual y los errores?",options:["Repetir el proceso manualmente cada semana en la consola, confiando en la memoria del equipo para no olvidar pasos.","Definir el entorno como código y volver a desplegarlo con una definición versionada.","Crear el entorno una vez y no volver a actualizarlo, aunque cambien el código ni la configuración de la aplicación.","Pedir a cada desarrollador que memorice los pasos y los replique a mano cada vez que necesite un entorno nuevo."],correctAnswer:1,explanation:"Un proceso que se repite es candidato a automatizarse: definir el entorno como código y desplegarlo con una definición versionada garantiza resultados idénticos y deja trazabilidad. Repetir pasos a mano, congelar el entorno o memorizar pasos mantiene el error humano. Si el requisito cambiara a una única prueba desechable sin reutilización, bastaría una operación puntual en la consola.",porQueOpcion:["Incorrecta: repetir pasos a mano confiando en la memoria del equipo mantiene el error humano.","Correcta: definir el entorno como código y desplegarlo con una definición versionada garantiza resultados idénticos.","Incorrecta: congelar el entorno sin actualizarlo desincroniza las pruebas de producción.","Incorrecta: memorizar y replicar los pasos a mano no reduce el trabajo manual ni los errores."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q10",taskId:"3.1",objetivos:["3.1#2"],tipo:"servicio",question:"Una arquitecta quiere ejecutar tareas de administración mediante comandos desde su terminal y automatizarlas en scripts. ¿Qué herramienta de AWS usaría?",options:["AWS CLI","Amazon CloudFront","Amazon Route 53","AWS Artifact"],correctAnswer:0,explanation:"AWS CLI permite ejecutar acciones de administración desde la terminal y encadenarlas en scripts, lo que encaja con el acceso programático por línea de comandos. CloudFront y Route 53 son servicios de red y entrega, y AWS Artifact ofrece informes de cumplimiento; ninguno ejecuta comandos de administración. Si el requisito fuera reproducir entornos completos de forma versionada en lugar de ejecutar comandos sueltos, la herramienta sería la infraestructura como código.",porQueOpcion:["Correcta: AWS CLI permite ejecutar acciones de administración desde la terminal y encadenarlas en scripts.","Incorrecta: Amazon CloudFront es un servicio de entrega de contenido y no ejecuta comandos de administración.","Incorrecta: Amazon Route 53 es un servicio de DNS y no sirve para ejecutar tareas de administración desde la terminal.","Incorrecta: AWS Artifact entrega informes de cumplimiento y no ejecuta comandos de administración."],fuentes:["https://docs.aws.amazon.com/cli/","https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/Introduction.html","https://docs.aws.amazon.com/artifact/","https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/Welcome.html"]},{id:"3.1-q11",taskId:"3.1",objetivos:["3.1#1"],tipo:"casoDeUso",question:"Un equipo quiere desplegar una aplicación web sin gestionar los servidores ni la infraestructura subyacente, subiendo solo el código. ¿Qué opción encaja mejor?",options:["AWS Elastic Beanstalk, que aprovisiona y opera los recursos por el usuario.","Crear cada instancia de Amazon EC2 a mano en la consola, aplicando parches y escalando el equipo de forma manual.","Montar un centro de datos propio con servidores físicos para no depender de proveedores externos de nube.","Usar únicamente AWS Artifact para desplegar el código y delegar en AWS la operación de los servidores."],correctAnswer:0,explanation:"AWS Elastic Beanstalk aprovisiona y opera la infraestructura por el usuario a partir del código de la aplicación, lo que permite desplegar sin gestionar los servidores. Crear instancias a mano, montar un centro de datos propio o usar un servicio de informes de cumplimiento implican gestionar infraestructura o no despliegan código. Si el escenario pidiera control total del sistema operativo, la respuesta cambiaría a instancias de Amazon EC2 administradas por el equipo.",porQueOpcion:["Correcta: AWS Elastic Beanstalk aprovisiona y opera la infraestructura a partir del código, sin gestionar servidores.","Incorrecta: crear instancias EC2 a mano implica gestionar la infraestructura que se quiere evitar.","Incorrecta: montar un centro de datos propio no despliega el código sin gestionar servidores.","Incorrecta: AWS Artifact ofrece informes de cumplimiento y no despliega código ni opera servidores."],fuentes:["https://docs.aws.amazon.com/elasticbeanstalk/latest/dg/Welcome.html","https://docs.aws.amazon.com/ec2/","https://docs.aws.amazon.com/artifact/"]},{id:"3.1-q12",taskId:"3.1",objetivos:["3.1#3"],tipo:"tradeoff",question:"¿Qué trade-off describe mejor elegir on-premises frente a la nube de AWS?",options:["On-premises da control total sobre la infraestructura, pero exige comprar capacidad por adelantado y mantenerla; la nube aporta elasticidad y pago por uso.","On-premises es siempre más barato y más elástico que la nube, porque no paga licencias y añade capacidad automáticamente en los picos de demanda.","La nube elimina toda responsabilidad del cliente sobre la seguridad de los datos, que pasa a ser gestionada íntegramente por el proveedor sin tareas del cliente.","On-premises no permite ejecutar bases de datos ni aplicaciones web, ya que solo admite sistemas operativos heredados y sin soporte."],correctAnswer:0,explanation:"On-premises ofrece control total a cambio de inversión anticipada y mantenimiento; la nube aporta elasticidad y pago por uso. On-premises no es más elástico ni automáticamente más barato, la nube no elimina la responsabilidad del cliente sobre la seguridad y sí permite ejecutar bases de datos. Si el requisito fuera crecer y decrecer con la demanda pagando solo por el uso, la respuesta sería la nube.",porQueOpcion:["Correcta: on-premises da control total pero exige inversión anticipada y mantenimiento, mientras la nube aporta elasticidad y pago por uso.","Incorrecta: on-premises no es más elástico, ya que no añade capacidad automáticamente en los picos de demanda.","Incorrecta: en la nube el cliente conserva responsabilidades de seguridad sobre sus datos.","Incorrecta: on-premises sí permite ejecutar bases de datos y aplicaciones web modernas."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q13",taskId:"3.1",objetivos:["3.1#2"],tipo:"escenario",question:"Un equipo debe decidir cómo interactuará con los servicios según la tarea. ¿Qué opción describe mejor el uso adecuado de cada forma de acceso?",options:["La consola para explorar y hacer tareas puntuales; la CLI y los SDK para automatizar desde scripts y aplicaciones; la IaC para reproducir entornos versionados.","La consola de administración para absolutamente todo, porque es la única vía oficial; la CLI y los SDK solo sirven para consultar la factura y no pueden crear recursos.","La CLI para todo, ya que no admite scripts; los SDK solo funcionan dentro de la consola y la IaC no permite versionar la definición del entorno.","La IaC para cualquier ajuste puntual, la consola para reproducir entornos enteros y los SDK para operar únicamente desde el navegador."],correctAnswer:0,explanation:"Cada vía encaja en un momento: la consola es visual y puntual, la CLI y los SDK automatizan desde scripts y aplicaciones, y la infraestructura como código reproduce entornos versionados. Reducir todo a la consola o a la CLI niega vías reales, y la IaC no es el medio natural para ajustes puntuales. Si cambiara el requisito a una exploración rápida sin automatización, la consola sería la opción adecuada.",porQueOpcion:["Correcta: la consola sirve para explorar, la CLI y los SDK para automatizar y la IaC para reproducir entornos versionados.","Incorrecta: la CLI y los SDK también crean recursos, no solo consultan la factura, y la consola no es la única vía.","Incorrecta: la CLI sí admite scripts, los SDK no funcionan solo dentro de la consola y la IaC sí versiona la definición.","Incorrecta: la IaC no es para ajustes puntuales, la consola no reproduce entornos enteros y los SDK no operan desde el navegador."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]},{id:"3.1-q14",taskId:"3.1",objetivos:["3.1#3","3.1#6"],tipo:"comparacion",question:"Una empresa debate dónde ejecutar cada carga. ¿Qué afirmación distingue correctamente los modelos de despliegue nube, híbrido y on-premises?",options:["La nube ejecuta todo el entorno en instalaciones propias; el híbrido solo en proveedores externos; y on-premises combina ambos mundos indistintamente.","La nube ejecuta todo en la nube; el híbrido combina instalaciones propias con la nube; on-premises mantiene todo en instalaciones propias.","La nube y on-premises son sinónimos, y el híbrido se define por usar dos proveedores de nube a la vez.","El híbrido describe el uso de varias regiones, on-premises el uso de varias zonas y la nube un único centro de datos."],correctAnswer:1,explanation:"La nube ejecuta todo en la nube, on-premises todo en instalaciones propias y el híbrido combina ambos. Confundir híbrido con multinube o con varias regiones es el error típico. Si el requisito fuera mantener datos en las instalaciones y usar la nube para el análisis, la respuesta sería el modelo híbrido.",porQueOpcion:["Incorrecta: invierte los modelos, ya que la nube no ejecuta en instalaciones propias ni on-premises combina ambos mundos.","Correcta: la nube ejecuta todo en la nube, el híbrido combina instalaciones propias con la nube y on-premises mantiene todo en instalaciones propias.","Incorrecta: nube y on-premises no son sinónimos, y el híbrido no se define por usar dos proveedores de nube a la vez.","Incorrecta: el híbrido no describe el uso de varias regiones ni on-premises el de varias zonas."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/introduction-devops-aws/infrastructure-as-code.html"]}],3.2:[{id:"3.2-q1",taskId:"3.2",objetivos:["3.2#1"],tipo:"conocimiento",question:"¿Qué describe correctamente la relación entre una región de AWS y sus Availability Zones?",options:["Cada Availability Zone contiene varias regiones independientes.","Una región es un área geográfica que agrupa varias Availability Zones aisladas entre sí.","Una Availability Zone es un punto de presencia para entrega de contenido, no un centro de datos.","Las Availability Zones de una región comparten alimentación y red, por lo que fallan a la vez."],correctAnswer:1,explanation:"Una región es un área geográfica compuesta por varias Availability Zones aisladas, cada una con su propia alimentación, refrigeración y red. Las AZ no comparten punto único de fallo y los puntos de presencia son las edge locations, no al revés. Si el requisito fuera describir dónde se acerca el contenido al usuario, la respuesta apuntaría a las edge locations.",porQueOpcion:["Incorrecta: una Availability Zone no contiene varias regiones, sino que forma parte aislada de una región.","Correcta: una región es un área geográfica que agrupa varias Availability Zones aisladas entre sí.","Incorrecta: la Availability Zone es un centro de datos aislado, no un punto de presencia para entrega de contenido.","Incorrecta: cada Availability Zone tiene alimentación y red propias, por lo que no fallan a la vez."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q2",taskId:"3.2",objetivos:["3.2#5"],tipo:"comparacion",question:"Un equipo discute dónde alojar cada pieza de su arquitectura. ¿Qué afirmación distingue correctamente región, Availability Zone y edge location?",options:["La región es el punto de presencia más cercano al usuario final y la edge location es la que agrupa los centros de datos aislados de esa área.","La Availability Zone es el área geográfica de mayor alcance y la región es cada uno de los centros de datos aislados, con su propia energía, refrigeración y red, que la componen.","La región es el área geográfica, la Availability Zone es un centro de datos aislado dentro de ella y la edge location es un punto de presencia para entrega de contenido.","Los tres términos son equivalentes y solo cambian de nombre según el servicio que se use."],correctAnswer:2,explanation:"La jerarquía es: región (área geográfica) → Availability Zones (centros de datos aislados dentro de la región) → edge locations (puntos de presencia fuera de ese eje, para entrega de contenido y DNS). Invertir la jerarquía o tratarlos como sinónimos es el error típico. Si el requisito fuera alojar la base de datos de forma tolerante a fallos, la capa relevante serían las Availability Zones de la región.",porQueOpcion:["Incorrecta: la edge location es el punto de presencia cercano al usuario, no la región, y la Availability Zone es el centro de datos aislado.","Incorrecta: invierte la jerarquía, ya que la región es el área geográfica y la Availability Zone el centro de datos aislado que la compone.","Correcta: la región es el área geográfica, la Availability Zone un centro de datos aislado dentro de ella y la edge location un punto de presencia.","Incorrecta: los tres términos no son equivalentes, ya que describen capas distintas de la infraestructura global."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q3",taskId:"3.2",objetivos:["3.2#5"],tipo:"escenario",question:"Una empresa debe explicar por qué despliega su base de datos en una región concreta y sirve las imágenes desde muchos países. ¿Qué combinación describe mejor el uso de cada capa?",options:["Los datos y el cómputo viven en una región y sus Availability Zones; la entrega global se apoya en edge locations.","Los datos viven en una edge location y el contenido se distribuye desde la región hacia todos los usuarios globales.","La base de datos se replica en todas las edge locations y el cómputo queda en una sola Availability Zone de la región.","Las edge locations sustituyen a la región cuando el tráfico es global y eliminan la necesidad de fijar una ubicación."],correctAnswer:0,explanation:"La región (con sus AZ) aloja datos y cómputo; las edge locations acercan la entrega de contenido al usuario. Las edge locations no alojan bases de datos ni sustituyen a la región, y la base de datos no se replica en cada punto de presencia. Si el escenario pidiera reducir la latencia de descarga sin mover el dato, bastaría apoyarse en el edge.",porQueOpcion:["Correcta: los datos y el cómputo viven en la región y sus Availability Zones, y las edge locations acercan la entrega global.","Incorrecta: los datos no viven en una edge location y el contenido se distribuye desde el edge, no desde la región.","Incorrecta: las edge locations no alojan la base de datos y el cómputo no queda en una sola Availability Zone.","Incorrecta: las edge locations no sustituyen a la región ni eliminan la necesidad de fijar una ubicación."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q4",taskId:"3.2",objetivos:["3.2#2"],tipo:"conocimiento",question:"¿Qué significa que un sistema tenga alta disponibilidad?",options:["Que guarda copias de seguridad diarias de sus datos y las conserva en varias regiones del mundo.","Que puede seguir atendiendo el servicio aunque falle un componente, gracias a la redundancia.","Que responde a los usuarios desde el punto de presencia más cercano, reduciendo la latencia de cada petición.","Que reparte los costes entre varias cuentas de AWS mediante una única factura consolidada."],correctAnswer:1,explanation:"Alta disponibilidad es seguir operando pese al fallo de un componente. Se consigue con redundancia activa, por ejemplo desplegando en varias Availability Zones; las copias de seguridad protegen los datos, no mantienen el servicio en marcha, y la cercanía del edge reduce latencia pero no cubre un fallo. Si el requisito fuera recuperar datos tras una pérdida, la respuesta sería la copia de seguridad.",porQueOpcion:["Incorrecta: las copias de seguridad protegen los datos, pero no mantienen el servicio en marcha ante un fallo.","Correcta: la alta disponibilidad es seguir atendiendo el servicio pese al fallo de un componente gracias a la redundancia.","Incorrecta: responder desde el punto de presencia más cercano reduce latencia, pero no cubre el fallo de un componente.","Incorrecta: repartir costes entre cuentas describe la facturación consolidada, no la alta disponibilidad."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q5",taskId:"3.2",objetivos:["3.2#6"],tipo:"escenario",question:"Una aplicación crítica se ejecuta en una sola Availability Zone y el equipo afirma que tiene alta disponibilidad porque hace snapshots cada hora. Aunque el presupuesto es limitado y se busca reducir la factura mensual, el servicio debe seguir operando ante la caída de una zona. ¿Cuál es el problema y la solución correcta?",options:["No hay problema: los snapshots horarios garantizan la disponibilidad del servicio aunque la Availability Zone falle por completo.","El problema es la falta de redundancia entre Availability Zones; hay que desplegar réplicas en varias zonas.","El problema es que falta una edge location; hay que añadir una distribución de contenido para acelerar la entrega.","El problema es que sobra una Availability Zone; hay que consolidar todo en una sola para simplificar la operación."],correctAnswer:1,explanation:"Los snapshots permiten recuperar datos, pero no evitan una interrupción si cae la AZ. La alta disponibilidad exige redundancia activa en más de una Availability Zone, no una edge location ni consolidar la carga. Si el escenario pidiera solo proteger los datos ante un borrado accidental, los snapshots serían suficientes.",porQueOpcion:["Incorrecta: los snapshots horarios no garantizan la disponibilidad si falla por completo la Availability Zone.","Correcta: el problema es la falta de redundancia y la solución es desplegar réplicas en varias Availability Zones.","Incorrecta: añadir una edge location acelera la entrega, pero no evita la interrupción por el fallo de la AZ.","Incorrecta: consolidar todo en una sola Availability Zone agrava el punto único de fallo en lugar de resolverlo."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q6",taskId:"3.2",objetivos:["3.2#7"],tipo:"conocimiento",question:"¿Por qué el aislamiento entre Availability Zones ayuda a evitar un punto único de fallo?",options:["Porque todas las Availability Zones comparten la misma red, la misma refrigeración y el mismo sistema eléctrico dentro de la región.","Porque cada AZ tiene infraestructura independiente, de modo que el fallo de una no provoca el de las demás.","Porque las AZ se comunican a través de internet público y eso reparte la carga entre todas ellas.","Porque una AZ solo existe mientras hay tráfico en ella y se retira automáticamente cuando deja de usarse."],correctAnswer:1,explanation:"Cada Availability Zone tiene alimentación, refrigeración y red propias. Ese aislamiento evita que un fallo físico o de infraestructura se propague a las otras AZ de la región. Compartir esas dependencias sería precisamente el punto único de fallo, y las AZ no nacen ni se retiran según el tráfico. Si el requisito fuera lograr alta disponibilidad, la respuesta sería repartir réplicas entre varias Availability Zones.",porQueOpcion:["Incorrecta: compartir red, refrigeración y sistema eléctrico sería precisamente el punto único de fallo.","Correcta: cada Availability Zone tiene infraestructura independiente, de modo que el fallo de una no provoca el de las demás.","Incorrecta: las Availability Zones no se comunican por internet público para repartir la carga, y eso no explica su aislamiento.","Incorrecta: las Availability Zones existen de forma permanente y no se retiran cuando dejan de usarse."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q7",taskId:"3.2",objetivos:["3.2#3"],tipo:"conocimiento",question:"¿Para qué sirve principalmente el uso de varias regiones?",options:["Para tener más Availability Zones dentro de un mismo centro de datos y reducir así la latencia interna.","Para añadir distancia geográfica: recuperación ante desastres, continuidad, latencia y residencia de datos.","Para eliminar por completo la necesidad de copias de seguridad y de planes de recuperación ante desastres.","Para reducir automáticamente la factura al repartir el tráfico entre regiones más baratas sin ningún coste extra."],correctAnswer:1,explanation:"Varias regiones aportan separación geográfica real: DR, continuidad de negocio, menor latencia para usuarios lejanos y cumplimiento de residencia de datos. No sustituyen a las copias de seguridad, no reducen costes por sí solas y no añaden AZ dentro de un mismo centro de datos. Si el requisito fuera cumplir la residencia de datos, la decisión sería fijar la región adecuada.",porQueOpcion:["Incorrecta: varias regiones no añaden Availability Zones dentro de un mismo centro de datos ni reducen la latencia interna.","Correcta: varias regiones añaden distancia geográfica para recuperación ante desastres, continuidad, latencia y residencia de datos.","Incorrecta: la separación geográfica no elimina la necesidad de copias de seguridad ni de planes de recuperación.","Incorrecta: repartir tráfico entre regiones no reduce la factura automáticamente y añade costes de transferencia."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q8",taskId:"3.2",objetivos:["3.2#4"],tipo:"servicio",question:"Una web con usuarios repartidos por varios continentes descarga imágenes estáticas con lentitud. ¿Qué beneficio aporta servir el contenido desde edge locations?",options:["Elimina la necesidad de una región de AWS y traslada todos los datos de origen a la ubicación de borde.","Acerca el contenido al usuario y reduce la latencia de descarga.","Convierte las imágenes en datos cifrados en reposo dentro de la región donde reside el origen.","Aumenta la capacidad de cómputo de la base de datos al distribuir las peticiones entre ubicaciones."],correctAnswer:1,explanation:"Las edge locations acercan el contenido al usuario final, reduciendo la latencia de entrega. No sustituyen a la región, donde vive el origen de los datos, ni cambian el cifrado o el cómputo. Si el requisito fuera acercar los datos maestros en lugar del contenido estático, la respuesta cambiaría a elegir una región más cercana al usuario.",porQueOpcion:["Incorrecta: las edge locations no eliminan la región ni trasladan los datos de origen a la ubicación de borde.","Correcta: servir el contenido desde el edge acerca el contenido al usuario y reduce la latencia de descarga.","Incorrecta: el edge no convierte las imágenes en datos cifrados en reposo ni cambia la ubicación del origen.","Incorrecta: las edge locations no aumentan la capacidad de cómputo de la base de datos."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q9",taskId:"3.2",objetivos:["3.2#8"],tipo:"escenario",question:"Una empresa con clientes solo en Chile necesita que sus datos personales no salgan del país y, además, quiere poder recuperarse si su región principal sufre un incidente grave. ¿Qué decisión de diseño es correcta?",options:["Usar únicamente edge locations, porque están repartidas por todo el mundo y guardan los datos personales cerca del usuario.","Elegir una región en Chile para los datos y otra región distinta con replicación para la recuperación ante desastres.","Concentrar todo en una sola Availability Zone para simplificar la operación y cumplir la residencia de datos.","Confiar en los snapshots guardados en la misma región y no replicar, porque el país ya cumple la normativa."],correctAnswer:1,explanation:"La residencia de datos exige fijar la región en el país (o en el marco legal aplicable) y la continuidad exige una estrategia de recuperación independiente, típicamente una réplica en otra región. Una sola AZ o snapshots en la misma región no cubren una pérdida regional, y las edge locations no almacenan los datos maestros. Si el requisito fuera solo latencia para usuarios lejanos, bastaría el uso del edge sin cambiar la región del dato.",porQueOpcion:["Incorrecta: las edge locations no guardan los datos maestros ni cumplen por sí solas la residencia de datos.","Correcta: se fija una región en Chile para los datos y otra distinta con replicación para la recuperación ante desastres.","Incorrecta: una sola Availability Zone simplifica la operación, pero no cubre la pérdida regional y concentra el riesgo.","Incorrecta: los snapshots en la misma región no protegen ante la pérdida completa de esa región."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q10",taskId:"3.2",objetivos:["3.2#1"],tipo:"escenario",question:"Un equipo debe decidir dónde colocar cada componente de su arquitectura global. ¿Qué opción describe mejor el papel de cada capa de la infraestructura?",options:["La región aloja los datos y el cómputo, sus Availability Zones dan tolerancia a fallos y las edge locations acercan la entrega al usuario.","La edge location aloja la base de datos, la región reparte el contenido estático y las Availability Zones almacenan los datos maestros de toda la arquitectura.","Las Availability Zones son puntos de presencia internacionales y las edge locations son los centros de datos aislados de cada región.","Las tres capas son equivalentes y solo cambian de nombre según el servicio de entrega que se configure en cada momento."],correctAnswer:0,explanation:"La región y sus Availability Zones alojan los datos y el cómputo, con tolerancia a fallos entre zonas, y las edge locations acercan la entrega de contenido al usuario. Intercambiar los papeles del edge y de la región invierte la jerarquía real. Si el escenario pidiera solo acelerar la descarga de contenido estático, la pieza protagonista serían las edge locations.",porQueOpcion:["Correcta: la región aloja datos y cómputo, sus Availability Zones dan tolerancia a fallos y las edge locations acercan la entrega al usuario.","Incorrecta: la edge location no aloja la base de datos ni las Availability Zones almacenan los datos maestros de la arquitectura.","Incorrecta: las Availability Zones no son puntos de presencia internacionales ni las edge locations los centros de datos de cada región.","Incorrecta: las tres capas no son equivalentes, ya que cumplen papeles distintos en la infraestructura global."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q11",taskId:"3.2",objetivos:["3.2#2"],tipo:"escenario",question:"Una plataforma debe seguir operando aunque se pierda por completo el centro de datos donde corre. ¿Qué decisión de diseño cumple el objetivo?",options:["Añadir copias de seguridad automáticas cada hora y planificar una recuperación rápida desde esas copias guardadas fuera de la zona.","Desplegar la carga en varias Availability Zones de la región y distribuir el tráfico entre ellas.","Concentrar todos los recursos en una única Availability Zone para simplificar la administración de la plataforma.","Servir el contenido desde edge locations cercanas a los usuarios para mejorar la latencia de entrega."],correctAnswer:1,explanation:"La alta disponibilidad se logra con redundancia activa: réplicas en varias Availability Zones con infraestructura independiente y tráfico repartido entre ellas. Las copias de seguridad permiten recuperar datos, pero no evitan la interrupción; concentrar todo en una AZ y usar el edge no cubren el fallo del centro de datos. Si el requisito fuera recuperar datos tras una pérdida, la respuesta sería la copia de seguridad.",porQueOpcion:["Incorrecta: las copias de seguridad permiten recuperar datos, pero no evitan la interrupción al perderse el centro de datos.","Correcta: desplegar en varias Availability Zones y distribuir el tráfico mantiene la operación aunque se pierda un centro de datos.","Incorrecta: concentrar todo en una sola Availability Zone crea un punto único de fallo que tumba la plataforma.","Incorrecta: servir desde edge locations mejora la latencia, pero no cubre la caída del centro de datos."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q12",taskId:"3.2",objetivos:["3.2#3"],tipo:"casoDeUso",question:"Una empresa quiere abrir mercado en otro continente y ofrecer baja latencia a esos usuarios, manteniendo el control del dato. ¿Qué uso de la infraestructura global responde mejor?",options:["Desplegar una segunda copia de la carga en una región del nuevo continente, cerca de los usuarios.","Añadir más Availability Zones dentro de la región actual, aunque estén muy lejos de los nuevos usuarios, para atenderlos con menor latencia.","Servir todo desde la región original con una distribución de contenido delante del origen.","Duplicar todos los recursos en cada una de las edge locations disponibles del planeta."],correctAnswer:0,explanation:"Para atender a usuarios de otro continente con baja latencia y control del dato, se despliega una copia en una región cercana a esos usuarios. Añadir AZ en la región actual no acorta la distancia, el edge acelera contenido pero no sustituye al cómputo regional y duplicar en cada punto de presencia no es viable. Si el requisito fuera solo entregar imágenes estáticas más rápido, bastaría el edge.",porQueOpcion:["Correcta: desplegar una copia de la carga en una región del nuevo continente ofrece baja latencia cerca de los usuarios.","Incorrecta: añadir Availability Zones en la región actual no acorta la distancia a los nuevos usuarios.","Incorrecta: servir todo desde la región original mantiene la latencia alta para el nuevo continente.","Incorrecta: duplicar todos los recursos en cada edge location no es viable ni necesario."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q13",taskId:"3.2",objetivos:["3.2#4"],tipo:"escenario",question:"Un sitio de noticias con audiencia en tres continentes quiere acelerar la carga de sus portadas sin mover los datos de origen. ¿Qué uso de la infraestructura global encaja mejor?",options:["Replicar la base de datos en tres regiones y servir cada portada desde la base más cercana al lector de cada continente.","Entregar el contenido desde ubicaciones de borde cercanas al usuario, manteniendo el origen en su región.","Mover todos los datos de origen a una edge location para reducir la distancia hasta el lector.","Aumentar el tamaño de las instancias de origen para responder más rápido a los tres continentes."],correctAnswer:1,explanation:"Las ubicaciones de borde acercan la entrega del contenido al usuario y reducen la latencia sin mover el origen, que sigue en su región. Las edge locations no alojan la base de datos maestra, y ampliar las instancias de origen no acorta la distancia al lector. Si el requisito fuera que los datos de origen también vivieran cerca de cada audiencia, la decisión pasaría por varias regiones.",porQueOpcion:["Incorrecta: replicar la base de datos no es necesario si solo se quiere acelerar la carga de portadas sin mover el origen.","Correcta: entregar desde ubicaciones de borde cercanas reduce la latencia manteniendo el origen en su región.","Incorrecta: los datos de origen no se mueven a una edge location, que no está pensada para alojarlos.","Incorrecta: ampliar las instancias de origen no acorta la distancia hasta el lector de cada continente."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q14",taskId:"3.2",objetivos:["3.2#6"],tipo:"conocimiento",question:"¿Cuál es la forma correcta de conseguir que una aplicación resista el fallo de un centro de datos?",options:["Desplegar réplicas de la aplicación en varias Availability Zones de la misma región y distribuir el tráfico entre ellas.","Contratar instancias más grandes en una sola Availability Zone y confiar en su mayor capacidad de reserva ante cualquier incidencia.","Programar copias de seguridad más frecuentes para recuperar el servicio lo antes posible tras el fallo.","Usar varias edge locations para que el contenido siga disponible aunque caiga el centro de datos."],correctAnswer:0,explanation:"Repartir réplicas entre Availability Zones aisladas y distribuir el tráfico es lo que permite seguir operando si cae un centro de datos. Una sola AZ, aunque tenga instancias mayores, sigue siendo un punto único de fallo; las copias de seguridad recuperan datos y el edge sirve contenido, pero ninguno mantiene la aplicación en marcha. Si el escenario exigiera sobrevivir a la caída de una región completa, la respuesta pasaría a ser varias regiones.",porQueOpcion:["Correcta: replicar la aplicación en varias Availability Zones y distribuir el tráfico permite resistir el fallo de un centro de datos.","Incorrecta: una sola Availability Zone con instancias mayores sigue siendo un punto único de fallo.","Incorrecta: programar más copias de seguridad recupera datos, pero no mantiene el servicio en marcha.","Incorrecta: las edge locations sirven contenido y no evitan que caiga la aplicación con el centro de datos."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q15",taskId:"3.2",objetivos:["3.2#7"],tipo:"escenario",question:"Un proveedor debe responder a un auditor: «¿por qué una caída física en un centro de datos no tumba todo el servicio?». ¿Qué argumento es correcto?",options:["Porque cada Availability Zone tiene alimentación, refrigeración y red independientes, así que el fallo no se propaga a las demás.","Porque todas las Availability Zones comparten el mismo sistema eléctrico y reparten la carga entre sus servidores para amortiguar el fallo.","Porque el proveedor de nube reubica de forma automática los recursos de la zona caída a otra zona sana.","Porque las Availability Zones se comunican por internet público y redirigen el tráfico sin intervención del cliente."],correctAnswer:0,explanation:"El aislamiento físico de cada Availability Zone —alimentación, refrigeración y red propias— es lo que impide que un fallo localizado se propague. Compartir esas dependencias sería el punto único de fallo, y la conmutación entre zonas es responsabilidad del diseño del cliente, no una reubicación automática. Si el requisito fuera una conmutación automática entre zonas, habría que diseñarla en el cliente, porque AWS no reubica recursos por sí solo.",porQueOpcion:["Correcta: cada Availability Zone tiene alimentación, refrigeración y red independientes, así que el fallo no se propaga a las demás.","Incorrecta: compartir el mismo sistema eléctrico sería el punto único de fallo que se quiere evitar.","Incorrecta: AWS no reubica automáticamente los recursos; la conmutación entre zonas la diseña el cliente.","Incorrecta: las Availability Zones no se comunican por internet público y la redirección del tráfico no es automática."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]},{id:"3.2-q16",taskId:"3.2",objetivos:["3.2#8"],tipo:"tradeoff",question:"¿Qué trade-off implica replicar una aplicación en varias regiones para lograr continuidad de negocio?",options:["Se gana independencia frente al fallo de una región completa, pero aumentan la complejidad operativa y los costes de replicación y transferencia.","Se gana simplicidad operativa, porque las regiones comparten la misma red, los mismos datos y las mismas Availability Zones sin replicación ni coste de transferencia alguno.","No hay contrapartida: replicar en varias regiones siempre reduce la factura al repartir el tráfico.","Se pierde la posibilidad de usar varias Availability Zones dentro de cada región replicada."],correctAnswer:0,explanation:"Replicar en varias regiones aporta continuidad frente al fallo regional, pero añade complejidad operativa y costes de replicación y transferencia de datos. Las regiones no comparten red ni datos, replicar no reduce la factura por sí solo y cada región conserva sus propias Availability Zones. Si el requisito fuera solo resistir el fallo de un centro de datos, bastaría con varias Availability Zones y no haría falta replicar entre regiones.",porQueOpcion:["Correcta: replicar entre regiones gana independencia frente al fallo regional a cambio de más complejidad operativa y costes.","Incorrecta: las regiones no comparten red, datos ni Availability Zones, y la replicación añade coste de transferencia.","Incorrecta: replicar en varias regiones no reduce la factura por sí solo; añade costes.","Incorrecta: cada región conserva sus propias Availability Zones, por lo que no se pierde la posibilidad de usarlas."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/aws-overview/global-infrastructure.html"]}],3.3:[{id:"3.3-q1",taskId:"3.3",objetivos:["3.3#1"],tipo:"conocimiento",question:"¿Qué afirmación describe correctamente la diferencia general entre los modelos de cómputo de AWS?",options:["Una máquina virtual no permite instalar software propio ni elegir el sistema operativo por el cliente, a diferencia de una función serverless, que sí lo permite.","En el cómputo serverless no se aprovisionan ni administran servidores, mientras que con máquinas virtuales sí se gestiona el sistema operativo.","Los contenedores solo pueden ejecutarse en instancias que el cliente administra y nunca en un motor serverless.","El cómputo serverless obliga a pagar por capacidad reservada aunque no haya tráfico ni eventos que procesar."],correctAnswer:1,explanation:"El espectro va del control total de la máquina virtual, que incluye gestionar el sistema operativo, al cómputo serverless, donde no se aprovisionan ni administran servidores. Las máquinas virtuales sí permiten instalar software, los contenedores pueden correr en un motor serverless y el cómputo serverless no exige capacidad reservada. Si el requisito fuera controlar el sistema operativo, la respuesta se inclinaría por las máquinas virtuales; si cambiara a ejecución solo ante eventos, por el cómputo serverless.",porQueOpcion:["Incorrecta: la máquina virtual sí permite instalar software propio y elegir el sistema operativo.","Correcta: en serverless no se aprovisionan ni administran servidores, mientras que con máquinas virtuales se gestiona el sistema operativo.","Incorrecta: los contenedores sí pueden ejecutarse en un motor serverless.","Incorrecta: el cómputo serverless no exige capacidad reservada y se cobra por uso."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"3.3-q2",taskId:"3.3",objetivos:["3.3#2"],tipo:"conocimiento",question:"Una carga se caracteriza por un volumen muy alto de operaciones de lectura y escritura sobre discos locales. ¿Qué familia de instancias encaja mejor?",options:["Memory optimized, porque prioriza la memoria RAM y mantiene en ella el conjunto de datos activo de la carga.","Compute optimized, porque prioriza la CPU y ofrece la mejor relación de cálculo por núcleo.","Storage optimized, porque prioriza la entrada/salida y el almacenamiento local.","General purpose, porque equilibra todos los recursos y sirve como punto de partida habitual."],correctAnswer:2,explanation:"Las familias storage optimized están diseñadas para cargas con muchas operaciones de disco y requisitos altos de almacenamiento local. Compute optimized prioriza la CPU, memory optimized la memoria y general purpose es el equilibrio, no el tipo especializado para entrada/salida. Si cambiara el cuello de botella a la CPU, la familia adecuada pasaría a ser compute optimized.",porQueOpcion:["Incorrecta: memory optimized prioriza la memoria RAM, no la entrada/salida sobre discos locales.","Incorrecta: compute optimized prioriza la CPU, no el rendimiento de los discos locales.","Correcta: storage optimized está diseñada para cargas con muchas operaciones de entrada/salida y almacenamiento local.","Incorrecta: general purpose equilibra recursos, pero no es la familia especializada para alto rendimiento de disco."],fuentes:["https://docs.aws.amazon.com/ram/latest/userguide/what-is.html"]},{id:"3.3-q3",taskId:"3.3",objetivos:["3.3#2"],tipo:"casoDeUso",question:"Un equipo ejecuta un trabajo de procesamiento por lotes que satura la CPU de forma constante y no necesita mucha memoria ni disco. ¿Qué elección es la más razonable?",options:["Instancias de la familia compute optimized.","Instancias de la familia storage optimized.","Instancias de la familia memory optimized.","Instancias de la familia accelerated computing."],correctAnswer:0,explanation:"Cuando el recurso limitante es la CPU, la familia compute optimized ofrece la mejor relación entre capacidad de cálculo y coste. Storage optimized y memory optimized optimizan recursos que esta carga no necesita, y accelerated computing solo se justifica si el trabajo aprovecha un acelerador. Si el requisito cambiara a un conjunto de datos que vive en memoria, la familia sería memory optimized.",porQueOpcion:["Correcta: la familia compute optimized ofrece la mejor relación de cálculo por coste cuando el recurso limitante es la CPU.","Incorrecta: storage optimized optimiza la entrada/salida, que esta carga no necesita.","Incorrecta: memory optimized optimiza la memoria, que esta carga no necesita.","Incorrecta: accelerated computing solo se justifica si el trabajo aprovecha un acelerador."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"3.3-q4",taskId:"3.3",objetivos:["3.3#3"],tipo:"comparacion",question:"Un equipo debe decidir cómo ejecutar sus contenedores. ¿Qué afirmación distingue correctamente un orquestador propietario, Kubernetes gestionado y un motor de cómputo serverless?",options:["Amazon ECS y Amazon EKS son motores serverless que ejecutan contenedores, y AWS Fargate es un orquestador de Kubernetes que organiza esos contenedores.","Amazon ECS y Amazon EKS son orquestadores de contenedores, mientras que AWS Fargate es un motor de cómputo que los ejecuta sin administrar servidores.","Los tres son orquestadores equivalentes y solo cambian de nombre según la región donde se despliegan los contenedores.","AWS Fargate sustituye a Amazon ECS y a Amazon EKS, por lo que no se pueden combinar entre ellos en la misma cuenta."],correctAnswer:1,explanation:"Amazon ECS es el orquestador propio de AWS y Amazon EKS es Kubernetes gestionado; ambos organizan los contenedores. AWS Fargate es el motor serverless que ejecuta las tareas y se combina con cualquiera de los dos. No son alternativas entre sí: presentarlos como motores o como sustitutos invierte sus papeles. Si el requisito fuera ejecutar en nodos que el equipo administra, la alternativa a Fargate serían instancias de Amazon EC2.",porQueOpcion:["Incorrecta: Amazon ECS y Amazon EKS son orquestadores, no motores serverless, y AWS Fargate no es un orquestador de Kubernetes.","Correcta: Amazon ECS y Amazon EKS son orquestadores de contenedores y AWS Fargate es el motor serverless que los ejecuta sin administrar servidores.","Incorrecta: no son tres orquestadores equivalentes; AWS Fargate es un motor de cómputo.","Incorrecta: AWS Fargate no sustituye a ECS ni a EKS, sino que se combina con cualquiera de ellos."],fuentes:["https://docs.aws.amazon.com/ecs/","https://docs.aws.amazon.com/eks/","https://docs.aws.amazon.com/AmazonECS/latest/developerguide/AWS_Fargate.html","https://docs.aws.amazon.com/ec2/"]},{id:"3.3-q5",taskId:"3.3",objetivos:["3.3#3"],tipo:"escenario",question:"Una startup despliega microservicios en contenedores. Su equipo no tiene experiencia en Kubernetes, valora la simplicidad y no quiere administrar servidores. ¿Qué combinación encaja mejor?",options:["Amazon ECS con AWS Fargate como motor de cómputo.","Amazon EKS con nodos que el equipo administra a mano.","Instancias de Amazon EC2 sin orquestador, ejecutando los contenedores manualmente.","Amazon Elastic Container Registry (Amazon ECR), porque almacena las imágenes de contenedor y las ejecuta sin administrar servidores."],correctAnswer:0,explanation:"Si no se necesita Kubernetes y se busca simplicidad, Amazon ECS es el orquestador adecuado; como no se quieren administrar servidores, se ejecuta con el motor serverless AWS Fargate. Amazon EKS tendría sentido con experiencia previa en Kubernetes, gestionar instancias a mano añade trabajo innecesario y Amazon ECR solo almacena las imágenes, no ejecuta la carga. Si cambiara el requisito a portabilidad de Kubernetes, la elección sería Amazon EKS.",porQueOpcion:["Correcta: Amazon ECS es el orquestador simple y AWS Fargate el motor serverless, sin administrar servidores ni exigir Kubernetes.","Incorrecta: Amazon EKS con nodos administrados a mano añade la complejidad y la administración que la startup quiere evitar.","Incorrecta: ejecutar contenedores manualmente en Amazon EC2 obliga a administrar servidores y prescinde del orquestador.","Incorrecta: Amazon ECR almacena y versiona las imágenes de contenedor, pero no es un motor de cómputo ni ejecuta la aplicación."],fuentes:["https://docs.aws.amazon.com/ecs/","https://docs.aws.amazon.com/AmazonECS/latest/developerguide/AWS_Fargate.html","https://docs.aws.amazon.com/eks/","https://docs.aws.amazon.com/ec2/","https://docs.aws.amazon.com/ecr/"]},{id:"3.3-q6",taskId:"3.3",objetivos:["3.3#4"],tipo:"comparacion",question:"¿Qué diferencia fundamental separa a un servidor virtual que administra el cliente de una función serverless por evento?",options:["Amazon EC2 cobra solo por invocación y AWS Lambda cobra por hora de instancia encendida, aunque no reciba tráfico ni eventos.","Amazon EC2 entrega servidores que el cliente administra; AWS Lambda ejecuta funciones por evento sin gestionar servidores.","AWS Lambda permite instalar el sistema operativo que se quiera y Amazon EC2 no permite elegirlo ni configurarlo.","Ambos son idénticos, salvo que AWS Lambda está limitado a un único usuario y no admite escalado."],correctAnswer:1,explanation:"Amazon EC2 proporciona instancias que el cliente configura y administra, con capacidad disponible de forma continua. AWS Lambda ejecuta funciones disparadas por eventos, sin servidores que gestionar y con pago por uso. Invertir los modelos de cobro, el control del sistema operativo o el escalado describe justo lo contrario. Si el requisito cambiara a un proceso continuo y con estado, la respuesta se inclinaría por Amazon EC2.",porQueOpcion:["Incorrecta: invierte los modelos de cobro, ya que Amazon EC2 cobra por capacidad y AWS Lambda por invocación.","Correcta: Amazon EC2 entrega servidores que el cliente administra y AWS Lambda ejecuta funciones por evento sin gestionar servidores.","Incorrecta: AWS Lambda no permite instalar el sistema operativo y Amazon EC2 sí permite elegirlo y configurarlo.","Incorrecta: Amazon EC2 y AWS Lambda no son idénticos; no están limitados a un único usuario y Lambda escala automáticamente."],fuentes:["https://docs.aws.amazon.com/ec2/","https://docs.aws.amazon.com/lambda/latest/dg/welcome.html"]},{id:"3.3-q7",taskId:"3.3",objetivos:["3.3#4"],tipo:"escenario",question:"Una empresa recibe archivos de forma imprevisible y debe ejecutar un proceso corto por cada uno. No quiere mantener servidores encendidos entre archivos. ¿Qué opción es la más adecuada?",options:["Un servidor de Amazon EC2 siempre encendido que comprueba si hay archivos.","Una función de AWS Lambda que se active con cada archivo nuevo.","Una base de datos relacional que procese los archivos dentro de la misma consulta.","Un balanceador de carga que transforme los archivos en el momento de la subida."],correctAnswer:1,explanation:"El patrón es orientado a eventos y de ejecución corta, justo el caso de AWS Lambda: se activa cuando llega cada archivo, escala con los eventos y no cuesta cuando no hay ninguno. Un servidor encendido de forma permanente desperdicia capacidad entre archivos, y ni la base de datos ni el balanceador transforman archivos. Si cambiara el requisito a un proceso largo con estado, la opción sería un servidor virtual.",porQueOpcion:["Incorrecta: un servidor de Amazon EC2 siempre encendido desperdicia capacidad entre archivos y no encaja con la llegada imprevisible.","Correcta: una función de AWS Lambda se activa con cada archivo, escala con los eventos y no cuesta cuando no hay ninguno.","Incorrecta: una base de datos relacional no procesa archivos dentro de la misma consulta.","Incorrecta: un balanceador de carga reparte tráfico y no transforma archivos en el momento de la subida."],fuentes:["https://docs.aws.amazon.com/ec2/","https://docs.aws.amazon.com/lambda/latest/dg/welcome.html"]},{id:"3.3-q8",taskId:"3.3",objetivos:["3.3#5"],tipo:"conocimiento",question:"¿Qué aporta AWS Auto Scaling a un sistema que debe atender demanda variable?",options:["Cifra los datos en reposo de forma automática y rota las claves de cifrado según una programación definida por el equipo.","Ajusta el número de recursos a la demanda, añadiendo capacidad en los picos y retirándola en los valles.","Reemplaza la necesidad de un balanceador de carga al repartir el tráfico entre los recursos disponibles.","Garantiza que el precio por hora de cada instancia sea siempre el más bajo posible del mercado."],correctAnswer:1,explanation:"AWS Auto Scaling aporta elasticidad: ajusta automáticamente la cantidad de recursos según la demanda. No cifra datos, no sustituye al balanceador de carga ni cambia por sí solo el modelo de precios. Si el requisito fuera repartir el tráfico entre los destinos activos, la pieza sería un balanceador de carga.",porQueOpcion:["Incorrecta: el cifrado y la rotación de claves no son funciones de AWS Auto Scaling.","Correcta: AWS Auto Scaling ajusta el número de recursos a la demanda, añadiendo capacidad en los picos y retirándola en los valles.","Incorrecta: Auto Scaling no sustituye al balanceador de carga, que sigue repartiendo el tráfico.","Incorrecta: Auto Scaling no garantiza el precio por hora más bajo del mercado."],fuentes:["https://docs.aws.amazon.com/autoscaling/"]},{id:"3.3-q9",taskId:"3.3",objetivos:["3.3#6"],tipo:"servicio",question:"¿Cuál es el propósito principal de un balanceador de carga?",options:["Ejecutar el código de la aplicación en lugar de los servidores.","Repartir el tráfico entrante entre varios destinos y comprobar su estado.","Almacenar de forma permanente los archivos estáticos de la aplicación.","Sustituir a auto scaling cuando no hay tráfico."],correctAnswer:1,explanation:"Un balanceador de carga distribuye las peticiones entre varios destinos y verifica su salud para dejar de enviar tráfico a los que fallan. Mejora la disponibilidad y la distribución de la carga, y se complementa con auto scaling, que decide cuántos destinos existen. Si el requisito fuera decidir cuántas instancias debe haber según la demanda, la pieza sería auto scaling.",porQueOpcion:["Incorrecta: el balanceador no ejecuta el código de la aplicación, sino que reparte el tráfico.","Correcta: un balanceador de carga reparte el tráfico entrante entre varios destinos y comprueba su estado.","Incorrecta: un balanceador de carga no almacena de forma permanente los archivos estáticos.","Incorrecta: el balanceador se complementa con auto scaling, no lo sustituye cuando no hay tráfico."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"3.3-q10",taskId:"3.3",objetivos:["3.3#4"],tipo:"tradeoff",question:"Un equipo sopesa ejecutar un proceso en funciones serverless frente a instancias de servidor virtual. ¿Qué criterio inclina la decisión hacia las funciones?",options:["Que el proceso sea continuo, de larga duración y necesite control del sistema operativo.","Que la carga llegue por eventos, sea de ejecución corta y no requiera estado entre invocaciones.","Que el proceso necesite conservar datos en memoria entre ejecuciones.","Que se quiera pagar por capacidad reservada durante todo el año."],correctAnswer:1,explanation:"Las funciones serverless brillan con cargas orientadas a eventos, cortas y sin estado, porque solo se ejecutan y se cobran cuando hay eventos. Los procesos continuos, largos o con estado encajan mejor en un servidor virtual, donde existe una máquina disponible de forma permanente. Si el requisito cambiara a conservar estado entre ejecuciones, la decisión pasaría a instancias de servidor virtual.",porQueOpcion:["Incorrecta: un proceso continuo y de larga duración con control del sistema operativo encaja mejor en un servidor virtual.","Correcta: las cargas que llegan por eventos, son cortas y no requieren estado son el caso ideal de las funciones serverless.","Incorrecta: conservar datos en memoria entre ejecuciones encaja mejor en un servidor virtual con estado.","Incorrecta: pagar capacidad reservada todo el año es lo opuesto al pago por uso de serverless."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"3.3-q11",taskId:"3.3",objetivos:["3.3#1"],tipo:"comparacion",question:"Un equipo compara ejecutar su carga en máquinas virtuales o en cómputo serverless. ¿Qué afirmación distingue correctamente ambos modelos?",options:["En las máquinas virtuales el cliente administra el sistema operativo y la capacidad está disponible; en serverless no se gestionan servidores y se paga por uso.","En serverless el cliente administra el sistema operativo de cada servidor y paga por adelantado la capacidad reservada que necesitará durante todo el año, sin depender del consumo real.","En las máquinas virtuales no se puede instalar software y en serverless solo se ejecutan contenedores ya empaquetados.","Ambos modelos ofrecen el mismo control y el mismo modelo de pago, y solo cambia el nombre comercial."],correctAnswer:0,explanation:"En las máquinas virtuales el cliente controla el sistema operativo y la capacidad permanece disponible; en serverless no se gestionan servidores y se paga por uso. Invertir el control o el pago, o tratarlos como equivalentes, niega la diferencia central del espectro de cómputo. Si el requisito fuera instalar software específico en el sistema operativo, la respuesta serían las máquinas virtuales.",porQueOpcion:["Correcta: en las máquinas virtuales el cliente administra el sistema operativo y en serverless no se gestionan servidores y se paga por uso.","Incorrecta: invierte el modelo, ya que en serverless no se administra el sistema operativo y se paga por uso, no por capacidad reservada.","Incorrecta: en las máquinas virtuales sí se puede instalar software y serverless no se limita a contenedores empaquetados.","Incorrecta: ambos modelos difieren en control y modelo de pago, no solo en el nombre comercial."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"3.3-q12",taskId:"3.3",objetivos:["3.3#2"],tipo:"comparacion",question:"Una carga tiene cuellos de botella distintos según el componente. ¿Qué afirmación distingue correctamente las familias de instancias?",options:["Compute optimized prioriza la CPU, memory optimized la memoria RAM y storage optimized la entrada/salida y el almacenamiento local.","Compute optimized prioriza la memoria RAM, memory optimized el almacenamiento local y storage optimized la capacidad de CPU de cada instancia contratada.","Las tres familias son equivalentes y solo se diferencian en el tamaño de la instancia y en la región elegida.","Accelerated computing es la opción por defecto para cualquier carga porque siempre ofrece más rendimiento."],correctAnswer:0,explanation:"Cada familia responde a un cuello de botella: compute optimized a la CPU, memory optimized a la RAM y storage optimized a la entrada/salida y el almacenamiento local. Intercambiar las especializaciones lleva a elegir la familia equivocada, y ninguna familia es la opción por defecto para todo. Si el requisito cambiara a entrenamiento de aprendizaje automático, la familia adecuada sería accelerated computing.",porQueOpcion:["Correcta: compute optimized prioriza la CPU, memory optimized la RAM y storage optimized la entrada/salida y el almacenamiento local.","Incorrecta: intercambia las especializaciones de las tres familias.","Incorrecta: las tres familias no son equivalentes; cada una responde a un cuello de botella distinto.","Incorrecta: accelerated computing no es la opción por defecto y solo se justifica con aceleradores."],fuentes:["https://docs.aws.amazon.com/ram/latest/userguide/what-is.html"]},{id:"3.3-q13",taskId:"3.3",objetivos:["3.3#1"],tipo:"escenario",question:"Una empresa debe elegir un modelo de cómputo para tres cargas: una API web con picos, un proceso nocturno de larga duración y un servicio de contenedores ya empaquetado. ¿Qué asignación es más razonable?",options:["Serverless por función para la API, servidor virtual para el proceso largo y motor serverless de contenedores para el servicio empaquetado.","Servidor virtual para las tres cargas, porque es el modelo con más control, admite cualquier proceso y permite instalar todo el software necesario.","Serverless por función para las tres cargas, porque elimina los servidores en todos los casos.","Motor serverless de contenedores para las tres cargas, porque acepta funciones y procesos largos indistintamente."],correctAnswer:0,explanation:"Cada carga encaja con un modelo distinto: la API con picos en funciones serverless, el proceso largo en un servidor virtual y el contenedor ya empaquetado en un motor serverless de contenedores. Forzar un único modelo para todo desaprovecha las ventajas de cada uno. Si el escenario pidiera ejecutar todo el código como funciones, habría que descartar el proceso largo, que no encaja en ese modelo.",porQueOpcion:["Correcta: asigna serverless a la API con picos, servidor virtual al proceso largo y motor serverless de contenedores al servicio empaquetado.","Incorrecta: usar servidor virtual para las tres cargas desaprovecha las ventajas de serverless y de los contenedores gestionados.","Incorrecta: serverless por función no encaja con el proceso nocturno de larga duración ni con el contenedor empaquetado.","Incorrecta: el motor serverless de contenedores no acepta funciones ni procesos largos indistintamente."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"3.3-q14",taskId:"3.3",objetivos:["3.3#5"],tipo:"escenario",question:"Una tienda en línea ve multiplicarse el tráfico en las rebajas y caer después al nivel habitual. Sin embargo, el equipo quiere mantener el presupuesto anual bajo control. ¿Cómo debe responder la arquitectura para ser elástica y eficiente en coste?",options:["Dimensionar la capacidad para el pico de rebajas y mantenerla contratada durante todo el año, aunque quede infrautilizada.","Ajustar automáticamente el número de recursos a la demanda, añadiendo capacidad en el pico y retirándola en el valle.","Mantener una capacidad fija pequeña y rechazar el tráfico excedente durante las horas de mayor demanda.","Replicar los recursos en varias regiones para repartir la carga entre todas ellas en cualquier momento."],correctAnswer:1,explanation:"La elasticidad ajusta el número de recursos a la demanda: crece en el pico y se retira en el valle, pagando solo por lo usado. Dimensionar para el pico deja capacidad ociosa el resto del año y limitar la capacidad rechaza clientes. Si el objetivo cambiara a resistir el fallo de una región, la decisión sería replicar entre regiones, no solo escalar.",porQueOpcion:["Incorrecta: dimensionar para el pico deja capacidad ociosa e infrautilizada durante todo el año.","Correcta: ajustar automáticamente el número de recursos a la demanda añade capacidad en el pico y la retira en el valle.","Incorrecta: mantener capacidad fija y rechazar el tráfico excedente pierde clientes en las horas de mayor demanda.","Incorrecta: replicar en varias regiones reparte la carga, pero no ajusta la capacidad a la demanda ni reduce el coste ocioso."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"3.3-q15",taskId:"3.3",objetivos:["3.3#6"],tipo:"casoDeUso",question:"Un equipo despliega varias instancias detrás de un componente que reparte el tráfico y comprueba su estado. ¿Qué aporta ese componente a la arquitectura?",options:["Distribuye las peticiones, mejora la disponibilidad y deja de enviar tráfico a los destinos que fallan.","Amazon API Gateway, porque publica la API, la protege con límites de uso y reparte las peticiones entre los destinos según su estado.","Almacena de forma permanente los archivos estáticos que sirve a los usuarios.","Decide cuántos destinos deben existir y crea o elimina instancias según la demanda."],correctAnswer:0,explanation:"El balanceador de carga reparte las peticiones entre varios destinos y retira de la rotación los que no responden, mejorando la disponibilidad. No publica ni gestiona APIs, como hace Amazon API Gateway, no almacena archivos de forma permanente y no decide cuántos destinos existen, tarea de auto scaling. Si el requisito fuera ajustar cuántas instancias hay según la demanda, la pieza responsable sería auto scaling.",porQueOpcion:["Correcta: el balanceador distribuye las peticiones, mejora la disponibilidad y deja de enviar tráfico a los destinos que fallan.","Incorrecta: Amazon API Gateway publica y gestiona APIs, pero no reparte el tráfico entre destinos ni comprueba su estado, función del balanceador.","Incorrecta: el balanceador no almacena de forma permanente los archivos estáticos.","Incorrecta: decidir cuántos destinos existen y crearlos o eliminarlos es tarea de auto scaling, no del balanceador."],fuentes:["https://docs.aws.amazon.com/apigateway/latest/developerguide/welcome.html"]}],3.4:[{id:"3.4-q1",taskId:"3.4",objetivos:["3.4#1"],tipo:"conocimiento",question:"¿Qué afirmación describe correctamente las categorías de servicios de base de datos de AWS?",options:["Todas las bases de datos de AWS son relacionales, se consultan con SQL y la única diferencia apreciable es el tamaño de la instancia contratada y la región donde se despliegan los recursos.","AWS ofrece bases relacionales (por ejemplo, Amazon RDS y Amazon Aurora), NoSQL (por ejemplo, Amazon DynamoDB) y en memoria (por ejemplo, Amazon ElastiCache).","Las bases NoSQL solo existen fuera de AWS, por eso se alojan en Amazon EC2 y no tienen servicio gestionado.","La categoría de la base de datos depende del sistema operativo de la instancia donde se ejecuta el motor."],correctAnswer:1,explanation:"AWS agrupa sus bases de datos por modelo de dato: relacionales gestionadas (Amazon RDS, Amazon Aurora), NoSQL (Amazon DynamoDB, Amazon DocumentDB, Amazon Neptune) y en memoria para caché (Amazon ElastiCache), además de almacenes analíticos como Amazon Redshift. No todas son relacionales y la categoría no depende del sistema operativo. Si el requisito cambiara a acceso por clave con escala impredecible, la categoría adecuada sería NoSQL.",porQueOpcion:["Incorrecta: no todas las bases de AWS son relacionales ni la categoría depende del tamaño de la instancia.","Correcta: AWS ofrece bases relacionales (Amazon RDS y Amazon Aurora), NoSQL (Amazon DynamoDB) y en memoria (Amazon ElastiCache).","Incorrecta: las bases NoSQL sí tienen servicio gestionado en AWS, como Amazon DynamoDB.","Incorrecta: la categoría depende del modelo de dato, no del sistema operativo de la instancia."],fuentes:["https://docs.aws.amazon.com/rds/","https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/CHAP_AuroraOverview.html","https://docs.aws.amazon.com/dynamodb/","https://docs.aws.amazon.com/elasticache/","https://docs.aws.amazon.com/ec2/","https://docs.aws.amazon.com/documentdb/","https://docs.aws.amazon.com/neptune/","https://docs.aws.amazon.com/redshift/"]},{id:"3.4-q2",taskId:"3.4",objetivos:["3.4#3"],tipo:"escenario",question:"Un equipo quiere decidir entre instalar su propia base de datos en Amazon EC2 o usar un servicio gestionado. ¿Qué criterio refleja la decisión correcta?",options:["Usar Amazon EC2 solo cuando se necesite menos control del sistema operativo y menos administración de la habitual, ya que la instancia aplica parches y copias automáticamente sin intervención del equipo.","Elegir una base gestionada para delegar en AWS parches, copias de seguridad y alta disponibilidad; usar Amazon EC2 cuando se necesite control total del motor y del sistema operativo.","Elegir Amazon EC2 siempre, porque resulta más barato que cualquier base gestionada cuando se suman todos los costes de operación.","Elegir una base gestionada porque impide escalar y así se controla el coste, aunque no permita copias de seguridad."],correctAnswer:1,explanation:"La base gestionada quita del equipo la operación de la infraestructura (parches, copias, alta disponibilidad, escalado). Amazon EC2 tiene sentido cuando se necesita control del sistema operativo o del motor, asumiendo esa operación por cuenta propia; no aplica parches automáticos ni es siempre más barato. Si el requisito fuera un motor no soportado por el servicio gestionado, la respuesta sería Amazon EC2.",porQueOpcion:["Incorrecta: una instancia de Amazon EC2 no aplica parches ni copias automáticamente, y a mayor control corresponde más administración.","Correcta: la base gestionada delega parches, copias y alta disponibilidad, y Amazon EC2 se usa cuando se necesita control total del motor.","Incorrecta: Amazon EC2 no es siempre más barato al sumar los costes de operación que asume el equipo.","Incorrecta: una base gestionada sí permite escalar y hacer copias de seguridad; impedirlos no es su propósito."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"3.4-q3",taskId:"3.4",objetivos:["3.4#3"],tipo:"tradeoff",question:"¿Qué contrapartida implica alojar la base de datos en Amazon EC2 en lugar de usar una base gestionada de AWS?",options:["Se gana control sobre el motor y el sistema operativo, pero el equipo asume parches, copias de seguridad, escalado y alta disponibilidad.","Se gana administración automática de parches y copias, pero se pierde el acceso al motor y a toda su configuración avanzada de parámetros.","No hay contrapartida: Amazon EC2 ofrece la misma automatización de parches y copias que una base gestionada.","Se reduce el coste a cero porque Amazon EC2 no cobra por cómputo ni por almacenamiento."],correctAnswer:0,explanation:"El control total es el beneficio de Amazon EC2 y su coste es operativo: el equipo pasa a ser responsable de la administración que en un servicio gestionado realiza AWS. Alojar en Amazon EC2 no aporta administración automática, no elimina el coste y no es una base gestionada. Si el requisito fuera minimizar la administración, la respuesta sería una base gestionada.",porQueOpcion:["Correcta: en Amazon EC2 se gana control del motor y del sistema operativo, pero el equipo asume parches, copias, escalado y alta disponibilidad.","Incorrecta: invierte la contrapartida, ya que Amazon EC2 no aporta administración automática y no se pierde acceso al motor.","Incorrecta: Amazon EC2 no ofrece la misma automatización de parches y copias que una base gestionada, por eso hay contrapartida.","Incorrecta: Amazon EC2 sí cobra por cómputo y almacenamiento, por lo que no reduce el coste a cero."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"3.4-q4",taskId:"3.4",objetivos:["3.4#4"],tipo:"conocimiento",question:"Una empresa necesita una base de datos gestionada compatible con MySQL y PostgreSQL, con alta disponibilidad y sin administrar el motor. ¿Qué servicio encaja mejor?",options:["Amazon DynamoDB, porque guarda documentos con clave-valor y escala horizontalmente.","Amazon ElastiCache, porque mantiene los datos en memoria para lecturas rápidas.","Amazon Aurora, porque es un motor relacional gestionado compatible con MySQL y PostgreSQL.","Amazon Neptune, porque organiza los datos como un grafo de relaciones."],correctAnswer:2,explanation:"Amazon Aurora es un motor relacional gestionado y compatible con MySQL y PostgreSQL, que es lo que pide el requisito. DynamoDB y Neptune son NoSQL (clave-valor/documento y grafo) y ElastiCache es una caché en memoria. Si el requisito pidiera latencia de un dígito de milisegundos a escala masiva y no relaciones, la respuesta sería DynamoDB.",porQueOpcion:["Incorrecta: Amazon DynamoDB es NoSQL clave-valor y no es compatible con MySQL ni PostgreSQL.","Incorrecta: Amazon ElastiCache es una caché en memoria, no una base relacional compatible con MySQL y PostgreSQL.","Correcta: Amazon Aurora es un motor relacional gestionado y compatible con MySQL y PostgreSQL.","Incorrecta: Amazon Neptune es una base de grafos y no es compatible con MySQL ni PostgreSQL."],fuentes:["https://docs.aws.amazon.com/dynamodb/","https://docs.aws.amazon.com/elasticache/","https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/CHAP_AuroraOverview.html","https://docs.aws.amazon.com/neptune/"]},{id:"3.4-q5",taskId:"3.4",objetivos:["3.4#4","3.4#5"],tipo:"comparacion",question:"Un equipo debe elegir entre dos motores relacionales gestionados y una base NoSQL. ¿Qué afirmación los distingue correctamente?",options:["Amazon RDS y Amazon Aurora son relacionales; Amazon DynamoDB es NoSQL y no usa el modelo relacional con SQL.","Amazon DynamoDB es un motor relacional y Amazon RDS es NoSQL, por lo que los modelos de datos de ambos servicios están intercambiados.","Los tres son relacionales y solo cambia la región donde se despliegan, sin diferencias de modelo de datos.","Amazon Aurora es NoSQL en memoria y Amazon DynamoDB es un motor relacional con consultas SQL."],correctAnswer:0,explanation:"Amazon RDS y Amazon Aurora comparten el modelo relacional (tablas, esquema y SQL); Aurora es el motor de AWS compatible con MySQL y PostgreSQL. Amazon DynamoDB es NoSQL, de clave-valor y documento, sin esquema fijo. Invertir los modelos o inventar una Aurora en memoria describe servicios que no corresponden. Si el requisito cambiara a acceso por clave con escala impredecible, la respuesta sería DynamoDB.",porQueOpcion:["Correcta: Amazon RDS y Amazon Aurora son relacionales, mientras que Amazon DynamoDB es NoSQL y no usa el modelo relacional con SQL.","Incorrecta: Amazon DynamoDB no es relacional ni Amazon RDS es NoSQL; los modelos están invertidos.","Incorrecta: los tres no son relacionales; Amazon DynamoDB es NoSQL y difiere en el modelo de datos.","Incorrecta: Amazon Aurora no es NoSQL en memoria ni Amazon DynamoDB es un motor relacional con consultas SQL."],fuentes:["https://docs.aws.amazon.com/rds/","https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/CHAP_AuroraOverview.html","https://docs.aws.amazon.com/dynamodb/"]},{id:"3.4-q6",taskId:"3.4",objetivos:["3.4#4"],tipo:"escenario",question:"Una aplicación transaccional necesita un motor relacional compatible con PostgreSQL, con réplicas de lectura, alta disponibilidad y menos administración. ¿Qué opción encaja mejor?",options:["Amazon DynamoDB, porque es una base NoSQL clave-valor.","Amazon Aurora, porque es un motor relacional gestionado y compatible con PostgreSQL.","Amazon ElastiCache, porque guarda los datos en memoria.","Alojar el motor en Amazon EC2 para no depender de un servicio gestionado."],correctAnswer:1,explanation:"Amazon Aurora ofrece el modelo relacional con compatibilidad PostgreSQL, replicación integrada y réplicas de lectura, sin administrar el sistema operativo. Amazon DynamoDB no es relacional, Amazon ElastiCache no es una base persistente y alojar en Amazon EC2 añade la administración que se quiere evitar. Si el requisito cambiara a un motor concreto no soportado por Aurora, la opción sería Amazon RDS.",porQueOpcion:["Incorrecta: Amazon DynamoDB es NoSQL clave-valor y no ofrece el modelo relacional compatible con PostgreSQL.","Correcta: Amazon Aurora es un motor relacional gestionado y compatible con PostgreSQL, con réplicas de lectura y alta disponibilidad.","Incorrecta: Amazon ElastiCache guarda datos en memoria y no es una base relacional con réplicas de lectura.","Incorrecta: alojar el motor en Amazon EC2 añade la administración que se quiere evitar."],fuentes:["https://docs.aws.amazon.com/dynamodb/","https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/CHAP_AuroraOverview.html","https://docs.aws.amazon.com/elasticache/","https://docs.aws.amazon.com/ec2/","https://docs.aws.amazon.com/rds/"]},{id:"3.4-q7",taskId:"3.4",objetivos:["3.4#5"],tipo:"conocimiento",question:"¿Qué característica define a una base NoSQL de clave-valor y documento totalmente gestionada?",options:["Es un motor relacional que exige un esquema fijo, admite SQL y garantiza integridad referencial.","Es una base NoSQL de clave-valor y documento, totalmente gestionada, que escala horizontalmente.","Es un servicio de caché en memoria que se coloca delante de una base relacional para acelerar lecturas.","Es un servicio que solo convierte esquemas y código entre motores de base de datos distintos."],correctAnswer:1,explanation:"Amazon DynamoDB es una base NoSQL gestionada: guarda elementos identificados por clave, admite clave-valor y documento, y escala de forma horizontal con latencia de milisegundos sin administrar servidores. No se consulta con SQL tradicional, no es una caché y no convierte esquemas. Si el requisito fuera una caché en memoria delante de otra base, la respuesta sería Amazon ElastiCache.",porQueOpcion:["Incorrecta: un motor relacional con esquema fijo y SQL no es una base NoSQL de clave-valor y documento.","Correcta: Amazon DynamoDB es una base NoSQL de clave-valor y documento, totalmente gestionada, que escala horizontalmente.","Incorrecta: una caché en memoria delante de una base relacional no es una base NoSQL de clave-valor y documento.","Incorrecta: convertir esquemas entre motores es tarea de AWS SCT, no una base NoSQL."],fuentes:["https://docs.aws.amazon.com/dynamodb/","https://docs.aws.amazon.com/SchemaConversionTool/","https://docs.aws.amazon.com/elasticache/"]},{id:"3.4-q8",taskId:"3.4",objetivos:["3.4#5"],tipo:"escenario",question:"Una aplicación con millones de usuarios necesita leer y escribir por clave con latencia de milisegundos y escala impredecible, sin administrar servidores. ¿Qué servicio encaja mejor?",options:["Amazon RDS con una instancia muy grande.","Amazon DynamoDB, por su modelo clave-valor y su escalado gestionado.","Amazon ElastiCache, porque es una base de datos principal persistente.","Una base alojada en Amazon EC2 para controlar el sistema operativo."],correctAnswer:1,explanation:"El patrón de acceso por clave con escala variable es exactamente el caso de uso de Amazon DynamoDB. Amazon ElastiCache es una caché, no una base persistente; una base en Amazon EC2 añadiría la administración que se quiere evitar; y una instancia RDS grande no cambia el modelo relacional. Si el requisito cambiara a consultas relacionales con integridad referencial, la respuesta sería Amazon RDS o Amazon Aurora.",porQueOpcion:["Incorrecta: una instancia RDS muy grande mantiene el modelo relacional y no ofrece el acceso por clave con escala impredecible.","Correcta: Amazon DynamoDB encaja con el acceso por clave, la latencia de milisegundos y el escalado gestionado.","Incorrecta: Amazon ElastiCache es una caché, no una base de datos principal persistente.","Incorrecta: una base alojada en Amazon EC2 añade la administración de servidores que se quiere evitar."],fuentes:["https://docs.aws.amazon.com/rds/","https://docs.aws.amazon.com/dynamodb/","https://docs.aws.amazon.com/elasticache/","https://docs.aws.amazon.com/ec2/","https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/CHAP_AuroraOverview.html"]},{id:"3.4-q9",taskId:"3.4",objetivos:["3.4#4","3.4#5","3.4#6"],tipo:"comparacion",question:"¿Qué diferencia hay entre usar una base relacional o NoSQL y usar una base en memoria como caché?",options:["Las bases relacionales y NoSQL guardan los datos de forma persistente; una base en memoria como Amazon ElastiCache se usa sobre todo como caché para acelerar lecturas.","Amazon ElastiCache sustituye por completo a la base de datos principal porque guarda todos los datos en disco de forma duradera y persistente, sin necesitar ninguna base detrás.","Las bases NoSQL y en memoria son lo mismo y solo cambia el nombre comercial del servicio contratado.","Una base en memoria garantiza la persistencia a largo plazo mejor que una base relacional o NoSQL."],correctAnswer:0,explanation:"El eje es persistencia frente a aceleración: relacional y NoSQL almacenan el dato de forma duradera (Amazon RDS, Amazon Aurora, Amazon DynamoDB), mientras que Amazon ElastiCache mantiene los datos en RAM como caché delante de otra base. Tratar la caché como base principal o como NoSQL niega su papel. Si el requisito fuera guardar el dato crítico, la respuesta sería una base persistente, no la caché.",porQueOpcion:["Correcta: relacional y NoSQL guardan el dato de forma persistente, mientras Amazon ElastiCache se usa sobre todo como caché para acelerar lecturas.","Incorrecta: Amazon ElastiCache no sustituye a la base principal porque es una caché en memoria, no un almacén duradero en disco.","Incorrecta: NoSQL y en memoria no son lo mismo; la caché cumple un papel de aceleración distinto.","Incorrecta: una base en memoria no garantiza mejor la persistencia a largo plazo que una relacional o NoSQL."],fuentes:["https://docs.aws.amazon.com/elasticache/","https://docs.aws.amazon.com/rds/","https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/CHAP_AuroraOverview.html","https://docs.aws.amazon.com/dynamodb/","https://docs.aws.amazon.com/ram/latest/userguide/what-is.html"]},{id:"3.4-q10",taskId:"3.4",objetivos:["3.4#6"],tipo:"conocimiento",question:"¿Para qué se usa principalmente una base de datos en memoria como caché?",options:["Para migrar esquemas entre motores de base de datos.","Para almacenar datos en memoria y acelerar el acceso, por ejemplo como caché.","Para reemplazar a Amazon DynamoDB como base NoSQL de propósito general y persistente para todos los datos de la aplicación.","Para ejecutar consultas analíticas sobre un almacén de datos."],correctAnswer:1,explanation:"Amazon ElastiCache es un almacén en memoria pensado para dar latencias muy bajas, normalmente como caché delante de una base relacional o NoSQL. No persiste los datos como base principal, no convierte esquemas y no sustituye a un almacén analítico. Si el requisito fuera conversión de esquema entre motores, la respuesta sería AWS Schema Conversion Tool (AWS SCT).",porQueOpcion:["Incorrecta: migrar esquemas entre motores es tarea de AWS SCT, no de una base en memoria.","Correcta: una base en memoria almacena datos en RAM para acelerar el acceso, por ejemplo como caché.","Incorrecta: Amazon ElastiCache no reemplaza a Amazon DynamoDB como base NoSQL persistente de propósito general.","Incorrecta: ejecutar consultas analíticas sobre un almacén de datos corresponde a Amazon Redshift."],fuentes:["https://docs.aws.amazon.com/dynamodb/","https://docs.aws.amazon.com/SchemaConversionTool/","https://docs.aws.amazon.com/elasticache/","https://docs.aws.amazon.com/redshift/","https://docs.aws.amazon.com/ram/latest/userguide/what-is.html"]},{id:"3.4-q11",taskId:"3.4",objetivos:["3.4#6"],tipo:"escenario",question:"Una aplicación lee con frecuencia los mismos datos de una base relacional y la latencia de esas lecturas es alta. Aunque el equipo valora migrar de motor para reducir coste, no es relevante para este problema: el cuello de botella está en las lecturas repetidas. ¿Qué solución reduce la carga sobre la base?",options:["Añadir Amazon ElastiCache como capa de caché en memoria delante de la base relacional.","Cambiar la base relacional por Amazon DynamoDB y migrar todo el esquema manteniendo el modelo relacional y las consultas SQL.","Migrar la base de datos con AWS Schema Conversion Tool (AWS SCT).","Alojar la base en Amazon EC2 con más almacenamiento."],correctAnswer:0,explanation:"Cuando las mismas lecturas se repiten, Amazon ElastiCache las sirve desde memoria y descarga a la base principal. Cambiar de modelo de datos, convertir el esquema o añadir almacenamiento no ataca el problema de latencia por lecturas repetidas. Si el requisito cambiara a latencia predecible con acceso por clave a gran escala, la opción sería Amazon DynamoDB.",porQueOpcion:["Correcta: añadir Amazon ElastiCache como caché en memoria delante de la base relacional sirve las lecturas repetidas desde memoria.","Incorrecta: cambiar a Amazon DynamoDB no mantiene el modelo relacional ni las consultas SQL y no ataca la latencia.","Incorrecta: AWS Schema Conversion Tool (AWS SCT) convierte esquemas, no reduce la carga de lecturas repetidas.","Incorrecta: alojar la base en Amazon EC2 con más almacenamiento no ataca la latencia por lecturas repetidas."],fuentes:["https://docs.aws.amazon.com/elasticache/","https://docs.aws.amazon.com/dynamodb/","https://docs.aws.amazon.com/SchemaConversionTool/","https://docs.aws.amazon.com/ec2/"]},{id:"3.4-q12",taskId:"3.4",objetivos:["3.4#7"],tipo:"conocimiento",question:"¿Cuál es la diferencia entre una herramienta de migración de datos y una de conversión de esquema?",options:["AWS DMS mueve los datos entre orígenes y destinos; AWS SCT convierte el esquema y el código de la base de datos entre motores distintos.","AWS DMS convierte el esquema y el código de la base de datos entre motores distintos, mientras que AWS SCT se encarga de mover los datos hacia el destino final.","Ambos solo funcionan entre bases de datos del mismo motor y no admiten escenarios heterogéneos.","Ambos son servicios de copia de seguridad y no tienen relación con la migración de bases de datos."],correctAnswer:0,explanation:"AWS Database Migration Service (AWS DMS) replica y mueve los datos, con replicación continua para reducir el corte. AWS Schema Conversion Tool (AWS SCT) convierte el esquema y el código cuando el motor de destino es distinto del de origen. Intercambiar las funciones o negar el escenario heterogéneo confunde ambas herramientas. Si cambiara el requisito a una migración homogénea con el mismo motor, AWS SCT dejaría de ser imprescindible.",porQueOpcion:["Correcta: AWS DMS mueve los datos entre orígenes y destinos y AWS SCT convierte el esquema y el código entre motores distintos.","Incorrecta: invierte las funciones, ya que AWS DMS mueve los datos y AWS SCT convierte el esquema.","Incorrecta: ambas herramientas admiten escenarios heterogéneos entre motores distintos.","Incorrecta: AWS DMS y AWS SCT son herramientas de migración, no servicios de copia de seguridad."],fuentes:["https://docs.aws.amazon.com/dms/","https://docs.aws.amazon.com/SchemaConversionTool/"]},{id:"3.4-q13",taskId:"3.4",objetivos:["3.4#2","3.4#7"],tipo:"comparacion",question:"En una migración heterogénea, ¿cómo se combinan las herramientas de migración de AWS?",options:["AWS Schema Conversion Tool (AWS SCT) convierte el esquema y el código, y AWS DMS replica los datos hacia la base de destino.","AWS DMS convierte el esquema y deja los datos en el origen sin moverlos, mientras que AWS SCT se limita a supervisar el progreso.","Solo se necesita AWS Migration Hub para mover los datos y no hace falta ninguna herramienta de conversión.","Basta con Amazon RDS para migrar sin herramientas adicionales, ya que el servicio importa cualquier esquema."],correctAnswer:0,explanation:"En una migración heterogénea primero se convierte el esquema y el código con AWS SCT y después se replica el dato con AWS DMS. AWS Migration Hub sirve para seguir el progreso, no para mover los datos, y Amazon RDS no migra por sí solo ni importa cualquier esquema. Si el requisito cambiara a una migración homogénea, bastaría con AWS DMS para mover los datos.",porQueOpcion:["Correcta: en una migración heterogénea AWS SCT convierte el esquema y el código y AWS DMS replica los datos hacia la base de destino.","Incorrecta: AWS DMS no convierte el esquema ni deja los datos en el origen; AWS SCT no se limita a supervisar el progreso.","Incorrecta: AWS Migration Hub solo sigue el progreso y no sustituye a la herramienta de conversión.","Incorrecta: Amazon RDS no migra por sí solo ni importa cualquier esquema sin herramientas adicionales."],fuentes:["https://docs.aws.amazon.com/SchemaConversionTool/","https://docs.aws.amazon.com/dms/","https://docs.aws.amazon.com/migrationhub/","https://docs.aws.amazon.com/rds/"]},{id:"3.4-q14",taskId:"3.4",objetivos:["3.4#2"],tipo:"escenario",question:"Una empresa quiere migrar su base de datos local a AWS con el menor tiempo de inactividad posible y mantener el destino sincronizado mientras corta el servicio. ¿Qué servicio encaja mejor?",options:["AWS Database Migration Service (AWS DMS), que replica los datos de forma continua hasta el corte.","AWS Schema Conversion Tool (AWS SCT), que replica los datos en tiempo real.","Amazon ElastiCache, que migra los datos a memoria.","Amazon EC2, que migra la base automáticamente al lanzarse."],correctAnswer:0,explanation:"AWS DMS replica los datos de forma continua, de modo que el destino se mantiene al día y el corte de servicio se reduce al mínimo. AWS SCT convierte esquemas, no replica datos; Amazon ElastiCache no migra bases de datos; y Amazon EC2 no migra nada por sí solo. Si el requisito cambiara a convertir el esquema entre motores distintos, la herramienta sería AWS SCT.",porQueOpcion:["Correcta: AWS DMS replica los datos de forma continua hasta el corte, minimizando el tiempo de inactividad.","Incorrecta: AWS SCT convierte esquemas y no replica datos en tiempo real.","Incorrecta: Amazon ElastiCache no migra bases de datos.","Incorrecta: Amazon EC2 no migra la base por el hecho de lanzarse."],fuentes:["https://docs.aws.amazon.com/dms/","https://docs.aws.amazon.com/SchemaConversionTool/","https://docs.aws.amazon.com/elasticache/","https://docs.aws.amazon.com/ec2/"]},{id:"3.4-q15",taskId:"3.4",objetivos:["3.4#1"],tipo:"escenario",question:"Una empresa revisa su cartera de aplicaciones: un sistema de facturación con relaciones y SQL, una app de sesiones con acceso por clave y un panel que repite lecturas. ¿Qué combinación de bases encaja mejor?",options:["Relacional gestionada para la facturación, NoSQL de clave-valor para las sesiones y una caché en memoria para las lecturas repetidas.","NoSQL clave-valor para la facturación, una caché en memoria para las sesiones y un almacén analítico para las lecturas repetidas del panel de datos.","Un único motor relacional para las tres cargas, ajustando solo el tamaño de la instancia según la demanda.","Solo cachés en memoria para las tres cargas, porque ofrecen la menor latencia posible en todos los casos."],correctAnswer:0,explanation:"Cada carga encaja con una categoría: facturación transaccional en una base relacional gestionada, sesiones con acceso por clave en una base NoSQL y lecturas repetidas en una caché en memoria. Forzar un único modelo o usar solo cachés desaprovecha las ventajas de cada categoría. Si el requisito cambiara a análisis de grandes volúmenes, la categoría adecuada sería un almacén de datos columnar.",porQueOpcion:["Correcta: relacional para la facturación, NoSQL clave-valor para las sesiones y caché en memoria para las lecturas repetidas.","Incorrecta: no asigna a cada carga su categoría, ya que la facturación es relacional y las sesiones encajan en NoSQL.","Incorrecta: forzar un único motor relacional desaprovecha las ventajas de NoSQL y de la caché.","Incorrecta: usar solo cachés en memoria no ofrece persistencia para la facturación ni para las sesiones."],fuentes:["https://docs.aws.amazon.com/rds/"]},{id:"3.4-q16",taskId:"3.4",objetivos:["3.4#7"],tipo:"escenario",question:"Una empresa migra su base de datos Oracle local a un motor relacional gestionado distinto y necesita minimizar el tiempo de inactividad sin reescribir el esquema a mano. Aunque el equipo es reducido y opera con un plazo ajustado, la migración debe superar una auditoría de cumplimiento. ¿Cómo aborda la migración?",options:["Convertir el esquema y el código con una herramienta de conversión y replicar los datos de forma continua con una herramienta de migración hasta el corte.","Copiar los archivos de datos directamente a la instancia de destino, ajustar el esquema a mano después del corte y validar la aplicación en producción durante la ventana de mantenimiento.","Exportar los datos a un almacén analítico y consultarlos desde la aplicación en lugar de migrarlos al nuevo motor.","Confiar en que el nuevo motor lea el esquema del origen sin conversión y sin réplica previa de los datos."],correctAnswer:0,explanation:"Es una migración heterogénea: primero se convierte el esquema y el código con AWS SCT y después se replica el dato con AWS DMS de forma continua hasta el corte, reduciendo la inactividad. Copiar archivos y reescribir el esquema a mano no ataca la incompatibilidad y alarga el corte, y el destino no interpreta el esquema de otro motor sin conversión. Si el requisito cambiara a una migración homogénea, la conversión de esquema dejaría de ser necesaria.",porQueOpcion:["Correcta: convierte el esquema con AWS SCT y replica los datos de forma continua con AWS DMS hasta el corte.","Incorrecta: copiar archivos y reescribir el esquema a mano no resuelve la incompatibilidad y alarga el corte.","Incorrecta: exportar a un almacén analítico no migra la base al nuevo motor relacional.","Incorrecta: el nuevo motor no interpreta el esquema de otro motor sin conversión ni réplica previa."],fuentes:["https://docs.aws.amazon.com/SchemaConversionTool/","https://docs.aws.amazon.com/dms/"]},{id:"3.4-q17",taskId:"3.4",objetivos:["3.4#3"],tipo:"comparacion",question:"Una empresa valora ejecutar su propia base de datos sobre instancias que administra frente a contratar una base gestionada por AWS. ¿Qué distingue la responsabilidad operativa de cada opción?",options:["La base gestionada delega en AWS parches, copias y alta disponibilidad, mientras que la base autogestionada traslada al equipo toda la operación del motor.","La base autogestionada delega en AWS los parches, las copias y la alta disponibilidad, mientras que la base gestionada obliga al equipo a mantener el sistema operativo y el motor sin ninguna automatización.","No hay diferencia en la operación: las dos alternativas aplican las mismas automatizaciones de parches, copias y alta disponibilidad sin intervención del equipo.","La base autogestionada siempre cuesta menos porque la instancia no cobra por cómputo ni por almacenamiento durante su ciclo de vida."],correctAnswer:0,explanation:"En la base gestionada, AWS administra la infraestructura del motor (parches, copias de seguridad, alta disponibilidad y parte del escalado) y el equipo se concentra en el esquema, los datos y las consultas. En la base autogestionada sobre instancias, el control total del motor y del sistema operativo viene acompañado de toda esa operación a cargo del equipo. Si cambia el requisito a una versión o configuración no soportada por el servicio gestionado, la opción sería la base autogestionada.",porQueOpcion:["Correcta: la base gestionada delega en AWS parches, copias y alta disponibilidad, y la autogestionada traslada toda la operación al equipo.","Incorrecta: invierte la responsabilidad, ya que la autogestionada no delega en AWS y la gestionada sí automatiza.","Incorrecta: las dos alternativas no aplican las mismas automatizaciones; difieren en quién opera el motor.","Incorrecta: la base autogestionada no cuesta menos por no cobrar cómputo ni almacenamiento, que sí se facturan."],fuentes:["https://docs.aws.amazon.com/rds/"]}],3.5:[{id:"3.5-q1",taskId:"3.5",objetivos:["3.5#1"],tipo:"conocimiento",question:"¿Qué servicio de AWS permite crear una red virtual aislada con el rango de direcciones IP que tú defines?",options:["Amazon Route 53","Amazon VPC","Amazon CloudFront","AWS Direct Connect"],correctAnswer:1,explanation:"Amazon VPC es la red virtual aislada que se crea dentro de una región con un rango de direcciones propio. Route 53 es DNS, CloudFront entrega contenido y Direct Connect es un enlace dedicado, no una red virtual. Si el requisito fuera conectar la red local con AWS en lugar de crear una red propia, el servicio sería AWS Direct Connect.",porQueOpcion:["Incorrecta: Route 53 es el servicio de DNS y no crea una red virtual aislada.","Correcta: Amazon VPC crea la red virtual aislada dentro de una región con el rango de direcciones IP que tú defines.","Incorrecta: CloudFront es una red de entrega de contenido que cachea y sirve contenido, no crea redes.","Incorrecta: Direct Connect es un enlace dedicado que conecta la red local con AWS, no una red virtual propia."],fuentes:["https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html","https://docs.aws.amazon.com/directconnect/latest/UserGuide/Welcome.html","https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/Welcome.html","https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/Introduction.html"]},{id:"3.5-q2",taskId:"3.5",objetivos:["3.5#2"],tipo:"conocimiento",question:"Dentro de una VPC, ¿qué se necesita para que una subred tenga salida y entrada hacia internet?",options:["Un security group asociado a la subred con reglas de permiso de entrada y de salida.","Un internet gateway asociado a la VPC y una route table que envíe el tráfico hacia él.","Una comprobación de estado de Amazon Route 53 que desvía el tráfico a otro destino.","Un VPC endpoint que da acceso privado a los servicios de AWS sin salir a internet público."],correctAnswer:1,explanation:"Una subred es pública cuando la VPC tiene un internet gateway y la route table de la subred dirige el tráfico hacia ese gateway. El security group controla permisos, no la salida a internet; el VPC endpoint sirve para acceso privado a servicios de AWS. Si el requisito fuera dar salida a internet a una subred privada, bastaría con un NAT gateway en lugar del internet gateway.",porQueOpcion:["Incorrecta: el security group controla permisos de tráfico, pero no proporciona la salida ni la entrada a internet.","Correcta: con un internet gateway asociado a la VPC y una route table que envía el tráfico hacia él, la subred se vuelve pública.","Incorrecta: una comprobación de estado de Route 53 desvía tráfico entre destinos, no da conectividad a internet.","Incorrecta: un VPC endpoint da acceso privado a los servicios de AWS sin salir a internet, no salida a internet público."],fuentes:["https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/Welcome.html"]},{id:"3.5-q3",taskId:"3.5",objetivos:["3.5#2"],tipo:"escenario",question:"Una empresa diseña una VPC con dos capas: servidores web accesibles desde internet y una base de datos que solo debe recibir tráfico de esos servidores. ¿Qué diseño de subredes es correcto?",options:["Colocar los servidores web y la base de datos en la misma subred pública para simplificar la ruta.","Poner los servidores web en una subred pública con internet gateway y la base de datos en una subred privada sin entrada desde internet.","Poner la base de datos en una subred pública con internet gateway y los servidores web aislados en una subred privada.","Colocar todo en subredes privadas y asociar un internet gateway y una ruta por defecto a cada subred."],correctAnswer:1,explanation:"La capa web necesita publicarse hacia internet, así que va en una subred pública con internet gateway. La base de datos debe quedar aislada de conexiones entrantes de internet, por lo que se ubica en una subred privada, con salida controlada si hace falta. Si el escenario pidiera que la base de datos recibiera conexiones desde internet, el diseño correcto cambiaría.",porQueOpcion:["Incorrecta: dejar la base de datos en una subred pública la expone a conexiones entrantes desde internet.","Correcta: la capa web va en una subred pública con internet gateway y la base de datos se aísla en una subred privada sin entrada desde internet.","Incorrecta: invierte el diseño, expone la base de datos y deja la capa web inaccesible desde internet.","Incorrecta: una subred con ruta por defecto al internet gateway deja de ser privada y no publica la capa web según el requisito."],fuentes:["https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html"]},{id:"3.5-q4",taskId:"3.5",objetivos:["3.5#5"],tipo:"comparacion",question:"Una empresa evalúa cómo conectar su centro de datos con AWS y compara dos alternativas: una que viaja cifrada por internet y otra que usa un enlace privado y dedicado. ¿Qué afirmación distingue correctamente ambas opciones?",options:["AWS Direct Connect cifra el tráfico sobre internet público y AWS VPN contrata un enlace dedicado por un proveedor.","AWS VPN usa un túnel cifrado sobre internet y AWS Direct Connect es un enlace dedicado y privado que no atraviesa internet.","Ambos son enlaces dedicados y privados que no atraviesan internet; solo cambia el ancho de banda contratado.","AWS VPN sirve únicamente para resolver nombres DNS y AWS Direct Connect solo conecta VPC dentro de una misma región."],correctAnswer:1,explanation:"AWS VPN establece un túnel cifrado a través de internet, rápido de desplegar pero con rendimiento variable. AWS Direct Connect es un enlace dedicado y privado que no pasa por internet, con ancho de banda y latencia más estables. Si cambia el requisito hacia el menor coste y la rapidez de despliegue, la opción adecuada pasaría a ser la VPN.",porQueOpcion:["Incorrecta: intercambia las definiciones, Direct Connect no viaja por internet y la VPN no contrata un enlace dedicado.","Correcta: AWS VPN establece un túnel cifrado sobre internet y AWS Direct Connect es un enlace dedicado y privado que no atraviesa internet.","Incorrecta: solo Direct Connect es un enlace dedicado y privado; la VPN sí atraviesa internet.","Incorrecta: la VPN no resuelve nombres DNS ni Direct Connect se limita a conectar VPC de una misma región."],fuentes:["https://docs.aws.amazon.com/directconnect/latest/UserGuide/Welcome.html","https://docs.aws.amazon.com/vpn/"]},{id:"3.5-q5",taskId:"3.5",objetivos:["3.5#5"],tipo:"escenario",question:"Una empresa transfiere cada noche grandes volúmenes de datos entre su centro de datos y AWS y exige ancho de banda estable y latencia predecible, con un enlace de respaldo. ¿Qué combinación es la más adecuada?",options:["Usar solo AWS VPN para el tráfico principal y añadir Amazon CloudFront como respaldo.","Contratar AWS Direct Connect como enlace principal y usar AWS VPN como respaldo.","Usar un VPC endpoint como enlace principal y prescindir de conexión dedicada.","Confiar únicamente en internet público y un security group para garantizar el ancho de banda."],correctAnswer:1,explanation:"AWS Direct Connect aporta un enlace dedicado y privado con ancho de banda y latencia estables, que es lo que exige la transferencia diaria. AWS VPN sobre internet sirve como respaldo y para tráfico puntual, sin la inversión de un segundo enlace dedicado. Si se pidiera el menor coste posible y no una latencia predecible, bastaría con el túnel cifrado sobre internet.",porQueOpcion:["Incorrecta: la VPN no ofrece la latencia predecible exigida y CloudFront no es un enlace de respaldo.","Correcta: Direct Connect aporta ancho de banda estable como enlace principal y la VPN sirve de respaldo sobre internet.","Incorrecta: un VPC endpoint da acceso privado a servicios de AWS y no conecta el centro de datos con la VPC.","Incorrecta: internet público no garantiza ancho de banda y el security group no mejora la conectividad."],fuentes:["https://docs.aws.amazon.com/vpn/","https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/Introduction.html","https://docs.aws.amazon.com/directconnect/latest/UserGuide/Welcome.html"]},{id:"3.5-q6",taskId:"3.5",objetivos:["3.5#5"],tipo:"tradeoff",question:"Un equipo pequeño quiere conectar su oficina con AWS en pocos días y con presupuesto ajustado, y acepta que el rendimiento varíe algo. ¿Qué opción equilibra mejor rapidez, coste y los requisitos de red?",options:["AWS Direct Connect, porque es la opción de menor coste inicial, se aprovisiona en pocos días y no exige contratos ni proveedor.","AWS VPN, porque se despliega rápido sobre internet y encaja con un presupuesto ajustado aceptando variaciones de rendimiento.","AWS PrivateLink, porque publica la red de la oficina como servicio privado dentro de la VPC y evita internet.","Un VPC endpoint, porque sustituye por completo a la conexión de red con la oficina y no cobra por tráfico."],correctAnswer:1,explanation:"AWS VPN es la opción rápida y económica cuando se tolera cierta variabilidad, porque el túnel viaja cifrado por internet. Direct Connect ofrece más estabilidad pero exige contratación y más tiempo, y ni PrivateLink ni los VPC endpoints conectan una red externa con la VPC. Si el escenario exigiera ancho de banda estable para producción, la respuesta cambiaría a una conexión dedicada.",porQueOpcion:["Incorrecta: Direct Connect no es la opción de menor coste inicial y exige contratación con proveedor y más tiempo.","Correcta: AWS VPN se despliega rápido sobre internet y encaja con un presupuesto ajustado que acepta rendimiento variable.","Incorrecta: PrivateLink publica servicios dentro de la VPC y no conecta la red de la oficina.","Incorrecta: un VPC endpoint no sustituye la conexión de red con la oficina ni es un enlace de red."],fuentes:["https://docs.aws.amazon.com/directconnect/latest/UserGuide/Welcome.html","https://docs.aws.amazon.com/vpn/","https://docs.aws.amazon.com/vpc/latest/privatelink/what-is-privatelink.html"]},{id:"3.5-q7",taskId:"3.5",objetivos:["3.5#3"],tipo:"comparacion",question:"¿Qué afirmación distingue correctamente un security group de un network ACL?",options:["El security group es sin estado y se asocia a la subred, mientras que el network ACL es con estado, se asocia a la instancia y solo admite reglas de permiso.","El security group es con estado y solo admite reglas de permiso sobre recursos; el network ACL es sin estado, actúa sobre la subred y admite permiso y denegación.","Los dos son equivalentes y solo cambia el nombre según el servicio que los use: ambos filtran por subred, son con estado y no admiten reglas de denegación.","El network ACL solo permite reglas de permiso y se evalúa por número de regla, mientras que el security group permite permitir y denegar y es sin estado."],correctAnswer:1,explanation:"El security group es con estado, actúa sobre recursos y solo admite reglas de permiso. El network ACL es sin estado, actúa sobre subredes, se evalúa por número de regla y admite reglas tanto de permiso como de denegación. Si el objetivo fuera filtrar a nivel de subred con reglas de denegación explícitas, el control adecuado sería el network ACL.",porQueOpcion:["Incorrecta: invierte las propiedades, el security group es con estado y actúa sobre recursos, no sin estado sobre la subred.","Correcta: el security group es con estado y solo admite reglas de permiso, y el network ACL es sin estado, actúa sobre la subred y admite permiso y denegación.","Incorrecta: no son equivalentes y el network ACL sí admite reglas de denegación.","Incorrecta: la descripción está invertida, el network ACL admite denegación y el security group es con estado."],fuentes:["https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html"]},{id:"3.5-q8",taskId:"3.5",objetivos:["3.5#3"],tipo:"seguridad",question:"Un equipo quiere detectar de forma continua vulnerabilidades y exposiciones de red en sus instancias. ¿Qué servicio cubre esa necesidad?",options:["Para filtrar el tráfico de entrada y salida a nivel de subred mediante reglas evaluadas por orden.","Para evaluar de forma continua las instancias y detectar vulnerabilidades y exposiciones de red.","Para registrar y auditar los cambios de configuración de la VPC y de los recursos de la cuenta.","Para emitir certificados TLS y gestionar el cifrado del tráfico en tránsito hacia los servicios."],correctAnswer:1,explanation:"Amazon Inspector es un servicio de evaluación continua que analiza las instancias para encontrar vulnerabilidades y exposiciones de red y reporta hallazgos. No filtra tráfico, no audita cambios de configuración ni gestiona certificados. Si el requisito fuera mitigar ataques de denegación de servicio en la red, el servicio sería otro distinto y no la evaluación de vulnerabilidades.",porQueOpcion:["Incorrecta: filtrar el tráfico por reglas evaluadas por orden corresponde a un network ACL, no a la evaluación de vulnerabilidades.","Correcta: evaluar de forma continua las instancias y detectar vulnerabilidades y exposiciones de red es la función de Amazon Inspector.","Incorrecta: registrar y auditar cambios de configuración corresponde a AWS CloudTrail, no a la detección de vulnerabilidades.","Incorrecta: emitir certificados TLS y gestionar el cifrado corresponde a AWS Certificate Manager, no a la evaluación de vulnerabilidades."],fuentes:["https://docs.aws.amazon.com/inspector/","https://docs.aws.amazon.com/cloudtrail/","https://docs.aws.amazon.com/acm/"]},{id:"3.5-q9",taskId:"3.5",objetivos:["3.5#4"],tipo:"conocimiento",question:"Un equipo necesita publicar un dominio y dirigir el tráfico hacia distintos destinos según políticas. ¿Cuál es el propósito principal del servicio de DNS gestionado?",options:["Alojar sitios web estáticos y entregar su contenido cacheado desde ubicaciones cercanas al usuario.","Ofrecer resolución DNS y registrar nombres de dominio, dirigiendo el tráfico a los destinos adecuados.","Crear redes virtuales aisladas dentro de una región con el rango de direcciones que tú defines.","Establecer un enlace dedicado y privado entre la red local y AWS sin atravesar internet."],correctAnswer:1,explanation:"Amazon Route 53 es el servicio de DNS administrado: registra dominios y resuelve nombres hacia direcciones IP o destinos de AWS. El alojamiento de contenido, las redes virtuales y los enlaces dedicados corresponden a otros servicios. Si el requisito fuera entregar el contenido cacheado cerca del usuario, el servicio sería la red de entrega de contenido y no el DNS.",porQueOpcion:["Incorrecta: alojar sitios estáticos y entregar contenido cacheado es la red de entrega de contenido, no el DNS.","Correcta: el DNS gestionado resuelve nombres y registra dominios, dirigiendo el tráfico a los destinos adecuados.","Incorrecta: crear redes virtuales aisladas dentro de una región corresponde a Amazon VPC, no al DNS.","Incorrecta: establecer un enlace dedicado y privado con la red local corresponde a AWS Direct Connect, no al DNS."],fuentes:["https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html","https://docs.aws.amazon.com/directconnect/latest/UserGuide/Welcome.html","https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/Welcome.html"]},{id:"3.5-q10",taskId:"3.5",objetivos:["3.5#4"],tipo:"casoDeUso",question:"Una empresa quiere que, si su servidor principal deja de responder, el dominio empiece a dirigir a los usuarios hacia un servidor secundario sin intervención manual. ¿Qué función del DNS gestionado lo permite?",options:["El registro de dominios, porque asigna el nombre público.","Las comprobaciones de estado con enrutamiento por failover.","El enrutamiento por ponderación, porque reparte el tráfico siempre al primer destino.","La resolución de nombres internos, porque solo funciona dentro de la VPC."],correctAnswer:1,explanation:"Las comprobaciones de estado de Amazon Route 53 detectan un destino no saludable y, con la política de failover, redirigen el tráfico al destino disponible de forma automática. El registro de dominios solo publica el nombre y la ponderación no resuelve por sí sola un fallo. Si el objetivo fuera repartir el tráfico por proporciones entre varios destinos, se usaría enrutamiento por ponderación.",porQueOpcion:["Incorrecta: registrar el dominio solo publica el nombre y no redirige el tráfico ante un fallo.","Correcta: las comprobaciones de estado con enrutamiento por failover redirigen el tráfico al destino disponible de forma automática.","Incorrecta: el enrutamiento por ponderación reparte el tráfico por proporciones y no resuelve por sí solo un fallo.","Incorrecta: la resolución de nombres internos solo funciona dentro de la VPC y no hace failover público."],fuentes:["https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/Welcome.html"]},{id:"3.5-q11",taskId:"3.5",objetivos:["3.5#1"],tipo:"escenario",question:"Una empresa publica una aplicación web y necesita dos cosas de su capa de red: entregar imágenes y vídeos estáticos con baja latencia a usuarios de varios continentes y resolver el nombre de dominio hacia el destino activo. ¿Qué combinación de servicios cubre esos requisitos?",options:["Amazon CloudFront para la entrega de contenido en el borde y Amazon Route 53 para la resolución DNS.","Amazon VPC para la entrega de contenido y AWS Direct Connect para la resolución de nombres.","AWS Global Accelerator para resolver los nombres y AWS VPN para entregar el contenido.","AWS Transit Gateway para la entrega y AWS PrivateLink para la resolución de nombres."],correctAnswer:0,explanation:"La entrega de contenido cercana al usuario corresponde a la red de entrega de contenido y la traducción de nombres al servicio de DNS. Las demás opciones cruzan funciones: la red virtual aísla recursos, la conexión dedicada y la VPN enlazan redes, y el concentrador y el acceso privado interconectan redes o servicios. Si el requisito fuera aislar la aplicación en una red propia con subredes, la respuesta sería la red virtual.",porQueOpcion:["Correcta: Amazon CloudFront entrega las imágenes y vídeos estáticos en el borde y Amazon Route 53 resuelve el nombre hacia el destino activo.","Incorrecta: Amazon VPC no entrega contenido y AWS Direct Connect no resuelve nombres de dominio.","Incorrecta: AWS Global Accelerator no resuelve nombres y AWS VPN no entrega contenido.","Incorrecta: AWS Transit Gateway interconecta redes y AWS PrivateLink publica servicios; ninguno entrega contenido ni resuelve DNS."],fuentes:["https://docs.aws.amazon.com/AmazonCloudFront/latest/DeveloperGuide/Introduction.html","https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html","https://docs.aws.amazon.com/directconnect/latest/UserGuide/Welcome.html","https://docs.aws.amazon.com/global-accelerator/latest/dg/what-is-global-accelerator.html","https://docs.aws.amazon.com/vpn/","https://docs.aws.amazon.com/vpc/latest/tgw/what-is-transit-gateway.html","https://docs.aws.amazon.com/vpc/latest/privatelink/what-is-privatelink.html","https://docs.aws.amazon.com/Route53/latest/DeveloperGuide/Welcome.html"]},{id:"3.5-q12",taskId:"3.5",objetivos:["3.5#4"],tipo:"comparacion",question:"Un equipo compara dos piezas de su arquitectura de red: una traduce nombres de dominio a direcciones y otra cachea contenido en ubicaciones cercanas al usuario para reducir la latencia. ¿Qué afirmación distingue correctamente ambas funciones?",options:["El DNS resuelve nombres y dirige el tráfico; la red de entrega de contenido cachea y sirve el contenido desde ubicaciones cercanas.","El DNS almacena y sirve el contenido estático a los usuarios; la red de entrega de contenido resuelve los nombres de dominio y aplica políticas de latencia.","Ambas piezas son equivalentes y solo se diferencian en el precio de las consultas DNS.","El DNS reparte las conexiones entre instancias y la red de entrega de contenido emite los certificados."],correctAnswer:0,explanation:"La traducción de nombres y el direccionamiento del tráfico corresponden al servicio de DNS, mientras que cachear y servir el contenido desde ubicaciones de borde corresponde a la red de entrega de contenido. Las opciones que intercambian esas funciones o las igualan son incorrectas. Si el escenario pidiera además desviar el tráfico a un destino secundario cuando el principal falla, seguiría siendo el DNS con comprobaciones de estado y failover.",porQueOpcion:["Correcta: el DNS resuelve nombres y dirige el tráfico, y la red de entrega de contenido cachea y sirve el contenido desde ubicaciones cercanas.","Incorrecta: intercambia las funciones, el DNS no sirve contenido ni la red de entrega resuelve nombres de dominio.","Incorrecta: no son equivalentes, cumplen funciones distintas en la arquitectura.","Incorrecta: el DNS no reparte conexiones entre instancias ni la red de entrega emite certificados."],fuentes:["https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html"]},{id:"3.5-q13",taskId:"3.5",objetivos:["3.5#3"],tipo:"escenario",question:"Un equipo necesita bloquear una subred completa ante un rango de direcciones malicioso y, además, permitir solo un puerto concreto hacia una instancia. ¿Qué combinación de controles debe aplicar?",options:["Un network ACL en la subred con una regla de denegación y un security group en la instancia que permita solo el puerto necesario.","Un security group en la subred que deniegue el rango y otro security group en la instancia con todas las reglas abiertas y sin admisión de reglas de denegación.","Un network ACL con reglas solo de permiso y sin evaluación por número de regla sobre la subred.","Un grupo de seguridad que cifre el tráfico y audite los cambios de configuración de la subred."],correctAnswer:0,explanation:"La denegación de un rango a nivel de subred exige un network ACL, que admite reglas de permiso y denegación, mientras que el control del puerto concreto sobre la instancia lo aporta el security group. Los security groups no admiten reglas de denegación ni se asocian a la subred. Si el objetivo fuera únicamente limitar el tráfico de entrada a la instancia, bastaría con el security group correspondiente.",porQueOpcion:["Correcta: el network ACL deniega el rango a nivel de subred y el security group limita la instancia al puerto necesario.","Incorrecta: los security groups se asocian a recursos, no a subredes, y no admiten reglas de denegación.","Incorrecta: un network ACL solo con reglas de permiso no puede denegar el rango malicioso.","Incorrecta: un security group no cifra el tráfico ni audita los cambios de configuración de la subred."],fuentes:["https://docs.aws.amazon.com/vpc/latest/userguide/what-is-amazon-vpc.html"]}],3.6:[{id:"3.6-q1",taskId:"3.6",objetivos:["3.6#1"],tipo:"conocimiento",question:"¿Qué describe correctamente el modelo de almacenamiento de objetos frente al de bloque y al de archivos?",options:["El de objetos expone un disco con sectores que el sistema operativo formatea y monta como volumen.","El de objetos guarda datos completos accesibles por API, con metadatos y sin edición parcial.","El de archivos solo permite una instancia conectada a la vez y no se comparte por red.","El de bloque está pensado para contenido estático servido directamente a internet por API."],correctAnswer:1,explanation:"El almacenamiento de objetos trata cada dato como una unidad completa con metadatos, accesible por API y sin edición por bloques. El modelo de bloque expone un volumen tipo disco para las instancias y el de archivos ofrece un sistema de archivos compartido por red. Si el requisito fuera un disco persistente para una instancia, el modelo correcto sería el de bloque.",porQueOpcion:["Incorrecta: describir un disco con sectores que se formatea y monta corresponde al almacenamiento en bloque, no al de objetos.","Correcta: el almacenamiento de objetos guarda cada dato completo accesible por API, con metadatos y sin edición parcial.","Incorrecta: el almacenamiento de archivos se comparte por red entre varias instancias, no se limita a una.","Incorrecta: el almacenamiento en bloque expone un volumen tipo disco, no sirve contenido estático por API."],fuentes:["https://docs.aws.amazon.com/s3/"]},{id:"3.6-q2",taskId:"3.6",objetivos:["3.6#2"],tipo:"comparacion",question:"Un equipo debe elegir dónde guardar tres cosas: imágenes servidas por una API, el volumen de una base de datos y archivos compartidos entre varias instancias Linux. ¿Qué asignación es correcta?",options:["Imágenes en bloque, base de datos en objetos y archivos compartidos en caché.","Imágenes en objetos, base de datos en bloque y archivos compartidos en archivos.","Todo en almacenamiento en bloque para simplificar la operación.","Imágenes en archivos, base de datos en objetos y archivos compartidos en bloque."],correctAnswer:1,explanation:"Las imágenes servidas por API encajan en almacenamiento de objetos; el volumen de una base de datos es almacenamiento en bloque por su semántica de disco; y los archivos compartidos entre varias instancias Linux corresponden a un sistema de archivos de red. Si el requisito fuera solo servir contenido estático por API, bastaría con el almacenamiento de objetos.",porQueOpcion:["Incorrecta: asigna cada dato al modelo equivocado, las imágenes no van en bloque ni la base de datos en objetos.","Correcta: las imágenes servidas por API van en objetos, el volumen de la base de datos en bloque y los archivos compartidos en archivos.","Incorrecta: el bloque no es adecuado para imágenes servidas por API ni para archivos compartidos entre instancias.","Incorrecta: las imágenes no van en archivos ni la base de datos en objetos."],fuentes:["https://docs.aws.amazon.com/s3/"]},{id:"3.6-q3",taskId:"3.6",objetivos:["3.6#2"],tipo:"escenario",question:"Una empresa sube documentos que deben conservarse íntegros durante años y casi nunca se leen. Quiere el menor coste posible sin perderlos, aunque cambie de herramientas de edición cada temporada. ¿Qué enfoque es correcto?",options:["Guardarlos como objetos y moverlos con una política de ciclo de vida a clases más frías.","Guardarlos en el instance store local de una instancia para abaratar el almacenamiento.","Montarlos como disco de instancia y programar snapshots automáticos cada hora.","Dejarlos en la clase de acceso más rápido para evitar recargos por recuperación."],correctAnswer:0,explanation:"El almacenamiento de objetos con una política de ciclo de vida es el patrón correcto: los documentos se conservan y se transicionan a clases más baratas cuando dejan de consultarse. El instance store es efímero y el bloque no es el modelo pensado para archivos completos servidos por API. Si el escenario pidiera edición parcial por bloques, el modelo de objetos dejaría de ser adecuado.",porQueOpcion:["Correcta: guardarlos como objetos y moverlos con una política de ciclo de vida a clases más frías reduce el coste sin perderlos.","Incorrecta: el instance store es efímero y se pierde al detener la instancia, por lo que no garantiza la conservación.","Incorrecta: el instance store es efímero y los snapshots no sustituyen una conservación a largo plazo de bajo coste.","Incorrecta: la clase de acceso más rápido es la más cara y no conviene para datos que casi no se leen."],fuentes:["https://docs.aws.amazon.com/s3/"]},{id:"3.6-q4",taskId:"3.6",objetivos:["3.6#3"],tipo:"comparacion",question:"¿Qué distingue a las clases de almacenamiento de objetos entre sí?",options:["Solo cambian de nombre comercial; el precio por gigabyte almacenado y el comportamiento de acceso son idénticos en todas las clases que ofrece el servicio, por lo que la elección no afecta al coste.","Cambian el modelo de acceso y el coste: unas priorizan acceso inmediato y otras abaratan el almacenamiento a cambio de menor disponibilidad o de tiempo de recuperación.","Cambian el motor de base de datos subyacente y el lenguaje de consultas que admiten, pero no el coste ni la latencia de recuperación.","Cambian el cifrado que se puede aplicar a los objetos y el tamaño máximo permitido por archivo, y no el tiempo de recuperación."],correctAnswer:1,explanation:"Las clases de Amazon S3 intercambian coste por latencia, disponibilidad y tiempo de recuperación. Las de acceso inmediato sirven datos calientes y las de archivado abaratan el almacenamiento de datos fríos a cambio de una recuperación más lenta. Si el escenario tuviera un patrón de acceso desconocido, una clase que mueva los objetos automáticamente sería la opción más segura.",porQueOpcion:["Incorrecta: las clases difieren en precio por gigabyte y en comportamiento de acceso, no solo en el nombre.","Correcta: las clases cambian el modelo de acceso y el coste, unas priorizan acceso inmediato y otras abaratan a cambio de menor disponibilidad o mayor tiempo de recuperación.","Incorrecta: las clases no cambian el motor de base de datos ni el lenguaje de consultas que admiten.","Incorrecta: el tamaño máximo por objeto no define las clases y el tiempo de recuperación sí varía entre ellas."],fuentes:["https://docs.aws.amazon.com/s3/"]},{id:"3.6-q5",taskId:"3.6",objetivos:["3.6#3"],tipo:"escenario",question:"Una aplicación genera registros que se consultan a diario durante una semana y luego deben conservarse un año con acceso casi nulo. No importa el formato de los ficheros y la factura mensual de almacenamiento debe mantenerse baja. ¿Qué configuración es correcta?",options:["Dejarlo todo en la clase de acceso frecuente durante el año y no definir ninguna regla de ciclo de vida.","Empezar en la clase de acceso frecuente, transicionar a una clase de acceso poco frecuente y archivar al final con una política de ciclo de vida.","Empezar directamente en la clase Amazon S3 Glacier Deep Archive y consultar cada día desde esa misma clase de recuperación lenta.","Guardar los registros en un volumen de bloque de una instancia y borrarlos a la semana para ahorrar espacio."],correctAnswer:1,explanation:"La política de ciclo de vida va moviendo los objetos según envejecen: acceso frecuente mientras se consultan, acceso poco frecuente después y archivado cuando el acceso es casi nulo. Empezar en archivado encarecería las consultas diarias. Si el escenario pidiera acceso diario durante todo el año, no convendría ninguna clase de archivado.",porQueOpcion:["Incorrecta: dejarlo todo en acceso frecuente durante el año y sin ciclo de vida desaprovecha el ahorro para el acceso casi nulo.","Correcta: empezar en acceso frecuente, transicionar a una clase de acceso poco frecuente y archivar al final con una política de ciclo de vida ajusta el coste a cada fase.","Incorrecta: empezar en Amazon S3 Glacier Deep Archive encarece las consultas de recuperación lenta y no conviene para un acceso diario durante la primera semana.","Incorrecta: un volumen de bloque no es el modelo adecuado y borrar a la semana no conserva el año requerido."],fuentes:["https://docs.aws.amazon.com/amazonglacier/latest/dev/introduction.html"]},{id:"3.6-q6",taskId:"3.6",objetivos:["3.6#4"],tipo:"comparacion",question:"¿Qué diferencia hay entre un volumen de bloque persistente de red y el almacenamiento local efímero del host de una instancia?",options:["El almacenamiento local del host es persistente y se conserva al detener la instancia, y el volumen de red es efímero y se pierde al reiniciar.","Amazon EBS es almacenamiento en bloque persistente de red; el instance store es almacenamiento local efímero que se pierde al detener la instancia.","Ambos son almacenamiento de objetos accesible por API y se facturan por operaciones de lectura y escritura.","Ambos se comparten por red entre varias instancias a la vez como un sistema de archivos compartido."],correctAnswer:1,explanation:"Amazon EBS es un volumen de bloque persistente asociado a la instancia, con snapshots y cifrado. El instance store es almacenamiento local del host, más rápido pero efímero: sus datos desaparecen al detener, mover o terminar la instancia. Si el objetivo fuera la máxima velocidad para datos reconstruibles, la opción local sería la adecuada.",porQueOpcion:["Incorrecta: invierte las propiedades, el instance store es efímero y el volumen de red persiste.","Correcta: Amazon EBS es almacenamiento en bloque persistente de red y el instance store es almacenamiento local efímero que se pierde al detener la instancia.","Incorrecta: ninguno es almacenamiento de objetos ni se factura por operaciones de API.","Incorrecta: EBS se asocia a una instancia y el instance store es local, no un sistema de archivos compartido."],fuentes:["https://docs.aws.amazon.com/ebs/"]},{id:"3.6-q7",taskId:"3.6",objetivos:["3.6#4"],tipo:"tradeoff",question:"Una instancia necesita la máxima velocidad para una caché temporal que se puede reconstruir, pero también un volumen para datos que deben sobrevivir. ¿Qué compromiso es correcto?",options:["Usar solo el almacenamiento local efímero para ambos, tanto la caché temporal como los datos que deben sobrevivir a la instancia.","Usar solo Amazon EBS para ambos, tanto para la caché de máxima velocidad como para los datos persistentes.","Usar instance store para la caché reconstruible y Amazon EBS para los datos persistentes.","Guardar ambos datos en un bucket de objetos y montarlo como disco en la instancia."],correctAnswer:2,explanation:"El tradeoff es rendimiento frente a persistencia: el instance store es la opción más rápida para datos temporales reconstruibles, mientras que Amazon EBS aporta persistencia, snapshots y cifrado para los datos que no se pueden perder. Si el requisito fuera únicamente persistencia y no velocidad, bastaría con Amazon EBS para ambos.",porQueOpcion:["Incorrecta: el instance store es efímero y no sirve para datos que deben sobrevivir a la instancia.","Incorrecta: EBS no ofrece la máxima velocidad del almacenamiento local para la caché reconstruible.","Correcta: usar instance store para la caché reconstruible y Amazon EBS para los datos persistentes equilibra velocidad y persistencia.","Incorrecta: un bucket de objetos no se monta como disco con la semántica de bloque requerida."],fuentes:["https://docs.aws.amazon.com/ebs/"]},{id:"3.6-q8",taskId:"3.6",objetivos:["3.6#5"],tipo:"conocimiento",question:"Una empresa necesita un sistema de archivos compartido y elástico para aplicaciones Linux en varias instancias y, por separado, un sistema de archivos gestionado para Windows. ¿Qué servicios corresponden?",options:["Amazon S3 para Linux y Amazon EBS para las instancias con Windows.","Amazon EFS para Linux y Amazon FSx para Windows.","AWS Storage Gateway para ambos casos.","Amazon EBS para ambos casos."],correctAnswer:1,explanation:"Amazon EFS es el sistema de archivos compartido y elástico para Linux, y Amazon FSx cubre sistemas de archivos gestionados para motores concretos, como Windows File Server. Si el requisito fuera solo un disco para una única instancia, bastaría con un volumen de bloque.",porQueOpcion:["Incorrecta: Amazon S3 es de objetos y Amazon EBS de bloque; ninguno es el sistema de archivos para esos casos.","Correcta: Amazon EFS es el sistema de archivos compartido y elástico para Linux y Amazon FSx cubre sistemas gestionados como Windows File Server.","Incorrecta: AWS Storage Gateway es la pieza híbrida, no el sistema de archivos gestionado para cada caso.","Incorrecta: Amazon EBS es un volumen de bloque para una instancia, no un sistema de archivos compartido."],fuentes:["https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/ebs/","https://docs.aws.amazon.com/efs/","https://docs.aws.amazon.com/fsx/","https://docs.aws.amazon.com/storagegateway/"]},{id:"3.6-q9",taskId:"3.6",objetivos:["3.6#5","3.6#6"],tipo:"comparacion",question:"¿Qué distingue a los sistemas de archivos gestionados en la nube de una puerta de enlace híbrida con caché?",options:["Los tres son servicios de almacenamiento de objetos y se facturan por gigabyte almacenado y por operaciones de API, sin ofrecer sistemas de archivos compartidos ni caché local para el entorno local de la empresa.","Amazon EFS y Amazon FSx son sistemas de archivos gestionados en AWS; AWS Storage Gateway es una puerta de enlace híbrida que da acceso con caché local a datos almacenados en AWS.","AWS Storage Gateway es un sistema de archivos gestionado y Amazon EFS es la puerta de enlace híbrida con caché local.","Solo se diferencian en la región donde se despliegan, en el cifrado que aplican a los datos en reposo y en el tamaño máximo de archivo permitido por cada servicio."],correctAnswer:1,explanation:"Amazon EFS y Amazon FSx alojan sistemas de archivos gestionados en AWS para consumirse desde las instancias. AWS Storage Gateway es la pieza híbrida: mantiene una caché local de los datos de acceso reciente y sirve el resto bajo demanda desde el almacenamiento en AWS. Si el escenario tuviera las aplicaciones ya en AWS y solo necesitara archivos compartidos, la puerta de enlace no sería necesaria.",porQueOpcion:["Incorrecta: EFS, FSx y Storage Gateway no son servicios de objetos ni se facturan por gigabyte y operaciones de API.","Correcta: Amazon EFS y Amazon FSx son sistemas de archivos gestionados en AWS y AWS Storage Gateway es la puerta de enlace híbrida que da acceso con caché local.","Incorrecta: intercambia los papeles, Storage Gateway no es el sistema de archivos gestionado ni EFS la puerta de enlace.","Incorrecta: no se diferencian solo por región, cifrado o tamaño de archivo, sino por su naturaleza gestionada o híbrida."],fuentes:["https://docs.aws.amazon.com/efs/","https://docs.aws.amazon.com/fsx/","https://docs.aws.amazon.com/storagegateway/"]},{id:"3.6-q10",taskId:"3.6",objetivos:["3.6#6"],tipo:"escenario",question:"Una empresa quiere mantener sus aplicaciones en la oficina, que deben seguir leyendo archivos con baja latencia, mientras el dato real se conserva en AWS. No quiere reescribir las aplicaciones ni mover todo el almacenamiento de golpe. ¿Qué servicio encaja mejor?",options:["AWS Storage Gateway, que expone una puerta de enlace con caché local y guarda el dato en AWS.","Amazon S3, para que las aplicaciones locales accedan directamente a los objetos por API sin puerta de enlace.","Amazon EFS, para montar el mismo sistema de archivos en las máquinas locales.","AWS Backup, para copiar los archivos locales a la nube cada noche."],correctAnswer:0,explanation:"Storage Gateway es la pieza híbrida: da acceso local con caché a datos que residen en AWS, sin reescribir las aplicaciones. Amazon S3 exigiría cambiar el acceso a la API, Amazon EFS está pensado para instancias en AWS (no para montar en la oficina) y AWS Backup solo copia, no sirve lecturas locales. Si el escenario pidiera acceso desde instancias ya desplegadas en AWS, la respuesta sería Amazon EFS.",porQueOpcion:["Correcta: AWS Storage Gateway expone una puerta de enlace con caché local y conserva el dato en AWS sin reescribir las aplicaciones.","Incorrecta: Amazon S3 exigiría cambiar el acceso de las aplicaciones locales a la API.","Incorrecta: Amazon EFS está pensado para instancias en AWS, no para montarlo en las máquinas de la oficina.","Incorrecta: AWS Backup solo copia, no sirve lecturas locales con baja latencia."],fuentes:["https://docs.aws.amazon.com/storagegateway/","https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/efs/","https://docs.aws.amazon.com/aws-backup/"]},{id:"3.6-q11",taskId:"3.6",objetivos:["3.6#7"],tipo:"casoDeUso",question:"Una empresa almacena en Amazon S3 millones de objetos cuya frecuencia de acceso baja con el tiempo. Quiere reducir costes de forma automática y sin intervención manual. ¿Qué debe usar?",options:["Una política de ciclo de vida que transicione los objetos entre clases y los expire.","Un volumen de Amazon EBS de mayor tamaño para guardar los objetos y moverlos manualmente entre clases.","Snapshots manuales cada semana de los volúmenes donde residen los objetos almacenados.","Un sistema de archivos Amazon FSx compartido que reorganice los objetos por antigüedad."],correctAnswer:0,explanation:"La política de ciclo de vida automatiza el movimiento de objetos entre clases de almacenamiento y su expiración, bajando el coste sin operación manual. Los snapshots y los sistemas de archivos no resuelven la optimización por antigüedad de objetos. Si el requisito fuera conservar copias recuperables del dato, haría falta un mecanismo de copia de seguridad y no solo una transición de clase.",porQueOpcion:["Correcta: una política de ciclo de vida transiciona los objetos entre clases y los expira de forma automática, bajando el coste sin operación manual.","Incorrecta: un volumen de Amazon EBS no almacena los objetos de S3 ni automatiza las transiciones entre clases.","Incorrecta: los snapshots de volúmenes no aplican a los objetos de S3 ni optimizan por antigüedad.","Incorrecta: un sistema de archivos Amazon FSx no reorganiza los objetos de S3 por antigüedad."],fuentes:["https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/ebs/","https://docs.aws.amazon.com/fsx/"]},{id:"3.6-q12",taskId:"3.6",objetivos:["3.6#8"],tipo:"conocimiento",question:"¿Qué aporta un servicio centralizado de copias de seguridad en una estrategia de protección de datos?",options:["Mueve automáticamente los objetos fríos a clases de almacenamiento más baratas según su antigüedad y su patrón de acceso.","Centraliza y automatiza las copias de seguridad de varios servicios con políticas y retención definidas.","Sustituye a las políticas de ciclo de vida y mueve los objetos a clases de archivado profundo.","Reemplaza el cifrado de los volúmenes por un cifrado gestionado propio del servicio de copias."],correctAnswer:1,explanation:"AWS Backup define, programa y supervisa copias de seguridad de varios servicios, como volúmenes de Amazon EBS y sistemas de archivos Amazon EFS y Amazon FSx, con políticas y retención. No sustituye al ciclo de vida ni al cifrado. Si el objetivo fuera abaratar el dato frío y no protegerlo, la herramienta adecuada sería la política de ciclo de vida.",porQueOpcion:["Incorrecta: mover objetos fríos a clases más baratas según su antigüedad es la política de ciclo de vida, no una copia de seguridad.","Correcta: un servicio centralizado de copias define, programa y supervisa copias de varios servicios con políticas y retención.","Incorrecta: el servicio de copias no sustituye a las políticas de ciclo de vida ni mueve objetos a archivado profundo.","Incorrecta: el servicio de copias no reemplaza el cifrado de los volúmenes por uno propio."],fuentes:["https://docs.aws.amazon.com/aws-backup/","https://docs.aws.amazon.com/ebs/","https://docs.aws.amazon.com/efs/","https://docs.aws.amazon.com/fsx/"]},{id:"3.6-q13",taskId:"3.6",objetivos:["3.6#7","3.6#8"],tipo:"comparacion",question:"Un equipo compara dos mecanismos sobre el mismo dato almacenado en la nube: uno que mueve o elimina los objetos según su antigüedad y otro que crea copias recuperables con retención. ¿Qué afirmación los distingue correctamente?",options:["La política de ciclo de vida optimiza el coste moviendo o expirando objetos; las copias de seguridad crean versiones recuperables con retención.","Las copias de seguridad son las que mueven los objetos entre clases de almacenamiento y la política de ciclo de vida crea las copias recuperables.","Ambos mecanismos son lo mismo: mover un objeto a una clase fría ya equivale a tener una copia de seguridad.","La política de ciclo de vida solo se aplica a volúmenes de bloque y las copias solo a sistemas de archivos."],correctAnswer:0,explanation:"El ciclo de vida optimiza el coste del dato activo moviéndolo entre clases o expirándolo, mientras que la copia de seguridad protege contra pérdida o corrupción con una retención definida. Mover un objeto a una clase fría no crea una copia independiente. Si el escenario exigiera recuperarse de un borrado accidental, el mecanismo imprescindible sería la copia de seguridad.",porQueOpcion:["Correcta: la política de ciclo de vida optimiza el coste moviendo o expirando objetos, mientras que las copias de seguridad crean versiones recuperables con retención.","Incorrecta: intercambia los mecanismos, las copias de seguridad no mueven objetos entre clases de almacenamiento.","Incorrecta: mover un objeto a una clase fría no crea una copia de seguridad independiente.","Incorrecta: el ciclo de vida se aplica a objetos y las copias a varios servicios, no se reparten como se indica."],fuentes:["https://docs.aws.amazon.com/s3/"]},{id:"3.6-q14",taskId:"3.6",objetivos:["3.6#1"],tipo:"casoDeUso",question:"Una empresa necesita almacenar millones de archivos de imágenes y documentos, servirlos por API y conservar versiones anteriores de cada uno, sin dimensionar servidores ni discos. ¿Qué modelo de almacenamiento encaja mejor?",options:["Almacenamiento de objetos, que guarda cada dato completo con metadatos, lo expone por API y admite versionado.","Almacenamiento en bloque, que expone un disco que el sistema operativo formatea y monta en una instancia.","Almacenamiento en archivos, que comparte una jerarquía de rutas por red entre varias instancias.","Almacenamiento local efímero del host, que ofrece la máxima velocidad pero pierde los datos al detener la instancia y no admite versionado."],correctAnswer:0,explanation:"Los datos completos con metadatos, servidos por API, con versionado y sin límite práctico de escala son el caso típico del almacenamiento de objetos. El bloque y el archivo no exponen los datos como objetos y el almacenamiento local es efímero. Si el requisito cambiara a montar un disco con sistema de archivos en una instancia, habría que usar almacenamiento en bloque.",porQueOpcion:["Correcta: el almacenamiento de objetos guarda cada dato completo con metadatos, lo expone por API y admite versionado sin dimensionar servidores.","Incorrecta: el almacenamiento en bloque expone un disco que se monta en una instancia y no se sirve por API.","Incorrecta: el almacenamiento en archivos comparte una jerarquía de rutas por red y no es el modelo de objetos por API.","Incorrecta: el almacenamiento local efímero pierde los datos al detener la instancia y no admite versionado."],fuentes:["https://docs.aws.amazon.com/s3/"]},{id:"3.6-q15",taskId:"3.6",objetivos:["3.6#5"],tipo:"escenario",question:"Un clúster de varias instancias Linux necesita compartir el mismo conjunto de archivos, que crecerá y se reducirá según la carga, sin administrar un servidor de archivos propio. ¿Qué servicio encaja mejor?",options:["Un sistema de archivos de red elástico y gestionado para Linux, montado en todas las instancias a la vez.","Un volumen de bloque individual asociado a una sola instancia del clúster y no compartido por red.","Un contenedor de objetos con acceso por API desde cada instancia y sin jerarquía de archivos.","El almacenamiento local efímero del host de cada instancia, reconstruible tras cada reinicio y sin compartirse entre las instancias del clúster."],correctAnswer:0,explanation:"Un sistema de archivos compartido por red, gestionado y elástico es lo que permite a varias instancias Linux acceder al mismo conjunto de archivos con crecimiento automático. El bloque se asocia a una instancia, el objeto no ofrece jerarquía de archivos y el almacenamiento local es efímero. Si el escenario exigiera un motor de archivos concreto como Windows File Server, cambiaría el servicio elegido.",porQueOpcion:["Correcta: un sistema de archivos de red elástico y gestionado para Linux permite compartir el mismo conjunto de archivos entre todas las instancias.","Incorrecta: un volumen de bloque se asocia a una sola instancia del clúster y no se comparte por red.","Incorrecta: un contenedor de objetos no ofrece jerarquía de archivos para montarlo en el clúster.","Incorrecta: el almacenamiento local es efímero y no se comparte entre las instancias del clúster."],fuentes:["https://docs.aws.amazon.com/s3/"]},{id:"3.6-q16",taskId:"3.6",objetivos:["3.6#8"],tipo:"casoDeUso",question:"Una empresa necesita proteger volúmenes de bloque y sistemas de archivos frente a borrados accidentales, con copias programadas y una retención definida por cumplimiento en varios servicios. ¿Qué debe usar?",options:["Un servicio centralizado de copias de seguridad con planes, retención y almacén de respaldo.","Una política de ciclo de vida que mueva los datos a clases de almacenamiento más frías.","Snapshots manuales creados por cada equipo, sin una política de retención común ni supervisión centralizada.","El versionado de los objetos como única medida de protección frente a borrados y corrupción."],correctAnswer:0,explanation:"La protección frente a borrados y corrupción con retención y cumplimiento sobre varios servicios encaja con un servicio centralizado de copias de seguridad, que define planes y supervisa el almacén de respaldo. Una política de ciclo de vida solo abarata el dato frío y los snapshots manuales no aportan retención común. Si el objetivo fuera únicamente ahorrar coste en datos fríos, bastaría con la política de ciclo de vida.",porQueOpcion:["Correcta: un servicio centralizado de copias con planes, retención y almacén de respaldo protege varios servicios frente a borrados accidentales.","Incorrecta: una política de ciclo de vida solo abarata el dato frío y no crea copias recuperables con retención.","Incorrecta: los snapshots manuales sin retención común ni supervisión no cumplen el requisito de cumplimiento.","Incorrecta: el versionado de objetos no cubre volúmenes de bloque ni sistemas de archivos."],fuentes:["https://docs.aws.amazon.com/s3/"]}],3.7:[{id:"3.7-q1",taskId:"3.7",objetivos:["3.7#1"],tipo:"conocimiento",question:"¿Cuál de los siguientes servicios de AWS está diseñado específicamente para añadir inteligencia artificial a una aplicación que analiza imágenes?",options:["Amazon CloudWatch","Amazon Rekognition","AWS CloudTrail","Amazon Simple Storage Service (Amazon S3)"],correctAnswer:1,explanation:"Amazon Rekognition es un servicio de IA ya entrenado que analiza imágenes y vídeos. Amazon CloudWatch y AWS CloudTrail son servicios de gestión y gobernanza, y Amazon S3 es almacenamiento de objetos. Si el requisito fuera entrenar un modelo propio con datos específicos, el servicio sería la plataforma de aprendizaje automático.",porQueOpcion:["Incorrecta: Amazon CloudWatch es un servicio de gestión y supervisión, no analiza imágenes con IA.","Correcta: Amazon Rekognition es un servicio de IA ya entrenado que analiza imágenes y vídeos.","Incorrecta: AWS CloudTrail registra la actividad de la cuenta, no analiza imágenes.","Incorrecta: Amazon S3 es almacenamiento de objetos, no un servicio de análisis de imágenes."],fuentes:["https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/cloudwatch/","https://docs.aws.amazon.com/rekognition/","https://docs.aws.amazon.com/cloudtrail/"]},{id:"3.7-q2",taskId:"3.7",objetivos:["3.7#3"],tipo:"comparacion",question:"Un equipo quiere generar subtítulos a partir de grabaciones de audio y, en otro caso, convertir un texto en una locución de voz. ¿Qué servicio corresponde a cada tarea?",options:["Amazon Polly convierte el audio en texto y Amazon Transcribe convierte el texto en voz.","Amazon Comprehend convierte el audio en texto y Amazon Lex convierte el texto en voz.","Amazon Transcribe convierte el audio en texto y Amazon Polly convierte el texto en voz.","Ambos casos se resuelven con Amazon Translate."],correctAnswer:2,explanation:"Amazon Transcribe convierte voz en texto (speech-to-text) y Amazon Polly convierte texto en voz (text-to-speech). Comprehend analiza texto existente, Lex construye asistentes conversacionales y Translate traduce idiomas. Si cambia la dirección de la conversión —de texto a voz—, el servicio sería Amazon Polly.",porQueOpcion:["Incorrecta: invierte los servicios, Polly sintetiza voz y Transcribe convierte audio en texto.","Incorrecta: Comprehend analiza texto existente y Lex construye asistentes; ninguno convierte audio ni genera voz.","Correcta: Amazon Transcribe convierte el audio en texto y Amazon Polly convierte el texto en voz.","Incorrecta: Amazon Translate traduce idiomas y no realiza conversión de voz."],fuentes:["https://docs.aws.amazon.com/polly/","https://docs.aws.amazon.com/transcribe/","https://docs.aws.amazon.com/comprehend/","https://docs.aws.amazon.com/lex/","https://docs.aws.amazon.com/translate/"]},{id:"3.7-q3",taskId:"3.7",objetivos:["3.7#3"],tipo:"comparacion",question:"Una empresa recibe documentos escaneados y, además, correos en texto plano. Necesita extraer los campos de los documentos y detectar el sentimiento de los correos. ¿Qué servicios corresponden a cada tarea?",options:["Amazon Comprehend para extraer los datos de los documentos y Amazon Textract para el sentimiento.","Amazon Transcribe para los documentos y Amazon Polly para los correos.","Amazon Textract para extraer datos de los documentos y Amazon Comprehend para analizar el sentimiento de los correos.","Amazon Lex para ambos casos."],correctAnswer:2,explanation:"Amazon Textract extrae texto, formularios y tablas de documentos escaneados o imágenes, mientras que Amazon Comprehend interpreta lenguaje natural sobre texto ya digital, como el sentimiento. Transcribe y Polly trabajan con voz, y Lex crea asistentes conversacionales. Si el escenario pidiera extraer campos de formularios escaneados, el servicio sería Amazon Textract.",porQueOpcion:["Incorrecta: intercambia las tareas, Comprehend no extrae campos de documentos ni Textract analiza sentimiento.","Incorrecta: Transcribe y Polly trabajan con voz, no con documentos ni sentimiento.","Correcta: Amazon Textract extrae datos de los documentos y Amazon Comprehend analiza el sentimiento de los correos.","Incorrecta: Amazon Lex construye asistentes conversacionales y no resuelve ninguna de las dos tareas."],fuentes:["https://docs.aws.amazon.com/comprehend/","https://docs.aws.amazon.com/textract/","https://docs.aws.amazon.com/transcribe/","https://docs.aws.amazon.com/polly/","https://docs.aws.amazon.com/lex/"]},{id:"3.7-q4",taskId:"3.7",objetivos:["3.7#3"],tipo:"comparacion",question:"Un equipo necesita un modelo propio entrenado con sus datos históricos. ¿Qué opción describe correctamente la diferencia entre una plataforma para construir modelos y los servicios de IA ya entrenados?",options:["Amazon SageMaker AI ofrece APIs listas para tareas concretas de imagen y voz, y los servicios de IA ya entrenados son los que permiten entrenar modelos propios.","Amazon SageMaker AI permite construir, entrenar y desplegar modelos propios; los servicios de IA ya entrenados resuelven una tarea concreta sin entrenar un modelo.","Ambos son equivalentes: Amazon SageMaker AI es solo el nombre comercial nuevo de los servicios de IA ya entrenados que existen desde siempre.","Amazon SageMaker AI solo sirve para almacenar y consultar datos, y los servicios de IA ya entrenados para generar las APIs de inferencia."],correctAnswer:1,explanation:"Amazon SageMaker AI es la plataforma para construir el ciclo completo de un modelo propio: preparar datos, entrenar, ajustar y desplegar. Los servicios de IA ya entrenados exponen una tarea resuelta como API y no requieren entrenamiento. Si el objetivo fuera una tarea estándar, bastaría con un servicio de IA ya entrenado.",porQueOpcion:["Incorrecta: intercambia los conceptos, SageMaker es la plataforma y los servicios ya entrenados resuelven tareas concretas.","Correcta: Amazon SageMaker AI construye, entrena y despliega modelos propios, y los servicios de IA ya entrenados resuelven una tarea concreta sin entrenar.","Incorrecta: no son equivalentes, SageMaker AI es una plataforma de modelos propios distinta de los servicios ya entrenados.","Incorrecta: SageMaker AI no es solo almacenar datos y los servicios ya entrenados no generan las APIs de inferencia."],fuentes:["https://docs.aws.amazon.com/sagemaker/"]},{id:"3.7-q5",taskId:"3.7",objetivos:["3.7#3"],tipo:"escenario",question:"Un banco quiere un asistente virtual que entienda preguntas en lenguaje natural y responda conversando con el cliente. ¿Qué servicio se ajusta mejor?",options:["Amazon Polly","Amazon Textract","Amazon Translate","Amazon Lex"],correctAnswer:3,explanation:"Amazon Lex es el servicio de IA ya entrenado para construir asistentes conversacionales: comprende el lenguaje natural del usuario y gestiona el diálogo. Polly solo convierte texto en voz, Textract extrae texto de documentos y Translate traduce idiomas. Si el objetivo fuera generar voz a partir de texto, el servicio sería Amazon Polly.",porQueOpcion:["Incorrecta: Amazon Polly solo convierte texto en voz y no mantiene una conversación.","Incorrecta: Amazon Textract extrae texto de documentos y no construye asistentes conversacionales.","Incorrecta: Amazon Translate traduce idiomas y no gestiona el diálogo con el cliente.","Correcta: Amazon Lex construye asistentes conversacionales que comprenden el lenguaje natural y gestionan el diálogo."],fuentes:["https://docs.aws.amazon.com/polly/","https://docs.aws.amazon.com/textract/","https://docs.aws.amazon.com/translate/","https://docs.aws.amazon.com/lex/"]},{id:"3.7-q6",taskId:"3.7",objetivos:["3.7#3"],tipo:"servicio",question:"¿Qué tarea resuelve un servicio de IA ya entrenado que trabaja con imágenes y vídeo?",options:["Convertir texto escrito en voz sintetizada para generar locuciones y audio.","Analizar imágenes y vídeos, por ejemplo para detectar objetos, caras o contenido inapropiado.","Traducir texto entre idiomas manteniendo el significado y el tono del original.","Transcribir llamadas y reuniones de voz a texto para su revisión posterior."],correctAnswer:1,explanation:"Amazon Rekognition analiza imágenes y vídeos para detectar objetos, caras, texto o contenido inapropiado. Convertir texto en voz es Amazon Polly, traducir es Amazon Translate y transcribir voz es Amazon Transcribe. Si el escenario pidiera transcribir audio, el servicio sería Amazon Transcribe.",porQueOpcion:["Incorrecta: convertir texto en voz sintetizada es Amazon Polly, no la tarea de análisis de imágenes.","Correcta: analizar imágenes y vídeos, por ejemplo para detectar objetos, caras o contenido inapropiado, es la tarea de Amazon Rekognition.","Incorrecta: traducir texto entre idiomas es Amazon Translate.","Incorrecta: transcribir voz a texto es Amazon Transcribe."],fuentes:["https://docs.aws.amazon.com/polly/","https://docs.aws.amazon.com/rekognition/","https://docs.aws.amazon.com/translate/","https://docs.aws.amazon.com/transcribe/"]},{id:"3.7-q7",taskId:"3.7",objetivos:["3.7#3"],tipo:"tradeoff",question:"Tu equipo duda entre usar un servicio de IA ya entrenado o construir un modelo propio con una plataforma de aprendizaje automático. ¿Qué criterio es correcto?",options:["Si la tarea es estándar conviene un servicio ya entrenado; si necesitas un modelo propio con tus datos y control del entrenamiento, la plataforma de aprendizaje automático.","Siempre hay que entrenar un modelo propio desde cero, aunque exista un servicio ya entrenado que resuelva exactamente esa misma tarea estándar, sin necesidad de datos etiquetados propios ni de controlar el algoritmo.","Los servicios ya entrenados permiten entrenar desde cero con datos propios, ajustar hiperparámetros, evaluar el modelo y desplegarlo, además de controlar el algoritmo empleado.","La plataforma de aprendizaje automático solo se usa cuando no hay ningún dato disponible para el problema planteado y se busca un resultado inmediato sin equipo de ciencia de datos."],correctAnswer:0,explanation:"El criterio equilibra esfuerzo y necesidad: para una tarea estándar, el servicio ya entrenado evita entrenar y mantener un modelo; para un modelo propio con datos específicos y control del entrenamiento, se usa una plataforma de aprendizaje automático. Si el objetivo fuera una tarea estándar sin datos propios, bastaría con un servicio ya entrenado.",porQueOpcion:["Correcta: un servicio ya entrenado conviene para tareas estándar y la plataforma de aprendizaje automático para un modelo propio con control del entrenamiento.","Incorrecta: no siempre hay que entrenar desde cero si existe un servicio ya entrenado que resuelve esa tarea estándar.","Incorrecta: los servicios ya entrenados no permiten entrenar desde cero ni controlar el algoritmo.","Incorrecta: la plataforma de aprendizaje automático se usa para modelos propios con datos, no solo cuando faltan por completo."],fuentes:["https://docs.aws.amazon.com/s3/"]},{id:"3.7-q8",taskId:"3.7",objetivos:["3.7#4"],tipo:"comparacion",question:"Un equipo tiene datos históricos almacenados en la nube que quiere consultar con SQL y, en paralelo, recibe un flujo continuo de eventos que debe procesar en tiempo real. ¿Qué servicios corresponden?",options:["Amazon Kinesis para consultar con SQL los datos históricos almacenados y Amazon Athena para el flujo de eventos en tiempo real.","Amazon Athena para consultar con SQL los datos en Amazon S3 y Amazon Kinesis para ingerir y procesar el flujo en tiempo real.","AWS Glue para consultar con SQL los datos históricos y Amazon Quick Sight para ingerir y procesar el flujo en tiempo real.","Amazon Redshift para ingerir el flujo continuo en tiempo real y AWS Glue para consultar los datos almacenados."],correctAnswer:1,explanation:"Amazon Athena consulta con SQL datos ya almacenados, por ejemplo en Amazon S3, sin administrar servidores; Amazon Kinesis ingiere y procesa datos en streaming en tiempo real. Glue prepara y cataloga, Quick Sight visualiza y Redshift es un almacén analítico. Si el requisito fuera solo consultar el histórico con SQL, bastaría con Amazon Athena.",porQueOpcion:["Incorrecta: intercambia los servicios, Kinesis procesa streaming y Athena consulta datos almacenados.","Correcta: Amazon Athena consulta con SQL los datos en Amazon S3 y Amazon Kinesis ingiere y procesa el flujo en tiempo real.","Incorrecta: Glue prepara y cataloga datos y Quick Sight visualiza; ninguno consulta SQL ni procesa streaming.","Incorrecta: Redshift es un almacén analítico y Glue prepara datos, no cubren esas tareas como se indica."],fuentes:["https://docs.aws.amazon.com/kinesis/","https://docs.aws.amazon.com/athena/","https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/glue/","https://docs.aws.amazon.com/quicksight/","https://docs.aws.amazon.com/redshift/"]},{id:"3.7-q9",taskId:"3.7",objetivos:["3.7#4"],tipo:"escenario",question:"Una empresa necesita preparar y transformar datos de varias fuentes antes de analizarlos, y llevar un catálogo central de esos datos. ¿Qué servicio de analítica encaja mejor?",options:["Amazon Polly, que transforma los datos en audio para escucharlos y catalogarlos después.","Amazon Lex, que prepara los datos conversacionales y construye el catálogo central de datos de la empresa.","AWS Artifact, que audita los datos y genera los informes de cumplimiento del catálogo.","AWS Glue, que cataloga los datos y ejecuta trabajos de extracción, transformación y carga (ETL)."],correctAnswer:3,explanation:"AWS Glue descubre y cataloga los datos y ejecuta trabajos ETL para dejarlos listos antes del análisis. Polly y Lex son servicios de IA, y AWS Artifact es un portal de documentación de cumplimiento. Si el requisito fuera procesar un flujo en tiempo real, el servicio sería Amazon Kinesis.",porQueOpcion:["Incorrecta: Amazon Polly convierte texto en voz y no prepara ni cataloga datos.","Incorrecta: Amazon Lex construye asistentes conversacionales y no ejecuta ETL ni catálogo.","Incorrecta: AWS Artifact es un portal de documentación de cumplimiento y no procesa datos.","Correcta: AWS Glue cataloga los datos y ejecuta trabajos de extracción, transformación y carga (ETL) para dejarlos listos antes del análisis."],fuentes:["https://docs.aws.amazon.com/polly/","https://docs.aws.amazon.com/lex/","https://docs.aws.amazon.com/artifact/","https://docs.aws.amazon.com/glue/","https://docs.aws.amazon.com/kinesis/"]},{id:"3.7-q10",taskId:"3.7",objetivos:["3.7#4"],tipo:"servicio",question:"Un analista de negocio quiere crear paneles interactivos con gráficos a partir de datos ya preparados, sin programar. ¿Qué servicio es el adecuado?",options:["Amazon Transcribe","AWS CloudTrail (registro de actividad de la cuenta)","Amazon Quick Sight","Amazon Aurora"],correctAnswer:2,explanation:"Amazon Quick Sight es el servicio de inteligencia de negocio para crear paneles y visualizaciones sin programar. Transcribe es voz a texto, CloudTrail registra actividad de la cuenta y Aurora es una base de datos relacional. Si el objetivo fuera procesar datos en streaming, el servicio sería Amazon Kinesis.",porQueOpcion:["Incorrecta: Amazon Transcribe convierte voz en texto y no crea paneles.","Incorrecta: AWS CloudTrail registra la actividad de la cuenta y no visualiza datos.","Correcta: Amazon Quick Sight es el servicio de inteligencia de negocio para crear paneles y visualizaciones sin programar.","Incorrecta: Amazon Aurora es una base de datos relacional y no una herramienta de paneles."],fuentes:["https://docs.aws.amazon.com/transcribe/","https://docs.aws.amazon.com/cloudtrail/","https://docs.aws.amazon.com/quicksight/","https://docs.aws.amazon.com/AmazonRDS/latest/AuroraUserGuide/CHAP_AuroraOverview.html","https://docs.aws.amazon.com/kinesis/"]},{id:"3.7-q11",taskId:"3.7",objetivos:["3.7#2"],tipo:"conocimiento",question:"¿Cuál de estos servicios pertenece a la categoría de analítica de AWS?",options:["Amazon Lex","Amazon Polly","AWS Shield Advanced (protección DDoS)","Amazon OpenSearch Service"],correctAnswer:3,explanation:"Amazon OpenSearch Service es un servicio de analítica para buscar y explorar registros y texto. Amazon Lex y Amazon Polly son servicios de IA, y AWS Shield es un servicio de seguridad. Si el requisito fuera analizar imágenes, el servicio pertenecería a la categoría de IA/ML.",porQueOpcion:["Incorrecta: Amazon Lex es un servicio de IA/ML, no de analítica.","Incorrecta: Amazon Polly es un servicio de IA/ML, no de analítica.","Incorrecta: AWS Shield Advanced pertenece a la categoría de seguridad.","Correcta: Amazon OpenSearch Service es un servicio de analítica para buscar y explorar registros y texto."],fuentes:["https://docs.aws.amazon.com/lex/","https://docs.aws.amazon.com/polly/","https://docs.aws.amazon.com/opensearch-service/","https://docs.aws.amazon.com/shield/"]},{id:"3.7-q12",taskId:"3.7",objetivos:["3.7#2"],tipo:"escenario",question:"Una empresa acumula terabytes de registros de aplicaciones y necesita buscar y analizar patrones en ellos casi en tiempo real, además de construir visualizaciones para el negocio. Aunque muchos campos de esos registros no se consultan nunca, el equipo es reducido y la latencia de búsqueda importa. ¿Qué combinación de servicios de analítica es la más adecuada?",options:["Amazon Textract para los registros y Amazon Polly para las visualizaciones.","Amazon OpenSearch Service para buscar y analizar los registros y Amazon Quick Sight para las visualizaciones.","Amazon Lex para los registros y Amazon Translate para las visualizaciones.","Amazon WorkSpaces para los registros y Amazon AppStream 2.0 para las visualizaciones."],correctAnswer:1,explanation:"Amazon OpenSearch Service está pensado para buscar y analizar registros y texto, y Amazon Quick Sight aporta los paneles y visualizaciones. Las demás opciones mezclan servicios de IA o de escritorio remoto que no cubren esas tareas. Si el escenario pidiera ingerir eventos en tiempo real, el servicio sería Amazon Kinesis.",porQueOpcion:["Incorrecta: Textract extrae texto de documentos y Polly genera voz; no analizan registros ni crean paneles.","Correcta: Amazon OpenSearch Service busca y analiza los registros y Amazon Quick Sight construye las visualizaciones.","Incorrecta: Lex y Translate son servicios de IA y no cubren registros ni paneles.","Incorrecta: WorkSpaces y AppStream 2.0 entregan escritorios y aplicaciones, no analizan registros."],fuentes:["https://docs.aws.amazon.com/textract/","https://docs.aws.amazon.com/polly/","https://docs.aws.amazon.com/opensearch-service/","https://docs.aws.amazon.com/quicksight/","https://docs.aws.amazon.com/lex/","https://docs.aws.amazon.com/translate/","https://docs.aws.amazon.com/workspaces/","https://docs.aws.amazon.com/kinesis/","https://docs.aws.amazon.com/appstream2/"]},{id:"3.7-q13",taskId:"3.7",objetivos:["3.7#1"],tipo:"casoDeUso",question:"Una aerolínea quiere clasificar automáticamente por sentimiento los comentarios de sus clientes en redes sociales, sin entrenar ningún modelo. ¿Qué tipo de servicio y tarea encaja mejor?",options:["Un servicio de IA ya entrenado de análisis de lenguaje natural, que clasifica el sentimiento del texto.","Una plataforma para entrenar un modelo propio de clasificación con datos etiquetados por el equipo.","Un servicio de almacenamiento de objetos que indexe los comentarios y los sirva por API.","Un servicio de analítica que ejecute consultas SQL sobre los comentarios almacenados."],correctAnswer:0,explanation:"Clasificar sentimiento es una tarea estándar de lenguaje natural que ya resuelve un servicio de IA entrenado, sin necesidad de datos etiquetados ni de entrenamiento. La plataforma de modelos propios se reserva para problemas específicos, y el almacenamiento o la analítica no interpretan el texto. Si el escenario pidiera un modelo propio con datos históricos de la aerolínea, la respuesta sería la plataforma de aprendizaje automático.",porQueOpcion:["Correcta: clasificar el sentimiento es una tarea estándar de lenguaje natural que resuelve un servicio de IA ya entrenado sin entrenar ningún modelo.","Incorrecta: una plataforma de modelos propios exige datos etiquetados y entrenamiento, que el escenario descarta.","Incorrecta: el almacenamiento de objetos no interpreta ni clasifica el texto.","Incorrecta: las consultas SQL sobre los comentarios almacenados no detectan sentimiento."],fuentes:["https://docs.aws.amazon.com/s3/"]}],3.8:[{id:"3.8-q1",taskId:"3.8",objetivos:["3.8#1"],tipo:"conocimiento",question:"¿Qué servicio de integración de aplicaciones entrega el mismo mensaje a múltiples suscriptores mediante publicación/suscripción, adecuado para alertas y notificaciones?",options:["Amazon Simple Queue Service (Amazon SQS), porque cada suscriptor retira su propio mensaje de la cola.","Amazon Simple Notification Service (Amazon SNS), porque difunde el mensaje a todos los suscriptores a la vez.","Amazon EventBridge, porque construye una máquina de estados con los pasos del flujo y los ejecuta en orden de principio a fin.","AWS Step Functions, porque retiene los mensajes en una cola hasta que el consumidor los lee."],correctAnswer:1,explanation:"Amazon SNS implementa publicación/suscripción: un mensaje se difunde a muchos suscriptores, que es el patrón de alertas y notificaciones. La cola que retiene mensajes para un consumidor es Amazon SQS; Amazon EventBridge enruta eventos según reglas y AWS Step Functions orquesta pasos. Si el requisito fuera que cada mensaje lo procesara un solo consumidor, el servicio sería Amazon SQS.",porQueOpcion:["Incorrecta: Amazon SQS es una cola donde cada consumidor retira su mensaje, no difunde a múltiples suscriptores.","Correcta: Amazon SNS difunde el mismo mensaje a todos los suscriptores mediante publicación/suscripción, ideal para alertas y notificaciones.","Incorrecta: Amazon EventBridge enruta eventos según reglas y no implementa publicación/suscripción para notificaciones masivas.","Incorrecta: AWS Step Functions orquesta pasos y no retiene mensajes en una cola."],fuentes:["https://docs.aws.amazon.com/sqs/","https://docs.aws.amazon.com/sns/","https://docs.aws.amazon.com/eventbridge/","https://docs.aws.amazon.com/step-functions/"]},{id:"3.8-q2",taskId:"3.8",objetivos:["3.8#1","3.8#8"],tipo:"comparacion",question:"Un equipo debe elegir entre los servicios de integración de aplicaciones del alcance. ¿Qué afirmación describe correctamente cuándo usar cada uno?",options:["Amazon SQS difunde alertas a muchos suscriptores, Amazon SNS retiene los mensajes en cola y Amazon EventBridge ejecuta los pasos secuenciales del flujo.","Amazon SQS desacopla con una cola que el consumidor recoge, Amazon SNS difunde alertas a muchos suscriptores y Amazon EventBridge enruta eventos según reglas.","Los tres servicios son equivalentes para desacoplar y solo cambia el nombre del producto y el precio por millón de mensajes.","Amazon EventBridge es una cola de mensajes, Amazon SQS es un bus de eventos y Amazon SNS orquesta los flujos de trabajo paso a paso."],correctAnswer:1,explanation:"Amazon SQS es la cola que desacopla productor y consumidor, Amazon SNS es el modelo pub/sub para alertas y notificaciones, y Amazon EventBridge es el bus de eventos que enruta según reglas. Los tres resuelven entrega de información con patrones distintos. Si el escenario exigiera reaccionar a eventos de otros servicios sin conocer al receptor, el servicio sería Amazon EventBridge.",porQueOpcion:["Incorrecta: intercambia las funciones de SQS, SNS y EventBridge.","Correcta: SQS desacopla con una cola que el consumidor recoge, SNS difunde alertas a muchos suscriptores y EventBridge enruta eventos según reglas.","Incorrecta: no son equivalentes, cada uno implementa un patrón de integración distinto.","Incorrecta: confunde las definiciones, EventBridge no es una cola ni SNS orquesta flujos de trabajo."],fuentes:["https://docs.aws.amazon.com/sqs/","https://docs.aws.amazon.com/sns/","https://docs.aws.amazon.com/eventbridge/"]},{id:"3.8-q3",taskId:"3.8",objetivos:["3.8#8"],tipo:"escenario",question:"Una empresa genera pedidos y necesita que un componente los procese a su propio ritmo, sin perder ninguno si el consumidor está ocupado. Aunque el equipo crecerá el próximo trimestre, el presupuesto mensual es limitado. ¿Qué servicio es el más adecuado?",options:["Amazon Simple Notification Service (Amazon SNS), para difundir el pedido inmediatamente a todos los suscriptores a la vez.","Amazon Simple Queue Service (Amazon SQS), para encolar los pedidos y que el consumidor los procese cuando pueda.","Amazon EventBridge, para dibujar el flujo como una máquina de estados.","AWS Step Functions, para sustituir al consumidor del pedido."],correctAnswer:1,explanation:"Cuando el trabajo debe esperar y procesarse una sola vez sin pérdidas, el patrón es una cola: Amazon SQS. Amazon SNS difundiría el mensaje a varios suscriptores, Amazon EventBridge enruta eventos y AWS Step Functions orquesta pasos, no sustituye al consumidor. Si el escenario exigiera avisar a muchos destinatarios a la vez, el servicio sería Amazon SNS.",porQueOpcion:["Incorrecta: SNS difunde de inmediato a todos los suscriptores y no permite que el consumidor procese a su propio ritmo.","Correcta: Amazon SQS encola los pedidos para que el consumidor los procese cuando pueda, sin perder ninguno.","Incorrecta: EventBridge enruta eventos y no dibuja ni ejecuta una máquina de estados.","Incorrecta: AWS Step Functions orquesta pasos y no sustituye al consumidor del pedido."],fuentes:["https://docs.aws.amazon.com/sns/","https://docs.aws.amazon.com/sqs/","https://docs.aws.amazon.com/eventbridge/","https://docs.aws.amazon.com/step-functions/"]},{id:"3.8-q4",taskId:"3.8",objetivos:["3.8#8"],tipo:"tradeoff",question:"Un sistema debe avisar de inmediato a operaciones por correo y SMS cuando se supera un umbral y, además, guardar trabajos para que un proceso los consuma más tarde. ¿Qué combinación es correcta?",options:["Amazon Simple Notification Service (Amazon SNS) para la alerta inmediata a varios suscriptores y Amazon Simple Queue Service (Amazon SQS) para encolar el trabajo pendiente.","Amazon Simple Queue Service (Amazon SQS) para la alerta inmediata a los suscriptores y Amazon Simple Notification Service (Amazon SNS) para el trabajo pendiente que se procesa después.","Amazon EventBridge, que cubre ambas necesidades —alerta inmediata y encolado— sin necesidad de otros servicios.","AWS Step Functions, que envía directamente el correo y los SMS y además encola el trabajo pendiente."],correctAnswer:0,explanation:"La alerta inmediata a muchos destinatarios es publicación/suscripción (Amazon SNS) y el trabajo que se procesa después encaja en una cola (Amazon SQS). Amazon EventBridge enruta eventos y AWS Step Functions orquesta pasos, pero ninguno sustituye a esa combinación. Si el objetivo fuera solo guardar trabajo para más tarde, bastaría con la cola.",porQueOpcion:["Correcta: Amazon SNS cubre la alerta inmediata a varios suscriptores y Amazon SQS encola el trabajo pendiente para procesarlo después.","Incorrecta: intercambia los servicios, SQS no alerta de inmediato ni SNS encola trabajo pendiente.","Incorrecta: EventBridge enruta eventos y no cubre por sí solo la alerta inmediata y el encolado.","Incorrecta: AWS Step Functions orquesta pasos y no envía directamente correo ni SMS."],fuentes:["https://docs.aws.amazon.com/sns/","https://docs.aws.amazon.com/sqs/","https://docs.aws.amazon.com/eventbridge/","https://docs.aws.amazon.com/step-functions/"]},{id:"3.8-q5",taskId:"3.8",objetivos:["3.8#2"],tipo:"conocimiento",question:"¿Qué par de servicios de aplicaciones de negocio ofrece atención al cliente y envío de correo electrónico, respectivamente?",options:["Amazon Connect para el centro de contacto y Amazon Simple Email Service (Amazon SES) para el correo.","Amazon Simple Email Service (Amazon SES) para el centro de contacto y Amazon Connect para el correo.","Amazon Simple Notification Service (Amazon SNS) para el centro de contacto y Amazon Simple Queue Service (Amazon SQS) para el correo.","AWS Amplify para el centro de contacto y AWS IoT Core para el correo."],correctAnswer:0,explanation:"Amazon Connect es el centro de contacto omnicanal (voz y chat) y Amazon Simple Email Service (Amazon SES) es el servicio de correo electrónico a escala. Los demás pares cruzan categorías: SNS y SQS son integración de aplicaciones, y Amplify e IoT Core son frontend e IoT. Si el objetivo fuera enrutar eventos entre servicios, el enfoque sería otro distinto.",porQueOpcion:["Correcta: Amazon Connect es el centro de contacto y Amazon Simple Email Service (Amazon SES) el servicio de correo electrónico.","Incorrecta: intercambia los servicios, SES no es centro de contacto ni Connect envía correo masivo.","Incorrecta: SNS y SQS son integración de aplicaciones y no cubren centro de contacto ni correo.","Incorrecta: AWS Amplify y AWS IoT Core son frontend e IoT y no ofrecen esas funciones."],fuentes:["https://docs.aws.amazon.com/connect/","https://docs.aws.amazon.com/ses/","https://docs.aws.amazon.com/sns/","https://docs.aws.amazon.com/sqs/","https://docs.aws.amazon.com/amplify/","https://docs.aws.amazon.com/iot/"]},{id:"3.8-q6",taskId:"3.8",objetivos:["3.8#9"],tipo:"escenario",question:"Una empresa quiere montar un centro de contacto omnicanal en la nube, con enrutamiento de llamadas y agentes que trabajan desde cualquier lugar, sin mantener infraestructura telefónica propia. Pese a que la plantilla cambia de turnos cada mes, la disponibilidad del servicio no puede resentirse. ¿Qué servicio satisface la necesidad?",options:["Amazon Simple Email Service (Amazon SES).","Amazon Connect.","Amazon Simple Notification Service (Amazon SNS).","Amazon WorkSpaces."],correctAnswer:1,explanation:"Amazon Connect es el centro de contacto gestionado que enruta voz y chat a los agentes sin infraestructura telefónica propia. Amazon SES envía correo, Amazon SNS difunde notificaciones y Amazon WorkSpaces entrega escritorios virtuales. Si el requisito fuera enviar correo transaccional, el servicio sería Amazon SES.",porQueOpcion:["Incorrecta: Amazon SES envía correo y no enruta llamadas ni chat.","Correcta: Amazon Connect es el centro de contacto omnicanal que enruta voz y chat sin infraestructura telefónica propia.","Incorrecta: Amazon SNS difunde notificaciones y no es un centro de contacto.","Incorrecta: Amazon WorkSpaces entrega escritorios virtuales y no atiende llamadas."],fuentes:["https://docs.aws.amazon.com/ses/","https://docs.aws.amazon.com/connect/","https://docs.aws.amazon.com/sns/","https://docs.aws.amazon.com/workspaces/"]},{id:"3.8-q7",taskId:"3.8",objetivos:["3.8#3"],tipo:"conocimiento",question:"¿Qué categoría de servicio de AWS agrupa los planes de soporte y qué plan incluye un Technical Account Manager (TAM)?",options:["Es un servicio de integración de aplicaciones y el TAM viene en el plan Basic.","Es un servicio de habilitación del cliente y el TAM lo incluye AWS Enterprise Support.","Es un servicio de computación de usuario final y el TAM solo existe en AWS Developer Support.","Es una herramienta de desarrollo que sustituye a AWS CodePipeline."],correctAnswer:1,explanation:"AWS Support pertenece a la categoría de habilitación del cliente. El Technical Account Manager (TAM) forma parte de AWS Enterprise Support, el nivel más alto; el plan Basic no incluye soporte técnico de producción ni TAM. Si el objetivo fuera una carga de producción con cobertura 24/7 pero sin TAM, bastaría con AWS Business Support.",porQueOpcion:["Incorrecta: AWS Support no es un servicio de integración de aplicaciones y el plan Basic no incluye TAM.","Correcta: AWS Support pertenece a la categoría de habilitación del cliente y el TAM lo incluye AWS Enterprise Support.","Incorrecta: no es computación de usuario final y el TAM no existe en AWS Developer Support.","Incorrecta: no sustituye a AWS CodePipeline ni es una herramienta de desarrollo."],fuentes:["https://docs.aws.amazon.com/codepipeline/","https://docs.aws.amazon.com/awssupport/latest/user/getting-started.html"]},{id:"3.8-q8",taskId:"3.8",objetivos:["3.8#10"],tipo:"escenario",question:"Una empresa ejecuta cargas críticas y necesita cobertura 24/7, tiempos de respuesta rápidos y un interlocutor técnico dedicado. ¿Qué opción de asistencia elige?",options:["El plan Basic, porque está incluido y basta para producción.","AWS Developer Support, porque incluye el Technical Account Manager (TAM).","AWS Enterprise Support, porque ofrece cobertura completa y Technical Account Manager (TAM).","No contratar soporte y depender solo de la comunidad."],correctAnswer:2,explanation:"Para cargas críticas con cobertura 24/7, respuesta rápida y un Technical Account Manager (TAM) el plan adecuado es AWS Enterprise Support. El plan Basic no cubre soporte de producción y AWS Developer Support no ofrece cobertura 24/7 ni TAM. Si el objetivo fuera una etapa de desarrollo sin cargas críticas, bastaría con AWS Developer Support.",porQueOpcion:["Incorrecta: el plan Basic no cubre soporte de producción ni ofrece cobertura 24/7.","Incorrecta: AWS Developer Support no incluye TAM ni cobertura 24/7 para cargas críticas.","Correcta: AWS Enterprise Support ofrece cobertura completa 24/7 y Technical Account Manager para cargas críticas.","Incorrecta: depender solo de la comunidad no aporta cobertura ni interlocutor técnico dedicado."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q9",taskId:"3.8",objetivos:["3.8#4"],tipo:"conocimiento",question:"¿Qué herramienta de desarrollo compila y ejecuta pruebas para construir el artefacto de una aplicación, y cuál rastrea las solicitudes entre componentes para depurar?",options:["AWS CodePipeline compila el código y lo prueba, y AWS CodeBuild rastrea las solicitudes distribuidas.","AWS CodeBuild compila y ejecuta pruebas, y AWS X-Ray rastrea las solicitudes para depurar.","AWS Systems Manager automatiza la compilación, las pruebas y el despliegue, y AWS CodePipeline rastrea las solicitudes distribuidas.","AWS Amplify compila y Amazon Connect rastrea las solicitudes."],correctAnswer:1,explanation:"AWS CodeBuild construye y prueba el código, y AWS X-Ray traza las solicitudes a través de los componentes para localizar errores y latencia. AWS CodePipeline coordina las etapas, no compila ni rastrea por sí mismo. Si el objetivo fuera coordinar toda la canalización, el servicio sería AWS CodePipeline.",porQueOpcion:["Incorrecta: CodePipeline coordina las etapas y CodeBuild compila, no al contrario.","Correcta: AWS CodeBuild compila y ejecuta pruebas, y AWS X-Ray rastrea las solicitudes para depurar.","Incorrecta: AWS Systems Manager gestiona operaciones sobre los recursos y no compila ni despliega código, y AWS CodePipeline coordina las etapas en lugar de rastrear solicitudes.","Incorrecta: Amplify es frontend e IoT Core gestiona dispositivos; ninguno compila ni rastrea."],fuentes:["https://docs.aws.amazon.com/codepipeline/","https://docs.aws.amazon.com/codebuild/","https://docs.aws.amazon.com/systems-manager/","https://docs.aws.amazon.com/amplify/","https://docs.aws.amazon.com/connect/","https://docs.aws.amazon.com/xray/","https://docs.aws.amazon.com/iot/"]},{id:"3.8-q10",taskId:"3.8",objetivos:["3.8#4","3.8#11"],tipo:"comparacion",question:"Un equipo distingue dos piezas de su canalización: una que compila y prueba el código y otra que coordina las etapas de principio a fin. ¿Qué afirmación es correcta?",options:["AWS CodePipeline compila el código y ejecuta las pruebas, y AWS CodeBuild coordina todas las etapas de la canalización.","AWS CodeBuild compila y prueba el código, y AWS CodePipeline coordina las etapas de la canalización.","Ambos servicios hacen lo mismo y se eligen por precio.","AWS CodeBuild es un bus de eventos y AWS CodePipeline un servicio de correo."],correctAnswer:1,explanation:"AWS CodeBuild es la fase de construcción y pruebas; AWS CodePipeline modela y coordina la canalización completa. Son complementarios: uno ejecuta el trabajo, el otro define y dirige el flujo. Si el objetivo fuera solo depurar errores en ejecución, la herramienta sería AWS X-Ray.",porQueOpcion:["Incorrecta: intercambia los papeles, CodePipeline no compila ni CodeBuild coordina la canalización.","Correcta: AWS CodeBuild compila y prueba el código, y AWS CodePipeline coordina las etapas de la canalización.","Incorrecta: no hacen lo mismo, son complementarios dentro del ciclo de entrega.","Incorrecta: ni CodeBuild es un bus de eventos ni CodePipeline un servicio de correo."],fuentes:["https://docs.aws.amazon.com/codepipeline/","https://docs.aws.amazon.com/codebuild/","https://docs.aws.amazon.com/xray/"]},{id:"3.8-q11",taskId:"3.8",objetivos:["3.8#11"],tipo:"escenario",question:"Una empresa quiere automatizar la compilación, las pruebas y el despliegue cada vez que hay un cambio en el repositorio, y además diagnosticar cuellos de botella entre microservicios. ¿Qué herramientas usa?",options:["AWS CodePipeline para coordinar el flujo, AWS CodeBuild para compilar y AWS X-Ray para el diagnóstico.","Amazon Simple Notification Service (Amazon SNS) para compilar, Amazon Simple Queue Service (Amazon SQS) para desplegar y Amazon Connect para el diagnóstico.","AWS Amplify para compilar, Amazon AppStream 2.0 para desplegar y AWS Support para el diagnóstico.","AWS IoT Core para compilar y Amazon WorkSpaces para el diagnóstico."],correctAnswer:0,explanation:"El ciclo de integración y entrega continua se arma con AWS CodePipeline (coordinación), AWS CodeBuild (compilación y pruebas) y AWS X-Ray (diagnóstico en ejecución). Los demás servicios pertenecen a otras categorías y no cubren esas funciones. Si el objetivo fuera solo crear y desplegar el frontend, el servicio sería AWS Amplify.",porQueOpcion:["Correcta: AWS CodePipeline coordina el flujo, AWS CodeBuild compila y prueba, y AWS X-Ray diagnostica los cuellos de botella entre microservicios.","Incorrecta: SNS, SQS y Connect son mensajería y contacto, no cubren compilación ni diagnóstico.","Incorrecta: Amplify, AppStream 2.0 y AWS Support pertenecen a otras categorías y no cubren ese ciclo.","Incorrecta: AWS IoT Core y Amazon WorkSpaces no compilan ni diagnostican microservicios."],fuentes:["https://docs.aws.amazon.com/codepipeline/","https://docs.aws.amazon.com/codebuild/","https://docs.aws.amazon.com/sns/","https://docs.aws.amazon.com/sqs/","https://docs.aws.amazon.com/connect/","https://docs.aws.amazon.com/amplify/","https://docs.aws.amazon.com/awssupport/latest/user/getting-started.html","https://docs.aws.amazon.com/iot/","https://docs.aws.amazon.com/workspaces/","https://docs.aws.amazon.com/xray/","https://docs.aws.amazon.com/appstream2/"]},{id:"3.8-q12",taskId:"3.8",objetivos:["3.8#5"],tipo:"conocimiento",question:"¿Qué servicio entrega aplicaciones de escritorio a los usuarios mediante streaming, sin instalar la aplicación en el dispositivo del usuario?",options:["Amazon WorkSpaces.","Amazon AppStream 2.0.","Amazon Connect.","AWS Amplify."],correctAnswer:1,explanation:"Amazon AppStream 2.0 publica aplicaciones concretas por streaming: la aplicación se ejecuta en AWS y el usuario solo recibe su salida. Amazon WorkSpaces entrega un escritorio virtual completo, Amazon Connect atiende llamadas y AWS Amplify despliega frontend web y móvil. Si el objetivo fuera un escritorio completo por usuario, el servicio sería Amazon WorkSpaces.",porQueOpcion:["Incorrecta: Amazon WorkSpaces entrega un escritorio virtual completo, no aplicaciones concretas por streaming.","Correcta: Amazon AppStream 2.0 publica aplicaciones concretas por streaming sin instalarlas en el dispositivo del usuario.","Incorrecta: Amazon Connect atiende llamadas y no entrega aplicaciones.","Incorrecta: AWS Amplify despliega frontend web y móvil, no aplicaciones de escritorio por streaming."],fuentes:["https://docs.aws.amazon.com/workspaces/","https://docs.aws.amazon.com/connect/","https://docs.aws.amazon.com/amplify/","https://docs.aws.amazon.com/appstream2/"]},{id:"3.8-q13",taskId:"3.8",objetivos:["3.8#5","3.8#12"],tipo:"comparacion",question:"Un equipo compara las opciones de computación de usuario final. ¿Qué afirmación distingue una opción que entrega aplicaciones concretas por streaming de otra que entrega un escritorio completo?",options:["La que entrega aplicaciones concretas por streaming publica apps individuales y la que entrega un escritorio virtual completo y persistente por usuario publica el puesto entero.","La que entrega un escritorio virtual completo publica aplicaciones por streaming y la que entrega aplicaciones concretas publica escritorios completos para cada usuario del equipo en cualquier momento.","Ambas opciones entregan escritorios completos y persistentes por usuario y solo cambian el sistema operativo del puesto de trabajo.","Una opción es un servicio de correo electrónico a escala y la otra un bus de eventos para aplicaciones, sin relación con los escritorios."],correctAnswer:0,explanation:"La entrega de aplicaciones individuales por streaming presenta solo la aplicación, mientras que la entrega de escritorios virtuales completos publica un puesto de trabajo persistente por usuario. La elección depende de si hay que publicar una aplicación o un puesto entero. Si el escenario pidiera un navegador aislado para sitios internos, la opción sería la variante de navegador seguro.",porQueOpcion:["Correcta: una opción publica aplicaciones individuales por streaming y la otra entrega un escritorio virtual completo y persistente por usuario.","Incorrecta: intercambia las definiciones de ambas opciones.","Incorrecta: no ambas entregan escritorios completos, una solo publica la aplicación concreta.","Incorrecta: ninguna de las dos es un servicio de correo ni un bus de eventos."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q14",taskId:"3.8",objetivos:["3.8#12"],tipo:"escenario",question:"Una empresa necesita que sus empleados accedan desde cualquier dispositivo, incluso uno personal, a un escritorio corporativo persistente con su propio sistema operativo y sus aplicaciones. ¿Qué servicio es el adecuado?",options:["Amazon AppStream 2.0, porque entrega solo una aplicación concreta.","Amazon WorkSpaces, porque proporciona un escritorio virtual completo por usuario.","Amazon WorkSpaces Secure Browser, porque entrega un escritorio completo con sistema operativo.","AWS IoT Core, porque conecta los dispositivos de los empleados."],correctAnswer:1,explanation:"Amazon WorkSpaces entrega un escritorio virtual completo y persistente por usuario, al que se accede desde distintos dispositivos. Amazon AppStream 2.0 solo publica aplicaciones y Amazon WorkSpaces Secure Browser ofrece un navegador aislado, no un escritorio con sistema operativo. Si el requisito fuera publicar una sola aplicación, el servicio sería Amazon AppStream 2.0.",porQueOpcion:["Incorrecta: Amazon AppStream 2.0 entrega solo una aplicación concreta, no un escritorio completo.","Correcta: Amazon WorkSpaces proporciona un escritorio virtual completo y persistente por usuario.","Incorrecta: Amazon WorkSpaces Secure Browser ofrece un navegador aislado, no un escritorio con sistema operativo.","Incorrecta: AWS IoT Core conecta dispositivos y no entrega escritorios."],fuentes:["https://docs.aws.amazon.com/workspaces/","https://docs.aws.amazon.com/workspaces-web/","https://docs.aws.amazon.com/iot/","https://docs.aws.amazon.com/appstream2/"]},{id:"3.8-q15",taskId:"3.8",objetivos:["3.8#6"],tipo:"conocimiento",question:"¿Qué servicio de AWS simplifica la creación y el despliegue de aplicaciones web y móviles, incluyendo frontend, autenticación y hosting?",options:["AWS Amplify.","AWS CodeBuild.","Amazon AppStream 2.0.","Amazon Connect."],correctAnswer:0,explanation:"AWS Amplify está orientado al frontend web y móvil: permite crear la interfaz, integrar capacidades como la autenticación y desplegar con hosting y entrega continua. AWS CodeBuild compila, AppStream 2.0 entrega aplicaciones y Amazon Connect atiende clientes. Si el objetivo fuera una canalización genérica de entrega, el servicio sería AWS CodePipeline.",porQueOpcion:["Correcta: AWS Amplify integra frontend, autenticación y hosting para aplicaciones web y móviles.","Incorrecta: AWS CodeBuild solo compila y ejecuta pruebas del código.","Incorrecta: Amazon AppStream 2.0 publica aplicaciones de escritorio por streaming.","Incorrecta: Amazon Connect es un centro de contacto y no publica aplicaciones."],fuentes:["https://docs.aws.amazon.com/amplify/","https://docs.aws.amazon.com/codebuild/","https://docs.aws.amazon.com/connect/","https://docs.aws.amazon.com/codepipeline/","https://docs.aws.amazon.com/appstream2/"]},{id:"3.8-q16",taskId:"3.8",objetivos:["3.8#13"],tipo:"escenario",question:"Un equipo quiere publicar una aplicación móvil con backend y una web con inicio de sesión, y desplegarla sin montar toda la infraestructura a mano. ¿Qué servicio encaja mejor?",options:["AWS IoT Core, porque conecta los dispositivos móviles con la nube y construye el frontend.","AWS Amplify, porque integra frontend, autenticación y despliegue de aplicaciones web y móviles.","Amazon WorkSpaces, porque publica escritorios virtuales completos para los usuarios de la aplicación.","AWS X-Ray, porque construye el frontend y despliega la aplicación móvil en producción."],correctAnswer:1,explanation:"AWS Amplify cubre la creación y el despliegue de frontend web y móvil, integrando autenticación, APIs y hosting. AWS IoT Core gestiona dispositivos, Amazon WorkSpaces entrega escritorios y AWS X-Ray depura solicitudes. Si el objetivo fuera diagnosticar errores en ejecución, la herramienta sería AWS X-Ray.",porQueOpcion:["Incorrecta: AWS IoT Core conecta dispositivos y no construye el frontend de la aplicación.","Correcta: AWS Amplify integra frontend, autenticación y despliegue de aplicaciones web y móviles.","Incorrecta: Amazon WorkSpaces publica escritorios virtuales, no la aplicación móvil.","Incorrecta: AWS X-Ray depura solicitudes y no construye ni despliega aplicaciones."],fuentes:["https://docs.aws.amazon.com/iot/","https://docs.aws.amazon.com/amplify/","https://docs.aws.amazon.com/workspaces/","https://docs.aws.amazon.com/xray/"]},{id:"3.8-q17",taskId:"3.8",objetivos:["3.8#7"],tipo:"conocimiento",question:"¿Qué servicio permite conectar, administrar y asegurar dispositivos IoT y recopilar los datos que envían a la nube?",options:["AWS IoT Core.","Amazon Connect.","Amazon EventBridge.","AWS Amplify."],correctAnswer:0,explanation:"AWS IoT Core registra y autentica los dispositivos, recibe sus mensajes y, mediante reglas, los enruta a otros servicios. Amazon Connect es un centro de contacto, Amazon EventBridge enruta eventos entre aplicaciones y AWS Amplify despliega frontend web y móvil. Si el requisito fuera encolar los mensajes de una aplicación, el servicio sería Amazon SQS.",porQueOpcion:["Correcta: AWS IoT Core conecta, administra y asegura los dispositivos IoT y recopila los datos que envían a la nube.","Incorrecta: Amazon Connect es un centro de contacto y no gestiona dispositivos.","Incorrecta: Amazon EventBridge enruta eventos entre aplicaciones, no administra dispositivos.","Incorrecta: AWS Amplify despliega frontend web y móvil, no gestiona IoT."],fuentes:["https://docs.aws.amazon.com/iot/","https://docs.aws.amazon.com/connect/","https://docs.aws.amazon.com/eventbridge/","https://docs.aws.amazon.com/amplify/","https://docs.aws.amazon.com/sqs/"]},{id:"3.8-q18",taskId:"3.8",objetivos:["3.8#14"],tipo:"escenario",question:"Una fábrica tiene miles de sensores que deben registrarse, comunicarse de forma segura con la nube y publicar sus lecturas para su análisis. ¿Qué servicio gestiona los dispositivos?",options:["Amazon Simple Queue Service (Amazon SQS), porque encola las lecturas.","AWS IoT Core, porque conecta y administra los dispositivos IoT.","Amazon WorkSpaces Secure Browser, porque administra los sensores.","AWS X-Ray, porque rastrea los sensores."],correctAnswer:1,explanation:"AWS IoT Core gestiona la identidad, la conexión segura y los mensajes de los dispositivos IoT, y los enruta a otros servicios con reglas. Amazon SQS desacopla aplicaciones con colas, Amazon WorkSpaces Secure Browser ofrece un navegador aislado y AWS X-Ray traza solicitudes. Si el objetivo fuera únicamente desacoplar el procesamiento de las lecturas, bastaría con la cola.",porQueOpcion:["Incorrecta: Amazon SQS encola lecturas, pero no registra ni autentica los dispositivos.","Correcta: AWS IoT Core registra y administra los dispositivos, asegura su conexión y recibe sus lecturas.","Incorrecta: Amazon WorkSpaces Secure Browser ofrece un navegador aislado y no administra sensores.","Incorrecta: AWS X-Ray rastrea solicitudes y no gestiona dispositivos."],fuentes:["https://docs.aws.amazon.com/sqs/","https://docs.aws.amazon.com/iot/","https://docs.aws.amazon.com/workspaces-web/","https://docs.aws.amazon.com/xray/"]},{id:"3.8-q19",taskId:"3.8",objetivos:["3.8#2","3.8#9"],tipo:"comparacion",question:"Una empresa necesita atender a sus clientes por voz y chat y, por separado, enviar correos transaccionales a gran escala. ¿Qué servicios corresponden a cada canal?",options:["Un centro de contacto omnicanal en la nube para voz y chat, y un servicio de correo electrónico a escala para los envíos.","Un servicio de correo electrónico a escala para voz y chat, y un centro de contacto omnicanal para los envíos.","Una cola de mensajes para voz y chat, y un bus de eventos para el correo.","Un servicio de escritorios virtuales para voz y chat, y un almacén de datos para el correo."],correctAnswer:0,explanation:"Cada canal apunta a una aplicación de negocio distinta: la voz y el chat a un centro de contacto omnicanal y el correo electrónico a un servicio de correo a escala. Las demás opciones asignan servicios de mensajería o de escritorio que no cubren esos canales. Si cambia el canal a solo correo masivo, bastaría con el servicio de correo electrónico.",porQueOpcion:["Correcta: un centro de contacto omnicanal cubre voz y chat y un servicio de correo a escala cubre los envíos.","Incorrecta: intercambia los canales y asigna cada servicio a la función equivocada.","Incorrecta: una cola y un bus de eventos son integración de aplicaciones y no atienden canales de cliente.","Incorrecta: los escritorios virtuales y el almacén de datos no son canales de atención ni correo electrónico."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q20",taskId:"3.8",objetivos:["3.8#3","3.8#10"],tipo:"comparacion",question:"Una empresa compara opciones de asistencia: un plan para cargas críticas con cobertura 24/7 y un interlocutor técnico dedicado, y un plan orientado a desarrollo y pruebas con atención por correo en horario laboral. ¿Qué afirmación los distingue?",options:["El plan empresarial cubre cargas críticas con cobertura 24/7 y un Technical Account Manager; el de desarrollo atiende desarrollo y pruebas por correo.","El plan de desarrollo cubre cargas críticas con cobertura 24/7 y el plan empresarial se limita a desarrollo y pruebas con soporte por correo en horario laboral.","Ambos planes son idénticos y solo cambia el precio; ninguno incluye un Technical Account Manager.","Ninguno de los dos planes da acceso a soporte técnico y todos dependen solo de la comunidad."],correctAnswer:0,explanation:"Los planes de AWS Support escalan el nivel de asistencia: el empresarial cubre cargas críticas con cobertura completa y Technical Account Manager, y el de desarrollo se orienta a desarrollo y pruebas con soporte por correo. El plan Basic no incluye soporte de producción. Si el requisito fuera una carga de producción sin interlocutor dedicado, bastaría con AWS Business Support.",porQueOpcion:["Correcta: el plan empresarial cubre cargas críticas 24/7 con Technical Account Manager y el de desarrollo se orienta a desarrollo y pruebas por correo.","Incorrecta: invierte los planes y sus características de soporte.","Incorrecta: no son idénticos y el plan empresarial sí incluye Technical Account Manager.","Incorrecta: ambos planes dan acceso a soporte técnico; no dependen solo de la comunidad."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/getting-started.html"]},{id:"3.8-q21",taskId:"3.8",objetivos:["3.8#6","3.8#13"],tipo:"comparacion",question:"Un equipo compara dos herramientas: una que crea y despliega el frontend web y móvil con autenticación y hosting integrados y otra que coordina las etapas de una canalización de entrega. ¿Qué afirmación es correcta?",options:["La primera está orientada al frontend web y móvil con capacidades integradas; la segunda orquesta las etapas de la canalización de extremo a extremo.","La primera orquesta las etapas de la canalización de entrega y la segunda crea y despliega el frontend web y móvil con autenticación integrada.","Ambas hacen lo mismo y se eligen por el lenguaje de programación del proyecto.","La primera es un bus de eventos y la segunda un servicio de correo electrónico."],correctAnswer:0,explanation:"Una herramienta está especializada en crear y desplegar el frontend web y móvil, integrando autenticación, APIs y hosting; la otra es una orquestación genérica de las etapas de la canalización. No son sustitutas: una publica la aplicación y la otra dirige el flujo de entrega. Si el objetivo fuera solo compilar y probar el código, la pieza sería otra distinta.",porQueOpcion:["Correcta: la primera está orientada al frontend web y móvil con capacidades integradas y la segunda orquesta las etapas de la canalización de extremo a extremo.","Incorrecta: intercambia las funciones de ambas herramientas.","Incorrecta: no hacen lo mismo; una publica la aplicación y la otra dirige el flujo de entrega.","Incorrecta: ninguna es un bus de eventos ni un servicio de correo electrónico."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q22",taskId:"3.8",objetivos:["3.8#7","3.8#14"],tipo:"comparacion",question:"Una fábrica necesita registrar miles de sensores, autenticar su conexión y recibir sus lecturas para análisis, y además desacoplar el procesamiento posterior de esas lecturas. ¿Qué afirmación distingue las dos piezas?",options:["La conexión y administración de los dispositivos la cubre un servicio de IoT gestionado; el desacople del procesamiento posterior, una cola de mensajes.","La conexión y administración de los dispositivos la cubre una cola de mensajes; el desacople del procesamiento posterior, un servicio de IoT gestionado.","Ambas piezas son la misma: una cola de mensajes gestiona la identidad de los dispositivos, su conexión segura y el enrutado de las lecturas a otros servicios.","Ninguna de las dos sirve: los dispositivos se conectan directamente a un centro de contacto."],correctAnswer:0,explanation:"El servicio de IoT gestionado se encarga de la identidad, la conexión segura y la recepción de los mensajes de los dispositivos; la cola desacopla el procesamiento posterior reteniendo las lecturas. Una cola no administra dispositivos y un centro de contacto no gestiona una flota. Si el escenario pidiera reaccionar a eventos y enrutarlos según reglas, entraría además un bus de eventos.",porQueOpcion:["Correcta: un servicio de IoT gestionado cubre la conexión y administración de los dispositivos y una cola de mensajes desacopla el procesamiento posterior.","Incorrecta: intercambia las piezas, una cola no administra dispositivos.","Incorrecta: una cola de mensajes no gestiona la identidad ni la conexión segura de los dispositivos.","Incorrecta: un centro de contacto no gestiona una flota de sensores IoT."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q23",taskId:"3.8",objetivos:["3.8#1"],tipo:"escenario",question:"Una plataforma de comercio debe reaccionar a un evento de pedido cancelado y disparar automáticamente la devolución del stock y la notificación al equipo de logística, sin que el sistema de pedidos conozca a esos receptores. ¿Qué patrón de integración encaja mejor?",options:["Un bus de eventos que reacciona a los eventos y los enruta a los destinos según reglas.","Una cola de mensajes que retiene el pedido hasta que un único consumidor lo retire y lo procese a su ritmo.","Un modelo de publicación/suscripción que difunde el mismo mensaje a todos los suscriptores.","Una máquina de estados que ejecuta pasos secuenciales definidos en el flujo."],correctAnswer:0,explanation:"Reaccionar a eventos de los servicios y enrutarlos a destinos según reglas, sin que el emisor conozca al receptor, es el patrón de un bus de eventos. Una cola retiene trabajo para un consumidor, la publicación/suscripción difunde a suscriptores y la máquina de estados orquesta pasos. Si el escenario pidiera alertar a muchos destinatarios a la vez, el patrón sería publicación/suscripción.",porQueOpcion:["Correcta: un bus de eventos reacciona a los eventos y los enruta a los destinos según reglas sin que el emisor conozca al receptor.","Incorrecta: una cola de mensajes retiene el trabajo para un único consumidor, no lo enruta a varios destinos.","Incorrecta: la publicación/suscripción difunde el mismo mensaje a los suscriptores, pero no lo enruta según reglas a destinos distintos.","Incorrecta: una máquina de estados ejecuta pasos definidos y no reacciona a eventos de otros servicios."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q24",taskId:"3.8",objetivos:["3.8#2"],tipo:"escenario",question:"Una empresa quiere lanzar una campaña de correo a cien mil clientes con alta entregabilidad y, a la vez, atender las respuestas por teléfono en un centro de contacto sin infraestructura propia. ¿Qué combinación de aplicaciones de negocio cubre ambos canales?",options:["Un servicio de correo electrónico a escala para la campaña y un centro de contacto omnicanal para las llamadas.","Un centro de contacto omnicanal para la campaña de correo y un servicio de correo electrónico para las llamadas.","Una cola de mensajes para enviar el correo a escala y un bus de eventos para enrutar las llamadas telefónicas.","Un servicio de escritorios virtuales para el correo y un almacén de datos para las llamadas."],correctAnswer:0,explanation:"La campaña de correo masiva con alta entregabilidad corresponde a un servicio de correo electrónico a escala, y la atención telefónica a un centro de contacto omnicanal. Las colas y los buses de eventos son integración de aplicaciones y no atienden canales de cliente. Si cambia el canal a solo correo, el centro de contacto dejaría de ser necesario.",porQueOpcion:["Correcta: un servicio de correo electrónico a escala cubre la campaña y un centro de contacto omnicanal cubre las llamadas.","Incorrecta: intercambia los servicios respecto a cada canal.","Incorrecta: las colas y los buses de eventos son integración de aplicaciones y no atienden clientes.","Incorrecta: los escritorios virtuales y el almacén de datos no envían correo ni atienden llamadas."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q25",taskId:"3.8",objetivos:["3.8#3"],tipo:"escenario",question:"Una empresa ejecuta una plataforma de ventas con tráfico continuo y quiere asistencia con tiempos de respuesta acordados y un interlocutor técnico que conozca su arquitectura. ¿Qué tipo de recurso de habilitación del cliente necesita?",options:["Un plan de soporte de nivel empresarial, con cobertura para cargas críticas y un Technical Account Manager.","El plan de soporte incluido por defecto en toda cuenta, que ya cubre producción sin coste adicional ni niveles de respuesta.","Una herramienta de revisión de buenas prácticas, que actúa como canal de soporte técnico con tiempos acordados.","Un catálogo de software de terceros, que incluye asistencia técnica con niveles de servicio y un interlocutor dedicado."],correctAnswer:0,explanation:"La combinación de tiempos de respuesta acordados y un Technical Account Manager que conoce la arquitectura corresponde a un plan de soporte de nivel empresarial. El plan incluido por defecto no cubre producción, las herramientas de revisión no son canales de soporte y un catálogo de software no presta asistencia técnica. Si el objetivo fuera solo desarrollo y pruebas, bastaría con un plan de nivel inferior.",porQueOpcion:["Correcta: un plan de soporte de nivel empresarial aporta cobertura para cargas críticas y un Technical Account Manager.","Incorrecta: el plan incluido por defecto no cubre producción ni ofrece niveles de respuesta acordados.","Incorrecta: una herramienta de revisión de buenas prácticas no es un canal de soporte técnico.","Incorrecta: un catálogo de software no presta asistencia técnica con niveles de servicio."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q26",taskId:"3.8",objetivos:["3.8#4"],tipo:"escenario",question:"Un equipo quiere que cada cambio en el repositorio compile, pase pruebas y se despliegue a producción sin pasos manuales, y poder diagnosticar después dónde se ralentizan las solicitudes entre microservicios. ¿Qué herramientas debe usar?",options:["Una herramienta que coordine las etapas del flujo, otra que compile y pruebe el código y otra que rastree las solicitudes para diagnosticar.","Una herramienta que compile el código, otra que rastree las solicitudes y ninguna que coordine las etapas del flujo de entrega continua.","Un centro de contacto para compilar el código y un escritorio virtual para rastrear las solicitudes.","Un almacén de objetos para compilar el código y un servicio de correo para coordinar las etapas del flujo."],correctAnswer:0,explanation:"El flujo se arma con una herramienta que compila y prueba, otra que coordina las etapas de la canalización y otra que rastrea las solicitudes para diagnosticar latencia y errores. Las opciones que omiten la orquestación o sustituyen las herramientas por servicios de otras categorías no cubren el ciclo. Si el objetivo fuera solo publicar el frontend, la herramienta sería otra distinta.",porQueOpcion:["Correcta: se combinan una herramienta que coordina las etapas del flujo, otra que compila y prueba el código y otra que rastrea las solicitudes.","Incorrecta: omite la herramienta que coordina las etapas del flujo de entrega continua.","Incorrecta: un centro de contacto y un escritorio virtual no compilan ni rastrean solicitudes.","Incorrecta: el almacenamiento de objetos y el correo no cubren la compilación ni la coordinación."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q27",taskId:"3.8",objetivos:["3.8#5"],tipo:"escenario",question:"Una empresa quiere dar acceso a un programa de diseño pesado a colaboradores externos con equipos modestos, sin instalarlo en esos equipos ni enviarles licencias locales. ¿Qué servicio encaja mejor?",options:["Un servicio que publica aplicaciones individuales por streaming, ejecutándolas en la nube.","Un servicio que entrega un escritorio virtual completo y persistente por usuario, con su sistema operativo y aplicaciones.","Un servicio que entrega un navegador aislado para acceder de forma segura a sitios internos.","Un servicio de correo electrónico a escala que distribuye la aplicación a los colaboradores."],correctAnswer:0,explanation:"Publicar una sola aplicación por streaming, ejecutándola en la nube, es exactamente el caso de una sola aplicación sin instalación ni licencia local. Un escritorio completo entrega un puesto entero, el navegador aislado no publica aplicaciones de escritorio y el correo no las ejecuta. Si el requisito fuera un puesto de trabajo completo por usuario, cambiaría el servicio elegido.",porQueOpcion:["Correcta: un servicio que publica aplicaciones individuales por streaming permite usar un programa pesado sin instalarlo ni enviar licencias locales.","Incorrecta: un escritorio virtual completo entrega un puesto entero, no solo la aplicación solicitada.","Incorrecta: un navegador aislado no publica aplicaciones de escritorio.","Incorrecta: un servicio de correo electrónico no distribuye ni ejecuta la aplicación."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q28",taskId:"3.8",objetivos:["3.8#6"],tipo:"escenario",question:"Una startup quiere publicar una aplicación móvil con registro de usuarios y una web de marketing, y desplegar ambas desde el repositorio sin configurar a mano autenticación, hosting y entrega. ¿Qué servicio encaja mejor?",options:["Un servicio de frontend web y móvil que integra autenticación, APIs y hosting en un flujo guiado.","Una herramienta de compilación genérica que solo ejecuta las pruebas unitarias del código y produce el artefacto desplegable.","Un servicio de rastreo de solicitudes que diagnostica errores en ejecución entre microservicios.","Un centro de contacto que atiende a los usuarios que usan el frontend de la aplicación."],correctAnswer:0,explanation:"Crear y desplegar frontend web y móvil integrando autenticación, APIs y hosting en un flujo guiado es el cometido de un servicio especializado de frontend. La herramienta de compilación no gestiona la autenticación ni el hosting, el rastreo solo diagnostica y el centro de contacto no publica aplicaciones. Si el objetivo fuera solo compilar el código, la herramienta sería otra distinta.",porQueOpcion:["Correcta: un servicio de frontend web y móvil integra autenticación, APIs y hosting en un flujo guiado.","Incorrecta: una herramienta de compilación genérica no gestiona la autenticación ni el hosting.","Incorrecta: un servicio de rastreo solo diagnostica y no publica aplicaciones.","Incorrecta: un centro de contacto atiende usuarios y no construye ni despliega el frontend."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]},{id:"3.8-q29",taskId:"3.8",objetivos:["3.8#7"],tipo:"tradeoff",question:"Un equipo debate entre operar su propia capa de mensajería para los dispositivos IoT o usar un servicio gestionado que registre cada dispositivo, autentique su conexión y enrute los mensajes. ¿Qué compromiso describe mejor esa decisión?",options:["El servicio gestionado asume la identidad, la conexión segura y el enrutado, a cambio de depender de la nube; la capa propia da control pero exige operarla.","Operar la propia capa evita cualquier dependencia de la nube y siempre resulta más barato a largo plazo, además de exigir menos esfuerzo de mantenimiento.","El servicio gestionado obliga a desarrollar el bróker y la autenticación desde cero, aunque no aporta enrutado de mensajes ni identidad de dispositivo.","Ninguna de las dos opciones permite conectar dispositivos: solo un centro de contacto puede recibir sus lecturas."],correctAnswer:0,explanation:"Un servicio gestionado de IoT asume el registro, la autenticación y el enrutado de los mensajes, lo que reduce el esfuerzo de operación a cambio de depender de la nube. Mantener la capa propia da más control pero exige operar el bróker y la seguridad. Si el objetivo fuera solo enrutar eventos entre aplicaciones, el servicio sería un bus de eventos y no la capa de IoT.",porQueOpcion:["Correcta: el servicio gestionado asume la identidad, la conexión segura y el enrutado a cambio de depender de la nube, mientras la capa propia da control pero exige operarla.","Incorrecta: operar la capa propia no evita la dependencia de la nube ni garantiza menor coste o esfuerzo.","Incorrecta: el servicio gestionado no obliga a desarrollar el bróker ni la autenticación, que ya aporta.","Incorrecta: ambas opciones permiten conectar dispositivos y no dependen de un centro de contacto."],fuentes:["https://docs.aws.amazon.com/aws-certification/latest/cloud-practitioner-02/cloud-practitioner-02.html"]}],4.1:[{id:"4.1-q1",taskId:"4.1",objetivos:["4.1#1"],tipo:"conocimiento",question:"¿Qué describe correctamente a las On-Demand Instances?",options:["Capacidad sobrante con descuento de hasta el 90 %, interrumpible con dos minutos de aviso para cargas tolerantes a fallos.","Capacidad facturada por el uso, sin compromiso de plazo ni pago por adelantado, con el precio de referencia.","Un compromiso de 1 o 3 años sobre una familia de instancias en una región, a cambio de un descuento de hasta el 72 %.","Un servidor físico completo reservado para una sola cuenta, con visibilidad y control de sockets y núcleos."],correctAnswer:1,explanation:"On-Demand factura por el tiempo de uso sin compromiso: es el precio de referencia. El descuento con interrupción describe Spot, el compromiso de 1 o 3 años describe Reserved Instances y el servidor físico completo describe Dedicated Hosts. Si cambia el requisito y el uso pasa a ser estable durante años, la respuesta correcta dejaría de ser On-Demand y sería un compromiso de 1 o 3 años.",porQueOpcion:["Incorrecta: la capacidad sobrante interrumpible con dos minutos de aviso describe Spot Instances, no On-Demand.","Correcta: On-Demand factura por uso sin compromiso de plazo ni pago por adelantado y es el precio de referencia.","Incorrecta: el compromiso de 1 o 3 años sobre una familia de instancias describe Reserved Instances o Savings Plans.","Incorrecta: el servidor físico completo reservado a una cuenta con control de sockets describe Dedicated Hosts."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q2",taskId:"4.1",objetivos:["4.1#1","4.1#3"],tipo:"comparacion",question:"Un equipo compara formas de bajar la factura de cómputo. ¿Qué afirmación distingue correctamente los planes de gasto por hora, las reservas de instancias y la capacidad sobrante interrumpible?",options:["Los tres exigen comprometerse durante tres años, y ninguna de las tres opciones puede reclamarse ni interrumpirse en ningún caso.","Savings Plans y Reserved Instances son compromisos de 1 o 3 años, mientras que Spot aprovecha capacidad sobrante y puede interrumpirse.","La capacidad sobrante ofrece el descuento menor y las reservas el mayor, y ninguna de las tres opciones exige comprometerse por un plazo.","Los planes de gasto por hora solo cubren almacenamiento y las reservas solo bases de datos administradas, no el cómputo de instancias."],correctAnswer:1,explanation:"Savings Plans y Reserved Instances son compromisos de 1 o 3 años que dan descuento. Spot no exige compromiso de plazo: usa capacidad sobrante y puede reclamarse con dos minutos de aviso. Si cambia el requisito y la carga debe ser interrumpible para pagar menos, la respuesta pasaría a ser Spot.",porQueOpcion:["Incorrecta: solo Savings Plans y Reserved Instances exigen compromiso, y Spot sí puede reclamarse o interrumpirse.","Correcta: Savings Plans y Reserved Instances son compromisos de 1 o 3 años, mientras que Spot usa capacidad sobrante interrumpible.","Incorrecta: Spot ofrece el mayor descuento y tanto las reservas como los planes sí exigen un plazo de compromiso.","Incorrecta: los planes de gasto por hora y las reservas cubren el cómputo de instancias, no solo almacenamiento o bases de datos."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q3",taskId:"4.1",objetivos:["4.1#1","4.1#3"],tipo:"comparacion",question:"Una empresa quiere garantizar capacidad en una Availability Zone concreta y, en paralelo, valora el aislamiento físico. ¿Qué distingue a las On-Demand Instances de Dedicated Hosts, Dedicated Instances y Capacity Reservations?",options:["On-Demand no tiene compromiso ni reserva capacidad; Dedicated Hosts e Instances dan aislamiento físico y Capacity Reservations garantiza capacidad en una AZ.","Las cuatro opciones reservan hardware físico exclusivo para la cuenta, garantizan capacidad en una Availability Zone y eliminan cualquier compromiso de plazo.","Capacity Reservations exige un compromiso de tres años y On-Demand requiere el pago por adelantado de toda la capacidad contratada.","Solo Dedicated Instances permiten traer licencias propias, mientras que Dedicated Hosts no ofrecen ningún control del hardware físico."],correctAnswer:0,explanation:"On-Demand es pago por uso sin garantía de capacidad. Dedicated Hosts ofrecen control del servidor físico (útil para BYOL), Dedicated Instances ejecutan en hardware dedicado a un cliente y Capacity Reservations asegura capacidad en una Availability Zone concreta. Si cambiara el requisito y solo se pidiera el descuento sin garantizar capacidad, la respuesta correcta sería un compromiso de 1 o 3 años.",porQueOpcion:["Correcta: On-Demand no reserva capacidad, Dedicated Hosts e Instances dan aislamiento físico y Capacity Reservations garantiza capacidad en una AZ.","Incorrecta: On-Demand no reserva hardware exclusivo ni garantiza capacidad, así que no se puede generalizar a las cuatro.","Incorrecta: Capacity Reservations no exige tres años y On-Demand no obliga al pago por adelantado de la capacidad.","Incorrecta: Dedicated Hosts permiten BYOL y sí ofrecen control del hardware físico; la afirmación los invierte."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q4",taskId:"4.1",objetivos:["4.1#3"],tipo:"escenario",question:"Un servicio web corre 24/7 con tráfico estable desde hace dos años, mientras que un proceso nocturno de conversión de vídeo puede reintentarse si se interrumpe. La empresa quiere minimizar el coste de ambas cargas. ¿Qué combinación es la más adecuada?",options:["Spot Instances para el servicio web y On-Demand Instances para la conversión nocturna, sin asumir ningún tipo de compromiso de plazo.","On-Demand Instances para ambas cargas para no adquirir ningún compromiso, manteniendo la máxima flexibilidad de cambio aunque se pague el precio de referencia.","Un compromiso de 1 o 3 años (Reserved Instances o Savings Plans) para el servicio estable y Spot Instances para la conversión tolerante a interrupciones.","Dedicated Hosts para el servicio web y Capacity Reservations para la conversión, buscando el mayor aislamiento físico del hardware."],correctAnswer:2,explanation:"La carga estable y predecible se beneficia de un compromiso de 1 o 3 años, y la carga tolerante a interrupciones encaja con Spot por su mayor descuento. Spot no es apta para el servicio crítico y On-Demand desaprovecha el ahorro en el uso estable. Si el escenario cambiara y la conversión no pudiera reanudarse, habría que descartar Spot.",porQueOpcion:["Incorrecta: Spot no es apta para el servicio web crítico y la conversión tolerante pagaría de más con On-Demand.","Incorrecta: On-Demand en ambas cargas paga el precio de referencia y desaprovecha el ahorro del compromiso y de Spot.","Correcta: el compromiso de 1 o 3 años abarata la carga estable y Spot abarata la conversión tolerante a interrupciones.","Incorrecta: Dedicated Hosts y Capacity Reservations buscan aislamiento y garantía de capacidad, no minimizar el coste."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q5",taskId:"4.1",objetivos:["4.1#3"],tipo:"tradeoff",question:"¿Qué trade-off describe mejor la elección entre un EC2 Instance Savings Plan y un enfoque On-Demand?",options:["El Savings Plan renuncia a todo descuento a cambio de flexibilidad total y de no asumir ningún plazo de compromiso.","El Savings Plan da más descuento a cambio de comprometer un gasto por hora durante 1 o 3 años, mientras que On-Demand mantiene la flexibilidad sin compromiso.","On-Demand siempre resulta más barato porque no tiene compromiso, su precio no depende del uso continuo ni exige reservar capacidad por adelantado para la carga.","Ambos tienen exactamente el mismo precio por hora, y lo único que cambia es la forma de facturar y el momento en que se realiza el pago."],correctAnswer:1,explanation:"El compromiso de gasto por hora de un Savings Plan reduce el precio a cambio de aceptar un plazo de 1 o 3 años; On-Demand conserva la flexibilidad y el precio de referencia. No hay descuento sin compromiso ni flexibilidad sin coste. Si cambia el requisito y la carga puede apagarse pronto, el compromiso deja de compensar frente a On-Demand.",porQueOpcion:["Incorrecta: el Savings Plan sí ofrece descuento, precisamente a cambio de asumir el plazo de compromiso.","Correcta: el Savings Plan cambia descuento por un compromiso de gasto por hora de 1 o 3 años, mientras On-Demand mantiene la flexibilidad.","Incorrecta: On-Demand no siempre es más barato, ya que para uso continuo el precio de referencia suele ser mayor que el comprometido.","Incorrecta: el Savings Plan tiene un precio efectivo menor y no comparte la misma tarifa por hora que On-Demand."],fuentes:["https://docs.aws.amazon.com/ec2/"]},{id:"4.1-q6",taskId:"4.1",objetivos:["4.1#4"],tipo:"conocimiento",question:"¿Qué flexibilidad ofrece una Reserved Instance regional de Linux/Unix con tenancy compartida?",options:["Puede aplicarse a cualquier Availability Zone de la región y repartirse entre tamaños dentro de la misma familia.","Solo cubre la Availability Zone exacta donde se compró y un tamaño concreto, sin repartirse entre otros tamaños de la familia.","Permite cambiar de familia de instancias aunque sea Standard, siempre que el sistema operativo sea Linux/Unix con tenancy compartida.","Se convierte automáticamente en capacidad Spot cuando no se usa durante varios días seguidos dentro de la misma región."],correctAnswer:0,explanation:"Una RI regional aplica el descuento a cualquier Availability Zone de la región y, con la flexibilidad de tamaño, se reparte entre tamaños de la misma familia, región y sistema operativo Linux/Unix con tenancy compartida. Cambiar de familia exige una RI Convertible. Si se necesitara cambiar de familia o de sistema operativo, la respuesta correcta sería la RI Convertible.",porQueOpcion:["Correcta: una RI regional se aplica a cualquier AZ de la región y, con flexibilidad de tamaño, se reparte entre tamaños de la misma familia.","Incorrecta: eso describe una RI zonal, que queda atada a la AZ y al tamaño concretos de la compra.","Incorrecta: cambiar de familia exige una RI Convertible, no una Standard, aunque el sistema operativo sea Linux/Unix.","Incorrecta: una Reserved Instance no se transforma en capacidad Spot; son mecanismos de compra independientes."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q7",taskId:"4.1",objetivos:["4.1#4"],tipo:"escenario",question:"Un equipo compró Reserved Instances Standard de una familia concreta y ahora migrará parte de la carga a otra familia de instancias y a otro sistema operativo. Quiere seguir aprovechando el descuento. ¿Qué debería haber elegido?",options:["Reserved Instances Standard, porque se pueden intercambiar libremente entre familias cuando el equipo lo necesite.","Reserved Instances Convertible, que permiten intercambiar familia, sistema operativo, tenancy y modalidad de pago.","Dedicated Instances, porque se ejecutan en hardware dedicado sin compromiso de plazo ni pago por adelantado.","Spot Instances, porque aprovechan capacidad sobrante y nunca se interrumpen si el uso se mantiene estable."],correctAnswer:1,explanation:"Las RI Standard no se pueden modificar ni intercambiar; las Convertible sí permiten cambiar atributos como familia, sistema operativo o tenancy, a cambio de un descuento algo menor. Si el escenario no exigiera cambiar de familia, una RI Standard seguiría dando el mayor descuento.",porQueOpcion:["Incorrecta: las RI Standard no se intercambian entre familias, así que no resuelven la migración planteada.","Correcta: las RI Convertible permiten intercambiar familia, sistema operativo, tenancy y modalidad de pago.","Incorrecta: Dedicated Instances aportan aislamiento físico, no un descuento por compromiso intercambiable entre familias.","Incorrecta: Spot usa capacidad sobrante y puede interrumpirse, y no ofrece el compromiso de descuento que se busca."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q8",taskId:"4.1",objetivos:["4.1#5"],tipo:"conocimiento",question:"¿Cómo se comportan por defecto los descuentos por compromiso de cómputo dentro de una organización con facturación consolidada?",options:["Quedan encerrados en la cuenta que los compró y no benefician al uso de ninguna otra cuenta miembro, ni siquiera con facturación consolidada.","Se comparten entre las cuentas: primero cubren el uso de la cuenta compradora y el descuento sobrante se aplica a las demás.","Se reparten a partes iguales entre todas las cuentas aunque no exista uso elegible en algunas de ellas durante el mes.","Solo funcionan si todas las cuentas de la organización se encuentran en la misma Availability Zone de una misma región."],correctAnswer:1,explanation:"Con la facturación consolidada, las RI y los Savings Plans se comparten por defecto entre las cuentas de la organización. Primero se aplican al uso de la cuenta que los compró y el beneficio restante reduce la factura de las demás. La cuenta de administración puede desactivar esa compartición. Si cambia la preferencia y se desactiva la compartición, el beneficio quedaría en la cuenta compradora.",porQueOpcion:["Incorrecta: con facturación consolidada el descuento no queda encerrado en la cuenta compradora por defecto.","Correcta: por defecto las RI y Savings Plans se comparten, cubriendo primero la cuenta compradora y luego a las demás.","Incorrecta: el reparto no es a partes iguales, sino que depende del uso elegible de cada cuenta del mes.","Incorrecta: la compartición no depende de compartir Availability Zone ni de estar en una misma región."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q9",taskId:"4.1",objetivos:["4.1#5"],tipo:"escenario",question:"En una organización con varias cuentas, la cuenta A compra Reserved Instances que no alcanza a usar, mientras que la cuenta B paga instancias a precio On-Demand. ¿Qué ocurre con el descuento no utilizado?",options:["Se pierde y la cuenta A sigue pagando el compromiso sin beneficio para nadie, ni para la propia cuenta A ni para la cuenta B.","Solo puede usarlo la cuenta de administración de la organización, nunca una cuenta miembro como la cuenta B, salvo que se activen etiquetas.","Al compartirse la reserva, el descuento sobrante de la cuenta A se aplica al uso de la cuenta B, salvo que la compartición esté desactivada.","Las Reserved Instances se cancelan automáticamente y se reembolsan a la cuenta A al detectar que están infrautilizadas."],correctAnswer:2,explanation:"En AWS Organizations el beneficio de las RI y los Savings Plans se comparte por defecto entre cuentas. El descuento que la cuenta A no consume se aplica al uso de la cuenta B, reduciendo la factura conjunta, a menos que la cuenta de administración haya desactivado la compartición. Si cambia el escenario y se desactiva la compartición, el descuento sobrante no llegaría a la cuenta B.",porQueOpcion:["Incorrecta: el descuento sobrante no se pierde mientras la compartición de la organización esté activada.","Incorrecta: cualquier cuenta miembro puede beneficiarse del descuento compartido, no solo la cuenta de administración.","Correcta: al compartirse la reserva, el descuento sobrante de la cuenta A se aplica al uso de la cuenta B salvo que la compartición esté desactivada.","Incorrecta: las RI no se cancelan ni se reembolsan automáticamente por quedar infrautilizadas."],fuentes:["https://docs.aws.amazon.com/organizations/"]},{id:"4.1-q10",taskId:"4.1",objetivos:["4.1#2"],tipo:"conocimiento",question:"¿Qué describe correctamente las clases de almacenamiento de objetos y sus niveles?",options:["Todas las clases tienen el mismo precio por GB y solo cambian de nombre comercial según la región donde se almacenen los datos.","S3 Standard es para acceso frecuente; las clases de archivo son para retención prolongada con almacenamiento más barato y recuperación más lenta.","S3 Intelligent-Tiering es la clase más barata de todas y solo admite datos que nunca se leen ni se recuperan, y no aplica ningún cargo por recuperación ni por gestión.","S3 One Zone-IA replica los datos en todas las Availability Zones de la región y por eso cuesta más que S3 Standard."],correctAnswer:1,explanation:"Las clases ordenan precio y latencia según el acceso: Standard para acceso frecuente, las clases de acceso poco frecuente con cargo por recuperación y las clases de archivo con almacenamiento muy barato y recuperación desde milisegundos hasta horas. Si cambia el patrón de acceso y los datos dejan de leerse, una política de ciclo de vida los mueve a una clase de archivo.",porQueOpcion:["Incorrecta: las clases no comparten el mismo precio por GB; difieren en costo y latencia según la frecuencia de acceso.","Correcta: S3 Standard es para acceso frecuente y las clases de archivo abaratan el almacenamiento a cambio de una recuperación más lenta.","Incorrecta: S3 Intelligent-Tiering no es la clase más barata y mueve automáticamente los datos entre niveles de acceso.","Incorrecta: S3 One Zone-IA almacena en una sola Availability Zone y por eso cuesta menos que S3 Standard."],fuentes:["https://docs.aws.amazon.com/s3/"]},{id:"4.1-q11",taskId:"4.1",objetivos:["4.1#7"],tipo:"escenario",question:"Una empresa conserva informes que debe mantener siete años, se consultan casi nunca y hoy están en S3 Standard. Quiere reducir el coste de almacenamiento sin perder los datos. ¿Qué debería hacer?",options:["Comprimir los objetos y dejarlos en S3 Standard para siempre, porque la compresión reduce el precio por GB almacenado.","Usar una política de ciclo de vida que mueva los objetos a una clase de archivo como S3 Glacier Deep Archive.","Mover los objetos a Amazon EBS para pagar menos por almacenarlos, ya que el almacenamiento de bloques es más barato que el de objetos.","Comprar Reserved Instances para el bucket de S3 y reducir así el coste mensual de almacenamiento de los informes archivados."],correctAnswer:1,explanation:"Las políticas de ciclo de vida mueven objetos desde Standard hacia clases de archivo como S3 Glacier Deep Archive, con el almacenamiento más barato para datos de retención prolongada y acceso excepcional. EBS es almacenamiento de bloques, no una clase de objeto, y las RI no aplican a almacenamiento de objetos. Si cambiara el requisito y los informes se leyeran a diario, la clase adecuada sería una de acceso frecuente.",porQueOpcion:["Incorrecta: comprimir no cambia la clase ni el alto precio por GB de S3 Standard para datos que casi no se leen.","Correcta: una política de ciclo de vida mueve los informes a una clase de archivo como S3 Glacier Deep Archive y reduce el coste.","Incorrecta: EBS es almacenamiento de bloques, no una clase de objetos, y no abarata la retención de informes frente a las clases de archivo.","Incorrecta: las Reserved Instances no aplican al almacenamiento de objetos de S3."],fuentes:["https://docs.aws.amazon.com/ebs/","https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/amazonglacier/latest/dev/introduction.html"]},{id:"4.1-q12",taskId:"4.1",objetivos:["4.1#6"],tipo:"conocimiento",question:"¿Qué regla general describe mejor los costes de transferencia de datos?",options:["Toda la salida de datos hacia internet es gratuita y toda la entrada desde internet se factura por GB en tramos decrecientes.","La entrada de datos desde internet suele ser gratuita; la salida a internet y el cruce entre Availability Zones o entre regiones se facturan por GB.","Solo se factura el tráfico dentro de la misma Availability Zone, mientras que el resto del tráfico interno de la región es gratuito.","El tráfico entre regiones es siempre gratuito si los recursos usan direcciones públicas, y solo se factura el cruce entre Availability Zones de la misma región."],correctAnswer:1,explanation:"La transferencia entrante a AWS desde internet suele ser gratuita, mientras que la saliente y los cruces entre AZ o entre regiones se facturan por GB. El tráfico entre recursos de la misma AZ con direcciones privadas no genera ese cargo de cruce. Si cambia la dirección del tráfico y se diseña para no cruzar AZ ni salir a internet, el coste de red baja.",porQueOpcion:["Incorrecta: invierte la regla, ya que la salida a internet se factura y la entrada desde internet suele ser gratuita.","Correcta: la entrada desde internet suele ser gratuita, mientras que la salida y el cruce entre AZ o regiones se facturan por GB.","Incorrecta: el tráfico dentro de la misma AZ con direcciones privadas no se factura, justo lo contrario de lo afirmado.","Incorrecta: el tráfico entre regiones no es gratuito por usar direcciones públicas."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q13",taskId:"4.1",objetivos:["4.1#6"],tipo:"escenario",question:"Dos instancias de la misma aplicación en Availability Zones distintas intercambian cada noche un gran volumen de datos. El equipo quiere reducir el coste de red, aunque el sistema operativo de las instancias no afecta a ese gasto. ¿Qué acción es más razonable?",options:["Mover todo el tráfico a internet para que no se cobre el cruce entre Availability Zones ni el de salida hacia internet.","Colocar en la misma Availability Zone los componentes que más se comunican o usar un endpoint privado, evaluando el efecto en la alta disponibilidad.","Cambiar las instancias a Spot para evitar los costes de transferencia, porque la capacidad sobrante no genera cargos de red.","Replicar los datos en todas las regiones posibles para repartir el coste de red entre más ubicaciones y reducir así el importe total que se paga cada mes."],correctAnswer:1,explanation:"El tráfico entre Availability Zones se factura por GB en ambos sentidos. Agrupar en la misma AZ los componentes que más se comunican o usar un endpoint privado reduce ese cargo, aunque hay que valorar el efecto sobre la alta disponibilidad. El tipo de compra de la instancia no cambia el coste de transferencia. Si cambia el requisito y prima la tolerancia a fallos sobre el coste de red, conviene mantener las cargas en AZ separadas.",porQueOpcion:["Incorrecta: mover el tráfico a internet añade cargos de salida en lugar de evitar el cruce entre AZ.","Correcta: agrupar en la misma AZ los componentes que más se comunican o usar un endpoint privado reduce el cruce facturado.","Incorrecta: el tipo de compra de la instancia no elimina los cargos de transferencia de datos.","Incorrecta: replicar en más regiones multiplica los cruces y el coste de red en lugar de reducirlo."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q14",taskId:"4.1",objetivos:["4.1#7"],tipo:"tradeoff",question:"Un equipo quiere reducir el coste mensual de almacenamiento y duda entre guardar datos en S3 Standard o en una clase de archivo como S3 Glacier Flexible Retrieval; aunque la región elegida no es relevante para la decisión, ¿qué trade-off describe mejor la elección entre ambas?",options:["Standard siempre es más barato de almacenar, pero más lento de leer, y no aplica ningún cargo por recuperación de datos.","La clase de archivo reduce el coste de almacenamiento a cambio de una recuperación más lenta y, según la clase, cargos por recuperación.","La clase de archivo no tiene ningún coste de almacenamiento, solo cargos por recuperación cuando se solicitan los objetos guardados.","Standard y la clase de archivo cuestan exactamente lo mismo por GB almacenado; lo único que cambia es la región donde se guardan y la latencia de acceso."],correctAnswer:1,explanation:"Las clases de archivo abaratan el almacenamiento mensual a cambio de mayor latencia de recuperación y, en algunos casos, cargos por recuperación. Standard es más caro de almacenar pero ofrece acceso inmediato, así que la elección depende de la frecuencia de lectura. Si cambia el requisito y los datos pasan a leerse con frecuencia, la clase adecuada vuelve a ser Standard.",porQueOpcion:["Incorrecta: Standard es más caro de almacenar y más rápido de leer, no más barato ni más lento.","Correcta: la clase de archivo reduce el almacenamiento a cambio de una recuperación más lenta y, según la clase, cargos por recuperación.","Incorrecta: las clases de archivo sí cobran almacenamiento mensual; no son gratuitas.","Incorrecta: Standard y la clase de archivo no cuestan lo mismo por GB ni solo difieren por región y latencia."],fuentes:["https://docs.aws.amazon.com/s3/","https://docs.aws.amazon.com/amazonglacier/latest/dev/introduction.html"]},{id:"4.1-q15",taskId:"4.1",objetivos:["4.1#2","4.1#7"],tipo:"comparacion",question:"Una empresa elige dónde guardar datos y compara las clases por frecuencia de acceso con otros tipos de almacenamiento. ¿Qué afirmación es correcta?",options:["Las clases de objetos ordenan el precio por frecuencia de acceso; el almacenamiento de bloques se paga por capacidad aprovisionada y el de archivos, por datos almacenados compartidos.","Las clases de objetos y los tipos de almacenamiento de bloques y de archivos son todos niveles de precio del mismo servicio, por lo que comparten la misma tarifa por GB y el mismo modelo de acceso.","El almacenamiento de bloques y el de archivos ofrecen las mismas clases de archivo que el de objetos, con idéntico precio por GB y la misma latencia.","El almacenamiento de archivos siempre cuesta más que cualquier clase de archivo de objetos porque replica los datos en todas las regiones de AWS."],correctAnswer:0,explanation:"Las clases de objetos ordenan el precio por frecuencia de acceso y latencia; el almacenamiento de bloques se paga por capacidad aprovisionada, se use o no, y el de archivos por datos almacenados. Si cambia el requisito y el dato debe montarse como sistema de archivos compartido, la respuesta correcta deja de ser una clase de objetos.",porQueOpcion:["Correcta: las clases de objetos ordenan el precio por acceso, el bloque se paga por capacidad aprovisionada y el archivo por datos almacenados.","Incorrecta: no son niveles del mismo servicio ni comparten tarifa por GB ni modelo de acceso.","Incorrecta: el bloque y el archivo no ofrecen las mismas clases de archivo ni idéntico precio o latencia que el objeto.","Incorrecta: el almacenamiento de archivos no replica en todas las regiones ni siempre cuesta más que cualquier clase de archivo de objetos."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q16",taskId:"4.1",objetivos:["4.1#5"],tipo:"comparacion",question:"Dentro de una organización con varias cuentas, ¿qué distingue el comportamiento por defecto del descuento por compromiso de cómputo del comportamiento cuando se desactiva su compartición?",options:["Por defecto el descuento se comparte entre todas las cuentas y el sobrante reduce la factura de las demás; si se desactiva, queda limitado a la cuenta compradora.","Por defecto el descuento queda limitado a la cuenta compradora y, al desactivar la compartición, se reparte a partes iguales entre el resto de las cuentas de la organización.","La compartición por defecto solo aplica a las cuentas que usan la misma familia de instancias y la misma región de AWS que la cuenta compradora.","Desactivar la compartición obliga a mover los recursos de las demás cuentas a la cuenta compradora para que el descuento siga aplicándose."],correctAnswer:0,explanation:"El comportamiento por defecto en una organización es compartir el descuento: cubre primero el uso de la cuenta compradora y el sobrante beneficia a las demás. La cuenta de administración puede desactivar esa compartición, y entonces el beneficio queda en la cuenta compradora. Si cambia la preferencia y se desactiva la compartición, el efecto es justo ese.",porQueOpcion:["Correcta: por defecto el descuento se comparte y el sobrante beneficia a las demás cuentas; al desactivarlo queda limitado a la compradora.","Incorrecta: invierte los dos comportamientos, ya que el defecto es compartir y no limitar a la cuenta compradora.","Incorrecta: la compartición no se restringe a la misma familia de instancias ni a la misma región de la cuenta compradora.","Incorrecta: desactivar la compartición no obliga a mover recursos; solo limita el beneficio a la cuenta compradora."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q17",taskId:"4.1",objetivos:["4.1#6"],tipo:"comparacion",question:"¿Qué distingue a la transferencia de datos entrante de la saliente y de la que cruza entre Availability Zones o regiones en la factura?",options:["La transferencia entrante desde internet suele ser gratuita, mientras que la saliente hacia internet y el cruce entre Availability Zones o regiones se facturan por GB.","La transferencia entrante hacia AWS se factura por GB y la saliente hacia internet es gratuita, por lo que conviene servir todo el tráfico desde AWS.","Todo el tráfico interno entre recursos de AWS es gratuito, con independencia de que cruce Availability Zones o regiones distintas dentro de la cuenta.","La transferencia entre regiones es gratuita cuando ambos recursos tienen dirección IP pública y solo se cobra el tráfico dentro de la misma Availability Zone de origen."],correctAnswer:0,explanation:"La entrada de datos a AWS desde internet suele ser gratuita; la salida y el cruce entre AZ o entre regiones se facturan por GB en los extremos que correspondan. Si cambia el diseño y el tráfico interno se concentra en una sola AZ con direcciones privadas, ese cargo de cruce desaparece.",porQueOpcion:["Correcta: la entrada desde internet suele ser gratuita y se facturan la salida a internet y el cruce entre AZ o regiones.","Incorrecta: es al revés, la entrada hacia AWS suele ser gratuita y la salida se factura por GB.","Incorrecta: el tráfico interno no es gratuito cuando cruza Availability Zones o regiones distintas.","Incorrecta: la dirección pública no hace gratuito el tráfico entre regiones."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q18",taskId:"4.1",objetivos:["4.1#1"],tipo:"casoDeUso",question:"Un equipo debe elegir cómo pagar el cómputo de un proyecto nuevo con uso imprevisible durante los primeros meses. ¿Qué opción encaja mejor con ese momento del proyecto?",options:["On-Demand Instances, porque se paga por uso sin compromiso y se ajusta a un patrón de consumo todavía incierto.","Reserved Instances de tres años, porque maximizan el descuento aunque el uso del proyecto todavía no sea predecible ni estable.","Dedicated Hosts, porque reservan un servidor físico completo y son la opción más económica mientras no se conoce la demanda.","Capacity Reservations, porque garantizan capacidad en una Availability Zone sin pago por adelantado ni coste por capacidad ociosa."],correctAnswer:0,explanation:"Con uso imprevisible, On-Demand evita comprometer gasto por capacidad que quizá no se consuma y es el precio de referencia. Un compromiso de 1 o 3 años, los Dedicated Hosts y las Capacity Reservations cobran o comprometen capacidad con independencia del uso. Si cambia el requisito y el consumo se vuelve estable y predecible, la respuesta correcta pasaría a un compromiso de 1 o 3 años.",porQueOpcion:["Correcta: On-Demand se paga por uso sin compromiso y se ajusta a un patrón de consumo todavía incierto.","Incorrecta: un compromiso de tres años no conviene con uso imprevisible y puede pagarse capacidad que no se consuma.","Incorrecta: los Dedicated Hosts reservan hardware físico completo y son caros, no la opción más económica con demanda desconocida.","Incorrecta: las Capacity Reservations no eliminan el coste por la capacidad ociosa que no se usa."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]},{id:"4.1-q19",taskId:"4.1",objetivos:["4.1#2"],tipo:"escenario",question:"Un equipo debe guardar durante años expedientes de consulta muy esporádica y, a la vez, datos de la aplicación que se leen a diario. ¿Qué combinación de clases de almacenamiento de objetos resulta más adecuada?",options:["Guardar todo en la clase de archivo más barata, incluidos los datos de acceso diario, para reducir al mínimo el coste de almacenamiento mensual.","Datos de acceso diario en una clase de acceso frecuente y expedientes de consulta esporádica en una clase de archivo alcanzada con una política de ciclo de vida.","Guardar todo en la clase de acceso frecuente, sin políticas de ciclo de vida, porque es la única clase que permite retener datos durante varios años sin perder el acceso inmediato.","Mover los datos de acceso diario a una clase de archivo y los expedientes a almacenamiento de bloques para abaratar la retención prolongada."],correctAnswer:1,explanation:"Cada patrón de acceso tiene su clase: acceso frecuente para lo que se lee a diario y una clase de archivo, alcanzada con una política de ciclo de vida, para lo que casi no se consulta. Poner todo en archivo encarece las lecturas diarias y no usar ciclo de vida deja en Standard datos que deberían archivar. Si cambia el patrón de acceso, la política de ciclo de vida reajusta la clase automáticamente.",porQueOpcion:["Incorrecta: poner los datos de acceso diario en una clase de archivo encarece las lecturas frecuentes.","Correcta: la clase de acceso frecuente sirve lo diario y una clase de archivo con ciclo de vida cubre los expedientes esporádicos.","Incorrecta: dejar todo en acceso frecuente sin ciclo de vida paga de más por los datos que casi no se consultan.","Incorrecta: mover lo diario a archivo y los expedientes a almacenamiento de bloques confunde tipos y empeora el acceso y el coste."],fuentes:["https://docs.aws.amazon.com/whitepapers/latest/how-aws-pricing-works/welcome.html"]}],4.2:[{id:"4.2-q1",taskId:"4.2",objetivos:["4.2#1"],tipo:"conocimiento",question:"¿Dónde se consulta la información de facturación y las facturas de una cuenta de AWS?",options:["En la consola de facturación y gestión de costos, desde la que se accede a facturas, uso y herramientas de análisis.","Únicamente abriendo un caso al soporte técnico de AWS, que es el canal para consultar facturas e historial de pagos.","En el informe de costos y uso, que es el único lugar donde aparecen las facturas y el historial de pagos de la cuenta.","En AWS Pricing Calculator, que guarda el historial de pagos y las facturas de cada mes para su consulta posterior."],correctAnswer:0,explanation:"La consola de facturación y gestión de costos centraliza facturas, historial de pagos, uso y herramientas de análisis. El soporte de AWS atiende dudas de facturación, pero no es el canal para consultarla; el informe de costos y uso detalla el uso, no sustituye a la consola; y AWS Pricing Calculator solo estima costos. Si cambia el requisito y lo que se busca es una aclaración de un cargo concreto, la respuesta correcta pasaría a ser el soporte de facturación.",porQueOpcion:["Correcta: la consola de facturación y gestión de costos reúne facturas, historial de pagos, uso y herramientas de análisis.","Incorrecta: el soporte atiende dudas de facturación, pero no es el canal para consultar facturas e historial de pagos.","Incorrecta: el informe de costos y uso detalla el uso, pero no contiene las facturas ni sustituye a la consola.","Incorrecta: AWS Pricing Calculator solo estima costos y no guarda el historial de pagos ni las facturas."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]},{id:"4.2-q2",taskId:"4.2",objetivos:["4.2#2"],tipo:"conocimiento",question:"¿Qué recurso conviene para estimar el costo mensual de una arquitectura antes de crearla?",options:["AWS Cost Explorer, porque proyecta el gasto futuro de recursos que todavía no se han creado y compara alternativas de diseño.","AWS Budgets, porque calcula el precio de cada servicio según el uso previsto y genera la estimación mensual de la arquitectura.","AWS Pricing Calculator, porque modela la arquitectura y devuelve una estimación sin desplegar recursos.","El informe de costos y uso, porque adelanta la factura del mes siguiente con el detalle de cada línea de uso previsto."],correctAnswer:2,explanation:"AWS Pricing Calculator es la herramienta de estimación previa: se modela la arquitectura y se obtiene un costo aproximado sin crear recursos. AWS Cost Explorer y el informe de costos y uso trabajan con gasto ya registrado, y AWS Budgets vigila umbrales, no calcula precios. Si cambia el requisito y lo que se necesita es analizar el gasto del mes pasado, la respuesta correcta sería AWS Cost Explorer.",porQueOpcion:["Incorrecta: AWS Cost Explorer trabaja con gasto ya registrado y no modela recursos que todavía no existen.","Incorrecta: AWS Budgets vigila umbrales de gasto, no calcula precios ni genera estimaciones de una arquitectura.","Correcta: AWS Pricing Calculator modela la arquitectura y devuelve una estimación sin desplegar recursos.","Incorrecta: el informe de costos y uso registra el uso real, no anticipa la factura de recursos que aún no existen."],fuentes:["https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/ce-what-is.html","https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/budgets-managing-costs.html"]},{id:"4.2-q3",taskId:"4.2",objetivos:["4.2#3"],tipo:"conocimiento",question:"¿Qué aporta agrupar muchas cuentas bajo una unidad de gobierno centralizada?",options:["Administrar de forma centralizada varias cuentas y sus políticas como una sola unidad de gobierno con una factura conjunta.","Sustituir la consola de facturación y eliminar la necesidad de etiquetas para atribuir el gasto entre equipos.","Convertir todas las cuentas en una sola cuenta con los mismos recursos, límites y credenciales compartidas.","Calcular automáticamente el precio de los servicios contratados y repartir la factura consolidada entre las cuentas miembro."],correctAnswer:0,explanation:"Agrupar cuentas bajo una administración central aporta gobierno común, políticas y facturación conjunta. No fusiona las cuentas ni elimina la necesidad de etiquetas para atribuir el gasto, y no calcula precios de servicio. Si cambia el requisito y solo se busca unir la factura de todas las cuentas, la capacidad relevante sería la facturación consolidada.",porQueOpcion:["Correcta: agrupar cuentas bajo una administración central aporta gobierno común, políticas y facturación conjunta.","Incorrecta: no sustituye a la consola de facturación ni elimina la necesidad de etiquetas para atribuir el gasto.","Incorrecta: no fusiona las cuentas en una sola con recursos, límites y credenciales compartidas.","Incorrecta: no calcula precios de servicio; esa función corresponde a la calculadora de precios."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]},{id:"4.2-q4",taskId:"4.2",objetivos:["4.2#4"],tipo:"conocimiento",question:"¿Qué es una etiqueta de asignación de costos?",options:["Un límite de gasto que bloquea el uso de los recursos cuando se supera el importe mensual definido.","Un par clave-valor que se aplica a los recursos para desglosar el gasto por criterios de negocio.","Un descuento automático aplicado por AWS según el volumen de uso mensual de cada servicio contratado.","Un informe detallado con cada línea de uso y su precio, que se entrega al final de cada mes."],correctAnswer:1,explanation:"Las etiquetas de asignación de costos son pares clave-valor, como equipo o proyecto, que permiten atribuir y agrupar el gasto. El límite con alerta es un presupuesto, el descuento por volumen es un efecto de la economía de escala y el detalle línea a línea es el informe de costos y uso. Si cambia la necesidad y lo que se pide es vigilar un umbral, la respuesta correcta sería un presupuesto.",porQueOpcion:["Incorrecta: el límite de gasto que bloquea el uso describe un presupuesto, no una etiqueta.","Correcta: la etiqueta de asignación de costos es un par clave-valor que se aplica a los recursos para desglosar el gasto por criterios de negocio.","Incorrecta: el descuento por volumen es un efecto de la economía de escala, no una etiqueta.","Incorrecta: un informe con cada línea de uso y su precio describe el informe de costos y uso."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]},{id:"4.2-q5",taskId:"4.2",objetivos:["4.2#5"],tipo:"comparacion",question:"¿Qué distingue a la herramienta que analiza el gasto ya registrado de la que estima el costo de una arquitectura futura?",options:["La primera estima el costo de una arquitectura futura y la segunda analiza el gasto histórico junto con las tendencias del mes.","AWS Cost Explorer analiza el costo y el uso ya registrados y AWS Pricing Calculator estima el costo de una arquitectura antes de desplegarla.","Ambas analizan solo el gasto futuro y se diferencian en el formato de los informes y en la frecuencia de actualización.","La primera define límites de gasto y envía alertas al superar el umbral, y la segunda analiza el uso pasado agrupado por servicio, cuenta o etiqueta."],correctAnswer:1,explanation:"AWS Cost Explorer trabaja con datos de costo y uso ya generados, agrupando y filtrando por servicio, cuenta o etiqueta. AWS Pricing Calculator modela una arquitectura hipotética y devuelve una estimación antes de crear recursos. Definir límites es la función de AWS Budgets. Si cambia el requisito y la estimación debe hacerse antes de desplegar, la respuesta correcta sería AWS Pricing Calculator.",porQueOpcion:["Incorrecta: invierte las funciones, ya que la primera analiza el gasto registrado y la segunda estima el costo futuro.","Correcta: AWS Cost Explorer analiza el costo y el uso ya registrados y AWS Pricing Calculator estima el costo antes de desplegar.","Incorrecta: no ambas analizan gasto futuro; una trabaja con datos ya generados.","Incorrecta: definir límites y enviar alertas corresponde a AWS Budgets, no al análisis del gasto registrado."],fuentes:["https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/ce-what-is.html","https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/budgets-managing-costs.html"]},{id:"4.2-q6",taskId:"4.2",objetivos:["4.2#5"],tipo:"escenario",question:"El responsable de un entorno de pruebas fijó un límite mensual y quiere recibir un aviso antes de superarlo. ¿Qué debe usar?",options:["AWS Budgets, porque permite definir el presupuesto y configurar alertas cuando el gasto se acerca o supera el umbral.","AWS Pricing Calculator, porque avisa cuando la estimación mensual supera el límite que se haya fijado previamente.","El informe de costos y uso, porque bloquea el gasto automáticamente al alcanzar el límite fijado para el entorno.","AWS Organizations, porque suspende las cuentas miembro que se pasan del presupuesto y reparte la factura entre equipos."],correctAnswer:0,explanation:"AWS Budgets está pensado para vigilar umbrales: se define el presupuesto y se disparan alertas al acercarse o superar el límite. AWS Pricing Calculator solo estima, el informe de costos y uso solo registra el detalle y AWS Organizations administra cuentas, no presupuestos. Si cambia el requisito y lo que se necesita es entender qué servicio provocó el gasto, la respuesta correcta sería AWS Cost Explorer.",porQueOpcion:["Correcta: AWS Budgets define el presupuesto y dispara alertas al acercarse o superar el umbral.","Incorrecta: AWS Pricing Calculator solo estima y no emite avisos cuando se supera un límite.","Incorrecta: el informe de costos y uso registra el detalle, pero no bloquea el gasto automáticamente.","Incorrecta: AWS Organizations administra cuentas y no suspende por presupuesto ni reparte la factura."],fuentes:["https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/budgets-managing-costs.html","https://docs.aws.amazon.com/organizations/","https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/ce-what-is.html"]},{id:"4.2-q7",taskId:"4.2",objetivos:["4.2#5"],tipo:"conocimiento",question:"¿Para qué sirve principalmente la herramienta de análisis del gasto ya registrado?",options:["Para estimar el costo de recursos que todavía no se han creado y comparar alternativas de diseño.","Para vigilar un límite de gasto y enviar alertas automáticas al acercarse o superar el umbral fijado antes.","Para analizar el costo y el uso ya registrados, agrupando y filtrando por servicio, cuenta o etiqueta.","Para administrar de forma centralizada varias cuentas y aplicar políticas de gobierno sobre ellas."],correctAnswer:2,explanation:"AWS Cost Explorer analiza el gasto existente y permite agrupar y filtrar por dimensiones como servicio, cuenta o etiqueta. Estimar es propio de AWS Pricing Calculator, vigilar límites de AWS Budgets y administrar cuentas de AWS Organizations. Si cambia el objetivo y lo que se pide es vigilar un límite con alertas, la respuesta correcta sería AWS Budgets.",porQueOpcion:["Incorrecta: estimar recursos que todavía no se han creado corresponde a AWS Pricing Calculator.","Incorrecta: vigilar un límite y enviar alertas es función de AWS Budgets.","Correcta: el análisis del gasto registrado agrupa y filtra por servicio, cuenta o etiqueta.","Incorrecta: administrar cuentas y aplicar políticas de gobierno corresponde a AWS Organizations."],fuentes:["https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/budgets-managing-costs.html","https://docs.aws.amazon.com/organizations/","https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/ce-what-is.html"]},{id:"4.2-q8",taskId:"4.2",objetivos:["4.2#6"],tipo:"comparacion",question:"Antes de crear una aplicación, un equipo necesita comparar el costo mensual de dos tamaños de instancia. ¿Qué afirmación sobre las herramientas es correcta?",options:["Debe usar AWS Pricing Calculator, que modela la arquitectura y estima el costo sin desplegar recursos.","Debe usar AWS Cost Explorer, porque calcula el precio futuro de las instancias y compara configuraciones antes de crearlas.","Debe usar AWS Budgets, porque compara el precio de dos configuraciones y genera una estimación mensual del gasto.","Ninguna herramienta sirve: solo la factura final indica el costo real de una arquitectura y de sus tamaños de instancia."],correctAnswer:0,explanation:"AWS Pricing Calculator permite modelar la arquitectura, ajustar cantidades y obtener una estimación antes de crear recursos, justo lo necesario para comparar alternativas. AWS Cost Explorer y la factura reflejan gasto real, y AWS Budgets vigila umbrales. Si cambia el momento y la comparación se hace sobre facturas ya emitidas, la respuesta correcta sería AWS Cost Explorer.",porQueOpcion:["Correcta: AWS Pricing Calculator modela la arquitectura y estima el costo sin desplegar recursos, lo que permite comparar alternativas.","Incorrecta: AWS Cost Explorer refleja gasto real y no calcula el precio de recursos futuros.","Incorrecta: AWS Budgets vigila umbrales, no compara precios de configuraciones.","Incorrecta: la factura final muestra el costo real, pero no permite comparar alternativas antes de crear recursos."],fuentes:["https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/ce-what-is.html","https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/budgets-managing-costs.html"]},{id:"4.2-q9",taskId:"4.2",objetivos:["4.2#7"],tipo:"escenario",question:"Una empresa tiene cuatro cuentas en la misma organización y quiere una sola factura, además de saber cuánto gasta cada equipo. ¿Qué combinación resuelve ambos objetivos?",options:["La facturación consolidada produce una sola factura y las etiquetas de asignación de costos permiten atribuir el gasto por equipo.","Facturar por separado es la única forma de saber cuánto gasta cada equipo, porque la factura consolidada oculta el detalle por filial.","La facturación consolidada reparte los cargos entre equipos de forma automática y genera un informe por filial.","AWS Pricing Calculator emite la factura única de la organización y divide el gasto por equipo según su consumo."],correctAnswer:0,explanation:"La facturación consolidada de AWS Organizations reúne el uso de todas las cuentas miembro en una sola factura; la atribución por equipo se logra etiquetando los recursos y analizando el gasto con esas etiquetas. Consolidar no reparte el costo automáticamente. Si cambia el requisito y se factura cada cuenta por separado, la atribución por equipo sería directa pero se perdería la factura única.",porQueOpcion:["Correcta: la facturación consolidada emite una sola factura y las etiquetas de asignación de costos permiten atribuir el gasto por equipo.","Incorrecta: la factura consolidada no oculta el detalle y facturar por separado no es la única vía para atribuir el gasto.","Incorrecta: consolidar no reparte el costo entre equipos de forma automática.","Incorrecta: AWS Pricing Calculator estima costos y no emite facturas ni divide el gasto por equipo."],fuentes:["https://docs.aws.amazon.com/organizations/"]},{id:"4.2-q10",taskId:"4.2",objetivos:["4.2#8"],tipo:"conocimiento",question:"¿Cómo se relacionan las etiquetas de asignación de costos con el informe de costos y uso?",options:["El informe crea las etiquetas automáticamente al final de cada mes a partir del nombre y el tipo de cada recurso.","Las etiquetas activadas aparecen en cada línea de uso del informe, de modo que el gasto se puede cruzar con criterios de negocio.","Las etiquetas sustituyen al informe cuando el número de recursos es pequeño y el análisis por cuenta es suficiente.","El informe ignora por completo las etiquetas y solo agrupa por cuenta y por servicio, sin mostrar los valores definidos por el usuario."],correctAnswer:1,explanation:"El informe de costos y uso es el detalle más granular de facturación e incluye las etiquetas que se han activado como etiquetas de asignación de costos. Así cada línea de uso se puede atribuir a un equipo, proyecto o entorno. Las etiquetas no se generan solas al cerrar el mes. Si cambia el requisito y solo se necesita un resumen por servicio del mes en curso, la respuesta correcta sería AWS Cost Explorer.",porQueOpcion:["Incorrecta: el informe no crea etiquetas; hay que definirlas y activarlas como etiquetas de asignación de costos.","Correcta: las etiquetas activadas aparecen en cada línea de uso del informe y permiten cruzar el gasto con criterios de negocio.","Incorrecta: las etiquetas no sustituyen al informe cuando el análisis por cuenta resulta suficiente.","Incorrecta: el informe sí incluye las etiquetas activadas como etiquetas de asignación de costos en cada línea."],fuentes:["https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/ce-what-is.html"]},{id:"4.2-q11",taskId:"4.2",objetivos:["4.2#1"],tipo:"escenario",question:"Ante una discrepancia en la factura, un equipo necesita revisar el detalle del uso del mes y entender de dónde viene un cargo antes de reclamar. ¿Qué recurso debe usar primero?",options:["La consola de facturación y gestión de costos, que reúne facturas, uso y herramientas de análisis del gasto registrado.","Un caso de soporte técnico de severidad crítica, porque solo el soporte puede desglosar el uso facturado de cada cuenta.","La calculadora de precios, porque reproduce el coste mensual de la arquitectura desplegada y detalla los cargos reales de cada servicio.","El informe de costos y uso, porque es el único recurso que explica el origen de un cargo antes de reclamarlo."],correctAnswer:0,explanation:"La consola de facturación y gestión de costos reúne las facturas, el uso y las herramientas de análisis para entender un cargo; el caso de soporte y la calculadora no sustituyen ese análisis. Si cambia el escenario y el equipo ya identificó el cargo pero necesita una aclaración formal, el recurso correcto pasaría a ser el soporte de facturación.",porQueOpcion:["Correcta: la consola de facturación y gestión de costos reúne facturas, uso y análisis para entender un cargo.","Incorrecta: un caso de soporte no es el primer recurso para desglosar el uso; aclara cargos, pero no sustituye el análisis.","Incorrecta: la calculadora estima arquitecturas y no reproduce los cargos reales de recursos desplegados.","Incorrecta: el informe detalla el uso, pero no es el único recurso ni el punto de entrada a las facturas."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]},{id:"4.2-q12",taskId:"4.2",objetivos:["4.2#2"],tipo:"casoDeUso",question:"Un equipo prepara la propuesta de un sistema que todavía no existe y necesita una cifra mensual para comparar dos diseños. ¿Qué recurso encaja mejor?",options:["La calculadora de precios, porque modela la arquitectura y devuelve una estimación sin desplegar recursos.","La herramienta de análisis del gasto registrado, porque proyecta el coste futuro del sistema a partir del uso actual.","La herramienta de presupuestos, porque calcula el precio de cada servicio según el uso previsto del diseño.","El informe de costos y uso, porque adelanta la factura del mes siguiente con el detalle de las líneas previstas."],correctAnswer:0,explanation:"La calculadora de precios modela el sistema propuesto y estima su coste mensual sin crear recursos, que es lo que permite comparar diseños. Las herramientas de análisis y de informes trabajan con gasto real, y la de presupuestos vigila umbrales. Si cambia el caso de uso y el sistema ya está desplegado, la comparación se haría con la herramienta de análisis del gasto registrado.",porQueOpcion:["Correcta: la calculadora de precios modela la arquitectura y devuelve una estimación sin desplegar recursos.","Incorrecta: el análisis del gasto registrado trabaja con datos reales y no proyecta un sistema que aún no existe.","Incorrecta: la herramienta de presupuestos vigila umbrales, no calcula precios de servicios.","Incorrecta: el informe de costos y uso registra el uso real ya generado, no anticipa la factura de un sistema no desplegado."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]},{id:"4.2-q13",taskId:"4.2",objetivos:["4.2#3","4.2#7"],tipo:"comparacion",question:"¿Qué distingue a las cuentas independientes de una organización con facturación consolidada?",options:["La organización administra las cuentas como una unidad y emite una sola factura; las cuentas independientes se facturan y gobiernan por separado.","La organización fusiona los recursos de todas las cuentas en una sola y comparte credenciales, límites y políticas entre todas las cuentas miembro.","Las cuentas independientes alcanzan antes los descuentos por volumen porque su uso se agrega y se factura conjuntamente.","La facturación consolidada impide etiquetar recursos, por lo que no se puede atribuir el gasto a cada equipo o proyecto."],correctAnswer:0,explanation:"La organización centraliza el gobierno y la facturación en una sola unidad, mientras que las cuentas independientes se gestionan y facturan por separado. No fusiona recursos ni credenciales, y la facturación consolidada sí permite atribuir el gasto con etiquetas. Si cambia el diseño y se opta por cuentas independientes, se pierde la factura única pero se gana aislamiento entre equipos.",porQueOpcion:["Correcta: la organización administra las cuentas como una unidad con una sola factura, mientras las independientes se facturan y gobiernan por separado.","Incorrecta: la organización no fusiona recursos ni comparte credenciales, límites y políticas entre todas las cuentas miembro.","Incorrecta: las cuentas independientes no agregan su uso, así que no alcanzan antes los descuentos por volumen.","Incorrecta: la facturación consolidada sí permite etiquetar y atribuir el gasto a cada equipo o proyecto."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]},{id:"4.2-q14",taskId:"4.2",objetivos:["4.2#3"],tipo:"escenario",question:"Una empresa crece por adquisiciones y ya tiene doce cuentas con equipos distintos; aunque el sector al que se dedica no es relevante para la decisión, necesita un gobierno central, políticas comunes y una sola factura. ¿Qué debe hacer?",options:["Agrupar las cuentas en una organización con administración central y facturación consolidada, aplicando etiquetas para atribuir el gasto.","Mantener las doce cuentas independientes y unificar la factura manualmente con una hoja de cálculo que reparta el gasto por equipo y proyecto.","Fusionar las doce cuentas en una sola cuenta con credenciales compartidas para todos los equipos de la empresa.","Contratar un plan de soporte empresarial, porque es lo que permite agrupar cuentas y emitir una factura única."],correctAnswer:0,explanation:"Agrupar las cuentas en una organización resuelve el gobierno central y la factura consolidada, y las etiquetas atribuyen el gasto por equipo. No hace falta fusionar cuentas ni contratar un plan de soporte para lograrlo. Si cambia el requisito y solo se necesita unir la factura sin gobierno central, la facturación consolidada por sí sola bastaría.",porQueOpcion:["Correcta: agrupar las cuentas en una organización da gobierno central, políticas comunes y facturación consolidada, con etiquetas para atribuir el gasto.","Incorrecta: mantenerlas independientes y unificar la factura a mano no aporta gobierno central ni políticas comunes.","Incorrecta: fusionar en una sola cuenta con credenciales compartidas elimina el aislamiento y no es el enfoque recomendado.","Incorrecta: el plan de soporte no agrupa cuentas ni emite una factura única."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]},{id:"4.2-q15",taskId:"4.2",objetivos:["4.2#4","4.2#8"],tipo:"comparacion",question:"¿Qué distingue a una etiqueta de asignación de costos del informe de costos y uso?",options:["La etiqueta aporta el criterio de negocio con el que se atribuye el gasto; el informe aporta el detalle de cada línea de uso con esas etiquetas.","La etiqueta es el detalle línea a línea de la factura y el informe es el par clave-valor que define el criterio de negocio y su valor concreto asociado.","Ambos son informes de facturación: la etiqueta se entrega al final del mes y el informe se consulta en tiempo real.","La etiqueta define límites de gasto y el informe envía alertas cuando el consumo supera el umbral configurado."],correctAnswer:0,explanation:"La etiqueta es el criterio (clave-valor) que se aplica a los recursos y se activa para asignación de costos; el informe es el detalle granular que incluye esas etiquetas en cada línea de uso. Ninguno fija límites ni sustituye al otro. Si cambia el requisito y solo se necesita el criterio sin el detalle, basta con definir y activar la etiqueta.",porQueOpcion:["Correcta: la etiqueta aporta el criterio de negocio y el informe el detalle de cada línea de uso con esas etiquetas.","Incorrecta: invierte los conceptos, ya que la etiqueta es el par clave-valor y el informe el detalle línea a línea.","Incorrecta: no ambos son informes; la etiqueta es un criterio que se aplica a los recursos.","Incorrecta: la etiqueta no define límites ni el informe envía alertas; eso corresponde a un presupuesto."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]},{id:"4.2-q16",taskId:"4.2",objetivos:["4.2#4","4.2#8"],tipo:"escenario",question:"Una empresa quiere saber cuánto gasta cada equipo y cada proyecto con el detalle mensual por línea de uso; aunque el número de cuentas de la organización no afecta al análisis, ¿qué combinación lo permite?",options:["Etiquetar los recursos con claves de negocio, activarlas como etiquetas de asignación de costos y analizar el detalle en el informe de costos y uso.","Etiquetar los recursos y dejarlas sin activar como etiquetas de asignación de costos, porque el informe de costos y uso lee todas las etiquetas por defecto.","Usar solo el nombre del recurso, porque el informe de costos y uso agrupa automáticamente por convención de nombres de recursos.","Definir un presupuesto por equipo, porque la herramienta de presupuestos atribuye el gasto a cada proyecto y a cada línea de uso."],correctAnswer:0,explanation:"El criterio de negocio lo aportan las etiquetas, pero deben activarse para asignación de costos; el detalle línea a línea lo aporta el informe de costos y uso. Etiquetar sin activar no propaga la etiqueta a la facturación, y el presupuesto no atribuye el gasto por proyecto. Si cambia el escenario y solo se quiere vigilar un umbral de gasto, la respuesta correcta sería un presupuesto con alertas.",porQueOpcion:["Correcta: etiquetar con claves de negocio, activarlas como asignación de costos y analizar el detalle en el informe permite atribuir el gasto por equipo y proyecto.","Incorrecta: si no se activan, las etiquetas no se propagan a la facturación y el informe no las lee por defecto.","Incorrecta: el informe no agrupa por convención de nombres; requiere etiquetas activadas.","Incorrecta: el presupuesto vigila umbrales y no atribuye el gasto por proyecto ni por línea de uso."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]},{id:"4.2-q17",taskId:"4.2",objetivos:["4.2#6"],tipo:"escenario",question:"Un equipo quiere estimar el coste mensual de tres tamaños distintos de instancia antes de decidir cuál desplegar. ¿Qué recurso debe usar?",options:["La calculadora de precios, porque modela cada configuración y devuelve una estimación sin desplegar recursos.","La herramienta de análisis del gasto registrado, porque compara el precio de configuraciones que aún no existen.","La herramienta de presupuestos, porque fija el precio de cada tamaño y envía alertas si la estimación sube.","El informe de costos y uso, porque muestra el coste de cada tamaño en cuanto se crea la primera instancia."],correctAnswer:0,explanation:"La calculadora de precios permite modelar cada configuración antes de crearla y comparar sus estimaciones. La herramienta de análisis y el informe describen gasto ya generado, y la de presupuestos vigila umbrales. Si cambia el requisito y los tres tamaños ya están desplegados, la comparación se haría con la herramienta de análisis del gasto registrado.",porQueOpcion:["Correcta: la calculadora de precios modela cada configuración y devuelve una estimación sin desplegar recursos.","Incorrecta: el análisis del gasto registrado compara configuraciones ya existentes, no futuras.","Incorrecta: la herramienta de presupuestos no fija precios de instancias; vigila umbrales de gasto.","Incorrecta: el informe muestra el gasto real una vez generado y exige que el recurso exista, así que no estima antes de decidir."],fuentes:["https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/Welcome.html"]}],4.3:[{id:"4.3-q1",taskId:"4.3",objetivos:["4.3#1"],tipo:"conocimiento",question:"Un ingeniero necesita el detalle autoritativo de una acción de la API: su comportamiento exacto, sus límites y sus permisos. ¿Qué recurso debe consultar?",options:["La sección de anuncios y novedades del blog de AWS.","La documentación del servicio publicada en los sitios oficiales de AWS.","Un hilo de la comunidad de AWS re:Post, aunque no esté verificado por AWS.","Un whitepaper de arquitectura publicado hace años."],correctAnswer:1,explanation:"La documentación del servicio es la fuente autoritativa para el comportamiento exacto, los límites y los permisos. El blog describe novedades, re:Post es una comunidad de preguntas y respuestas y los whitepapers explican decisiones de arquitectura y buenas prácticas. Si cambia el requisito y lo que se busca es un patrón de implementación, la respuesta correcta sería AWS Prescriptive Guidance.",porQueOpcion:["Incorrecta: el blog describe anuncios y novedades, no el detalle autoritativo de una acción de la API.","Correcta: la documentación del servicio es la fuente autoritativa del comportamiento exacto, los límites y los permisos.","Incorrecta: re:Post es una comunidad de preguntas y respuestas y sus hilos no están verificados por AWS.","Incorrecta: un whitepaper antiguo explica arquitectura y buenas prácticas, no el comportamiento exacto de una acción."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]},{id:"4.3-q2",taskId:"4.3",objetivos:["4.3#5"],tipo:"conocimiento",question:"¿Dónde publica AWS los whitepapers y las guías de buenas prácticas?",options:["Únicamente en el AWS Support Center, que publica whitepapers junto con los casos de soporte.","En los sitios oficiales de AWS, dentro de su sección de whitepapers y guías.","Solo en la documentación de la API de cada servicio y sus guías.","Exclusivamente en AWS Marketplace, donde los partners publican whitepapers."],correctAnswer:1,explanation:"Los whitepapers y las guías se publican en los sitios oficiales de AWS. El AWS Support Center gestiona casos de soporte, la documentación de la API describe interfaces y AWS Marketplace es un catálogo de software de terceros. Si cambia el recurso buscado y lo que se necesita es experiencia de la comunidad, la respuesta correcta sería AWS re:Post.",porQueOpcion:["Incorrecta: el AWS Support Center gestiona casos de soporte y no publica whitepapers.","Correcta: los whitepapers y las guías se publican en los sitios oficiales de AWS, en su sección correspondiente.","Incorrecta: la documentación de la API describe interfaces, no es el repositorio de whitepapers y guías.","Incorrecta: AWS Marketplace es un catálogo de software de terceros, no la fuente de whitepapers de AWS."],fuentes:["https://docs.aws.amazon.com/marketplace/","https://docs.aws.amazon.com/awssupport/latest/user/getting-started.html"]},{id:"4.3-q3",taskId:"4.3",objetivos:["4.3#6"],tipo:"conocimiento",question:"Un ingeniero busca patrones de migración y estrategias de implementación publicadas por AWS. ¿Qué recurso corresponde?",options:["AWS Prescriptive Guidance.","AWS Marketplace, catálogo de terceros.","AWS Trusted Advisor, que recomienda parámetros.","AWS Knowledge Center, que responde dudas puntuales."],correctAnswer:0,explanation:"AWS Prescriptive Guidance reúne estrategias, patrones y guías de implementación. AWS Marketplace es un catálogo de terceros, Trusted Advisor recomienda sobre el entorno propio y Knowledge Center resuelve dudas puntuales. Si cambiara el requisito y se pidiera descargar un informe de cumplimiento, la respuesta correcta sería AWS Artifact.",porQueOpcion:["Correcta: AWS Prescriptive Guidance reúne estrategias, patrones de migración y guías de implementación.","Incorrecta: AWS Marketplace es un catálogo de software de terceros, no una guía de migración.","Incorrecta: Trusted Advisor recomienda sobre la configuración del entorno propio, no publica patrones de migración.","Incorrecta: Knowledge Center resuelve dudas puntuales y no reúne patrones de implementación."],fuentes:["https://docs.aws.amazon.com/marketplace/","https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/artifact/"]},{id:"4.3-q4",taskId:"4.3",objetivos:["4.3#2","4.3#7"],tipo:"comparacion",question:"¿Qué diferencia clave separa los planes de soporte de entrada de los planes orientados a producción?",options:["Los planes de entrada cuestan más que los de producción porque incluyen menos canales de atención.","Los planes de entrada se limitan a documentación, comunidad y correo en horario laboral; los de producción añaden atención 24/7, comprobaciones completas y, en Enterprise, un TAM.","Los planes de producción no incluyen acceso a las comprobaciones de AWS Trusted Advisor, no ofrecen atención fuera del horario laboral ni cuentan con un Technical Account Manager en ningún nivel.","Solo los planes de entrada permiten abrir consultas de facturación y revisar el uso de la cuenta."],correctAnswer:1,explanation:"La frontera está en las cargas de producción: los planes de entrada (Basic y AWS Developer Support) se apoyan en documentación, comunidad y correo en horario laboral, mientras que AWS Business Support y los niveles Enterprise añaden atención 24/7, comprobaciones completas y, en Enterprise, TAM y guía proactiva. Si cambia el escenario y la carga es solo de desarrollo, bastaría con un plan de entrada.",porQueOpcion:["Incorrecta: los planes de entrada cuestan menos, no más, y ofrecen menos canales de atención.","Correcta: los de entrada se limitan a documentación, comunidad y correo en horario laboral, y los de producción añaden 24/7, comprobaciones completas y TAM en Enterprise.","Incorrecta: los planes de producción sí incluyen las comprobaciones completas y atención fuera del horario, y Enterprise aporta un TAM.","Incorrecta: también los planes de pago permiten abrir consultas y revisar el uso, no solo los de entrada."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html"]},{id:"4.3-q5",taskId:"4.3",objetivos:["4.3#7"],tipo:"escenario",question:"Una empresa con una aplicación crítica necesita atención telefónica 24/7, respuesta en menos de una hora ante una caída de producción y todas las comprobaciones de buenas prácticas de la cuenta, sin exigir un TAM asignado. ¿Qué plan se ajusta mejor?",options:["Basic Support.","AWS Developer Support.","AWS Business Support.","AWS Enterprise Support."],correctAnswer:2,explanation:"AWS Business Support ofrece atención 24/7 por teléfono, chat y correo, tiempos de respuesta cortos y todas las comprobaciones de AWS Trusted Advisor. Basic no incluye casos técnicos, Developer se limita a correo en horario laboral y Enterprise añade un TAM designado, que aquí no se exige. Si cambia el requisito y se exige un TAM designado, la respuesta correcta pasaría a AWS Enterprise Support.",porQueOpcion:["Incorrecta: Basic no incluye casos técnicos ni ofrece atención 24/7.","Incorrecta: Developer se limita al correo en horario laboral y no cubre una producción crítica.","Correcta: Business Support ofrece atención 24/7 por teléfono, chat y correo, tiempos cortos y todas las comprobaciones de Trusted Advisor sin exigir TAM.","Incorrecta: Enterprise cubre el requisito pero añade un TAM designado que aquí no se exige."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html"]},{id:"4.3-q6",taskId:"4.3",objetivos:["4.3#7"],tipo:"tradeoff",question:"Una startup con uso moderado quiere guía proactiva y acceso a un grupo de Technical Account Managers, pero no necesita un TAM designado ni los compromisos más estrictos. ¿Qué opción equilibra mejor lo que pide y lo que no necesita?",options:["AWS Enterprise On-Ramp Support.","AWS Enterprise Support, con el TAM designado.","Basic Support, incluido en toda cuenta.","AWS Developer Support, para desarrollo y pruebas."],correctAnswer:0,explanation:"AWS Enterprise On-Ramp Support ofrece guía proactiva y acceso a un grupo de TAM para cargas moderadas, sin el TAM designado ni los tiempos de respuesta más estrictos de AWS Enterprise Support. Basic no abre casos técnicos y Developer no aporta guía proactiva. Si cambia el requisito y se exige un TAM designado, la respuesta correcta sería AWS Enterprise Support.",porQueOpcion:["Correcta: Enterprise On-Ramp ofrece guía proactiva y acceso a un grupo de TAM sin el TAM designado ni los compromisos más estrictos.","Incorrecta: Enterprise Support incluye un TAM designado y compromisos más estrictos que aquí no se necesitan.","Incorrecta: Basic no abre casos técnicos ni aporta guía proactiva.","Incorrecta: Developer Support no incluye guía proactiva ni acceso a un grupo de TAM."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]},{id:"4.3-q7",taskId:"4.3",objetivos:["4.3#4"],tipo:"conocimiento",question:"¿Para qué sirve el AWS Support Center?",options:["Para diseñar arquitecturas de referencia y publicar whitepapers oficiales de AWS.","Para crear, seguir y gestionar los casos de soporte de la cuenta y acceder a AWS Trusted Advisor y al AWS Health Dashboard.","Para comprar software de terceros con facturación consolidada en la factura de AWS.","Para denunciar el abuso de recursos de AWS, como spam o phishing, ante el equipo de AWS Trust and Safety de forma confidencial."],correctAnswer:1,explanation:"El AWS Support Center es el panel de gestión de casos y el punto de entrada a AWS Trusted Advisor y al AWS Health Dashboard. El diseño de arquitecturas corresponde a los AWS solutions architects, la compra de software a AWS Marketplace y las denuncias de abuso al equipo de AWS Trust and Safety. Si cambia el requisito y el reto es un proyecto de migración, la respuesta correcta serían los AWS Professional Services.",porQueOpcion:["Incorrecta: diseñar arquitecturas de referencia corresponde a los AWS solutions architects, no al Support Center.","Correcta: el AWS Support Center gestiona los casos de soporte y da acceso a Trusted Advisor y al Health Dashboard.","Incorrecta: comprar software de terceros corresponde a AWS Marketplace.","Incorrecta: las denuncias de abuso se dirigen al equipo de AWS Trust and Safety."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/health/","https://docs.aws.amazon.com/marketplace/","https://docs.aws.amazon.com/awssupport/latest/user/getting-started.html"]},{id:"4.3-q8",taskId:"4.3",objetivos:["4.3#13"],tipo:"servicio",question:"Una empresa necesita acompañamiento experto para un proyecto de migración y para rediseñar su arquitectura. ¿Qué opción de asistencia técnica de AWS es la más adecuada?",options:["Abrir una consulta de facturación en el AWS Support Center.","AWS Professional Services y los AWS solutions architects.","Denunciar el caso al equipo de AWS Trust and Safety.","Publicar la duda en AWS re:Post y esperar respuesta."],correctAnswer:1,explanation:"AWS Professional Services y los AWS solutions architects acompañan proyectos de migración y diseño de arquitectura. Una consulta de facturación no cubre un proyecto, AWS re:Post no garantiza seguimiento y AWS Trust and Safety se ocupa de denuncias de abuso. Si cambia el requisito y se trata de un incidente puntual de la cuenta, la respuesta correcta sería abrir un caso en el AWS Support Center.",porQueOpcion:["Incorrecta: una consulta de facturación no cubre un proyecto de migración ni el rediseño de arquitectura.","Correcta: AWS Professional Services y los AWS solutions architects acompañan proyectos de migración y diseño de arquitectura.","Incorrecta: AWS Trust and Safety atiende denuncias de abuso, no proyectos de migración.","Incorrecta: AWS re:Post no garantiza el seguimiento experto que requiere el proyecto."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/getting-started.html"]},{id:"4.3-q9",taskId:"4.3",objetivos:["4.3#8"],tipo:"servicio",question:"Un equipo quiere una revisión periódica de su cuenta con recomendaciones sobre costos, seguridad, tolerancia a fallos y límites de servicio, sin que ninguna herramienta aplique cambios por sí sola. ¿Qué recurso de AWS encaja?",options:["AWS Trusted Advisor, que inspecciona la cuenta y recomienda por categorías.","El AWS Health Dashboard, que muestra el estado de los servicios de AWS.","AWS Cost Explorer, que analiza el gasto ya realizado por servicio y etiqueta.","AWS Config, que evalúa la configuración de los recursos frente a reglas definidas."],correctAnswer:0,explanation:"AWS Trusted Advisor es el que entrega recomendaciones en varias categorías (coste, seguridad, tolerancia a fallos, límites y rendimiento) sin aplicar cambios. El Health Dashboard informa del estado y los eventos, Cost Explorer analiza el gasto y Config evalúa configuración frente a reglas. Si cambia el requisito y se pidiera consultar eventos de salud de forma programática, la respuesta correcta sería la AWS Health API.",porQueOpcion:["Correcta: AWS Trusted Advisor inspecciona la cuenta y recomienda por categorías —coste, seguridad, tolerancia a fallos y límites— sin aplicar cambios.","Incorrecta: el AWS Health Dashboard informa del estado y los eventos, no hace revisiones de buenas prácticas.","Incorrecta: AWS Cost Explorer analiza el gasto y no revisa seguridad, tolerancia a fallos ni límites.","Incorrecta: AWS Config evalúa la configuración frente a reglas, no entrega las recomendaciones por categorías descritas."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/health/","https://docs.aws.amazon.com/awsaccountbilling/latest/aboutv2/ce-what-is.html","https://docs.aws.amazon.com/config/"]},{id:"4.3-q10",taskId:"4.3",objetivos:["4.3#8"],tipo:"conocimiento",question:"¿Qué aporta a un cliente la vista personalizada del estado de los servicios y de los eventos que afectan a sus recursos?",options:["Recomendaciones de ahorro sobre recursos infrautilizados y comprobaciones de buenas prácticas de configuración.","Una vista personalizada del estado de los servicios de AWS y de los eventos que afectan a sus recursos.","La compra de software de terceros con facturación consolidada en la factura mensual de AWS.","La formación y certificación de partners y el acceso a eventos exclusivos del programa."],correctAnswer:1,explanation:"El AWS Health Dashboard muestra el estado de los servicios de AWS y los eventos que afectan a los recursos de la cuenta. Las recomendaciones de ahorro son de AWS Trusted Advisor, la compra de software corresponde a AWS Marketplace y la formación de partners al AWS Partner Network. Si cambia el requisito y se necesita automatizar esa información de salud, la respuesta correcta sería la AWS Health API.",porQueOpcion:["Incorrecta: las recomendaciones de ahorro y las comprobaciones de buenas prácticas corresponden a AWS Trusted Advisor.","Correcta: el AWS Health Dashboard ofrece la vista personalizada del estado de los servicios de AWS y de los eventos que afectan a los recursos.","Incorrecta: la compra de software de terceros corresponde a AWS Marketplace.","Incorrecta: la formación y certificación de partners pertenecen al AWS Partner Network."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/health/","https://docs.aws.amazon.com/marketplace/"]},{id:"4.3-q11",taskId:"4.3",objetivos:["4.3#9"],tipo:"conocimiento",question:"¿Cuál es la función del equipo de AWS Trust and Safety?",options:["Atender consultas técnicas 24/7 según el plan de soporte contratado por la organización.","Gestionar los casos de facturación de la cuenta y emitir las facturas mensuales del cliente.","Recibir denuncias sobre el uso abusivo de recursos de AWS, como spam o phishing.","Certificar a los partners de AWS y gestionar los descuentos por volumen del programa."],correctAnswer:2,explanation:"AWS Trust and Safety es el canal para denunciar el uso abusivo de recursos de AWS. La atención técnica depende del plan de soporte, la facturación se gestiona en el AWS Support Center y la certificación de partners pertenece al AWS Partner Network. Si cambia el escenario y el problema es un incidente técnico de la cuenta, la respuesta correcta sería abrir un caso en el AWS Support Center.",porQueOpcion:["Incorrecta: la atención técnica 24/7 depende del plan de soporte, no del equipo de Trust and Safety.","Incorrecta: la facturación se gestiona en el AWS Support Center, no en Trust and Safety.","Correcta: AWS Trust and Safety recibe denuncias sobre el uso abusivo de recursos de AWS, como spam o phishing.","Incorrecta: la certificación de partners y los descuentos por volumen corresponden al AWS Partner Network."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/getting-started.html"]},{id:"4.3-q12",taskId:"4.3",objetivos:["4.3#3","4.3#10"],tipo:"conocimiento",question:"¿Qué tipos de organización forman parte del programa que agrupa a proveedores de software independientes y a integradores de sistemas?",options:["Consulting partners o system integrators y technology partners o independent software vendors.","Únicamente los clientes que tienen contratado un plan de soporte empresarial de AWS.","Solo los fabricantes de hardware que operan centros de datos de AWS y que venden equipos a los clientes.","Exclusivamente los equipos internos de AWS que atienden a los clientes de la nube."],correctAnswer:0,explanation:"El AWS Partner Network reúne consulting partners (system integrators) y technology partners (independent software vendors). No es un programa limitado a un plan de soporte ni a fabricantes de hardware, ni lo forman equipos internos de AWS. Si cambia el requisito y lo que se busca es un catálogo para comprar software de terceros, la respuesta correcta sería AWS Marketplace.",porQueOpcion:["Correcta: el AWS Partner Network reúne consulting partners (system integrators) y technology partners (independent software vendors).","Incorrecta: no se limita a los clientes con un plan de soporte empresarial contratado.","Incorrecta: no lo forman fabricantes de hardware que operan centros de datos de AWS.","Incorrecta: no lo integran equipos internos de AWS que atienden a los clientes de la nube."],fuentes:["https://docs.aws.amazon.com/marketplace/"]},{id:"4.3-q13",taskId:"4.3",objetivos:["4.3#11"],tipo:"conocimiento",question:"¿Cuál de los siguientes es un beneficio de participar en el AWS Partner Network?",options:["Formación y certificación de partners, acceso a eventos de partners y descuentos por volumen.","Asistencia telefónica 24/7 incluida en toda cuenta de AWS, sin coste de soporte adicional ni plan contratado.","Uso gratuito e ilimitado de todos los servicios de AWS durante el primer año del programa.","Exención del modelo de responsabilidad compartida entre el cliente y AWS para los recursos."],correctAnswer:0,explanation:"Los beneficios de ser partner incluyen formación y certificación, eventos de partners y descuentos por volumen. La asistencia 24/7 depende del plan de soporte contratado, ningún programa regala uso ilimitado y el modelo de responsabilidad compartida no se exime. Si cambia el objetivo y lo que se busca es comprar software de terceros, el recurso correcto sería AWS Marketplace.",porQueOpcion:["Correcta: ser partner aporta formación y certificación, acceso a eventos de partners y descuentos por volumen.","Incorrecta: la asistencia 24/7 depende del plan de soporte contratado y no está incluida en toda cuenta.","Incorrecta: ningún programa regala uso ilimitado de todos los servicios durante el primer año.","Incorrecta: el modelo de responsabilidad compartida no se exime por participar en el programa de partners."],fuentes:["https://docs.aws.amazon.com/marketplace/"]},{id:"4.3-q14",taskId:"4.3",objetivos:["4.3#12"],tipo:"conocimiento",question:"¿Qué capacidades clave ofrece a los clientes el catálogo de software de terceros?",options:["Gestión de costos con facturación consolidada, gobernanza y derechos de uso de las soluciones adquiridas.","Recomendaciones automáticas de optimización sobre el entorno de la cuenta de AWS del cliente.","El estado en tiempo real de los servicios de AWS en cada Región y los eventos que afectan a los recursos del cliente.","La formación y certificación oficiales de los partners de AWS y su acceso a eventos exclusivos."],correctAnswer:0,explanation:"AWS Marketplace consolida la facturación de las soluciones de terceros y aporta gobernanza y derechos de uso para controlar qué se adquiere y quién lo despliega. Las recomendaciones son de Trusted Advisor, el estado de servicios es del Health Dashboard y la formación de partners pertenece al AWS Partner Network. Si cambia el requisito y lo que se necesita es atención técnica, la respuesta correcta sería el AWS Support Center.",porQueOpcion:["Correcta: AWS Marketplace ofrece gestión de costos con facturación consolidada, gobernanza y derechos de uso de las soluciones.","Incorrecta: las recomendaciones automáticas de optimización corresponden a AWS Trusted Advisor.","Incorrecta: el estado en tiempo real de los servicios de AWS corresponde al AWS Health Dashboard.","Incorrecta: la formación y certificación de partners pertenecen al AWS Partner Network."],fuentes:["https://docs.aws.amazon.com/marketplace/","https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html","https://docs.aws.amazon.com/health/","https://docs.aws.amazon.com/awssupport/latest/user/getting-started.html"]},{id:"4.3-q15",taskId:"4.3",objetivos:["4.3#6"],tipo:"comparacion",question:"Un ingeniero distingue entre la fuente autoritativa del comportamiento de un servicio, las guías de implementación y la comunidad. ¿Qué afirmación es correcta?",options:["La documentación del servicio es la fuente autoritativa de su comportamiento; las guías de implementación y la comunidad ayudan a resolver dudas y patrones, pero no la sustituyen.","La comunidad de preguntas y respuestas es la fuente autoritativa del comportamiento exacto de un servicio, por encima de la documentación oficial, porque recoge la experiencia real de otros clientes.","Un whitepaper publicado hace años es la referencia más actual del comportamiento exacto de una acción de la API del servicio.","Las guías de implementación y la documentación del servicio son lo mismo y se publican siempre en el mismo apartado oficial."],correctAnswer:0,explanation:"La documentación del servicio fija el comportamiento exacto; las guías de implementación aportan patrones y la comunidad comparte experiencia, pero ninguna sustituye a la documentación. Si cambia el requisito y lo que se necesita es un patrón de migración, la respuesta correcta sería AWS Prescriptive Guidance.",porQueOpcion:["Correcta: la documentación es la fuente autoritativa del comportamiento, y las guías y la comunidad ayudan pero no la sustituyen.","Incorrecta: la comunidad no es la fuente autoritativa por encima de la documentación oficial.","Incorrecta: un whitepaper antiguo puede quedar desactualizado y no rige el comportamiento exacto de la API.","Incorrecta: las guías de implementación y la documentación son recursos distintos, aunque puedan publicarse en sitios oficiales."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]},{id:"4.3-q16",taskId:"4.3",objetivos:["4.3#8"],tipo:"comparacion",question:"¿Qué distingue a la herramienta que recomienda sobre la configuración de la cuenta del tablero que informa del estado de los servicios y de la API de salud?",options:["La herramienta de recomendaciones evalúa la configuración frente a buenas prácticas; el tablero informa de los eventos que afectan a la cuenta y la API permite automatizar esa información.","El tablero recomienda sobre la configuración; la herramienta de recomendaciones informa del estado de los servicios; y la API de salud bloquea los cambios no permitidos en la cuenta ni en sus recursos.","Los tres hacen lo mismo: recomiendan configuraciones, informan del estado y automatizan alertas sin diferencias entre ellos.","La API de salud es la única que recomienda sobre costos; el tablero y la herramienta solo muestran métricas del cliente."],correctAnswer:0,explanation:"La herramienta de recomendaciones (Trusted Advisor) revisa la configuración frente a buenas prácticas; el tablero de estado informa de los eventos que afectan a la cuenta y la API de salud expone esa información para automatizarla. Ninguna aplica cambios por sí sola. Si cambia el requisito y se busca solo el estado de los servicios, la respuesta correcta sería el tablero de estado.",porQueOpcion:["Correcta: la herramienta de recomendaciones evalúa la configuración frente a buenas prácticas, el tablero informa de los eventos y la API permite automatizar esa información.","Incorrecta: invierte las funciones y atribuye a la API de salud un bloqueo de cambios que no realiza.","Incorrecta: los tres recursos cumplen funciones distintas y no son equivalentes.","Incorrecta: la API de salud difunde el estado y los eventos, no recomienda sobre costos."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html"]},{id:"4.3-q17",taskId:"4.3",objetivos:["4.3#3","4.3#10","4.3#12"],tipo:"comparacion",question:"¿Qué distingue al programa de partners y a su catálogo de compra de los canales de soporte y de denuncia de abuso?",options:["El programa de partners reúne a consultoras y fabricantes de software; su catálogo permite comprar sus soluciones; el soporte gestiona casos y el equipo de confianza recibe denuncias de abuso.","El catálogo de partners gestiona los casos de soporte, el programa de partners recibe las denuncias de abuso y el soporte certifica a las consultoras de la red de partners en la práctica de AWS.","Los tres canales son equivalentes: cualquiera de ellos compra software, abre casos técnicos y atiende denuncias de uso abusivo.","El equipo de confianza certifica a los partners, el catálogo emite las facturas y el soporte vende software de terceros a los clientes."],correctAnswer:0,explanation:"El programa de partners agrupa a las consultoras y a los fabricantes de software, y su catálogo es donde se compran esas soluciones con facturación consolidada; el soporte gestiona casos y el equipo de confianza recibe denuncias de abuso. Si cambia el requisito y lo que se necesita es solo comprar software, la respuesta correcta sería el catálogo de compra.",porQueOpcion:["Correcta: el programa reúne consultoras y fabricantes, su catálogo permite comprar soluciones, el soporte gestiona casos y Trust and Safety recibe denuncias de abuso.","Incorrecta: mezcla los papeles, ya que el catálogo no gestiona casos ni el soporte certifica a las consultoras.","Incorrecta: los tres canales no son equivalentes; cada uno cumple una función distinta.","Incorrecta: atribuye al equipo de confianza certificar partners y al catálogo emitir facturas, lo que es falso."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]},{id:"4.3-q18",taskId:"4.3",objetivos:["4.3#1","4.3#6"],tipo:"escenario",question:"Un ingeniero necesita confirmar el comportamiento exacto de una función y, por separado, buscar un patrón de implementación recomendado. ¿Qué recurso corresponde a cada necesidad?",options:["La documentación del servicio para el comportamiento exacto y una guía de implementación para el patrón recomendado, ambas en sitios oficiales.","La comunidad de preguntas y respuestas para ambas necesidades, porque recoge respuestas de otros clientes ya verificadas por los equipos de AWS.","El catálogo de software de terceros para el comportamiento y el centro de conocimiento para el patrón de implementación.","Un caso de soporte de facturación para el comportamiento y un blog de anuncios para el patrón de implementación."],correctAnswer:0,explanation:"La documentación es la fuente autoritativa del comportamiento exacto y las guías de implementación aportan los patrones recomendados. La comunidad ayuda, pero no es la fuente autoritativa ni sustituye a la documentación. Si cambia el escenario y el patrón buscado es de migración, la respuesta correcta seguiría siendo una guía oficial como AWS Prescriptive Guidance.",porQueOpcion:["Correcta: la documentación da el comportamiento exacto y una guía de implementación el patrón recomendado, ambas en sitios oficiales.","Incorrecta: la comunidad no es la fuente autoritativa ni sus respuestas están verificadas por los equipos de AWS.","Incorrecta: el catálogo de terceros no describe el comportamiento del servicio ni el centro de conocimiento publica patrones.","Incorrecta: un caso de facturación no confirma comportamiento técnico ni un blog de anuncios aporta patrones de implementación."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]},{id:"4.3-q19",taskId:"4.3",objetivos:["4.3#2"],tipo:"escenario",question:"Una empresa con cargas en producción necesita atención telefónica a cualquier hora y tiempos de respuesta comprometidos, pero no requiere un TAM designado. ¿Qué plan se ajusta mejor?",options:["El plan de entrada incluido en toda cuenta, que no abre casos técnicos ni ofrece atención fuera del horario.","El plan de producción con atención 24/7 por teléfono, chat y correo y comprobaciones completas de Trusted Advisor.","El plan de desarrollo, que ofrece asistencia por correo en horario laboral y un contacto designado para el equipo.","El plan empresarial con TAM designado, revisión proactiva y el menor tiempo de respuesta del catálogo."],correctAnswer:1,explanation:"El plan de producción con atención 24/7 y comprobaciones completas encaja con cargas críticas sin exigir un TAM designado. El plan de entrada no abre casos técnicos, el de desarrollo se limita al horario laboral y el empresarial añade un TAM que aquí no se requiere. Si cambia el requisito y se exige un TAM designado, la respuesta correcta pasaría al plan empresarial.",porQueOpcion:["Incorrecta: el plan de entrada no abre casos técnicos ni cubre atención fuera del horario.","Correcta: el plan de producción ofrece atención 24/7 por teléfono, chat y correo y comprobaciones completas sin exigir un TAM designado.","Incorrecta: el plan de desarrollo se limita al correo en horario laboral y no cubre producción.","Incorrecta: el plan empresarial cumple pero añade un TAM designado que no se requiere."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html"]},{id:"4.3-q20",taskId:"4.3",objetivos:["4.3#3","4.3#10","4.3#12"],tipo:"escenario",question:"Una empresa quiere migrar un sistema heredado con ayuda externa y, además, comprar software de seguridad de un fabricante, unificando el pago. ¿Qué opciones encajan?",options:["Una consultora del programa de partners para la migración y el catálogo de compra para el software, con facturación consolidada.","Un caso de soporte técnico para la migración y el centro de conocimiento para comprar el software de seguridad.","El equipo de denuncia de abuso para la migración y una guía de implementación para adquirir el software.","El plan de soporte empresarial para la migración y el programa de formación y certificación de partners para comprar el software."],correctAnswer:0,explanation:"La migración con ayuda externa encaja con una consultora del programa de partners, y el software de un fabricante se compra en el catálogo con facturación consolidada. Un caso de soporte no migra sistemas ni el centro de conocimiento vende software. Si cambia el requisito y el proyecto es interno sin compra de software, bastaría con el acompañamiento de un partner de consultoría.",porQueOpcion:["Correcta: una consultora del programa de partners cubre la migración y el catálogo de compra el software, con facturación consolidada.","Incorrecta: un caso de soporte no migra sistemas ni el centro de conocimiento vende software.","Incorrecta: el equipo de denuncia de abuso no migra sistemas ni una guía permite adquirir software.","Incorrecta: el plan de soporte no ejecuta la migración ni el programa de formación vende software."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]},{id:"4.3-q21",taskId:"4.3",objetivos:["4.3#4","4.3#13"],tipo:"escenario",question:"Una empresa necesita que AWS investigue un incidente de un recurso en producción y, por separado, acompañamiento experto para rediseñar su arquitectura. ¿Qué debe usar en cada caso?",options:["Abrir un caso en el centro de soporte para el incidente y recurrir a servicios profesionales o arquitectos de soluciones para el rediseño.","Publicar la duda en la comunidad de preguntas y respuestas para ambas necesidades, porque otros clientes y expertos responden con su experiencia real en la nube.","Abrir un caso de facturación en el centro de soporte para el incidente y usar el catálogo de compra para el rediseño de la arquitectura.","Denunciar el incidente al equipo de confianza y seguridad y usar el programa de formación de partners para el rediseño de la arquitectura."],correctAnswer:0,explanation:"El incidente se gestiona como un caso en el centro de soporte, y el rediseño de arquitectura como un proyecto con servicios profesionales o arquitectos de soluciones. La comunidad no garantiza que AWS actúe sobre la cuenta. Si cambia el caso y solo se necesita una consulta de facturación, bastaría con un caso de ese tipo en el centro de soporte.",porQueOpcion:["Correcta: el incidente se abre como caso en el centro de soporte y el rediseño se apoya en servicios profesionales o arquitectos de soluciones.","Incorrecta: la comunidad no garantiza que AWS actúe sobre la cuenta ni sustituye el proyecto de rediseño.","Incorrecta: un caso de facturación no investiga un incidente técnico ni el catálogo diseña arquitecturas.","Incorrecta: Trust and Safety recibe denuncias de abuso y el programa de formación no rediseña arquitecturas."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]},{id:"4.3-q22",taskId:"4.3",objetivos:["4.3#8"],tipo:"tradeoff",question:"Un equipo busca recomendaciones concretas para reducir el gasto y, a la vez, quiere enterarse de los eventos que afectan a sus recursos. ¿Qué trade-off de uso describe mejor cada herramienta?",options:["La herramienta de recomendaciones analiza la configuración y propone mejoras de costos; el tablero de estado informa de eventos, pero ninguna aplica cambios por sí sola.","La herramienta de recomendaciones informa del estado de los servicios de AWS y el tablero propone mejoras de costos y aplica los cambios de forma automática en la cuenta.","Ambas herramientas aplican cambios automáticamente en la cuenta, pero solo si se contrata el plan de soporte empresarial.","El tablero recomienda sobre costos y la herramienta de recomendaciones solo muestra métricas en tiempo real del cliente."],correctAnswer:0,explanation:"La herramienta de recomendaciones (Trusted Advisor) propone mejoras, incluidas las de costos, y el tablero de estado informa de los eventos que afectan a la cuenta; ninguna aplica cambios por sí sola. Si cambia el requisito y se necesita automatizar la reacción a los eventos, la respuesta correcta sería consumir la API de salud.",porQueOpcion:["Correcta: Trusted Advisor propone mejoras de costos y el tablero informa de eventos, sin que ninguna aplique cambios por sí sola.","Incorrecta: intercambia las funciones y atribuye al tablero aplicar cambios automáticos que no realiza.","Incorrecta: ninguna de las dos aplica cambios automáticamente, con plan empresarial o sin él.","Incorrecta: el tablero informa del estado y no recomienda sobre costos."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/trusted-advisor.html"]},{id:"4.3-q23",taskId:"4.3",objetivos:["4.3#9"],tipo:"escenario",question:"Una empresa detecta que una de sus instancias se está usando para enviar correo no deseado. ¿A qué canal debe dirigirse?",options:["Al centro de soporte, para abrir un caso técnico de severidad crítica sobre el recurso afectado y su configuración de red.","Al equipo de confianza y seguridad, que recibe las denuncias de uso abusivo de recursos, como spam o phishing.","Al catálogo de compra, para reportar al fabricante del software que originó el envío de correo no deseado.","Al programa de partners, para que la consultora revise la configuración de la instancia comprometida."],correctAnswer:1,explanation:"Las denuncias por uso abusivo de recursos, como el envío de spam, se dirigen al equipo de confianza y seguridad. El centro de soporte atiende incidentes técnicos de la cuenta, no denuncias de abuso. Si cambia el escenario y lo que se necesita es investigar una caída de la instancia, la respuesta correcta sería abrir un caso en el centro de soporte.",porQueOpcion:["Incorrecta: el centro de soporte atiende incidentes técnicos de la cuenta, no denuncias de uso abusivo.","Correcta: el equipo de confianza y seguridad recibe las denuncias de uso abusivo de recursos, como spam o phishing.","Incorrecta: el catálogo de compra no atiende denuncias sobre el uso indebido de recursos.","Incorrecta: el programa de partners no gestiona denuncias de abuso."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]},{id:"4.3-q24",taskId:"4.3",objetivos:["4.3#11"],tipo:"casoDeUso",question:"Una empresa de software se incorpora al programa de partners y quiere capacitar a su equipo y obtener ventajas comerciales. ¿Qué beneficios recibe por ser partner?",options:["Formación y certificación, acceso a eventos y descuentos por volumen en los programas que los ofrecen.","Atención telefónica 24/7 incluida en la cuenta del partner, con independencia del plan de soporte que tenga contratado.","Uso gratuito e ilimitado de los servicios de la nube y exención del modelo de responsabilidad compartida.","La gestión automática de las denuncias de abuso y la revisión proactiva de la arquitectura del cliente."],correctAnswer:0,explanation:"El programa de partners ofrece formación y certificación, eventos y descuentos por volumen. La atención 24/7 depende del plan de soporte, ningún programa regala uso ilimitado y las denuncias de abuso las gestiona el equipo de confianza. Si cambia el caso de uso y lo que se busca es vender en la nube, el catálogo de compra es el canal comercial.",porQueOpcion:["Correcta: ser partner aporta formación y certificación, acceso a eventos y descuentos por volumen.","Incorrecta: la atención 24/7 no está incluida por ser partner; depende del plan de soporte contratado.","Incorrecta: ningún programa concede uso ilimitado ni exime del modelo de responsabilidad compartida.","Incorrecta: las denuncias de abuso las gestiona el equipo de confianza y la revisión proactiva no es un beneficio de este programa."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]},{id:"4.3-q25",taskId:"4.3",objetivos:["4.3#5"],tipo:"casoDeUso",question:"Un equipo quiere documentar las buenas prácticas de su arquitectura y compartir una guía con la organización. ¿Dónde encuentra los whitepapers y las guías oficiales de AWS?",options:["En los sitios oficiales de AWS, en la sección de whitepapers y guías de buenas prácticas.","En el centro de soporte, dentro del historial de casos técnicos ya cerrados de la propia cuenta.","En el catálogo de compra de software de terceros, en la ficha de cada producto publicado.","En el tablero de estado de los servicios, junto a los eventos que afectan a la cuenta del cliente."],correctAnswer:0,explanation:"Los whitepapers y las guías de buenas prácticas se publican en los sitios oficiales de AWS. El centro de soporte gestiona casos, el catálogo vende software de terceros y el tablero informa del estado de los servicios. Si cambia el caso de uso y lo que se necesita es una estrategia de migración, la respuesta correcta sería AWS Prescriptive Guidance.",porQueOpcion:["Correcta: los whitepapers y las guías oficiales están en los sitios oficiales de AWS, en su sección de buenas prácticas.","Incorrecta: el centro de soporte gestiona casos y no publica whitepapers ni guías oficiales.","Incorrecta: el catálogo vende software de terceros y no aloja las guías oficiales de AWS.","Incorrecta: el tablero de estado informa de eventos y no contiene whitepapers ni guías."],fuentes:["https://docs.aws.amazon.com/awssupport/latest/user/aws-support-plans.html"]}]},r={1.1:[{id:"1.1-t1",taskId:"1.1",objetivos:["1.1#1"],tipo:"definicion",frente:"¿En qué consiste la propuesta de valor de la nube de AWS?",reverso:"En cambiar el modelo de coste y de operación: pago por uso sin inversión inicial, capacidad ajustada a la demanda, economías de escala, velocidad y agilidad, alcance global y servicios gestionados que reducen la carga operativa."},{id:"1.1-t2",taskId:"1.1",objetivos:["1.1#2"],tipo:"definicion",frente:"¿Qué dos beneficios aporta disponer de una infraestructura global de AWS?",reverso:"Velocidad de despliegue (crear recursos en minutos en cualquier región, sin comprar hardware) y alcance global (servir a usuarios de todo el mundo desde la plataforma común de AWS)."},{id:"1.1-t3",taskId:"1.1",objetivos:["1.1#3"],tipo:"diferencia",frente:"Un compañero dice: «con el ajuste automático de capacidad ya tenemos alta disponibilidad». ¿Qué le corriges?",reverso:"La elasticidad ajusta la capacidad a la demanda; no protege frente a fallos. La alta disponibilidad exige redundancia, por ejemplo desplegar en varias Availability Zones, de modo que el servicio siga operativo cuando falle un componente."}],1.2:[{id:"1.2-t1",taskId:"1.2",objetivos:["1.2#1"],tipo:"definicion",frente:"¿Qué es el AWS Well-Architected Framework y en qué se diferencia del AWS Well-Architected Tool?",reverso:"El Framework es la guía de diseño: buenas prácticas y preguntas organizadas por pilar para revisar una carga de trabajo. El Tool es el servicio que conduce esa revisión, recoge las respuestas y genera el plan de mejora. Guía frente al instrumento que la aplica."},{id:"1.2-t2",taskId:"1.2",objetivos:["1.2#2"],tipo:"definicion",frente:"Enumera los seis pilares del AWS Well-Architected Framework.",reverso:"Operational excellence, security, reliability, performance efficiency, cost optimization y sustainability. Cada pilar responde a una pregunta distinta de diseño y el buen diseño los equilibra en lugar de priorizar uno solo."},{id:"1.2-t3",taskId:"1.2",objetivos:["1.2#3"],tipo:"diferencia",frente:"Un compañero dice: «la aplicación se vuelve lenta con muchos usuarios, es un problema de fiabilidad». ¿Qué corriges?",reverso:"La lentitud por falta de recursos o de escalado es performance efficiency. Reliability se ocupa de seguir funcionando ante fallos. El síntoma decide el pilar: velocidad apunta a rendimiento; tolerancia a fallos, a fiabilidad."}],1.3:[{id:"1.3-t1",taskId:"1.3",objetivos:["1.3#1"],tipo:"definicion",frente:"¿Qué beneficios de negocio se buscan al migrar a la nube?",reverso:"Reducir costes de infraestructura, ganar agilidad de despliegue, obtener elasticidad, mejorar la resiliencia y ampliar el alcance global. La adopción se planifica por olas y con enfoque cloud-first para no trasladar el modelo anterior."},{id:"1.3-t2",taskId:"1.3",objetivos:["1.3#2"],tipo:"servicio",frente:"¿Qué recurso usar para construir el caso de negocio de la migración y cuál para inventariar el entorno?",reverso:"Migration Evaluator estima el ahorro y el caso de negocio; AWS Application Discovery Service inventaría servidores, dependencias y uso real. AWS Migration Hub sigue el progreso de las migraciones entre herramientas y regiones."},{id:"1.3-t3",taskId:"1.3",objetivos:["1.3#3"],tipo:"diferencia",frente:"AWS CAF y AWS Well-Architected Framework: ¿cuándo aplica cada uno?",reverso:"El AWS CAF ordena la adopción y el cambio organizativo mediante seis perspectivas (Business, People, Governance, Platform, Security y Operations). El AWS Well-Architected Framework guía el diseño técnico de las cargas mediante sus pilares. Adopción frente a arquitectura."},{id:"1.3-t4",taskId:"1.3",objetivos:["1.3#4"],tipo:"tradeoff",frente:"Estás migrando con poco plazo y quieres aprovechar servicios gestionados. ¿Rehost o replatform?",reverso:"Rehost (*lift and shift*) es más rápido y barato en el momento, pero mantiene la deuda técnica. Replatform (*lift, tuck and reshape*) exige ajustes, pero gana en operación y explotación a cambio de un esfuerzo puntual. La elección depende del plazo y del valor de cada aplicación."}],1.4:[{id:"1.4-t1",taskId:"1.4",objetivos:["1.4#3","1.4#4"],tipo:"diferencia",frente:"Un compañero dice: «en on-premises el coste es fijo porque el hardware ya está pagado; en la nube todo es variable». ¿Qué matiz añades?",reverso:"Es correcto en lo esencial: on-premises concentra costes fijos e indirectos (hardware, energía, refrigeración, espacio, personal) que se pagan aunque la capacidad quede ociosa, mientras la nube convierte buena parte del gasto en variable ligado al consumo. El matiz es que la nube también tiene costes asociados a aprovisionar capacidad reservada."},{id:"1.4-t2",taskId:"1.4",objetivos:["1.4#6","1.4#7"],tipo:"definicion",frente:"¿Qué es rightsizing y cómo se relaciona con la automatización?",reverso:"Rightsizing es ajustar el tamaño de los recursos a la carga real según las métricas de uso, ni por encima ni por debajo. La automatización lo sostiene en el tiempo: escala, apaga fuera de horario y aplica cambios sin intervención manual, evitando que la capacidad se desajuste o quede encendida por olvido."},{id:"1.4-t3",taskId:"1.4",objetivos:["1.4#2","1.4#8"],tipo:"definicion",frente:"¿Por qué las economías de escala permiten un precio unitario menor en la nube?",reverso:"Porque el proveedor compra y opera a un volumen muy superior al de cualquier cliente y reparte ese coste entre millones de usuarios. El coste por unidad baja con la escala y esa tarifa reducida se traslada al cliente sin que este tenga que alcanzar ese volumen. Refuerza el ahorro de migrar junto con la eliminación de la capacidad ociosa."},{id:"1.4-t4",taskId:"1.4",objetivos:["1.4#5"],tipo:"diferencia",frente:"BYOL o licencia incluida: ¿qué gana y qué exige cada una?",reverso:"BYOL reutiliza las licencias que la empresa ya posee y factura solo la infraestructura, pero exige gestionar el cumplimiento y los términos de la licencia. La licencia incluida lleva su coste dentro del servicio y simplifica la gestión, aunque puede salir más cara si ya se tenían licencias propias."}],2.1:[{id:"2.1-t1",taskId:"2.1",objetivos:["2.1#1"],tipo:"definicion",frente:"¿Qué reparte el AWS shared responsibility model y entre quiénes?",reverso:"Reparte la seguridad entre AWS y el cliente: AWS responde de la seguridad de la nube (la infraestructura) y el cliente de la seguridad en la nube (datos, identidades, aplicaciones y configuración)."},{id:"2.1-t2",taskId:"2.1",objetivos:["2.1#2","2.1#3"],tipo:"diferencia",frente:"Un compañero dice: «hemos contratado Amazon EC2, así que AWS protegerá nuestros datos y el sistema operativo». ¿Qué le corriges?",reverso:"AWS protege la infraestructura física, el hardware, la red y la virtualización; el cliente protege el sistema operativo invitado, sus parches, los datos, las identidades y la configuración de cada instancia."},{id:"2.1-t3",taskId:"2.1",objetivos:["2.1#4"],tipo:"definicion",frente:"¿De qué responde AWS en el modelo de responsabilidad compartida?",reverso:"De la seguridad de la nube: instalaciones físicas, hardware, red y la capa de virtualización que sostienen los servicios, además del software de los servicios gestionados."},{id:"2.1-t4",taskId:"2.1",objetivos:["2.1#5"],tipo:"definicion",frente:"Cita ejemplos de responsabilidades compartidas entre AWS y el cliente.",reverso:"Gestión de parches, gestión de la configuración y concienciación y formación en seguridad. Cada parte aplica su mitad: AWS sobre su infraestructura y el cliente sobre sus recursos y su personal."},{id:"2.1-t5",taskId:"2.1",objetivos:["2.1#6"],tipo:"tradeoff",frente:"¿Cómo cambia la responsabilidad al pasar de Amazon EC2 a Amazon RDS o AWS Lambda?",reverso:"Cuanto más gestionado es el servicio, más asume AWS. En Amazon EC2 el cliente parchea el sistema operativo; en Amazon RDS AWS parchea el motor; en AWS Lambda AWS gestiona también el entorno de ejecución. El cliente conserva siempre los datos, las identidades y la configuración."}],2.2:[{id:"2.2-t1",taskId:"2.2",objetivos:["2.2#8"],tipo:"diferencia",frente:"Pregunta rápida: ¿Amazon CloudWatch, AWS CloudTrail o AWS Config para saber quién eliminó un recurso?",reverso:"AWS CloudTrail: registra las llamadas a la API y responde quién hizo qué y cuándo. Amazon CloudWatch: métricas, logs y alarmas del funcionamiento. AWS Config: historial de configuración de los recursos y evaluación frente a reglas."},{id:"2.2-t2",taskId:"2.2",objetivos:["2.2#3","2.2#8"],tipo:"definicion",frente:"¿Dónde se capturan y localizan los logs asociados a la seguridad?",reverso:"Los logs operativos en CloudWatch Logs; la actividad de la API en AWS CloudTrail (entregable a Amazon S3); los cambios de configuración en AWS Config. Centralizarlos en Amazon S3 facilita la retención y las auditorías."},{id:"2.2-t3",taskId:"2.2",objetivos:["2.2#7"],tipo:"definicion",frente:"Cifrado en tránsito y cifrado en reposo: ¿qué protege cada uno?",reverso:"El cifrado en tránsito protege el dato mientras viaja por la red entre el cliente y el servicio. El cifrado en reposo protege el dato almacenado, por ejemplo en un volumen o en un bucket. Se complementan y cubren riesgos distintos."},{id:"2.2-t4",taskId:"2.2",objetivos:["2.2#4","2.2#5"],tipo:"definicion",frente:"¿Dónde se encuentra la información de cumplimiento de AWS?",reverso:"AWS Artifact es el centro de autoservicio donde se descargan informes de auditoría y certificaciones de AWS (por ejemplo, SOC e ISO) y los acuerdos aplicables. Los requisitos varían por geografía e industria, así que hay que revisar la documentación correspondiente al caso concreto."},{id:"2.2-t5",taskId:"2.2",objetivos:["2.2#6"],tipo:"servicio",frente:"Asocia cada servicio con lo que protege: Amazon Inspector, Amazon GuardDuty, AWS Security Hub y AWS Shield.",reverso:"Amazon Inspector evalúa vulnerabilidades; Amazon GuardDuty detecta actividad maliciosa; AWS Security Hub centraliza hallazgos; AWS Shield mitiga ataques de denegación de servicio distribuido (DDoS). Se complementan entre sí."},{id:"2.2-t6",taskId:"2.2",objetivos:["2.2#1"],tipo:"definicion",frente:"Compliance y governance: ¿en qué se diferencian?",reverso:"Compliance es cumplir las normas, leyes y estándares aplicables. Governance es el conjunto de reglas, controles y procesos internos con los que la organización demuestra y mantiene ese cumplimiento en el tiempo."}],2.3:[{id:"2.3-t1",taskId:"2.3",objetivos:["2.3#1"],tipo:"definicion",frente:"¿Qué controla AWS Identity and Access Management (IAM) y en qué se diferencian usuarios, grupos y roles?",reverso:"Controla quién puede hacer qué en una cuenta. El usuario es una identidad con credenciales propias; el grupo reúne usuarios para compartir permisos; el rol es una identidad que se asume temporalmente y no tiene credenciales permanentes. Las políticas definen las acciones permitidas."},{id:"2.3-t2",taskId:"2.3",objetivos:["2.3#3"],tipo:"definicion",frente:"¿Qué exige el principio de menor privilegio?",reverso:"Conceder a cada identidad solo los permisos necesarios para su tarea y durante el tiempo imprescindible. Se implementa con políticas específicas, grupos con permisos mínimos, roles con credenciales temporales y una revisión periódica que retira los permisos sobrantes."},{id:"2.3-t3",taskId:"2.3",objetivos:["2.3#1","2.3#7"],tipo:"diferencia",frente:"Un equipo quiere dar acceso a una aplicación que se ejecuta en AWS. ¿Usuario de IAM o rol de IAM?",reverso:"Rol. Un rol entrega credenciales temporales y no tiene claves permanentes, por lo que es ideal para aplicaciones y accesos entre cuentas. Un usuario con claves de acceso de larga duración solo se justifica cuando no hay alternativa, y exige rotación y almacenamiento seguro."},{id:"2.3-t4",taskId:"2.3",objetivos:["2.3#5"],tipo:"riesgo",frente:"¿Por qué es peligroso guardar una clave de acceso en el código fuente de una aplicación?",reverso:"La clave de acceso es una credencial de larga duración que concede permisos programáticos: si se filtra en un repositorio, cualquiera puede usar la cuenta. Debe almacenarse en AWS Secrets Manager o AWS Systems Manager y rotarse; el código no contiene secretos."},{id:"2.3-t5",taskId:"2.3",objetivos:["2.3#2","2.3#9"],tipo:"definicion",frente:"¿Qué medidas protegen la cuenta raíz (root user)?",reverso:"Activar MFA en el root user, no crear claves de acceso para él, no usarlo para tareas diarias (emplear una identidad administrativa de IAM o IAM Identity Center) y vigilar su actividad con AWS CloudTrail. Así el impacto de una credencial filtrada es mínimo."},{id:"2.3-t6",taskId:"2.3",objetivos:["2.3#4","2.3#10"],tipo:"servicio",frente:"¿Para qué sirve AWS IAM Identity Center frente a crear usuarios de IAM para cada persona?",reverso:"Centraliza el acceso de la plantilla con inicio de sesión único, conecta el directorio o proveedor de identidad corporativo y asigna permission sets por cuenta. Evita un usuario de IAM por persona y por cuenta y encaja con la autenticación federada."}],2.4:[{id:"2.4-t1",taskId:"2.4",objetivos:["2.4#3"],tipo:"diferencia",frente:"Un compañero dice que basta con activar AWS Shield para detener los intentos de inyección en los formularios del sitio. ¿Qué matizas?",reverso:"AWS Shield protege frente a ataques de denegación de servicio distribuido por volumen, no inspecciona el contenido de cada petición. El filtrado de peticiones HTTP(S) maliciosas corresponde a AWS WAF."},{id:"2.4-t2",taskId:"2.4",objetivos:["2.4#3"],tipo:"diferencia",frente:"Separa estas tres funciones: comportamiento sospechoso, vulnerabilidades de las cargas y vista agregada de hallazgos. ¿Qué servicio cubre cada una?",reverso:"Amazon GuardDuty detecta amenazas sobre la actividad; Amazon Inspector evalúa vulnerabilidades y exposición; AWS Security Hub agrega y prioriza los hallazgos en una vista única."},{id:"2.4-t3",taskId:"2.4",objetivos:["2.4#1"],tipo:"definicion",frente:"¿En qué dominios se agrupan las capacidades de seguridad que ofrece AWS?",reverso:"Identidad y acceso, protección de la red y las aplicaciones, detección, protección de datos, visibilidad y auditoría, y cumplimiento. Se combinan: ninguna cubre todo por sí sola."},{id:"2.4-t4",taskId:"2.4",objetivos:["2.4#4"],tipo:"servicio",frente:"¿Dónde encuentra un cliente productos de seguridad de terceros para integrarlos con AWS?",reverso:"En AWS Marketplace, el catálogo donde proveedores independientes publican software y servicios, incluidos productos de seguridad, que el cliente adquiere como suscripciones."},{id:"2.4-t5",taskId:"2.4",objetivos:["2.4#6"],tipo:"servicio",frente:"¿Para qué sirve AWS Trusted Advisor en materia de seguridad?",reverso:"Revisa el entorno y entrega comprobaciones y recomendaciones en categorías como seguridad, rendimiento, tolerancia a fallos, optimización de costes y cuotas de servicio. Señala configuraciones de riesgo, pero no aplica correcciones."},{id:"2.4-t6",taskId:"2.4",objetivos:["2.4#2","2.4#5"],tipo:"definicion",frente:"Empareja cada recurso con su uso: AWS Security Center, AWS Security Blog, AWS Knowledge Center y AWS Artifact.",reverso:"AWS Security Center reúne la información de seguridad; AWS Security Blog publica artículos y novedades; AWS Knowledge Center responde dudas puntuales; AWS Artifact entrega informes de cumplimiento."}],3.1:[{id:"3.1-t1",taskId:"3.1",objetivos:["3.1#2","3.1#4"],tipo:"diferencia",frente:"Un compañero dice: «automatizar es meter los comandos de la CLI en un script; eso ya es infraestructura como código». ¿Qué matiz le falta?",reverso:"Un script de CLI ejecuta acciones concretas en un orden dado, pero no describe necesariamente el estado deseado del entorno. La infraestructura como código describe ese estado en archivos versionados y lo reproduce de forma repetible; la CLI puede formar parte del despliegue, pero no es lo mismo que IaC."},{id:"3.1-t2",taskId:"3.1",objetivos:["3.1#1","3.1#5"],tipo:"definicion",frente:"¿Aprovisionar y operar son lo mismo?",reverso:"No. Aprovisionar es crear y configurar recursos (red, cómputo, almacenamiento, permisos). Operar es mantenerlos, ajustarlos y responder a los cambios. Ambas cosas se pueden hacer a mano o de forma automatizada y repetible."},{id:"3.1-t3",taskId:"3.1",objetivos:["3.1#3","3.1#6"],tipo:"diferencia",frente:"Explica en una frase cloud, híbrido y on-premises.",reverso:"Cloud: todo se ejecuta en la nube de AWS. On-premises: todo se ejecuta en instalaciones propias. Híbrido: parte en instalaciones propias y parte en la nube de AWS, normalmente por normativa, latencia o inversión existente."},{id:"3.1-t4",taskId:"3.1",objetivos:["3.1#2"],tipo:"definicion",frente:"Nombra las formas de acceder a los servicios de AWS.",reverso:"Consola de administración (visual), interfaz de línea de comandos, SDK, API e infraestructura como código. La consola es puntual; las demás son programáticas y permiten automatizar."}],3.2:[{id:"3.2-t1",taskId:"3.2",objetivos:["3.2#5"],tipo:"diferencia",frente:"Un compañero dice: «vamos a desplegar la base de datos en la edge location para que esté más cerca». ¿Qué le corriges?",reverso:"Las edge locations no alojan bases de datos ni cómputo general: son puntos de presencia para entrega de contenido y DNS. La base de datos va en una región, repartida entre sus Availability Zones."},{id:"3.2-t2",taskId:"3.2",objetivos:["3.2#1","3.2#5"],tipo:"definicion",frente:"Ordena de mayor a menor alcance geográfico: Availability Zone, región, edge location.",reverso:"Región (área geográfica con varias AZ) → Availability Zone (centro de datos aislado dentro de la región) → edge location (punto de presencia cerca del usuario, fuera del eje región/AZ)."},{id:"3.2-t3",taskId:"3.2",objetivos:["3.2#2","3.2#6","3.2#7"],tipo:"definicion",frente:"¿Qué hace que desplegar en varias Availability Zones proporcione alta disponibilidad?",reverso:"Cada AZ tiene alimentación, refrigeración y red independientes y no comparten punto único de fallo. Con réplicas en varias AZ, el fallo de una no detiene el servicio; el balanceador reparte el tráfico entre las que siguen activas."}],3.3:[{id:"3.3-t1",taskId:"3.3",objetivos:["3.3#3"],tipo:"diferencia",frente:"Un compañero pregunta: «¿Amazon ECS y Amazon EKS son lo mismo que AWS Fargate?». ¿Qué le aclaras?",reverso:"No. Amazon ECS y Amazon EKS son orquestadores que organizan los contenedores: ECS es propio de AWS y EKS es Kubernetes gestionado. AWS Fargate es un motor de cómputo serverless que ejecuta esos contenedores sin administrar servidores, y se combina con ECS o con EKS."},{id:"3.3-t2",taskId:"3.3",objetivos:["3.3#4"],tipo:"diferencia",frente:"AWS Lambda o AWS Fargate: ¿cuál ejecuta funciones y cuál ejecuta contenedores?",reverso:"AWS Lambda ejecuta funciones disparadas por eventos, pensadas para ejecuciones cortas y sin estado. AWS Fargate ejecuta contenedores sin administrar la infraestructura. Ambos evitan gestionar servidores, pero Lambda se invoca como función y Fargate ejecuta una tarea de contenedor."},{id:"3.3-t3",taskId:"3.3",objetivos:["3.3#2"],tipo:"definicion",frente:"El cuello de botella de una carga es la entrada/salida de disco. ¿Qué familia de instancias de Amazon EC2 encaja mejor?",reverso:"Una familia storage optimized, diseñada para cargas con muchas operaciones de disco y almacenamiento local de alto rendimiento. Si el límite fuera la CPU, encajaría compute optimized; si fuera la memoria, memory optimized."},{id:"3.3-t4",taskId:"3.3",objetivos:["3.3#5"],tipo:"definicion",frente:"¿Cómo aporta AWS Auto Scaling elasticidad a una aplicación?",reverso:"Observa una métrica, por ejemplo el uso de CPU, y ajusta el número de recursos: añade capacidad cuando la demanda crece y la retira cuando baja. Así se atienden los picos sin mantener capacidad fija sobredimensionada el resto del tiempo."},{id:"3.3-t5",taskId:"3.3",objetivos:["3.3#6"],tipo:"definicion",frente:"¿Cuáles son las funciones principales de un balanceador de carga?",reverso:"Repartir el tráfico entrante entre varios destinos, comprobar su estado y dejar de enviar tráfico a los que fallan. Aporta distribución de carga y tolerancia a fallos, y trabaja junto con auto scaling, que decide cuántos destinos existen."},{id:"3.3-t6",taskId:"3.3",objetivos:["3.3#1"],tipo:"servicio",frente:"Ordena de mayor a menor control y responsabilidad operativa: AWS Lambda, Amazon EC2 y contenedores gestionados.",reverso:"Amazon EC2 con control total del servidor, contenedores gestionados con Amazon ECS o Amazon EKS donde tú defines el contenedor y el orquestador lo coordina, y AWS Lambda donde solo existe tu función. A más control, más administración."}],3.4:[{id:"3.4-t1",taskId:"3.4",objetivos:["3.4#4"],tipo:"diferencia",frente:"Un compañero dice que Amazon Aurora es NoSQL porque escala muy bien. ¿Qué le corriges?",reverso:"Amazon Aurora es una base **relacional** compatible con MySQL y PostgreSQL: se consulta con SQL y los datos viven en tablas. Su escalado y su almacenamiento distribuido no la convierten en NoSQL; para NoSQL está Amazon DynamoDB."},{id:"3.4-t2",taskId:"3.4",objetivos:["3.4#5"],tipo:"servicio",frente:"¿Qué es Amazon DynamoDB y para qué tipo de acceso está pensado?",reverso:"Base **NoSQL** gestionada de clave-valor y documento, sin esquema fijo y con escalado horizontal. Está pensada para acceder al dato por clave con latencia de milisegundos y tráfico impredecible, sin administrar servidores."},{id:"3.4-t3",taskId:"3.4",objetivos:["3.4#5","3.4#6"],tipo:"diferencia",frente:"¿En qué se diferencia Amazon DynamoDB de Amazon ElastiCache?",reverso:"Amazon DynamoDB es una base **persistente** NoSQL y la fuente de verdad de esos datos; Amazon ElastiCache es un almacén **en memoria** que se usa como **caché** delante de otra base. DynamoDB guarda; ElastiCache acelera."},{id:"3.4-t4",taskId:"3.4",objetivos:["3.4#7","3.4#2"],tipo:"diferencia",frente:"En una migración, ¿qué hace AWS DMS y qué hace AWS SCT?",reverso:"`AWS Database Migration Service (AWS DMS)` mueve y **replica los datos** entre origen y destino, con replicación continua para reducir el corte. `AWS Schema Conversion Tool (AWS SCT)` convierte el **esquema y el código** entre motores. Se combinan en las migraciones heterogéneas."},{id:"3.4-t5",taskId:"3.4",objetivos:["3.4#3"],tipo:"tradeoff",frente:"¿Qué se gana y qué se pierde al alojar una base de datos en Amazon EC2 en lugar de usar un servicio gestionado?",reverso:"Se gana **control** total del motor, la versión y el sistema operativo. Se pierde la administración automática: el equipo asume parches, copias de seguridad, alta disponibilidad y escalado, con más esfuerzo operativo y riesgo."}],3.5:[{id:"3.5-t1",taskId:"3.5",objetivos:["3.5#5"],tipo:"diferencia",frente:"Un compañero dice: «con AWS VPN tenemos un enlace privado que no pasa por internet». ¿Qué le corriges?",reverso:"AWS VPN levanta un túnel cifrado que sí viaja por internet; lo que no atraviesa internet es AWS Direct Connect, que es un enlace dedicado y privado. La VPN es más rápida de desplegar y la conexión dedicada aporta un rendimiento más estable."},{id:"3.5-t2",taskId:"3.5",objetivos:["3.5#3"],tipo:"definicion",frente:"¿En qué se diferencian un security group y un network ACL?",reverso:"El security group es con estado, se asocia a recursos y solo admite reglas de permiso. El network ACL es sin estado, se asocia a una subred y admite reglas de permiso y de denegación, evaluadas por orden."},{id:"3.5-t3",taskId:"3.5",objetivos:["3.5#2"],tipo:"definicion",frente:"¿Qué hace que una subred sea pública dentro de una VPC?",reverso:"Que la VPC tenga un internet gateway asociado y que la route table de la subred envíe el tráfico hacia ese gateway. Una subred sin esa ruta queda privada, aunque su rango de direcciones sea válido."},{id:"3.5-t4",taskId:"3.5",objetivos:["3.5#4"],tipo:"servicio",frente:"¿Cuál es el propósito de Amazon Route 53?",reverso:"Es el servicio de DNS administrado: registra dominios, resuelve nombres hacia direcciones o destinos de AWS y aplica políticas de enrutamiento y comprobaciones de estado. No aloja contenido ni reparte conexiones como un balanceador de carga."}],3.6:[{id:"3.6-t1",taskId:"3.6",objetivos:["3.6#1","3.6#2"],tipo:"definicion",frente:"¿Qué es el almacenamiento de objetos y qué usos tiene?",reverso:"Guarda cada dato como un objeto completo con metadatos y una clave, dentro de un contenedor plano, y se accede por API. Encaja en contenido estático, copias de seguridad, data lakes y cualquier dato que se lea y escriba como un todo, no por bloques."},{id:"3.6-t2",taskId:"3.6",objetivos:["3.6#3"],tipo:"diferencia",frente:"Un compañero quiere consultar cada día objetos guardados en la clase de archivado profundo. ¿Qué le explicas?",reverso:"Las clases de archivado abaratan el almacenamiento a cambio de una recuperación lenta y con coste por acceso. Para consultas diarias conviene una clase de acceso inmediato, y una política de ciclo de vida para transicionar a clases frías solo cuando el objeto deja de consultarse."},{id:"3.6-t3",taskId:"3.6",objetivos:["3.6#4"],tipo:"diferencia",frente:"¿Cuándo usarías Amazon EBS y cuándo el instance store?",reverso:"Amazon EBS es un volumen de bloque persistente de red, con snapshots, cifrado y cambio de tamaño, ideal para datos que deben sobrevivir a la instancia. El instance store es local y efímero: se reserva para cachés o datos reconstruibles que priorizan el máximo rendimiento."},{id:"3.6-t4",taskId:"3.6",objetivos:["3.6#5","3.6#6"],tipo:"diferencia",frente:"¿Cómo diferencias Amazon EFS y Amazon FSx de AWS Storage Gateway?",reverso:"Amazon EFS (elástico, para Linux) y Amazon FSx (motores concretos, como Windows File Server o Lustre) son sistemas de archivos gestionados en AWS. AWS Storage Gateway es la puerta de enlace híbrida que sirve con caché local datos que viven en AWS."},{id:"3.6-t5",taskId:"3.6",objetivos:["3.6#7","3.6#8"],tipo:"tradeoff",frente:"¿En qué se diferencian una política de ciclo de vida y AWS Backup?",reverso:"La política de ciclo de vida optimiza el coste del dato vivo moviéndolo entre clases de almacenamiento o expirándolo. AWS Backup crea copias recuperables con retención definida sobre varios servicios. Abaratar el dato no es lo mismo que protegerlo: una transición de clase no es una copia de seguridad."},{id:"3.6-t6",taskId:"3.6",objetivos:["3.6#1"],tipo:"definicion",frente:"¿Qué distingue el almacenamiento de objetos, el de bloque y el de archivos?",reverso:"Objetos: datos completos con metadatos por API. Bloque: volúmenes tipo disco para una instancia. Archivos: sistema de archivos compartido por red entre varias instancias. Los tres modelos resuelven necesidades distintas y no son intercambiables."}],3.7:[{id:"3.7-t1",taskId:"3.7",objetivos:["3.7#1","3.7#3"],tipo:"servicio",frente:"Relaciona cada servicio de IA/ML con la tarea que resuelve: Amazon Rekognition, Amazon Comprehend, Amazon Textract, Amazon Transcribe, Amazon Polly, Amazon Lex y Amazon SageMaker AI.",reverso:"Rekognition: imágenes y vídeo. Comprehend: lenguaje natural sobre texto. Textract: extraer texto y campos de documentos. Transcribe: voz a texto. Polly: texto a voz. Lex: asistentes conversacionales. SageMaker AI: construir, entrenar y desplegar modelos propios."},{id:"3.7-t2",taskId:"3.7",objetivos:["3.7#3"],tipo:"diferencia",frente:"¿Cuál es la diferencia entre Amazon Transcribe y Amazon Polly?",reverso:"Amazon Transcribe convierte voz en texto (speech-to-text); Amazon Polly convierte texto en voz (text-to-speech). Son las dos direcciones opuestas del mismo par voz/texto."},{id:"3.7-t3",taskId:"3.7",objetivos:["3.7#4"],tipo:"diferencia",frente:"Un compañero confunde Amazon Athena, AWS Glue y Amazon Kinesis. ¿Cómo los distingues?",reverso:"Amazon Athena consulta con SQL datos ya almacenados (por ejemplo, en Amazon S3); AWS Glue cataloga y ejecuta ETL para preparar esos datos; Amazon Kinesis ingiere y procesa datos en streaming, en tiempo real."},{id:"3.7-t4",taskId:"3.7",objetivos:["3.7#2","3.7#4"],tipo:"definicion",frente:"¿Qué servicio de analítica usarías para un almacén analítico, para buscar en registros, para procesamiento masivo y para un panel de negocio?",reverso:"Almacén analítico: Amazon Redshift. Búsqueda y análisis de registros: Amazon OpenSearch Service. Procesamiento de grandes volúmenes: Amazon EMR. Paneles y visualización: Amazon Quick Sight."},{id:"3.7-t5",taskId:"3.7",objetivos:["3.7#1","3.7#3"],tipo:"servicio",frente:"¿Cuándo eliges Amazon SageMaker AI en lugar de un servicio de IA ya entrenado?",reverso:"Cuando necesitas un modelo propio entrenado con tus datos y control sobre el entrenamiento y el despliegue. Si la tarea es estándar, un servicio ya entrenado la resuelve sin entrenar nada."}],3.8:[{id:"3.8-t1",taskId:"3.8",objetivos:["3.8#1"],tipo:"definicion",frente:"¿Qué patrón de integración representa cada servicio: Amazon Simple Queue Service (Amazon SQS), Amazon Simple Notification Service (Amazon SNS) y Amazon EventBridge?",reverso:"Amazon SQS es una cola (el consumidor retira el mensaje, desacopla y acumula trabajo); Amazon SNS es publicación/suscripción (difunde a muchos suscriptores, para alertas y notificaciones); Amazon EventBridge es un bus de eventos (reacciona y enruta según reglas)."},{id:"3.8-t2",taskId:"3.8",objetivos:["3.8#8"],tipo:"tradeoff",frente:"Debes entregar un mensaje a un único consumidor que lo procesará después, avisar de inmediato a muchos suscriptores y reaccionar a eventos de otros servicios. ¿Qué servicios eliges?",reverso:"Para el trabajo encolado, Amazon Simple Queue Service (Amazon SQS); para la alerta inmediata a varios destinatarios, Amazon Simple Notification Service (Amazon SNS); para reaccionar y enrutar eventos según reglas, Amazon EventBridge. La clave es cola frente a pub/sub frente a bus de eventos."},{id:"3.8-t3",taskId:"3.8",objetivos:["3.8#2"],tipo:"servicio",frente:"¿Qué aplicación de negocio cubre la voz y el chat, y cuál el correo electrónico a escala?",reverso:"Amazon Connect es el centro de contacto omnicanal (llamadas y chat) y Amazon Simple Email Service (Amazon SES) es el servicio de correo electrónico a escala. Se eligen por canal: voz/chat frente a correo."},{id:"3.8-t4",taskId:"3.8",objetivos:["3.8#3","3.8#10"],tipo:"servicio",frente:"¿Qué plan de AWS Support conviene a una carga crítica que exige cobertura 24/7 y un Technical Account Manager (TAM)?",reverso:"AWS Enterprise Support: incluye cobertura para cargas críticas, tiempos de respuesta mínimos y Technical Account Manager (TAM). El plan Basic no tiene soporte de producción, y AWS Business Support cubre producción 24/7 sin TAM."},{id:"3.8-t5",taskId:"3.8",objetivos:["3.8#4","3.8#11"],tipo:"definicion",frente:"¿Qué hace cada herramienta de desarrollo: AWS CodeBuild, AWS CodePipeline y AWS X-Ray?",reverso:"AWS CodeBuild compila, ejecuta pruebas y produce el artefacto; AWS CodePipeline coordina las etapas de la canalización de principio a fin; AWS X-Ray rastrea solicitudes para depurar errores y latencia."},{id:"3.8-t6",taskId:"3.8",objetivos:["3.8#5","3.8#12"],tipo:"diferencia",frente:"¿Qué diferencia hay entre Amazon AppStream 2.0, Amazon WorkSpaces y Amazon WorkSpaces Secure Browser?",reverso:"Amazon AppStream 2.0 publica aplicaciones concretas por streaming; Amazon WorkSpaces entrega un escritorio virtual completo y persistente por usuario; Amazon WorkSpaces Secure Browser ofrece un navegador aislado para acceso web seguro. En los tres, el cómputo corre en AWS."},{id:"3.8-t7",taskId:"3.8",objetivos:["3.8#6","3.8#13"],tipo:"servicio",frente:"¿Con qué servicio se crean y despliegan aplicaciones web y móviles integrando autenticación, APIs y hosting?",reverso:"AWS Amplify: ofrece un flujo guiado para construir el frontend, conectar capacidades y desplegar la aplicación web o móvil, apoyándose por debajo en servicios como Amazon Cognito, Amazon API Gateway, Amazon S3 y Amazon CloudFront."},{id:"3.8-t8",taskId:"3.8",objetivos:["3.8#7","3.8#14"],tipo:"servicio",frente:"¿Qué servicio conecta, autentica y administra dispositivos IoT y recibe sus datos?",reverso:"AWS IoT Core: registra la identidad de cada dispositivo, autentica su conexión, recibe los mensajes publicados (por ejemplo, con MQTT) y los enruta a otros servicios con reglas, como AWS Lambda o Amazon S3."}],4.1:[{id:"4.1-t1",taskId:"4.1",objetivos:["4.1#3"],tipo:"tradeoff",frente:"Un arquitecto duda entre Spot Instances y un compromiso de 1 o 3 años para un servicio crítico que no admite interrupciones. ¿Qué le recomiendas?",reverso:"Si el servicio no tolera interrupciones, descarta Spot y evalúa Reserved Instances o AWS Savings Plans para el uso estable. Spot solo encaja en cargas tolerantes a fallos, como lotes o tareas stateless."},{id:"4.1-t2",taskId:"4.1",objetivos:["4.1#4"],tipo:"diferencia",frente:"¿Qué diferencia hay entre una Reserved Instance Standard y una Convertible?",reverso:"Standard da el descuento máximo y no puede modificarse ni intercambiarse; Convertible permite cambiar familia, sistema operativo, tenancy o modalidad de pago por otra Convertible de valor igual o mayor, con un descuento algo menor."},{id:"4.1-t3",taskId:"4.1",objetivos:["4.1#5"],tipo:"definicion",frente:"¿Qué pasa con las Reserved Instances no usadas en una organización con varias cuentas?",reverso:"Con la facturación consolidada se comparten por defecto: primero cubren el uso de la cuenta compradora y el descuento sobrante se aplica a las demás cuentas. La cuenta de administración puede desactivar esa compartición."},{id:"4.1-t4",taskId:"4.1",objetivos:["4.1#1"],tipo:"servicio",frente:"Dedicated Hosts, Dedicated Instances y Capacity Reservations: ¿qué problema resuelve cada opción?",reverso:"Dedicated Hosts dan un servidor físico completo con control de sockets y núcleos (útil para BYOL). Dedicated Instances corren en hardware dedicado a un único cliente sin control del host. Capacity Reservations garantizan capacidad en una Availability Zone concreta sin compromiso de plazo, pagando la tarifa On-Demand se use o no."},{id:"4.1-t5",taskId:"4.1",objetivos:["4.1#2","4.1#7"],tipo:"definicion",frente:"¿Cómo se ordena el precio de almacenamiento entre S3 Standard, las clases de acceso poco frecuente y las clases de archivo?",reverso:"Es más caro en las clases de acceso frecuente (Standard) y más barato en las de archivo, pero las clases de bajo coste añaden latencia de recuperación y, según la clase, cargos por recuperación. Las políticas de ciclo de vida hacen el traslado automático."},{id:"4.1-t6",taskId:"4.1",objetivos:["4.1#6"],tipo:"definicion",frente:"¿Qué transferencia de datos se factura y cuál suele ser gratuita?",reverso:"La entrada de datos desde internet a AWS suele ser gratuita; la salida a internet y el cruce entre Availability Zones o entre regiones se facturan por GB. El tráfico dentro de la misma AZ con direcciones privadas no genera ese cargo de cruce."}],4.2:[{id:"4.2-t1",taskId:"4.2",objetivos:["4.2#5","4.2#6"],tipo:"diferencia",frente:"Te piden estimar el costo de una arquitectura que todavía no existe y, por separado, entender el gasto del mes pasado. ¿Qué herramienta usas en cada caso?",reverso:"Para estimar lo que aún no existe, AWS Pricing Calculator: modela la arquitectura y devuelve un costo aproximado sin desplegar recursos. Para entender el gasto ya realizado, AWS Cost Explorer: muestra el costo y el uso registrados y permite agrupar y filtrar. Vigilar un límite es tarea de AWS Budgets."},{id:"4.2-t2",taskId:"4.2",objetivos:["4.2#3","4.2#7"],tipo:"definicion",frente:"¿Qué es la facturación consolidada de AWS Organizations?",reverso:"Es la factura única que reúne el uso de todas las cuentas miembro, pagada por la cuenta de gestión. Además de simplificar el pago, el uso agregado puede alcanzar antes los descuentos por volumen, pero no reparte el costo entre equipos: para eso hacen falta etiquetas de asignación de costos e informes."},{id:"4.2-t3",taskId:"4.2",objetivos:["4.2#4","4.2#8"],tipo:"definicion",frente:"Acabas de etiquetar todos los recursos con el equipo y el proyecto. ¿Por qué no aparecen esas etiquetas en los informes de facturación?",reverso:"Porque etiquetar no basta: hay que activarlas como etiquetas de asignación de costos. Solo entonces se propagan a los datos de facturación y aparecen en cada línea del informe de costos y uso, donde se pueden usar para agrupar y filtrar el gasto."},{id:"4.2-t4",taskId:"4.2",objetivos:["4.2#1","4.2#2"],tipo:"servicio",frente:"¿Dónde se consultan las facturas y los precios de los servicios de AWS?",reverso:"Las facturas, el uso y el historial de pagos se consultan en la consola de facturación y gestión de costos; las dudas sobre cargos se atienden por AWS Support. La información de precios es pública en la página de precios de cada servicio, y AWS Pricing Calculator permite estimar el costo de una arquitectura antes de crearla."}],4.3:[{id:"4.3-t1",taskId:"4.3",objetivos:["4.3#7"],tipo:"diferencia",frente:"Un compañero dice que Basic Support basta para que AWS atienda un incidente de producción. ¿Qué le corriges?",reverso:"Basic Support viene incluido en toda cuenta, pero no abre casos técnicos: solo cubre facturación y cuenta. Para incidentes de producción con atención 24/7 y tiempos de respuesta comprometidos se necesita al menos AWS Business Support."},{id:"4.3-t2",taskId:"4.3",objetivos:["4.3#1","4.3#6"],tipo:"definicion",frente:"Asocia cada necesidad con su recurso oficial: comportamiento exacto de un servicio, patrón de migración e incidente de cuenta.",reverso:"Comportamiento exacto → documentación del servicio. Patrón de migración → AWS Prescriptive Guidance o un whitepaper. Incidente de cuenta → un caso en el AWS Support Center. Para dudas frecuentes, AWS Knowledge Center; para experiencia de la comunidad, AWS re:Post."},{id:"4.3-t3",taskId:"4.3",objetivos:["4.3#8"],tipo:"servicio",frente:"¿En qué categorías recomienda AWS Trusted Advisor?",reverso:"Optimización de costos, seguridad, tolerancia a fallos, rendimiento y cuotas de servicio. Solo recomienda: el cliente decide y aplica los cambios. Las comprobaciones completas requieren un plan de soporte de negocio o superior."},{id:"4.3-t4",taskId:"4.3",objetivos:["4.3#2","4.3#7"],tipo:"diferencia",frente:"¿Qué separa a AWS Developer Support de AWS Business Support?",reverso:"AWS Developer Support ofrece asistencia por correo en horario laboral y un contacto designado, pensada para desarrollo y pruebas. AWS Business Support añade atención 24/7 por teléfono, chat y correo, tiempos de respuesta más cortos y todas las comprobaciones de AWS Trusted Advisor."},{id:"4.3-t5",taskId:"4.3",objetivos:["4.3#3","4.3#10","4.3#12"],tipo:"servicio",frente:"¿Qué papel cumplen un system integrator y un independent software vendor frente a AWS?",reverso:"El system integrator (consulting partner) diseña, migra y opera soluciones para los clientes. El independent software vendor (technology partner) construye productos de software y los comercializa, por ejemplo a través de AWS Marketplace."},{id:"4.3-t6",taskId:"4.3",objetivos:["4.3#9"],tipo:"riesgo",frente:"Detectas que una instancia de tu cuenta se usa para enviar spam. ¿A quién lo comunicas?",reverso:"Al equipo de AWS Trust and Safety, que gestiona las denuncias de uso abusivo de recursos de AWS, como spam, phishing o contenido ilícito. No es un canal de soporte técnico."},{id:"4.3-t7",taskId:"4.3",objetivos:["4.3#4","4.3#13"],tipo:"servicio",frente:"¿Qué diferencia hay entre el AWS Support Center y AWS Professional Services?",reverso:"El AWS Support Center es donde se abren y se siguen los casos de soporte de la cuenta. AWS Professional Services es un equipo de consultoría que acompaña proyectos concretos, como migraciones o modernizaciones."},{id:"4.3-t8",taskId:"4.3",objetivos:["4.3#11"],tipo:"definicion",frente:"Nombra tres beneficios de ser partner de AWS.",reverso:"Formación y certificación de partners, acceso a eventos de partners y descuentos por volumen en los programas que los ofrecen."}]},c={1.1:[{id:"alta-disponibilidad-vs-elasticidad-vs-agilidad",etiqueta:"Alta disponibilidad vs elasticidad y agilidad",a:{titulo:"Alta disponibilidad",resumen:"Capacidad de seguir atendiendo el servicio aunque falle un componente. Se consigue con redundancia activa, por ejemplo repartiendo la carga entre varias Availability Zones."},b:{titulo:"Elasticidad y agilidad",resumen:"La elasticidad ajusta la capacidad de forma automática a la demanda; la agilidad es la velocidad para crear, probar y cambiar. Ninguna de las dos evita por sí sola una interrupción por fallo."},diferenciaClave:"La alta disponibilidad responde a los fallos (seguir en marcha); la elasticidad responde a la demanda (más o menos capacidad); la agilidad responde al tiempo de cambio (innovar rápido).",cuandoA:["Cuando el servicio no puede interrumpirse y necesitas tolerancia al fallo de una zona.","Cuando cada componente debe tener réplica para no ser un punto único de fallo."],cuandoB:["Cuando la carga varía y quieres pagar solo por la capacidad que usas.","Cuando necesitas probar ideas nuevas en poco tiempo sin comprar infraestructura."],escenarioA:"Una aplicación crítica se despliega en dos Availability Zones con un balanceador que reparte el tráfico: si una zona falla, la otra sigue atendiendo.",escenarioB:"La misma aplicación añade recursos cuando sube el tráfico de la campaña y los retira al terminar, y el equipo publica una versión nueva en días porque no depende de comprar servidores.",preguntaIds:["1.1-q6"],objetivos:["1.1#3"]},{id:"velocidad-despliegue-vs-alcance-global",etiqueta:"Velocidad de despliegue vs alcance global",a:{titulo:"Velocidad de despliegue",resumen:"La infraestructura global permite crear recursos en la región elegida en minutos, sin esperar a comprar ni montar hardware. Responde a cuánto tarda una idea en llegar a producción."},b:{titulo:"Alcance global",resumen:"La misma plataforma está disponible en muchas zonas geográficas, de modo que una aplicación puede atender a usuarios de varios continentes sin abrir centros de datos propios."},diferenciaClave:"La velocidad de despliegue mide el tiempo de puesta en marcha; el alcance global mide la cobertura geográfica. Ambas nacen de la infraestructura global, pero responden a problemas distintos: el plazo y la audiencia.",cuandoA:["Cuando el plazo es el requisito principal y hay que poner recursos en producción cuanto antes.","Cuando el equipo necesita experimentar rápido sin comprar infraestructura propia."],cuandoB:["Cuando la audiencia está repartida por varios continentes y hay que servirla sin abrir centros de datos en cada país.","Cuando conviene desplegar en la región cercana a cada grupo de usuarios."],escenarioA:"Una startup debe publicar su aplicación en dos semanas: aprovisiona los recursos en minutos en lugar de esperar a comprar y montar servidores.",escenarioB:"La misma aplicación atiende después a clientes de tres continentes desplegando en varias regiones, sin construir infraestructura propia en cada país.",preguntaIds:["1.1-q10"],objetivos:["1.1#2"]}],1.2:[{id:"well-architected-pillars",etiqueta:"Pilares de operación y riesgo vs pilares de eficiencia y economía",a:{titulo:"Pilares de operación y riesgo",resumen:"Operational excellence, security y reliability miran cómo se opera la carga, cómo se protege y cómo sobrevive a los fallos. Responden a las preguntas de proceso, protección y continuidad del servicio."},b:{titulo:"Pilares de eficiencia y economía",resumen:"Performance efficiency, cost optimization y sustainability miran cómo se usan los recursos, cuánto cuestan y qué consumo generan. Responden a las preguntas de adecuación, gasto y sostenibilidad."},diferenciaClave:"Cada pilar responde a una pregunta distinta: los primeros protegen y mantienen el servicio en marcha; los segundos ajustan los recursos y el gasto. Un cambio técnico puede mejorar un grupo y empeorar el otro, y la revisión busca el equilibrio, no un pilar ganador.",cuandoA:["Cuando el problema es un fallo, una interrupción, una brecha de seguridad o la falta de un proceso operativo.","Cuando hay que decidir redundancia, controles de acceso, automatización de despliegues o respuesta a incidentes."],cuandoB:["Cuando el problema es lentitud, sobredimensionamiento, gasto innecesario o desperdicio de recursos.","Cuando hay que elegir el tamaño y el tipo de recurso, el modelo de uso o cómo reducir el consumo de la carga."],escenarioA:"Una plataforma sufre cortes cuando se cae una ubicación y, además, nadie tiene runbooks ni despliegues automatizados. El equipo ataca el problema con redundancia y recuperación (reliability) y con procedimientos y automatización (operational excellence).",escenarioB:"La misma plataforma responde lenta en horas punta y la factura creció por recursos ociosos. El equipo corrige eligiendo mejor el tipo y tamaño de recurso y escalando con la demanda (performance efficiency), reduciendo el gasto (cost optimization) y evitando desperdicio (sustainability).",preguntaIds:["1.2-q3","1.2-q6"],objetivos:["1.2#2","1.2#3"]}],1.3:[{id:"caf-vs-well-architected",etiqueta:"AWS CAF vs AWS Well-Architected Framework",a:{titulo:"AWS Cloud Adoption Framework (AWS CAF)",resumen:"Marco de adopción organizativa. Organiza el cambio en seis perspectivas (Business, People, Governance, Platform, Security y Operations) y busca resultados de negocio: menor riesgo, mejor desempeño ESG, más ingresos y más eficiencia operativa."},b:{titulo:"AWS Well-Architected Framework",resumen:"Marco de diseño técnico de cargas de trabajo. Evalúa y mejora la arquitectura con seis pilares: excelencia operativa, seguridad, fiabilidad, eficiencia del rendimiento, optimización de costes y sostenibilidad."},diferenciaClave:"El AWS CAF actúa sobre la organización y el negocio (adopción, personas y gobernanza); el AWS Well-Architected Framework actúa sobre la arquitectura técnica de cada carga. Uno planifica el viaje; el otro revisa el diseño.",cuandoA:["Cuando la organización necesita ordenar la adopción: estrategia, personas, gobernanza, plataforma, seguridad y operaciones.","Cuando la dirección pide justificar el valor de negocio y gestionar el riesgo del cambio."],cuandoB:["Cuando hay que evaluar y mejorar el diseño técnico de una carga de trabajo concreta.","Cuando se buscan decisiones de arquitectura equilibradas entre fiabilidad, seguridad, coste y rendimiento."],escenarioA:"Una empresa va a migrar a AWS y necesita alinear a negocio, recursos humanos y tecnología: define perspectivas y capacidades para que finanzas vea el retorno y las personas estén preparadas para el cambio.",escenarioB:"El equipo de una aplicación ya diseñada revisa su arquitectura frente a los pilares para decidir si conviene mejorar la tolerancia a fallos o el uso de servicios gestionados.",preguntaIds:["1.3-q5"],objetivos:["1.3#3"]},{id:"rehost-vs-replataforma",etiqueta:"Rehost vs replatform",a:{titulo:"Rehost (lift and shift)",resumen:"Mover la aplicación tal cual a AWS, normalmente a servidores equivalentes, sin tocar su arquitectura ni su configuración salvo lo imprescindible. Prioriza la velocidad de salida."},b:{titulo:"Replatform (lift, tuck and reshape)",resumen:"Migrar con ajustes acotados para aprovechar servicios gestionados, por ejemplo cambiar un motor autogestionado por uno gestionado. Equilibra esfuerzo y beneficio operativo."},diferenciaClave:"Rehost no modifica la aplicación y gana rapidez; replatform introduce cambios limitados y a cambio reduce la carga operativa. El rediseño profundo pertenece a refactor, no a estas dos.",cuandoA:["Cuando el plazo manda y se necesita salir del centro de datos cuanto antes.","Cuando la aplicación se va a retirar pronto o no interesa invertir en rediseñarla."],cuandoB:["Cuando un cambio acotado permite delegar operación en servicios gestionados.","Cuando el equipo puede asumir una ventana de ajuste a cambio de menor coste operativo a largo plazo."],escenarioA:"Una empresa debe abandonar su centro de datos en tres meses y traslada sus servidores a AWS sin cambios para cumplir la fecha.",escenarioB:"La misma empresa migra su base de datos autogestionada a un motor gestionado para reducir las tareas de mantenimiento y parcheo.",preguntaIds:["1.3-q8"],objetivos:["1.3#4"]}],1.4:[{id:"costes-fijos-vs-variables",etiqueta:"Coste fijo on-premises vs coste variable en la nube",a:{titulo:"Costes fijos (on-premises)",resumen:"Inversión que se paga por adelantado y no cambia con el uso: servidores, almacenamiento, licencias perpetuas, obra y equipamiento del centro de datos. Se incurre en ella aunque la capacidad quede ociosa e incluye costes indirectos como energía, refrigeración, espacio y personal de mantenimiento."},b:{titulo:"Costes variables (nube)",resumen:"Gasto que sigue al consumo real: horas de cómputo, GB almacenados o transferencia de datos. Si el recurso no se usa, no se factura, y la capacidad se ajusta con elasticidad en lugar de comprarse para el pico."},diferenciaClave:"El coste fijo se decide antes de conocer la demanda y se paga aunque no se use; el coste variable se decide según la demanda y desaparece cuando el consumo baja. On-premises concentra fijos e indirectos; la nube convierte buena parte de ese gasto en variable.",cuandoA:["Cuando se compra hardware para el pico de tráfico previsto, con capacidad que quedará ociosa el resto del tiempo.","Cuando hay que asumir energía, refrigeración, espacio y personal aunque la demanda sea baja."],cuandoB:["Cuando la demanda es variable o difícil de predecir y conviene pagar solo lo consumido.","Cuando se quiere evitar la inversión inicial y trasladar el gasto a medida que crece el uso."],escenarioA:"Una empresa compra servidores sobredimensionados para el pico anual y los mantiene encendidos todo el año: paga por adelantado una capacidad que solo usa unas semanas.",escenarioB:"La misma carga se ejecuta en la nube con capacidad elástica: en el pico escala y el resto del tiempo reduce recursos, de modo que la factura sigue al consumo.",preguntaIds:["1.4-q2"],objetivos:["1.4#1","1.4#3","1.4#4"]},{id:"byol-vs-licencias-incluidas",etiqueta:"BYOL vs licencias incluidas",a:{titulo:"BYOL (Bring Your Own License)",resumen:"La organización reutiliza las licencias de software que ya posee y paga aparte solo la infraestructura. Aprovecha la inversión previa, pero exige gestionar el cumplimiento y los términos de cada licencia."},b:{titulo:"Licencias incluidas",resumen:"El software viene con el servicio y su coste forma parte del precio. Simplifica la gestión, pero puede salir más caro si la organización ya tenía licencias propias en propiedad."},diferenciaClave:"BYOL parte de licencias ya adquiridas y factura solo la infraestructura; las incluidas evitan esa gestión porque el coste va dentro del servicio. Ninguna es siempre más barata: depende de qué licencias se tengan y de lo que cueste gestionarlas.",cuandoA:["Cuando la organización ya posee licencias válidas para el entorno elegido y puede cumplir sus términos.","Cuando interesa aprovechar una inversión previa en software en lugar de pagar la licencia otra vez."],cuandoB:["Cuando se prefiere no gestionar licencias y se acepta que su coste vaya dentro del precio del servicio.","Cuando no se dispone de licencias propias reutilizables para ese software."],escenarioA:"Una empresa que renovó licencias de base de datos hace un año las lleva a la nube y paga solo la infraestructura donde las ejecuta.",escenarioB:"Otra empresa sin licencias propias contrata el servicio con la licencia incorporada y evita comprar y gestionar licencias por separado.",preguntaIds:["1.4-q15"],objetivos:["1.4#5"]},{id:"rightsizing-vs-capacidad-fija",etiqueta:"Right-sizing vs capacidad fija",a:{titulo:"Right-sizing",resumen:"Ajustar de forma continua el tamaño o el tipo de recurso a la carga real medida. Sube o baja la capacidad según las métricas y evita pagar por lo que no se aprovecha."},b:{titulo:"Capacidad fija",resumen:"Dimensionar los recursos de antemano y mantenerlos. Se paga la capacidad completa aunque quede ociosa, y no se corrige hasta que alguien revisa el dimensionado."},diferenciaClave:"El right-sizing usa métricas de uso para ajustar el tamaño de forma continua; la capacidad fija se decide antes de conocer la demanda y se paga tal cual. Un recurso sobredimensionado y fijo acumula coste aunque no aporte rendimiento.",cuandoA:["Cuando las métricas muestran recursos muy por debajo o por encima de su capacidad.","Cuando la carga cambia y conviene revisar el tamaño de forma periódica."],cuandoB:["Cuando la capacidad se decide antes de conocer la demanda y no se revisa el dimensionado.","Cuando se mantiene el tamaño por inercia aunque el uso real sea muy inferior."],escenarioA:"Un equipo observa que sus servidores usan menos del 10 % de CPU y reduce el tamaño de los recursos, revisando las métricas cada mes.",escenarioB:"El mismo equipo compró instancias grandes para el pico y las mantiene todo el año, pagando capacidad que solo necesita unas semanas.",preguntaIds:["1.4-q16"],objetivos:["1.4#6"]},{id:"automatizacion-vs-operacion-manual",etiqueta:"Automatización vs operación manual",a:{titulo:"Automatización",resumen:"Aplicar acciones de forma repetible sin intervención: apagar recursos fuera de horario, escalar según la demanda o aplicar cambios reproducibles. Reduce el trabajo manual y los olvidos."},b:{titulo:"Operación manual",resumen:"Ejecutar cada tarea a mano cuando alguien lo recuerda. Depende de la disponibilidad y la atención de la persona, por lo que es propensa a olvidos y a resultados inconsistentes."},diferenciaClave:"La automatización garantiza que la acción se cumpla siempre igual; la operación manual depende de que alguien la ejecute a tiempo. Un recurso encendido por olvido es el coste típico de la gestión manual.",cuandoA:["Cuando hay tareas repetitivas de ahorro, como apagar entornos fuera de horario o escalar con la demanda.","Cuando el resultado debe ser consistente y no depender de la memoria de una persona."],cuandoB:["Cuando se hacen tareas puntuales donde no compensa automatizar, como un ajuste único.","Cuando el proceso aún no está definido y no se puede ejecutar de forma repetible."],escenarioA:"Un equipo programa el apagado y encendido de los entornos de desarrollo según un horario y deja de pagar recursos ociosos por las noches.",escenarioB:"Otro equipo apaga los entornos a mano y algunos fines de semana olvida hacerlo, de modo que esos recursos siguen facturando.",preguntaIds:["1.4-q17"],objetivos:["1.4#7"]}],2.1:[{id:"responsabilidad-compartida-cliente-vs-aws",etiqueta:"Cliente frente a AWS en el modelo de responsabilidad compartida",a:{titulo:"Cliente: seguridad en la nube",resumen:"Responsabilidad del cliente sobre lo que pone y configura dentro de la nube: datos, identidades y permisos, aplicaciones, sistema operativo invitado y ajustes de red y cifrado de los recursos que contrata."},b:{titulo:"AWS: seguridad de la nube",resumen:"Responsabilidad de AWS sobre la infraestructura que ejecuta los servicios: instalaciones físicas, hardware, red, capa de virtualización y el software del propio servicio gestionado."},diferenciaClave:"El cliente responde de lo que configura en la nube; AWS responde de la infraestructura que hace posible la nube. La frontera se mueve según el servicio contratado, pero ninguna de las dos partes cubre la mitad de la otra.",cuandoA:["Cuando hay que asegurar los datos, gestionar identidades y permisos o configurar correctamente el servicio.","Cuando se parchea el sistema operativo invitado, se mantiene la aplicación o se define el cifrado de los recursos."],cuandoB:["Cuando se trata de la seguridad física de los centros de datos, el hardware, la red troncal o la capa de virtualización.","Cuando hay que mantener el software de un servicio gestionado, como el motor de base de datos o el entorno de ejecución serverless."],escenarioA:"Un equipo define políticas de acceso, cifra sus datos y aplica parches al sistema operativo invitado de sus instancias, porque esas capas están bajo su control.",escenarioB:"AWS mantiene las instalaciones, el hardware, la red y la capa de virtualización que alojan las instancias, algo que el cliente no puede controlar ni delegar.",preguntaIds:["2.1-q2"],objetivos:["2.1#1","2.1#2","2.1#3","2.1#4"]},{id:"seguridad-de-la-nube-vs-seguridad-en-la-nube",etiqueta:"Seguridad de la nube frente a seguridad en la nube",a:{titulo:"Seguridad de la nube",resumen:"La que asume AWS: proteger la infraestructura global —instalaciones, cómputo, almacenamiento y red— y el software que ejecuta los servicios."},b:{titulo:"Seguridad en la nube",resumen:"La que asume el cliente: proteger sus datos, gestionar identidades y accesos, asegurar sus aplicaciones y configurar correctamente el servicio que usa."},diferenciaClave:"«De la nube» es la parte que AWS controla y no se puede delegar; «en la nube» es la parte que depende de las decisiones del cliente. Entre ambas quedan responsabilidades compartidas, como la gestión de parches y de la configuración.",cuandoA:["Cuando se evalúa la seguridad física, la resistencia de la red o las capacidades de un servicio gestionado que AWS opera.","Cuando hay que explicar por qué ciertos controles no dependen de la configuración del cliente."],cuandoB:["Cuando el resultado de seguridad depende de cómo el cliente protege datos, permisos, aplicaciones y ajustes del servicio.","Cuando se usa un servicio gestionado y hay que saber qué sigue siendo responsabilidad propia."],escenarioA:"AWS protege los centros de datos y la red troncal, y mantiene el motor de base de datos de Amazon RDS con sus parches y copias de seguridad de plataforma.",escenarioB:"El cliente que usa Amazon RDS define quién accede a la base de datos, clasifica y protege los datos y elige la configuración de red y cifrado a su cargo.",preguntaIds:["2.1-q5"],objetivos:["2.1#5","2.1#6"]}],2.2:[{id:"cloudwatch-vs-cloudtrail-vs-config",etiqueta:"Amazon CloudWatch vs AWS CloudTrail vs AWS Config",a:{titulo:"Amazon CloudWatch (monitoreo)",resumen:"Recoge métricas, logs y alarmas del funcionamiento del entorno y permite reaccionar cuando un umbral se cruza. Responde a la pregunta «¿cómo está funcionando?»."},b:{titulo:"AWS CloudTrail y AWS Config (auditoría y estado de configuración)",resumen:"AWS CloudTrail registra las llamadas a la API: quién hizo qué, desde dónde y cuándo. AWS Config guarda el historial de configuración de los recursos y evalúa si cumplen las reglas definidas."},diferenciaClave:"CloudWatch observa el rendimiento y la operación; CloudTrail audita la actividad de la API; Config vigila el estado de la configuración. Son tres preguntas distintas y complementarias: funcionamiento, autoría y cumplimiento de configuración.",cuandoA:["Cuando necesitas métricas, logs y alarmas para operar y detectar degradaciones en tiempo real.","Cuando quieres centralizar los logs de servicio y reaccionar ante umbrales."],cuandoB:["Cuando necesitas saber quién realizó una acción y cuándo, para una investigación o una auditoría de seguridad.","Cuando debes demostrar el estado de configuración de los recursos y evaluarlo frente a reglas de cumplimiento."],escenarioA:"Un equipo supervisa una aplicación con un panel de métricas y recibe una alarma cuando el uso de CPU supera el umbral definido, para actuar antes de que afecte a los usuarios.",escenarioB:"Tras un incidente, el equipo reconstruye la secuencia de acciones con el historial de actividad de la API y comprueba si la configuración del recurso se había desviado de la regla requerida.",preguntaIds:["2.2-q13","2.2-q14"],objetivos:["2.2#3","2.2#8"]},{id:"cifrado-en-transito-vs-en-reposo",etiqueta:"Cifrado en tránsito vs cifrado en reposo",a:{titulo:"Cifrado en tránsito",resumen:"Protege el dato mientras viaja por la red, entre el cliente y el servicio o entre servicios. Se apoya en protocolos seguros en los endpoints y en las conexiones."},b:{titulo:"Cifrado en reposo",resumen:"Protege el dato almacenado en un volumen, un bucket o una base de datos. Se gestiona mediante claves, por ejemplo con AWS KMS."},diferenciaClave:"El cifrado en tránsito cubre el recorrido del dato por la red; el cifrado en reposo cubre el dato almacenado. Son momentos distintos del ciclo de vida y se complementan: aplicar uno no protege el otro.",cuandoA:["Cuando el dato sale de un sistema y viaja hacia otro, por ejemplo en una consulta o una transferencia.","Cuando quieres evitar que el tráfico sea leído o alterado durante su recorrido."],cuandoB:["Cuando el dato permanece guardado y quieres protegerlo frente a accesos no autorizados al almacenamiento.","Cuando un requisito de cumplimiento exige cifrado de los datos almacenados y control de las claves."],escenarioA:"Una aplicación consulta una base de datos a través de una conexión segura, de modo que los datos no puedan leerse durante el trayecto por la red.",escenarioB:"Los mismos datos se guardan en un almacenamiento cifrado con claves gestionadas, de modo que no sean legibles aunque el soporte físico se exponga.",preguntaIds:["2.2-q12"],objetivos:["2.2#7"]},{id:"artifact-vs-config-informes-vs-configuracion",etiqueta:"Informes de cumplimiento de AWS vs evaluación de la configuración propia",a:{titulo:"Informes de cumplimiento de AWS",resumen:"Centro de autoservicio donde el cliente descarga las certificaciones e informes de auditoría que AWS emite sobre sus propios servicios, junto con los acuerdos aplicables a cada sector."},b:{titulo:"Evaluación de la configuración propia",resumen:"Servicio que guarda el historial de configuración de los recursos del cliente y evalúa si cumplen las reglas definidas, mostrando el estado real de la cuenta."},diferenciaClave:"Uno aporta la evidencia documental que emite AWS sobre sí mismo; el otro evalúa cómo está configurada la cuenta del cliente. Para una auditoría se necesitan ambos: la certificación de AWS no demuestra la configuración propia.",cuandoA:["Cuando un auditor solicita informes, certificaciones o acuerdos aplicables a AWS.","Cuando hay que demostrar que las obligaciones del proveedor están cubiertas por documentación oficial."],cuandoB:["Cuando hay que verificar si los recursos de la cuenta cumplen las reglas de configuración requeridas.","Cuando se necesita el historial de cambios de configuración de un recurso concreto."],escenarioA:"El área legal descarga los informes SOC e ISO y los acuerdos aplicables para entregarlos al auditor externo.",escenarioB:"El ingeniero revisa qué recursos se desviaron de la configuración permitida y en qué momento cambió su estado.",preguntaIds:["2.2-q22"],objetivos:["2.2#4"]},{id:"inspector-vs-guardduty-vs-shield-deteccion",etiqueta:"Detección de amenazas, evaluación de vulnerabilidades y mitigación de DDoS",a:{titulo:"Detección y evaluación",resumen:"Amazon GuardDuty detecta actividad maliciosa a partir de señales del entorno y Amazon Inspector evalúa vulnerabilidades y exposición en las cargas de trabajo."},b:{titulo:"Mitigación de ataques de volumen",resumen:"AWS Shield absorbe y mitiga ataques de denegación de servicio distribuido (DDoS) que buscan saturar el servicio por volumen de tráfico."},diferenciaClave:"GuardDuty e Inspector examinan y producen hallazgos sobre lo que ya ocurre o podría fallar; Shield actúa frente a un ataque en curso para preservar la disponibilidad. Detectar y mitigar son acciones complementarias, no sustitutas.",cuandoA:["Cuando se quiere saber si hay comportamiento sospechoso o vulnerabilidades conocidas en las cargas de trabajo.","Cuando el objetivo es generar hallazgos para priorizar la remediación."],cuandoB:["Cuando un ataque de volumen intenta dejar el servicio fuera de línea.","Cuando se busca proteger la disponibilidad sin gestionar la mitigación manualmente."],escenarioA:"La empresa recibe un aviso de tráfico hacia direcciones desconocidas y, en paralelo, revisa sus instancias para localizar vulnerabilidades conocidas.",escenarioB:"El mismo servicio sufre un pico masivo de tráfico dirigido a saturarlo y la mitigación del ataque la asume la protección gestionada frente a DDoS.",preguntaIds:["2.2-q23"],objetivos:["2.2#6"]},{id:"cifrado-por-servicio-vs-por-cliente",etiqueta:"Cifrado aplicado por el servicio frente a cifrado configurado por el cliente",a:{titulo:"Cifrado gestionado por el servicio",resumen:"Algunos servicios aplican el cifrado en reposo de forma predeterminada y administran las claves, de modo que el cliente solo debe verificar que la opción esté activa."},b:{titulo:"Cifrado configurado por el cliente",resumen:"En otros servicios el cliente elige el método de cifrado, administra o selecciona las claves y decide qué datos se protegen, asumiendo esa configuración como parte de su responsabilidad."},diferenciaClave:"Aunque el objetivo sea el mismo requisito de cifrado, el alcance y la gestión de claves cambian de un servicio a otro. Por eso hay que revisar cada servicio en lugar de dar por supuesto que el cifrado se aplica igual en todos.",cuandoA:["Cuando el servicio ya cifra por defecto y solo hay que confirmar y documentar esa configuración.","Cuando se prefiere delegar la gestión de claves en el servicio para simplificar la operación."],cuandoB:["Cuando el requisito exige control propio de las claves o elegir el método de cifrado.","Cuando el servicio no aplica el cifrado por defecto y el cliente debe habilitarlo y configurarlo."],escenarioA:"Un almacenamiento aplica el cifrado en reposo de forma predeterminada y la empresa solo verifica que esté activo en todos sus recursos.",escenarioB:"Otro servicio exige que el cliente seleccione el método y administre las claves, por lo que la empresa configura y documenta esa decisión para la auditoría.",preguntaIds:["2.2-q24"],objetivos:["2.2#9"]}],2.3:[{id:"iam-user-vs-iam-role",etiqueta:"Usuario de IAM vs rol de IAM",a:{titulo:"Usuario de IAM",resumen:"Identidad con credenciales propias y duraderas. Puede tener contraseña para la consola y claves de acceso para llamadas programáticas. Representa a una persona o a una aplicación concreta y sus permisos provienen de las políticas adjuntas o de los grupos a los que pertenece."},b:{titulo:"Rol de IAM",resumen:"Identidad sin credenciales permanentes que se asume temporalmente. La asumen personas, aplicaciones o servicios y entrega credenciales temporales con los permisos indicados. Se usa para delegar acceso entre cuentas y para dar permisos a cargas de trabajo."},diferenciaClave:"El usuario tiene credenciales de larga duración que hay que proteger y rotar; el rol se asume y entrega credenciales temporales, por lo que no guarda secretos permanentes. Para aplicaciones y accesos entre cuentas, el rol es la opción recomendada.",cuandoA:["Cuando una persona necesita credenciales propias y no existe un proveedor de identidad federado que pueda usarse.","Cuando se requiere acceso programático de larga duración y no es viable asumir un rol, aceptando rotación y almacenamiento seguro de las claves."],cuandoB:["Cuando una aplicación o un servicio de AWS necesita permisos sin guardar claves de acceso permanentes.","Cuando se delega acceso entre cuentas de AWS o se entregan permisos temporales a personas o cargas de trabajo."],escenarioA:"Una persona necesita acceso a la consola y no existe un proveedor de identidad federado; se le crea un usuario de IAM con contraseña, MFA obligatorio y permisos mínimos a través de un grupo.",escenarioB:"Una aplicación que corre en AWS debe leer un bucket; se le asigna un rol, de modo que obtiene credenciales temporales sin guardar claves de acceso permanentes.",preguntaIds:["2.3-q2"],objetivos:["2.3#1"]},{id:"claves-de-acceso-vs-mfa",etiqueta:"Claves de acceso vs autenticación multifactor (MFA)",a:{titulo:"Claves de acceso",resumen:"Par de credenciales (access key ID y secret access key) asociado a un usuario de IAM para llamadas programáticas. Es de larga duración, no se usa para iniciar sesión en la consola y exige almacenamiento seguro y rotación."},b:{titulo:"Autenticación multifactor (MFA)",resumen:"Factor adicional que se exige al iniciar sesión, además de la contraseña. Puede apoyarse en una aplicación de códigos, un dispositivo de hardware o una llave de seguridad, y protege incluso si la contraseña se filtra."},diferenciaClave:"Las claves de acceso autentican programas y son un secreto permanente que hay que custodiar; el MFA refuerza la autenticación humana con un factor extra. No son alternativas entre sí: una aplicación usa claves o roles, mientras que una persona inicia sesión con contraseña más MFA.",cuandoA:["Cuando una herramienta o un script fuera de la consola necesita llamar a la API de AWS y no puede asumir un rol.","Cuando se requiere acceso programático y las claves se guardan en un almacén de secretos con rotación periódica."],cuandoB:["Cuando se protege el inicio de sesión de personas, en especial del root user y de las identidades administrativas.","Cuando se quiere que una contraseña filtrada no baste por sí sola para entrar en la cuenta."],escenarioA:"Un script de inventario se ejecuta fuera de AWS y se autentica con una clave de acceso guardada en AWS Secrets Manager y rotada periódicamente.",escenarioB:"Una administradora inicia sesión en la consola con su contraseña y un código temporal de su aplicación de autenticación, de modo que un robo de contraseña no le da acceso.",preguntaIds:["2.3-q10"],objetivos:["2.3#5","2.3#6"]},{id:"iam-identity-center-vs-usuario-iam",etiqueta:"Acceso federado centralizado vs usuario de IAM por persona y por cuenta",a:{titulo:"Acceso federado centralizado",resumen:"Conecta el directorio o proveedor de identidad corporativo y entrega inicio de sesión único y permission sets por cuenta y por grupo. La persona se valida fuera de AWS y recibe credenciales temporales."},b:{titulo:"Usuario de IAM por persona y por cuenta",resumen:"Crea una identidad local en cada cuenta, con contraseña y, si se necesita, claves de acceso de larga duración. Hay que administrar y rotar esas credenciales cuenta por cuenta."},diferenciaClave:"La federación delega la autenticación en un proveedor externo y emite credenciales temporales; el usuario local guarda credenciales duraderas dentro de cada cuenta. La federación reduce la administración y el riesgo, pero no elimina la necesidad de definir permisos.",cuandoA:["Cuando la plantilla ya está en un directorio corporativo y necesita acceder a varias cuentas con permisos por función.","Cuando se quiere retirar el acceso de inmediato al desactivar la persona en el directorio de origen."],cuandoB:["Cuando no existe un proveedor de identidad federado y una persona necesita credenciales propias en una cuenta concreta.","Cuando se requiere una identidad local concreta y se acepta administrar su contraseña, MFA y rotación de claves."],escenarioA:"La empresa conecta su directorio corporativo, agrupa a la plantilla y asigna permission sets por cuenta; al desactivar a una persona en el directorio, pierde el acceso sin borrar usuarios uno a uno.",escenarioB:"Una persona sin directorio federado recibe un usuario de IAM con contraseña, MFA y permisos mínimos a través de un grupo de su cuenta.",preguntaIds:["2.3-q21"],objetivos:["2.3#4","2.3#10"]},{id:"root-user-vs-identidad-administrativa-iam",etiqueta:"Root user vs identidad administrativa de IAM",a:{titulo:"Root user (cuenta raíz)",resumen:"Identidad que crea la cuenta con el correo y la contraseña de registro. Tiene acceso completo a todos los recursos y servicios, sus permisos no se limitan con políticas de IAM y concentra tareas que no se delegan, como cambiar el plan de soporte o cerrar la cuenta."},b:{titulo:"Identidad administrativa de IAM",resumen:"Usuario o rol con permisos elevados concedidos mediante políticas, creado para el trabajo diario. No hereda el acceso irrestricto de la cuenta raíz, se rige por el principio de menor privilegio y puede reforzarse con MFA y credenciales temporales."},diferenciaClave:"La cuenta raíz no admite restricciones por políticas y queda reservada a las tareas que solo ella puede realizar; la identidad administrativa de IAM recibe permisos acotados y asume el trabajo cotidiano. Proteger la raíz con MFA y sin claves de acceso es lo que permite delegar la operación en una identidad administrativa.",cuandoA:["Cuando hay que cambiar el plan de soporte, cerrar la cuenta, cambiar el correo de contacto o restaurar los permisos de un administrador de IAM.","Cuando una tarea exige actuar como propietario de la cuenta y no existe una alternativa delegable."],cuandoB:["Cuando el equipo necesita administrar recursos a diario aplicando el principio de menor privilegio.","Cuando se quiere operar la cuenta sin exponer las credenciales de la cuenta raíz."],escenarioA:"El equipo de seguridad modifica el plan de soporte contratado: como es una tarea reservada, la ejecuta la cuenta raíz con MFA activado y sin claves de acceso.",escenarioB:"El trabajo diario de crear recursos y revisar políticas lo realiza un usuario administrativo de IAM con MFA y permisos mínimos, mientras la cuenta raíz permanece sin uso.",preguntaIds:["2.3-q22"],objetivos:["2.3#2","2.3#3","2.3#8","2.3#9"]},{id:"managed-policy-vs-inline-policy",etiqueta:"Managed policy vs política inline",a:{titulo:"Managed policy",resumen:"Documento de permisos independiente y reutilizable que AWS administra o que crea el cliente. Se adjunta a varias identidades, se actualiza en un solo lugar y permite mantener el permiso mínimo de forma consistente."},b:{titulo:"Política inline",resumen:"Política incrustada en una única identidad que no se puede reutilizar ni adjuntar a otra. Se usa para permisos muy concretos de esa identidad, a costa de duplicar cambios si se necesita el mismo permiso en más sitios."},diferenciaClave:"La managed policy vive fuera de las identidades y se comparte entre ellas; la inline vive dentro de una sola identidad. Para definir grupos, usuarios y permisos conforme al mínimo privilegio conviene reutilizar managed policies y reservar la inline para excepciones.",cuandoA:["Cuando el mismo conjunto de permisos debe aplicarse a varios usuarios, grupos o roles.","Cuando se quiere cambiar el permiso en un único punto y que todas las identidades lo hereden."],cuandoB:["Cuando un permiso muy concreto no debe compartirse ni reutilizarse en otra identidad.","Cuando se necesita un ajuste puntual que no tiene sentido mantener a escala de toda la organización."],escenarioA:"Una empresa crea una managed policy de solo lectura de paneles y la adjunta al grupo de analistas; al añadir una vista nueva, actualiza la política una vez y todo el grupo la hereda.",escenarioB:"Un script concreto recibe una política inline con permiso exclusivo para una acción puntual sobre un recurso, sin reutilizarla en ninguna otra identidad.",preguntaIds:["2.3-q23"],objetivos:["2.3#7"]}],2.4:[{id:"guardduty-vs-inspector-vs-security-hub",etiqueta:"Amazon GuardDuty, Amazon Inspector y AWS Security Hub",a:{titulo:"Detección y evaluación",resumen:"Amazon GuardDuty vigila la actividad del entorno y avisa de comportamiento sospechoso; Amazon Inspector evalúa vulnerabilidades y exposición de las cargas de trabajo. Ambos examinan y producen hallazgos, pero miran cosas distintas."},b:{titulo:"Agregación de hallazgos",resumen:"AWS Security Hub recopila y prioriza los hallazgos que generan otros servicios de seguridad, incluidos GuardDuty e Inspector, y los presenta en una vista única."},diferenciaClave:"GuardDuty detecta amenazas sobre la actividad; Inspector busca vulnerabilidades y exposición; Security Hub no descubre por sí mismo, agrega y prioriza lo que otros servicios encuentran.",cuandoA:["Cuando quieres detectar actividad sospechosa o potencialmente maliciosa en el entorno.","Cuando necesitas conocer vulnerabilidades y exposición de instancias y contenedores."],cuandoB:["Cuando tienes varios servicios de seguridad y quieres una vista única y priorizada de sus hallazgos.","Cuando buscas centralizar la gestión de hallazgos en una o varias cuentas."],escenarioA:"Una empresa ve picos de tráfico hacia direcciones desconocidas y quiere saber si es actividad maliciosa; en paralelo, revisa sus instancias para localizar vulnerabilidades conocidas.",escenarioB:"La misma empresa recibe hallazgos de varios servicios de seguridad y los reúne en una sola vista priorizada para que el equipo sepa qué atender primero.",preguntaIds:["2.4-q4"],objetivos:["2.4#3"]},{id:"waf-vs-shield",etiqueta:"AWS WAF frente a AWS Shield",a:{titulo:"AWS WAF",resumen:"Firewall de aplicaciones web: inspecciona las peticiones HTTP(S) y bloquea patrones maliciosos mediante reglas, por ejemplo inyección SQL o cross-site scripting."},b:{titulo:"AWS Shield",resumen:"Protección gestionada frente a ataques de denegación de servicio distribuido (DDoS): absorbe y mitiga el tráfico de volumen que busca tumbar el servicio."},diferenciaClave:"AWS WAF decide mirando el contenido de cada petición; AWS Shield decide frente al volumen del ataque. Uno filtra peticiones maliciosas, el otro protege la disponibilidad frente a un DDoS.",cuandoA:["Cuando necesitas bloquear peticiones concretas con carga maliciosa contra tu aplicación web.","Cuando quieres aplicar reglas de filtrado asociadas a una distribución o a un balanceador."],cuandoB:["Cuando el riesgo es un ataque de volumen que intenta saturar el servicio.","Cuando buscas proteger la disponibilidad sin gestionar tú mismo la mitigación."],escenarioA:"Un portal detecta intentos de inyección de código en sus formularios y aplica reglas que bloquean las peticiones que coinciden con patrones maliciosos.",escenarioB:"El mismo portal sufre un pico masivo de tráfico dirigido a dejarlo fuera de servicio y la mitigación del ataque la asume la protección gestionada frente a DDoS.",preguntaIds:["2.4-q3"],objetivos:["2.4#3"]},{id:"trusted-advisor-vs-security-hub",etiqueta:"Revisión proactiva de la cuenta vs centralización de hallazgos",a:{titulo:"Revisión proactiva de la cuenta",resumen:"AWS Trusted Advisor revisa el entorno y entrega comprobaciones y recomendaciones en categorías como seguridad, rendimiento, tolerancia a fallos, optimización de costes y cuotas de servicio. Señala, pero no corrige por el cliente."},b:{titulo:"Centralización de hallazgos",resumen:"AWS Security Hub recopila, normaliza y prioriza los hallazgos que generan otros servicios de seguridad, incluidos GuardDuty e Inspector, en una vista única para varias cuentas."},diferenciaClave:"La revisión proactiva mira la configuración de la cuenta y propone mejoras; la centralización no descubre por sí misma, reúne y ordena lo que otros servicios encuentran. Una recomienda y la otra agrega y prioriza.",cuandoA:["Cuando se quiere localizar configuraciones de riesgo o desviaciones de las mejores prácticas antes de una auditoría.","Cuando se busca una lista de recomendaciones accionables sobre la propia cuenta."],cuandoB:["Cuando varios servicios de seguridad producen hallazgos y se necesita verlos juntos y priorizados.","Cuando se quiere centralizar la gestión de hallazgos en una o varias cuentas de la organización."],escenarioA:"El equipo revisa las comprobaciones de seguridad del servicio de recomendaciones y corrige las configuraciones señaladas antes de la auditoría.",escenarioB:"La misma empresa recibe hallazgos de varios servicios de seguridad y los reúne en una sola vista priorizada para saber qué atender primero.",preguntaIds:["2.4-q16"],objetivos:["2.4#6"]},{id:"marketplace-terceros-vs-servicio-nativo",etiqueta:"Producto de seguridad de un proveedor externo frente a un servicio nativo de AWS",a:{titulo:"Producto de un proveedor externo",resumen:"AWS Marketplace es el catálogo donde proveedores independientes publican productos, incluidos productos de seguridad, que el cliente adquiere por suscripción e integra en su entorno. La herramienta sigue siendo responsabilidad de su proveedor."},b:{titulo:"Servicio nativo de AWS",resumen:"Un servicio de seguridad propio de AWS forma parte del alcance del proveedor: AWS lo opera, lo mantiene y lo soporta, y el cliente lo configura dentro del modelo de responsabilidad compartida."},diferenciaClave:"En el catálogo de terceros el cliente elige y adquiere la solución de un proveedor externo, que responde de su producto; en el servicio nativo la solución la opera y soporta AWS. Uno amplía las opciones con el ecosistema de terceros y el otro cubre la necesidad con una capacidad propia de AWS.",cuandoA:["Cuando se necesita una herramienta especializada o de un fabricante concreto que no existe como servicio nativo.","Cuando se prefiere adquirir la solución por suscripción e integrarla en el entorno en lugar de desarrollarla."],cuandoB:["Cuando la necesidad encaja en las capacidades de seguridad que AWS ya ofrece y se quiere que AWS las opere y soporte.","Cuando se busca la integración y el soporte directo de AWS sin depender de un proveedor externo."],escenarioA:"Una empresa debe cumplir un requisito sectorial con una herramienta de un fabricante especializado que no quiere construir; la adquiere por suscripción desde el catálogo y la integra en su entorno.",escenarioB:"La misma empresa decide cubrir esa necesidad con una capacidad de seguridad que ya ofrece AWS y que AWS opera y soporta, sin contratar a un proveedor externo.",preguntaIds:["2.4-q17"],objetivos:["2.4#4"]}],3.1:[{id:"iac-vs-consola-vs-cli",etiqueta:"Infraestructura como código vs consola y CLI",a:{titulo:"Infraestructura como código (IaC)",resumen:"Describe el estado deseado de la infraestructura en archivos versionados que se despliegan de forma repetible. El entorno queda documentado, revisable y reconstruible; la definición es la fuente de verdad."},b:{titulo:"Consola de administración y CLI",resumen:"Vías de acceso directo a los servicios de AWS. La consola es visual y guiada, ideal para explorar y para tareas puntuales; la CLI ejecuta comandos desde la terminal y se encadena en scripts, pero el usuario sigue siendo quien los escribe."},diferenciaClave:"La IaC define y reproduce el entorno a partir de archivos versionados; la consola y la CLI ejecutan acciones concretas en el momento y, por sí mismas, no dejan una definición reutilizable del entorno.",cuandoA:["Cuando el mismo entorno debe reproducirse en varias cuentas o regiones con el mismo resultado.","Cuando necesitas auditar quién cambió qué y reconstruir la infraestructura tras un fallo."],cuandoB:["Cuando exploras un servicio por primera vez o haces un ajuste puntual.","Cuando ejecutas una tarea rápida desde la terminal sin necesidad de describir todo el entorno."],escenarioA:"Un equipo define una plantilla con la red, el cómputo y la base de datos y la despliega igual en desarrollo, pruebas y producción; ante un desastre, vuelve a ejecutar la plantilla y recrea el entorno.",escenarioB:"Una persona recién incorporada abre la consola para entender cómo se ve un servicio y crea un recurso de prueba; otro perfil ejecuta un comando de la CLI para consultar el estado de unos recursos sin escribir una plantilla.",preguntaIds:["3.1-q3"],objetivos:["3.1#2","3.1#4"]},{id:"una-vez-vs-repetible",etiqueta:"Operación puntual vs proceso repetible",a:{titulo:"Operación puntual",resumen:"Acción que resuelve una necesidad concreta y no se vuelve a ejecutar. Se hace a mano o con un comando aislado; su valor está en la inmediatez."},b:{titulo:"Proceso repetible",resumen:"Procedimiento definido una vez y diseñado para volver a ejecutarse tantas veces como haga falta, con el mismo resultado. Suele apoyarse en scripts, plantillas o infraestructura como código."},diferenciaClave:"La operación puntual responde al «ahora» y no requiere definición previa; el proceso repetible invierte tiempo en definirse para que cada ejecución sea consistente y auditable.",cuandoA:["Cuando exploras, pruebas o haces un ajuste que no volverá a repetirse.","Cuando el coste de definir y mantener el proceso supera claramente el beneficio."],cuandoB:["Cuando la misma tarea se repite en el tiempo o debe aplicarse a varios entornos.","Cuando necesitas resultados idénticos, trazabilidad y menos errores humanos."],escenarioA:"Una persona crea una instancia de Amazon EC2 para probar una idea durante una tarde y la elimina después; no documenta el proceso porque no volverá a necesitarlo.",escenarioB:"Un equipo debe crear cada semana un entorno de pruebas completo e idéntico al de producción; define el entorno como código y lo despliega con la misma definición cada vez.",preguntaIds:["3.1-q8"],objetivos:["3.1#5"]},{id:"nube-vs-hibrido-vs-onpremises",etiqueta:"Modelos de despliegue: nube, híbrido y on-premises",a:{titulo:"Nube",resumen:"Todo el entorno se ejecuta en la nube de AWS: el cliente no compra servidores y obtiene elasticidad, alcance global y pago por uso. Es el modelo por defecto cuando no hay ataduras de hardware ni de cumplimiento."},b:{titulo:"Híbrido y on-premises",resumen:"El híbrido combina instalaciones propias con la nube de AWS, normalmente por normativa, latencia o inversión ya realizada. On-premises mantiene todo en las instalaciones del cliente y da control total a cambio de comprar y mantener la capacidad."},diferenciaClave:"Nube pone todo en la nube; on-premises lo mantiene todo en instalaciones propias; el híbrido reparte la carga entre ambos mundos. No confundir híbrido (local más nube) con multinube (varios proveedores de nube).",cuandoA:["Cuando no hay requisitos de permanencia física y se busca elasticidad, alcance global y pago por uso.","Cuando el equipo quiere delegar la operación de la infraestructura y centrarse en la aplicación."],cuandoB:["Cuando parte de los datos debe quedarse en las instalaciones por normativa o por latencia.","Cuando existe una inversión ya amortizada que conviene reutilizar mientras se adopta la nube."],escenarioA:"Una startup despliega toda su plataforma en la nube y crece añadiendo recursos según la demanda, sin comprar ni mantener servidores propios.",escenarioB:"Un hospital conserva su sistema clínico en el centro de datos por normativa y ejecuta el análisis y las aplicaciones nuevas en la nube, conectando ambos entornos mediante un enlace dedicado.",preguntaIds:["3.1-q14"],objetivos:["3.1#3","3.1#6"]}],3.2:[{id:"regiones-vs-az-vs-edge",etiqueta:"Región y Availability Zone vs edge location",a:{titulo:"Región y Availability Zones",resumen:"La región es el área geográfica donde se despliegan datos y cómputo; dentro de ella, cada Availability Zone es un centro de datos aislado con su propia energía y red. Es la capa de residencia, tolerancia a fallos y residencia de datos."},b:{titulo:"Edge locations",resumen:"Puntos de presencia cercanos al usuario final que usan los servicios de entrega de contenido y DNS para acercar la respuesta. No alojan los servicios generales ni el origen de los datos."},diferenciaClave:"La región (con sus AZ) es donde viven la aplicación y los datos; el edge es donde se acerca la entrega al usuario. La región aporta disponibilidad y residencia; el edge aporta proximidad y menor latencia.",cuandoA:["Cuando necesitas cumplir residencia de datos o elegir la ubicación del cómputo y la base de datos.","Cuando buscas alta disponibilidad repartiendo réplicas entre varias Availability Zones de la región."],cuandoB:["Cuando el contenido estático o las respuestas DNS deben servirse con baja latencia a usuarios repartidos geográficamente.","Cuando quieres descargar de tu origen el tráfico de entrega sin mover los datos de la región."],escenarioA:"Una empresa fija `eu-west-1` como región para que los datos personales europeos no salgan de la UE y despliega su base de datos en dos Availability Zones para tolerar el fallo de una.",escenarioB:"La misma empresa publica imágenes y vídeos mediante una distribución de contenido que los sirve desde puntos de presencia cercanos a cada usuario, reduciendo el tiempo de descarga sin cambiar la región del dato.",preguntaIds:["3.2-q2"],objetivos:["3.2#1","3.2#5"]}],3.3:[{id:"ecs-vs-eks-vs-fargate",etiqueta:"Amazon ECS y Amazon EKS vs AWS Fargate",a:{titulo:"Amazon ECS y Amazon EKS (orquestadores de contenedores)",resumen:"Organizan, programan y escalan los contenedores. Amazon ECS es el orquestador propio de AWS, sencillo y muy integrado con el resto del ecosistema; Amazon EKS es Kubernetes gestionado, adecuado si ya usas Kubernetes o necesitas su portabilidad."},b:{titulo:"AWS Fargate (motor de cómputo serverless)",resumen:"Motor que ejecuta contenedores sin que aprovisiones ni administres servidores. No es un orquestador: se combina con Amazon ECS o con Amazon EKS para decidir en qué se ejecutan las tareas."},diferenciaClave:"ECS y EKS deciden cómo se orquesta; Fargate decide en qué se ejecuta, sin servidores. No son alternativas: ECS o EKS con Fargate es una combinación habitual, mientras que la alternativa a Fargate es ejecutar los contenedores en instancias de Amazon EC2 que tú gestionas.",cuandoA:["Cuando necesitas coordinar muchos contenedores, definir tareas o servicios y elegir un orquestador.","Cuando quieres Kubernetes gestionado con Amazon EKS o la integración más directa con AWS mediante Amazon ECS."],cuandoB:["Cuando no quieres administrar instancias ni aplicar parches y prefieres pagar solo por los recursos que consumen las tareas.","Cuando ya usas ECS o EKS y quieres liberarte de gestionar el plano de datos."],escenarioA:"Una empresa estandariza sus aplicaciones en Kubernetes porque ya lo usa en otros entornos y necesita portabilidad entre nubes; despliega sus clústeres con Amazon Elastic Kubernetes Service (Amazon EKS).",escenarioB:"La misma empresa no quiere gestionar nodos ni aplicar parches al sistema operativo, así que ejecuta las tareas de sus contenedores con AWS Fargate como motor de cómputo.",preguntaIds:["3.3-q4"],objetivos:["3.3#3"]},{id:"ec2-vs-lambda",etiqueta:"Amazon EC2 vs AWS Lambda",a:{titulo:"Amazon EC2 (servidores virtuales)",resumen:"Proporciona instancias: servidores virtuales que aprovisionas y administras. Tienes control total del sistema operativo y de la configuración, eliges familia y tamaño, y la capacidad queda disponible de forma continua aunque no haya trabajo."},b:{titulo:"AWS Lambda (cómputo serverless orientado a eventos)",resumen:"Ejecuta funciones disparadas por eventos sin gestionar servidores. Escala de forma automática con los eventos y solo se paga por las invocaciones y el tiempo de ejecución; no hay capacidad encendida por defecto."},diferenciaClave:"EC2 es un servidor que controlas tú; Lambda es una función que se ejecuta cuando ocurre un evento. EC2 conviene para procesos continuos, de ejecución larga o que requieren control del sistema operativo; Lambda, para lógica corta y sin estado disparada por eventos.",cuandoA:["Cuando necesitas control del sistema operativo, instalar software específico o ejecutar procesos de larga duración.","Cuando la carga es continua y estable, o el proceso necesita conservar estado en la propia máquina."],cuandoB:["Cuando la lógica se activa por eventos y las ejecuciones son cortas.","Cuando quieres escalar automáticamente sin aprovisionar capacidad ni pagar mientras no hay eventos."],escenarioA:"Una empresa mantiene una base de datos auto-gestionada y varios procesos de larga duración que necesitan control total del sistema operativo; esos componentes se ejecutan en instancias de Amazon EC2.",escenarioB:"Otra parte del sistema reacciona a cada archivo nuevo y a cada petición web con lógica breve; se implementa con funciones de AWS Lambda que se activan solo cuando llega el evento.",preguntaIds:["3.3-q6"],objetivos:["3.3#4"]},{id:"servidores-virtuales-vs-serverless",etiqueta:"Máquinas virtuales vs cómputo serverless",a:{titulo:"Máquinas virtuales (control y capacidad continua)",resumen:"El cliente elige el tipo de instancia, administra el sistema operativo y el software, y la capacidad está disponible de forma continua. Es el extremo del espectro con más control y más responsabilidad operativa."},b:{titulo:"Cómputo serverless (sin servidores y pago por uso)",resumen:"No se aprovisionan ni administran servidores: el servicio ejecuta funciones o contenedores ante eventos, escala de forma automática y solo se paga por el uso. Se gana comodidad y elasticidad a cambio de menos control."},diferenciaClave:"El eje es control frente a gestión: la máquina virtual da control total del sistema operativo y capacidad permanente; el cómputo serverless elimina la administración de servidores y cobra por uso, con menos control del entorno de ejecución.",cuandoA:["Cuando necesitas instalar software específico, controlar el sistema operativo o mantener un proceso de larga duración.","Cuando la carga es continua o el proceso necesita conservar estado en la propia máquina."],cuandoB:["Cuando la lógica responde a eventos, es corta y sin estado, y quieres escalar sin gestionar servidores.","Cuando prefieres pagar solo por lo que se usa y no mantener capacidad encendida entre eventos."],escenarioA:"Un equipo ejecuta un sistema heredado que exige una versión concreta del sistema operativo y procesos nocturnos de larga duración; lo mantiene en instancias que administra él mismo.",escenarioB:"Otro equipo procesa cada archivo subido con lógica breve y sin estado; usa cómputo serverless para no mantener servidores encendidos entre eventos.",preguntaIds:["3.3-q11"],objetivos:["3.3#1"]},{id:"familias-instancia-compute-memory-storage",etiqueta:"Familias de instancias: compute, memory y storage optimized",a:{titulo:"Compute optimized y memory optimized",resumen:"Compute optimized prioriza la CPU: cálculo intensivo, procesamiento por lotes, codificación o servidores web muy exigentes. Memory optimized prioriza la RAM para conjuntos de datos activos, cachés y bases de datos en memoria."},b:{titulo:"Storage optimized",resumen:"Prioriza la entrada/salida de disco y el almacenamiento local de alto rendimiento. Es la familia para bases de datos con muchas lecturas y escrituras, sistemas de archivos de alto rendimiento y cargas intensivas de disco."},diferenciaClave:"La familia se elige por el recurso limitante: CPU (compute optimized), memoria (memory optimized) o entrada/salida de disco (storage optimized). Elegir por tamaño en lugar de por perfil deja recursos sin aprovechar.",cuandoA:["Cuando el cuello de botella es el cálculo o el conjunto de datos activo vive en memoria.","Cuando la carga no depende del rendimiento de disco local ni de un almacenamiento local intensivo."],cuandoB:["Cuando el cuello de botella es la entrada/salida de disco o se necesita almacenamiento local de alto rendimiento.","Cuando la carga realiza muchas operaciones de lectura y escritura sobre discos locales."],escenarioA:"Un equipo ejecuta un trabajo de procesamiento por lotes que satura la CPU de forma constante; elige instancias compute optimized y no necesita memoria ni disco especiales.",escenarioB:"Otro equipo mantiene un clúster de datos con requisitos muy altos de IOPS y gran capacidad local; elige instancias storage optimized.",preguntaIds:["3.3-q12"],objetivos:["3.3#2"]}],3.4:[{id:"rds-vs-aurora-vs-dynamodb",etiqueta:"Bases relacionales gestionadas vs Amazon DynamoDB",a:{titulo:"Amazon RDS y Amazon Aurora (relacional)",resumen:"Amazon RDS ejecuta motores relacionales conocidos (MySQL, PostgreSQL, MariaDB, Oracle, SQL Server) de forma gestionada, y Amazon Aurora es el motor relacional de AWS compatible con MySQL y PostgreSQL, con almacenamiento distribuido y réplicas de lectura. Ambos se consultan con SQL y guardan los datos en tablas con esquema fijo."},b:{titulo:"Amazon DynamoDB (NoSQL)",resumen:"Base NoSQL gestionada de clave-valor y documento, sin esquema fijo y con escalado horizontal. No usa SQL tradicional; se accede por clave y ofrece latencia de milisegundos."},diferenciaClave:"La elección es de **modelo de dato**, no de tamaño: si hay relaciones y SQL, Amazon RDS o Amazon Aurora; si el acceso es por clave con escala impredecible, Amazon DynamoDB. Aurora y RDS comparten el modelo relacional y se diferencian sobre todo por rendimiento y compatibilidad de motor.",cuandoA:["Cuando el dato es transaccional, tiene relaciones claras y necesitas consultas SQL con integridad referencial.","Cuando quieres motores conocidos (Amazon RDS) o un motor relacional de alto rendimiento compatible con MySQL o PostgreSQL (Amazon Aurora)."],cuandoB:["Cuando el acceso es por clave, el volumen crece de forma impredecible y no quieres administrar servidores.","Cuando un esquema fijo y las transacciones relacionales no son requisitos del caso de uso."],escenarioA:"Un sistema de facturación con clientes, facturas y líneas necesita transacciones y consultas relacionales; se apoya en Amazon Aurora para tener réplicas de lectura y alta disponibilidad sin administrar el motor.",escenarioB:"Una aplicación de sesiones y perfiles con millones de usuarios lee y escribe por clave con tráfico variable; usa Amazon DynamoDB para escalar sin administrar servidores.",preguntaIds:["3.4-q5"],objetivos:["3.4#4","3.4#5"]},{id:"relacional-vs-nosql-vs-memoria",etiqueta:"Persistencia relacional y NoSQL vs base en memoria",a:{titulo:"Relacional y NoSQL (persistencia)",resumen:"Amazon RDS y Amazon Aurora (relacionales) y Amazon DynamoDB (NoSQL) son la **fuente de verdad**: los datos persisten en disco y sobreviven a reinicios. Cambian el modelo y la forma de consultar, no su papel de almacenamiento duradero."},b:{titulo:"En memoria (Amazon ElastiCache)",resumen:"Amazon ElastiCache mantiene los datos en RAM para dar latencias muy bajas y se usa como **caché** delante de una base persistente. Acelera lecturas repetidas; no es el lugar donde debe vivir el dato crítico."},diferenciaClave:"El eje no es relacional frente a NoSQL, sino **persistencia frente a aceleración**: relacional y NoSQL guardan el dato de forma duradera; la base en memoria lo mantiene temporalmente para responder más rápido.",cuandoA:["Cuando necesitas que los datos sobrevivan a reinicios y sean la fuente de verdad de la aplicación.","Cuando el modelo del dato exige relaciones y SQL o, por el contrario, acceso por clave con escala horizontal."],cuandoB:["Cuando las mismas lecturas se repiten y la latencia de la base es el cuello de botella.","Cuando quieres descargar de trabajo a la base principal sin cambiar el modelo de datos."],escenarioA:"Una tienda en línea guarda pedidos en Amazon Aurora y su catálogo de productos en Amazon DynamoDB; ambos datos deben persistir aunque el servicio se reinicie.",escenarioB:"La misma tienda coloca Amazon ElastiCache delante de las consultas más repetidas del catálogo para reducir la latencia y la carga sobre la base principal.",preguntaIds:["3.4-q9"],objetivos:["3.4#4","3.4#5","3.4#6"]},{id:"dms-vs-sct",etiqueta:"AWS DMS vs AWS SCT",a:{titulo:"AWS Database Migration Service (AWS DMS)",resumen:"Mueve y **replica los datos** entre un origen y un destino, con soporte de motores distintos y replicación continua. Reduce el tiempo de inactividad porque el destino se mantiene sincronizado hasta el corte."},b:{titulo:"AWS Schema Conversion Tool (AWS SCT)",resumen:"Convierte el **esquema y el código** de la base de datos (tablas, procedimientos, vistas) de un motor a otro. Es la pieza que resuelve la incompatibilidad en las migraciones heterogéneas."},diferenciaClave:"Uno mueve **datos** y el otro convierte **estructura y código**. La forma de recordarlo: AWS SCT trabaja con el esquema y AWS DMS con la réplica de los datos.",cuandoA:["Cuando necesitas copiar o replicar los datos hacia el destino con el mínimo tiempo de inactividad.","Cuando el origen y el destino son motores distintos y quieres una sincronización continua durante la migración."],cuandoB:["Cuando el motor de destino no es compatible con el de origen y hay que convertir esquema, procedimientos y vistas.","Cuando preparas una migración heterogénea antes de empezar a mover los datos."],escenarioA:"Una empresa sincroniza de forma continua su base local con el destino en AWS mientras la aplicación sigue operativa, y hace el corte cuando la réplica está al día.",escenarioB:"Antes de mover nada, el equipo convierte las tablas y los procedimientos almacenados de Oracle al dialecto de PostgreSQL para que la aplicación funcione en el destino.",preguntaIds:["3.4-q13"],objetivos:["3.4#2","3.4#7"]},{id:"base-gestionada-vs-base-en-ec2",etiqueta:"Base de datos gestionada por AWS vs base autogestionada en Amazon EC2",a:{titulo:"Base de datos gestionada de AWS",resumen:"El proveedor administra la infraestructura del motor: aprovisionamiento, parches, copias de seguridad de plataforma, alta disponibilidad y parte del escalado. El equipo se concentra en el esquema, los índices, los datos y las consultas."},b:{titulo:"Base autogestionada en Amazon EC2",resumen:"El equipo instala y opera el motor en una instancia que controla por completo, con acceso total al sistema operativo y a la versión del motor. A cambio, asume parches, copias, escalado y alta disponibilidad por su cuenta."},diferenciaClave:"El eje es quién administra la infraestructura: la base gestionada delega parches, copias y alta disponibilidad en AWS, mientras que la base en Amazon EC2 traslada toda la operación al equipo. Se elige Amazon EC2 cuando hay un requisito de control del motor o del sistema operativo que el servicio gestionado no cubre.",cuandoA:["Cuando se prefiere delegar la operación del motor y centrar al equipo en la aplicación.","Cuando el motor o la versión que se necesita está disponible en el servicio gestionado."],cuandoB:["Cuando se necesita un motor, una versión o una configuración del sistema operativo que el servicio gestionado no ofrece.","Cuando se acepta asumir parches, copias y alta disponibilidad a cambio de control total."],escenarioA:"Una plataforma usa una base gestionada para no ocuparse de parches ni de copias y dedicar el equipo al modelo de datos y a las consultas.",escenarioB:"Otro equipo requiere una versión concreta del motor y extensiones del sistema operativo que el servicio gestionado no permite, así que la instala en una instancia que administra y asume su mantenimiento.",preguntaIds:["3.4-q17"],objetivos:["3.4#3"]}],3.5:[{id:"vpn-vs-direct-connect",etiqueta:"AWS VPN vs AWS Direct Connect",a:{titulo:"AWS VPN",resumen:"Túnel cifrado sobre internet entre la red local y la VPC. Se despliega rápido, tiene coste bajo y sirve para respaldo, tráfico puntual o bajo volumen. El rendimiento depende de las variaciones de internet."},b:{titulo:"AWS Direct Connect",resumen:"Enlace dedicado y privado que no atraviesa internet. Ofrece ancho de banda y latencia más estables y predecibles, a cambio de contratar la conexión con un proveedor y esperar su aprovisionamiento."},diferenciaClave:"La VPN viaja cifrada por internet y la conexión dedicada usa un enlace privado. La VPN prioriza rapidez de despliegue y coste; Direct Connect prioriza estabilidad, ancho de banda y privacidad del tráfico.",cuandoA:["Cuando necesitas conectar la red local con AWS en poco tiempo y con presupuesto ajustado.","Cuando quieres un enlace de respaldo del enlace principal o cubrir tráfico puntual y de bajo volumen."],cuandoB:["Cuando transfieres grandes volúmenes de datos de forma recurrente y necesitas ancho de banda estable.","Cuando la latencia predecible y el tráfico que no atraviesa internet son requisitos del negocio o del cumplimiento."],escenarioA:"Una empresa configura un túnel cifrado desde su oficina hacia la VPC para que los administradores accedan a los recursos internos mientras termina de definir su enlace permanente.",escenarioB:"La misma empresa contrata un enlace dedicado con un proveedor para su tráfico de producción y recurrente, y conserva el túnel cifrado como respaldo del enlace dedicado.",preguntaIds:["3.5-q4"],objetivos:["3.5#5"]},{id:"security-group-vs-nacls",etiqueta:"Security groups vs network ACLs",a:{titulo:"Security groups",resumen:"Cortafuegos con estado asociado a recursos como instancias. Solo admite reglas de permiso y la respuesta de una conexión permitida vuelve sin regla inversa."},b:{titulo:"Network ACLs",resumen:"Cortafuegos sin estado asociado a una subred. Admite reglas de permiso y de denegación, se evalúa por número de regla y exige definir el tráfico de respuesta."},diferenciaClave:"El security group filtra a nivel de recurso y es con estado; el network ACL filtra a nivel de subred y es sin estado. Son capas complementarias y el tráfico debe superar ambas.",cuandoA:["Cuando quieres controlar qué tráfico puede entrar y salir de una instancia o recurso concreto.","Cuando prefieres reglas simples de permiso sin gestionar el tráfico de respuesta."],cuandoB:["Cuando necesitas una barrera a nivel de subred que aplique a todos los recursos de esa subred.","Cuando requieres reglas explícitas de denegación además de las de permiso."],escenarioA:"Un equipo abre el puerto de una aplicación en el security group de la instancia y comprueba que la respuesta de la conexión vuelve sin añadir una regla adicional.",escenarioB:"El mismo equipo añade una regla en el network ACL de la subred para denegar el tráfico de un rango concreto antes de que llegue a los recursos.",preguntaIds:["3.5-q7"],objetivos:["3.5#3"]},{id:"route53-vs-cloudfront",etiqueta:"Amazon Route 53 vs Amazon CloudFront",a:{titulo:"Amazon Route 53 (DNS)",resumen:"Servicio de DNS gestionado: registra dominios, traduce nombres a direcciones o destinos de AWS y aplica políticas de enrutamiento y comprobaciones de estado. No almacena ni sirve el contenido."},b:{titulo:"Amazon CloudFront (entrega de contenido)",resumen:"Red de entrega de contenido: cachea los archivos en ubicaciones de borde cercanas al usuario y los sirve con baja latencia, reduciendo la carga sobre el origen. No resuelve nombres de dominio."},diferenciaClave:"El DNS decide a qué destino se dirige el usuario a partir del nombre; la red de entrega de contenido guarda y sirve el contenido cerca de ese usuario. Uno resuelve direcciones y el otro cachea y entrega datos.",cuandoA:["Cuando necesitas publicar un dominio, resolver nombres y aplicar políticas como failover o latencia.","Cuando quieres desviar el tráfico a otro destino si el principal deja de responder."],cuandoB:["Cuando sirves contenido estático o descargable a usuarios repartidos por el mundo y quieres reducir la latencia.","Cuando buscas descargar el origen y acelerar la entrega de imágenes, vídeo o archivos."],escenarioA:"Una empresa publica `app.ejemplo.com` y configura una comprobación de estado con failover para que el dominio apunte al servidor secundario si el principal deja de responder.",escenarioB:"La misma empresa distribuye las imágenes y los vídeos de su catálogo desde ubicaciones de borde, de modo que el usuario los recibe desde el punto más cercano.",preguntaIds:["3.5-q12"],objetivos:["3.5#4"]}],3.6:[{id:"s3-vs-ebs-vs-efs",etiqueta:"Almacenamiento de objetos, de bloque y de archivos",a:{titulo:"Almacenamiento de objetos (Amazon S3)",resumen:"Guarda cada dato como un objeto completo con metadatos y una clave, dentro de un contenedor plano, accesible por API y prácticamente sin límite de escala. Es la opción para contenido estático, copias y datos que se leen como un todo."},b:{titulo:"Bloque y archivos (Amazon EBS, instance store, Amazon EFS y Amazon FSx)",resumen:"El bloque entrega volúmenes tipo disco a las instancias, persistentes con Amazon EBS o locales y efímeros con instance store. Los archivos ofrecen un sistema de archivos compartido por red: Amazon EFS para Linux y Amazon FSx para motores concretos."},diferenciaClave:"El objeto se accede por API y no se edita parcialmente; el bloque es un disco que gestiona el sistema operativo de una instancia; el archivo es una jerarquía de rutas compartida por varias instancias. La elección depende de si el consumidor es una aplicación por API, una instancia con disco o varios hosts con sistema de archivos.",cuandoA:["Cuando sirves contenido estático, guardas copias o alimentas un data lake accedido por API.","Cuando quieres escalado prácticamente ilimitado, versionado y clases de almacenamiento con ciclo de vida."],cuandoB:["Cuando una instancia necesita un disco persistente (Amazon EBS) o el máximo rendimiento local efímero (instance store).","Cuando varias instancias deben compartir la misma jerarquía de archivos por red (Amazon EFS o Amazon FSx)."],escenarioA:"Una aplicación web sube imágenes de producto a un bucket y las sirve a los usuarios por API. Cada imagen se reemplaza entera cuando cambia y una política de ciclo de vida la mueve a una clase fría con el tiempo.",escenarioB:"El equipo de la base de datos asocia un volumen de Amazon EBS a su instancia para los datos persistentes y monta un sistema de archivos Amazon EFS compartido para los ficheros que procesan varios servidores Linux.",preguntaIds:["3.6-q2","3.6-q6"],objetivos:["3.6#1","3.6#2","3.6#4"]},{id:"s3-storage-classes",etiqueta:"Clases de almacenamiento de Amazon S3",a:{titulo:"Clases de acceso inmediato (S3 Standard, Intelligent-Tiering)",resumen:"Priorizan la disponibilidad y la latencia baja: el objeto se lee al instante. S3 Standard guarda datos calientes y de acceso impredecible; Intelligent-Tiering mueve automáticamente los objetos entre niveles de acceso según su uso. Tienen el coste de almacenamiento más alto."},b:{titulo:"Clases de acceso poco frecuente y de archivado (Standard-IA, One Zone-IA, familia S3 Glacier)",resumen:"Abaratan el almacenamiento a cambio de menor disponibilidad o de un tiempo de recuperación mayor, y algunas cobran por acceso. Standard-IA y One Zone-IA sirven datos fríos de acceso poco frecuente —One Zone-IA en una sola Availability Zone, con menor durabilidad— y la familia Glacier (Instant Retrieval, Flexible Retrieval y Deep Archive) cubre el archivado con recuperaciones de segundos a horas."},diferenciaClave:"Todas las clases guardan el mismo objeto; lo que cambia es el equilibrio entre coste de almacenamiento, latencia de acceso, disponibilidad, durabilidad y tiempo de recuperación. Las de acceso inmediato sirven datos vivos; las de acceso poco frecuente y archivado sirven datos que se consultan de forma excepcional, y Deep Archive es la de recuperación más lenta y menor coste.",cuandoA:["Cuando los objetos se consultan con frecuencia o el patrón de acceso es desconocido y no puedes asumir latencia.","Cuando necesitas respuesta inmediata para servir contenido a los usuarios."],cuandoB:["Cuando los objetos llevan tiempo sin consultarse y solo se necesitan para retención o cumplimiento.","Cuando el ahorro de almacenamiento compensa una recuperación más lenta y con coste por acceso."],escenarioA:"Un portal sirve las portadas y los documentos más vistos del día desde una clase de acceso inmediato, porque cada visita debe responder sin demora.",escenarioB:"Los registros y facturas de más de un año se conservan en una clase de archivado; solo se recuperan ante una auditoría y una política de ciclo de vida se encarga de moverlos.",preguntaIds:["3.6-q4"],objetivos:["3.6#2","3.6#3"]},{id:"efs-vs-fsx-vs-storage-gateway",etiqueta:"Sistemas de archivos gestionados frente a caché híbrida",a:{titulo:"Sistemas de archivos gestionados (Amazon EFS y Amazon FSx)",resumen:"Alojan el sistema de archivos en AWS y lo comparten por red entre instancias. Amazon EFS es elástico y para Linux; Amazon FSx cubre motores concretos, como Windows File Server o Lustre."},b:{titulo:"Puerta de enlace con caché (AWS Storage Gateway)",resumen:"Puente híbrido entre el entorno local y AWS. Mantiene en caché local los archivos de acceso reciente y sirve el resto bajo demanda desde el almacenamiento en la nube, para que las aplicaciones locales sigan trabajando con baja latencia."},diferenciaClave:"Amazon EFS y Amazon FSx son el destino del dato en AWS; AWS Storage Gateway es el intermediario que acerca ese dato a un entorno local mediante caché. El primero resuelve compartir archivos en la nube; el segundo, dar acceso local al dato que vive en la nube.",cuandoA:["Cuando las cargas corren en AWS y varias instancias deben compartir archivos con crecimiento automático o un motor específico.","Cuando quieres un sistema de archivos gestionado y elástico sin administrar servidores de archivos."],cuandoB:["Cuando las aplicaciones siguen en las instalaciones pero el dato debe residir en AWS.","Cuando necesitas baja latencia local para los archivos en uso sin replicar todo el conjunto de datos."],escenarioA:"Un clúster de instancias Linux monta un sistema de archivos Amazon EFS compartido y crece automáticamente; otra carga con Windows usa Amazon FSx para su sistema de archivos gestionado.",escenarioB:"Una oficina conserva su servidor de archivos local, pero los datos se respaldan en AWS a través de una puerta de enlace que mantiene en caché los documentos que se abren a diario.",preguntaIds:["3.6-q9"],objetivos:["3.6#5","3.6#6"]},{id:"lifecycle-vs-aws-backup",etiqueta:"Políticas de ciclo de vida vs AWS Backup",a:{titulo:"Políticas de ciclo de vida",resumen:"Reglas que mueven o eliminan objetos automáticamente según su antigüedad. En Amazon S3 transicionan el objeto entre clases de almacenamiento y lo expiran cuando deja de aportar. Optimizan el coste del dato vivo."},b:{titulo:"AWS Backup",resumen:"Servicio centralizado que define, programa y supervisa copias de seguridad de varios servicios, como volúmenes de Amazon EBS o sistemas de archivos Amazon EFS y Amazon FSx, con políticas y retención. Protege contra pérdida o corrupción."},diferenciaClave:"La política de ciclo de vida abarata el dato moviéndolo entre clases o expirándolo; AWS Backup crea copias recuperables con una retención definida. Una transición de clase no es una copia de seguridad y AWS Backup no sustituye a la gestión del ciclo de vida.",cuandoA:["Cuando el patrón de acceso de los objetos cambia con el tiempo y quieres abaratar el almacenamiento de forma automática.","Cuando necesitas expirar datos que ya no aportan valor sin operación manual."],cuandoB:["Cuando necesitas recuperarte de un borrado accidental o de una corrupción con copias y retención.","Cuando debes cumplir una retención de copias de seguridad sobre varios servicios a la vez."],escenarioA:"Una plataforma mueve las fotos antiguas a una clase más fría y las expira al año con una regla automática, sin copias adicionales.",escenarioB:"La misma plataforma crea copias semanales de sus volúmenes y sistemas de archivos, con una retención de un año por cumplimiento y un almacén de respaldo centralizado.",preguntaIds:["3.6-q13"],objetivos:["3.6#7","3.6#8"]}],3.7:[{id:"transcribe-vs-polly",etiqueta:"Amazon Transcribe y Amazon Polly: las dos direcciones entre voz y texto",a:{titulo:"Amazon Transcribe",resumen:"Convierte audio en texto (speech-to-text). Se usa para transcribir llamadas o reuniones y para generar subtítulos a partir de una grabación."},b:{titulo:"Amazon Polly",resumen:"Convierte texto en voz (text-to-speech). Se usa para generar locuciones y audio a partir de un texto escrito."},diferenciaClave:"La dirección del dato es opuesta: Amazon Transcribe recibe audio y devuelve texto; Amazon Polly recibe texto y devuelve audio.",cuandoA:["Cuando tienes grabaciones o audio en directo y necesitas el texto para buscar, subtitular o analizar.","Cuando quieres convertir conversaciones en texto para su revisión posterior."],cuandoB:["Cuando tienes un texto y necesitas una locución hablada para un producto o una atención automatizada.","Cuando quieres generar audio accesible a partir de contenido escrito."],escenarioA:"Un contact center quiere transcribir automáticamente sus llamadas grabadas para poder buscarlas y analizarlas después.",escenarioB:"Una aplicación quiere leer en voz alta las noticias del día al usuario a partir del texto publicado.",preguntaIds:["3.7-q2"],objetivos:["3.7#3"]},{id:"comprehend-vs-textract",etiqueta:"Amazon Comprehend y Amazon Textract: analizar texto frente a extraerlo de documentos",a:{titulo:"Amazon Comprehend",resumen:"Analiza lenguaje natural sobre texto ya digital: detecta sentimiento, entidades, temas e idioma."},b:{titulo:"Amazon Textract",resumen:"Extrae texto, formularios y tablas de documentos escaneados o imágenes, más allá de un reconocimiento óptico de caracteres básico."},diferenciaClave:"Amazon Comprehend interpreta texto que ya tienes; Amazon Textract obtiene el texto que está atrapado en una imagen o un documento escaneado.",cuandoA:["Cuando ya tienes texto digital y quieres entender su contenido, su tono o sus entidades.","Cuando necesitas clasificar o enrutar comentarios y correos según lo que expresan."],cuandoB:["Cuando los documentos llegan escaneados o como imágenes y necesitas sus datos en formato utilizable.","Cuando quieres extraer campos de formularios y tablas de forma automática."],escenarioA:"Una empresa analiza los comentarios de sus clientes en texto para detectar si la opinión es positiva o negativa.",escenarioB:"Un departamento digitaliza facturas en papel y necesita extraer automáticamente el número y el importe de cada una.",preguntaIds:["3.7-q3"],objetivos:["3.7#3"]},{id:"sagemaker-vs-servicios-ia",etiqueta:"Amazon SageMaker AI y los servicios de IA ya entrenados",a:{titulo:"Amazon SageMaker AI",resumen:"Plataforma gestionada para el ciclo completo del aprendizaje automático: preparar datos, entrenar, ajustar y desplegar modelos propios."},b:{titulo:"Servicios de IA ya entrenados",resumen:"APIs que resuelven una tarea concreta sin entrenar un modelo: Amazon Rekognition, Amazon Comprehend, Amazon Textract, Amazon Transcribe, Amazon Polly, Amazon Translate y Amazon Lex."},diferenciaClave:"Con Amazon SageMaker AI construyes el modelo con tus datos; con los servicios de IA ya entrenados consumes una tarea resuelta por API.",cuandoA:["Cuando el problema es específico del negocio y necesitas un modelo propio entrenado con tus datos.","Cuando quieres controlar el entrenamiento, la evaluación y el despliegue del modelo."],cuandoB:["Cuando la tarea es estándar (imágenes, texto, voz, traducción o conversación) y no quieres gestionar entrenamiento.","Cuando necesitas un resultado rápido sin equipo de ciencia de datos."],escenarioA:"Un equipo de datos entrena un modelo para predecir la rotación de clientes con los datos históricos de la empresa.",escenarioB:"Una aplicación agrega un buscador por palabras clave en imágenes etiquetando automáticamente su contenido sin entrenar nada.",preguntaIds:["3.7-q4"],objetivos:["3.7#1","3.7#3"]},{id:"athena-vs-glue-vs-kinesis",etiqueta:"Amazon Athena y AWS Glue frente a Amazon Kinesis",a:{titulo:"Amazon Athena y AWS Glue",resumen:"Amazon Athena consulta con SQL datos ya almacenados, por ejemplo en Amazon S3, sin administrar servidores. AWS Glue cataloga los datos y ejecuta trabajos de extracción, transformación y carga (ETL) para prepararlos."},b:{titulo:"Amazon Kinesis",resumen:"Ingiere y procesa datos en streaming, es decir, datos que llegan de forma continua y deben analizarse casi en tiempo real."},diferenciaClave:"Amazon Athena y AWS Glue trabajan sobre datos ya almacenados (consultar y preparar); Amazon Kinesis trabaja sobre datos en movimiento (ingerir y procesar en tiempo real).",cuandoA:["Cuando quieres consultar con SQL un histórico que ya está en Amazon S3 sin montar infraestructura.","Cuando necesitas transformar y catalogar datos antes de analizarlos."],cuandoB:["Cuando los datos llegan de forma continua y necesitas procesarlos con baja latencia, como telemetría o eventos.","Cuando quieres calcular métricas sobre un flujo en lugar de sobre un histórico."],escenarioA:"Una empresa analiza su histórico de ventas guardado en Amazon S3 con consultas SQL puntuales y prepara los datos con trabajos ETL.",escenarioB:"Una plataforma recibe miles de eventos por segundo y necesita calcular métricas en tiempo real sobre ese flujo continuo.",preguntaIds:["3.7-q8"],objetivos:["3.7#2","3.7#4"]}],3.8:[{id:"sns-vs-sqs-vs-eventbridge",etiqueta:"Colas, notificaciones y eventos: Amazon SQS, Amazon SNS y Amazon EventBridge",a:{titulo:"Entrega de mensajes: Amazon Simple Queue Service (Amazon SQS) y Amazon Simple Notification Service (Amazon SNS)",resumen:"Amazon SQS es una cola: el productor deposita el mensaje y un consumidor lo retira para procesarlo, lo que desacopla ambos lados y permite acumular trabajo y reintentar. Amazon SNS es publicación/suscripción: el mismo mensaje se difunde a muchos suscriptores al instante, el patrón de alertas y notificaciones."},b:{titulo:"Enrutado de eventos: Amazon EventBridge",resumen:"Bus de eventos que reacciona a eventos del sistema o de las aplicaciones y los enruta a destinos según reglas. El emisor no necesita conocer al receptor y se pueden filtrar y transformar los eventos antes de entregarlos."},diferenciaClave:"Amazon SQS entrega trabajo a un consumidor mediante una cola; Amazon SNS difunde alertas y notificaciones a muchos suscriptores a la vez; Amazon EventBridge reacciona a eventos y los enruta según reglas. Cola, pub/sub y bus de eventos resuelven necesidades distintas.",cuandoA:["Usa Amazon SQS para desacoplar componentes y encolar trabajo que se procesará a su ritmo, sin perder mensajes.","Usa Amazon SNS para enviar alertas y notificaciones inmediatas a varios destinatarios a la vez."],cuandoB:["Usa Amazon EventBridge cuando debas reaccionar a eventos de servicios o aplicaciones y enrutarlos según reglas.","Usa Amazon EventBridge cuando el emisor no deba conocer al receptor y necesites filtrar eventos por su contenido."],escenarioA:"Una tienda publica cada cambio de pedido en un topic de Amazon SNS para avisar por correo y SMS a varios suscriptores y, a la vez, deja el análisis pesado en una cola de Amazon SQS que el analizador consume cuando puede.",escenarioB:"La misma tienda define reglas en Amazon EventBridge para que un pedido cancelado dispare automáticamente la devolución del stock y la notificación al equipo de logística, sin que el sistema de pedidos conozca a esos receptores.",preguntaIds:["3.8-q2"],objetivos:["3.8#1","3.8#8"]},{id:"appstream-vs-workspaces",etiqueta:"Amazon AppStream 2.0 frente a Amazon WorkSpaces",a:{titulo:"Amazon AppStream 2.0",resumen:"Entrega aplicaciones concretas por streaming. La aplicación se ejecuta en AWS y el usuario la usa desde su navegador o cliente sin instalarla ni recibir el sistema operativo del servidor."},b:{titulo:"Amazon WorkSpaces",resumen:"Entrega un escritorio virtual completo y persistente por usuario, con su sistema operativo y sus aplicaciones, accesible desde distintos dispositivos. Amazon WorkSpaces Secure Browser es la variante de navegador aislado."},diferenciaClave:"Amazon AppStream 2.0 publica una aplicación individual; Amazon WorkSpaces publica un puesto de trabajo completo. Se elige según lo que deba presentarse en el equipo del usuario final: una app suelta o un escritorio entero.",cuandoA:["Usa Amazon AppStream 2.0 cuando unos pocos usuarios necesiten una aplicación concreta sin instalarla en sus equipos.","Usa Amazon AppStream 2.0 para dar acceso temporal a software especializado a contratistas con equipos modestos."],cuandoB:["Usa Amazon WorkSpaces cuando cada usuario necesite un escritorio corporativo completo y persistente.","Usa Amazon WorkSpaces para reemplazar puestos de trabajo tradicionales manteniendo el sistema operativo y las aplicaciones de cada persona."],escenarioA:"Una agencia publica su programa de diseño por Amazon AppStream 2.0 para que colaboradores externos lo usen desde un navegador, sin instalarlo en sus ordenadores personales.",escenarioB:"Un banco entrega a cada empleado un escritorio virtual de Amazon WorkSpaces al que accede desde cualquier dispositivo corporativo o personal, conservando su configuración entre sesiones.",preguntaIds:["3.8-q13"],objetivos:["3.8#5","3.8#12"]},{id:"codebuild-vs-codepipeline",etiqueta:"AWS CodeBuild frente a AWS CodePipeline",a:{titulo:"AWS CodeBuild",resumen:"Servicio de compilación. Ejecuta el build y las pruebas, y produce el artefacto desplegable, sin administrar servidores de compilación. Es una etapa que hace el trabajo."},b:{titulo:"AWS CodePipeline",resumen:"Servicio de orquestación de la canalización. Modela y coordina las etapas de extremo a extremo —origen, compilación, pruebas y despliegue— y decide el orden del flujo."},diferenciaClave:"AWS CodeBuild construye y prueba; AWS CodePipeline coordina las etapas y el orden de la canalización. Uno ejecuta la construcción y el otro dirige el proceso completo.",cuandoA:["Usa AWS CodeBuild cuando necesites compilar código y ejecutar pruebas para generar un artefacto.","Usa AWS CodeBuild para construir y probar de forma gestionada, sin servidores de compilación propios."],cuandoB:["Usa AWS CodePipeline cuando necesites automatizar la entrega completa desde el repositorio hasta el despliegue.","Usa AWS CodePipeline para coordinar varias etapas y herramientas dentro de un mismo flujo, incluyendo la compilación con AWS CodeBuild."],escenarioA:"Cada vez que un desarrollador sube código, una etapa de AWS CodeBuild compila el proyecto y ejecuta las pruebas unitarias, y deja el artefacto listo para desplegar.",escenarioB:"La canalización de AWS CodePipeline toma el código del repositorio, invoca a AWS CodeBuild, ejecuta las pruebas de integración y despliega en producción, deteniéndose si una etapa falla.",preguntaIds:["3.8-q10"],objetivos:["3.8#4","3.8#11"]},{id:"connect-vs-ses",etiqueta:"Amazon Connect vs Amazon Simple Email Service (Amazon SES)",a:{titulo:"Amazon Connect",resumen:"Centro de contacto omnicanal en la nube: enruta llamadas, chat y tareas a los agentes, incorpora IVR, grabación y analíticas y se paga por uso sin mantener centralitas propias. Es el canal de voz y chat."},b:{titulo:"Amazon Simple Email Service (Amazon SES)",resumen:"Servicio de envío y recepción de correo electrónico a escala, pensado para correo transaccional y de marketing con alta entregabilidad, sin administrar servidores de correo. Es el canal de email."},diferenciaClave:"Amazon Connect atiende a los clientes por voz y chat con agentes y enrutamiento; Amazon SES envía y recibe correo electrónico a escala. La elección se hace por el canal que hay que cubrir.",cuandoA:["Cuando necesitas atención al cliente con enrutamiento de llamadas, IVR y agentes distribuidos.","Cuando quieres atender voz y chat sin infraestructura telefónica propia."],cuandoB:["Cuando una aplicación debe enviar correos transaccionales o de marketing de forma masiva y fiable.","Cuando buscas alta entregabilidad y reputación gestionada sin operar servidores de correo."],escenarioA:"Una empresa monta un centro de contacto con IVR y agentes que trabajan desde casa para atender las llamadas y el chat de sus clientes.",escenarioB:"La misma empresa envía a sus clientes los recibos y las confirmaciones de compra por correo electrónico de forma masiva.",preguntaIds:["3.8-q19"],objetivos:["3.8#2","3.8#9"]},{id:"soporte-empresarial-vs-planes-menores",etiqueta:"AWS Enterprise Support vs planes de soporte menores",a:{titulo:"AWS Enterprise Support",resumen:"Nivel más alto de asistencia: cobertura para cargas críticas, tiempos de respuesta mínimos, Technical Account Manager (TAM) designado y revisión proactiva de la arquitectura."},b:{titulo:"AWS Business Support y AWS Developer Support",resumen:"AWS Business Support cubre producción 24/7 con AWS Trusted Advisor completo pero sin TAM; AWS Developer Support se orienta a desarrollo y pruebas con soporte por correo en horario laboral. El plan Basic no incluye soporte técnico de producción."},diferenciaClave:"La cobertura, los tiempos de respuesta y el Technical Account Manager distinguen los planes. Enterprise atiende cargas críticas con TAM; Business cubre producción sin TAM y Developer se limita a desarrollo y pruebas.",cuandoA:["Cuando ejecutas cargas críticas que no pueden interrumpirse y necesitas el menor tiempo de respuesta y un interlocutor dedicado.","Cuando quieres revisión proactiva de la arquitectura y un Technical Account Manager que conozca tu entorno."],cuandoB:["Cuando tienes producción que requiere cobertura 24/7 pero no un Technical Account Manager.","Cuando solo necesitas soporte para desarrollo y pruebas en horario laboral."],escenarioA:"Una plataforma de ventas con tráfico continuo contrata AWS Enterprise Support y trabaja con un Technical Account Manager en la revisión de su arquitectura.",escenarioB:"Una startup en fase de desarrollo usa AWS Developer Support para resolver dudas por correo mientras prepara su primer producto.",preguntaIds:["3.8-q20"],objetivos:["3.8#3","3.8#10"]},{id:"amplify-vs-codepipeline",etiqueta:"AWS Amplify vs AWS CodePipeline",a:{titulo:"AWS Amplify",resumen:"Frontend web y móvil: permite crear la interfaz, integrar capacidades como autenticación o APIs y publicar la aplicación con hosting y entrega continua en un flujo guiado."},b:{titulo:"AWS CodePipeline",resumen:"Orquestación genérica de canalizaciones: modela y coordina las etapas de origen, compilación, pruebas y despliegue de cualquier aplicación, encadenando las herramientas implicadas."},diferenciaClave:"AWS Amplify está especializado en crear y desplegar frontend web y móvil con capacidades integradas; AWS CodePipeline coordina las etapas de una canalización de entrega de propósito general. Una publicación de frontend no es lo mismo que una orquestación de CI/CD.",cuandoA:["Cuando quieres lanzar una aplicación web o móvil con autenticación, APIs y hosting sin cablear cada servicio por separado.","Cuando el equipo se centra en el frontend y busca un flujo guiado de despliegue."],cuandoB:["Cuando necesitas automatizar la entrega completa desde el repositorio hasta el despliegue.","Cuando hay que coordinar varias etapas y herramientas dentro de un mismo flujo de CI/CD."],escenarioA:"Una startup publica su aplicación móvil con registro de usuarios y su web de marketing desde el repositorio, con la autenticación y el hosting ya integrados.",escenarioB:"Un equipo encadena origen, compilación, pruebas y despliegue en una canalización que se detiene si una etapa falla.",preguntaIds:["3.8-q21"],objetivos:["3.8#6","3.8#13"]},{id:"iot-core-vs-sqs",etiqueta:"AWS IoT Core vs Amazon Simple Queue Service (Amazon SQS)",a:{titulo:"AWS IoT Core",resumen:"Servicio gestionado que conecta dispositivos IoT con la nube: registra la identidad de cada dispositivo, autentica su conexión, recibe sus mensajes por protocolos ligeros y los enruta a otros servicios con reglas."},b:{titulo:"Amazon Simple Queue Service (Amazon SQS)",resumen:"Cola de mensajes para aplicaciones: el productor deposita el mensaje y un consumidor lo retira para procesarlo, desacoplando ambos lados y permitiendo acumular trabajo y reintentar."},diferenciaClave:"AWS IoT Core gestiona la identidad, la conexión y los mensajes de una flota de dispositivos; Amazon SQS desacopla el procesamiento de mensajes entre componentes de aplicación. Una cola no administra dispositivos.",cuandoA:["Cuando tienes que registrar, autenticar y administrar miles de dispositivos IoT y recibir sus lecturas.","Cuando las lecturas de los dispositivos deben enrutarse a otros servicios mediante reglas."],cuandoB:["Cuando quieres desacoplar productor y consumidor y acumular trabajo para procesarlo a su ritmo.","Cuando necesitas reintentar el procesamiento sin perder mensajes."],escenarioA:"Una fábrica registra cada sensor, autentica su conexión segura y recibe sus lecturas para enrutarlas a un proceso de análisis.",escenarioB:"El proceso de análisis recibe las lecturas en una cola y las consume a su propio ritmo, sin bloquear a los dispositivos.",preguntaIds:["3.8-q22"],objetivos:["3.8#7","3.8#14"]}],4.1:[{id:"savings-plans-vs-ri-vs-spot",etiqueta:"Savings Plans y Reserved Instances frente a Spot Instances",a:{titulo:"AWS Savings Plans y Reserved Instances",resumen:"Ambos son compromisos de 1 o 3 años que intercambian flexibilidad por descuento. Las Reserved Instances se anclan a atributos de instancia, con Standard (sin cambios) y Convertible (con intercambio) como variantes. Los Savings Plans comprometen un gasto por hora, y los Compute Savings Plans cubren Amazon EC2, AWS Fargate y AWS Lambda en cualquier familia, sistema operativo y región."},b:{titulo:"Spot Instances",resumen:"No hay compromiso de plazo: se usan instancias de capacidad sobrante con el mayor descuento, pero pueden reclamarse con dos minutos de aviso. Solo encajan en cargas tolerantes a interrupciones."},diferenciaClave:"Savings Plans y Reserved Instances compran previsibilidad con un compromiso de plazo; Spot compra precio a cambio de tolerar la interrupción. El riesgo que asumes es distinto: compromiso de gasto frente a pérdida de la instancia.",cuandoA:["Cuando la carga es estable y se mantiene durante uno o más años y quieres reducir la factura sin asumir interrupciones.","Cuando necesitas cubrir cómputo de varios servicios con un solo compromiso de gasto y buscas flexibilidad de familia y región."],cuandoB:["Cuando el trabajo tolera la interrupción y puede reintentarse, como procesamiento por lotes, renderizado o tareas stateless.","Cuando quieres el mayor descuento posible sobre capacidad sobrante y el momento exacto de ejecución es flexible."],escenarioA:"Una plataforma con uso estable contrata un Compute Savings Plan de un año que cubre sus instancias, sus tareas de contenedores administrados y sus funciones serverless, reduciendo la factura sin riesgo de interrupción.",escenarioB:"Un estudio de animación lanza renderizados nocturnos en Spot Instances; si la capacidad se reclama, el trabajo se reintenta en la siguiente franja sin afectar al servicio.",preguntaIds:["4.1-q2"],objetivos:["4.1#1","4.1#3"]},{id:"on-demand-vs-dedicated-vs-capacity",etiqueta:"On-Demand Instances frente a Dedicated Hosts, Dedicated Instances y Capacity Reservations",a:{titulo:"On-Demand Instances",resumen:"Capacidad facturada por uso, sin compromiso y sin reserva. Da la máxima flexibilidad y el precio de referencia, pero no garantiza que la capacidad esté disponible ni ofrece aislamiento físico."},b:{titulo:"Dedicated Hosts, Dedicated Instances y Capacity Reservations",resumen:"Opciones para requisitos concretos. Dedicated Hosts entregan un servidor físico completo con control de sockets y núcleos (BYOL); Dedicated Instances corren en hardware dedicado a un único cliente; Capacity Reservations aseguran capacidad en una Availability Zone concreta sin compromiso de plazo."},diferenciaClave:"On-Demand resuelve el pago por uso; Dedicated Hosts e Instances resuelven aislamiento físico y licencias, y Capacity Reservations resuelve la garantía de capacidad en una AZ concreta. Se pueden combinar: una Capacity Reservation conserva la capacidad y un Savings Plan o una RI aplica el descuento sobre ella.",cuandoA:["Cuando la carga es imprevisible o de corta duración y no necesitas garantizar capacidad ni aislamiento físico.","Cuando quieres evitar cualquier compromiso de plazo o pago por adelantado."],cuandoB:["Cuando necesitas traer tus propias licencias o cumplir requisitos de aislamiento físico en hardware dedicado.","Cuando debes garantizar que habrá capacidad en una Availability Zone concreta para un lanzamiento o un pico planificado."],escenarioA:"Un equipo de desarrollo levanta y destruye entornos de prueba varias veces al día y paga solo por las horas en que las instancias están encendidas.",escenarioB:"Una empresa con licencias de software basadas en sockets usa Dedicated Hosts para cumplir el contrato y reserva capacidad en una Availability Zone concreta para el lanzamiento de un producto.",preguntaIds:["4.1-q3"],objetivos:["4.1#1","4.1#3"]},{id:"clases-de-objetos-vs-bloques-y-archivos",etiqueta:"Clases de almacenamiento de objetos frente a bloques y archivos",a:{titulo:"Clases y niveles del almacenamiento de objetos",resumen:"Dentro del almacenamiento de objetos, las clases ordenan el precio por frecuencia de acceso y latencia de recuperación: la clase de acceso frecuente es la más cara por GB, las de acceso poco frecuente abaratan el almacenamiento con cargo por recuperación y las de archivo lo minimizan con recuperación lenta."},b:{titulo:"Almacenamiento de bloques y de archivos",resumen:"No son niveles de un mismo servicio. El almacenamiento de bloques se paga por capacidad aprovisionada aunque no se monte, y el de archivos compartidos se paga por datos almacenados. Cada tipo atiende un acceso distinto: volumen de una instancia frente a sistema de archivos compartido."},diferenciaClave:"Las clases de objetos son niveles de precio dentro de un mismo servicio de objetos; los bloques y los archivos son otros tipos de almacenamiento con su propio modelo de cobro. No se eligen como niveles entre sí, sino por la forma de acceso que necesita la carga.",cuandoA:["Cuando el dato se accede como objeto y quieres ajustar el precio según la frecuencia de lectura.","Cuando necesitas retención prolongada de objetos con una política de ciclo de vida que baje de nivel de forma automática."],cuandoB:["Cuando una instancia necesita un volumen de bloques o cuando varios recursos deben compartir un sistema de archivos.","Cuando el acceso no es por objeto sino por lectura y escritura a nivel de bloque o por montaje de un sistema de archivos."],escenarioA:"Una empresa conserva documentos que casi no se leen y los mueve con una política de ciclo de vida desde la clase de acceso frecuente a una clase de archivo, reduciendo el precio por GB almacenado.",escenarioB:"Un servidor de base de datos monta un volumen de bloques para sus datos y un clúster de análisis comparte un sistema de archivos para sus nodos de proceso.",preguntaIds:["4.1-q15"],objetivos:["4.1#2","4.1#7"]},{id:"comparticion-de-descuento-activada-vs-desactivada",etiqueta:"Descuento por compromiso compartido por defecto frente a compartición desactivada",a:{titulo:"Compartición activada (por defecto)",resumen:"En una organización, las RI y los Savings Plans se comparten por defecto: primero cubren el uso de la cuenta que los compró y el descuento sobrante se aplica al uso elegible de las demás cuentas, reduciendo la factura consolidada."},b:{titulo:"Compartición desactivada",resumen:"La cuenta de administración puede desactivar la compartición, cuenta por cuenta, en las preferencias de facturación. A partir de ahí, el descuento queda limitado a la cuenta que lo compró y el sobrante no beneficia a las demás."},diferenciaClave:"No es una diferencia de producto sino de preferencia de la organización: activada, el descuento se reparte entre cuentas; desactivada, se retiene en la cuenta compradora. El comportamiento por defecto es la compartición.",cuandoA:["Cuando varias cuentas comparten una organización y quieres que el descuento no usado en una reduzca la factura de las demás.","Cuando buscas maximizar el aprovechamiento del compromiso sobre el uso agregado."],cuandoB:["Cuando necesitas que cada cuenta cargue su propio consumo sin que el descuento de otra la beneficie.","Cuando las cuentas se facturan a unidades distintas y quieres el descuento encerrado en la cuenta compradora."],escenarioA:"La cuenta de producción de un grupo compra un compromiso de cómputo que no consume entero; el descuento sobrante baja la factura de la cuenta de desarrollo, que pagaba todo a precio de referencia.",escenarioB:"Una empresa desactiva la compartición porque cada filial tiene presupuesto propio y quiere que el descuento solo reduzca el gasto de la cuenta que lo contrató.",preguntaIds:["4.1-q16"],objetivos:["4.1#5"]},{id:"transferencia-entrante-vs-saliente-y-cruce",etiqueta:"Transferencia entrante frente a saliente y cruce entre Availability Zones o regiones",a:{titulo:"Transferencia entrante (incoming)",resumen:"La entrada de datos desde internet hacia AWS suele ser gratuita. Recibir datos en la nube no genera un cargo por GB de los que sí aparecen al sacarlos o al cruzar fronteras internas."},b:{titulo:"Transferencia saliente y cruce entre AZ o regiones",resumen:"Sacar datos hacia internet se factura por GB con tramos decrecientes, y el tráfico que cruza entre Availability Zones o entre regiones también se cobra por GB en los extremos. El tráfico dentro de la misma AZ con direcciones privadas no genera ese cargo."},diferenciaClave:"Entrar a AWS suele ser gratis; salir y cruzar entre zonas o regiones se paga. Por eso el diseño de red importa: concentrar el tráfico intenso en la misma AZ o usar un endpoint privado reduce la factura sin eliminar la transferencia.",cuandoA:["Cuando ingieres datos hacia AWS de forma masiva y quieres saber que esa dirección no genera cargo de transferencia.","Cuando planificas la carga inicial de datos y el coste relevante es el almacenamiento, no la entrada."],cuandoB:["Cuando sirves contenido o resultados hacia internet y necesitas presupuestar la salida por GB.","Cuando el tráfico interno cruza Availability Zones o regiones y quieres evaluar si conviene reagruparlo en una sola zona."],escenarioA:"Una empresa sube cada noche millones de registros desde su centro de datos hacia AWS y comprueba que esa entrada no genera un cargo por GB de transferencia.",escenarioB:"Dos componentes en Availability Zones distintas intercambian grandes volúmenes de datos y el equipo compara el coste de cruce con el de concentrarlos en una misma zona.",preguntaIds:["4.1-q17"],objetivos:["4.1#6"]}],4.2:[{id:"budgets-vs-cost-explorer-vs-pricing-calculator",etiqueta:"AWS Budgets y AWS Cost Explorer vs AWS Pricing Calculator",a:{titulo:"AWS Budgets y AWS Cost Explorer",resumen:"Herramientas que trabajan sobre el gasto ya comprometido: AWS Cost Explorer analiza el costo y el uso registrados agrupando y filtrando por servicio, cuenta o etiqueta, y AWS Budgets define un límite y alerta cuando el gasto real o previsto se acerca o supera el umbral."},b:{titulo:"AWS Pricing Calculator",resumen:"Calculadora de estimación previa al despliegue: permite modelar una arquitectura, ajustar cantidades y obtener un costo mensual estimado sin crear recursos."},diferenciaClave:"AWS Cost Explorer y AWS Budgets trabajan sobre datos de gasto reales ya generados (analizar y vigilar); AWS Pricing Calculator trabaja sobre una arquitectura hipotética antes de que exista gasto (estimar).",cuandoA:["Cuando quieras entender el gasto histórico o del mes en curso y desglosarlo por servicio, cuenta o etiqueta.","Cuando necesites definir un límite y recibir alertas al acercarse o superar el presupuesto."],cuandoB:["Cuando quieras estimar el costo mensual de una arquitectura antes de crearla.","Cuando compares alternativas de diseño o tamaños para decidir con una cifra aproximada."],escenarioA:"El equipo de finanzas revisa con AWS Cost Explorer el gasto del mes por servicio y define en AWS Budgets una alerta para avisar si el entorno de pruebas supera su límite.",escenarioB:"Antes de solicitar presupuesto, el arquitecto modela la nueva aplicación en AWS Pricing Calculator y obtiene una estimación mensual para comparar dos opciones de tamaño.",preguntaIds:["4.2-q5","4.2-q8"],objetivos:["4.2#5","4.2#6"]},{id:"organizacion-centralizada-vs-cuentas-independientes",etiqueta:"Organización con administración central frente a cuentas independientes",a:{titulo:"Cuentas agrupadas en una organización",resumen:"Las cuentas miembro se administran como una sola unidad de gobierno: la cuenta de gestión aplica políticas, incorpora cuentas y recibe la factura consolidada con el uso agregado de todas ellas."},b:{titulo:"Cuentas independientes",resumen:"Cada cuenta se gobierna y se factura por separado. Gana aislamiento entre equipos o negocios, pero se pierde la factura única y la posibilidad de alcanzar antes los descuentos por volumen con el uso agregado."},diferenciaClave:"Agrupar cuentas centraliza el gobierno y consolida la factura; mantenerlas independientes conserva la separación total de gestión y pago. En ambos casos la atribución del gasto por equipo o proyecto se logra con etiquetas, no con la mera separación de cuentas.",cuandoA:["Cuando necesitas gobierno central, políticas comunes y una sola factura para todas las cuentas.","Cuando el uso agregado de varias cuentas conviene para alcanzar antes los descuentos por volumen."],cuandoB:["Cuando cada equipo o negocio debe gobernar y pagar sus cuentas de forma totalmente independiente.","Cuando el aislamiento entre unidades pesa más que el beneficio de una factura consolidada."],escenarioA:"Un grupo con varias filiales agrupa sus cuentas, aplica políticas desde un punto central y recibe una sola factura, atribuyendo el gasto por filial con etiquetas.",escenarioB:"Dos empresas del mismo grupo mantienen cuentas separadas por requisitos regulatorios y cada una se factura y se gobierna sin compartir administración.",preguntaIds:["4.2-q13"],objetivos:["4.2#3","4.2#7"]},{id:"etiquetas-de-asignacion-vs-informe-de-costos-y-uso",etiqueta:"Etiquetas de asignación de costos frente al informe de costos y uso",a:{titulo:"Etiquetas de asignación de costos",resumen:"Pares clave-valor que se aplican a los recursos y que hay que activar para asignación de costos. Aportan el criterio de negocio, como equipo, proyecto o entorno, con el que se puede agrupar y filtrar el gasto."},b:{titulo:"Informe de costos y uso",resumen:"Es el informe más detallado de facturación: incluye cada línea de uso con las etiquetas que se hayan activado. Aporta el detalle granular sobre el que se cruza el gasto con los criterios de negocio."},diferenciaClave:"La etiqueta es el criterio y el informe es el detalle. La etiqueta debe activarse para aparecer en la facturación; el informe recoge esa etiqueta en cada línea de uso. Ninguno de los dos fija límites ni sustituye al otro.",cuandoA:["Cuando necesitas definir el criterio de negocio con el que atribuirás el gasto antes de analizarlo.","Cuando quieres agrupar o filtrar el gasto por equipo, proyecto o entorno en las herramientas de costos."],cuandoB:["Cuando necesitas el detalle línea a línea de la facturación con las etiquetas ya activadas.","Cuando vas a cruzar el uso de cada recurso con el proyecto o el centro de costo al que pertenece."],escenarioA:"Una empresa define las claves equipo y proyecto, las aplica a sus recursos y las activa como etiquetas de asignación de costos para poder agrupar el gasto.",escenarioB:"El equipo de finanzas descarga el informe de costos y uso y encuentra en cada línea el valor de las etiquetas activadas, atribuyendo el gasto por proyecto.",preguntaIds:["4.2-q15"],objetivos:["4.2#4","4.2#8"]}],4.3:[{id:"planes-de-soporte-aws",etiqueta:"Planes de soporte de entrada vs planes para producción",a:{titulo:"Basic Support y AWS Developer Support",resumen:"Niveles de entrada. Basic viene incluido en toda cuenta y no abre casos técnicos; AWS Developer Support añade asistencia técnica por correo en horario laboral y un contacto designado. Están pensados para aprendizaje, desarrollo y pruebas."},b:{titulo:"AWS Business Support, AWS Enterprise On-Ramp Support y AWS Enterprise Support",resumen:"Niveles para producción. AWS Business Support da atención 24/7 por teléfono, chat y correo con todas las comprobaciones de AWS Trusted Advisor; AWS Enterprise On-Ramp Support añade guía proactiva y acceso a un grupo de TAM; AWS Enterprise Support ofrece TAM designado y los tiempos de respuesta más cortos."},diferenciaClave:"La frontera está en si la carga es de producción y qué compromiso se necesita: los planes de entrada se limitan al horario laboral y a canales limitados, mientras que AWS Business Support y los niveles Enterprise ofrecen atención 24/7, comprobaciones completas y, en Enterprise, un TAM y guía proactiva.",cuandoA:["Cuando el uso es de desarrollo o pruebas y basta con documentación, comunidad y asistencia técnica por correo en horario laboral.","Cuando se quiere empezar sin coste adicional de soporte y solo se necesitan consultas de facturación y cuenta."],cuandoB:["Cuando hay cargas en producción que exigen atención 24/7, tiempos de respuesta comprometidos y comprobaciones completas de AWS Trusted Advisor.","Cuando la organización necesita un TAM, revisión proactiva de la arquitectura y el menor tiempo de respuesta para sistemas críticos."],escenarioA:"Un equipo de desarrollo abre un entorno de pruebas, resuelve dudas de configuración y no necesita atención fuera del horario laboral: le basta con Basic Support o con AWS Developer Support.",escenarioB:"Una empresa opera una plataforma de ventas 24/7 y quiere abrir casos por teléfono a cualquier hora con respuesta en menos de una hora: contrata AWS Business Support, y si además necesita un TAM designado, AWS Enterprise Support.",preguntaIds:["4.3-q4"],objetivos:["4.3#2","4.3#7"]},{id:"documentacion-oficial-vs-comunidad-y-guias",etiqueta:"Documentación oficial frente a comunidad y guías de implementación",a:{titulo:"Documentación del servicio",resumen:"Referencia autoritativa de cada servicio: describe la API, los límites, los parámetros y los permisos. Es el punto de consulta para confirmar el comportamiento exacto antes de implementar."},b:{titulo:"Guías de implementación y comunidad",resumen:"Las guías de implementación y AWS Prescriptive Guidance aportan estrategias y patrones; el centro de conocimiento resuelve dudas puntuales y la comunidad comparte experiencia. Ayudan a decidir y a desbloquear, pero no son la fuente autoritativa del comportamiento exacto."},diferenciaClave:"La documentación fija el comportamiento exacto de forma autoritativa; las guías y la comunidad ayudan a aplicar y a resolver dudas, pero deben contrastarse con la documentación vigente. La elección depende de si la pregunta es «cómo funciona exactamente» o «cómo lo hago».",cuandoA:["Cuando necesitas confirmar el comportamiento exacto, los límites o los permisos de un servicio.","Cuando una decisión técnica exige la referencia oficial y vigente del servicio."],cuandoB:["Cuando buscas un patrón de migración o una estrategia de implementación recomendada.","Cuando tienes una duda puntual y quieres pasos de solución o la experiencia de otros clientes."],escenarioA:"Un ingeniero confirma en la documentación oficial los límites y permisos exactos de una acción antes de implementarla.",escenarioB:"El mismo equipo consulta una guía de implementación para el patrón de migración y la comunidad para una duda puntual de configuración.",preguntaIds:["4.3-q15"],objetivos:["4.3#1","4.3#5","4.3#6"]},{id:"trusted-advisor-vs-health-dashboard-y-api",etiqueta:"Trusted Advisor frente al AWS Health Dashboard y la AWS Health API",a:{titulo:"AWS Trusted Advisor",resumen:"Revisa la configuración del entorno y emite recomendaciones en cinco categorías: optimización de costos, seguridad, tolerancia a fallos, rendimiento y cuotas de servicio. Solo recomienda: el cliente decide y aplica los cambios."},b:{titulo:"AWS Health Dashboard y AWS Health API",resumen:"El Health Dashboard da una vista personalizada del estado de los servicios de AWS y de los eventos que afectan a los recursos de la cuenta. La Health API expone esa información para automatizar alertas y flujos de trabajo."},diferenciaClave:"Trusted Advisor recomienda sobre la configuración y las buenas prácticas; el Health Dashboard y la Health API informan de los eventos de AWS que afectan a la cuenta. Ninguno aplica cambios por sí solo.",cuandoA:["Cuando buscas recomendaciones concretas para optimizar costos, seguridad o tolerancia a fallos.","Cuando quieres una revisión periódica del entorno con acciones sugeridas."],cuandoB:["Cuando necesitas saber si un servicio de AWS está degradado y cómo afecta a tus recursos.","Cuando quieres consumir por programación la información de salud y automatizar la reacción."],escenarioA:"Un equipo de finanzas recibe de Trusted Advisor recomendaciones para detectar instancias infrautilizadas y reducir el gasto sin rehacer la arquitectura.",escenarioB:"El mismo equipo consulta el Health Dashboard para ver los eventos que afectan a su región y automatiza alertas con la Health API.",preguntaIds:["4.3-q16"],objetivos:["4.3#8"]},{id:"partners-y-marketplace-vs-canales-de-soporte",etiqueta:"Programa de partners y catálogo frente a canales de soporte y denuncia",a:{titulo:"AWS Partner Network y AWS Marketplace",resumen:"El AWS Partner Network agrupa a consulting partners (system integrators) y technology partners (independent software vendors), con beneficios como formación, eventos y descuentos por volumen. AWS Marketplace es el catálogo donde se descubren y compran esas soluciones, con facturación consolidada, gobernanza y derechos de uso."},b:{titulo:"AWS Support Center y Trust and Safety",resumen:"El AWS Support Center es el canal para crear y gestionar los casos de soporte de la cuenta, y el equipo de AWS Trust and Safety recibe las denuncias de uso abusivo de recursos, como spam, phishing o contenido ilícito."},diferenciaClave:"El programa de partners y su catálogo cubren la parte comercial y de implementación; el centro de soporte atiende incidentes de la cuenta y el equipo de confianza gestiona denuncias de abuso. Son canales distintos y no intercambiables.",cuandoA:["Cuando necesitas experiencia externa para migrar u operar, o comprar software de un fabricante con facturación consolidada.","Cuando quieres conocer los programas, la formación y los descuentos disponibles para partners."],cuandoB:["Cuando necesitas que AWS investigue un incidente sobre un recurso de tu cuenta.","Cuando quieres denunciar el uso abusivo de recursos de AWS."],escenarioA:"Una empresa contrata a un system integrator para migrar su sistema heredado y compra un software de seguridad a un ISV a través del catálogo, con el pago unificado.",escenarioB:"La misma empresa abre un caso para investigar una caída y comunica al equipo de confianza que una de sus instancias envía correo no deseado.",preguntaIds:["4.3-q17"],objetivos:["4.3#3","4.3#9","4.3#10","4.3#11","4.3#12"]}]},t=e("i",Object.values(s).flat());for(const e of[...a,...n])i[e.taskId]?i[e.taskId].push(e):i[e.taskId]=[e];const d=e("a",Object.values(i).flat()),l=e("b",Object.values(r).flat()),u=e("c",Object.values(c).flat()),p=e("T",Array.from(new Set([...Object.keys(s),...Object.keys(i),...Object.keys(r),...Object.keys(c)])).sort());e("d",o.filter(e=>!p.includes(e.id)).map(e=>e.id)),e("j",[]),e("O",[]),Object.fromEntries(t.map(e=>[e.id,e])),Object.fromEntries(d.map(e=>[e.id,e])),Object.fromEntries(l.map(e=>[e.id,e])),e("M",Object.fromEntries(u.map(e=>[e.id,e])));const m={};function g(e,a,o){const n=m[e]??(m[e]={grupos:[],preguntas:[],tarjetas:[],pares:[]});n[a].includes(o)||n[a].push(o)}for(const e of t)for(const a of e.objetivos)g(a,"grupos",e.id);for(const e of d)for(const a of e.objetivos)g(a,"preguntas",e.id);for(const e of l)for(const a of e.objetivos)g(a,"tarjetas",e.id);for(const e of u)for(const a of e.objetivos)g(a,"pares",e.id)}}});
